local config = {
  ui_story_1_1_Z1_dialog_content = "♪Salju putih… cakrawala…♪",
  ui_story_1_1_Z2_dialog_content = "♪… Angin…♪",
  ui_story_1_1_Z3_dialog_content = "♪Dandelion…♪",
  ui_story_1_1_Z4_dialog_content = "♪… Musim semi♪",
  ui_story_1_1_Z5_dialog_content = "♪Lembah… hampa♪",
  ui_story_1_1_Z6_dialog_content = "♪… Negeri… kita♪",
  ui_story_1_1_Z7_dialog_content = "\"Lagi-lagi\"",
  ui_story_1_1_Z8_dialog_content = "\"Putus asa\"",
  ui_story_1_1_Z9_dialog_content = "\"Melawan.\"",
  ui_story_1_1_Z10_dialog_content = "\"Hidup…\"",
  ui_story_1_1_Z11_dialog_content = "Kau akan terus hidup…",
  ui_story_1_1_Z12_dialog_content = "\"Aku… masih hidup.\"",
  ui_story_1_1_1_dialog_content = "<color=#e8d9bb>\"Kontrol Utama… normal\"</color>",
  ui_story_1_1_2_dialog_content = "<color=#e8d9bb>\"Modul biologis… sedang hibernasi.\"</color>",
  ui_story_1_1_3_dialog_content = "<color=#e8d9bb>\"Bantuan hidup… beroperasi. Kapasitas saat ini: 1 orang.\"</color>",
  ui_story_1_1_4_dialog_content = "<color=#e8d9bb>\"Generator… normal. Mencoba menyalakannya…\"</color>",
  ui_story_1_1_5_dialog_content = "<color=#e8d9bb>(8%… 3%… 1%…)</color>",
  ui_story_1_1_6_dialog_content = "<color=#e8d9bb>\"Gagal menyalakan. Jumlah Kegagalan: 3.921.\"</color>",
  ui_story_1_1_7_dialog_content = "<color=#e8d9bb>\"Level daya di bawah normal. Sisa 7%.\"</color>",
  ui_story_1_1_8_dialog_content = "<color=#e8d9bb>\"Tetap dalam mode hemat energi.\"</color>",
  ui_story_1_1_10_dialog_content = "<color=#e8d9bb>Hari ke-<color=#FFB400>6.055</color>.</color>",
  ui_story_1_1_X1_dialog_content = "<color=#e8d9bb>\"Silakan tanda tangani dan konfirmasikan.\"</color>",
  ui_story_1_1_18_dialog_content = "<color=#FFB400>Soroz</color>…?",
  ui_story_1_1_X2_dialog_content = "Ya, PlayerName.",
  ui_story_1_1_A1_dialog_content = "Apa ada yang tidak wajar di luar sana?",
  ui_story_1_1_A2_dialog_content = "Ada sinyal lemah yang mendekat, mungkin lagi-lagi kawanan <color=#FFB400>Eclipsite</color>, seperti biasa.",
  ui_story_1_1_A3_dialog_content = "Kalau begitu, abaikan saja. Aku ingin mencoba memulai kembali.",
  ui_story_1_1_A4_dialog_content = "Aku terpaksa menolak permintaanmu, PlayerName.",
  ui_story_1_1_A5_dialog_content = "Kau sudah mencoba terlalu banyak, dan kondisi mentalmu jadi terpengaruh…",
  ui_story_1_1_A6_dialog_content = "Tapi, daya kita hampir habis, dan kita harus mencari jalan keluar!",
  ui_story_1_1_A7_dialog_content = "Prioritas utamaku adalah menjaga agar kau tetap hidup dan selamat.",
  ui_story_1_1_A8_dialog_content = "Kalau dayanya benar-benar habis, kita akan mati!",
  ui_story_1_1_A9_dialog_content = "Di mana ada kemauan, di situ ada jalan.",
  ui_story_1_1_A10_dialog_content = "Sekarang sudah 17 tahun. Kalau memang ada jalan, harusnya kita sekarang sudah bisa keluar.",
  ui_story_1_1_A11_dialog_content = "Maaf, PlayerName, terlalu berisiko jika terus mencoba penyalaan ulang. Tolong tenangkan dulu dirimu.",
  ui_story_1_1_A12_dialog_content = "Kau sudah bisa menghubungi mereka?",
  ui_story_1_1_A13_dialog_content = "Peluang kita untuk menghubungi <color=#FFB400>Caelestite</color> lain sangat kecil, tapi akan kucoba lagi.",
  ui_story_1_1_A14_dialog_content = "Kalau bisa berkomunikasi dengan mereka, kita akan mampu…",
  ui_story_1_1_A15_dialog_content = [[
Menurut perhitunganku, tanpa generator yang masih berfungsi, 
peluang kita untuk keluar dari sini hampir mendekati nol.]],
  ui_story_1_1_A16_dialog_content = "…",
  ui_story_1_1_B1_dialog_content = "Ini ujian, PlayerName. Kamu bisa jadi kuat hanya jika kamu bisa mengasah keteguhanmu dalam kesendirian.",
  ui_story_1_1_B2_dialog_content = "Cukup sudah ceramahnya. Telingaku tak sanggup mendengarnya lagi.",
  ui_story_1_1_B3_dialog_content = "Kamu ingin mendengar sejarah kontinen ini sekali lagi?",
  ui_story_1_1_B4_dialog_content = "Aku sudah mendengarnya 192 kali.",
  ui_story_1_1_B5_dialog_content = "Perintah medan tempur?",
  ui_story_1_1_B6_dialog_content = "246 kali. Lagi pula, aku tak akan bisa mendengarkannya sementara aku sedang sibuk begini.",
  ui_story_1_1_B7_dialog_content = "Maaf, PlayerName. Aku hanya berusaha menghiburmu.",
  ui_story_1_1_B8_dialog_content = "…",
  ui_story_1_1_B9_dialog_content = "Apa kamu melihat <color=#FFB400>mimpi</color> itu lagi?",
  ui_story_1_1_B10_dialog_content = "Ya.",
  ui_story_1_1_B11_dialog_content = "Mimpi adalah visualisasi dari hal-hal tak diketahui yang dihadirkan oleh pikiran. Itu hanya ilusi.",
  ui_story_1_1_B12_dialog_content = "Kau suka melebih-lebihkan fenomena psikologis ini, yang juga disebut…",
  ui_story_1_1_B13_dialog_content = "Sudah 17 tahun dan aku masih saja belum terbiasa dengan cara bicaramu, Profesor Soroz.",
  ui_story_1_1_B14_dialog_content = "Aku hanya menekankan bahwa itu hanya <color=#FFB400>mimpi</color> dan tidak mencerminkan kenyataan.",
  ui_story_1_1_B15_dialog_content = "Tapi, rasanya begitu nyata sampai-sampai tak seperti mimpi. Seakan-akan aku memang ada di <color=#FFB400>Eraveil</color>, mengalami sendiri serangan itu…",
  ui_story_1_1_B16_dialog_content = "Aku bahkan bisa merasakan kesakitan mereka.",
  ui_story_1_1_B17_dialog_content = "Memori memang selalu dikaitkan dengan emosi, dan kebenaran pun jadi menyimpang.",
  ui_story_1_1_B18_dialog_content = "Kenyataannya adalah bahwa kau masih hidup, dan kewajibanku adalah menjaga agar kau tetap hidup.",
  ui_story_1_1_X3_dialog_content = "Mulai lagi, deh…",
  ui_story_1_1_19_dialog_content = "Sebentar, aku baru saja mendeteksi sinyal baru.",
  ui_story_1_1_20_dialog_content = "Sinyal baru?",
  ui_story_1_1_21_dialog_content = "Sinyalnya sedang kuanalisis… Sudah terkonfirmasi, asalnya dari <color=#FFB400>Aurorian</color>.",
  ui_story_1_1_22_dialog_content = "Aurorian?",
  ui_story_1_1_23_dialog_content = "Maaf, rupanya aku membuatmu berharap terlalu tinggi. Mereka bukan Caelestite.",
  ui_story_1_1_B20_dialog_content = "Tak apa, toh aku sudah terbiasa… Tapi, sedang apa kaum Aurorian di sini?",
  ui_story_1_1_B21_dialog_content = "Mereka sedang melawan <color=#FFB400>Eclipsite</color> persis di atas kita, dan sepertinya mereka kewalahan.",
  ui_story_1_1_A17_dialog_content = "Belum ada Aurorian yang pernah kemari. Kenapa malah hari ini, sih…",
  ui_story_1_1_24_dialog_content = "Akan kutunjukkan kepadamu apa yang terjadi di luar sana.",
  ui_story_1_1_25_dialog_content = "Apa barang yang kausebutkan tadi benar-benar ada di sini, <color=#FFB400>Vice</color>?",
  ui_story_1_1_26_dialog_content = "Kenapa ada begitu banyak Eclipsite di sekeliling? Mereka mengepung kita…",
  ui_story_1_1_27_dialog_content = "Tak salah lagi. Menurut hasil deteksi, mestinya ada <color=#FFB400>Colossus</color> di dekat sini!",
  ui_story_1_1_A18_dialog_content = "Pemeriksaan kita di area-area lain tak membuahkan hasil, tapi firasatku mengatakan kali ini kita akan menemukan sesuatu!",
  ui_story_1_1_A19_dialog_content = "Kalau boleh jujur, sebenarnya aku lebih memikirkan apakah kita bisa pulang hidup-hidup. Kita ini pengintai, bukan komando…",
  ui_story_1_1_28_dialog_content = "Sudah bisa diduga, Eclipsite itu akan datang kemari.",
  ui_story_1_1_29_dialog_content = "Tapi, jumlah mereka terlalu banyak!",
  ui_story_1_1_30_dialog_content = "Apa menurutmu mereka akan membiarkan kita pergi kalau kita bilang bahwa kita hanya numpang lewat?",
  ui_story_1_1_31_dialog_content = "Jangan konyol! <color=#FFB400>Perang</color> antara kita dan Eclipsite sudah berkobar lebih dari satu milenium.",
  ui_story_1_1_A20_dialog_content = "Lagi pula, apa yang membuatmu berpikir kutu-kutu itu akan bisa memahamimu?",
  ui_story_1_1_32_dialog_content = "Harusnya sejak awal aku tak usah ikut dalam misi ini. Kupikir tugas ini akan mudah…",
  ui_story_1_1_33_dialog_content = "Fokus. Eclipsite itu datang berduyun-duyun. Kita harus cari jalan keluar.",
  ui_story_1_1_34_dialog_content = "Serahkan padaku… Rapid Torrent!",
  ui_story_1_1_35_dialog_content = "Ayo berkoordinasi dengan Vice!",
  ui_story_1_1_36_dialog_content = "Kenapa tanahnya terbelah? Apa aku berhalusinasi gara-gara kurang tidur?",
  ui_story_1_1_37_dialog_content = "<size=45>Hati-hati, cari pegangan!</size>",
  ui_story_1_1_38_dialog_content = "Maaf, ya! Hati-hati melangkah—",
  ui_story_1_1_40_dialog_content = "Aduh, aduh, aduh…!",
  ui_story_1_1_41_dialog_content = "Semua baik-baik saja? Angel? Dove?",
  ui_story_1_1_42_dialog_content = "Di mana… Halo, apa kalian bisa mendengarku?",
  ui_story_1_1_43_dialog_content = "Di mana aku? Kenapa ada struktur di bawah tanah…?",
  ui_story_1_1_A21_dialog_content = "Tempat ini… juga sangat terawat. Aku tidak berhalusinasi, 'kan?",
  ui_story_1_1_44_dialog_content = "Apa aku benar-benar menemukan sebuah Colossus?",
  ui_story_1_1_45_dialog_content = "Angel, Dove, di mana kalian?!",
  ui_story_1_1_46_dialog_content = "<anim type=Shake>Aahhhhhh!</anim>",
  ui_story_1_1_47_dialog_content = "Ya ampun, Eclipsite lagi?!",
  ui_story_1_1_48_dialog_content = "Hantaman langsung dari para Aurorian menimbulkan celah di bagian belakang. Menilai kerusakan…",
  ui_story_1_1_49_dialog_content = "Apa itu artinya… Aku bisa keluar lewat celah itu?",
  ui_story_1_1_50_dialog_content = "Menurut hasilnya, iya, kau bisa keluar ke permukaan lewat celah itu.",
  ui_story_1_1_51_dialog_content = "Sungguh? Akhirnya aku bisa pergi…?",
  ui_story_1_1_A23_dialog_content = "Tapi, itu tidak disarankan karena ada banyak Eclipsite di sekitar.",
  ui_story_1_1_A24_dialog_content = "Sepertinya krisis belum teratasi dan dunia ini sama sekali belum berubah.",
  ui_story_1_1_52_dialog_content = "Aku setengah mati ingin lari keluar, tapi aku… enggan…",
  ui_story_1_1_B22_dialog_content = "Eclipsite memang ancaman mematikan untukmu.",
  ui_story_1_1_B23_dialog_content = "Bukan, bukan hanya Eclipsite itu…",
  ui_story_1_1_B24_dialog_content = "Ada perasaan lain yang lebih rumit dan tak bisa digambarkan.",
  ui_story_1_1_A25_dialog_content = "Maaf, aku tak paham. Kamu khawatir meninggalkanku sendirian?",
  ui_story_1_1_53_dialog_content = "Tak apa. Setelah dayanya habis, aku akan bebas seperti Colossus lainnya.",
  ui_story_1_1_54_dialog_content = "Tapi, aku harus memenuhi misiku. Dan, aku yakin kau juga punya misimu sendiri.",
  ui_story_1_1_55_dialog_content = "Tapi, sudah cukup, kita bicarakan itu nanti saja.",
  ui_story_1_1_56_dialog_content = "Aurorian itu sepertinya sedang menghadapi masalah besar. Lihat…",
  ui_story_1_1_58_dialog_content = "Tidak bisa… bertarung… Semua kekuatanku sudah habis terpakai…",
  ui_story_1_1_59_dialog_content = "Kenapa aku malah harus bertemu dengan Eclipsite, sih??",
  ui_story_1_1_60_dialog_content = "<anim type=Shake><size=50>Aahhhh!</size></anim>",
  ui_story_1_1_61_dialog_content = "Lumina… Aku butuh Lumina…",
  ui_story_1_1_62_dialog_content = "Jalan dua langkah ke arah pukul sembilan darimu.",
  ui_story_1_1_63_dialog_content = "<size=45>Siapa itu?!</size>",
  ui_story_1_1_64_dialog_content = "Apa aku salah dengar, atau memang Eclipsite itu benar-benar bicara?",
  ui_story_1_1_65_dialog_content = "Kamu tidak salah dengar. Aku memang berbicara kepadamu.",
  ui_story_1_1_66_dialog_content = "Ya ampun, ternyata yang bicara memang orang sungguhan! Tapi, sepertinya ini bukan dari saluran komunikasi kami…",
  ui_story_1_1_67_dialog_content = "Ini <color=#FFB400>telepati</color>.",
  ui_story_1_1_68_dialog_content = "Telepati?",
  ui_story_1_1_B25_dialog_content = "Ini pertama kalinya aku bicara dengan manusia, jadi aku masih berusaha membiasakan diri.",
  ui_story_1_1_A26_dialog_content = "Kau pasti bisa. Walau ini baru pertama kalinya untukmu, kau masih punya waktu bertahun-tahun untuk belajar…",
  ui_story_1_1_A27_dialog_content = "Kenapa kau tiba-tiba menyemangatiku? Memangnya kau ini siapa?",
  ui_story_1_1_A28_dialog_content = "Aku tadi bicara dengan diriku sendiri! Omong-omong…",
  ui_story_1_1_69_option_content = "Force Boost!",
  ui_story_1_1_70_dialog_content = "<size=45>Waaaooowww!</size>",
  ui_story_1_1_75_dialog_content = "Aku berhasil mengalahkan semua Eclipsite ini sendirian!",
  ui_story_1_1_76_dialog_content = "Melihat Light Trail, kekuatanku jadi meningkat luar biasa.",
  ui_story_1_1_77_dialog_content = "Apa aku sedang mengalami Luminoception Ascension? Apa aku sudah berhasil menguasai kemampuan baru yang belum dimiliki Aurorian lain?",
  ui_story_1_1_78_dialog_content = "Takdir, ini pasti takdir! Tidak… Mungkin aku sebenarnya berasal dari garis keturunan istimewa?",
  ui_story_1_1_79_dialog_content = "Kenapa aku harus mengalami tragedi dan halangan bertubi-tubi? Bagaimana kalau aku dicemooh karena aku ini orang luar?",
  ui_story_1_1_80_dialog_content = "Secara teknis, itu sebenarnya kemampuanku.",
  ui_story_1_1_81_dialog_content = "Ehh! Kau masih di sini? Apa kau ini hantu yang bergentayangan di sini?",
  ui_story_1_1_82_dialog_content = "Aku bukan hantu. Tadi itu hanya kemampuan psikisku, sama seperti Light Trail yang tadi kaulihat.",
  ui_story_1_1_83_dialog_content = "Apa? Berarti itu bukan karena aku mendapatkan kekuatan baru…?",
  ui_story_1_1_84_dialog_content = "Maaf mengecewakanmu.",
  ui_story_1_1_B26_dialog_content = "…",
  ui_story_1_1_B27_dialog_content = "Ah… Apa aku membuatmu takut?",
  ui_story_1_1_B28_dialog_content = "Tapi, aku juga takut saat kau tiba-tiba menyelonong masuk tadi.",
  ui_story_1_1_B29_dialog_content = "Aku tak tahu apa sebenarnya yang sedang terjadi.",
  ui_story_1_1_B30_dialog_content = "Ayo kita bicara tatap muka saja. Kaum Aurorian seperti kalian mungkin tidak terbiasa berkomunikasi seperti ini.",
  ui_story_1_1_85_dialog_content = "Jadi, ikuti saja terowongannya. Aku akan menunggumu di ruang paling akhir.",
  ui_story_1_1_86_dialog_content = "Waow…",
  ui_story_1_1_A34_dialog_content = "Hmm…",
  ui_story_1_1_87_dialog_content = "Ada apa? Ada sesuatu di wajahku? Aku memang baru saja mencuci muka, sih…",
  ui_story_1_1_88_dialog_content = "Anu, tak apa. Hanya saja, aku tak menyangka kau ternyata orang sungguhan. Kau bukan hantu, 'kan?",
  ui_story_1_1_89_dialog_content = "<size=40>Bukannya tadi sudah kubilang hantu itu tak ada?</size>",
  ui_story_1_1_B31_dialog_content = "Lalu, kenapa kau terlihat sangat kaget?",
  ui_story_1_1_B32_dialog_content = "… Aku tak menyangka ada orang yang masih hidup di sini.",
  ui_story_1_1_90_dialog_content = "Bukannya itu artinya sama saja… Jadi, siapa kau? Dan apa ini… Colossus?",
  ui_story_1_1_91_dialog_content = "Ini memang Colossus. Aku bertanggung jawab atasnya, dan akulah yang tadi berbicara denganmu melalui telepati.",
  ui_story_1_1_92_dialog_content = "Aku hanya pernah baca tentang kemampuan semacam ini di buku sejarah, tapi…",
  ui_story_1_1_93_dialog_content = "Tapi apa…?",
  ui_story_1_1_94_dialog_content = "Tunggu, apa kau ini seorang…|\n<color=#FFB400>Caelestite</color>?",
  ui_story_1_1_95_dialog_content = "Kenapa kau kaget begitu? Ya, aku Caelestite.",
  ui_story_1_1_96_dialog_content = "… Apa kau satu-satunya yang ada di sini?",
  ui_story_1_1_97_dialog_content = "Ya. Kampung halamanku dihancurkan oleh Eclipsite.",
  ui_story_1_1_A29_dialog_content = "Ya, aku juga dengar tentang itu…",
  ui_story_1_1_B33_dialog_content = "Boleh aku tanya sesuatu?",
  ui_story_1_1_B34_dialog_content = "Kau berdiri terlalu dekat, Caelestite…",
  ui_story_1_1_B35_dialog_content = "Ah, maaf. Aku hanya ingin tanya—",
  ui_story_1_1_B36_option_content = "Apa kau pernah bertemu Caelestite lain?",
  ui_story_1_1_B37_option_content = "Apa yang terjadi 17 tahun lalu?",
  ui_story_1_1_B38_option_content = "Sebenarnya Aurorian dan Eclipsite itu apa?",
  ui_story_1_1_B39_dialog_content = "Aku di sini sudah lama sekali, dan sistem komunikasiku rusak. Aku tak bisa…",
  ui_story_1_1_B40_dialog_content = "Tenanglah. Aku belum pernah bertemu dengan Caelestite, tapi mungkin itu karena memang tak pernah ada Caelestite di sekitarku.",
  ui_story_1_1_B41_dialog_content = "… Tapi, kenapa mereka tak berusaha mencariku, ya?",
  ui_story_1_1_B42_dialog_content = "…",
  ui_story_1_1_B43_dialog_content = "Dulu… Aku hanya pernah baca dokumen tentang apa yang terjadi di Eraveil. Tapi, kadang aku <color=#FFB400>bermimpi</color> aneh…",
  ui_story_1_1_B44_dialog_content = "Mimpi?",
  ui_story_1_1_B45_dialog_content = "Tentang malapetaka itu… bisakah kauceritakan lebih banyak?",
  ui_story_1_1_B46_dialog_content = "Aku baru saja lahir saat peristiwa itu terjadi, jadi aku sama sekali tak tahu banyak.",
  ui_story_1_1_B47_dialog_content = "Sepertinya Eclipsite tiba-tiba saja melancarkan <color=#FFB400>serangan tertata</color> dan menumpas Eraveil dalam semalam.",
  ui_story_1_1_B48_dialog_content = "Ya, aku sudah tahu itu.",
  ui_story_1_1_B49_dialog_content = "Hanya itu yang kutahu, maaf…",
  ui_story_1_1_B50_dialog_content = "Jadi, kau ini <color=#FFB400>Aurorian</color>?",
  ui_story_1_1_B51_dialog_content = "Ya, dan kudengar dulu kaum kami bekerja sama dengan kaum Caelestite untuk melawan Eclipsite.",
  ui_story_1_1_B52_dialog_content = "Monster-monster yang tadi itu, mereka Eclipsite, 'kan?",
  ui_story_1_1_B53_dialog_content = "Ya, benar. Monster-monster itu kini merajalela di setiap penjuru kontinen. Tak ada yang tahu dari mana asal mereka.",
  ui_story_1_1_B54_dialog_content = "Ada yang bilang mereka datang dari bagian lain negeri ini. Ada yang bilang mereka datang sebagai hukuman dari langit.",
  ui_story_1_1_B55_dialog_content = "Yang jelas, mereka memang sudah jadi musuh kita bersama sejak dulu.",
  ui_story_1_1_B56_dialog_content = "Yah… Aku sudah baca tentang ini semua di arsip.",
  ui_story_1_1_B57_dialog_content = "Kalau begitu, kenapa masih tanya?",
  ui_story_1_1_B58_option_content = "Aku punya pertanyaan lain.",
  ui_story_1_1_B59_option_content = "*Diam saja*",
  ui_story_1_1_B60_dialog_content = "Aku punya pertanyaan lain—",
  ui_story_1_1_98_dialog_content = "Omong-omong, kau 'kan selama ini berada di sini, apa kau tidak pernah berpikir ingin pergi dari sini?",
  ui_story_1_1_99_dialog_content = "Yah… Kami tidak tahu cara bertarung, tidak seperti kalian yang bisa menggunakan <color=#FFB400>Luminatics</color>.",
  ui_story_1_1_100_dialog_content = "Aku bisa lihat Light Trail, tapi tak bisa memanfaatkannya untuk bertarung. Ironis, ya?",
  ui_story_1_1_101_dialog_content = "Tidak, yang ironis adalah Aurorian bisa memanfaatkannya untuk bertarung, tapi tak bisa melihat Light Trail.",
  ui_story_1_1_103_dialog_content = "Oh, ya, aku tidak pernah keluar dari bawah tanah dan selama ini bertahan dengan bantuan hidup dari Soroz.",
  ui_story_1_1_104_dialog_content = "\"<color=#FFB400>Soroz</color>\"? Maksudmu Colossus ini? Dia punya nama? Wow…!",
  ui_story_1_1_105_dialog_content = "Tentu saja, sebagai kombinasi sihir, teknologi, dan kehidupan, Colossus punya akal sendiri.",
  ui_story_1_1_106_dialog_content = "Karena kau ini Caelestite, kau pasti bisa berkomunikasi dengannya, 'kan?",
  ui_story_1_1_107_dialog_content = "Tentu saja, itu kemampuan alami kami.",
  ui_story_1_1_109_dialog_content = "Kenapa? Kau terluka?",
  ui_story_1_1_110_dialog_content = "…",
  ui_story_1_1_111_dialog_content = "Hah…? Tidak, baru saja aku teringat sesuatu, itu saja.",
  ui_story_1_1_112_dialog_content = "Oh, ya, apa berarti dia masih bisa dioperasikan? Mungkin kita bisa…",
  ui_story_1_1_113_dialog_content = "Maaf, walaupun dulu Soroz memang salah satu Colossus terbaik di kelas Sky, aku masih belum bisa menyalakannya.",
  ui_story_1_1_114_dialog_content = "Tapi, sepertinya kamu tahu banyak tentang Colossus. Ya, 'kan, Vice?",
  ui_story_1_1_115_dialog_content = "Hanya sedikit! Aku pernah baca buku tentang mereka, dan misiku sebenarnya adalah mencari Colossus yang mungkin berhasil bertahan…",
  ui_story_1_1_A31_dialog_content = "Sebentar, kau tadi memanggilku apa? Seingatku, aku belum memberitahukan namaku!",
  ui_story_1_1_A32_dialog_content = "Ini karena kemampuan psikisku, Vice. Tadi aku mendengar percakapanmu dengan skuadmu di luar sana.",
  ui_story_1_1_A33_dialog_content = "Oh… Benar, aku lupa kau ini Caelestite.",
  ui_story_1_1_116_dialog_content = "Sayang sekali Soroz tidak bisa diaktifkan, tapi sepertinya aku justru menemukan sesuatu yang lebih baik!",
  ui_story_1_1_117_dialog_content = "Apa yang kaumaksud itu aku?",
  ui_story_1_1_118_dialog_content = "Aku masih butuh bantuanmu… Anu, aku belum tahu namamu…",
  ui_story_1_1_119_dialog_content = "PlayerName.",
  ui_story_1_1_120_dialog_content = "PlayerName? Kedengarannya agak eksotis!",
  ui_story_1_1_121_dialog_content = "Aku terpisah dari skuadku saat jatuh tadi. Kau bisa bantu aku mencari mereka?",
  ui_story_1_1_122_dialog_content = "Aku tidak merasakan keberadaan mereka sekarang. Bagaimana, Soroz, kau tahu di mana mereka?",
  ui_story_1_1_123_dialog_content = "Ada dua Aurorian di Luminite Altar, dan ada banyak Eclipsite bergerak mendekati area itu.",
  ui_story_1_1_124_dialog_content = "Dengan kata lain, mungkin kita pun tak aman di sini.",
  ui_story_1_1_125_dialog_content = "Sepertinya mereka sedang menghadapi masalah di dekat Luminite Altar.",
  ui_story_1_1_126_dialog_content = "Kalau begitu, aku harus membantu mereka!",
  ui_story_1_1_127_dialog_content = "Aku butuh bantuanmu! Kau bisa lihat Light Trail dan, yang lebih penting, kau bisa memandu kami dalam pertempuran!",
  ui_story_1_1_128_dialog_content = "Maksudku, tadi kau meningkatkan kekuatan tempurku begitu saja!",
  ui_story_1_1_129_option_content = "Tapi, aku tidak lihai bertarung…",
  ui_story_1_1_130_option_content = "Kalau begitu, kita akan bertarung bersama!",
  ui_story_1_1_131_dialog_content = "Jangan khawatir, aku akan melindungimu!",
  ui_story_1_1_132_dialog_content = "Dia benar. Para Eclipsite sudah masuk ke area ini. Kita akan lebih aman jika bersamanya.",
  ui_story_1_1_133_dialog_content = "Oke, Vice. Tapi, aku punya satu permintaan…",
  ui_story_1_1_134_dialog_content = "Baiklah! Kau tak perlu mengkhawatirkan apa pun, aku akan melindungimu!",
  ui_story_1_1_135_dialog_content = "Aurorian pemberani ini bernama Vice, 'kan?",
  ui_story_1_1_X6_dialog_content = "Keputusan yang kauambil juga luar biasa, PlayerName.",
  ui_story_1_1_136_dialog_content = "Tapi, aku punya permintaan, dan kuharap kau bisa membantuku.",
  ui_story_1_1_B61_dialog_content = "Bukan masalah! Apa pun itu, akan kulakukan sebisaku!",
  ui_story_1_1_137_dialog_content = "Aku ingin kau membantuku keluar dari sini.",
  ui_story_1_1_138_dialog_content = "Keluar dari sini… Tentu saja. Tapi, apa kau yakin?",
  ui_story_1_1_139_dialog_content = "Aku… tidak yakin.",
  ui_story_1_1_140_dialog_content = "Tapi, aku tahu aku harus keluar dari sini!",
  ui_story_1_2_1_dialog_content = "Aku tak sanggup lagi, Angel…",
  ui_story_1_2_2_dialog_content = "Eclipsite itu terus saja berdatangan. Aku tak bisa bertahan lebih lama lagi…",
  ui_story_1_2_3_dialog_content = "Nyaris tak ada Lumina di tempat gelap dan kosong ini. Tanpa cahaya, Eclipsite itu akan jadi lebih sulit diatasi!",
  ui_story_1_2_4_dialog_content = "Bagaimana kita bisa kembali ke permukaan, dan mana Vice?",
  ui_story_1_2_6_dialog_content = "Aku tak mau mati di sini!",
  ui_story_1_2_7_dialog_content = "Dove! Ini aku!",
  ui_story_1_2_8_dialog_content = "Untunglah sisa Lumina-mu tidak banyak. Kalau tidak, Vice pasti sudah terluka…",
  ui_story_1_2_9_dialog_content = "Vice? Kau baik-baik saja?",
  ui_story_1_2_10_dialog_content = "Aku baik-baik saja. Aku berhasil menemukanmu berkat bantuan PlayerName!",
  ui_story_1_2_11_dialog_content = "PlayerName? Siapa dia? Aku tidak lihat siapa pun…",
  ui_story_1_2_12_dialog_content = "PlayerName bisa memberi tahu apa yang harus kita lakukan dari jauh! Kita hanya perlu bekerja sama!",
  ui_story_1_2_13_dialog_content = "Bekerja sama? Bagaimana? Kita…",
  ui_story_1_2_14_option_content = "Force Boost!",
  ui_story_1_2_15_dialog_content = "Apa aku bermimpi jalan-jalan melintasi cahaya?",
  ui_story_1_2_16_dialog_content = "Sebenarnya ada apa ini, Vice? Dan kenapa orang itu sembunyi di balik pintu?",
  ui_story_1_2_17_dialog_content = "Maaf, aku sama sekali tak bisa bertarung.",
  ui_story_1_2_18_dialog_content = "Luminoception dan kemampuan psikis… Jadi, kau ini…",
  ui_story_1_2_19_dialog_content = "Kau tak pernah bilang kau punya teman seperti ini, Vice.",
  ui_story_1_2_20_option_content = "Yah, sebenarnya kami memang baru saja bertemu…",
  ui_story_1_2_21_option_content = "Teman?",
  ui_story_1_2_22_dialog_content = "Ya, PlayerName menyelamatkanku setelah kita jatuh tadi.",
  ui_story_1_2_23_dialog_content = "PlayerName adalah master Colossus ini, dan dia seorang Caelestite.",
  ui_story_1_2_24_dialog_content = "\"Teman\"… ku?",
  ui_story_1_2_25_dialog_content = "Kenapa, PlayerName?",
  ui_story_1_2_26_dialog_content = "Oh, anu, tak apa.",
  ui_story_1_2_28_dialog_content = "Aku juga bertemu dengan Eclipsite setelah aku jatuh. PlayerName menyelamatkanku.",
  ui_story_1_2_29_dialog_content = "Ini Angel, dan ini Dove. Kami berasal dari skuad yang sama.",
  ui_story_1_2_30_dialog_content = "Aku PlayerName, pemilik Colossus ini, dan aku seorang Caelestite.",
  ui_story_1_2_31_dialog_content = "Terima kasih atas bantuanmu, PlayerName. Tapi, sepertinya aku masih punya pertanyaan untukmu…",
  ui_story_1_2_32_dialog_content = "Caele-apa? Aku sama sekali tak paham apa maksud kalian.",
  ui_story_1_2_33_dialog_content = "Oh, ya, terima kasih, PlayerName. Mari berteman!",
  ui_story_1_2_34_dialog_content = "Aku tak pernah menyangka suatu hari aku akan punya teman…",
  ui_story_1_3_1_dialog_content = "Sekarang, bagaimana, Vice? Eclipsite itu terlalu banyak. Kita butuh bala bantuan.",
  ui_story_1_3_2_dialog_content = "Komunikatornya hancur dalam pertarungan tadi. <color=#FFB400>Navigator</color>, apa Soroz punya sarana komunikasi?",
  ui_story_1_3_3_dialog_content = "Tidak, sudah hancur.",
  ui_story_1_3_X1_dialog_content = "Kalau begitu, kalian pasti punya senjata, 'kan?",
  ui_story_1_3_X2_dialog_content = "Tidak, sama sekali tidak.",
  ui_story_1_3_4_dialog_content = "Kenapa tidak kita aktifkan saja Colossus itu?",
  ui_story_1_3_X3_dialog_content = "<color=#e8d9bb>Gagal mengaktifkan. Jumlah Kegagalan: 3.921.</color>",
  ui_story_1_3_X4_dialog_content = "Sia-sia saja.",
  ui_story_1_3_X5_dialog_content = "Kenapa begitu?",
  ui_story_1_3_X6_dialog_content = "Tidak. Sudah tak terhitung berapa kali aku mencobanya, tapi selalu saja gagal, entah karena apa.",
  ui_story_1_3_X7_dialog_content = "Maaf, tapi kondisi Colossus ini buruk sekali.",
  ui_story_1_3_X8_dialog_content = "Colossus ini sudah berusaha sebisanya, dia berusaha keras sekadar agar aku bisa tetap hidup.",
  ui_story_1_3_X9_dialog_content = "Terima kasih atas pujianmu, PlayerName.",
  ui_story_1_3_X10_dialog_content = "…",
  ui_story_1_3_6_dialog_content = "Tunggu sebentar, Navigator.",
  ui_story_1_3_X11_dialog_content = "Walaupun dia tak bisa dinyalakan dan tidak ada senjata, tadi kau menyebutkan sesuatu tentang…",
  ui_story_1_3_7_dialog_content = "Luminite Altar, 'kan?",
  ui_story_1_3_8_dialog_content = "Seingatku, setiap Colossus punya Luminite Altar untuk mengirimkan sinyal minta bantuan.",
  ui_story_1_3_A1_dialog_content = "Kalau mereka lihat sinyalnya, pasti akan ada orang yang datang kemari!",
  ui_story_1_3_9_dialog_content = "Harusnya ada di dekat sini, 'kan? Tadi kaubilang Dove dan Angel sangat dekat dengannya.",
  ui_story_1_3_10_dialog_content = "… Rupanya kau cukup ahli dalam hal Colossus, ya?",
  ui_story_1_3_X12_dialog_content = "Ah, aku hanya tahu sedikit. Biasanya orang-orang bilang padaku tak ada gunanya aku tahu tentang hal-hal ini…",
  ui_story_1_3_X13_dialog_content = "Stasiunnya memang dekat dari sini dan kondisinya masih sempurna.",
  ui_story_1_3_X14_dialog_content = "Tapi, kurasa kau pasti bisa menebak apa yang akan kukatakan…",
  ui_story_1_3_11_dialog_content = "Kita tidak punya material yang dibutuhkan untuk mengirimkan sinyal…",
  ui_story_1_3_12_dialog_content = "<color=#FFB400>Lumamber</color>.",
  ui_story_1_3_13_dialog_content = "Bagaimana kau—untuk ukuran \"sedikit\", kau tahu banyak sekali.",
  ui_story_1_3_14_dialog_content = "Kalau memang butuh Lumamber, kami punya, sih.",
  ui_story_1_3_15_dialog_content = "Tapi, Vice…",
  ui_story_1_3_16_dialog_content = "Apa? Kita 'kan memang punya. Di dalam tasmu. Aku tadi lihat!",
  ui_story_1_3_18_dialog_content = "Itu sangat mahal…",
  ui_story_1_3_19_dialog_content = "Ini urusan hidup dan mati! Bukan saatnya bersikap kikir, Dove!",
  ui_story_1_3_B1_dialog_content = "Apa nanti aku akan diberi ganti rugi?",
  ui_story_1_3_B2_dialog_content = "Tentu saja! Kau boleh libur 10 hari setelah kita kembali nanti. Bagaimana?",
  ui_story_1_3_B3_dialog_content = "Krr krr, setuju!",
  ui_story_1_3_B4_dialog_content = "Kalau begitu, ayo ke Luminite Altar!",
  ui_story_1_3_A2_dialog_content = "Mungkin masih ada banyak lagi Eclipsite di sepanjang jalan, jadi tetaplah waspada!",
  ui_story_1_3_24_dialog_content = "Ini dia! Untunglah ada Navigator. Kalau tidak, kita tak mungkin bisa menemukannya.",
  ui_story_1_3_25_dialog_content = "Sudah 17 tahun, tahu…",
  ui_story_1_3_26_dialog_content = "Syukurlah, kita sampai lebih dulu dari para Eclipsite itu.",
  ui_story_1_3_27_dialog_content = "Untunglah, tak ada yang rusak.",
  ui_story_1_3_28_dialog_content = "Jadi, apa itu kontrolnya?",
  ui_story_1_3_29_dialog_content = "Wow, ini pertama kalinya aku lihat ini secara langsung! Nah, tentang detail pengoperasiannya…",
  ui_story_1_3_30_dialog_content = "Masukkan Lumamber ke dalam proyektor, kemudian <color=#FFB400>tarik tuasnya</color>. Begitu saja.",
  ui_story_1_3_31_dialog_content = "Sayang sekali selama ini aku tak punya material yang dibutuhkan untuk ini…",
  ui_story_1_3_33_dialog_content = "Tapi, sekarang kau punya teman yang bisa diandalkan! Dove!",
  ui_story_1_3_34_dialog_content = "Vice, kau akan menggunakan material ini dengan baik, 'kan?",
  ui_story_1_3_35_dialog_content = "Tentu saja.",
  ui_story_1_3_36_dialog_content = "…",
  ui_story_1_3_B5_dialog_content = "… Dove, kau… bisa melepaskannya sekarang.",
  ui_story_1_3_B6_dialog_content = "Krr krr, apa sudah terlambat untuk berubah pikiran?",
  ui_story_1_3_B7_dialog_content = "Kalau kau tak menepati kata-katamu tadi, akan kupaksa kau makan seribu jari Eclipsite.",
  ui_story_1_3_B8_dialog_content = "Krr!",
  ui_story_1_4_1_dialog_content = "Hei, berhasil! Wow, terang sekali!",
  ui_story_1_4_2_dialog_content = "Kita berhasil… Terima kasih, Vice!",
  ui_story_1_4_3_dialog_content = "Eh? Aku 'kan tidak melakukan apa pun. Aku hanya menawarkan ide gila, itu saja.",
  ui_story_1_4_4_dialog_content = "Kalau kau memang mau berterima kasih kepadaku, tunggu sampai kita berhasil keluar dari sini.",
  ui_story_1_4_5_dialog_content = "Yah, kita memang punya Aurorian yang luar biasa, dan kalian semua punya semangat kerja sama yang hebat!",
  ui_story_1_4_6_dialog_content = "Kesunyian bertahun-tahun ini… hari ini berakhir.",
  ui_story_1_4_X1_dialog_content = "Tapi, kenapa kau tampak tak gembira, PlayerName? Kau baik-baik saja?",
  ui_story_1_4_X2_dialog_content = "Aku tak apa, hanya agak lelah…",
  ui_story_1_4_B29_dialog_content = "Mengantuk? Saya punya ini untuk Anda—gambar teknik!",
  ui_story_1_4_B30_dialog_content = "Setiap kali merasa mengantuk, aku membolak-baliknya… Setelah melihat diagram ini, aku selalu merasa segar lagi!",
  ui_story_1_4_B31_dialog_content = "Kurasa tidak semua orang punya otak sepertimu, Vice.",
  ui_story_1_4_X3_dialog_content = "Hah? Tapi… Eh!",
  ui_story_1_4_X4_dialog_content = "Kenapa? Apa ada sesuatu lagi di wajahku?",
  ui_story_1_4_X5_dialog_content = "Hidungmu berdarah!",
  ui_story_1_4_X6_dialog_content = "Oh, tidak. Telepati… kelebihan beban…",
  ui_story_1_4_X7_dialog_content = "Mengoperasikan Luminite Altar ini membuat tenagaku terkuras…",
  ui_story_1_4_A1_dialog_content = "Tadi kau mengarahkan kami dengan mudah, lalu kenapa sekarang…?",
  ui_story_1_4_A2_dialog_content = "Mengontrol Colossus… butuh… energi lebih banyak… Aku tak apa… ini sudah pernah terjadi… Aku akan…",
  ui_story_1_4_7_option_content = "A-aku tak bisa…",
  ui_story_1_4_8_option_content = "Vice…",
  ui_story_1_4_9_dialog_content = "Apa kau baik-baik saja… Hei, siapa saja, tolong, PlayerName pingsan!",
  ui_story_1_4_10_dialog_content = "Aku tidak bisa memapahmu… Kemari, kalian berdua! Aku tak bisa menggendong PlayerName sendirian!!",
  ui_story_1_4_12_dialog_content = "Suarnya menarik para Eclipsite. Kita harus pergi!",
  ui_story_1_4_13_dialog_content = "Lt. Vice, PlayerName masih belum siuman, dan aku khawatir gerak kita akan jadi lambat kalau kita membawa dia.",
  ui_story_1_4_A6_dialog_content = "Tugas utamaku adalah mengawal nona ini ke <color=#FFB400>Undercity 28</color>. Waktu kita tak banyak…",
  ui_story_1_4_A3_dialog_content = [[
Kuhargai bantuanmu, prajurit.|
Tapi, PlayerName sudah menyelamatkan kita. Kita tak bisa meninggalkan PlayerName begitu saja.]],
  ui_story_1_4_14_dialog_content = "Di <color=#FFB400>Illumina Federation</color>, kita tidak akan membalas kebaikan dengan sikap abai.",
  ui_story_1_4_A4_dialog_content = "Lagi pula, PlayerName ini seorang Caelestite.",
  ui_story_1_4_15_dialog_content = "Benarkah?",
  ui_story_1_4_16_dialog_content = "Tapi, pasukan kita tidak cukup untuk menjaga keselamatan semua orang sambil menyeret orang pingsan ini!",
  ui_story_1_4_17_dialog_content = [[
Kau benar, prajurit.|
Tolong pandu semua orang keluar, dan tinggalkan sebagian suplai. Aku akan di sini untuk melindungi Caelestite ini.]],
  ui_story_1_4_18_dialog_content = "Kau memang layak jadi panutan, Lt. Vice!",
  ui_story_1_4_19_dialog_content = "Aku belum memperkenalkan diri. Namaku Blanc. Senang bertemu denganmu.",
  ui_story_1_4_20_dialog_content = "Maaf merepotkanmu, Kapten…",
  ui_story_1_4_21_dialog_content = "Tak apa. Tak ada alasan untuk mengabaikan sinyal minta bantuan.",
  ui_story_1_4_22_dialog_content = "Dan perjalananku jelas tak sia-sia karena aku jadi bisa melihat Colossus.",
  ui_story_1_4_23_dialog_content = "Karena sang Kapten memutuskan untuk tetap di sini, sebagai anggota Exploration Team, aku juga tak bisa pergi begitu saja.",
  ui_story_1_4_24_dialog_content = "Krr? Kalau begitu… kurasa aku juga akan tetap di sini. Maksudku, PlayerName memang menyelamatkan kita tadi.",
  ui_story_1_4_25_dialog_content = "Kalian semua…",
  ui_story_1_4_A5_dialog_content = [[
Oh, kau sudah siuman!|
Bala bantuan sudah tiba. Bagaimana rasanya? Kau bisa bergerak?]],
  ui_story_1_4_26_dialog_content = "Hmm…",
  ui_story_1_4_28_dialog_content = "Baru saja kami menerima laporan bahwa Kraken terlihat di dekat sini, Lt. Vice.",
  ui_story_1_4_29_dialog_content = "<color=#FFB400>Kraken, High-Level Eclipsite itu</color>? Belakangan ini dia memang aktif, tapi kenapa dia sampai sedekat ini dengan kita?",
  ui_story_1_4_30_dialog_content = "Apa pun alasannya, bukan itu yang harus kita khawatirkan sekarang! Ayo pergi!",
  ui_story_1_4_31_dialog_content = "Maukah kau ikut dengan kami, PlayerName?",
  ui_story_1_4_32_dialog_content = "Aku sangat ingin ikut denganmu, Vice, tapi Soroz…",
  ui_story_1_4_33_dialog_content = "Jadi, Colossus itu bernama Soroz? Kita bisa susun rencana nanti untuk mengambil Soroz.",
  ui_story_1_4_X8_dialog_content = "Tugasku adalah memastikan semua orang selamat, itu saja.",
  ui_story_1_4_X9_dialog_content = "Tak apa, PlayerName. Asalkan kau tak lagi dalam bahaya, keselamatanku tak perlu dikhawatirkan.",
  ui_story_1_4_X10_dialog_content = "Sekarang, hindari saja para Eclipsite itu dan pergilah dari sini!",
  ui_story_1_4_B1_option_content = "Maafkan aku. Aku akan kembali sesegera mungkin!",
  ui_story_1_4_B2_option_content = "Tak adakah cara agar kita bisa pergi bersama-sama?",
  ui_story_1_4_B3_option_content = "Aku harus mengemasi barang-barangku…",
  ui_story_1_4_B4_dialog_content = "Sudah kuputuskan. Aku akan ikut denganmu!",
  ui_story_1_4_B5_dialog_content = "Sekarang, yang kutahu hanyalah bahwa aku sudah menanti terlalu lama… Apa pun yang sedang terjadi di luar sana, aku harus melihatnya dengan mata kepalaku sendiri.",
  ui_story_1_4_B6_dialog_content = "Ada banyak hal yang ingin kutanyakan kepada kaumku…",
  ui_story_1_4_B7_dialog_content = "Baiklah! Kalau begitu, ayo bersiap untuk bertarung. Kalau Eclipsite itu sudah berkerumun di sekitar sini, pasti kita akan menghadapi pertempuran besar!",
  ui_story_1_4_B9_dialog_content = "Nostalgia, rasa takut, kecemasan… Aku harus bisa mengatasi semua itu agar bisa jadi lebih kuat.",
  ui_story_1_4_B10_dialog_content = "Kuharap kau bisa belajar untuk mengatasinya… Kau bisa mulai dengan mengucapkan salam perpisahan kepadaku.",
  ui_story_1_4_B11_dialog_content = "Soroz…",
  ui_story_1_4_B12_dialog_content = "Kau hanya akan bisa memenuhi takdirmu sebagai seorang Caelestite kalau kau bisa pergi dari sini. Pergilah, semua orang mengandalkanmu!",
  ui_story_1_4_B13_dialog_content = "Dan aku pun tak akan ke mana-mana. Jangan khawatir.",
  ui_story_1_4_B14_dialog_content = "PlayerName, kita harus bertindak sekarang, sebelum Eclipsite yang berdatangan makin banyak!",
  ui_story_1_4_B15_dialog_content = "Aku paham…",
  ui_story_1_4_B16_dialog_content = "Oke! Semuanya, fokus! Bersiaplah untuk bertarung sewaktu-waktu! Kita akan keluar dari sini!",
  ui_story_1_4_B17_dialog_content = "Hah? Barang bawaan?",
  ui_story_1_4_B18_dialog_content = "Satu kaleidoskop yang terbuat dari suku cadang, bola-bola kecil yang terbungkus kawat, dan beberapa gambar yang dibuat dengan cat Lumina.",
  ui_story_1_4_B19_dialog_content = "…",
  ui_story_1_4_B20_dialog_content = "Jangan mengejekku! Ini memang hanya barang remeh, tapi barang-barang ini sudah lama sekali menemaniku…",
  ui_story_1_4_B21_dialog_content = "Aku bahkan menamainya.",
  ui_story_1_4_B22_dialog_content = "… Aku paham perasaanmu, tapi ini bukan saatnya merisaukan barang-barang itu.",
  ui_story_1_4_B23_dialog_content = "Percayalah padaku, PlayerName, kau akan menemukan lebih banyak barang berharga setelah keluar dari sini.",
  ui_story_1_4_B24_dialog_content = "Aku tak akan pergi ke mana pun, begitu juga barang-barang itu. Kau bisa jemput kami setelah semua ini berakhir.",
  ui_story_1_4_B25_dialog_content = "Sepertinya aku tak punya pilihan…",
  ui_story_1_4_B26_dialog_content = "Maaf tadi aku bicara aneh… Ayo kita pergi sekarang.",
  ui_story_1_4_B32_dialog_content = "Haha, tak usah dipikirkan! Aku juga punya banyak hobi aneh!",
  ui_story_1_4_B27_dialog_content = "Ayo! Tetap bersemangat dan cari jalan keluarnya sebelum para Eclipsite itu berkumpul!",
  ui_story_1_4_B28_dialog_content = "Oh, ya, Navigator, bersiaplah untuk mengomando kami dalam pertempuran sewaktu-waktu!",
  ui_story_1_8_1_dialog_content = "Mereka banyak sekali… Kita tak boleh berlama-lama lagi di sini.",
  ui_story_1_8_B37_dialog_content = "Semuanya hancur. Bertahun-tahun upaya pembersihan dilakukan tanpa kenal lelah, ternyata sia-sia saja.",
  ui_story_1_8_2_dialog_content = "Maaf, PlayerName, seandainya saja tadi kami tidak menerobos masuk…",
  ui_story_1_8_3_dialog_content = "Maka, aku tak akan punya kesempatan untuk keluar dari sini. Jangan menyalahkan diri, ini bukan salahmu. Ini salah makhluk-makhluk yang merayap dari bayang-bayang itu.",
  ui_story_1_8_B29_dialog_content = "Tak usah khawatir, tunggu saja sampai kita bisa mengambil Soroz—aku akan meminta Illumina untuk melakukan perbaikan menyeluruh untuknya!",
  ui_story_1_8_B30_dialog_content = "Aku sendiri juga bisa mendesain rencana modifikasi untukmu!",
  ui_story_1_8_B31_dialog_content = "Apa kau punya ide untuk upgrade desain? Bagaimana kalau kita tambahkan dapur terbuka? Kau bisa memasak sup gurita lezat kapan pun kau mau.",
  ui_story_1_8_B32_dialog_content = "Aku tak bisa masak. Biasanya, itu jadi urusan Soroz…",
  ui_story_1_8_B33_dialog_content = "Ah, ya. Bagaimana kalau bathtub besar? Setelah bekerja keras seharian, kau bisa mandi berendam air hangat sambil membaca buku—",
  ui_story_1_8_B34_dialog_content = "Tidak, tidak, tidak. Saat ini aku tidak butuh hal-hal semacam itu…",
  ui_story_1_8_B35_dialog_content = "Mungkin ruang gambar teknis sebenarnya lebih penting...",
  ui_story_1_8_B36_dialog_content = "Terima kasih, Vice. Kalau kau sebenarnya hanya ingin menghiburku, kau berhasil. Aku sudah merasa lebih baik.",
  ui_story_1_8_4_dialog_content = "Hah? Oh… maaf…",
  ui_story_1_8_B38_dialog_content = "Hanya saja, kau tampak agak sedih dan aku hanya menyebutkan hal-hal yang mungkin menarik untukmu agar kau bisa sedikit ceria…",
  ui_story_1_8_5_dialog_content = "Lagi pula, karena jumlah orang yang kaukomando kini makin bertambah, aku khawatir kalau-kalau kau akan mimisan lagi…",
  ui_story_1_8_6_dialog_content = "Mendukung kalian semua sama sekali tak ada apa-apanya dibandingkan bertelepati dengan Colossus. Seperti membalikkan telapak…",
  ui_story_1_8_7_dialog_content = "<size=45>Ada kendala di depan sana! Mundur, mundur sekarang juga!</size>",
  ui_story_1_8_8_dialog_content = "Apa itu…?",
  ui_story_1_8_9_dialog_content = "Sial, hanya ada satu makhluk yang punya kekuatan sebesar itu…",
  ui_story_1_8_10_dialog_content = "<color=#FFB400>Kraken</color>!",
  ui_story_1_8_11_dialog_content = "<anim type=Shake><size=50>Aahhhhhh!</size></anim>",
  ui_story_1_8_12_dialog_content = "Aku tak menyangka ada Eclipsite sebesar itu! Apa dulu monster yang menyerang Eraveil juga sebesar itu?",
  ui_story_1_8_13_dialog_content = "Awas, PlayerName! Cari tempat aman, berlindunglah!",
  ui_story_1_8_14_dialog_content = "Tak ada tempat aman! Satu-satunya cara adalah menghadapi Kraken itu!",
  ui_story_1_8_15_option_content = "Kalau begitu, ayo kalahkan monster itu dari depan!",
  ui_story_1_8_16_option_content = "Aku akan membantu dari belakang!",
  ui_story_1_8_17_dialog_content = "Nah, begitu! Ayo!",
  ui_story_1_8_A2_dialog_content = "Siap menerima perintahmu, Navigator!",
  ui_story_1_8_18_dialog_content = "Memulai telepati! Bersiaplah!",
  ui_story_1_8_19_dialog_content = "Siap! Ayo!",
  ui_story_1_8_20_dialog_content = "<anim type=Shake><size=50>Aahhhhhh!</size></anim>",
  ui_story_1_8_21_dialog_content = "Tutup mulutmu dan kembalilah ke asalmu!",
  ui_story_1_8_B1_dialog_content = "Gah, gah…",
  ui_story_1_8_B2_dialog_content = "Sepertinya dia… berusaha bilang sesuatu?",
  ui_story_1_8_B3_option_content = "Layangkan serangan akhirnya, Vice.",
  ui_story_1_8_B4_option_content = "Force Boost!",
  ui_story_1_8_B6_dialog_content = "Rapid Torrent—",
  ui_story_1_8_B7_dialog_content = "Aku tak peduli makhluk ini bilang apa, aku sama sekali tak mau tahu…",
  ui_story_1_8_B8_dialog_content = "Dia bau sekali!!!",
  ui_story_1_8_B9_dialog_content = "Itu bau <color=#FFB400>Eclipsium</color>. Semua Eclipsite bergantung pada energi ini.",
  ui_story_1_8_B10_dialog_content = "Baunya memang membuat siapa pun mual.",
  ui_story_1_8_B11_dialog_content = "Gah, gah…",
  ui_story_1_8_B12_dialog_content = "Bahasa Eclipsite sama sekali tak bisa dimengerti…",
  ui_story_1_8_B13_dialog_content = "Aku belum pernah mencoba berkomunikasi dengan makhluk lain lewat telepati. Aku bahkan tak tahu apa aku bisa…",
  ui_story_1_8_B14_dialog_content = "<color=#FFB400>Caeles</color>… <color=#FFB400>tite</color>?",
  ui_story_1_8_B15_dialog_content = "…?",
  ui_story_1_8_B16_dialog_content = "Urraagh…",
  ui_story_1_8_B17_dialog_content = "Dia mati…? Sayang sekali, aku tak bisa mendapatkan informasi lebih banyak, tapi dia ternyata punya emosi yang kuat.",
  ui_story_1_8_B18_dialog_content = "Saat menghadapi kematian, dia tampak takut… Sepertinya dia… kaget? Kenapa begitu, ya?",
  ui_story_1_8_22_dialog_content = "Kita… benar-benar berhasil mengalahkan High-Level Eclipsite…",
  ui_story_1_8_23_dialog_content = "Apa kita bertambah kuat lagi tanpa kita sadari?",
  ui_story_1_8_24_dialog_content = "Sebenarnya, ini berkat PlayerName. Kalau tidak, kau bahkan tak akan tahu harus mulai dari mana.",
  ui_story_1_8_25_dialog_content = "PlayerName benar-benar luar biasa.",
  ui_story_1_8_A3_dialog_content = "Omong-omong soal itu, aku hanya pernah dengar tentang itu dari beberapa orang veteran.",
  ui_story_1_8_26_dialog_content = "Menurut legenda, saat Caelestite muncul, bisa dipastikan kemenangan akan berpihak pada kita, kapan pun, di mana pun. Kulihat itu ternyata tidak berlebihan.",
  ui_story_1_8_27_dialog_content = "Jalan keluarnya ada di depan sana. Ayo bergegas keluar dari sini!",
  ui_story_1_8_28_dialog_content = "Bagaimana kondisimu, PlayerName?",
  ui_story_1_8_B19_dialog_content = "Aku tak apa. Hanya lelah… apa ada hal lain yang perlu kuketahui?",
  ui_story_1_8_B20_dialog_content = "Maksudmu?",
  ui_story_1_8_B21_dialog_content = "Selama ini aku tinggal di dalam Colossus. Karena sekarang aku bisa melihat dunia luar…",
  ui_story_1_8_B22_dialog_content = "Apa aku harus tahan napas?",
  ui_story_1_8_B23_dialog_content = "Mungkin udara di luar beracun untukku?",
  ui_story_1_8_B24_dialog_content = "Apa aku harus memejamkan mata saja sampai aku terbiasa dengan cahaya matahari?",
  ui_story_1_8_B25_dialog_content = "Kalau dipikir-pikir lagi, sepertinya akan lebih baik kalau kututupi saja wajahku…",
  ui_story_1_8_B26_dialog_content = "Aku mulai paham apa yang dipikirkan Caelestite ini selama 17 tahun terakhir.",
  ui_story_1_8_B27_dialog_content = "Tak usah terlalu cemas. Ikuti saja aku. Dunia luar tidak seseram yang kaubayangkan.",
  ui_story_1_8_B28_dialog_content = "Sini, ulurkan tanganmu.",
  ui_story_1_8_29_dialog_content = "<color=#FFB400>Dunia baru</color>…",
  ui_story_1_8_30_dialog_content = "?!",
  ui_story_1_8_31_dialog_content = "Ada masalah, Vice.",
  ui_story_1_8_32_dialog_content = "Itu <color=#FFB400>pasukan Eclipsite</color>? Di sini? Bagaimana mungkin?",
  ui_story_1_8_33_dialog_content = "Semuanya, mundur, dan tutup jalan masuknya!",
  ui_story_1_8_34_dialog_content = "Mereka tidak ada di sana saat kita tiba tadi… Biar kuhalangi temboknya!",
  ui_story_1_8_A4_dialog_content = "Tapi, itu jalan keluar kita, Lt. Vice!",
  ui_story_1_8_36_dialog_content = "Kenapa Eclipsite-nya banyak sekali? Kita masih jauh dari baris depan!",
  ui_story_1_8_37_dialog_content = "Tetap tenang, Lt. Vice. Sepertinya mereka berhasil menyeberangi baris depan.",
  ui_story_1_8_38_dialog_content = "Masalahnya, bagaimana mereka bisa menembus pembatas Illumina?",
  ui_story_1_8_39_dialog_content = "Mungkin ada kendaraan yang membawa mereka terbang melintasinya…",
  ui_story_1_8_40_dialog_content = "Memangnya kendaraan apa yang bisa mengangkut sebegitu banyak Eclipsite sekaligus? Colossus lain? Memangnya ada?",
  ui_story_1_8_41_dialog_content = "Mungkin dugaanku berlebihan. Tapi, itu berarti kita hanya punya satu pilihan.",
  ui_story_1_8_42_dialog_content = "Kita <color=#FFB400>harus menyalakan Colossus itu</color>.",
  ui_story_1_8_44_dialog_content = "Tapi, selama ini kau belum pernah berhasil…",
  ui_story_1_8_45_dialog_content = "Memangnya kita punya pilihan lain? Satu-satunya yang bisa kita lakukan adalah mencoba sekali lagi.",
  ui_story_1_8_46_dialog_content = "Walau aku ini Caelestite, kalau aku tetap tak bisa menyalakan Colossus…",
  ui_story_1_8_47_dialog_content = "Tapi, terakhir kali mencobanya, kau 'kan pingsan. Memangnya tubuhmu sanggup?",
  ui_story_1_8_48_dialog_content = "Kepalamu tidak akan sampai meledak karena mencobanya, 'kan?",
  ui_story_1_8_49_dialog_content = "Terima kasih sudah mengkhawatirkanku, tapi aku harus mencobanya!",
  ui_story_1_8_50_dialog_content = "…",
  ui_story_1_8_51_dialog_content = "Dari raut wajahmu, Vice, jangan-jangan kau berpikir…",
  ui_story_1_8_52_dialog_content = "Yah, mestinya sih aku bisa membantu, tapi itu sebatas teori.",
  ui_story_1_8_53_dialog_content = "Apa maksudmu?",
  ui_story_1_8_54_dialog_content = "Oke, aku siap! Kalau ada masalah, kita akan berimprovisasi! Kurasa tak ada apa pun yang tak bisa kita atasi!",
  ui_story_1_8_55_dialog_content = "Sebelumnya, kau selalu berusaha sendirian. Kali ini, mungkin akan berhasil kalau kami membantumu!",
  ui_story_1_8_56_dialog_content = "Kenapa sih kau lebih percaya diri daripada aku?",
  ui_story_1_8_57_dialog_content = "Tentu saja. Aku ini orang yang selalu optimistis, PlayerName.",
  ui_story_1_8_59_dialog_content = "Menurutku, kendala hanyalah ujian bagi kita, dan kau tak harus menghadapi segalanya sendirian lagi!",
  ui_story_1_8_60_dialog_content = "Baiklah, kalau begitu, ayo kita menuju Bridge!",
  ui_story_1_8_61_dialog_content = "PlayerName…",
  ui_story_1_8_62_dialog_content = "Kali ini aku akan berhasil menyalakanmu, Soroz!",
  ui_story_1_9_1_dialog_content = "<color=#e8d9bb>Kontrol Utama… normal. Menyalakan…</color>",
  ui_story_1_9_2_dialog_content = "<color=#e8d9bb>Modul biologis… abnormal dan nyaris kelelahan.</color>",
  ui_story_1_9_3_dialog_content = "<color=#e8d9bb>Bantuan hidup… dimatikan.</color>",
  ui_story_1_9_4_dialog_content = "<color=#e8d9bb>Generator… normal. Mencoba menyalakan…</color>",
  ui_story_1_9_5_dialog_content = "<color=#e8d9bb>10%… 23%…</color>",
  ui_story_1_9_6_dialog_content = "<color=#e8d9bb>76%… 85%…</color>",
  ui_story_1_9_7_dialog_content = "<color=#e8d9bb>Gagal menyalakan. Jumlah kegagalan: 3.922.</color>",
  ui_story_1_9_8_dialog_content = "Tidak, belum berhasil.",
  ui_story_1_9_10_dialog_content = "Kenapa? Kenapa tidak berhasil? Apa masalahnya?",
  ui_story_1_9_11_dialog_content = "Anu, mungkin lagi-lagi tenagaku sudah terkuras…?",
  ui_story_1_9_12_dialog_content = "Krr krr… PlayerName kenapa…?",
  ui_story_1_9_13_dialog_content = "Kalau kau yakin, Vice, sekarang saatnya.",
  ui_story_1_9_14_dialog_content = "Yang seperti piano ini pasti panel kontrol Colossus, 'kan?",
  ui_story_1_9_15_dialog_content = "Biar kubantu kau menyalakan Colossus ini, Navigator.",
  ui_story_1_9_16_dialog_content = "Bersamaku? Kau ini Aurorian, Vice. Kau tak punya kemampuan psikis.",
  ui_story_1_9_17_dialog_content = "Tapi, aku bisa jadi kekuatanmu. Aku… bisa membantu.",
  ui_story_1_9_18_dialog_content = "…?",
  ui_story_1_9_19_dialog_content = "Percayalah padaku, PlayerName. Aku dan kau… Sebenarnya kita tidak jauh berbeda.",
  ui_story_1_9_21_dialog_content = "Ceritanya panjang. Akan kuceritakan lain kali kalau aku punya kesempatan!",
  ui_story_1_9_22_dialog_content = "Tapi, memangnya kau benar-benar tahu cara memakai panel kontrol ini?",
  ui_story_1_9_23_dialog_content = "Tentu saja! Jangan lupa, aku tahu sedikit tentang Colossus!",
  ui_story_1_9_24_dialog_content = "Lagi pula, Illumina memang sedang berusaha membangun ulang Colossus dan merekrut Navigator. Sayang sekali bahwa…",
  ui_story_1_9_25_dialog_content = "Sudahlah, mungkin kita akan bisa menyalakannya kalau kita bekerja sama!",
  ui_story_1_9_26_dialog_content = "Tapi, kalau sampai ada masalah, kepala kita berdua mungkin saja akan…|\nSeperti katamu tadi, meledak.",
  ui_story_1_9_27_dialog_content = "Ini satu-satunya pilihan yang ada. Kita harus mencobanya walau berisiko.",
  ui_story_1_9_28_dialog_content = "Baiklah, sepertinya memang kita tak bisa mundur lagi. Kemarilah dan duduk bersamaku.",
  ui_story_1_9_29_dialog_content = "Biar kutunjukkan cara \"memainkan\"nya…",
  ui_story_1_9_30_dialog_content = "<color=#e8d9bb>Generator… normal. Mencoba menyalakan…</color>",
  ui_story_1_9_B1_dialog_content = "Navigator, beri tahu saja apa yang harus kulakukan.",
  ui_story_1_9_B2_dialog_content = "Sederhana sekali. Sama seperti memainkan piano.",
  ui_story_1_9_B3_dialog_content = "Tapi di sini tidak ada partitur! Bisa kautunjukkan tuts mana yang harus kutekan?",
  ui_story_1_9_31_dialog_content = "<color=#e8d9bb>16%… 33%…</color>",
  ui_story_1_9_B4_dialog_content = "Aku bisa merasakan… energinya mengalir.",
  ui_story_1_9_B5_dialog_content = "Apa kau mengalirkan Lumina?",
  ui_story_1_9_B6_dialog_content = "Ya. Rasanya seperti sedang berbincang, walau aku tak paham bahasa Colossus.",
  ui_story_1_9_B7_dialog_content = "Bahasanya ada di tuts piano ini, Vice.",
  ui_story_1_9_32_dialog_content = "<color=#e8d9bb>89%… 97%…</color>",
  ui_story_1_9_B8_dialog_content = "Berhasil… Ini… tak bisa dipercaya.",
  ui_story_1_9_B9_dialog_content = "Navigator, apa lagunya sudah hampir selesai?",
  ui_story_1_9_B10_dialog_content = "Ya. Ayo selesaikan perintah aktivasinya, Vice.",
  ui_story_1_9_B11_dialog_content = "Not terakhirnya—",
  ui_story_1_9_33_dialog_content = "<color=#e8d9bb>100% berhasil menyalakan.</color>",
  ui_story_1_9_34_dialog_content = "Ada apa? Semua di sekitar kita menyala!",
  ui_story_1_9_35_dialog_content = "<size=45>PlayerName!!</size>",
  ui_story_1_9_36_dialog_content = "Apa Bridge-nya menyala?",
  ui_story_1_9_37_dialog_content = "<size=45>Ki-kita berhasil menyalakannya!</size>",
  ui_story_1_9_38_dialog_content = "…!",
  ui_story_1_9_40_dialog_content = "Kita berhasil, PlayerName! Aku tak percaya, kita berhasil!",
  ui_story_1_9_41_dialog_content = "Rupanya seperti inilah Bridge-nya! Terang sekali!",
  ui_story_1_9_42_dialog_content = "Indah sekali… Apa ini warna Lumina?",
  ui_story_1_9_A1_dialog_content = "Atau warna aurora?",
  ui_story_1_9_43_dialog_content = "Aku terpana… Belum pernah kulihat hal seperti ini…",
  ui_story_1_9_44_dialog_content = "Seperti itukah langit yang sesungguhnya? Sulit dilihat, tapi luar biasa menakjubkan…",
  ui_story_1_9_45_dialog_content = "Aku masih belum percaya kita berhasil! Dan baru sekali ini kekuatanku meluap begini!",
  ui_story_1_9_46_dialog_content = "Kau sudah pulih kembali, Soroz!",
  ui_story_1_9_47_dialog_content = "Benar! Kekuatan meluap melalui setiap serat dalam tubuhku, tapi aku masih butuh waktu untuk bisa terbang.",
  ui_story_1_9_48_dialog_content = "Mungkin ada musuh di dekat sini. Tetap waspada!",
  ui_story_1_9_49_dialog_content = "Pemanasan sedikit setelah teronggok sekian lama?",
  ui_story_1_9_50_dialog_content = "Betul! Sepertinya semangatmu masih besar.",
  ui_story_1_9_51_dialog_content = "Hati-hati, jangan memaksakan diri sampai kelelahan, PlayerName!",
  ui_story_1_9_52_dialog_content = "Aku merasa luar biasa, Vice. Tak ada yang salah dengan diriku!",
  ui_story_1_9_A2_dialog_content = "Aku selalu bermimpi keluar dari sini dan kembali ke dunia.",
  ui_story_1_9_A3_dialog_content = "Tapi, aku tak menyangka akan seperti ini, dan dengan ditemani sekian banyak Aurorian!",
  ui_story_1_9_53_dialog_content = "Kita berhasil mewujudkan hal yang kukira mustahil!",
  ui_story_1_9_54_dialog_content = "Aku juga sulit membayangkannya.",
  ui_story_1_9_A4_dialog_content = "Colossus yang sempurna, Aurora di ujung jemariku…",
  ui_story_1_9_55_dialog_content = "Tahu tidak, padahal kemarin aku masih seorang prajurit Illumina yang tak mampu mengalahkan satu Eclipsite sekalipun…",
  ui_story_1_9_56_dialog_content = "Pusing sekali… Mimpi itu… Lagi?",
  ui_story_1_9_58_dialog_content = "<color=#FFB400>Schummer</color>, kenapa!?",
  ui_story_1_9_59_dialog_content = "Schummer, dasar pengkhianat! Berani-beraninya kau mengkhianati kaummu sendiri demi kekuasaan?!",
  ui_story_1_9_60_dialog_content = "Pengkhianat dan pembelot hanyalah julukan yang diberikan oleh orang-orang munafik dan pengecut.",
  ui_story_1_9_61_dialog_content = "Eraveil sudah binasa, saudara-saudara Caelestite milikku. Aku akan mewujudkan nilai-nilai yang kalian sebut itu dengan caraku sendiri.",
  ui_story_1_9_62_dialog_content = "Sia-sia saja berjuang. Tak ada alasan pribadi, ini sebatas prinsip \"hanya yang kuatlah yang mampu bertahan\"…",
  ui_story_1_9_63_dialog_content = "Tidak!!!",
  ui_story_1_9_64_dialog_content = "… Mimpi itu lagi?",
  ui_story_1_9_65_dialog_content = "Tidak… lebih banyak. Soroz, apa arti semua ini? Apa maksud semua ini!?",
  ui_story_1_9_A5_dialog_content = "…",
  ui_story_1_9_66_option_content = "Tak ada waktu untuk itu sekarang.",
  ui_story_1_9_A6_option_content = "Tunggu! Ini bukan ilusi!",
  ui_story_1_9_67_option_content = "Apa yang kaututup-tutupi dariku?",
  ui_story_1_9_B12_dialog_content = "Aku… tak bisa membiarkan gambaran tak bermakna ini mengganggu pikiranku.",
  ui_story_1_9_B13_dialog_content = "Karena aku sudah berhasil mengaktifkannya, aku harus menjaga agar Colossus ini tetap stabil… Ayo, konsentrasi…",
  ui_story_1_9_B14_dialog_content = "Bagus, PlayerName. Gambaran yang kaulihat tadi… tak lama lagi kau akan tahu artinya.",
  ui_story_1_9_B15_dialog_content = "Aku sendiri pun mencari jawaban, dan kini, aku yakin kita sudah siap menemukannya.",
  ui_story_1_9_B16_dialog_content = "Lagi-lagi kau bicara penuh teka-teki, Soroz. Tapi, sudahlah… Hari ini, akhirnya aku berhasil melakukannya.",
  ui_story_1_9_B17_dialog_content = "Ya. Teruslah berusaha. Sebagai seorang Caelestite, kau bisa menjelajahi langit biru yang luas ini.",
  ui_story_1_9_B18_dialog_content = "Semua terasa begitu nyata… Terlalu nyata kalau hanya ilusi! Ini PASTI nyata, 'kan!?",
  ui_story_1_9_B19_dialog_content = "Karena itu ada di alam sadarmu, pasti itu berasal dari jejak-jejak kenyataan. Itu tak bisa dipungkiri.",
  ui_story_1_9_B20_dialog_content = "Berhentilah menghindari pertanyaanku, Soroz… Aku butuh jawaban.",
  ui_story_1_9_B21_dialog_content = "Maaf… Aku ingin menjawabmu, tapi aku tak bisa.",
  ui_story_1_9_B22_dialog_content = "Aku benar-benar tak ingat. Aku kehilangan semuanya malam itu. Satu-satunya yang kuingat hanyalah perintah untuk menjaga nyawamu.",
  ui_story_1_9_B23_dialog_content = "…",
  ui_story_1_9_B24_dialog_content = "Kenyataan atau ilusi… Sekarang, yang penting adalah perjalanan kita sudah dimulai.",
  ui_story_1_9_B25_dialog_content = "Dan kau sudah siap mencari jawabannya sendiri, 'kan?",
  ui_story_1_9_B26_dialog_content = "Jawab aku, Soroz. Apa yang kaututup-tutupi? Gambaran itu tadi nyata atau palsu!?",
  ui_story_1_9_B27_dialog_content = "Aku tak tahu, PlayerName.",
  ui_story_1_9_B28_dialog_content = "Kau pasti bercanda…",
  ui_story_1_9_B29_dialog_content = "Aku tak bohong kepadamu. Memang semua pengetahuanku waktu itu sudah sirna di kedalaman ingatan yang samar-samar.",
  ui_story_1_9_B30_dialog_content = "Aku selalu berharap bisa memberimu jawaban, bukan harapan palsu, tapi sepertinya takdir kita sudah berubah.",
  ui_story_1_9_B31_dialog_content = "Dan, dengan bantuan dari teman-teman barumu, kau sekarang siap mencari jawabannya sendiri, 'kan?",
  ui_story_1_9_B32_dialog_content = "Tapi, jawabannya… Kira-kira apa?",
  ui_story_1_9_B33_dialog_content = "Kaumku, Eraveil-ku… Kalau jawabannya adalah hal yang paling kutakutkan—",
  ui_story_1_9_B34_dialog_content = "Apa maksud semua ini?",
  ui_story_1_10_1_dialog_content = "<color=#e8d9bb>Di suatu tempat</color>",
  ui_story_1_10_2_dialog_content = "(Eclipsian) Aurorians telah menembus interior Soroz the Colossus, dan keturunan Caelestite ditemukan di dalamnya.",
  ui_story_1_10_3_dialog_content = "(Eclipsian) Unit Aurorian terlalu kuat bagi Kraken untuk menyelesaikan misi Kebenaran...",
  ui_story_1_10_A1_dialog_content = "(Eclipsian) Kraken akan menanggung dosa dan kembali ke Sisi Lain di mana Ibu memohon pengampunan.",
  ui_story_1_10_4_dialog_content = "(Eclipsian) Hiduplah <color=#FFB400>Gerhana</color>.",
  ui_story_1_10_5_dialog_content = "Apa itu kata-kata terakhir Kraken? Apa dia dikalahkan oleh Caelestite dan Aurorian itu?",
  ui_story_1_10_6_dialog_content = "Aku tak menyangka ada yang selamat dari <color=#FFB400>peristiwa itu</color>. Kukira mereka semua sudah binasa.",
  ui_story_1_10_A2_dialog_content = "Bolehkah kutangani Caelestite itu saja sendiri?",
  ui_story_1_10_7_dialog_content = "Apa membunuh <color=#FFB400>kaummu</color> sendiri membuatmu begitu bersemangat?",
  ui_story_1_10_8_dialog_content = "Kaumku sendiri? Sudah lama sekali tak kudengar istilah itu.",
  ui_story_1_10_9_dialog_content = "Saat ini ada tugas lebih penting yang harus kaujalankan. Tak usah repot-repot memikirkan gangguan sepele seperti itu.",
  ui_story_1_10_10_dialog_content = "Yang kita cari tidak ada di dalam Colossus itu. Jangan buang-buang waktumu dan waktuku. Bukankah kau sudah menunggu cukup lama?",
  ui_story_1_10_11_dialog_content = "Tentang si Caelestite itu, serahkan saja kepada <color=#FFB400>Nozard</color>. Bukankah dia kebetulan ada di dekat sana?",
  ui_story_1_10_12_dialog_content = "Kau akan mengizinkan dia menuntaskan tugas yang gagal dipenuhi Kraken?",
  ui_story_1_10_13_dialog_content = "Nozard sudah lebih dari cukup untuk membereskan Aurorian itu, dan lebih baik dia bawa mereka hidup-hidup.",
  ui_story_1_10_14_dialog_content = "Aku akan memberitahunya untuk menemui kita lagi setelah tugasnya selesai agar rencana kita tidak tertunda.",
  ui_story_1_10_A3_dialog_content = "Tak sepertimu, dia mematuhi perintah dengan sangat baik. Kau harus belajar lebih banyak darinya.",
  ui_story_1_10_15_dialog_content = "Dibandingkan rencana kita, Caelestite yang tak tahu apa-apa memang hanya hal sepele.",
  ui_story_1_10_16_dialog_content = "Tapi, kalau lagi-lagi kau menyepelekanku, akan kupatahkan lehermu.",
  ui_story_1_10_17_dialog_content = "Ha, Ha, ha, lucu sekali kau ini, <color=#FFB400>Schummer</color>.",
  ui_story_1_10_18_dialog_content = "Aku hanya bisa mengantarmu sampai sini, Nozard. Kau tahu konsekuensinya kalau gagal!",
  ui_story_1_10_19_dialog_content = "Tentu saja. Aku ini Nozard, si tak kenal takut…",
  ui_story_1_10_21_dialog_content = "Targetnya ada di depan sana. Berani-beraninya! Colossus yang berhasil kabur itu justru menampakkan diri di wilayah kita.",
  ui_story_1_10_22_dialog_content = "Banting dia ke tanah sebelum sempat lepas landas!",
  ui_story_1_10_23_dialog_content = "Lalu, cari dengan teliti sampai kau menemukan Caelestite itu untuk tuan kita!",
  ui_story_1_10_24_dialog_content = "<size=45>Dalam nama sang Bunda, maju!</size>",
  ui_story_1_10_25_dialog_content = "Mereka benar-benar mengirimkan pasukan sebanyak itu untuk menghadapi kita?",
  ui_story_1_10_26_dialog_content = "Kita memang jadi sangat terlihat setelah mengaktifkan Colossus itu. Itu sebabnya semua Eclipsite itu mengepung kita.",
  ui_story_1_10_27_dialog_content = "Mau bagaimana lagi. Jadi, apa Soroz masih butuh waktu lebih lama untuk memanaskan diri?",
  ui_story_1_10_B1_dialog_content = "…",
  ui_story_1_10_B2_dialog_content = "PlayerName?",
  ui_story_1_10_B3_dialog_content = "Hah? Maaf, aku… aku sedang memikirkan hal lain.",
  ui_story_1_10_B4_dialog_content = "… Aku ingin memastikan sesuatu—apa Soroz butuh waktu untuk memanaskan diri.",
  ui_story_1_10_28_dialog_content = "Yah, kurasa begitu. Butuh waktu hingga Soroz bisa bergerak, tapi setelah Soroz terbang, kita akan aman.",
  ui_story_1_10_30_dialog_content = "Ulur waktu untukku, PlayerName.",
  ui_story_1_10_31_dialog_content = "Aku tak sabar ingin pergi dari sini bersama kalian semua dan merasakan langit di dunia baru!",
  ui_story_1_10_32_dialog_content = "Kita harus menjaga Soroz sampai dia bisa terbang!",
  ui_story_1_10_33_dialog_content = "Baiklah. Kita berpencar dan jaga setiap bagian!",
  ui_story_1_10_34_dialog_content = "Tetaplah di Bridge, PlayerName.",
  ui_story_1_10_35_dialog_content = "Pasukan, siapkan amunisi! Saatnya menuju medan tempur!",
  ui_story_1_10_A4_dialog_content = "Siapkan senjata dan ulur waktu agar Soroz bisa memanaskan diri.",
  ui_story_1_10_36_dialog_content = "Jayalah Illumina!",
  ui_story_1_10_37_dialog_content = "Jayalah Illumina!",
  ui_story_1_10_38_dialog_content = "Jaya apa?",
  ui_story_1_14_1_dialog_content = "(Eclipsian) Colossus akan lepas landas! Hancurkan dia dan Aurorian segera bersembunyi di dalamnya!",
  ui_story_1_14_2_dialog_content = "(Eclipsian) Kami telah menyusup ke banyak area di dalam Colossus, tetapi bertemu dengan perlawanan yang kuat di dekat jembatan. Pasukan kami menderita kerugian besar.",
  ui_story_1_14_3_dialog_content = "(Eclipsian) Jadi? Apakah kita takut mati?",
  ui_story_1_14_4_dialog_content = "(Eclipsian) Tidak pernah!",
  ui_story_1_14_5_dialog_content = "(Eclipsian) Lalu pertajam cakarmu dan jangan menahan diri!",
  ui_story_1_14_A1_dialog_content = "(Eclipsian) Bahkan jika Anda mati, kuliti sebanyak yang Anda bisa saat keluar!",
  ui_story_1_14_6_dialog_content = "(Eclipsian) Bawa saya ke sana. Saya akan melihat betapa sulitnya para Aurorian ini untuk diri saya sendiri!",
  ui_story_1_14_7_dialog_content = "<color=#e8d9bb>(Di dalam Colossus)</color>",
  ui_story_1_14_8_dialog_content = "Gelombang berikutnya akan segera menyerang. Semuanya, istirahat sebentar. Aku butuh laporan jumlah amunisi dan korban.",
  ui_story_1_14_9_dialog_content = "Tinggal 11 tembakan. Ada 6 petarung yang tewas, 4 cedera ringan, 2…",
  ui_story_1_14_10_dialog_content = "Oke, cukup.",
  ui_story_1_14_11_dialog_content = "Kita harus mundur, Kapten…",
  ui_story_1_14_12_dialog_content = "Tidak bisa! Vice dan skuadnya sedang menjaga area paling penting. Kita harus membendung serangan para Eclipsite ini di luar!",
  ui_story_1_14_13_dialog_content = "Kita semua bertarung agar bisa bertahan hidup dan ini sama beratnya untuk kita semua! Jadi, singkirkan pikiran itu, dan masuk ke barisan!",
  ui_story_1_14_14_dialog_content = "Kobarkan semangat kalian! Kalau kehabisan amunisi, gunakan pedang kalian!",
  ui_story_1_15_1_dialog_content = "Kau, jangan berpikir untuk kabur!",
  ui_story_1_15_2_dialog_content = "Bagus! Mestinya itu bisa menyingkirkan mereka dari Bridge!",
  ui_story_1_15_3_dialog_content = "Kau makin lihai mengoordinasi kami, PlayerName!",
  ui_story_1_15_4_dialog_content = "Jelas bahwa pikiran dan kemampuanku meningkat banyak hari ini.",
  ui_story_1_15_5_dialog_content = "Aku penasaran, bagaimana perkembangan pertarungannya di area lain?",
  ui_story_1_15_6_dialog_content = "Kau masih butuh berapa lama lagi, Soroz?",
  ui_story_1_15_7_dialog_content = [[
Generatornya menyala. Pijakkan kaki kalian kuat-kuat.|
<size=45>Melesat ke langit!</size>]],
  ui_story_1_15_8_dialog_content = "Kita terbang?!",
  ui_story_1_15_9_dialog_content = "Waow, aku hampir saja jatuh! Kita tinggi sekali!! Apa kita terbang?!",
  ui_story_1_15_10_dialog_content = "Semuanya, cari apa pun untuk pegangan!",
  ui_story_1_15_11_dialog_content = "Itu rambutku, Vice!",
  ui_story_1_15_A1_dialog_content = "Oh, langit! Sudah lama sekali… Aku masih ingat terakhir kali aku melihatnya, saat malam berdarah itu…",
  ui_story_1_15_A2_dialog_content = "Aku ingin terus menambah kecepatan, PlayerName!",
  ui_story_1_15_A3_dialog_content = "Jangan sungkan-sungkan, Soroz! Silakan, membubunglah!",
  ui_story_1_15_12_dialog_content = "Ayo terbang dengan kecepatan penuh! Kita bahkan berhasil menyingkirkan para Eclipsite itu!",
  ui_story_1_15_13_dialog_content = "Dengan senang hati! Ayo membubung melintasi langit luas sekali lagi!",
  ui_story_1_15_14_dialog_content = "Getaran apa ini, Vice?",
  ui_story_1_15_15_dialog_content = "Aku baru saja mau memanggilmu! Kita melayang di udara!",
  ui_story_1_15_16_dialog_content = "Sungguh? Menakjubkan! Tadi aku khawatir… mungkin sudah terlambat…",
  ui_story_1_15_17_dialog_content = "Terlambat? Apa yang terjadi? Kalian baik-baik saja?",
  ui_story_1_15_18_dialog_content = "Ada monster raksasa menerjang masuk dan kami tidak bisa menghentikannya. Kami sudah kehilangan banyak orang…",
  ui_story_1_15_19_dialog_content = "Dia langsung menuju Bridge. Jelas, dia High-Level Eclipsite… Maaf…",
  ui_story_1_15_20_dialog_content = "Musuh yang lebih kuat? Semuanya, tetap siaga, ini belum berakhir!",
  ui_story_1_15_21_dialog_content = "Brr… Kenapa suhunya tiba-tiba turun? Dingin sekali…",
  ui_story_1_15_22_dialog_content = "Bukan suhunya, Dove. Ini hawa Darkflow… Semuanya, musuh sudah sampai sini.",
  ui_story_1_15_23_dialog_content = "<color=#e8d9bb>Hawa dingin seram tiba-tiba saja memenuhi sekitar…</color>",
  ui_story_1_15_25_dialog_content = "Kalian orang-orang tolol ternyata berhasil membuat peti mati ini terbang. Tak apa, kini saatnya kalian mati!",
  ui_story_1_15_26_dialog_content = "High-Level Eclipsite lagi?",
  ui_story_1_15_27_dialog_content = "Aku punya nama, Aurorian. Kau bisa panggil aku <color=#FFB400>Nozard</color>. Sang Bunda sendiri yang memberikan nama itu kepadaku.",
  ui_story_1_15_28_dialog_content = "Ingat namaku, karena itulah yang akan menuntunmu menuju Truth di Other Side!",
  ui_story_1_15_29_dialog_content = "Eclipsite ini kok bisa bicara? \"Bunda\", \"Truth\", kau ini omong kosong apa, sih?",
  ui_story_1_15_30_dialog_content = "Tak usah dipikirkan, PlayerName! Hanya segelintir Eclipsite saja yang bisa bahasa Universese, jadi mungkin yang satu ini termasuk salah satunya!",
  ui_story_1_15_31_dialog_content = "Cih! Kami bahkan belajar bahasa Universese untuk memberikan pencerahan pada kaum Aurorian, tapi rupanya sia-sia saja. Hama tetap saja hama…",
  ui_story_1_15_32_dialog_content = "Sudah cukup salamku untuk orang-orang yang sebentar lagi akan mati. Sekarang…",
  ui_story_1_15_33_dialog_content = "Saatnya kalian mati.",
  ui_story_1_15_34_option_content = "Maksudmu pasti dirimu sendiri!",
  ui_story_1_15_35_option_content = "Semuanya, bersiap untuk bertarung!",
  ui_story_1_15_36_dialog_content = "Berani-beraninya kau melukaiku! Cukup!",
  ui_story_1_15_37_dialog_content = "Sebenarnya aku berniat membiarkan kalian hidup, tapi sulit menundukkan hama tanpa harus membunuhnya!",
  ui_story_1_15_38_dialog_content = "Kau memberiku tugas berat, <color=#FFB400>Master Schummer</color>.",
  ui_story_1_15_39_dialog_content = "<color=#FFB400>Schummer</color>!? Itu nama yang kudengar dalam mimpiku! Dari mana kaudengar nama itu dan siapa dia?",
  ui_story_1_15_40_dialog_content = "Rupanya kau tahu sedikit tentang apa yang dulu terjadi, Caelestite… Tapi, memangnya kenapa?",
  ui_story_1_15_B1_dialog_content = "Semua orang dari kaummu tewas di tangan kami. Apa kau benar-benar puas hidup sendirian dalam kehampaan ini?",
  ui_story_1_15_B2_dialog_content = "Apa… katamu?",
  ui_story_1_15_B3_dialog_content = "Pertanyaan aneh. Aku yakin kau tadi mendengarku dengan jelas.",
  ui_story_1_15_B4_dialog_content = "Kaummu, mereka <color=#FFB400>semua tewas</color>.",
  ui_story_1_15_B5_dialog_content = "Eraveil sudah tak ada lagi.",
  ui_story_1_15_B6_dialog_content = "Lautan api dan jeritan panik… Mayat-mayat diremukkan, satu per satu…|\nLalu dibuang.",
  ui_story_1_15_B7_dialog_content = "Tidak… Tidak… Tak mungkin.",
  ui_story_1_15_B8_dialog_content = "Mustahil…",
  ui_story_1_15_B9_dialog_content = "Cukup, Eclipsite! Memangnya kau ini tahu apa!?",
  ui_story_1_15_B10_dialog_content = "Aku ada di sana saat itu. <color=#FFB400>Kami</color> semua ada di sana… Memangnya siapa yang mau melewatkan peristiwa sebesar itu?",
  ui_story_1_15_B11_dialog_content = "Sama seperti suatu hari nanti kami akan menembus pertahanan Aurorian dan menghadiahi kalian dengan kebinasaan.",
  ui_story_1_15_41_dialog_content = "PlayerName, jangan percaya pada Eclipsite itu!",
  ui_story_1_15_42_dialog_content = "Bukan masalah kau percaya padaku atau tidak. Toh tetap saja kalian semua akan mati.",
  ui_story_1_15_44_dialog_content = "Kau tak akan berhasil!",
  ui_story_1_15_46_dialog_content = "Bodoh! Padahal kalian bisa saja tetap hidup, tapi kalian malah memilih mati!",
  ui_story_1_15_47_dialog_content = "Argh!",
  ui_story_1_15_48_dialog_content = "Jadi, rencana cemerlangmu adalah menyerangku asal-asalan dan tergencet di bawah kakiku?",
  ui_story_1_15_49_dialog_content = "Ya, benar, karena niatku adalah meletakkan <color=#FFB400>bom</color> ini, tolol!",
  ui_story_1_15_50_dialog_content = "Apa-apaan kau…!",
  ui_story_1_15_53_dialog_content = "<size=45>Sampai jumpa di neraka, moron.</size>",
  ui_story_1_15_54_dialog_content = "PlayerName! Ada lubang di dekatmu! Hati-hati saat maju!",
  ui_story_1_15_55_dialog_content = "Tekanannya! Aku tak bisa bertahan lagi!",
  ui_story_1_15_56_dialog_content = "Tunggu—!!",
  ui_story_1_15_B13_dialog_content = "Kapten!",
  ui_story_1_15_B14_dialog_content = "Jangan bergerak! Pegang tanganku sebelum kau terisap ke sana!",
  ui_story_1_15_B15_dialog_content = "Kenapa jadi begini? Tadi kita nyaris berhasil!",
  ui_story_1_15_57_dialog_content = "Ledakan? Jangan-jangan, apa Aurorian itu…?",
  ui_story_1_15_A4_dialog_content = "Abu yang tadi itu… mungkinkah…?",
  ui_story_1_15_58_dialog_content = "Tenanglah, PlayerName! Pikiranmu sedang kacau…",
  ui_story_1_15_A5_dialog_content = "Dan dalam ingatanku… Mayat-mayat kaumku…",
  ui_story_1_15_A6_dialog_content = "Semuanya tewas… <color=#FFB400>Mereka semua tewas?</color>? Bagaimana dengan di luar Eraveil, dan di luar kontinen? Apa aku sungguh satu-satunya <color=#FFB400>Caelestite yang tersisa</color>?",
  ui_story_1_15_A7_dialog_content = "Detak jantungmu bertambah cepat! Hati-hati, jangan memaksakan dirimu lagi!",
  ui_story_1_15_B12_dialog_content = "Tidak… Tidak seperti ini… Harusnya tidak seperti ini. Aku hampir tak bisa…",
  ui_story_1_15_A8_dialog_content = "<size=45>Jangan mengusikku lagi!</size>",
  ui_story_1_15_59_dialog_content = "Colossus itu menambah kecepatan! Aku tak bisa bertahan lagi…",
  ui_story_1_15_60_dialog_content = "Apa yang kaulakukan, Caelestite? Peganganku melemah…",
  ui_story_1_15_61_dialog_content = "<size=45>Tak mungkin…</size>",
  ui_story_1_15_62_dialog_content = "<size=45>Navigator, tundukkan kepalamu!</size>",
  ui_story_1_15_63_dialog_content = "Raawr!",
  ui_story_2_1_A1_dialog_content = "\"Colossus itu akhirnya terbang.\"",
  ui_story_2_1_A2_dialog_content = "\"Tadi aku sempat mengira aku akan terperangkap di bawah tanah selamanya…\"",
  ui_story_2_1_A3_dialog_content = "\"Tapi, begitu aku berhasil keluar…\"",
  ui_story_2_1_A4_dialog_content = "\"Semua makna dalam hidupku sirna…\"",
  ui_story_2_1_A5_dialog_content = "\"Karena kaumku… kaum Caelestite telah binasa.\"",
  ui_story_2_1_1_dialog_content = "Apa kau sedang menulis jurnal?",
  ui_story_2_1_3_dialog_content = "Yah, memang tidak ada kegiatan lain yang bisa kulakukan saat sendirian.",
  ui_story_2_1_4_dialog_content = "Menulis jurnal membantuku mengingat waktu, walau sebenarnya tidak terlalu bermanfaat.",
  ui_story_2_1_5_dialog_content = "Itu kebiasaan bagus. Kadang kau terlalu keras pada dirimu sendiri, PlayerName.",
  ui_story_2_1_6_dialog_content = "Bagaimana situasinya?",
  ui_story_2_1_B26_dialog_content = "Untuk sementara ini, kita aman dari bahaya. Hampir semua pasukan kita yang terluka sudah dimasukkan ke rumah sakit.",
  ui_story_2_1_B27_dialog_content = "Prajurit yang tadi… mengorbankan dirinya…",
  ui_story_2_1_B28_dialog_content = "…",
  ui_story_2_1_B29_dialog_content = "Kita tak bisa mengambil jasadnya, tapi akan kukumpulkan barang-barang pribadinya dan membuatkan tugu peringatan untuknya.",
  ui_story_2_1_B30_dialog_content = "…",
  ui_story_2_1_B31_dialog_content = "… Apa ini pertama kalinya kau menyaksikan kematian?",
  ui_story_2_1_B32_dialog_content = "Tidak.",
  ui_story_2_1_B33_dialog_content = "Berapa kali pun aku melihatnya, aku tetap tak akan terbiasa.",
  ui_story_2_1_B34_dialog_content = "Bagaimana dengan… keluarganya?",
  ui_story_2_1_B35_dialog_content = "Jangan khawatir, Illumina Federation akan mengurus mereka.",
  ui_story_2_1_B37_dialog_content = "Kami akan mengenang setiap pahlawan yang telah mengorbankan nyawa mereka demi Illumina.",
  ui_story_2_1_B38_dialog_content = "Maaf, PlayerName.",
  ui_story_2_1_B39_dialog_content = "Maaf kenapa?",
  ui_story_2_1_B40_dialog_content = "Aku benar-benar minta maaf, dari lubuk hati terdalam, atas segala yang terjadi hari ini…",
  ui_story_2_1_B41_dialog_content = "Tapi, kita masih hidup, dan satu-satunya yang bisa kita lakukan sekarang adalah terus berusaha agar pengorbanannya tidak sia-sia.",
  ui_story_2_1_F1_dialog_content = "…",
  ui_story_2_1_7_dialog_content = "Jadi, apa yang akan kaulakukan sekarang?",
  ui_story_2_1_8_dialog_content = "… Entahlah.",
  ui_story_2_1_9_dialog_content = "Bagaimana kalau kau ikut aku kembali ke Illumina?",
  ui_story_2_1_10_dialog_content = "Kau tadi dengar Nozard bilang apa, 'kan?",
  ui_story_2_1_A8_dialog_content = "Aku dengar. Tapi, itu hanya cerita dari satu sisi.",
  ui_story_2_1_11_dialog_content = "Semua orang dari kaumku sudah tewas. Eraveil sudah tak ada lagi.",
  ui_story_2_1_13_dialog_content = "…",
  ui_story_2_1_A9_dialog_content = "Kau masih punya kampung halaman dan orang-orang yang menantimu, sedangkan aku…",
  ui_story_2_1_14_dialog_content = "Jangan berpikir begitu, PlayerName…",
  ui_story_2_1_15_dialog_content = "Aku yakin masih ada orang sepertimu yang berhasil selamat!",
  ui_story_2_1_B1_dialog_content = "…",
  ui_story_2_1_B2_dialog_content = "Aku bisa membantumu mencari mereka!",
  ui_story_2_1_B3_dialog_content = "Maaf, Vice. Aku hanya…",
  ui_story_2_1_B4_dialog_content = "Tak apa, aku paham.",
  ui_story_2_1_B5_dialog_content = "Aku menghabiskan 17 tahun di bawah tanah, memikirkan Eraveil setiap hari.",
  ui_story_2_1_B6_dialog_content = "Dan kini yang kudapati adalah bahwa… semuanya sudah lama musnah? Mana mungkin aku bisa menerima kenyataan itu? Aku tak bisa!",
  ui_story_2_1_B7_dialog_content = "Kalau begitu, jangan, PlayerName.",
  ui_story_2_1_B8_dialog_content = "Aku ingin tahu apa yang sebenarnya terjadi 17 tahun lalu!",
  ui_story_2_1_B9_dialog_content = "Tentu, kita bisa menjelajahi seluruh kontinen ini untuk mencari kebenarannya!",
  ui_story_2_1_B10_dialog_content = "Tapi, sebelum itu, kau perlu istirahat. Ikutlah kembali ke Illumina bersamaku.",
  ui_story_2_1_A10_option_content = "Baiklah kalau begitu. Aku akan pergi denganmu.",
  ui_story_2_1_A11_option_content = "Tidak, aku harus menempuh jalanku sendiri.",
  ui_story_2_1_A12_dialog_content = "Kau benar, Vice.",
  ui_story_2_1_A13_dialog_content = "Toh, aku tak punya tujuan lain.",
  ui_story_2_1_A14_dialog_content = "Bergembiralah. Percayalah, kau akan suka Illumina!",
  ui_story_2_1_B11_dialog_content = "<color=#FFB400>Schummer</color>, kaubilang? Nama yang aneh.",
  ui_story_2_1_B12_dialog_content = "Aku tak bisa melenyapkan wajah itu dari pikiranku… Kurasa, hanya itu yang bisa kulakukan untuk saat ini.",
  ui_story_2_1_B13_dialog_content = "Jadi, pertama-tama, kau harus janji kepadaku bahwa kau akan melindungi dirimu sendiri dan Colossus itu.",
  ui_story_2_1_B14_dialog_content = "Setelah kau menenangkan pikiran dan memperbaiki Soroz, aku akan menemanimu sepanjang petualanganmu.",
  ui_story_2_1_A15_dialog_content = "Kenapa?",
  ui_story_2_1_A16_dialog_content = "Yah, karena Illumina Federation…",
  ui_story_2_1_A17_dialog_content = "Maksudku, kenapa kau sangat berniat membantuku dan menjadi temanku?",
  ui_story_2_1_A18_dialog_content = "Apa masih perlu kujelaskan? Kau sudah menyelamatkan nyawaku, ingat, 'kan?",
  ui_story_2_1_A19_dialog_content = "Itu, dan kemampuanmu sangat berarti bagi kaum Aurorian…",
  ui_story_2_1_A20_dialog_content = "Maksudmu program Colossus Navigator itu, 'kan?",
  ui_story_2_1_A21_dialog_content = "Program itu disebut Pembangunan Ulang Colossus dan Pengembangan Navigator!",
  ui_story_2_1_A22_dialog_content = "Sebenarnya, aku juga… Anu, itu tak penting untuk saat ini!",
  ui_story_2_1_A23_dialog_content = "Walaupun aku tak tahu kenapa kau melakukan ini…",
  ui_story_2_1_F2_dialog_content = "Aku percaya padamu, Vice.",
  ui_story_2_1_A24_dialog_content = "Terima kasih, PlayerName.",
  ui_story_2_1_A25_dialog_content = "Baiklah, ayo cari Illumina Undercity terdekat sesegera mungkin! Kita harus istirahat dan berkumpul lagi!",
  ui_story_2_1_A26_dialog_content = "Aku sudah berusaha bertahun-tahun.",
  ui_story_2_1_A28_dialog_content = "Setiap hari, aku mencoba menyalakan Colossus itu, tapi hasilnya adalah aku justru pingsan setiap kali mencobanya.",
  ui_story_2_1_B15_dialog_content = "Setiap hari, aku mempelajari informasi yang tersimpan di dalam sistem Soroz. Aku tak tahu apa informasi itu bisa membantuku sekarang.",
  ui_story_2_1_B16_dialog_content = "Setiap hari, aku mendambakan bisa melihat dunia luar dan kembali ke Eraveil suatu hari nanti.",
  ui_story_2_1_B17_dialog_content = "Aku tahu kau sudah berusaha sangat keras, PlayerName.",
  ui_story_2_1_B19_dialog_content = "Aku yakin ada jalan yang harus kutempuh sendiri.",
  ui_story_2_1_B20_dialog_content = "Tapi, kau mau pergi ke mana?",
  ui_story_2_1_B21_dialog_content = "…",
  ui_story_2_1_B22_dialog_content = "Pulang, ke Eraveil.",
  ui_story_2_1_B23_dialog_content = "Dan aku ingin mencari <color=#FFB400>Schummer</color>.",
  ui_story_2_1_A29_dialog_content = "Terlalu berbahaya kalau kau melakukannya sendirian, PlayerName!",
  ui_story_2_1_A30_dialog_content = "Aku tahu, tapi aku ingin tahu kebenarannya. Aku ingin pulang.",
  ui_story_2_1_A31_dialog_content = "Kau dan Soroz baru saja kembali ke permukaan dan sudah melalui sekian banyak kendala. Kalian berdua benar-benar butuh istirahat dulu.",
  ui_story_2_1_A32_dialog_content = "Setelah kalian berdua pulih, aku bisa membantumu mencari…",
  ui_story_2_1_A33_dialog_content = "Kenapa kau mau membantuku?",
  ui_story_2_1_A34_dialog_content = "Apa masih perlu kujelaskan? Kau sudah menyelamatkan nyawaku, ingat, 'kan?",
  ui_story_2_1_A35_dialog_content = "Itu… dan kemampuanmu mungkin saja akan sangat bermanfaat bagi kaum Aurorian.",
  ui_story_2_1_A36_dialog_content = "…",
  ui_story_2_1_A37_dialog_content = "Kita bisa bertarung bersama melawan musuh yang sama, seperti kaum Caelestite dan Aurorian pendahulu kita!",
  ui_story_2_1_A38_dialog_content = "Tapi, sebelum itu, kita harus bergegas dan menuju Illumina Undercity terdekat untuk beristirahat dan berkumpul kembali…",
  ui_story_2_1_19_dialog_content = "Oh! Ada apa?",
  ui_story_2_1_20_dialog_content = "Apa yang terjadi, Soroz!?",
  ui_story_2_1_21_dialog_content = "Sistem navigasinya rusak di beberapa area dan saat ini tidak bisa diperbaiki.",
  ui_story_2_1_22_dialog_content = "Beginilah jadinya kalau mengabaikan pemeliharaan selama 17 tahun. Sepertinya kita harus kembali mendarat.",
  ui_story_2_1_23_dialog_content = "Sepertinya aku hanya bisa membawamu sampai sini, PlayerName.",
  ui_story_2_1_24_dialog_content = "…",
  ui_story_2_1_25_dialog_content = "Apa pun yang terjadi, lindungi dirimu sendiri dan teman-temanmu!",
  ui_story_2_1_26_dialog_content = "Aku percaya padamu… Kau akan jadi… kuat…",
  ui_story_2_1_A43_dialog_content = "Soroz! Soroz!",
  ui_story_2_1_27_dialog_content = "PlayerName!!!",
  ui_story_2_1_28_dialog_content = "Bersiap menghadapi benturan!",
  ui_story_2_1_29_dialog_content = "Aku baru saja merasakan gelombang Lumina yang kuat.",
  ui_story_2_1_30_dialog_content = "Master Schummer, semuanya masih bisa kukendalikan.",
  ui_story_2_1_A44_dialog_content = "Sudah gagal dan terhempas dari langit, masih saja kau bisa omong besar. Lebih baik kau tak berjanji kalau tak bisa kautepati.",
  ui_story_2_1_A45_dialog_content = "…",
  ui_story_2_1_X1_dialog_content = "Harus kuakui, kau lebih tangguh daripada Kraken. Tapi, kalau tak mampu menjalankan perintah kita…",
  ui_story_2_1_X2_dialog_content = "Maka, kau tak ada gunanya, Nozard.",
  ui_story_2_1_31_dialog_content = "Colossus itu tak bisa selamanya melindungi mereka. Perlawanan mereka sia-sia saja.",
  ui_story_2_1_32_dialog_content = "Tak lama lagi, aku akan berhasil sesuai harapanmu.",
  ui_story_2_1_33_dialog_content = "Bersyukurlah, kau masih diberi kesempatan kedua. Sebaiknya segera kautuntaskan, sebelum kesabaranku habis.",
  ui_story_2_1_35_dialog_content = "Siap, Master.",
  ui_story_2_1_36_dialog_content = "(Eclipsian) Colossus... jatuh... hutan belantara... di barat...",
  ui_story_2_1_37_dialog_content = "(Eclipsian) Barat. Panggil <color=#FFB400> Umbrahulk</color>.",
  ui_story_2_1_38_dialog_content = "(Eclipsian) Atas perintah Anda.",
  ui_story_2_1_39_dialog_content = "(Eclipsian) Kejar mereka dan bunuh mereka... Aku akan segera bergabung denganmu!",
  ui_story_2_1_40_dialog_content = "(Eclipsian) Mengerti! Eclipsites, menyerang!",
  ui_story_2_2_2_dialog_content = "Aduh… Hah?",
  ui_story_2_2_3_dialog_content = "Tolong menjauhlah dariku, Vice…",
  ui_story_2_2_A1_dialog_content = "Hah? Oh, maaf… Kau baik-baik saja?",
  ui_story_2_2_A2_dialog_content = "Setidaknya aku masih hidup…",
  ui_story_2_2_4_dialog_content = "Kita dikepung Eclipsite?! Secepat ini?",
  ui_story_2_2_5_dialog_content = "PlayerName, beri aku perintah!",
  ui_story_2_2_6_dialog_content = "<color=#e8d9bb>Suara keras saat kita jatuh tadi menarik perhatian sejumlah Eclipsite.</color>",
  ui_story_2_3_1_dialog_content = "Bagaimana situasi saat ini?",
  ui_story_2_3_2_dialog_content = "Kami mendeteksi ada kawanan Eclipsite mendekat, Lt. Vice, tapi kita kehabisan suplai untuk bertarung.",
  ui_story_2_3_3_dialog_content = "Di mana lokasi Undercity terdekat?",
  ui_story_2_3_A1_dialog_content = "Undercity 28 tak jauh dari sini. Kita bisa berlindung di sana.",
  ui_story_2_3_A2_dialog_content = "Siap menjalankan perintahmu, Lt. Vice!",
  ui_story_2_3_4_dialog_content = "Semua pasukan, menuju Undercity 28 dengan kecepatan penuh!",
  ui_story_2_3_6_dialog_content = "Ayo, PlayerName!",
  ui_story_2_3_7_dialog_content = "Tak usah khawatirkan aku. Sana, pergilah.",
  ui_story_2_3_8_dialog_content = "PlayerName?!",
  ui_story_2_3_A3_dialog_content = "Kau harus pergi sekarang, sebelum terlambat.",
  ui_story_2_3_A4_dialog_content = "Kau tidak ikut dengan kami?",
  ui_story_2_3_9_dialog_content = "Kondisi Soroz sangat buruk, aku tak bisa meninggalkannya.",
  ui_story_2_3_10_dialog_content = "Aku bisa bertahan hingga 17 tahun berkat Soroz. Soroz adalah satu-satunya \"keluarga\" yang kumiliki.",
  ui_story_2_3_A5_dialog_content = "…",
  ui_story_2_3_11_dialog_content = "Kalau semua yang dibilang Nozard memang benar…",
  ui_story_2_3_12_dialog_content = "Apa pun yang terjadi, aku tak akan pernah meninggalkan Soroz lagi.",
  ui_story_2_3_13_dialog_content = "Memangnya kau bisa melawan semua Eclipsite di sini sendirian?",
  ui_story_2_3_A6_dialog_content = "Mereka mengejarku, 'kan? Akan lebih baik bagi semua orang kalau aku tetap di sini saja.",
  ui_story_2_3_14_dialog_content = "Kau…!!",
  ui_story_2_3_15_dialog_content = "Aku paham. Prajurit, bawa semuanya ke Undercity!",
  ui_story_2_3_A7_dialog_content = "Bagaimana denganmu, Lt. Vice…",
  ui_story_2_3_A8_dialog_content = "Jangan buang-buang waktu lagi, pergilah sekarang!",
  ui_story_2_3_A9_dialog_content = "Ya!",
  ui_story_2_3_A10_dialog_content = "Kau sudah cukup banyak membantuku, Vice. Kau harus pergi bersama teman-temanmu.",
  ui_story_2_3_16_dialog_content = "Kau juga temanku. Aku tak bisa membiarkanmu mati di sini!",
  ui_story_2_3_17_dialog_content = "Dalam situasi ini, kita berdua akan mati kalau kau tak segera pergi.",
  ui_story_2_3_18_dialog_content = "PlayerName…!!",
  ui_story_2_3_19_dialog_content = "<anim type=Shake><size=45>*Meraung*</size></anim>",
  ui_story_2_3_B3_dialog_content = "Vice!",
  ui_story_2_3_B4_dialog_content = "K-kembali! Cari tempat aman dulu untuk sembunyi!",
  ui_story_2_3_B5_dialog_content = "Mereka berkumpul begitu cepat…",
  ui_story_2_3_B6_option_content = "Mulai telepati.",
  ui_story_2_3_B7_dialog_content = "Wooga—!!!",
  ui_story_2_3_B8_dialog_content = "Aku tak bisa meninggalkanmu!",
  ui_story_2_3_B9_dialog_content = "Vice…",
  ui_story_2_3_B10_dialog_content = "Raawr!",
  ui_story_2_3_22_dialog_content = "Ahhh—!",
  ui_story_2_3_A11_dialog_content = "Sakit sekali! Tak bisa fokus…",
  ui_story_2_3_F1_dialog_content = "Bertahanlah, PlayerName! Aku akan segera ke sana!",
  ui_story_2_3_B11_dialog_content = "<anim type=Shake><size=45>*Meraung*</size></anim>",
  ui_story_2_3_B12_dialog_content = "<color=#e8d9bb>Tak punya waktu untuk bereaksi, sejumlah Eclipsite serentak menyerang Vice sekali lagi—</color>",
  ui_story_2_3_B13_dialog_content = "Argh—",
  ui_story_2_3_B14_dialog_content = "Lari! Sembunyi… Ayo…",
  ui_story_2_3_B15_dialog_content = "Vice!?",
  ui_story_2_3_24_option_content = "Mulai telepati.",
  ui_story_2_3_25_dialog_content = "Ya ampun, dia pingsan…",
  ui_story_2_3_26_dialog_content = "Bertarung… Aku harus bertarung… Aku tak bisa duduk diam saja di sini…",
  ui_story_2_3_27_dialog_content = "<color=#e8d9bb>Para Eclipsite melewati Vice yang pingsan dan mengepungmu…</color>",
  ui_story_2_3_28_dialog_content = "Hei, hei, hei, mempertaruhkan nyawamu tak akan memecahkan masalah. Membunuh Eclipsite adalah suatu bentuk seni.",
  ui_story_2_3_29_dialog_content = "Saatnya bermain!",
  ui_story_2_3_30_dialog_content = "<size=45>Maju!! Maju!!</size>",
  ui_story_2_3_31_dialog_content = "Siap, Bos!",
  ui_story_2_3_32_dialog_content = "Waspadai ledakan!",
  ui_story_2_3_33_dialog_content = "Ayo berpesta!",
  ui_story_2_3_34_dialog_content = "Minggir, kau menghalangi jalan!",
  ui_story_2_3_36_dialog_content = "Siapa kau? Apa maumu?",
  ui_story_2_3_37_dialog_content = "Bukannya sudah jelas? Kami mau merampokmu.",
  ui_story_2_3_38_dialog_content = "Kami sudah menyelamatkan nyawamu, jadi sekarang berikan semua barang berhargamu, cepat!",
  ui_story_2_3_F2_dialog_content = "Hahahahaha!",
  ui_story_2_3_39_dialog_content = "Izinkan aku memperkenalkan diri, namaku <color=#FFB400>Sinsa</color>, pemimpin <color=#FFB400>Rediesel Wrench</color>.",
  ui_story_2_3_40_dialog_content = "Yang suka berpose ini <color=#FFB400>Regina</color>.",
  ui_story_2_3_41_dialog_content = "Yang main-main dengan bom itu <color=#FFB400>Joanie Boom</color>.",
  ui_story_2_3_42_dialog_content = "Mereka tangan kananku.",
  ui_story_2_3_43_dialog_content = "Rediesel Wrench? Merampok kami…? Kalian sedang apa? Jangan berani-berani menyentuh Colossus itu!",
  ui_story_2_3_44_dialog_content = "Maksudmu benda besar ini? Kenapa kami tidak bisa masuk, sih? Biar kulubangi saja benda itu!",
  ui_story_2_3_45_dialog_content = "Ayo! Saatnya memasukkan muatan!",
  ui_story_2_3_46_dialog_content = "Asyik! Hidup Joanie Boom!",
  ui_story_2_3_47_dialog_content = "Eh, ada Colossus! Ini hari keberuntunganku!",
  ui_story_2_3_A12_dialog_content = "Bongkar saja dia dan angkut pulang!",
  ui_story_2_3_48_dialog_content = "Kesempatan seperti ini tak boleh dilewatkan!",
  ui_story_2_3_49_dialog_content = "Jangan hancurkan Soro—Colossus itu! Ada orang yang memakai bantuan hidupnya…",
  ui_story_2_3_50_dialog_content = "Temanku, Vice, terluka dan dia butuh itu!",
  ui_story_2_3_51_dialog_content = "Sepertinya gadis muda ini dihajar cukup keras.",
  ui_story_2_3_52_dialog_content = "Seragam ini? Bukankah ini seragam Illumina?",
  ui_story_2_3_53_dialog_content = "Mungkin kau bisa menduga, kami tidak begitu rukun dengan para Officer ini…",
  ui_story_2_3_54_dialog_content = "Lagi pula, Colossus ini sekarang jadi milik kami. Untuk menyelamatkan gadis ini, kau harus menukarnya dengan sesuatu.",
  ui_story_2_3_55_dialog_content = "Dari penampilanmu, sepertinya kau bukan orang kaya. Sudah berapa lama kau tidak mencuci gombal yang kaukenakan itu?",
  ui_story_2_3_56_option_content = "Tapi AKU kaya. Bahkan sangat kaya!",
  ui_story_2_3_57_option_content = "Jangan main-main denganku, Aurorian!",
  ui_story_2_3_58_dialog_content = "Kuberi tahu, ya, benda paling berharga di sini adalah Colossus ini. Kau pasti baru sekali ini melihat Colossus, 'kan?",
  ui_story_2_3_59_dialog_content = "Eh, enak saja! Tapi, dibandingkan dengan yang ada di pangkalan kami, yang ini masih lumayan utuh…",
  ui_story_2_3_60_dialog_content = "Benar, kalau kau terus membongkarnya, ia tak akan lagi berharga.",
  ui_story_2_3_61_dialog_content = "Cih. Itu baru masalah. Padahal kukira kali ini aku bisa membongkarnya sepuasku! Sekarang bagaimana nih, Bos?",
  ui_story_2_3_62_dialog_content = "…",
  ui_story_2_3_63_dialog_content = "Omongannya ada benarnya. Untuk sekarang, kita hentikan saja dulu pembongkarannya.",
  ui_story_2_3_64_dialog_content = "Kau benar! Semuanya, berhenti!",
  ui_story_2_3_65_dialog_content = "Hoi, kamu! Sini.",
  ui_story_2_3_66_dialog_content = "Katakan, siapa kau ini?",
  ui_story_2_3_67_dialog_content = "…",
  ui_story_2_3_68_dialog_content = "Kalaupun kau tak memberitahuku, aku bisa menebak. Pakaian yang kaukenakan ini hanya dipakai oleh orang-orang dari masa 17 tahun lalu.",
  ui_story_2_3_69_dialog_content = "Hebat juga kau bisa bertahan hidup sebegitu lama dengan benda raksasa ini!",
  ui_story_2_3_70_dialog_content = "Apa kamu tahu siapa aku?",
  ui_story_2_3_71_dialog_content = "Belum begitu lama, <color=#FFB400>Caelestite</color>. Aku tidak pikun.",
  ui_story_2_3_72_dialog_content = "Kau tidak tahu siapa aku, atau apa yang akan terjadi kalau kau cari masalah denganku! Aku… aku tidak takut padamu!",
  ui_story_2_3_73_dialog_content = "…",
  ui_story_2_3_74_dialog_content = "Kepalamu tadi terbentur atau kenapa, sih?",
  ui_story_2_3_75_dialog_content = "Kau berusaha mengancam kami hanya karena kau ini berasal dari <color=#FFB400>ras istimewa</color>?",
  ui_story_2_3_76_dialog_content = "Jangan main-main, ya, kami ini perampok bengis.",
  ui_story_2_3_77_dialog_content = "… Kamu tahu siapa aku?",
  ui_story_2_3_78_dialog_content = "Ya ampun, pakaian yang kaukenakan itu, Colossus itu, dan tatapanmu yang kebingungan itu, siapa pun bisa menebaknya dengan mudah.",
  ui_story_2_3_79_dialog_content = "Harusnya bisa dapat uang banyak…",
  ui_story_2_3_80_dialog_content = "M-menjualku?! Kenapa kalian memperlakukanku sangat berbeda walaupun kalian sendiri juga Aurorian?!",
  ui_story_2_3_81_dialog_content = "Jangan salah paham, <color=#FFB400>Caelestite</color>. Kau tak berarti apa pun bagi bandit seperti kami.",
  ui_story_2_3_82_dialog_content = "Caelestite? Kaum yang dibinasakan oleh para Eclipsite itu?",
  ui_story_2_3_B1_dialog_content = "Dibinasakan…",
  ui_story_2_3_B2_dialog_content = "Jadi, 17 tahun lalu, tak ada orang lain yang selamat dari serangan di Eraveil?",
  ui_story_2_3_83_dialog_content = "Apa kau tahu detailnya lebih banyak?",
  ui_story_2_3_84_dialog_content = "Maaf, tapi itu terjadi begitu tiba-tiba. Semua berakhir dalam semalam saja.",
  ui_story_2_3_85_dialog_content = "Lagi pula, waktu itu aku masih anak-anak, jadi mana mungkin aku tahu banyak, 'kan?",
  ui_story_2_3_89_dialog_content = "Baiklah, sudah cukup omong kosong ini! Entah si Caelestite ini atau Colossus itu, kalian semua sekarang jadi milik kami!",
  ui_story_2_3_90_dialog_content = "Jadi, tentang Vice…",
  ui_story_2_3_91_dialog_content = "Sudah dari tadi kami mengirimnya ke <color=#FFB400>bantuan hidup</color> untuk dirawat! Kami ini perampok, bukan pembunuh!",
  ui_story_2_3_92_dialog_content = "Kenapa kau bisa tahu begitu banyak tentang Colossus…",
  ui_story_2_3_93_dialog_content = "Kaum Caelestite bukan satu-satunya yang punya Colossus. Kami yang tinggal di Rediesel Wrench juga punya <color=#FFB400>Roadrunner</color> kami sendiri.",
  ui_story_2_3_94_dialog_content = "Coba kita lihat apa ada yang mau memberi kami uang untuk menebusmu, Caelestite!",
  ui_story_2_4_1_dialog_content = "Bos, ada sekawanan Eclipsite menuju ke arah kita.",
  ui_story_2_4_2_dialog_content = "Mana bisa kita menyeret Colossus ini pulang kalau mereka terus berdatangan begini?",
  ui_story_2_4_3_dialog_content = "Omong-omong, PlayerName, sebelum kami sampai di sini, kau tadi dikejar-kejar Eclipsite, 'kan?",
  ui_story_2_4_4_dialog_content = "Oh, begitu…",
  ui_story_2_4_5_dialog_content = "Sial, masalah lagi.",
  ui_story_2_4_6_dialog_content = "Bersiap, teman-teman! Saatnya membasmi kutu!",
  ui_story_2_4_7_dialog_content = "Bagaimana kalau kautunjukkan kemampuan psikis Caelestite yang legendaris itu?",
  ui_story_2_4_8_dialog_content = "Kau ingin aku memandumu…?",
  ui_story_2_4_9_dialog_content = "Tentu saja, kesempatan seperti ini tak boleh dilewatkan! Tunjukkan Light Trail-mu itu kepada kami!",
  ui_story_2_4_10_dialog_content = "Musuh berdatangan! Siapkan senjatamu! Jangan sampai mati!",
  ui_story_2_8_1_dialog_content = "Manuver seperti ini tak mungkin hanya kebetulan semata.",
  ui_story_2_8_2_dialog_content = "Sejak kapan para Eclipsite itu jadi pintar?",
  ui_story_2_8_3_dialog_content = "Bagaimana menurutmu, Joanie?",
  ui_story_2_8_4_dialog_content = "Mungkinkah ada High-Level Eclipsite yang mengomando mereka?",
  ui_story_2_8_5_dialog_content = "Jangan bawa sial untuk kami!",
  ui_story_2_8_7_dialog_content = "High-Level Eclipsite…",
  ui_story_2_8_B1_dialog_content = "Apa, sudah saatnya?",
  ui_story_2_8_B2_dialog_content = "Bos, akhirnya kau ingat!",
  ui_story_2_8_B3_dialog_content = "Maaf, seru sekali bertarung bersama Caelestite sampai-sampai aku lupa waktu…",
  ui_story_2_8_B4_dialog_content = "Kita istirahat dulu sekarang! <color=#FFB400>Saatnya makan malam</color>!",
  ui_story_2_8_B5_dialog_content = "<anim type=Shake><size=45>Yeaaaaahh!! Saatnya makan malam!</size></anim>",
  ui_story_2_8_SS_dialog_content = "Area Piknik Rediesel Wrench",
  ui_story_2_8_B6_dialog_content = "Hoi! Jangan dorong! Bukankah kau sudah tahu, bos harus duluan!?",
  ui_story_2_8_B7_dialog_content = "Haha! Kau duluan saja! Sisakan dua tong untukku!",
  ui_story_2_8_B8_dialog_content = "Sebenarnya… kalian sedang apa?",
  ui_story_2_8_B9_dialog_content = "Makan. Memangnya aneh? Memangnya kau belum pernah makan?",
  ui_story_2_8_B10_dialog_content = "Maksudku, kalian liar sekali…",
  ui_story_2_8_B11_dialog_content = "Ini satu-satunya cara agar kami bisa bertahan hidup di dunia ini, PlayerName. Jangan meremehkan ketangguhan kami.",
  ui_story_2_8_B12_dialog_content = "Kami hanya bisa hidup kalau kami makan dan minum, dan kami hidup untuk makan dan minum!",
  ui_story_2_8_B13_dialog_content = "Terus saja mengobrol dengan Caelestite itu, Sinsa, dan akan kami habiskan semua dagingnya!",
  ui_story_2_8_B14_dialog_content = "Saya menyambar beberapa <color=#FFB400>dendeng kadal panggang</color> untukmu!",
  ui_story_2_8_B15_dialog_content = "Berikan kepada Caelestite itu. Aku tidak lapar.",
  ui_story_2_8_B16_dialog_content = "Nih!",
  ui_story_2_8_B17_dialog_content = "… Aku… Aku juga tidak lapar…",
  ui_story_2_8_B18_dialog_content = "Kenapa kau selalu tampak tertekan, sih?",
  ui_story_2_8_B19_dialog_content = "Bukankah tadi kaubilang ini pertama kalinya kau melihat dunia luar?",
  ui_story_2_8_B20_dialog_content = "Memangnya kau tidak ingin merayakannya?",
  ui_story_2_8_B21_dialog_content = "Kenapa kau sungkan begitu?",
  ui_story_2_8_B22_dialog_content = "Apa? Dunia luar tidak seindah bawah tanah?",
  ui_story_2_8_B23_dialog_content = "Hah?",
  ui_story_2_8_B24_dialog_content = "Aku tak peduli apa yang sudah kaulalui, tapi bukankah kau, Colossus itu, dan gadis itu sekarang sudah selamat?",
  ui_story_2_8_B25_dialog_content = "Kalau tak punya peran sama sekali, tak mungkin kau bisa hidup selama ini.",
  ui_story_2_8_B26_dialog_content = "Hidup di dunia ini tidak mudah, tapi kalau kaukira hanya hidupmu saja yang berat, berarti kau bodoh.",
  ui_story_2_8_B27_dialog_content = "Apa gunanya orang bodoh untukku? Lebih baik kubunuh saja kau agar aku tak usah repot.",
  ui_story_2_8_B28_dialog_content = "Kalau kaubunuh aku, kau akan dapat masalah. I-Illumina tak akan akan membiarkanmu kabur begitu saja!",
  ui_story_2_8_B29_dialog_content = "Hahahahahaha!",
  ui_story_2_8_B30_dialog_content = "Apanya yang lucu?",
  ui_story_2_8_B33_dialog_content = "Kurasa kau tidak sepenuhnya bodoh!",
  ui_story_2_8_8_dialog_content = "Aku menemukan si Caelestite!",
  ui_story_2_8_9_dialog_content = "Itu <color=#FFB400>Umbrahulk</color>!?",
  ui_story_2_8_B34_dialog_content = "Eclipsite itu! Apa mereka benar-benar mencariku?!",
  ui_story_2_8_B35_dialog_content = "Taruh makanan kalian dan susun formasi! Saatnya bertarung!",
  ui_story_2_8_10_dialog_content = "Menyerang saat enak-enaknya makan? Apa-apaan dunia ini?",
  ui_story_2_8_B36_dialog_content = "Sepertinya aku harus turun tangan sendiri untuk mengajari kalian sopan santun.",
  ui_story_2_8_11_dialog_content = "Dia agak lebih tangguh dari dugaanku…",
  ui_story_2_8_12_dialog_content = "<color=#FFB400>Kereta</color> ini…",
  ui_story_2_8_13_dialog_content = "Bukan, bukan <color=#FFB400>dia</color>…",
  ui_story_2_8_14_dialog_content = "Memalukan, Sinsa.",
  ui_story_2_8_15_dialog_content = "Kau sedang main rumah-rumahan dengan para Eclipsite itu?",
  ui_story_2_8_16_dialog_content = "Sudah kuduga, rupanya kamu. Akhir-akhir ini aku belum mencuri apa pun darimu.",
  ui_story_2_8_17_dialog_content = "Aku kemari untuk membawa rekanku kembali ke Illumina, tapi aku akan mengurusmu belakangan.",
  ui_story_2_8_18_dialog_content = "Oh, si gadis muda itu?",
  ui_story_2_8_19_dialog_content = "Kebetulan sekali! Tadi aku memang berniat memulangkan dia.",
  ui_story_2_8_20_dialog_content = "Bukan hanya dia, tapi juga Colossus itu. Dia milik <color=#FFB400>Illumina Federation</color>.",
  ui_story_2_8_21_dialog_content = "Jangan berani-berani mendorongnya, monster rambut putih!",
  ui_story_2_8_22_dialog_content = "Akan kuledakkan mobilmu.",
  ui_story_2_8_23_dialog_content = "Tenanglah, Bing Bang Boom!",
  ui_story_2_8_24_dialog_content = "Dia ini lawan yang lebih tangguh daripada Umbrahulk itu.",
  ui_story_2_8_25_dialog_content = "Itu hanya Colossus, dan karena kita toh tak bisa membongkar atau menjualnya, benda itu jadi tak begitu penting untuk kita.",
  ui_story_2_8_26_dialog_content = "Cih! Kau sedang beruntung!",
  ui_story_2_8_B37_dialog_content = "Charon, kuharap kau tahu apa yang kauhadapi.",
  ui_story_2_8_B38_dialog_content = "PlayerName, kau lebih menarik daripada yang kukira.",
  ui_story_2_8_B39_dialog_content = "Hah?",
  ui_story_2_8_B40_dialog_content = "Sayang sekali! Tidak setiap hari kita bisa menemukan harta karun langka seperti itu.",
  ui_story_2_8_B41_dialog_content = "PlayerName, kau benar-benar harus agak ceria sedikit…",
  ui_story_2_8_B42_dialog_content = "Tapi kau masih bersinar dengan aura cahaya.",
  ui_story_2_8_B43_dialog_content = "Aura cahaya? Tapi, aku tak bisa menggunakan kekuatan Light—",
  ui_story_2_8_B44_dialog_content = "Ya ampun! Itu cuma kiasan!",
  ui_story_2_8_B48_dialog_content = "Tak bisakah kau katakan langsung saja? Kau tak perlu sok berteka-teki begitu.",
  ui_story_2_8_B49_dialog_content = "Hahaha… Nah, begitu, dong! Sepertinya kau sudah merasa lebih baik!",
  ui_story_2_8_B50_dialog_content = "Ingat ini, Caelestite, mati itu mudah, tapi sebaiknya kau tetap hidup selagi masih bisa!",
  ui_story_2_8_B51_dialog_content = "Kau selalu bisa menemukan yang disebut \"<color=#FFB400>harapan</color>\".",
  ui_story_2_8_B52_dialog_content = "Harapan selalu ada, dalam hari paling cerah maupun malam paling kelam sekalipun.",
  ui_story_2_8_B53_dialog_content = "Dari mana kau dapat kata-kata seperti itu?",
  ui_story_2_8_B54_dialog_content = "Hmm… Aku lupa.",
  ui_story_2_8_B55_dialog_content = "Baru beberapa hari saja aku tak melihatmu, rupanya kau sudah mulai membaca buku.",
  ui_story_2_8_B56_dialog_content = "Hahahaha! Jangan meremehkan orang gembel keras kepala seperti kami ini! Nah, sampai jumpa, semuanya!",
  ui_story_2_8_28_dialog_content = "Aku punya firasat kita akan bertemu lagi…",
  ui_story_2_8_29_dialog_content = "Rediesel Wrench, ayo pulang dan nikmati sandworm hari ini!",
  ui_story_2_8_31_dialog_content = "… Tidak bisakah sekali saja kau pulang membawa kabar baik, Nozard?",
  ui_story_2_8_32_dialog_content = "Ada bala bantuan yang dikirimkan Illumina. Dia seorang Aurorian bernama <color=#FFB400>Charon</color>…",
  ui_story_2_8_33_dialog_content = "Charon? Sudah lama sekali aku tak mendengar nama itu.",
  ui_story_2_8_34_dialog_content = "Jadi, mereka juga membawa si Caelestite itu?",
  ui_story_2_8_35_dialog_content = "Mereka menuju <color=#FFB400>Undercity 28</color>.",
  ui_story_2_8_36_dialog_content = "Setidaknya Umbrahulk tahu mereka pergi ke mana. Kau tahu apa yang harus kaulakukan berikutnya.",
  ui_story_2_8_37_dialog_content = "Ya!",
  ui_story_2_8_38_dialog_content = "Aurorian Undercity…",
  ui_story_2_8_39_dialog_content = "Memangnya tikus-tikus itu kira mereka bisa bersembunyi di liang mereka dan tenang-tenang saja?",
  ui_story_2_8_40_dialog_content = "Pengecut… Kalau kalian memang berniat sembunyi di sana…",
  ui_story_2_8_41_dialog_content = "Bersiaplah untuk menyaksikan semua orang mati bersama kalian!",
  ui_story_2_9_1_dialog_content = "Siapa kau?",
  ui_story_2_9_2_dialog_content = "Aku kepala <color=#FFB400>Undercity 28 Logistics</color>.",
  ui_story_2_9_3_dialog_content = "Panggil aku Charon.",
  ui_story_2_9_4_dialog_content = "Di mana Vice?",
  ui_story_2_9_5_dialog_content = "Dia ada di sistem bantuan hidup di dalam Colossus itu. Dia terluka. Aku… gagal melindunginya.",
  ui_story_2_9_6_dialog_content = "Dan kau ini siapanya Vice…?",
  ui_story_2_9_7_dialog_content = "Sebelumnya, Vice melaporkan tugas eksplorasinya ke sini.",
  ui_story_2_9_8_dialog_content = "Lalu, aku melihat sinyal minta bantuan dari Colossus itu dan mengikuti para Eclipsite itu ke lokasimu.",
  ui_story_2_9_9_dialog_content = "Bagaimana keadaan Vice?",
  ui_story_2_9_10_dialog_content = "Cederanya sudah distabilkan oleh perangkat bantuan hidup di Colossus itu.",
  ui_story_2_9_11_dialog_content = "Apa yang harus kita lakukan selanjutnya?",
  ui_story_2_9_12_dialog_content = "Kau benar-benar banyak tanya, ya. Bagaimana kalau kau ikut aku kembali ke Undercity 28 saja untuk sementara ini?",
  ui_story_2_9_13_dialog_content = "Officer Charon sudah kembali!",
  ui_story_2_9_14_dialog_content = "Wow! Besar sekali! Apa itu?",
  ui_story_2_9_15_dialog_content = "Cepat, beri tahu divisi Transportasi untuk membuka rel eksklusif Charon.",
  ui_story_2_9_17_dialog_content = "Selamat datang kembali, Officer Charon!",
  ui_story_2_9_18_dialog_content = "Ini… sebuah Colossus?!",
  ui_story_2_9_19_dialog_content = "Ya, dan ada seseorang yang cedera di dalam Colossus itu. Beri tahu tim medis.",
  ui_story_2_9_20_dialog_content = "Selain itu, seorang anggota skuad Illumina… mengorbankan nyawanya.",
  ui_story_2_9_21_dialog_content = "Siap, Pak. Aku akan mengurusnya sebagaimana mestinya dan mengerahkan pasukan cadangan sekarang juga.",
  ui_story_2_9_22_dialog_content = "Bagus. Terima kasih.",
  ui_story_2_9_23_dialog_content = "Bagaimana kondisi di baris depan?",
  ui_story_2_9_24_dialog_content = "Semuanya wajar!",
  ui_story_2_9_25_dialog_content = "Aneh. Bagaimana bisa Eclipsite sebanyak itu berhasil menembus baris depan?",
  ui_story_2_9_26_dialog_content = "Beri tahu divisi komunikasi untuk menghubungi <color=#FFB400>markas pusat di Gannon</color>. Aku ingin bicara dengan mereka nanti.",
  ui_story_2_9_B1_dialog_content = "…",
  ui_story_2_9_B2_dialog_content = "Kenapa? Belum pernah lihat kota bawah tanah sebesar ini, atau organisasi sekuat ini?",
  ui_story_2_9_B3_dialog_content = "Di sini… Ini Illumina?",
  ui_story_2_9_B4_dialog_content = "Ini hanyalah salah satu Undercity milik Illumina Federation—Nomor 28.",
  ui_story_2_9_B5_dialog_content = "Walaupun Undercity 28 bukan baris depan dalam pertempuran melawan Eclipsite, kami masih menjadi pangkalan logistik yang tak tergantikan.",
  ui_story_2_9_F1_dialog_content = "Kalau kami sampai jatuh, Eclipsite akan menembus batas dan langsung menuju ke…",
  ui_story_2_9_B6_dialog_content = "Oh, Caelestite, apa kau pernah belajar geografi?",
  ui_story_2_9_F2_dialog_content = "Aku… aku belajar sedikit. Kalau Eclipsite sampai menembus batas, mereka bisa saja langsung merangsek ke jantung kontinen, 'kan?",
  ui_story_2_9_B7_dialog_content = "Benar! Dengan satu sisi yang selalu siang sedangkan sisi lainnya selalu malam, di sinilah tempat satu-satunya kami bisa bertahan hidup. Kami tak punya tempat lain untuk pergi.",
  ui_story_2_9_B8_dialog_content = "Kami orang-orang Illumina terlahir untuk melawan Eclipsite. Itu tujuan dan takdir kami.",
  ui_story_2_9_B9_dialog_content = "Kami harus melindungi negeri kami yang berharga ini.",
  ui_story_2_9_B10_dialog_content = "Negerimu? Maksudmu negeri Aurorian?",
  ui_story_2_9_B11_dialog_content = "Lebih tepatnya, tempat yang berisi segala <color=#FFB400>hal yang kami hargai</color>.",
  ui_story_2_9_B13_dialog_content = "Mungkin saja Aurorian, mungkin pula reruntuhan yang hilang, bahkan mungkin pula kenangan tak penting.",
  ui_story_2_9_B14_dialog_content = "Sepertinya… agak sentimental?",
  ui_story_2_9_B15_dialog_content = "Sentimental? Ini motivasi kami untuk terus bertahan hidup.",
  ui_story_2_9_B16_dialog_content = "Dengan kata lain, <color=#FFB400>harapan</color>!",
  ui_story_2_9_B17_dialog_content = "Kalau tak bisa menghindari keputusasaan, kita harus mengatasi masa-masa sulit dengan harapan.",
  ui_story_2_9_B18_dialog_content = "Yah, itu terdengar agak puitis.",
  ui_story_2_9_B19_dialog_content = "… Aku jadi teringat apa yang pernah dibilang Sinsa.",
  ui_story_2_9_B20_dialog_content = "Kau tampak agak lelah. Apa yang akan kaulakukan setelah ini? Istirahat?",
  ui_story_2_9_B21_dialog_content = "Atau kau mau menemui teman-temanmu yang lain?",
  ui_story_2_9_B22_dialog_content = "Teman…? Aku tak tahu apakah kaumku…",
  ui_story_2_9_B23_dialog_content = "Maksudku para Aurorian itu. Bukannya mereka temanmu?",
  ui_story_2_9_B24_dialog_content = "Ah… Ya, mereka sudah banyak membantuku…",
  ui_story_2_9_B25_dialog_content = "Aku mungkin butuh waktu untuk menata pikiranku. Hari ini agak terlalu berat untukku…",
  ui_story_2_9_B26_dialog_content = "Oke. Tinggallah di sini kalau begitu—aku masih harus menyelesaikan laporan harian, jadi aku terpaksa meninggalkanmu sekarang.",
  ui_story_2_9_B27_dialog_content = "Kenapa tiba-tiba jadi serius…?",
  ui_story_2_9_B28_dialog_content = "Penyair paling romantis sekalipun tetap punya pekerjaan yang harus dilakukan!",
  ui_story_2_9_B30_dialog_content = "Dan tolong, jangan terlalu menyalahkan dirimu sendiri atas apa yang telah terjadi.",
  ui_story_2_9_B31_dialog_content = "Para prajurit Illumina itu gugur karena menjalankan tugas, bukan hanya demi kamu.",
  ui_story_2_9_27_dialog_content = "Semoga ini bisa meringankan beban pikiranmu.",
  ui_story_2_9_28_dialog_content = "…",
  ui_story_2_9_29_dialog_content = "Caeles… tite? Bolehkah aku memanggilmu begitu? Lounge ada di dekat sini.",
  ui_story_2_9_30_dialog_content = "Ikuti aku. Walau ini baru pertama kalinya kita bertemu, siapa pun yang dibawa Charon bisa dipercaya.",
  ui_story_2_9_32_dialog_content = "Selamat datang di Undercity 28.",
  ui_story_2_9_33_dialog_content = "Undercity 28 kepada Gannon. Ini Charon, menyampaikan laporan situasi penting.",
  ui_story_2_9_34_dialog_content = "Dimengerti. Ini <color=#FFB400>Hiiro</color> di Gannon.",
  ui_story_2_9_35_dialog_content = "Sandi.",
  ui_story_2_9_36_dialog_content = "<color=#FFB400>\"Masinis kereta superganteng.\"</color>",
  ui_story_2_9_37_dialog_content = "Rupanya kau bertugas hari ini, Hiiro.",
  ui_story_2_9_38_dialog_content = "Balas.",
  ui_story_2_9_39_dialog_content = "<color=#FFB400>\"Sakura\"</color>…",
  ui_story_2_9_41_dialog_content = "Bagaimana progres misi Vice?",
  ui_story_2_9_42_dialog_content = "Memang itulah yang ingin kusampaikan kepadamu.",
  ui_story_2_9_43_dialog_content = "Colossus itu sudah ditemukan dan dibawa ke Undercity 28.",
  ui_story_2_9_44_dialog_content = "Vice terluka dan saat ini sedang dirawat.",
  ui_story_2_9_45_dialog_content = "Terluka? Apa lukanya parah?",
  ui_story_2_9_46_dialog_content = "Dia baik-baik saja.",
  ui_story_2_9_47_dialog_content = "Sebagai atasan sementaranya, Charon, kau harus bertanggung jawab atas hal ini.",
  ui_story_2_9_48_dialog_content = "Beri tahu aku apa yang terjadi.",
  ui_story_2_9_49_dialog_content = "Dugaan Vice benar.",
  ui_story_2_9_50_dialog_content = "Colossus yang meninggalkan Eraveil 17 tahun lalu itu jatuh di dekat Undercity 28.",
  ui_story_2_9_51_dialog_content = "Dia dan timnya menghadapi banyak Eclipsite yang sepertinya sedang melacak Colossus itu.",
  ui_story_2_9_52_dialog_content = "Memangnya tadi Vice tidak meminta pasukan bantuan setelah dia menemukan Colossus itu?",
  ui_story_2_9_F3_dialog_content = "Aku melihat sinyal minta bantuannya, tapi…",
  ui_story_2_9_53_dialog_content = "Terlambat?",
  ui_story_2_9_54_dialog_content = "Biar kuselesaikan dulu, Hiiro. Ini lebih rumit dari yang kaukira.",
  ui_story_2_9_55_dialog_content = "Colossus itu terkubur di bawah tanah, tapi kau tak akan pernah menyangka bahwa ada seorang Caelestite yang juga hidup di dalamnya.",
  ui_story_2_9_57_dialog_content = "Caelestite?",
  ui_story_2_9_58_dialog_content = "Maksudmu, ada Caelestite yang hidup di bawah tanah selama 17 tahun?",
  ui_story_2_9_60_dialog_content = "Lalu?",
  ui_story_2_9_61_dialog_content = "Vice meminta bantuan dengan mengirimkan sinyal minta bantuan dari Colossus itu.",
  ui_story_2_9_62_dialog_content = "Aku langsung berangkat secepatnya dan menemukan jejak yang ditinggalkan kawanan Eclipsite.",
  ui_story_2_9_63_dialog_content = "Lalu, aku tahu dari Caelestite itu bahwa sebelumnya mereka sudah melawan Kraken, Nozard, dan Umbrahulk.",
  ui_story_2_9_64_dialog_content = "Tiga High-Level Eclipsite?",
  ui_story_2_9_65_dialog_content = "Mereka berhasil menembus pertahanan kita dan bahkan menyusup ke wilayah di dekat Undercity 28?",
  ui_story_2_9_66_dialog_content = "Tak ada satu Eclipsite pun yang bisa menembus pertahanan kita, kecuali Kraken.",
  ui_story_2_9_67_dialog_content = "Selain itu, ada sejumlah besar Eclipsite biasa yang mengikuti mereka.",
  ui_story_2_9_68_dialog_content = "Mereka tidak meninggalkan jejak rute yang mereka lewati untuk sampai ke sana, seakan-akan mereka jatuh begitu saja dari langit, sama seperti yang terjadi 17 tahun lalu di Eraveil.",
  ui_story_2_9_69_dialog_content = "Maksudmu, Eclipsite berhasil menembus pertahanan kita?",
  ui_story_2_9_70_dialog_content = "Sayangnya, kurasa begitu…",
  ui_story_2_9_71_dialog_content = "Lagi pula, Nozard ternyata masih hidup, dan ini berarti masalah.",
  ui_story_2_9_72_dialog_content = "Baiklah, aku akan memberi tahu Grand Marshal sekarang juga.",
  ui_story_2_9_73_dialog_content = "Kalian juga tetap waspada, ya.",
  ui_story_2_9_74_dialog_content = "Undercity 28 adalah jalur suplai penting untuk baris depan. Kalau suplai di sana…",
  ui_story_2_9_75_dialog_content = "Hiiro, aku bisa menanganinya.",
  ui_story_2_9_76_dialog_content = "<color=#e8d9bb>Beberapa Hari Kemudian - Area Perbaikan Colossus</color>",
  ui_story_2_9_77_dialog_content = "Di situ kau rupanya.",
  ui_story_2_9_78_dialog_content = "Vice? Memangnya kau sudah cukup sehat untuk berjalan-jalan?!",
  ui_story_2_9_79_dialog_content = "Yah, teknologi medis Illumina memang menakjubkan, 'kan?",
  ui_story_2_9_80_dialog_content = "Bagaimana keadaan Soroz?",
  ui_story_2_9_81_dialog_content = "Semuanya bagus. Teknologi Illumina memang menakjubkan. Unit-unit yang rusak sudah diperbaiki hanya dalam hitungan hari.",
  ui_story_2_9_82_dialog_content = "Para pekerja sekarang sedang mengerjakan sentuhan akhir, yang menurutku agak sedikit berlebihan.",
  ui_story_2_9_83_dialog_content = "Akan bagus kalau lambang Illumina yang mencolok itu dilepas saja…",
  ui_story_2_9_84_dialog_content = "Aku tak menyangka ternyata keterampilan dan pengetahuan Illumina sebagus ini… Tolong sampaikan terima kasihku kepada Vice.",
  ui_story_2_9_87_dialog_content = "Tentu saja, divisi teknik di Illumina selalu berusaha memberikan hasil cemerlang.",
  ui_story_2_9_88_dialog_content = "Lihat seragam dan senjataku. Ini semua hasil karya divisi teknik. Mereka sangat penting bagi pertempuran kita.",
  ui_story_2_9_89_dialog_content = "Ini konfigurasi hasil rekayasa Lumina, yang mengatur dan memberikan kekuatan kepada Aurorian.",
  ui_story_2_9_90_dialog_content = "Teknologi ini sangat canggih dalam hal efisiensi dan kecepatan aktivasi.",
  ui_story_2_9_91_dialog_content = "Walau kekuatannya jauh di bawah praktik tradisional, teknologi hasil rekayasa ini cocok untuk Illumina karena kami bertarung berkelompok.",
  ui_story_2_9_A1_dialog_content = "…",
  ui_story_2_9_A2_dialog_content = "…",
  ui_story_2_9_A3_dialog_content = "Oh, apa ada yang tidak kaupahami?",
  ui_story_2_9_A4_dialog_content = "… Yah, sebenarnya hampir semuanya tidak bisa kupahami, sih.",
  ui_story_2_9_A5_dialog_content = "Semua? Oh, maaf, aku lupa ini hal baru untukmu…",
  ui_story_2_9_A6_dialog_content = "Nah… Ganti topik…",
  ui_story_2_9_A7_dialog_content = "Vice, saat kita jatuh…",
  ui_story_2_9_98_dialog_content = "Sepertinya aku bilang sesuatu… Nah…",
  ui_story_2_9_99_dialog_content = "Singkatnya… Aku minta maaf!",
  ui_story_2_9_100_dialog_content = "Hah? Kenapa tiba-tiba minta maaf?",
  ui_story_2_9_101_dialog_content = "Memang aku egois bilang begitu waktu itu, dan kau jadi terluka gara-gara aku. Beberapa hari terakhir ini aku mimpi buruk…",
  ui_story_2_9_102_dialog_content = "Oh, rupanya itu maksudmu! Tak perlu minta maaf sama sekali!",
  ui_story_2_9_103_dialog_content = "Waktu itu aku tak paham seberapa dekatnya kau dan Soroz. Aku salah waktu itu bilang begitu.",
  ui_story_2_9_104_dialog_content = "Aku khawatir kau akan tetap di sana dan menghadapi para Eclipsite itu sendirian.",
  ui_story_2_9_105_dialog_content = "Tapi, yang penting kita berhasil pergi dari sana hidup-hidup!",
  ui_story_2_9_107_dialog_content = "Aku tak sabar untuk bekerja sama denganmu, PlayerName.",
  ui_story_2_9_108_dialog_content = "Iya!",
  ui_story_2_9_109_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_2_9_110_dialog_content = "<color=#e8d9bb>Getarannya makin hebat, sepertinya berasal dari tanah di bawah sana.</color>",
  ui_story_2_9X_1_dialog_content = "<color=#e8d9bb>Baru saja ada getaran ringan.</color>",
  ui_story_2_9X_2_dialog_content = "<color=#e8d9bb>Getarannya makin hebat, sepertinya berasal dari tanah di bawah sana.</color>",
  ui_story_2_9X_3_dialog_content = "Ada yang aneh…",
  ui_story_2_9X_4_dialog_content = "Getaran apa itu? Jangan-jangan Soroz?",
  ui_story_2_9X_5_dialog_content = "Kurasa bukan. Biar kucoba bertelepati dengannya.",
  ui_story_2_9X_6_dialog_content = "<color=#e8d9bb>Biip—Biip—BII!</color>",
  ui_story_2_9X_7_dialog_content = "Alarm ini… Ada yang menembus sistem pertahanan? Bagaimana mungkin! Sistemnya berfungsi sebagaimana mestinya, di mana persisnya…?",
  ui_story_2_9X_8_dialog_content = "Vice! Pertahanan… ditembus… Kita diserang!! Kau…",
  ui_story_2_9X_9_dialog_content = "Apa katamu? Aku tak bisa mendengarmu, Officer Charon!",
  ui_story_2_9X_19_dialog_content = "Vice! Aku merasakan kehadiran Eclipsite!",
  ui_story_2_9X_20_dialog_content = "Eclipsite? Di Undercity? Bagaimana bisa?",
  ui_story_2_9X_21_dialog_content = "Tiga… sepuluh… Aku tak bisa menghitungnya. Vice, jumlah Eclipsite itu makin bertambah!",
  ui_story_2_9X_22_dialog_content = "Pasti ada sesuatu di balik getaran itu! Mungkin Undercity sudah…",
  ui_story_2_9X_23_dialog_content = "Kalau begitu, ayo kita cari sumbernya! Kalau benar ini serangan, kita harus menghentikannya sebelum mereka mencapai area permukiman!",
  ui_story_2_9X_24_dialog_content = "Bersiaplah untuk bertempur, PlayerName!",
  ui_story_2_9X_25_dialog_content = "Siap!",
  ui_story_2_9X_26_dialog_content = "Sana… Bantai… Cabik-cabik apa pun yang kalian lihat sampai remuk…",
  ui_story_2_9X_27_dialog_content = "Aku tak akan gagal lagi kali ini. Penghinaan ini hanya bisa dihapus dengan darah dan tulang kaum Aurorian!",
  ui_story_2_9X_28_dialog_content = "<size=45>Basmi Undercity ini!</size>",
  ui_story_2_10_19_dialog_content = "Vice! PlayerName!",
  ui_story_2_10_20_dialog_content = "Kau baik-baik saja, Officer Charon?",
  ui_story_2_10_21_dialog_content = "Vice??",
  ui_story_2_10_22_dialog_content = "<color=#FFB400>Pertahanan Undercity ditembus</color>… Terjadi hal di luar dugaan kita! Mereka berhasil menembus pembatas!",
  ui_story_2_10_23_dialog_content = "Bagaimana mereka bisa melancarkan serangan tertata yang menarget titik-titik lemah Undercity?",
  ui_story_2_10_24_dialog_content = "Tak mungkin. Ada yang salah. Selama ini belum pernah ada kejadian seperti ini.",
  ui_story_2_10_25_dialog_content = "Lalu sekarang kita harus bagaimana? Berapa banyak dari kita yang masih bisa bertarung? Kumpulkan semua orang di area yang tertembus itu!",
  ui_story_2_10_26_dialog_content = [[
Jalankan rencana evakuasi. Sudah banyak Eclipsite yang berhasil masuk. Menurut Pedoman Illumina, ini termasuk ancaman Kelas S.
Kita harus mengevakuasi seisi kota.]],
  ui_story_2_10_27_dialog_content = "Maafkan aku. Aku sama sekali tidak menduganya…",
  ui_story_2_10_28_dialog_content = "Ayo, Vice. Ayo kita evakuasi orang-orang yang terluka dan warga sipil bersama-sama!",
  ui_story_2_10_29_option_content = "Apa situasinya sudah tak tertolong lagi?",
  ui_story_2_10_30_option_content = "Benarkah tak ada peluang untuk melawan…?",
  ui_story_2_10_31_dialog_content = "Lihat sekelilingmu! Undercity 28 bukan lagi medan tempur. Tempat ini penuh dengan prajurit dan petugas logistik yang terluka!",
  ui_story_2_10_32_dialog_content = "Hal terbaik yang bisa kita lakukan adalah menyimpan kekuatan kita dan mengungsi ke Undercity lain!",
  ui_story_2_10_33_dialog_content = "Bagaimana situasi kita sekarang?",
  ui_story_2_10_34_dialog_content = "Para Eclipsite itu ada di mana-mana, dan mungkin ada High-Level Eclipsite di antara mereka. Apa pun itu, kita tak bisa tetap bertahan di sini!",
  ui_story_2_10_A1_dialog_content = "Itu Nozard…",
  ui_story_2_10_35_dialog_content = "Tak lama lagi Undercity ini akan dipenuhi Eclipsite.",
  ui_story_2_10_36_dialog_content = "Paham! PlayerName, kami butuh arahan darimu. Ayo kita evakuasi semua orang bersama-sama!",
  ui_story_2_10_40_dialog_content = "Siap, jangan sampai ada seorang pun yang tertinggal!",
  ui_story_2_10_41_dialog_content = "Ya, aku tak akan menelantarkan siapa pun! Kita harus mengevakuasi semua orang dengan aman!",
  ui_story_2_10_42_dialog_content = "Ayo pergi, sebelum terlambat!",
  ui_story_2_10_43_dialog_content = "Itu dia! Jangan beri para Aurorian itu kesempatan untuk istirahat sedikit pun! Begitu kalian menemukan lokasi Colossus dan Caelestite itu…",
  ui_story_2_10_44_dialog_content = "<size=45>Langsung beri tahu aku!</size>",
  ui_story_2_12_3_dialog_content = "Makhluk nista dan menjijikkan harus tetap tinggal dalam kegelapan!",
  ui_story_2_12_4_dialog_content = "Kenapa sih mereka kemari dan menghancurkan Undercity yang megah ini? Tak masuk akal!!",
  ui_story_2_12_5_dialog_content = "Wooga!",
  ui_story_2_12_6_dialog_content = "Aku tidak paham!",
  ui_story_2_12_7_dialog_content = "Kalau terus seperti ini, para Eclipsite itu akan lebih dulu sampai di area permukiman daripada kita!",
  ui_story_2_12_8_dialog_content = "Di mana keretamu, Charon? Tidak bisakah kita naik keretamu?",
  ui_story_2_12_9_dialog_content = "Di sini tak ada jalur rel yang bisa dilintasi Other End.",
  ui_story_2_12_10_dialog_content = "Kalau makhluk itu sampai dipanggil, kita bahkan tak perlu lagi berpikir untuk menyelamatkan nyawa. Kalau mayat kita bisa utuh saja, itu sudah merupakan keajaiban.",
  ui_story_2_12_11_dialog_content = "Kita harus berbuat sesuatu… dan cepat-cepat…",
  ui_story_2_12_12_dialog_content = "Apa ini memang Eclipsite yang sama dengan yang kulihat sebelumnya? Kenapa mereka bisa begitu… tertata… dan seakan-akan punya tujuan tertentu?",
  ui_story_2_12_13_dialog_content = "<color=#FFB400>Seakan-akan mereka punya target…</color>",
  ui_story_2_12_14_dialog_content = "…",
  ui_story_2_12_15_dialog_content = "Ah, jadi target mereka adalah Caelestite itu? Keadaan ini sulit sekali.",
  ui_story_2_12_16_dialog_content = "<color=#e8d9bb>Undercity lagi-lagi berguncang hebat.</color>",
  ui_story_2_12_17_dialog_content = "Aku tak suka mengakuinya, tapi sepertinya kita sudah kewalahan.",
  ui_story_2_12_18_dialog_content = "Masih ada secercah harapan. Kita belum mengeluarkan kartu as!",
  ui_story_2_12_19_dialog_content = "PlayerName, apa maksudmu…",
  ui_story_2_12_20_dialog_content = "<color=#FFB400>Soroz</color>!",
  ui_story_2_12_24_dialog_content = "Persis seperti yang kulakukan sebelumnya dengan PlayerName!",
  ui_story_2_12_25_dialog_content = "Colossus-nya masih mengisi daya, dan sepertinya butuh waktu agak lama.",
  ui_story_2_12_26_dialog_content = "Tetap saja kita harus mencobanya, 'kan? Dia bisa mengangkut semua orang keluar dari sini…",
  ui_story_2_12_X26_dialog_content = "Kalau begitu, ayo pergi. Sekarang kita tak punya pilihan selain memercayakan nasib kepada Soroz.",
  ui_story_2_12_27_dialog_content = "Orang-orang memang selalu memercayakan misi kepadaku pada saat-saat genting dan sulit. Aku sudah terbiasa. Tapi, akan lebih baik kalau kita bergegas.",
  ui_story_2_12_X27_dialog_content = "Aku bisa merasakan para Eclipsite itu sudah makin dekat…",
  ui_story_2_12_28_dialog_content = "Kita tak punya pilihan. Akan kuatur semua orang untuk naik ke Colossus itu.",
  ui_story_2_12_29_dialog_content = "Dan kami akan menyalakan Colossus itu dulu!",
  ui_story_2_13_1_dialog_content = "<color=#e8d9bb>Di dermaga bawah tanah, di mana Soroz sang Colossus berada</color>",
  ui_story_2_13_2_dialog_content = "Jumlah mereka bertambah…",
  ui_story_2_13_3_dialog_content = "Balik, balik…",
  ui_story_2_13_4_dialog_content = "Sudah kuduga! Para Eclipsite juga sudah mulai berkumpul di sekitar Colossus itu!",
  ui_story_2_13_5_dialog_content = "Hmm…",
  ui_story_2_13_6_dialog_content = "Apa dia sedang… mengirimkan sinyal? Mungkinkah dia sedang berkomunikasi dengan Eclipsite di tempat lain…?",
  ui_story_2_13_7_dialog_content = "Masa bodoh! Semuanya, masuk ke Colossus sekarang juga. Biarkan orang yang terluka dan anak-anak masuk duluan! Kami akan melindungi kalian dari sini!",
  ui_story_2_13_8_dialog_content = "Sepertinya aku tak akan mengemudikan kereta sama sekali… Padahal kukira hari ini kita bisa menutup tirai panggung dengan megah.",
  ui_story_2_13_9_dialog_content = "Sepertinya aku terpaksa bersenang-senang dengan ini saja.",
  ui_story_2_13_10_dialog_content = "Sedang apa kau dengan… remote control?",
  ui_story_2_13_11_dialog_content = "… <color=#FFB400>Red Key</color>? Kapan kau…",
  ui_story_2_13_12_dialog_content = "Ini prosedur standar untuk evakuasi kelas S. Semua jejak keberadaan kita harus dimusnahkan. Kembang apinya akan sangat megah.",
  ui_story_2_13_13_dialog_content = "Sebenarnya berat bagiku untuk pergi dari Undercity ini… Aku sudah bertahun-tahun tinggal di sini.",
  ui_story_2_13_14_dialog_content = "\"Supervisor dari Undercity 28\" tak mampu melindungi kotanya. Gagal total!",
  ui_story_2_13_15_dialog_content = "Maafkan aku…",
  ui_story_2_13_16_dialog_content = "Kenapa? Memangnya kau sengaja membiarkan para Eclipsite itu masuk?",
  ui_story_2_13_17_dialog_content = "Tentu saja tidak!",
  ui_story_2_13_18_dialog_content = "Tenanglah, Letnan… Aku hanya bercanda.",
  ui_story_2_13_19_dialog_content = "Masa Undercity 28 sudah habis. Ini bukan salah siapa-siapa.",
  ui_story_2_13_20_dialog_content = "Mungkin… semua hal pasti akan berakhir, dan memang begitulah semestinya…",
  ui_story_2_13_21_dialog_content = "Bahkan siang abadi dan malam abadi pun suatu saat akan berakhir… Kedengarannya puitis, ya?",
  ui_story_2_13_22_dialog_content = "Apa lagi yang kautunggu? Sana! Begitu kutekan Red Key ini, aku tak bisa menentukan siapa yang akan meledak.",
  ui_story_2_13_23_dialog_content = "Letnan, ada gelombang Eclipsite lagi! Masih ada orang-orang terluka di belakang…",
  ui_story_2_13_24_dialog_content = "Aku paham! Kami akan menahan mereka. Kalian semua, bergegaslah!",
  ui_story_2_13_25_dialog_content = "Sepertinya ini belum saatnya menurunkan tirai panggung. Akan kujauhkan dulu Red Key ini untuk sementara ini…",
  ui_story_2_14_1_dialog_content = "Aku datang… akhirnya! Ada yang terluka?",
  ui_story_2_14_2_dialog_content = "Kami sedang menghitung jumlah orang di sini! Sepertinya semua sudah lengkap. Mana Officer Charon?",
  ui_story_2_14_3_dialog_content = "Officer Charon? Dia sedang menjaga gerbang Colossus dari tempat lain.",
  ui_story_2_14_4_dialog_content = "Maaf membuatmu menunggu, Letnan! Sudah tak ada lagi orang yang tertinggal, 'kan? Para Eclipsite itu sudah memenuhi setiap jengkal tempat ini!",
  ui_story_2_14_5_dialog_content = "Terima kasih atas semuanya! Aku sudah menimbulkan begitu banyak masalah…",
  ui_story_2_14_6_dialog_content = "Tolong jangan bilang begitu, Letnan! Kita bawa orang-orang ini keluar lebih dulu. Ayo!",
  ui_story_2_14_7_dialog_content = "Tunggu, ada yang tertinggal. Mana Officer Charon?",
  ui_story_2_14_8_dialog_content = "Baru saja aku melihatnya melindungi orang-orang terluka yang masih tertinggal di belakang. Sepertinya…",
  ui_story_2_14_9_dialog_content = "Aku melihatnya! Di sana!",
  ui_story_2_14_10_dialog_content = "Sial, mereka merusak pakaianku…",
  ui_story_2_14_11_dialog_content = "Dia masih bertarung sendirian, dan semua Eclipsite di Undercity sudah berkumpul di sini!",
  ui_story_2_14_12_dialog_content = "Dari pergerakan para Eclipsite itu, jelas akulah target mereka!",
  ui_story_2_14_13_dialog_content = "Ayo naik!",
  ui_story_2_14_14_dialog_content = "Aku juga inginnya begitu! Tapi makhluk-makhluk ini sangat menjengkelkan!",
  ui_story_2_14_15_dialog_content = "Yang bisa kulakukan hanya memastikan mereka tidak mendesak kalian!",
  ui_story_2_14_16_dialog_content = "Tidak, aku harus membantunya… PlayerName, ikuti aku! Yang lainnya, tetap di tempat kalian!",
  ui_story_2_14_17_dialog_content = "Wooga?!",
  ui_story_2_14_18_dialog_content = "Jumlah mereka terlalu banyak! Kita bahkan tak bisa bergerak maju!",
  ui_story_2_14_19_dialog_content = "Kalau tak segera pergi, kita semua akan mati di sini! Ini bukan saatnya ragu-ragu!",
  ui_story_2_14_20_option_content = "Vice, kita harus pergi sekarang.",
  ui_story_2_14_21_dialog_content = "Tidak! Kita sudah sepakat untuk tidak meninggalkan siapa pun!",
  ui_story_2_14_22_dialog_content = "Vice, PlayerName benar. Kita harus pergi sesegera mungkin!",
  ui_story_2_14_23_dialog_content = "Charon tadi menyelamatkanmu! Bahkan, dia sudah berbuat sesuatu untuk kita semua! Kita tak bisa meninggalkannya begitu saja!",
  ui_story_2_14_24_dialog_content = "Tapi kita juga tak boleh mempertaruhkan nyawa semua orang di sini!",
  ui_story_2_14_25_dialog_content = "Aku tahu itu, tentu saja aku tahu… Kenapa jadi begini?!",
  ui_story_2_14_26_option_content = "Tidak. Kita harus menyelamatkan Charon.",
  ui_story_2_14_27_dialog_content = "Apa kau sudah memikirkannya matang-matang, PlayerName?",
  ui_story_2_14_28_dialog_content = "Semua penduduk Undercity ada di sini! Kau pasti tahu akibatnya kalau kita gagal, 'kan?",
  ui_story_2_14_29_dialog_content = "Aku yakin kita bisa melakukannya!",
  ui_story_2_14_31_dialog_content = "Mungkin saja kepercayaan dirimu yang agak sembrono itu masih bisa menghasilkan keajaiban.",
  ui_story_2_14_32_dialog_content = "Itulah yang membuatmu berbeda dari orang-orang lain, PlayerName…",
  ui_story_2_15_1_dialog_content = "Officer Charon!",
  ui_story_2_15_X1_dialog_content = "Raawr!",
  ui_story_2_15_F1_dialog_content = "Sial, tak bisa mendekat!",
  ui_story_2_15_X2_dialog_content = "Vice! Jangan berbuat bodoh!",
  ui_story_2_15_X3_dialog_content = "Dasar sampah kotor! Biar kutunjukkan padamu!",
  ui_story_2_15_X4_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_2_15_A1_dialog_content = "Apa-apaan kau ini, Charon? Sinyalnya justru akan menarik lebih banyak Eclipsite!",
  ui_story_2_15_X6_dialog_content = "Letnan, tunggu apa lagi? Kekanak-kanakan sekali kau ini! Berhentilah menanggungnya sendirian! Kau malah menambah masalah!",
  ui_story_2_15_2_dialog_content = "Aku, Charon sang Acheron Ferryman, lambang kemegahan dan keindahan, tak akan memaklumi gangguan apa pun terhadap misi mulia ini!",
  ui_story_2_15_3_dialog_content = "Apa kau… sengaja melakukannya?",
  ui_story_2_15_4_dialog_content = "Teruskan, PlayerName! Jangan sampai kehebatanku mengalihkan perhatianmu!",
  ui_story_2_15_5_dialog_content = "Ini bukan saatnya pasang gaya, Officer Charon! Kita tak akan bisa lepas landas kalau kau tak…",
  ui_story_2_15_A2_dialog_content = "Tenanglah! Musuh seperti ini tak akan mampu mengalahkanku! Kau tahu itu, Vice!",
  ui_story_2_15_A3_dialog_content = "Kau hanya akan menghalangi, dan bahkan membuatku, sang Acheron Ferryman, Charon si Jagal Eclipsite, terbunuh!",
  ui_story_2_15_A4_dialog_content = "Charon…",
  ui_story_2_15_A5_dialog_content = "Bawa semua orang naik ke Colossus sekarang, Letnan. Ini perintah! Aku akan menyusul.",
  ui_story_2_15_A6_dialog_content = "… Siap, Pak. Bersiaplah untuk lepas landas, PlayerName…",
  ui_story_2_15_A7_dialog_content = "Lepas landas…",
  ui_story_2_15_A8_dialog_content = "Soroz, jangan kunci pintu naiknya. Charon mungkin akan sampai ke sini sewaktu-waktu!",
  ui_story_2_15_A9_dialog_content = "Kau yakin, PlayerName?",
  ui_story_2_15_A10_dialog_content = "… Apa maksudmu?",
  ui_story_2_15_A11_dialog_content = "Sepertinya… Sepertinya Charon tidak berusaha menyusul kita.",
  ui_story_2_15_A12_dialog_content = "Justru sebaliknya. Dia terbenam makin jauh dalam kepungan kawanan Eclipsite itu.",
  ui_story_2_15_A13_dialog_content = "Apa?! Dia…",
  ui_story_2_15_6_dialog_content = "Alarm apa itu?",
  ui_story_2_15_7_dialog_content = "Letnan! Itu protokol penghancuran diri. Charon sudah menekan Red Key!",
  ui_story_2_15_8_dialog_content = "Tak usah kaubilang pun, aku sudah tahu!",
  ui_story_2_15_A14_dialog_content = "Charon… Jangan-jangan kau memang berniat berbuat begitu…?",
  ui_story_2_15_9_dialog_content = "Kita sudah stabil untuk lepas landas! Aku akan ingat Aurorian itu. Duduklah kuat-kuat!",
  ui_story_2_15_10_option_content = "Kita berangkat!",
  ui_story_2_15_13_dialog_content = "Lambungnya retak! Ada sesuatu di bagian sayap putih besar, <color=#FFB400>dan terlalu berat…</color>",
  ui_story_2_15_14_dialog_content = "…",
  ui_story_2_15_15_option_content = "Kau baik-baik saja?",
  ui_story_2_15_17_dialog_content = "Sebaiknya kau pegangan, PlayerName, kita belum stabil!",
  ui_story_2_15_18_dialog_content = "Charon sudah menekan Red Key. Kita harus naik ke ketinggian aman sebelum Undercity… meledak.",
  ui_story_2_15_19_option_content = "Maafkan aku…",
  ui_story_2_15_20_option_content = "Tentang Charon…",
  ui_story_2_15_21_dialog_content = "Padahal aku sudah berjanji… aku tak akan meninggalkan siapa pun… Aku sudah berjanji…",
  ui_story_2_15_F2_dialog_content = "Ini bukan salahmu, PlayerName. Ini salahku.",
  ui_story_2_15_22_dialog_content = "Seandainya saja aku berusaha sedikit lebih keras lagi, bahkan walaupun sebatas mengambil rute lain, mungkin para Eclipsite itu tak akan membuat dia terpisah dari kita.",
  ui_story_2_15_23_dialog_content = "Tidak, harusnya sejak awal kita tidak berpencar dan meminta dia melindungi semua orang…",
  ui_story_2_15_24_dialog_content = "Sungguh momen yang menyentuh, dan aku nyaris saja melewatkannya.",
  ui_story_2_15_25_dialog_content = "Betapa tangguhnya, setidaknya lebih dari dugaanku.",
  ui_story_2_15_26_dialog_content = "Kau…?!",
  ui_story_2_15_27_dialog_content = "Menyerah sajalah. Tak ada gunanya melawan! Aku tak akan tertipu akal-akalanmu lagi…",
  ui_story_2_15_28_option_content = "Kenapa kau mengejarku?",
  ui_story_2_15_29_dialog_content = "Aku harus menuntaskan misiku.",
  ui_story_2_15_30_dialog_content = "Apa misiku? Mungkin menghancurkan semua orang yang tak beriman.",
  ui_story_2_15_31_option_content = "Sebenarnya apa yang kauinginkan?",
  ui_story_2_15_32_dialog_content = "Semuanya dilakukan demi misi kami.",
  ui_story_2_15_33_dialog_content = "Kekuatan kami berasal dari keyakinan kami.",
  ui_story_2_15_34_dialog_content = "Keyakinan kami berasal dari sang Bunda.",
  ui_story_2_15_35_dialog_content = "Kalian, Caelestite dan Aurorian, adalah kaum rendahan yang menggerogoti negeri ini. Harusnya kalian justru bersyukur karena kami membasmi kalian.",
  ui_story_2_15_36_dialog_content = "Lebih sia-sia lagi kalau kalian terus berusaha melawan. Itu hanya akan menunda hal yang tak bisa dihindari, seperti yang dialami prajurit bodoh itu.",
  ui_story_2_15_37_dialog_content = "Aurorian, kembalilah ke tanah agar kalian bisa mati dengan cepat.",
  ui_story_2_15_38_dialog_content = "Aku tak akan pernah menyerah! Tak akan kubiarkan kau melukai teman-temanku lagi!",
  ui_story_2_15_39_dialog_content = "Mau mati dengan terhormat dalam pertempuran? Baiklah.",
  ui_story_2_15_40_dialog_content = "Kalau begitu, akan kuberi kau kematian yang pantas karena kau begitu keras kepala.",
  ui_story_2_15_41_dialog_content = "Akan kusiksa kau sebrutal mungkin sampai mampus.",
  ui_story_2_15_89_dialog_content = "Master… Aku… gagal…",
  ui_story_2_15_91_dialog_content = "Ini tidak akan berakhir sampai sini saja… Percayalah…",
  ui_story_2_15_X92_dialog_content = "Apa kau mau dengar pengakuanku? Haha… hahahahahaha…",
  ui_story_2_15_X93_dialog_content = "Silakan nikmati kemenanganmu yang hanya sekejap ini!",
  ui_story_2_15_X94_dialog_content = "Saat Master menghadapi kalian, dia akan memberikan balasan yang pantas untuk kalian, kalian semua, termasuk kalian, para Aurorian, dan kau, Caelestite pengecut.",
  ui_story_2_15_X95_dialog_content = "Saat itu terjadi, tenggorokan kalian yang hina itu tak akan mampu mengerang sedikit pun…",
  ui_story_2_15_92_dialog_content = "Schummer… Ingat nama itu.",
  ui_story_2_15_93_dialog_content = "Kalian tak akan sanggup membayangkan betapa kuatnya dia.",
  ui_story_2_15_42_dialog_content = "Kali ini… Ini benar-benar berakhir.",
  ui_story_2_15_43_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_2_15_44_dialog_content = "Undercity 28… meledak…",
  ui_story_2_15_45_dialog_content = "<color=#e8d9bb>Fajar merekah seiring dengan padamnya ledakan, seakan-akan mengalunkan lagu penghormatan bagi mereka yang gugur dan menyambut datangnya hari baru…</color>",
  ui_story_2_15_46_dialog_content = "Selamat tinggal… Undercity 28 dan Charon…",
  ui_story_2_15_47_dialog_content = "Aku benar-benar minta maaf.",
  ui_story_2_15_48_dialog_content = "Ini pilihannya, PlayerName. Jangan salahkan dirimu.",
  ui_story_2_15_49_dialog_content = "Kenapa… Kenapa kau mengorbankan keselamatanmu sendiri demi melindungi kami? Kenapa kau harus pura-pura berani hingga saat-saat terakhir…",
  ui_story_2_15_51_option_content = "Dia pasti akan jadi teladan terhormat untuk kita semua, 'kan?",
  ui_story_2_15_52_dialog_content = "Kalau dia sudah mati, apa gunanya?",
  ui_story_2_15_B1_dialog_content = "\"Teladan\"? Apa artinya?",
  ui_story_2_15_B2_dialog_content = "Kalau aku tak salah, Charon melindungi apa yang berharga baginya.",
  ui_story_2_15_B3_dialog_content = "…",
  ui_story_2_15_B4_dialog_content = "Para prajuritnya, rekan-rekan kerjanya, teman-temannya… dan Undercity.",
  ui_story_2_15_53_option_content = "Dia akan tetap hidup dalam diri kita semua.",
  ui_story_2_15_54_dialog_content = "Tetap hidup dalam diri kita semua? Mungkin aku terdengar egois, tapi itu sama sekali bukan hidup, PlayerName.",
  ui_story_2_15_55_dialog_content = "Itu sama saja rasa sakit, tapi diderita oleh orang lain.",
  ui_story_2_15_B5_dialog_content = "Rasanya sama dengan rasa sakit yang selama ini kaurasakan. Memangnya kau mau menerima akhir seperti ini?",
  ui_story_2_15_B6_dialog_content = "Tapi, aku hanya bisa menerimanya…",
  ui_story_2_15_B7_dialog_content = "Setidaknya dia gugur karena melindungi apa yang berharga baginya, para prajurit dan orang-orang terkasihnya.",
  ui_story_2_15_B8_dialog_content = "Kita tak boleh mengecewakannya, Vice.",
  ui_story_2_15_B9_dialog_content = "Aku paham maksudmu, PlayerName, tapi saat ini pikiranku sedang kacau.",
  ui_story_2_15_B10_dialog_content = "Melindungi, berdedikasi… Sebagai anggota Illumina, tentu saja aku juga menghargai nilai-nilai ini.",
  ui_story_2_15_B11_dialog_content = "Tapi aku masih belum bisa menerima saat satu per satu temanku pergi dari sisiku.",
  ui_story_2_15_57_dialog_content = "Kami selalu bersorak, \"Jayalah Illumina!\" Tapi, apa kami benar-benar mampu menjadi Aurora dan mewujudkan masa depan yang lebih baik?",
  ui_story_2_15_58_dialog_content = "Kurasa, seandainya suatu hari nanti…",
  ui_story_2_15_59_dialog_content = "Seandainya suatu hari nanti kita dihadapkan pada pilihan yang sama…",
  ui_story_2_15_60_dialog_content = "Aku bahkan tak mau membayangkannya.",
  ui_story_2_15_61_dialog_content = "Harapan.",
  ui_story_2_15_62_dialog_content = "…?",
  ui_story_2_15_63_dialog_content = "Charon pernah bilang, \"Kalau tak bisa menghindari keputusasaan, kita harus mengatasi masa-masa sulit dengan harapan.\"",
  ui_story_2_15_66_option_content = "Sepertinya dia pasti akan bilang begitu.",
  ui_story_2_15_F3_dialog_content = "Aku akan selalu mengenang namanya, Charon sang Acheron Ferryman.",
  ui_story_2_15_F4_dialog_content = "The Acheron Ferryman…?",
  ui_story_2_15_F5_dialog_content = "Ada apa?",
  ui_story_2_15_70_dialog_content = "Kenapa Charon disebut The Acheron Ferryman?",
  ui_story_2_15_71_dialog_content = "Karena… keretanya yang serba megah. Kau sudah pernah melihatnya.",
  ui_story_2_15_72_dialog_content = "Sebagai mantan operator kereta, dia bisa kapan saja memanggil keretanya itu, Other End.",
  ui_story_2_15_73_dialog_content = "Ah!",
  ui_story_2_15_74_dialog_content = "Kereta? Tunggu… suar sinyal itu…",
  ui_story_2_15_79_dialog_content = "Jangan bilang dia…",
  ui_story_2_15_80_dialog_content = "Lt. Vice, PlayerName, lihat di atas sana!",
  ui_story_2_15_81_dialog_content = "<color=#FFB400>Yah, memang serba megah, ya</color>…",
  ui_story_2_15_82_dialog_content = "<size=45>Ini dia yang kusebut menutup tirai panggung dengan meeeegah!!</size>",
  ui_story_2_15_A15_dialog_content = "Kembang api, tepuk tangan, dan air mata kalian yang mengharukan. Kuterima semuanya dengan senang hati!",
  ui_story_2_15_83_dialog_content = "<size=45>Lihatlah, Charon sang Acheron Ferryman ada di sini!</size>",
  ui_story_2_15_84_dialog_content = "Apa di antara kalian ada yang menitikkan air mata untukku, para penontonku yang terkasih?",
  ui_story_2_15_F6_dialog_content = "Coba kita tanyai seorang penonton yang beruntung. Bagaimana menurutmu, PlayerName?",
  ui_story_2_15_X85_dialog_content = "Anu, tadi itu… pertunjukan yang memukau…",
  ui_story_2_15_85_dialog_content = "Bagus… sekali, Officer Charon…",
  ui_story_2_15_86_dialog_content = "Aku bingung aku harus senang atau marah…",
  ui_story_2_15_87_option_content = "Tadi itu keren… Aduh…",
  ui_story_2_15_88_dialog_content = "PlayerName?",
  ui_story_2_15_X88_dialog_content = "Pusing… Ini… muncul lagi…",
  ui_story_2_15_95_dialog_content = "Pemandangan yang familier itu…",
  ui_story_2_15_96_dialog_content = "Vice…",
  ui_story_2_15_100_dialog_content = "PlayerName, aku di sini! Tolong tetap sadar!",
  ui_story_2_15_101_dialog_content = "<color=#e8d9bb>Di luar puing-puing</color> <color=#FFB400>Colossus lain</color>",
  ui_story_2_15_102_dialog_content = "…",
  ui_story_2_15_103_dialog_content = "Kau baik-baik saja, Master?",
  ui_story_2_15_104_dialog_content = "Kenapa tanya begitu?",
  ui_story_2_15_105_dialog_content = "Perhatianmu teralihkan. Harusnya kau tetap fokus karena kau sudah begitu lama menunggu datangnya kesempatan ini…",
  ui_story_2_15_106_dialog_content = "Jangan main-main denganku. Jangan tanya hal-hal yang tak seharusnya kautanyakan, Eclipsite. Aku hanya… Mungkin itu tadi hanya ilusi.",
  ui_story_2_15_107_dialog_content = "Kalau begitu, semoga perburuanmu seru. Kuharap kau bisa menemukan apa yang kaucari.",
  ui_story_2_15_108_dialog_content = "Perburuan? Hmm, aku suka istilahmu itu.",
  ui_story_2_15_109_dialog_content = "Kau bisa dengar suaraku? Aku bisa merasakan keberadaanmu…",
  ui_story_2_15_110_dialog_content = "Sekarang kau pasti sudah tahu bahwa aku juga <color=#FFB400>Caelestite</color>. Tapi, waktuku hampir habis.",
  ui_story_2_15_111_dialog_content = "Aviduz, <color=#FFB400>wanita itu</color>… Kegelapan ngeri itu… Si pendosa yang membunuh kaumnya sendiri…",
  ui_story_2_15_112_dialog_content = "Dia berhasil menemukanku…",
  ui_story_2_15_113_dialog_content = "Aku dan Colossus milikku… sudah kehabisan waktu…",
  ui_story_3_1_1_dialog_content = "Bisakah kau mendengarku? Aku tak mengenalmu, tapi aku tahu kau juga seorang Caelestite.",
  ui_story_3_1_2_dialog_content = "Aku yakin kau bisa mendengarku.",
  ui_story_3_1_3_dialog_content = "Sinyalnya sudah dikirimkan. Semuanya, tetap tenang dan jangan pergi ke mana-mana.",
  ui_story_3_1_4_dialog_content = "Anu, Vice, si PlayerName itu sudah sadar!",
  ui_story_3_1_5_dialog_content = "Tapi, PlayerName sepertinya masih terkesima dengan pertunjukanku yang membahana.",
  ui_story_3_1_6_dialog_content = "Terima kasih banyak, Officer Charon. Nah, sekarang biarkan kami merawat lukamu!",
  ui_story_3_1_7_dialog_content = "Tidak, tidak, aku baik-baik saja. Sayang sekali aksi heroikku tak tertangkap kamera…",
  ui_story_3_1_8_dialog_content = "Sepertinya prioritasmu agak berantakan, ya…",
  ui_story_3_1_9_dialog_content = "Jelas bahwa kekuatan Red Key memang sangat menakjubkan. Jujur saja, sudah lama aku ingin menggunakannya…",
  ui_story_3_1_10_dialog_content = "Undercity 28 sekarang tinggal puing-puing, Officer Charon. Memangnya kau tidak… sedih?",
  ui_story_3_1_11_dialog_content = "Memang sangat disayangkan, tapi tak usah menangis! Kita masih punya <color=#FFB400>rumah</color>.",
  ui_story_3_1_12_dialog_content = "Rumah?",
  ui_story_3_1_13_dialog_content = "Ya. Lihat sekelilingmu.",
  ui_story_3_1_14_dialog_content = "Para warga, para prajurit… Aset paling berharga bagi Federation masih utuh.",
  ui_story_3_1_15_dialog_content = "Di mana ada orang-orang terkasih, di situlah rumah.",
  ui_story_3_1_F1_dialog_content = "Hmm…",
  ui_story_3_1_16_dialog_content = "Kau dan si Caelestite itu baik-baik saja, 'kan? Ini kedua kalinya aku menyelamatkanmu.",
  ui_story_3_1_F2_dialog_content = "Terima kasih, Pak…",
  ui_story_3_1_17_dialog_content = "Aku harus memeriksa situasi. Tunggu dengan sabar di sini, dan jangan kabur!",
  ui_story_3_1_18_dialog_content = "Baiklah…",
  ui_story_3_1_19_dialog_content = "Charon… ternyata tidak sesombong penampilannya.",
  ui_story_3_1_20_dialog_content = "Kau baik-baik saja, PlayerName? Kau agak…",
  ui_story_3_1_B1_dialog_content = "Ya, aku tak apa-apa.",
  ui_story_3_1_B2_dialog_content = "Kau tampak tidak begitu sehat, jangan paksakan dirimu.",
  ui_story_3_1_B3_dialog_content = "Terima kasih, Vice… karena selalu mendampingiku selama ini.",
  ui_story_3_1_B4_dialog_content = "Jelas, kita ini 'kan satu tim!",
  ui_story_3_1_B5_dialog_content = "Kita berhasil mengalahkan High-Level Eclipsite itu berkat dirimu!",
  ui_story_3_1_B6_dialog_content = "Ini baru <color=#FFB400>permulaan</color>, Vice.",
  ui_story_3_1_B7_dialog_content = "Hah? Permulaan?",
  ui_story_3_1_B8_dialog_content = "Sebelum Nozard tewas, dia menyebut nama itu lagi—<color=#FFB400>Schummer</color>.",
  ui_story_3_1_B9_dialog_content = "Schummer… Sebenarnya dia siapa, sih?",
  ui_story_3_1_B10_dialog_content = "Aku juga tak yakin, tapi kurasa dia pasti tahu seluruh kebenarannya.",
  ui_story_3_1_B11_dialog_content = "Maaf, Vice, tapi aku harus menemukan Schummer dan mencari tahu kebenarannya.",
  ui_story_3_1_B12_dialog_content = "Kenapa kau tiba-tiba jadi penuh motivasi begitu, PlayerName?",
  ui_story_3_1_B13_dialog_content = "Aku sudah menemukan \"<color=#FFB400>rumah</color>\" lagi.",
  ui_story_3_1_B14_dialog_content = "Apa kau tadi berbincang dengan Charon sementara aku sedang dalam masa pemulihan…",
  ui_story_3_1_B15_dialog_content = "Sayang sekali kita tak berhasil mengorek informasi lebih banyak tentang Schummer dari Nozard…",
  ui_story_3_1_B17_dialog_content = "Tak apa. Mungkin ada banyak berkas yang bisa kita periksa di Markas Illumina.",
  ui_story_3_1_B18_dialog_content = "Kenapa, PlayerName?",
  ui_story_3_1_B21_dialog_content = "Tolong…",
  ui_story_3_1_B22_dialog_content = "Cepat… Bisakah kau… mendengarku!?",
  ui_story_3_1_B23_dialog_content = "Apa kau merasakannya, PlayerName? Apa itu barusan?",
  ui_story_3_1_B24_dialog_content = "Ya. <color=#FFB400>Ada seseorang minta tolong</color>?",
  ui_story_3_1_21_dialog_content = "Aviduz sedang… Aku… kehabisan waktu…",
  ui_story_3_1_22_dialog_content = "Kau dengar sesuatu, 'kan?",
  ui_story_3_1_23_option_content = "Ini pasti telepati Caelestite!",
  ui_story_3_1_24_dialog_content = "Orang yang berhasil selamat <color=#FFB400>sepertiku</color>? Caelestite lain?!",
  ui_story_3_1_25_dialog_content = "Ya. Dan dari pesannya, dia sedang dalam bahaya besar.",
  ui_story_3_1_26_dialog_content = "Mungkin dia seperti kita…",
  ui_story_3_1_27_option_content = "Itu suara anak lelaki",
  ui_story_3_1_28_dialog_content = "Ya, kesadarannya dipenuhi rasa takut, jadi pasti keadaannya sangat buruk.",
  ui_story_3_1_F3_dialog_content = "Komunikasi psikis… Apa dia seorang Caelestite?!",
  ui_story_3_1_29_dialog_content = "Ya, tapi sinyal dari Colossus-nya sangat lemah sehingga aku tak bisa memastikannya.",
  ui_story_3_1_30_dialog_content = "Dia minta bantuan. Sesuatu yang buruk sedang menimpa dirinya dan Colossus-nya.",
  ui_story_3_1_31_dialog_content = "<color=#FFB400>Caelestite lain</color>?",
  ui_story_3_1_32_dialog_content = "Tunggu, maksudmu kau bisa mencari Colossus lain melalui dia?",
  ui_story_3_1_33_dialog_content = "Kau bisa bantu aku, Vice?",
  ui_story_3_1_34_dialog_content = "…",
  ui_story_3_1_35_dialog_content = "Ada yang perlu kausampaikan padaku, Letnan?",
  ui_story_3_1_36_dialog_content = "Anu, kami…",
  ui_story_3_1_37_dialog_content = "Kami menerima sinyal minta bantuan dari Caelestite lain!",
  ui_story_3_1_38_dialog_content = "…?!",
  ui_story_3_1_39_dialog_content = "Dua Caelestite? Sebenarnya ada apa ini?",
  ui_story_3_1_40_dialog_content = "Aku bisa memastikan bahwa komunikasi psikisnya sama persis denganku!",
  ui_story_3_1_41_dialog_content = "Di mana dia? Apa di dekat sini?",
  ui_story_3_1_42_dialog_content = "Aku tak yakin… Tapi aku tahu perkiraan lokasinya. Kita harus ke sana sekarang!",
  ui_story_3_1_43_dialog_content = "…",
  ui_story_3_1_44_dialog_content = "Itu tak akan ada gunanya.",
  ui_story_3_1_45_dialog_content = "Pak!",
  ui_story_3_1_46_dialog_content = "Benar-benar berantakan.. Benar-benar tidak disiplin.. Tahu tidak, berapa banyak masalah yang sudah kautimbulkan!?",
  ui_story_3_1_47_dialog_content = "Tapi…",
  ui_story_3_1_48_dialog_content = "Semua orang melihatmu, jadi coba jangan buat mereka makin panik sekarang.",
  ui_story_3_1_49_dialog_content = "Lagi pula, atasan langsungmu, Hiiro, Commander dari 3rd Legion, hampir sampai sini.",
  ui_story_3_1_50_dialog_content = "Bukannya kau harus melaporkan situasi terbaru kepadanya?",
  ui_story_3_1_51_dialog_content = "…",
  ui_story_3_1_52_dialog_content = "Tapi kita tak bisa buang-buang waktu lagi.",
  ui_story_3_1_53_dialog_content = "Kapan lagi kita bisa dapat petunjuk seperti ini?",
  ui_story_3_1_54_dialog_content = "Dan sepertinya dia benar-benar butuh bantuan! Aku yakin dia sedang dalam bahaya besar!",
  ui_story_3_1_55_dialog_content = "Dia salah satu kaumku, Charon. Caelestite sungguhan, dan masih hidup!",
  ui_story_3_1_56_dialog_content = "…",
  ui_story_3_1_57_dialog_content = "Pak…",
  ui_story_3_1_58_dialog_content = "Aku paham betapa pentingnya ini untukmu, PlayerName.",
  ui_story_3_1_59_dialog_content = "Tapi, Illumina Federation juga punya aturan disiplin sendiri, terutama selama aku masih bertugas.",
  ui_story_3_1_60_dialog_content = "Kecuali…",
  ui_story_3_1_61_dialog_content = "…!",
  ui_story_3_1_62_dialog_content = "Kecuali kalau aku tak diberi tahu tentang tindakanmu.",
  ui_story_3_1_63_dialog_content = "Hah?",
  ui_story_3_1_64_dialog_content = "Pangkatmu letnan, 'kan, Vice? Dan kau bukan bawahan langsungku.",
  ui_story_3_1_A1_dialog_content = "Jadi, kau juga punya hak untuk mengambil keputusan, asalkan kau tidak membahayakan Illumina Federation.",
  ui_story_3_1_A2_dialog_content = "Tapi, sekali lagi kutekankan, Illumina Federation selalu mengawasi.",
  ui_story_3_1_A3_dialog_content = "Aku tahu apa yang harus kita lakukan, Vice.",
  ui_story_3_1_65_dialog_content = "Punya ide?",
  ui_story_3_1_B25_option_content = "Kita menyelinap diam-diam saja.",
  ui_story_3_1_B26_option_content = "Kreatif, dong. Kita lakukan dengan cara mencolok saja sekalian.",
  ui_story_3_1_66_dialog_content = "Jangan bilang begitu di hadapan Officer atasan, PlayerName.",
  ui_story_3_1_67_dialog_content = "Hah? Kau tadi bilang apa? Anginnya kencang sekali, suaramu tidak terdengar.",
  ui_story_3_1_68_dialog_content = "…",
  ui_story_3_1_B26_dialog_content = "Maksudmu, kau menyarankan bahwa kita harus…",
  ui_story_3_1_B27_dialog_content = "Saran? Aku tak menyarankan apa pun! Apa maksudmu?",
  ui_story_3_1_B28_dialog_content = "Aku hanya mengingatkanmu bahwa sebagai seorang letnan, kau punya beberapa pilihan, Vice.",
  ui_story_3_1_B29_dialog_content = "Terserah kau mau memutuskan akan berbuat apa.",
  ui_story_3_1_B30_dialog_content = "Aku paham, Pak. Terima kasih.",
  ui_story_3_1_B31_dialog_content = "Hiiro akan segera sampai sini. Kalau kau mau berbuat sesuatu tanpa sepengetahuanku, sebaiknya lakukan sekarang.",
  ui_story_3_1_B32_dialog_content = "Kalau tidak, kau terpaksa harus tetap di sini dan memberitahukannya kepadanya saat dia tiba nanti.",
  ui_story_3_1_B33_dialog_content = "Charon… memang penuh kejutan.",
  ui_story_3_1_B34_dialog_content = "Wow… Aku gugup. Aku penasaran kira-kira bagaimana reaksi Commander Hiiro nanti…",
  ui_story_3_1_B35_dialog_content = "Lakukan dengan cara mencolok?",
  ui_story_3_1_B36_dialog_content = "Ehem!",
  ui_story_3_1_B37_dialog_content = "Oh, Charon, aku ingin bilang sesuatu, tapi tak yakin apa aku boleh mengatakannya.",
  ui_story_3_1_B38_dialog_content = "Silakan, sampaikan saja, Caelestite!",
  ui_story_3_1_B39_dialog_content = "Soroz baru saja memberitahuku bahwa sekawanan besar Eclipsite mengikuti jejak Colossus dan langsung menuju kemari!",
  ui_story_3_1_B40_dialog_content = "Hah? Ah?",
  ui_story_3_1_B41_dialog_content = "Apa!? Aura Colossus itu justru membuat lebih banyak Eclipsite tertarik kemari!?",
  ui_story_3_1_B42_dialog_content = "Kenapa tak bilang dari tadi!? Itu bahaya sekali!",
  ui_story_3_1_B43_dialog_content = "???",
  ui_story_3_1_B44_dialog_content = "(Bekerja samalah denganku, Vice, ikuti saja!)",
  ui_story_3_1_B45_dialog_content = "Ah… Oh! Maaf, aku.. aku sendiri juga baru saja menyadarinya…",
  ui_story_3_1_B46_dialog_content = "Astaga! Maksudku, kita baru saja lepas dari mulut singa, sekarang malah masuk mulut harimau!",
  ui_story_3_1_B47_dialog_content = "Tak akan kubiarkan orang-orangku menghadapi bahaya sebesar itu!",
  ui_story_3_1_B48_dialog_content = "Ah, jadi… Apa yang harus kita lakukan!?",
  ui_story_3_1_B49_dialog_content = "Arahkan Colossus itu menjauh dari sini! Jauhkan dia dari warga sipil yang tak tahu apa-apa!",
  ui_story_3_1_B50_dialog_content = "Ya!",
  ui_story_3_1_B51_dialog_content = "(Sana, cepat!)",
  ui_story_3_1_B52_dialog_content = "Terima kasih, Officer Charon.",
  ui_story_3_1_B53_dialog_content = "… Hmm.",
  ui_story_3_1_B55_dialog_content = "Lawakan tadi… Memangnya perlu…",
  ui_story_3_1_B56_dialog_content = "Aku tak tahu, tapi sepertinya Charon juga menyukainya.",
  ui_story_3_1_B57_dialog_content = "Tapi kita butuh alasan untuk pergi sebelum atasan langsungmu tiba.",
  ui_story_3_1_B58_dialog_content = "Benar… Hiiro…",
  ui_story_3_1_B59_dialog_content = "*Berdesah* Aku merinding sendiri membayangkan reaksi Commander Hiiro nantinya setelah tahu bahwa kita pergi tanpa izin.",
  ui_story_3_1_69_option_content = "Menyesal, nih?",
  ui_story_3_1_70_dialog_content = "Tidak!",
  ui_story_3_1_71_dialog_content = "Yah, semoga saja Hiiro adalah atasan yang simpatik.",
  ui_story_3_1_72_dialog_content = "Nah, karena kau malah bilang begitu, sekarang aku jadi agak menyesal.",
  ui_story_3_1_73_option_content = "Kuharap kita mengambil pilihan yang tepat",
  ui_story_3_1_74_dialog_content = "Tepat atau tidak… mungkin bukan kita yang menentukan…",
  ui_story_3_1_76_dialog_content = "Oh, tidak, Commander Hiiro pasti akan membunuhku!",
  ui_story_3_1_77_dialog_content = "Tujuan: Lokasi asal sinyal dari Caelestite tak dikenal. Menghitung mundur!",
  ui_story_3_1_78_dialog_content = "5, 4, 3, 2…",
  ui_story_3_1_79_dialog_content = "1! Lepas landas!",
  ui_story_3_1_80_dialog_content = "Ini laporan insiden yang kauminta. Silakan dibaca…",
  ui_story_3_1_81_dialog_content = "Biar kubaca… Oh, ya, oh, ya. Perlu peningkatan di sini…",
  ui_story_3_1_82_dialog_content = "Jelaskan lebih banyak tentang Vice dan Caelestite itu, cari hubungan antara tindakan mereka dan apa yang terjadi di sini.",
  ui_story_3_1_83_dialog_content = "Ah, siap, Pak!",
  ui_story_3_1_84_dialog_content = "Percayalah padaku, kau tak akan suka kalau wanita itu sampai bawel meminta informasi detail.",
  ui_story_3_1_85_dialog_content = "Ini tidak seperti yang kubayangkan, Charon.",
  ui_story_3_1_86_dialog_content = "…",
  ui_story_3_1_87_dialog_content = "Kalau kau mencari-cari Undercity 28, tempat itu sekarang sudah jadi puing-puing di bawah kakimu itu, Legion Commander.",
  ui_story_3_1_88_dialog_content = "Jangan mengulangi apa yang sudah kuketahui, Charon. Di mana Colossus yang tadi kausebutkan dalam briefing-mu?",
  ui_story_3_1_89_dialog_content = "Burung itu pergi dengan gaya.",
  ui_story_3_1_90_dialog_content = "Di mana bawahanku?",
  ui_story_3_1_91_dialog_content = "Dia sudah pergi. Dia naik Colossus itu.",
  ui_story_3_1_92_dialog_content = "Supervisor Charon dari Undercity 28, maksudmu bawahanku menentang perintahku?",
  ui_story_3_1_93_dialog_content = "Aku hanya bilang dia bersama Caelestite itu.",
  ui_story_3_1_94_dialog_content = "Caelestite…",
  ui_story_3_1_95_dialog_content = "Officer, kami… Maaf menyela, Legion Commander!",
  ui_story_3_1_96_dialog_content = "Lanjutkan.",
  ui_story_3_1_97_dialog_content = "Siap! Kami sudah selesai menilai kerusakan dan status warga sipil. Kami menunggu perintah berikutnya darimu!",
  ui_story_3_1_98_dialog_content = "Ikuti rencana dan evakuasi mereka ke Undercity terdekat. Akan kuminta Batalion 1 dan 3 untuk mengawal mereka.",
  ui_story_3_1_99_dialog_content = "Kami bisa melindungi warga sipil sendiri. Kau tak usah repot-repot…",
  ui_story_3_1_100_dialog_content = "Yang lainnya, ikut aku.",
  ui_story_3_1_101_dialog_content = "…",
  ui_story_3_1_102_dialog_content = "Masih saja suka bersungut-sungut seperti biasa, Hiiro.",
  ui_story_3_1_103_dialog_content = "Sedang apa kau?",
  ui_story_3_1_104_dialog_content = "Aku?",
  ui_story_3_1_A4_dialog_content = "Apa ini, alat masak?",
  ui_story_3_1_A5_dialog_content = "… Ini komunikator jarak jauh ringkas.",
  ui_story_3_1_105_dialog_content = "Memangnya Illumina punya perangkat seperti ini? Kok aku belum pernah melihatmu menggunakannya?",
  ui_story_3_1_106_dialog_content = "Tadi Charon diam-diam memberikannya untukku.",
  ui_story_3_1_107_dialog_content = "Charon…",
  ui_story_3_1_108_dialog_content = "Nah, bagaimana cara kerjanya? Ya ampun, susah amat, sih!",
  ui_story_3_1_109_dialog_content = "Sepertinya harus kausilangkan di sini, lingkarkan memutar, lalu setel frekuensinya…",
  ui_story_3_1_111_dialog_content = "A-ha, bisa!",
  ui_story_3_1_112_dialog_content = "Sebutkan lokasimu saat ini.",
  ui_story_3_1_113_dialog_content = "Siap…! Commander Hiiro?",
  ui_story_3_1_114_dialog_content = "Rupanya kau masih mengenali atasanmu, Letnan. Kenapa kau pergi tanpa izin?",
  ui_story_3_1_115_dialog_content = "Maaf. Eclipsite berhasil menembus masuk Undercity 28, dan protokol penghancuran diri diaktifkan.",
  ui_story_3_1_116_dialog_content = "Jangan mengulangi hal yang sudah kuketahui. Aku tanya, kenapa kau pergi tanpa izin bersama Colossus itu.",
  ui_story_3_1_117_dialog_content = "Colossus itu… Aku…",
  ui_story_3_1_118_dialog_content = "Begini, Nona, Colossus itu bukan milikmu. Kita harus perjelas hal itu, ya.",
  ui_story_3_1_119_dialog_content = "Rupanya kau…",
  ui_story_3_1_120_dialog_content = "Ya, aku pemilik Colossus ini.",
  ui_story_3_1_122_dialog_content = "Gara-gara kau dan Colossus-mu yang berharga itu, Undercity 28 kini musnah.",
  ui_story_3_1_A6_dialog_content = "Bukankah harusnya kau menjelaskannya kepada Illumina Federation?",
  ui_story_3_1_123_dialog_content = "Aku benar-benar minta maaf, tapi aku akan berusaha menebusnya untuk Illumina!",
  ui_story_3_1_124_dialog_content = "Nozard juga menyebutkan seseorang bernama <color=#FFB400>Schummer</color>.",
  ui_story_3_1_125_dialog_content = "Nozard, Schummer… Aku tak tertarik dengan nama-nama aneh itu.",
  ui_story_3_1_126_dialog_content = "Tapi, semuanya… dan Undercity 28, mungkin ini semua ada hubungannya dengan Schummer!",
  ui_story_3_1_127_dialog_content = "Oh?",
  ui_story_3_1_128_dialog_content = "Madam, kami punya petunjuk tentang Caelestite lain lagi, yang mungkin bisa mengarahkan kita untuk menemukan Colossus lain!",
  ui_story_3_1_129_dialog_content = "Apa kaubilang!?",
  ui_story_3_1_130_dialog_content = "Tapi Caelestite itu dan Colossus-nya sedang dalam masalah besar!",
  ui_story_3_1_131_dialog_content = "PlayerName ingin berbuat sesuatu untuk membantu, jadi kupikir…",
  ui_story_3_1_132_dialog_content = "Aku harus membantunya! Ini juga penting untuk Illumina!",
  ui_story_3_1_133_dialog_content = "Aku harus mengingatkanmu, Letnan…",
  ui_story_3_1_A7_dialog_content = "Sekarang kau ini prajurit Illumina Federation, jadi pertimbangkan ulang!",
  ui_story_3_1_134_dialog_content = "Maaf, Madam. Aku sudah berusaha menghentikan PlayerName, tapi kurasa kali ini PlayerName benar!",
  ui_story_3_1_135_dialog_content = "Vice…?",
  ui_story_3_1_136_dialog_content = "PlayerName benar… kali ini.",
  ui_story_3_1_137_dialog_content = "Aku akan menyelamatkan Caelestite itu dan mencari penjelasan untuk semua ini.",
  ui_story_3_1_A8_dialog_content = "…",
  ui_story_3_1_A9_dialog_content = "…",
  ui_story_3_1_138_dialog_content = "*Berdesah* Kamu benar-benar yakin?",
  ui_story_3_1_139_dialog_content = "Aku tak akan membiarkan para Eclipsite itu kabur lagi!",
  ui_story_3_1_140_dialog_content = "Kirimi aku koordinatnya, sekarang juga.",
  ui_story_3_1_141_dialog_content = "Sinyalmu tidak stabil. Kami tak bisa melacak posisimu.",
  ui_story_3_1_142_dialog_content = "Oh, ya, Vice, jangan lupa kau ada di pihak mana, dan jangan berbuat bodoh.",
  ui_story_3_1_144_dialog_content = "Kita kehilangan sinyalnya!",
  ui_story_3_1_145_dialog_content = "Aku merasakan sesuatu yang kuat dan mendominasi, beda dengan yang kita hadapi sebelumnya.",
  ui_story_3_1_146_dialog_content = "Saat minta tolong tadi, Caelestite itu menyebut <color=#FFB400>Aviduz</color>.",
  ui_story_3_1_A10_dialog_content = "Diakah itu?",
  ui_story_3_1_147_dialog_content = "Aku tak tahu, PlayerName, tapi kekuatan ini sangat besar, di…",
  ui_story_3_1_148_dialog_content = "Ya, di sana!",
  ui_story_3_1_A11_dialog_content = "Soroz berhasil menemukan lokasinya, Vice. Aviduz mungkin ada di dalam sana.",
  ui_story_3_1_A12_dialog_content = "Kita tak punya cukup banyak informasi, hati-hati di sana.",
  ui_story_3_1_149_dialog_content = "Aviduz? Apa ini Colossus itu?",
  ui_story_3_1_150_dialog_content = "Untuk saat ini, aku belum yakin.",
  ui_story_3_1_151_dialog_content = "Eh…",
  ui_story_3_1_152_dialog_content = "PlayerName, kalau aku menghentikanmu sekarang, apa kamu mau mendengarkanku?",
  ui_story_3_1_153_dialog_content = "Maaf, Soroz.",
  ui_story_3_1_154_dialog_content = "Memang sudah kuduga…",
  ui_story_3_1_155_dialog_content = "Mendaratlah sekarang dan bersiaplah untuk bertempur.",
  ui_story_3_1_A13_dialog_content = "Sepertinya kita sudah ditunggu sejumlah Eclipsite!",
  ui_story_3_3_1_dialog_content = "Ada yang datang.",
  ui_story_3_3_2_dialog_content = "Orang bego mana yang berani-beraninya mengusikku?",
  ui_story_3_3_3_dialog_content = "Apa perlu kutangani?",
  ui_story_3_3_4_dialog_content = "Jangan sekarang. Kita di sini karena ada urusan yang lebih penting.",
  ui_story_3_3_5_dialog_content = "Schummer… Sedang apa kau di sini?",
  ui_story_3_3_6_dialog_content = "Nah, ini dia adikku yang menggemaskan! Kukira kau akan kabur seperti dulu.",
  ui_story_3_3_7_dialog_content = "Master si <color=#FFB400>Mantiz</color>.",
  ui_story_3_3_8_dialog_content = "Oh, sebentar, harusnya aku memanggilmu dengan nama julukanmu yang imut, <color=#FFB400>Mendelson</color> si Pengecut.",
  ui_story_3_3_9_dialog_content = "Iyuh, aku tak percaya aroma yang pertama kucium setelah bangun ternyata baumu yang menjijikkan itu, Schummer.",
  ui_story_3_3_10_dialog_content = "Atau, mungkin kau lebih suka kusebut <color=#FFB400>Master si Aviduz</color>?",
  ui_story_3_3_11_dialog_content = "Karena kau ini adikku, aku tak akan bertele-tele.",
  ui_story_3_3_12_dialog_content = "Antar aku mencari <color=#FFB400>benda itu</color>.",
  ui_story_3_3_A1_dialog_content = "Aku tak paham maksudmu. Aku tak punya apa-apa di sini, Schummer, selain sejarah membosankan…",
  ui_story_3_3_A2_dialog_content = "Dan rahasia kotor. Jangan kira aku tak tahu, ya.",
  ui_story_3_3_A3_dialog_content = "Serahkan <color=#FFB400>Think Tank Module</color> itu padaku. Aku tahu kau punya satu di sini.",
  ui_story_3_3_A4_dialog_content = "… Mau apa kau dengan benda itu?",
  ui_story_3_3_A5_dialog_content = "Oh, hanya mau mencari beberapa… info rahasia yang menarik untukku.",
  ui_story_3_3_A6_dialog_content = "Tidak, kalau itu niatmu, aku tak akan pernah menyerahkannya.",
  ui_story_3_3_A7_dialog_content = "Perbuatanmu ini jelas-jelas dilarang dan bertentangan dengan prinsip Colossus!",
  ui_story_3_3_13_dialog_content = "Dan kau malah ingin aku mengantarmu ke sana?",
  ui_story_3_3_14_dialog_content = "Kau pasti salah memahami tujuan Mantiz, Schummer.",
  ui_story_3_3_15_dialog_content = "Ayolah, Mendelson, jangan pelit begitu.",
  ui_story_3_3_16_dialog_content = "Bukannya kita ada di pihak yang sama? Kalau tidak, tak mungkin kau masih bertahan hidup sampai sekarang.",
  ui_story_3_3_17_dialog_content = "Itu kekuatan yang tak mungkin dimiliki Caelestite. Kau dan aku, kita ini sama saja.",
  ui_story_3_3_18_dialog_content = "Dan aku terus-menerus menyesalinya sejak itu, Schummer… Seandainya saja aku tahu…",
  ui_story_3_3_19_dialog_content = "Hmm…? Kesehatanmu sepertinya menurun…",
  ui_story_3_3_A8_dialog_content = "Mendelson yang malang… Sepertinya kau belum menerima berkat itu seluruhnya.",
  ui_story_3_3_20_dialog_content = "Aku sedih melihatmu kesulitan bicara seperti itu!",
  ui_story_3_3_22_dialog_content = "Di mana paluku kuhantamkan, di situlah akan ada kematian. Hentikan penerbanganmu.",
  ui_story_3_3_23_dialog_content = "Paham tidak? Kalau berani melewati garis itu, tamat riwayatmu.",
  ui_story_3_3_24_dialog_content = "Aku tak punya kemampuan bertarung yang bisa kusombongkan, tapi Mantiz ini sama sekali tak pantas dicemooh…",
  ui_story_3_3_25_dialog_content = "Memanfaatkan manusia sebagai tameng. Begitukah cara pengecut berlindung?",
  ui_story_3_3_26_dialog_content = "Jangan remehkan aku, Schummer!",
  ui_story_3_3_27_dialog_content = "Perlu kutangani ini, Lady?",
  ui_story_3_3_A9_dialog_content = "Untuk terakhir kalinya, tidak! Ini sama sekali bukan urusanmu!",
  ui_story_3_3_28_dialog_content = "Anak kucing dan anak anjing yang setia. Cocok sekali, Mendelson.",
  ui_story_3_3_29_dialog_content = "Tapi, itu jugalah yang membuatmu jadi pengecut tak berguna selama ini.",
  ui_story_3_3_30_dialog_content = "Dasar kurang ajar!",
  ui_story_3_3_31_dialog_content = "Cukup. Berlututlah!",
  ui_story_3_3_32_dialog_content = "Lumpuh! Lumpuh! Perintah prioritas tertinggi diterima, wajib dijalankan!",
  ui_story_3_3_33_dialog_content = "Philex! Sesuatu terjadi kepadanya, Master!",
  ui_story_3_3_34_dialog_content = "Aghhh…",
  ui_story_3_3_35_dialog_content = "Vani, Philex… Apa-apaan ini? Kauapakan mereka, Schummer!?",
  ui_story_3_3_36_dialog_content = "\"Mainan\"-mu ini lucu juga, Mendelson.",
  ui_story_3_3_37_dialog_content = "Jadi, kuputuskan mereka akan jadi milikku.",
  ui_story_3_3_38_dialog_content = "Ternyata yang sudah tersesat bukan hanya tubuh dan jiwamu, Schummer… Kau benar-benar sudah jadi setan!",
  ui_story_3_3_39_dialog_content = "Terima kasih atas pujianmu, tapi niatku tak akan berubah.",
  ui_story_3_3_40_dialog_content = "Kembalikan mereka kepadaku, dasar monster!",
  ui_story_3_3_41_dialog_content = "Nah, kalau yang itu bisa kulakukan untukmu! Philex, Vani… Itu nama kalian, 'kan?",
  ui_story_3_3_42_dialog_content = "Ya!",
  ui_story_3_3_43_dialog_content = "Tangkap Mendelson.",
  ui_story_3_3_44_dialog_content = "Apa?!",
  ui_story_3_3_45_dialog_content = "Cih, lagi-lagi dia berhasil lolos!",
  ui_story_3_3_46_dialog_content = "\"Jangan remehkan aku,\" katanya… Ternyata dia masih pengecut seperti dulu.",
  ui_story_3_3_47_dialog_content = "Apa yang harus kulakukan selanjutnya, Lady?",
  ui_story_3_3_48_dialog_content = "Kejar dan bawa dia kemari…",
  ui_story_3_3_49_dialog_content = "Agar aku bisa melihat raut wajahnya dengan cermat.",
  ui_story_3_3_50_dialog_content = "Ya!",
  ui_story_3_3_51_dialog_content = "Ya!",
  ui_story_3_3_52_dialog_content = "Aku tak boleh sampai tertangkap… Hei, aku tahu kau bisa mendengarku… Cepat kemari…",
  ui_story_3_3_53_dialog_content = "Aku bisa mendengarmu! Di mana kau? Kau juga seorang Caelestite, 'kan?",
  ui_story_3_3_54_dialog_content = "Aviduz kini makin kuat…",
  ui_story_3_3_55_dialog_content = "Jangan sampai dia merebut Think Tank Module itu, jangan sampai… rahasia itu jatuh ke tangannya…",
  ui_story_3_3_56_dialog_content = "Kau tak akan pernah bisa meninggalkanku. Aku sedih melihatmu kesulitan bicara seperti itu.",
  ui_story_3_3_57_dialog_content = "Kau tak bisa kabur begitu saja, Schummer, tak akan pernah bisa…",
  ui_story_3_3_58_dialog_content = "Kau tak boleh meninggalkanku.",
  ui_story_3_3_59_dialog_content = "Tapi 'kan kau sudah menang? Sejak awal.",
  ui_story_3_3_60_dialog_content = "Kau menggunakan kekuatan jahat untuk menghancurkanku, menghentikanku agar aku tak menghentikanmu…",
  ui_story_3_3_61_dialog_content = "Tidak, aku harus menghentikamu… Ini tugasku dan Mantiz.",
  ui_story_3_3_62_dialog_content = "Sejak dulu kau memang pengecut ingusan.",
  ui_story_3_3_63_dialog_content = "Harusnya aku tetap hidup, atau binasa saja…?",
  ui_story_3_3_64_dialog_content = "(Eclipsian) Di sana! Tangkap mereka!",
  ui_story_3_3_65_dialog_content = "Apa kau di sana, Caelestite? Aku harus terus berlari!",
  ui_story_3_3_66_dialog_content = "Tolong, cepatlah… Demi aku, dan demi dirimu sendiri!",
  ui_story_3_3_A10_dialog_content = "Dia dikejar Eclipsite, dan aku tak bisa memastikan lokasi persisnya…",
  ui_story_3_3_A11_dialog_content = "Paham. Ayo bergegas!",
  ui_story_3_3_A12_dialog_content = "Jumlah Eclipsite di depan sana makin banyak, PlayerName. Tetap waspada!",
  ui_story_3_7_1_dialog_content = "Tempat ini juga dipenuhi kerumunan Eclipsite. Kau baik-baik saja, PlayerName?",
  ui_story_3_7_2_dialog_content = "Aku baik-baik saja.",
  ui_story_3_7_3_dialog_content = "Aku penasaran apakah Caelestite yang kausebut itu…",
  ui_story_3_7_4_dialog_content = "Tunggu!",
  ui_story_3_7_5_dialog_content = "Jangan sampai mereka menangkapku… Tidak…",
  ui_story_3_7_6_dialog_content = "Kami sudah masuk! Di mana kau? Kau bisa mendengarku?",
  ui_story_3_7_7_dialog_content = "Kemarilah! Aku bisa melindungimu!",
  ui_story_3_7_8_dialog_content = "Rupanya kau, sesama Caelestite! Kau sudah sampai!",
  ui_story_3_7_9_dialog_content = "Maaf, aku terlambat!! Kau bisa mendengarku?!",
  ui_story_3_7_10_dialog_content = "Tentu saja, Caelestite, tentu saja bisa. Aku bahkan bisa melihatmu. Kaukah itu…?",
  ui_story_3_7_16_dialog_content = "Siapa di sana?",
  ui_story_3_7_17_dialog_content = "*Batuk-batuk* Musuh, di belakang…",
  ui_story_3_7_18_dialog_content = "Kau baik-baik saja? Bagus, untunglah kami sampai tepat waktu!",
  ui_story_3_7_A5_dialog_content = "Apa ini…?",
  ui_story_3_7_A6_dialog_content = "Ya, Vice, dialah Caelestite yang meminta bantuan kita!",
  ui_story_3_7_19_dialog_content = "Keadaannya agak buruk, PlayerName, dan luka-luka ini bukan disebabkan oleh Eclipsite.",
  ui_story_3_7_20_dialog_content = "Siapa yang melakukannya padamu?",
  ui_story_3_7_22_dialog_content = "Target Mendelson ditemukan!",
  ui_story_3_7_23_dialog_content = "Menjalankan perintah penangkapan!",
  ui_story_3_7_24_dialog_content = "Philex, Vani…",
  ui_story_3_7_25_dialog_content = "Berlindunglah, Caelestite!",
  ui_story_3_7_26_dialog_content = "Urus dia, PlayerName. Kami akan tangani pertarungannya!",
  ui_story_3_7_27_dialog_content = "Philex, Vani…",
  ui_story_3_7_28_dialog_content = "Maafkan aku… Sampai akhir pun aku tetap tak bisa berbuat apa-apa…",
  ui_story_3_7_29_dialog_content = "Sepertinya mereka bukan Eclipsite. Ada apa ini?",
  ui_story_3_7_30_dialog_content = "Mereka ini pengawalku, bagian dari mekanisme pertahanan di Colossus ini.",
  ui_story_3_7_31_dialog_content = "Tapi, kenapa mereka malah menyerangmu?",
  ui_story_3_7_32_dialog_content = "Ini ulahnya… Dia mengendalikan mereka dengan kekuatannya.",
  ui_story_3_7_33_dialog_content = "Sulit dipercaya…",
  ui_story_3_7_34_dialog_content = "Aku paham perasaanmu…",
  ui_story_3_7_35_dialog_content = "Aku tak pernah menyangka keadaan akan sama seperti dulu…",
  ui_story_3_7_36_dialog_content = "Siapa namamu, Caelestite?",
  ui_story_3_7_37_dialog_content = "Aku Mendelson, Master-nya Mantiz.",
  ui_story_3_7_38_dialog_content = "Mantiz… Nama itu terdengar familier. Sayangnya, aku sudah lupa…",
  ui_story_3_7_40_dialog_content = "Hari itu, untuk melindungi Spark, para Colossus yang berhasil selamat memutuskan untuk pergi berpencar.",
  ui_story_3_7_41_dialog_content = "Sepertinya selama ini Soroz melindungimu… Bagus.",
  ui_story_3_7_42_dialog_content = "Sudah berapa lama kau di sini? Adakah Caelestite lain yang masih hidup?",
  ui_story_3_7_43_dialog_content = "Kenapa kau jadi seperti ini? Dan siapa itu Aviduz?",
  ui_story_3_7_44_dialog_content = "*Batuk-batuk* Aku… *Batuk-batuk*",
  ui_story_3_7_45_dialog_content = "Dia cedera, PlayerName. Biarkan dia atur napas dulu.",
  ui_story_3_7_46_dialog_content = "Maafkan aku, aku tidak seperti kalian… PlayerName, Soroz…",
  ui_story_3_7_47_dialog_content = "Kau masih hidup. Itu berarti Soroz sudah memenuhi tugasnya untuk melindungi Caelestite.",
  ui_story_3_7_48_dialog_content = "Tapi, aku justru gagal menuntaskan satu-satunya misiku…",
  ui_story_3_7_49_dialog_content = "Maaf, aku tak paham.",
  ui_story_3_7_50_dialog_content = "Memangnya Soroz belum memberitahumu, PlayerName?",
  ui_story_3_7_51_dialog_content = "Sayang sekali, memoriku hilang saat aku jatuh.",
  ui_story_3_7_52_dialog_content = "Selain perintah untuk melayani dan melindungi PlayerName, tak banyak yang bisa kuingat.",
  ui_story_3_7_53_dialog_content = "Hari itu, Soroz mengalami kerusakan parah.",
  ui_story_3_7_54_dialog_content = "Begitukan…? *Batuk-batuk* Aku merasakan perbincangan kalian…",
  ui_story_3_7_55_dialog_content = "Aku tak yakin itu berarti untung atau sial…",
  ui_story_3_7_56_dialog_content = "Jadi, apa yang sebenarnya terjadi di sini?",
  ui_story_3_7_57_dialog_content = "Di dalam Mantiz, ada benda penting yang disebut <color=#FFB400>Think Tank Module</color>…",
  ui_story_3_7_A1_dialog_content = "Modul itu berisi banyak sekali informasi, dari sejarah Caelestite hingga karya klasik Aurorian…",
  ui_story_3_7_58_dialog_content = "Modul itu juga berisi himne paling megah serta bisikan paling gelap dari dalam jurang…",
  ui_story_3_7_60_dialog_content = "Tapi, yang diinginkan Aviduz—Schummer justru bagian paling tak penting dalam modul itu…",
  ui_story_3_7_61_dialog_content = "Jadi, Schummer ada di sini?!",
  ui_story_3_7_62_dialog_content = "Ya. Saat ini dia sedang memburuku untuk merebut Think Tank Module itu.",
  ui_story_3_7_A2_dialog_content = "Dan menggunakannya untuk… Tidak, aku tak bisa memberitahumu hal yang tak boleh diungkapkan!",
  ui_story_3_7_63_dialog_content = "Kalau begitu, kita harus hentikan dia! Bantu aku, Vice!",
  ui_story_3_7_64_dialog_content = "Minta Caelestite itu untuk menunjukkan jalan. Aku ingin bertemu langsung dengan biang kerok yang membuat Undercity 28 hancur.",
  ui_story_3_7_65_dialog_content = "Kau juga sudah lama menunggu datangnya hari ini, 'kan, PlayerName?",
  ui_story_3_7_A3_dialog_content = "Benar sekali. Aku tak sabar ingin menemukan jawaban atas semua pertanyaanku.",
  ui_story_3_7_A4_dialog_content = "Hati-hati, PlayerName… Dia…",
  ui_story_3_7_66_dialog_content = "*Batuk-batuk*…",
  ui_story_3_7_67_dialog_content = "Kondisimu makin parah. Aku harus bagaimana?",
  ui_story_3_7_68_dialog_content = "Kita tak bisa meninggalkannya di sini, PlayerName, tapi kita juga harus pergi…",
  ui_story_3_7_69_dialog_content = "…",
  ui_story_3_7_70_dialog_content = "Tak usah khawatir, saudara Caelestite milikku…",
  ui_story_3_7_71_dialog_content = "Aku akan baik-baik saja. Akan lebih mudah kalau kutunjukkan jalannya.",
  ui_story_3_7_72_dialog_content = "Sebagai master Mantiz, memang aku harus menghentikannya agar tak merebut Think Tank Module…",
  ui_story_3_7_73_dialog_content = "Terima kasih, Mendelson. Saat ini semua sudah selesai, kau harus memberitahuku semua tentang Caelestite!",
  ui_story_3_7_74_dialog_content = "Tentu saja, PlayerName. Aku janji akan memberitahumu semua tentang Eraveil…",
  ui_story_3_7_75_dialog_content = "Kalau begitu, tolong tunjukkan jalannya, Mendelson!",
  ui_story_3_7_76_dialog_content = "Ayo hentikan Schummer!",
  ui_story_3_9_A1_dialog_content = "(Aku sedang apa, sih… Sebenarnya aku punya peluang untuk kabur, tapi aku malah memilih untuk kembali…)",
  ui_story_3_9_A2_dialog_content = "(Mustahil kami bisa menang, ya 'kan…? Jadi, buat apa melawan…)",
  ui_story_3_9_A3_dialog_content = "(Lari, Mendelson! Lupakan tugasmu, demi keselamatan nyawamu…)",
  ui_story_3_9_2_dialog_content = "Demi nyawaku…?",
  ui_story_3_9_3_dialog_content = "Kenapa kau berhenti? Apa kita sudah sampai?",
  ui_story_3_9_4_dialog_content = "Kau yakin mau melakukannya? Masih ada waktu untuk kembali kalau kau mau lari saja…",
  ui_story_3_9_5_dialog_content = "Schummer bukan lawan sembarangan. Lihat saja perbuatannya pada Philex dan Vani…",
  ui_story_3_9_6_dialog_content = "Mereka pengawal setiaku, tapi sekarang mereka malah mau membunuhku.",
  ui_story_3_9_7_dialog_content = "Kemampuannya jauh melebihi perkiraan kita.",
  ui_story_3_9_8_dialog_content = "Kenapa kau mau melawannya padahal kau tak bisa bertarung, PlayerName?",
  ui_story_3_9_10_dialog_content = "Aku sudah lama mencarinya untuk menjawab semua pertanyaanku, tentang Undercity 28, tentang peristiwa 17 tahun lalu…",
  ui_story_3_9_A4_dialog_content = "Dan sekarang, dia mati-matian mengejar Caelestite lain…",
  ui_story_3_9_13_dialog_content = "Aku tak bisa pergi! Aku harus menghentikannya!",
  ui_story_3_9_14_dialog_content = "Kabur memang mudah, tapi memangnya kita mau kabur ke mana?",
  ui_story_3_9_15_dialog_content = "Ada satu tempat, Mendelson, dan sekali kita masuk ke sana, kita tak akan pernah bisa berbalik arah. Kalau kita langsung menuju Gerbang Neraka…",
  ui_story_3_9_A5_dialog_content = "Kalau begitu, kita kalahkan makhluk laknat itu bersama-sama!",
  ui_story_3_9_16_dialog_content = "Sekarang aku paham. Kenapa tadi aku malah berpikir macam-macam, sih?",
  ui_story_3_9_18_dialog_content = "Eraveil sudah hancur. Semua teman dan orang yang kusayangi dibantai oleh Eclipsite.",
  ui_story_3_9_19_dialog_content = "Hanya aku, si penakut dan pengecut ini yang berhasil kabur bersama Mantiz… hanyut dalam rasa malu.",
  ui_story_3_9_20_dialog_content = "Dan sekarang, tak bisa kupercaya aku justru berpikir begitu juga.",
  ui_story_3_9_21_dialog_content = "Mendelson…",
  ui_story_3_9_22_dialog_content = "Kalau aku tak bisa bertahan, berarti aku masih sama saja seperti dulu. Kita…",
  ui_story_3_9_23_dialog_content = "Mendelson!",
  ui_story_3_9_24_dialog_content = "Ah… Aku…",
  ui_story_3_9_25_dialog_content = "Kenapa kau tiba-tiba kesakitan begitu?",
  ui_story_3_9_26_dialog_content = "Apa sudah mulai? Aku tahu <color=#FFB400>kau berhasil mendapatkannya</color>, Schummer!",
  ui_story_3_9_27_dialog_content = "Aku bisa merasakan kekuatan besarmu, cukup untuk mengubur Mantiz dalam kegelapan pekat!",
  ui_story_3_9_28_dialog_content = "Berusaha mengejar sekecil apa pun cahaya yang tersisa…",
  ui_story_3_9_29_dialog_content = "Ada yang perlu kubantu, Mendelson?",
  ui_story_3_9_30_dialog_content = "Jangan… khawatir! Ini sebenarnya hanya untuk menyingkirkan sisa-sisa sifat pengecutku.",
  ui_story_3_9_A8_dialog_content = "Ayo, PlayerName, dan teman-temanmu juga. Ikuti aku.",
  ui_story_3_9_A9_dialog_content = "Kita akan bantai semua Eclipsite di hadapan kita walaupun harus sampai ke kegelapan paling dalam sekalipun!",
  ui_story_3_9_A10_dialog_content = "Itu, dan waspadai belakangmu! Musuh datang!",
  ui_story_3_9_31_dialog_content = "Oh, Mendelson, adikku sayang, hentikan saja usaha sia-siamu itu…",
  ui_story_3_9_32_dialog_content = "Buat apa kausembunyikan benda itu sebegitu dalam? Toh aku tetap saja berhasil menemukannya—<color=#FFB400>Think Tank Module</color>!",
  ui_story_3_9_33_dialog_content = "Ternyata sama sekali tidak sesulit dugaanku. Malah agak membosankan.",
  ui_story_3_9_34_dialog_content = "Sini, tunjukkan rahasiamu kepadaku…",
  ui_story_3_9_A11_dialog_content = "Sial! Bahasa sandi. Sepertinya akan butuh waktu agak lama.",
  ui_story_3_9_35_dialog_content = "Master-ku sudah menunggumu, Lady…",
  ui_story_3_9_36_dialog_content = "Mau sampai kapan kau berkutat dengan benda itu?",
  ui_story_3_9_37_dialog_content = "Sebentar lagi selesai…",
  ui_story_3_9_38_dialog_content = "Sebentar lagi, dan aku akan memiliki segalanya, termasuk \"rahasia\" itu.",
  ui_story_3_9_39_dialog_content = "Melalui aku, mereka akan menyatu dengan <color=#FFB400>Black Colossus</color> milikku dan menjadi fondasi evolusi!",
  ui_story_3_9_41_dialog_content = "Cepatlah, Schummer.",
  ui_story_3_9_42_dialog_content = "(Eclipsian) Pergilah, rekan-rekanku.",
  ui_story_3_9_43_dialog_content = "Memangnya pasukan yang dikerahkan harus sebanyak ini?",
  ui_story_3_9_44_dialog_content = "Kita masih jauh dari tujuan. Eclipsite bilang, mainan yang kaurebut dari Mendelson sudah dikalahkan…",
  ui_story_3_9_45_dialog_content = "Oleh master Soroz dan rekan sesama Caelestite-mu itu.",
  ui_story_3_9_47_dialog_content = "Pas sekali waktunya. Setelah kudapatkan apa yang kucari, akan kubereskan mereka dengan sekali pukul.",
  ui_story_3_9_48_dialog_content = "Dendam bisa dibalaskan kapan saja, tapi rencana tetaplah rencana, Schummer. Jangan kaukacaukan.",
  ui_story_3_9_50_dialog_content = "Kukira aku bisa menahan diri? Saat cacing yang kabur itu akhirnya akan bisa kutangkap?",
  ui_story_3_9_51_dialog_content = "Aku tak suka kekacauan, gangguan, dan improvisasi.",
  ui_story_3_9_52_dialog_content = "Dan aku tak suka bertarung. Aku tak tertarik dengan tindakan vulgar semacam itu.",
  ui_story_3_9_53_dialog_content = "…",
  ui_story_3_9_54_dialog_content = "Baiklah, cukup sudah mengobrolnya.",
  ui_story_3_9_56_dialog_content = "Tabaad!",
  ui_story_3_9_57_dialog_content = "Aku sudah terlalu lama bersembunyi dalam gelap, Master. Boleh aku bertindak sekarang?",
  ui_story_3_9_58_dialog_content = "Lakukan sesukamu.",
  ui_story_3_9_59_dialog_content = "Siap, Master.",
  ui_story_3_9_61_dialog_content = "Akan kucabik-cabik mereka dengan tangan telanjang, akan kulemparkan mereka ke dalam kegelapan tak berujung…",
  ui_story_3_9_A12_dialog_content = "Kau bisa merasakannya, PlayerName? Para Eclipsite itu berkumpul menuju arah kita.",
  ui_story_3_9_A13_dialog_content = "Ya, dan jumlah mereka banyak sekali. Tapi, mereka tak akan bisa menghalangi kita.",
  ui_story_3_9_A14_dialog_content = "Benar. Terus maju dan bantai semua Eclipsite yang menghalangi jalan kita!",
  ui_story_3_12_2_dialog_content = "Kita sudah sampai.",
  ui_story_3_12_3_dialog_content = "Di situkah lokasi Think Tank Module?",
  ui_story_3_12_4_dialog_content = "Ya. Waspada, siapa tahu Schummer juga sudah sampai sini.",
  ui_story_3_12_5_dialog_content = "Ayo kita akhiri ini bersama, Mendelson.",
  ui_story_3_12_6_dialog_content = "Ya, PlayerName! Kita hentikan…",
  ui_story_3_12_7_dialog_content = "Tenanglah, Mendelson. Kondisimu…",
  ui_story_3_12_9_dialog_content = "Tak usah khawatir tentang itu. Ini <color=#FFB400>kekuatan kegelapan</color>… Kekuatan ini tak bisa dikontrol dan sudah menyebar ke seluruh tubuhku.",
  ui_story_3_12_10_dialog_content = "Bagaimana… Bagaimana bisa begitu?",
  ui_story_3_12_12_dialog_content = "Hari itu, 17 tahun lalu, aku menerima <color=#FFB400>Kekuatan Eclipsite</color> agar bisa bertahan hidup.",
  ui_story_3_12_A1_dialog_content = "<color=#FFB400>Schummer juga menerimanya</color>, tapi bedanya, kondisi tubuhku jadi memburuk.",
  ui_story_3_12_A2_dialog_content = "Mungkin ini karena keyakinanku kurang kuat, atau mungkin karena aku memang sebenarnya tak mau hidup seperti ini?",
  ui_story_3_12_15_dialog_content = "Penderitaanmu itu hanya sementara, Nak. Jangan mengambil keputusan kalau kau hanya akan menyesalinya.",
  ui_story_3_12_16_dialog_content = "Maafkan aku, Guru. Sudah terlambat. Aku ingin tetap hidup…",
  ui_story_3_12_17_dialog_content = "Menerima kekuatan Eclipsite hanya agar bisa tetap hidup? Tapi, kenapa?",
  ui_story_3_12_18_dialog_content = "Ironis, ya? Walau aku ini dibenci, selama ini aku tetap menjalankan tugasku sebagai Master Mantiz.",
  ui_story_3_12_A3_dialog_content = "Tapi, aku ini siapa? Aku ini apa?",
  ui_story_3_12_A4_dialog_content = "Masih ada harapan. Kalau kita berhasil mengalahkan Schummer, aku janji aku akan mencari cara agar kau bisa kembali normal!",
  ui_story_3_12_A5_dialog_content = "Sudahlah. Sudah terlalu terlambat untukku. Takdir punya cara yang tak bisa kita pahami.",
  ui_story_3_12_19_dialog_content = "Dulu, aku mengandalkan kekuatan kegelapan untuk bersembunyi di bawah tanah yang gelap ini dan tidak ketahuan hingga bertahun-tahun…",
  ui_story_3_12_20_dialog_content = "Sama seperti yang sudah-sudah, kukira aku bisa kabur dengan menanggung kekalahan dan rasa malu…",
  ui_story_3_12_21_dialog_content = "Lalu meringkuk di pojok suram dan melanjutkan hidupku yang sengsara ini.",
  ui_story_3_12_22_dialog_content = "Tapi, ternyata aku bertemu denganmu! Mungkin ini saatnya aku harus bersikap berani, sekali saja seumur hidupku.",
  ui_story_3_12_23_dialog_content = "Kali ini aku tak akan kabur! Ayo selamatkan masa depan kita dari takdir kejam ini!",
  ui_story_3_13_1_dialog_content = "<color=#e8d9bb>Di luar puing Mantiz</color>",
  ui_story_3_13_2_dialog_content = "Apa mereka ada di sini, Tabaad?",
  ui_story_3_13_3_dialog_content = "Tiga orang cemas, salah satunya sudah hampir mati.",
  ui_story_3_13_4_dialog_content = "Bagus. Lakukan sesukamu.",
  ui_story_3_13_5_dialog_content = "Ya. Kiranya sang Bunda menjadi saksi, aku akan berusaha sebaik mungkin. Di bawah Aurora, hanya Eclipse-lah yang akan bertahan selamanya.",
  ui_story_3_13_6_dialog_content = "Diakah orangnya?",
  ui_story_3_13_8_dialog_content = "Kenapa lama sekali? Kalian melewatkan pertunjukan bagus.",
  ui_story_3_13_9_dialog_content = "Tunggu, hanya kau saja, sendirian?",
  ui_story_3_13_10_dialog_content = "Sendirian pun, aku sudah lebih dari cukup.",
  ui_story_3_13_11_dialog_content = "Cukup?",
  ui_story_3_13_12_dialog_content = "PlayerName, orang terakhir dari kaum Caelestite. Kau berbeda dari Aurorian ini. Harusnya kau ambil pilihan yang lebih baik.",
  ui_story_3_13_13_dialog_content = "Bagaimana kau bisa tahu nama PlayerName?",
  ui_story_3_13_14_dialog_content = [[
Karena kami memiliki semua pengetahuan, penglihatan, dan masa depan yang kalian cari.
PlayerName, bukankah selama ini kau juga mendambakan itu semua?]],
  ui_story_3_13_15_dialog_content = "Tak usah berusaha menutupinya, PlayerName. Aku paham hasrat terdalam kaum Caelestite. Kalian sangat mendambakan hal-hal ini…",
  ui_story_3_13_16_dialog_content = "PlayerName?",
  ui_story_3_13_17_dialog_content = "Kau menginginkan kekuatan besar agar tak perlu lagi bersembunyi di belakang kaum Aurorian.",
  ui_story_3_13_18_dialog_content = "Aku…",
  ui_story_3_13_19_dialog_content = "Mendekatlah. Ya, lebih dekat lagi. Jadilah seperti Master-ku, <color=#FFB400>terimalah Eclipse</color>!",
  ui_story_3_13_20_dialog_content = "Eclipse?",
  ui_story_3_13_21_dialog_content = "Pikirkan lagi!",
  ui_story_3_13_22_dialog_content = "Si anjing penakut rupanya sudah kembali, tertatih-tatih.",
  ui_story_3_13_23_dialog_content = "Kau takut? Mana Master-mu?",
  ui_story_3_13_A1_dialog_content = "(Think Tank Module dan Schummer sudah tidak ada!)",
  ui_story_3_13_24_dialog_content = "Aku tak menyangka, Mendelson.",
  ui_story_3_13_25_dialog_content = "Dulu kau meringkuk di dalam Colossus itu seperti anjing dekil sambil menyaksikan kaummu dibantai…",
  ui_story_3_13_26_dialog_content = "Kau menutup diri dari dunia, tak mau menghadapi kenyataan. Menangnya sekarang kau siap menghadapi mimpi terburukmu?",
  ui_story_3_13_27_dialog_content = "Kasihan sekali. Kau memang lemah dan tak berguna sampai-sampai gemetaran begitu… Mengenaskan.",
  ui_story_3_13_28_dialog_content = "Tutup mulutmu dan jangan ganggu Mendelson!",
  ui_story_3_13_29_dialog_content = "Kau baik-baik saja?",
  ui_story_3_13_30_dialog_content = "Maaf, sepertinya biang keladi yang sebenarnya malah berhasil lolos.",
  ui_story_3_13_31_dialog_content = "Dan dia juga berhasil membawa Think Tank Module. Aduh, aku sudah tak tahan lagi…",
  ui_story_3_13_32_dialog_content = "Tapi, karena modul itu sudah diambil, ada hal lain yang harus kulakukan…",
  ui_story_3_13_33_dialog_content = "Tenanglah. Kami bisa menanganinya!",
  ui_story_3_13_34_dialog_content = "Aneh sekali, orang-orang celaka ini malah saling menghibur.",
  ui_story_3_13_35_dialog_content = "Jangan sampai perhatianmu teralihkan, PlayerName!",
  ui_story_3_13_36_dialog_content = "Tunjukkan jalannya!",
  ui_story_3_13_37_dialog_content = "Sudah berakhir?",
  ui_story_3_13_38_dialog_content = "<color=#e8d9bb>Yang tersisa hanyalah keheningan yang terasa ngeri.</color>",
  ui_story_3_13_39_dialog_content = "Tidak, ada yang aneh! Kekuatan kegelapan bertumpuk! Waspadai serangan!",
  ui_story_3_13_40_dialog_content = "Ini belum berakhir untuk Tabaad! Lihatlah hukuman dariku!",
  ui_story_3_13_41_dialog_content = "Kegelapan, telan Caelestite itu!",
  ui_story_3_13_42_dialog_content = "Sial, dia memburuku!",
  ui_story_3_13_43_dialog_content = "Kau tak bisa semudah itu melukai orang yang dilindungi Illumina!",
  ui_story_3_13_44_dialog_content = "Bagus, Letnan!",
  ui_story_3_13_45_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_3_13_F1_dialog_content = "Gaah!!!",
  ui_story_3_13_46_dialog_content = "Co-Commander!",
  ui_story_3_13_47_dialog_content = "Sepertinya aku datang tepat waktu.",
  ui_story_3_13_48_dialog_content = "(Eclipsian) Hal-hal yang rendah, kotor, bodoh, lemah...",
  ui_story_3_13_49_dialog_content = "Eclipsite itu… berubah menjadi bunga sakura dan menghilang…",
  ui_story_3_13_50_dialog_content = "Terima kasih atas bantuanmu!",
  ui_story_3_13_51_dialog_content = "Lt. Vice, kau telah melanggar protokol Illumina. Kau pasti tahu konsekuensi dari tindakanmu, 'kan?",
  ui_story_3_13_52_dialog_content = "…",
  ui_story_3_13_53_dialog_content = "Lt. Vice!",
  ui_story_3_13_54_dialog_content = "Nih!",
  ui_story_3_13_55_dialog_content = "Aku ingin kaubuat laporan untukku, paling sedikit 5.000 kata, tentang Colossus itu dan Caelestite yang tak becus bertarung ini.",
  ui_story_3_13_56_dialog_content = "Eh! Aku ini navigator ahli dan bisa memerintah Colossus itu!",
  ui_story_3_13_57_dialog_content = "Jangan mengulangi apa yang sudah kuketahui.",
  ui_story_3_13_58_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_3_13_59_dialog_content = "Mendelson! Tubuhmu!",
  ui_story_3_13_60_dialog_content = "Oh, tidak! Apa dia…?",
  ui_story_3_13_61_dialog_content = "Sepertinya… nasibku sudah jelas. Saatnya menebus kesalahanku.",
  ui_story_3_13_62_dialog_content = "Tidak… kami bisa menyelamatkanmu! Iya, 'kan, Vice?",
  ui_story_3_13_63_dialog_content = "PlayerName, aku…",
  ui_story_3_13_64_dialog_content = "Tak apa. Ini pilihanku sendiri. Aku… aku tahu hari ini akan tiba…",
  ui_story_3_13_A2_dialog_content = "Ada yang lebih penting, PlayerName.",
  ui_story_3_13_A3_dialog_content = "Melihat situasinya, kurasa aku tak perlu lagi merahasiakannya…",
  ui_story_3_13_65_dialog_content = "Ingat Think Tank Module yang kusebutkan tadi? <color=#FFB400>Dengarkan penjelasanku baik-baik</color>…",
  ui_story_3_13_A4_dialog_content = "Walau setiap Colossus punya spesialisasi masing-masing, tidak ada Colossus yang dirancang khusus untuk bertempur.",
  ui_story_3_13_A5_dialog_content = "Kecuali Aviduz. Dialah satu-satunya Colossus yang punya kemampuan untuk menyerang!",
  ui_story_3_13_66_dialog_content = "Untungnya, dia belum selesai dibangun.",
  ui_story_3_13_67_dialog_content = "Schummer, master-nya, berusaha memperbaiki Colossus itu. Untuk itu, dia butuh:",
  ui_story_3_13_X67_dialog_content = "<color=#FFB400>Think Tank Module</color>",
  ui_story_3_13_X68_dialog_content = "<color=#FFB400>Autonomous Growth Unit</color>",
  ui_story_3_13_X69_dialog_content = "…dan <color=#FFB400>Flame Control Module</color>",
  ui_story_3_13_X70_dialog_content = "Ketiga modul itu.",
  ui_story_3_13_A6_dialog_content = "Dia harus mendapatkan Think Tank Module dulu karena modul itu akan menunjukkan lokasi kedua modul lainnya!",
  ui_story_3_13_68_dialog_content = "Agar bisa memperoleh kekuatan tertinggi, Schummer akan berusaha mendapatkan ketiga modul itu, apa pun caranya.",
  ui_story_3_13_69_dialog_content = "Tapi, dia sudah berhasil mendapatkan Think Tank Module!",
  ui_story_3_13_70_dialog_content = "Tidak. Dia tak akan bisa langsung menggunakannya. Modul itu diamankan dengan protokol pelindung yang akan aktif begitu aku mati. \"Kejutan\" kecil yang sengaja kusiapkan untuknya.",
  ui_story_3_13_71_dialog_content = "Tenanglah, Mendelson. Kita masih punya banyak waktu untuk mengobrol setelah kau pulih.",
  ui_story_3_13_72_dialog_content = "Kita bisa mengalahkan Schummer bersama-sama, dan saat ini semua selesai, kita bisa pulang!",
  ui_story_3_13_73_dialog_content = "Aku belum pernah ke Eraveil. Kau bisa menceritakan tentang Eraveil padaku…",
  ui_story_3_13_74_dialog_content = "Sayangnya, ini sudah berakhir untukku. Mintalah Soroz untuk menceritakannya padamu… Atau, carilah Caelestite lain…",
  ui_story_3_13_75_dialog_content = "Tidak, Mendelson!",
  ui_story_3_13_A7_dialog_content = "Diamlah, dengarkan aku. Waktu kita hampir habis…",
  ui_story_3_13_76_dialog_content = "Setelah aku mati, aku yakin tempat berikutnya yang akan dituju Schummer adalah <color=#FFB400>Lumopolis</color>, kota terakhir kaum Aurorian…",
  ui_story_3_13_A8_dialog_content = "Karena ada Think Tank Module lain di sana! Ya, modulnya bukan hanya satu.",
  ui_story_3_13_A9_dialog_content = "Kau harus memperingatkan Lumopolis, PlayerName.",
  ui_story_3_13_A10_dialog_content = "Para Aurorian di sana pasti tak menyadari seberapa pentingnya Think Tank Module…",
  ui_story_3_13_77_dialog_content = "Mendelson! Kumohon, jangan tinggalkan aku!",
  ui_story_3_13_78_dialog_content = "Aku sepenuhnya berharap bisa bersamamu dan semua teman baru ini, PlayerName.",
  ui_story_3_13_79_dialog_content = "Tapi, kali ini aku tak akan lari lagi. Schummer tak boleh sampai berhasil begitu saja…",
  ui_story_3_13_80_dialog_content = "Setidaknya dia tak akan pernah berhasil merebut Think Tank Module milikku! Kali ini, si pengecut ini akan bangkit… dan melawan!",
  ui_story_3_13_81_dialog_content = "Mendelson…",
  ui_story_3_13_82_dialog_content = "Indah sekali…",
  ui_story_3_13_83_dialog_content = "…",
  ui_story_3_13_84_dialog_content = "Itu… naga yang agak unik.",
  ui_story_3_13_F2_dialog_content = "Itu <color=#FFB400>Zakura</color> milik Commander Hiiro.",
  ui_story_3_13_F3_dialog_content = "Indah sekali. Siapa bisa mengira ada warna yang begitu indah di dunia ini? Seandainya saja aku bisa melihat lebih banyak…",
  ui_story_3_13_85_dialog_content = "Bertahun-tahun tinggal dalam kegelapan, aku hampir lupa langit itu seperti apa.",
  ui_story_3_13_86_dialog_content = "Kita harus berbuat sesuatu, PlayerName, Commander Hiiro! Masa, kita hanya akan membiarkannya…",
  ui_story_3_13_F4_dialog_content = "…",
  ui_story_3_13_F5_dialog_content = "…",
  ui_story_3_13_87_dialog_content = "Seandainya saja kita punya waktu lebih banyak untuk berbincang, PlayerName. Seandainya saja bisa seperti dulu… Soroz, saat kita…",
  ui_story_3_13_88_dialog_content = "Kuharap aku bisa melihat langit sekali lagi…",
  ui_story_3_13_89_dialog_content = "Soroz!",
  ui_story_3_13_90_dialog_content = "Ya, PlayerName.",
  ui_story_3_13_91_dialog_content = "Lakukan telepati dengan Mendelson dan tunjukkan langit kepadanya.",
  ui_story_3_13_92_dialog_content = "Ya.",
  ui_story_3_13_93_dialog_content = "Oh, langit biru… Sudah lama sekali.",
  ui_story_3_13_94_dialog_content = "Biar kubagi Soroz denganmu, Mendelson.",
  ui_story_3_13_95_dialog_content = "Sekarang dan selamanya, dia akan menjadi mata dan telinga yang akan menunjukkan segala yang ada di atas awan kepadamu.",
  ui_story_3_13_96_dialog_content = "Seperti inikah rasanya kematian? Agak berbeda… dari yang kubayangkan… Rasanya sangat kesepian…",
  ui_story_3_13_97_dialog_content = "Aku di sini, Master.",
  ui_story_3_13_98_dialog_content = "Suara apa itu?",
  ui_story_3_13_99_dialog_content = "Kami semua di sini.",
  ui_story_3_13_100_dialog_content = "Kami akan menemanimu hingga akhir.",
  ui_story_3_13_101_dialog_content = "Vani… Philex…",
  ui_story_3_13_103_dialog_content = "Mendelson!",
  ui_story_3_13_104_dialog_content = "…",
  ui_story_3_13_105_dialog_content = "…",
  ui_story_3_13_106_dialog_content = "<size=45>Kau sudah menerima kejutan dariku, Schummer?</size>",
  ui_story_3_13_107_dialog_content = "Apa?",
  ui_story_3_13_108_dialog_content = "Think Tank Module ini malah mengaktifkan protokol <color=#FFB400>penghancuran diri</color>? Sial!",
  ui_story_3_13_110_dialog_content = "<anim type=Shake>MEN-DEL-SON!</anim>",
  ui_story_3_13_111_dialog_content = "Memalukan, Schummer. Sepertinya tidak seperti harapanmu.",
  ui_story_3_13_112_dialog_content = "Tak kusangka Mendelson masih punya satu trik terakhir. Benda ini… sekarang tak berguna.",
  ui_story_3_13_113_dialog_content = "Berani benar dia, dasar pengecut sial, payah…!",
  ui_story_3_13_114_dialog_content = "Hahahaha, itu baru namanya adikku!",
  ui_story_3_13_115_dialog_content = "Seumur hidupnya, dia selalu lemah, tapi ternyata dia masih punya keberanian untuk menentangku sebelum mati.",
  ui_story_3_13_116_dialog_content = "Jangan bilang kau tak berhasil mendapatkan apa pun dari benda itu.",
  ui_story_3_13_118_dialog_content = "Hanya berupa kepingan-kepingan, tapi tetap saja ini informasi baru.",
  ui_story_3_13_120_dialog_content = "Ada Think Tank Module yang sama persis dengan ini di <color=#FFB400>Lumopolis</color>.",
  ui_story_3_13_121_dialog_content = "Para Aurorian bodoh itu tak tahu betapa pentingnya benda itu.",
  ui_story_3_13_122_dialog_content = "Kau tak bisa seenaknya saja keluar-masuk Lumopolis. Aku harus memikirkan cara untuk membereskan kekacauan yang kautimbulkan ini.",
  ui_story_3_13_123_dialog_content = "Mendelson, lihat baik-baik. Tak seorang pun bisa menghentikanku untuk menuntaskan…",
  ui_story_3_13_124_dialog_content = "Akan kutunjukkan padamu betapa sia-sianya pengorbananmu.",
  ui_story_3_14_A2_dialog_content = "<color=#e8d9bb>Lumopolis Archive</color>",
  ui_story_3_14_1_dialog_content = "Ya ampun, kerjaan hari ini banyak sekali…",
  ui_story_3_14_2_dialog_content = "Sungguh, berantakan sekali… Semuanya bertumpuk di sini… Eh, ini apa, ya?",
  ui_story_3_14_3_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_3_14_4_dialog_content = "Aduh!",
  ui_story_3_14_5_dialog_content = "Kau baik-baik saja? Mana yang kena?",
  ui_story_3_14_6_dialog_content = "Aku tak apa, tapi kau ini kenapa, sih? Memindahkan barang saja tak becus!",
  ui_story_3_14_7_dialog_content = "Ma-maaf, aku baru pertama kali…",
  ui_story_3_14_8_dialog_content = "Hoi! Apa-apaan…? Kau ini kenapa, sih?!",
  ui_story_3_14_9_dialog_content = "Ma-maaf, aku benar-benar minta maaf, aku tak sengaja…",
  ui_story_3_14_10_dialog_content = "Kau! Kau merusak <color=#FFB400>benda ini</color>! Ini sangat berharga, tahu!",
  ui_story_3_14_11_dialog_content = "… Akan kuambil sekarang juga.",
  ui_story_3_14_12_dialog_content = "Sudahlah, biar aku saja. Aku tak tahu apa kegunaannya, tapi benda ini jelas kelihatan mahal.",
  ui_story_3_14_13_dialog_content = "Suara langkah kaki.",
  ui_story_3_14_14_dialog_content = "Kalian, jangan mengobrol saja saat kerja! Fokus pada pekerjaan kalian!",
  ui_story_3_14_15_dialog_content = "Kami sedang memilah barang-barang di ruang arsip, Kapten! Sudah separuh…",
  ui_story_3_14_16_dialog_content = "Kalian sudah tak diperlukan di sini. Pergilah.",
  ui_story_3_14_17_dialog_content = "Siap, Kapten!",
  ui_story_3_14_18_dialog_content = "Siap, Kapten!",
  ui_story_3_14_A1_dialog_content = "Yah, benda ini memang persis seperti yang disebutkan <color=#FFB400>Master</color>.",
  ui_story_3_14_19_dialog_content = "Sangat berharga, tapi pihak berwenang di Lumopolis mengira ini hanyalah benda antik biasa.",
  ui_story_3_14_20_dialog_content = "Tak lama lagi, akan ada orang yang memahami <color=#FFB400>nilaimu yang sebenarnya</color>…",
  ui_story_3_14_B1_dialog_content = "Kapten! Chief memanggil kita untuk melapor!",
  ui_story_3_14_B2_dialog_content = "…",
  ui_story_3_14_B3_dialog_content = "Paham. Ayo.",
  ui_story_4_1_1_dialog_content = "<color=#FFB400>Think Tank Module</color>, <color=#FFB400>Autonomous Growth Unit</color>, dan <color=#FFB400>Flame Control Module</color>… Sebenarnya, bentuknya seperti apa?",
  ui_story_4_1_2_dialog_content = "Informasi yang diberikan Mendelson tidak banyak, jadi walaupun kita tahu ada Think Tank Module lain di Lumopolis…",
  ui_story_4_1_3_dialog_content = "Mungkinkah Colossus lain?",
  ui_story_4_1_4_dialog_content = "Apa pun yang direncanakannya, kita harus mendahuluinya!",
  ui_story_4_1_5_dialog_content = "Apa kita langsung menuju Lumopolis? Lalu bagaimana?",
  ui_story_4_1_6_option_content = "Kalau begitu, kita akan cari tahu!",
  ui_story_4_1_7_option_content = "Sejujurnya, aku belum memikirkannya matang-matang.",
  ui_story_4_1_8_dialog_content = "Kedengarannya tidak meyakinkan, PlayerName.",
  ui_story_4_1_9_dialog_content = "Kita sama sekali tak tahu siapa yang akan kita hadapi. Kita tak tahu kemampuan, motif, atau bahkan wujud mereka.",
  ui_story_4_1_10_dialog_content = "Setidaknya kau jujur soal itu…",
  ui_story_4_1_11_dialog_content = "Tapi, kalau tak kenal siapa lawan kita, kita tak akan bisa menyusun rencana.",
  ui_story_4_1_12_dialog_content = "Kita tak tahu kemampuan, motif, atau bahkan wujud mereka.",
  ui_story_4_1_13_dialog_content = "Lagi pula, Lumopolis tidak seperti Illumina. Tempat itu… yah, dipenuhi masalah.",
  ui_story_4_1_14_dialog_content = "<color=#e8d9bb>Raut wajah Vice tampak pedih, seakan-akan dia sedang mengingat kenangan pahit.</color>",
  ui_story_4_1_15_dialog_content = "Karena kaulah Navigatornya, PlayerName, kau saja yang memutuskan.",
  ui_story_4_1_16_dialog_content = "Aku masih tetap ingin pergi ke Lumopolis.",
  ui_story_4_1_17_dialog_content = "Aku tahu ini mungkin berisiko, Vice, tapi…",
  ui_story_4_1_18_dialog_content = "Ini satu-satunya petunjuk yang kumiliki untuk mencari tahu apa yang terjadi 17 tahun lalu.",
  ui_story_4_1_19_dialog_content = "Baiklah, tapi aku harus memberi tahu Commander Hiiro dulu. Ini akan jauh lebih sulit dari yang kaukira.",
  ui_story_4_1_20_dialog_content = "Ternyata kau belum melupakan Officer atasanmu.",
  ui_story_4_1_21_dialog_content = "Ups! Kau masih di sini, Commander?",
  ui_story_4_1_22_dialog_content = "Dari tadi aku di sini, Lt. Vice. PlayerName, aku turut berduka cita atas Caelestite itu, tapi kita harus mendekati intel tentang Lumopolis dengan hati-hati.",
  ui_story_4_1_23_dialog_content = "Hati-hati… maksudnya?",
  ui_story_4_1_24_dialog_content = "Tanpa penyelidikan cermat, kita tak boleh langsung menerima kata-kata Mendelson mentah-mentah. Lagi pula, kita sudah menghadapi beberapa High-Level Eclipsite, jadi sebaiknya kita tidak bertindak gegabah.",
  ui_story_4_1_25_dialog_content = "Tapi kita tak punya waktu! Kalau terjadi sesuatu… Soroz akan melindungi kita!",
  ui_story_4_1_26_dialog_content = "Tanpa mengurangi rasa hormat, PlayerName…",
  ui_story_4_1_27_dialog_content = "Sejak awal, aku sudah tahu tentang Colossus-mu itu, dan aku sudah menerima semua informasi yang dibutuhkan dari Charon.",
  ui_story_4_1_A1_dialog_content = "Menurut sistem peringkat Colossus yang dulu kami gunakan…",
  ui_story_4_1_28_dialog_content = "Soroz adalah Colossus <color=#FFB400>Level 6</color>.",
  ui_story_4_1_29_dialog_content = "…",
  ui_story_4_1_30_dialog_content = "Setinggi itu? Soroz memang jagoan, ya.",
  ui_story_4_1_31_dialog_content = "Bukan, level tertinggi adalah Level 1. Makin besar angkanya, makin rendah levelnya, berarti makin payah pula performanya.",
  ui_story_4_1_32_dialog_content = "…?",
  ui_story_4_1_33_dialog_content = "Lalu, berapa level terendahnya?",
  ui_story_4_1_34_dialog_content = "<color=#FFB400>6</color>.",
  ui_story_4_1_35_dialog_content = "…?!",
  ui_story_4_1_36_dialog_content = "Bukannya kau mengaku sebagai Colossus dari kelas Langit, Soroz?!",
  ui_story_4_1_37_dialog_content = "Itu agar kau punya kemauan untuk tetap hidup. Aku terpaksa bohong seperti itu.",
  ui_story_4_1_A2_dialog_content = "Lagi pula, \"kelas Langit\" sebenarnya tak ada.",
  ui_story_4_1_38_dialog_content = "Kau sudah bohong padaku, dan sekarang kau mengakuinya dengan begitu mudahnya?",
  ui_story_4_1_39_dialog_content = "Colossus Level 6 hanya dilengkapi dengan fitur bantuan hidup dan transportasi.",
  ui_story_4_1_40_dialog_content = "Dan spesialisasinya adalah kabur.",
  ui_story_4_1_41_dialog_content = "Sudah cukup…",
  ui_story_4_1_42_dialog_content = "PlayerName kelihatan tertekan.",
  ui_story_4_1_43_dialog_content = "Sepertinya aku terlalu banyak bicara. Jangan kecewa, PlayerName.",
  ui_story_4_1_44_dialog_content = "Sebagai seorang Caelestite, kau punya \"karunia\" unik dan jiwa pemimpin yang luar biasa dalam pertempuran. Aku sama sekali tak meragukannya.",
  ui_story_4_1_45_dialog_content = "Dan melihat bagaimana Lt. Vice sangat mendukungmu, kau pasti memang bisa diandalkan.",
  ui_story_4_1_46_dialog_content = "Hah?",
  ui_story_4_1_47_dialog_content = "Terima kasih. Aku akan berusaha keras.",
  ui_story_4_1_48_dialog_content = "Kalau begitu, ayo menuju Lumopolis! Kalau ingin mengalahkan Schummer, kita harus bergegas!",
  ui_story_4_1_49_dialog_content = "Baiklah! Bisakah kau memberi kami izin untuk masuk ke Lumopolis, Commander?",
  ui_story_4_1_50_dialog_content = "Tidak. Itu masalahmu.",
  ui_story_4_1_51_dialog_content = "Hah?!",
  ui_story_4_1_52_dialog_content = "Maaf, tapi tanpa informasi yang sudah terverifikasi, Illumina Federation tak bisa mengambil tindakan resmi apa pun, apalagi terkait Lumopolis.",
  ui_story_4_1_54_dialog_content = "…",
  ui_story_4_1_55_dialog_content = [[
Bukannya dulu kau bersekolah di Lumopolis? 
Saatnya reuni dengan teman-teman kelasmu dulu.]],
  ui_story_4_1_56_dialog_content = "Bukankah dulu kau sekelas dengan <color=#FFB400>Carleen</color>, Kapten dari Lumopolis Guardians?",
  ui_story_4_1_57_dialog_content = "Justru karena itulah masalahnya jadi lebih besar. Aduh…",
  ui_story_4_1_58_dialog_content = "<color=#e8d9bb>Di Atas Lumopolis</color>",
  ui_story_4_1_59_dialog_content = "Apa <color=#FFB400>kota apung</color> itu tujuan kita?",
  ui_story_4_1_60_dialog_content = "Sepertinya kita sudah sampai. Perjalannya cukup singkat kalau naik Colossus…",
  ui_story_4_1_X1_dialog_content = "Vice, pakaianmu itu…",
  ui_story_4_1_X2_dialog_content = "Ini cuma penyamaran! Aku sudah mengirimkan surat kepada Carleen untuk menjelaskan situasi kita, tapi tetap saja aku tak boleh kelihatan mencolok…",
  ui_story_4_1_X3_dialog_content = "Anu, sepertinya penampilanmu itu justru akan membuatmu tampak makin mencolok.",
  ui_story_4_1_61_dialog_content = "Lihat, PlayerName!",
  ui_story_4_1_62_dialog_content = "Itu Lumopolis.",
  ui_story_4_1_64_option_content = "Itukah kota terakhir Aurorian?",
  ui_story_4_1_65_option_content = "Kok bisa mengapung di udara, ya?",
  ui_story_4_1_66_dialog_content = "Berhentilah bergumam sendiri, kemarilah. Aku ingin menjelaskan sesuatu sebelum kita memulai misi ini!",
  ui_story_4_1_67_dialog_content = "Apa pun yang terjadi, biar aku saja yang bicara. Paham?",
  ui_story_4_1_68_dialog_content = "Jangan gegabah, dan ingat bahwa kita harus mencapai target lebih dulu sebelum Schummer!",
  ui_story_4_1_69_dialog_content = "Paham, Letnan Vice. Kau sangat bisa diandalkan.",
  ui_story_4_1_70_dialog_content = "Nah, biar kuperiksa lagi izin masukku… Aku benar-benar tak mau berurusan dengannya.",
  ui_story_4_1_71_dialog_content = "Aku agak gugup, PlayerName. Benarkah aman kalau aku di sini saja sendirian?",
  ui_story_4_1_72_dialog_content = "Tak ada cara lain, Soroz. Bentukmu 'kan sangat mencolok.",
  ui_story_4_1_73_dialog_content = "Kalau kau ikut dengan kami, kami mungkin tak akan bisa masuk ke wilayah pinggiran kota, apalagi ke Lumopolis.",
  ui_story_4_1_74_dialog_content = "Lagi pula, bukankah kau ini Colossus Level 6? Memangnya kau bisa membantu dalam pertempuran?",
  ui_story_4_1_75_dialog_content = "Rupanya kau masih jengkel soal itu.",
  ui_story_4_1_76_dialog_content = "Ya. Kau benar. Kalau begitu, kupercayakan urusan bertarungnya kepadamu saja.",
  ui_story_4_1_A3_dialog_content = "Aku akan menunggu kalian di area tersembunyi di angkasa. Hati-hati ya.",
  ui_story_4_1_77_dialog_content = "Baiklah, ayo. Antrean masuk kotanya sudah panjang.",
  ui_story_4_1_A4_dialog_content = "Huh, aku tak suka mengantre.",
  ui_story_4_1_78_dialog_content = "Aku benar-benar tak mau bertemu orang itu… Tapi, tentu saja <color=#FFB400>Carleen de Schwartz</color> memang layak jadi Kapten dari Lumopolis Guardians.",
  ui_story_4_1_79_dialog_content = "Memangnya si Kapten itu kenapa, sih?",
  ui_story_4_1_80_dialog_content = "Tunggu dan lihat saja. Mungkin dia sekarang sedang menunggu kita di gerbang.",
  ui_story_4_1_81_dialog_content = "Mana Kapten yang kausebutkan itu, Vice?",
  ui_story_4_1_82_dialog_content = "Ssst!",
  ui_story_4_1_83_dialog_content = "Harap patuhi perintah dan menurutlah saat kalian sedang diperiksa!",
  ui_story_4_1_84_dialog_content = "Pengunjung dengan izin sementara tidak boleh berada di sini lebih dari 24 jam. Kalau tidak, kalian akan dideportasi!",
  ui_story_4_1_85_dialog_content = "Kalau melihat orang mencurigakan, segera laporkan kepada Lumo Guard!",
  ui_story_4_1_86_dialog_content = "Kuulangi, ya, PlayerName. Apa pun yang terjadi, jangan…",
  ui_story_4_1_87_dialog_content = "Jangan bisik-bisik. Tunjukkan saja surat izinmu!",
  ui_story_4_1_88_dialog_content = "Oh, begitu…",
  ui_story_4_1_89_dialog_content = "Pengunjung dari Illumina lagi… Memangnya tak ada kejadian apa-apa di baris depan, ya? Pakaianmu tidak seperti seharusnya.",
  ui_story_4_1_90_dialog_content = "Anu, aku kemari karena ada urusan pribadi.",
  ui_story_4_1_91_dialog_content = "Baru pertama kali ke Lumopolis? Kenapa kau celingukan begitu?",
  ui_story_4_1_92_dialog_content = "Tidak, dulu aku bersekolah di sini. Kali ini aku kembali dengan Izin Kelas A yang sudah diperpanjang…",
  ui_story_4_1_93_dialog_content = "Bagaimana dengan orang yang kelihatan mencurigakan di sampingmu itu?",
  ui_story_4_1_94_option_content = "Aku? Aku baru pertama kali melihat dunia ini.",
  ui_story_4_1_95_option_content = "(Vice bilang, aku tak boleh bicara…)",
  ui_story_4_1_96_dialog_content = "Kaukira aku bercanda? Mana surat izinmu? Satu orang, satu surat izin. Sudah tertulis di papan pengumuman!",
  ui_story_4_1_97_dialog_content = "Kau ini tuli, ya? Aku bertanya, lho!",
  ui_story_4_1_98_dialog_content = "Maaf, dia ikut denganku. Permohonanku sudah mendapatkan persetujuan khusus. Tolong periksa lagi!",
  ui_story_4_1_99_dialog_content = "Kapten Carleen yang…",
  ui_story_4_1_100_dialog_content = "Kapten? Oh, rupanya kau orangnya!",
  ui_story_4_1_101_dialog_content = "Kenapa tidak bilang dari tadi, sih? Baiklah, tunggu di sini.",
  ui_story_4_1_102_dialog_content = "Fyuh…",
  ui_story_4_1_103_dialog_content = "Kau kelihatan santai. Memangnya kau sedang tidak bertugas di Illumina?",
  ui_story_4_1_104_dialog_content = "Hah, <color=#FFB400>Carleen</color>, lama tak jumpa. Kau masih… mengesankan, seperti biasa.",
  ui_story_4_1_105_dialog_content = "Berani benar kau memanggil Kapten dengan namanya saja.",
  ui_story_4_1_106_dialog_content = "Gadis aneh ini tampak familier…",
  ui_story_4_1_107_dialog_content = "Ah, kau pasti teman sekelas Carleen!",
  ui_story_4_1_108_dialog_content = "Ssst, Raphael. Kapten bisa menangani ini sendirian.",
  ui_story_4_1_109_dialog_content = "Coba tiru Michael. Dia tahu kapan harus diam.",
  ui_story_4_1_110_dialog_content = "…",
  ui_story_4_1_111_dialog_content = "Diam.",
  ui_story_4_1_112_dialog_content = "Tak perlu ada banyak orang di sini. Guardian, kembali jalankan tugas patroli kalian seperti biasa.",
  ui_story_4_1_113_dialog_content = "Biar kuurus kedua pengunjung ini.",
  ui_story_4_1_114_dialog_content = "Sepertinya aku tak perlu memperkenalkan diri.",
  ui_story_4_1_115_dialog_content = "Langsung saja, Carleen. Kami kemari untuk…",
  ui_story_4_1_116_dialog_content = "Aku sudah baca suratmu. Masih sama saja seperti dulu, tata bahasamu kacau dan bahasa formalmu berantakan.",
  ui_story_4_1_117_dialog_content = "Kaubilang <color=#FFB400>Eclipsite mengincar Lumopolis</color>, 'kan?",
  ui_story_4_1_118_dialog_content = "Memangnya harus sekarang kau mengkritik gaya tulisanku, ya?",
  ui_story_4_1_A5_dialog_content = "Kami dapat kabar bahwa ada orang bernama Schummer yang sedang mengincar Lumopolis.",
  ui_story_4_1_119_dialog_content = "Kami yakin dia berniat mencuri <color=#FFB400>Think Tank Module</color> dari Lumopolis.",
  ui_story_4_1_120_dialog_content = "Think Tank Module? Maaf, aku belum pernah dengar tentang benda itu. Apa pun itu, kurasa tak akan ada yang bisa mengambilnya dari Lumopolis.",
  ui_story_4_1_122_dialog_content = "Hmm? Siapa kau?",
  ui_story_4_1_123_dialog_content = "Boleh kujawab?",
  ui_story_4_1_124_dialog_content = "Menurutmu, apa dia bisa mendengar kita kalau kita bisik-bisik?",
  ui_story_4_1_125_dialog_content = "…",
  ui_story_4_1_126_dialog_content = "PlayerName adalah… Carleen, bisa mendekat? Kau satu-satunya yang boleh tahu…",
  ui_story_4_1_127_dialog_content = "Apa maksudmu… orang-orang egois yang memilih cari aman saja itu? Bagaimana dengan Colossus-nya?",
  ui_story_4_1_128_dialog_content = "Colossus itu bernama Soroz… Soroz sedang terbang di atas Lumopolis dan tidak terdeteksi.",
  ui_story_4_1_129_dialog_content = "…!",
  ui_story_4_1_130_dialog_content = "Tak apa, dia cuma Colossus Level 6… tak bisa bertarung, dan biasanya hanya digunakan untuk melarikan diri.",
  ui_story_4_1_131_dialog_content = "Payah.",
  ui_story_4_1_132_dialog_content = "Tapi, itu tak penting, Carleen. Aku sudah memberitahumu identitas PlayerName, jadi kau bisa memercayai kami!",
  ui_story_4_1_133_dialog_content = "Kau punya bukti lain yang bisa mendukung pernyataanmu itu?",
  ui_story_4_1_134_dialog_content = "Tidak. Tapi para Eclipsite itu jelas berusaha masuk ke Lumopolis. Mungkin sekarang mereka bahkan sudah ada dalam antrean itu!",
  ui_story_4_1_137_dialog_content = "Kapten! Ada situasi darurat!",
  ui_story_4_1_139_dialog_content = "Benarkah?!",
  ui_story_4_1_140_dialog_content = "Apa maksud mereka?",
  ui_story_4_1_141_dialog_content = "Aku tak tahu, tapi kurasa bukan kabar bagus…",
  ui_story_4_1_142_dialog_content = "Letnan Vice, karena dulu kita teman sekelas, kali ini aku akan percaya padamu, dan kau boleh masuk ke kota.",
  ui_story_4_1_143_dialog_content = "Tapi, aku akan selalu mengawasimu. Kalau bohong, kau akan dihukum menurut undang-undang!",
  ui_story_4_1_144_dialog_content = "Tentu, bukan masalah! Kita mulai dari…",
  ui_story_4_1_145_dialog_content = "Kita mulai dari <color=#FFB400>Lower Lumopolis</color>.",
  ui_story_4_1_146_dialog_content = "Lower Lumopolis?",
  ui_story_4_1_147_dialog_content = "Ya… Baru saja ada <color=#FFB400>serbuan</color> di Lower Lumopolis.",
  ui_story_4_1_148_dialog_content = "?!",
  ui_story_4_2_1_dialog_content = "<color=#e8d9bb>Lower Lumopolis</color>",
  ui_story_4_2_2_dialog_content = "Tak ada waktu untuk main-main. Ambil jalan pintas balik…",
  ui_story_4_2_3_dialog_content = "Hm? Siapa di sana… Aghhh!",
  ui_story_4_2_4_dialog_content = "Berisik.",
  ui_story_4_2_5_dialog_content = "Maaf, maaf. Aku yang salah.",
  ui_story_4_2_6_dialog_content = "Sudah mati?",
  ui_story_4_2_A1_dialog_content = "Yap, gampang sekali.",
  ui_story_4_2_7_dialog_content = "Jangan dendam padaku, ya. Sayang sekali, kau berada di tempat dan waktu yang salah.",
  ui_story_4_2_8_dialog_content = "Keberuntungan juga salah satu kemampuan untuk bertahan hidup.",
  ui_story_4_2_9_dialog_content = "Kau memang suka melontarkan omong kosong kepada mereka, ya, Gertzurde.",
  ui_story_4_2_A2_dialog_content = "Sudah lama sekali kita tak berjumpa, tapi kau malah sudah bicara lebih banyak kepada orang itu daripada kepadaku!",
  ui_story_4_2_10_dialog_content = "Kau selalu ada dalam hati dan pikiranku. Aku memikirkanmu setiap saat, Shelt.",
  ui_story_4_2_11_dialog_content = "Dasar tukang merayu… Tak usah basa-basi, ya. Aku dapat kabar dari sang Lady, kita harus segera mulai.",
  ui_story_4_2_12_dialog_content = "Sekarang?",
  ui_story_4_2_13_dialog_content = "Yap. Akan kujelaskan detail rencananya satu per satu.",
  ui_story_4_2_14_dialog_content = "Aku sudah mengerahkan beberapa pasukan kacangan sebagai umpan \nuntuk menarik para penjaga ke permukiman. Lalu, kau akan punya kesempatan…",
  ui_story_4_2_15_dialog_content = "Tunggu, jadi kau sudah memutuskan, Shelt? Kau tak perlu ambil risiko sebesar itu. Tunggu saja aku.",
  ui_story_4_2_16_dialog_content = "Cukup, Gertzurde, lakukan saja seperti kataku.",
  ui_story_4_2_17_dialog_content = "Aku akan menyibukkan para penjaga, dan kau… Kau <color=#FFB400>curi benda itu</color>.",
  ui_story_4_2_18_dialog_content = "Aku sudah memastikan lokasi benda itu… Tapi apa benar bisa semudah itu?",
  ui_story_4_2_19_dialog_content = "Ya, semudah itu. Kita baru akan bebas kalau rencana kita berhasil. Ingat, 'kan?",
  ui_story_4_2_20_dialog_content = "Oke. Kau memang pintar membujuk.",
  ui_story_4_2_21_dialog_content = "Kapten! Sejumlah warga melaporkan bahwa mereka diserang Eclipsite!",
  ui_story_4_2_22_dialog_content = "Bukannya itu lokasi yang kita tuju? Jangan-jangan ini serangan berkelompok?",
  ui_story_4_2_23_dialog_content = "Carleen! Kita sudah sampai!",
  ui_story_4_2_24_dialog_content = "…",
  ui_story_4_2_25_dialog_content = "Sepertinya musuh kita lebih dari satu kelompok.",
  ui_story_4_2_26_dialog_content = "Dimengerti! Bagaimana dengan para Guardian lain?",
  ui_story_4_2_27_dialog_content = "Mereka tetap di Uptown untuk melindungi para bangsawan. Perintah dari orang itu, sih.",
  ui_story_4_2_28_dialog_content = "Perintah dari <color=#FFB400>City Lord</color>…?",
  ui_story_4_2_29_dialog_content = [[
Semua serangan yang dilaporkan itu terjadi di sisi timur, jadi para Supervisor 
di Lower Lumopolis menuju ke sana.]],
  ui_story_4_2_30_dialog_content = "Menurut perasaanku, kita justru harusnya ke area barat…",
  ui_story_4_2_31_dialog_content = "Nah, tatapan itu lagi. Tatapan \"Harus melakukan hal besar apa pun yang melintas di pikiran saat ini juga\"…",
  ui_story_4_2_32_dialog_content = "Apa dia juga biasanya melontarkan tatapan seperti itu semasa kalian sekolah dulu?",
  ui_story_4_2_33_dialog_content = "Oh, ya. Misalnya waktu kami mengikuti kelas pertarungan, dan dia akan mengalahkanku.",
  ui_story_4_2_34_dialog_content = "Kurasa Carleen memang lumayan mengesankan.",
  ui_story_4_2_35_dialog_content = "Tak usah memujiku. Ayo ke area barat. Kau bisa bertarung, PlayerName?",
  ui_story_4_2_36_dialog_content = "Aku tak bisa bertarung, tapi aku bisa mengoordinasi dan memandu.",
  ui_story_4_2_37_dialog_content = "Kalau kau yang bilang, kedengarannya jadi kurang meyakinkan, ya.",
  ui_story_4_2_38_dialog_content = "Tapi, kuberi kau kesempatan untuk membuktikan kemampuanmu.",
  ui_story_4_2_39_dialog_content = "Aku jadi merasa tertekan…",
  ui_story_4_3_1_dialog_content = "Rupanya kau memang punya bakat memimpin.",
  ui_story_4_3_2_dialog_content = "Oh. ya, itu Light Trail, 'kan? Aku tak percaya, orang-orang dengan bakat seperti kalian justru sudah binasa sebelum aku lahir.",
  ui_story_4_3_3_dialog_content = "Aku jadi tahu umurmu, Carleen.",
  ui_story_4_3_4_dialog_content = "Jangan terlalu percaya diri dulu. Para Eclipsite itu juga terlihat di area barat. Kita harus tetap waspada.",
  ui_story_4_3_5_dialog_content = "Eclipsite-nya lebih banyak dari dugaan kita…",
  ui_story_4_3_6_option_content = "Tapi, Lumopolis tak akan kalah, 'kan?",
  ui_story_4_3_7_option_content = "Para penjaga di gerbang tak mampu menangani para Eclipsite itu?",
  ui_story_4_3_8_dialog_content = "Itu hanya berlaku untuk Uptown, bukan Lower Lumopolis.",
  ui_story_4_3_9_dialog_content = "Para penjaga itu memang berguna, tapi sebagian besar dari mereka bertugas melindungi Uptown, bukan Lower Lumopolis.",
  ui_story_4_3_10_dialog_content = "Di Lower Lumopolis ini, semua diurus sendiri oleh para penghuninya. Ya, 'kan, Carleen?",
  ui_story_4_3_F1_dialog_content = "…",
  ui_story_4_3_11_dialog_content = "Ternyata perlakuan untuk Lower Lumopolis dan Uptown sangat berbeda begitu, ya?",
  ui_story_4_3_12_dialog_content = "Kami tak bisa berbuat banyak. Memang beginilah Lumopolis…",
  ui_story_4_3_13_dialog_content = "Maaf, aku terlambat… Ketua skuadron, Gertzurde, melapor.",
  ui_story_4_3_14_dialog_content = "Ada yang aneh?",
  ui_story_4_3_15_dialog_content = "Tidak, Kapten.",
  ui_story_4_3_16_dialog_content = "Kumpulkan semua orang untuk mengevakuasi warga sipil. Tutup juga semua gerbang di Lower Lumopolis!",
  ui_story_4_3_17_dialog_content = "Sudah, Kapten.",
  ui_story_4_3_18_dialog_content = "Cepat sekali! Kalau begitu, kuminta kau ikut dengan kami—",
  ui_story_4_3_19_dialog_content = "Maafkan kalau aku lancang, tapi ada banyak warga sipil yang terkunci di luar kota, dan mereka harus dibiarkan masuk.",
  ui_story_4_3_20_dialog_content = "Kalau tidak, mereka akan jadi mangsa para Eclipsite itu.",
  ui_story_4_3_21_dialog_content = "Baiklah. Sana uruslah, tapi sisakan beberapa prajurit untukku!",
  ui_story_4_3_22_dialog_content = "Aku izin pergi lebih dulu, Kapten. Demi White Night.",
  ui_story_4_3_23_dialog_content = "Carleen, tadi itu…?",
  ui_story_4_3_24_dialog_content = "Salah satu ketua skuadron di Lower Lumopolis. Dia bertanggung jawab atas banyak titik pertahanan, dan selama ini dia sangat efisien.",
  ui_story_4_3_25_dialog_content = "Dulu, dia juga seorang <color=#FFB400>kesatria ternama</color>.",
  ui_story_4_3_26_dialog_content = "Kita memang tidak bisa menilai sesuatu dari tampilannya…",
  ui_story_4_3_27_dialog_content = "Oke, ayo terus bergerak. Banyak Eclipsite sudah berhasil menyelusup masuk lewat retakan dan mengacau di seluruh Lower Lumopolis.",
  ui_story_4_3_28_dialog_content = "Aku juga ingin bertemu dengan <color=#FFB400>Schummer</color> si misterius itu.",
  ui_story_4_6_1_dialog_content = "Kapten! Area timur sudah diamankan!",
  ui_story_4_6_2_dialog_content = "Kapten, ada kabar dari area barat. Sepertinya ada yang melihat High-Level Eclipsite di sana!",
  ui_story_4_6_3_dialog_content = "Sudah kuduga! Beri tahu aku lokasinya!!",
  ui_story_4_6_4_dialog_content = "Jangan-jangan tadi itu hanya untuk mengalihkan perhatian? Para High-Level Eclipsite itu pasti mengincar Think Tank Module!",
  ui_story_4_6_5_dialog_content = "Kita tidak tertinggal terlalu jauh, 'kan?",
  ui_story_4_6_6_dialog_content = "Kita punya Carleen dan pengetahuannya yang tajam!",
  ui_story_4_6_7_dialog_content = "…",
  ui_story_4_6_8_dialog_content = "Duuh, lagi-lagi tatapannya seperti itu… Kenapa? Ada yang tidak beres?",
  ui_story_4_6_9_dialog_content = "Entahlah… Tapi, perasaan ini membuatku tak nyaman… Sudahlah, kita teruskan saja!",
  ui_story_4_6_10_dialog_content = "Shelt! Kita harus membatalkan rencana!",
  ui_story_4_6_11_dialog_content = "Apa? Tapi, aku sudah jauh-jauh memancing putri Carleen de Schwartz itu kemari!",
  ui_story_4_6_12_dialog_content = "Dan sekarang kau malah mau membatalkan rencananya? Aku tak mau berdebat denganmu soal ini, Gertzurde.",
  ui_story_4_6_13_dialog_content = "Carleen ditemani bocah dari Illumina itu, dan sepertinya mereka juga mencari Think Tank Module!",
  ui_story_4_6_14_dialog_content = "Dan gerbang ruang Archive terlalu sulit untuk dibuka. Aku tak tahu apakah waktunya cukup untuk…",
  ui_story_4_6_15_dialog_content = "Tidak, tidak, jangan sampai bocah-bocah sialan itu mengacaukan rencana kita!",
  ui_story_4_6_16_dialog_content = "Tak akan… tak akan kubiarkan…",
  ui_story_4_6_17_dialog_content = "Lalu, kita harus bagaimana?",
  ui_story_4_6_18_dialog_content = "Akan kuulur waktu lagi untukmu!",
  ui_story_4_6_19_dialog_content = "<color=#FFB400>Shire</color>… Oh, iya. Aku bisa membangunkan Shire agar dia muncul…",
  ui_story_4_6_20_dialog_content = "Tidak! Apa pun niatmu, Shelt, aku tak akan membiarkanmu melakukannya!",
  ui_story_4_6_21_dialog_content = "Shire—adikmu itu tak bisa diduga! Dia sinting!",
  ui_story_4_6_22_dialog_content = "Sinting? Ha… Lalu, aku ini apa, dong?",
  ui_story_4_6_23_dialog_content = "Pergi dari sini, Gertzurde. Pergilah ke tempat yang seharusnya. Jangan kecewakan aku.",
  ui_story_4_6_24_dialog_content = "Aku akan menunggumu di tempat yang sudah kita sepakati, Shelt…",
  ui_story_4_6_25_dialog_content = "Kau sudah mengucapkan janji kesatria. Kau akan menepatinya, 'kan?",
  ui_story_4_6_26_dialog_content = "Tentu saja, Gertzurde. Aku akan menepati janjiku, apa pun yang terjadi…",
  ui_story_4_6_27_dialog_content = "Apa kau sudah cukup tidur, Shire? Bangunlah. Aku akan membawamu… keluar untuk bermain.",
  ui_story_4_6_28_dialog_content = "Asyik! Main!",
  ui_story_4_7_1_dialog_content = "<color=#e8d9bb>Jalanan di Lower Lumopolis</color>",
  ui_story_4_7_2_dialog_content = "Kapten, kami menemukan mayat di depan sana. Kami sudah memeriksanya, dia penjaga yang bertugas menjaga Lower Lumopolis.",
  ui_story_4_7_3_dialog_content = "Hanya ada satu luka di tubuhnya, menembus jantungnya.",
  ui_story_4_7_4_dialog_content = "Semua penjaga! Mulai geledah. Tak akan kubiarkan apa pun membahayakan wargaku!",
  ui_story_4_7_5_dialog_content = "\"<color=#FFB400>Wargaku</color>\"?",
  ui_story_4_7_6_dialog_content = "Carleen memang peduli kepada warga.",
  ui_story_4_7_7_dialog_content = "Bukan, aku penasaran dengan kata \"<color=#FFB400>ku</color>\" itu.",
  ui_story_4_7_8_dialog_content = "Oh… Aku belum bilang, ya? Carleen adalah <color=#FFB400>putri Lord of Lumopolis</color>.",
  ui_story_4_7_9_dialog_content = "???",
  ui_story_4_7_10_dialog_content = "Maaf, banyak sekali yang terjadi, aku jadi lupa memberitahumu…",
  ui_story_4_7_11_dialog_content = "Tapi, setidaknya, dalam situasi kita sekarang ini, dia adalah Kapten dari Lumopolis Guardians.",
  ui_story_4_7_13_dialog_content = "Waow! Apa itu?!",
  ui_story_4_7_14_dialog_content = "Guard! Maju ke arah suara dengan kecepatan penuh!",
  ui_story_4_7_16_dialog_content = "Ini pertama kalinya… aku menampakkan diri dalam wujud ini.",
  ui_story_4_7_17_dialog_content = "Apa permukiman warga itu diledakkan?",
  ui_story_4_7_18_dialog_content = "Carleen, PlayerName, awas! Ada yang aneh dengan orang itu!",
  ui_story_4_7_19_dialog_content = "Kau ini… Shelt?",
  ui_story_4_7_20_dialog_content = "Kau tak menduga, 'kan, Putri, bahwa kita akan bertemu lagi dalam wujud yang sama?",
  ui_story_4_7_21_dialog_content = "Bagaimana menurutmu? Apa penampilanku lebih bagus dibandingkan dulu?",
  ui_story_4_7_22_dialog_content = "Kalian saling kenal, Carleen?",
  ui_story_4_7_23_dialog_content = "Ya, sudah lama sekali. Dia hanyalah makhluk malang yang berpaling dari imannya.",
  ui_story_4_7_24_dialog_content = "Makhluk malang? Cih. Yah… sepertinya memang.",
  ui_story_4_7_25_dialog_content = "Terinjak-injak di bawah kaki pihak berwenang, mereka menganggapku tak lebih dari makhluk hina di Uptown. Menyedihkan, memang.",
  ui_story_4_7_26_dialog_content = "Penderitaanmu itu akibat pilihanmu sendiri!",
  ui_story_4_7_27_dialog_content = "Lihat dirimu sekarang… Aku bahkan tak bisa menemukan kata-kata \nuntuk menggambarkan wujudmu.",
  ui_story_4_7_28_dialog_content = [[
Memangnya itu salahku? Seandainya kau tak terlahir 
sebagai bangsawan, akan jadi apa kau, Putri?]],
  ui_story_4_7_29_dialog_content = "Seandainya kau juga terlahir di tempat kumuh sepertiku… Kau akan jadi apa?",
  ui_story_4_7_30_dialog_content = "…",
  ui_story_4_7_31_dialog_content = "Bingung? Arogan sekali kau menuduh bahwa penderitaanku ini adalah akibat kesalahanku sendiri, Putri.",
  ui_story_4_7_32_dialog_content = "Kau masih ingat apa yang terakhir kukatakan padamu, Shelt?",
  ui_story_4_7_33_dialog_content = "Aku bersumpah demi White Night, kalau sampai kau berani menginjakkan kaki lagi di sini, akan kupastikan kau dapat ganjarannya!",
  ui_story_4_7_34_dialog_content = "Hari ini, akan kupenuhi sumpahku itu.",
  ui_story_4_7_35_dialog_content = "Sebenarnya selama ini aku tak ke mana-mana. Aku selalu ada di hadapanmu, bersembunyi di sudut gelap…",
  ui_story_4_7_36_dialog_content = "Kaget, ya? Bukan itu saja, aku juga sudah punya banyak teman.",
  ui_story_4_7_37_dialog_content = "Apa…?!",
  ui_story_4_7_38_dialog_content = "Kemarilah, adikku, Shire-ku tersayang…",
  ui_story_4_7_39_dialog_content = "Kak… Shire ma-mau…",
  ui_story_4_7_40_dialog_content = "Kau mau main? Mana mungkin aku bilang tidak padamu, adikku sayang.",
  ui_story_4_7_41_dialog_content = "Ayo, kita main dengan tuan putri cantik ini!",
  ui_story_4_7_42_dialog_content = "Main—!",
  ui_story_4_7_43_dialog_content = "Awas!",
  ui_story_4_7_44_dialog_content = "Sial! Kenapa? Kenapa? Kau…!",
  ui_story_4_7_45_dialog_content = "Siapa kau?! Kenapa kau bisa mengoordinasi mereka?!",
  ui_story_4_7_46_dialog_content = "Kau… seorang Caelestite?!",
  ui_story_4_7_47_dialog_content = "…",
  ui_story_4_7_48_dialog_content = "Tidak seru… Tidak seru!! Ayo pergi, Kak…",
  ui_story_4_7_49_dialog_content = "Tidak, dia masih butuh waktu. Kita tak boleh… Kita tak boleh biarkan mereka pergi!",
  ui_story_4_7_50_dialog_content = "Kalau kau dan para penjilat Lumopolis itu memang berani, coba kejar kami!!",
  ui_story_4_7_51_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_4_7_53_dialog_content = "*Uhuk, uhuk* Sial, <color=#FFB400>mereka pergi</color>!",
  ui_story_4_7_54_dialog_content = "Mereka menuju Uptown!",
  ui_story_4_7_55_dialog_content = "Bunyikan alarm! Beri tahu semua Guardian! Kembali ke Uptown, sekarang juga!",
  ui_story_4_7_56_dialog_content = "PlayerName! Cepat! Kita harus mengejarnya!",
  ui_story_4_8_1_dialog_content = "<color=#e8d9bb>Lumopolis Archive, jauh dari Uptown…</color>",
  ui_story_4_8_2_dialog_content = "Putar ke kiri… 3 derajat… Putar ke kanan… 14 derajat… Lalu…",
  ui_story_4_8_3_dialog_content = "Gagal lagi… Kode sandi macam apa ini?! Bodoh sekali waktu itu aku tak mengintipnya saat dia membuat kode sandi ini…",
  ui_story_4_8_4_dialog_content = "Lebih baik kuledakkan saja biar terbuka! Tidak, nanti modulnya malah rusak.",
  ui_story_4_8_5_dialog_content = "Memangnya gedung arsip harus pakai kunci seperti ini?",
  ui_story_4_8_6_dialog_content = "Gertzurde.",
  ui_story_4_8_7_dialog_content = "Maaf, Shelt, aku masih butuh waktu. Gerbang gedung arsipnya…",
  ui_story_4_8_8_dialog_content = "Tunggu, bukannya kau sedang bertarung?",
  ui_story_4_8_9_dialog_content = "Tidak… Maaf, aku… aku kabur.",
  ui_story_4_8_10_dialog_content = "Ada Caelestite, Gertzurde! Mereka ditemani seorang Caelestite.",
  ui_story_4_8_11_dialog_content = "Tadi kau bertarung melawan Carleen? Apa kau terluka?!",
  ui_story_4_8_12_dialog_content = "Dengarkan aku. Akan kupancing mereka ke selatan Uptown, \njauh dari lokasimu…",
  ui_story_4_8_A1_dialog_content = "Jadi, kau akan punya banyak waktu untuk…",
  ui_story_4_8_13_dialog_content = "Tidak! Kalau kau kabur dari Uptown, sama saja kau cari mati!!",
  ui_story_4_8_14_dialog_content = "Jangan lupa, kita melakukan ini semua untuk…",
  ui_story_4_8_15_dialog_content = "<color=#FFB400>Sang Lady</color> akan membantu kita. Dia sudah berjanji…",
  ui_story_4_8_16_dialog_content = "Keyakinan adalah kekuatan, Gertzurde. Kita sudah memilih, dan kita harus menuntaskannya!",
  ui_story_4_8_17_dialog_content = "Sampai jumpa di luar Lumopolis, Sayangku.",
  ui_story_4_8_18_dialog_content = "Shelt!!",
  ui_story_4_8_19_dialog_content = "Tunggu! Tunggu aku. Kau terlalu cepat…",
  ui_story_4_8_20_dialog_content = "Bocah bernama Shire itu siapa, Carleen? Apa mereka berdua itu Aurorian?",
  ui_story_4_8_21_dialog_content = "Ya, walaupun aku sebenarnya tak mau mengakuinya. Mereka pengkhianat Lumopolis.",
  ui_story_4_8_22_dialog_content = "PlayerName, caramu mengomando benar-benar sempurna. Kukira tadi kau akan ketakutan menghadapi High-Level Eclipsite.",
  ui_story_4_8_23_dialog_content = "Kau benar-benar Caelestite yang sama sekali berbeda dari dugaanku.",
  ui_story_4_8_24_option_content = "Itu memang sudah tugasku.",
  ui_story_4_8_25_option_content = [[
Tidak, aku sama saja 
dengan Caelestite lainnya.]],
  ui_story_4_8_26_dialog_content = "Bukankah kau juga selalu bertarung sebagai Kapten di Guardian, Kapten Carleen?",
  ui_story_4_8_A2_dialog_content = "Kami tak suka bertarung, dan kami juga tak punya kemampuan bertarung.",
  ui_story_4_8_27_dialog_content = "Kami hanya tak ingin para Eclipsite itu menang.",
  ui_story_4_8_28_dialog_content = "Aku percaya padamu. Kaumku juga bertarung dengan semangat seperti itu.",
  ui_story_4_8_29_dialog_content = "Memangnya kau tidak takut bertarung kalau kau tak mampu?",
  ui_story_4_8_31_dialog_content = "Aku tahu kaumku dulu bertarung melawan Eclipsite sekuat tenaga, dan mereka memang punya peran sangat penting.",
  ui_story_4_8_32_dialog_content = "Aku sama sekali tak berbeda dari mereka.",
  ui_story_4_8_33_dialog_content = "Kemampuanmu sangat mengesankan.",
  ui_story_4_8_34_dialog_content = "Kemampuanku… Mungkin justru itulah yang membuat kita diserbu.",
  ui_story_4_8_35_dialog_content = "Memangnya kau tidak merasa tak berdaya?",
  ui_story_4_8_36_dialog_content = "Tidak, karena ada tujuan yang harus kucapai.",
  ui_story_4_8_37_dialog_content = "Dan kau mau menempuh bahaya demi mencapai tujuan itu?",
  ui_story_4_8_F1_dialog_content = "Ya, karena ini bukan pertarunganku semata.",
  ui_story_4_8_38_dialog_content = "Menarik. Temanmu ini ternyata menarik, Vice.",
  ui_story_4_8_39_dialog_content = "Menempuh bahaya untuk <color=#FFB400>bertarung demi orang lain</color>… begitu?",
  ui_story_4_8_40_dialog_content = "…",
  ui_story_4_8_41_dialog_content = "…!!",
  ui_story_4_8_46_dialog_content = "Di mana kau, Raphael?",
  ui_story_4_8_47_dialog_content = "Di sini!",
  ui_story_4_8_48_dialog_content = "Jangan ikut kami ke Uptown. Kuminta kau… menuju arah berlawanan.",
  ui_story_4_8_49_dialog_content = "Apa?! Kenapa?",
  ui_story_4_8_50_dialog_content = "Kalau ke Uptown, bukankah itu sama saja bunuh diri?",
  ui_story_4_8_51_dialog_content = "Mungkin sebenarnya mereka sama sekali tidak berniat kabur… Tapi, mereka mau…",
  ui_story_4_8_52_dialog_content = "Mengalihkan perhatian kita?",
  ui_story_4_8_53_dialog_content = "Benar, tapi sekarang memang kita tak punya pilihan selain mengejar mereka.",
  ui_story_4_8_54_dialog_content = "Jadi, kuminta Raphael menuju ke arah berlawanan. Aku punya firasat, ada seseorang di sana…",
  ui_story_4_8_55_dialog_content = "Oh, begitu! Aku paham sekarang! Aku akan cari orang yang mencurigakan! Aku pergi sekarang!",
  ui_story_4_8_56_dialog_content = "Kau memang hebat, Carleen. Tak ada yang bisa lolos dari pengamatanmu.",
  ui_story_4_8_57_dialog_content = "Justru sebaliknya. Ada banyak hal yang belum kupahami. Sudut pandang kita semua ini rumit.",
  ui_story_4_8_58_dialog_content = "Nah, fokus. Ada beberapa cacing baru mulai merayap ke jalanan. Ayo kita bereskan mereka.",
  ui_story_4_12_1_dialog_content = "…",
  ui_story_4_12_2_dialog_content = "…",
  ui_story_4_12_3_dialog_content = "Anu… Kau sedang apa di sini, ketua Squadron?",
  ui_story_4_12_4_dialog_content = "Aku 'kan sudah bilang dua kali, aku kemari untuk mengantar staf gedung Archive. Kalau tak percaya, tanya saja pada mereka.",
  ui_story_4_12_5_dialog_content = "Lho, tadi 'kan kaubilang kepada Kapten bahwa kau membawa warga masuk dari luar?",
  ui_story_4_12_6_dialog_content = "Staf Archive inilah warga yang kumaksud itu, dan mereka sekarang sudah sampai sini.",
  ui_story_4_12_7_dialog_content = "Eh, yang kaupegang itu apa? Kenapa dibungkus begitu?",
  ui_story_4_12_8_dialog_content = "Oh, ini? Aku membereskan beberapa berkas yang kutinggalkan di sini minggu lalu.",
  ui_story_4_12_9_dialog_content = "Ini, anu, laporan koroner untuk warga sipil yang tewas dibunuh Eclipsite dalam enam bulan terakhir.",
  ui_story_4_12_10_dialog_content = "Eh…",
  ui_story_4_12_11_dialog_content = "Kita butuh berkas ini untuk referensi langkah pengamanan. Sebagian besar berupa foto, gambar autopsi, semacam itulah.",
  ui_story_4_12_12_dialog_content = "Mau lihat…?",
  ui_story_4_12_13_dialog_content = "…",
  ui_story_4_12_14_dialog_content = "…",
  ui_story_4_12_15_dialog_content = "Ah ha ha, tak usah, terima kasih.",
  ui_story_4_12_16_dialog_content = "Tak apa. Situasi memang sudah benar-benar tak terkendali, jadi kalau kau memang diperintahkan untuk melakukan pemeriksaan…",
  ui_story_4_12_17_dialog_content = "Oh, haha! Tak usah. Aku permisi dulu, aku mau patroli di sana!",
  ui_story_4_12_18_dialog_content = "…",
  ui_story_4_13_1_dialog_content = "Kapten! Noda darahnya tercecer di sepanjang sisi ini, sampai ke balik pintu ini!",
  ui_story_4_13_2_dialog_content = "Jarak antara tetes-tetes darahnya makin sempit… Laju mereka melambat. Kita sudah makin dekat!",
  ui_story_4_13_3_dialog_content = "Cepat! Mungkin mereka di depan sana!",
  ui_story_4_13_4_dialog_content = "Wah, kita sudah lari lama sekali sampai hampir sampai di Uptown…",
  ui_story_4_13_5_dialog_content = "Sepertinya mereka tahu mereka tak bisa masuk ke Uptown, jadi mereka berniat melawan di sini.",
  ui_story_4_13_6_dialog_content = "Ayo. Akhirnya akan selalu sama—semua pengkhianat akan bernasib sama!",
  ui_story_4_13_7_dialog_content = "Kak… Aku mengan-ngantuk…",
  ui_story_4_13_8_dialog_content = "Jangan tidur sekarang, Shire… Maaf, aku tahu kau lelah…",
  ui_story_4_13_9_dialog_content = "Mereka sudah sampai…? Memang begitulah Carleen, mereka cepat sekali…",
  ui_story_4_13_10_dialog_content = "Saatnya memenuhi janjimu, Lady…",
  ui_story_4_13_11_dialog_content = "Halo, Shelt.",
  ui_story_4_13_12_dialog_content = "Lady…! Kami kesulitan… Ternyata musuh kami ditemani seorang Caelestite!",
  ui_story_4_13_13_dialog_content = "Sepertinya pertempuran memang tak bisa dihindari.",
  ui_story_4_13_14_dialog_content = "Kami butuh bantuanmu…! Gertzurde masih butuh waktu…!",
  ui_story_4_13_15_dialog_content = "Kumohon, beri kami kekuatan untuk mengalahkan musuh! Kumohon… beri kami harapan untuk hidup!",
  ui_story_4_13_16_dialog_content = "Itu dua permintaan berbeda, Shelt.",
  ui_story_4_13_17_dialog_content = "…!",
  ui_story_4_13_18_dialog_content = "Kau ingin mengalahkan musuhmu, atau kau ingin tetap hidup?",
  ui_story_4_14_1_dialog_content = "Shelt, Shire.",
  ui_story_4_14_3_dialog_content = "Kau… datang…",
  ui_story_4_14_4_dialog_content = "Kakak…",
  ui_story_4_14_5_dialog_content = "Katakan, Shelt, <color=#FFB400>kau mengulur waktu untuk siapa</color>?",
  ui_story_4_14_6_dialog_content = "…",
  ui_story_4_14_7_dialog_content = "Yah, kuanggap kau lebih suka bertarung daripada bicara.",
  ui_story_4_14_8_dialog_content = "Carleen… Memangnya kaukira kau berhasil memojokkan kami?",
  ui_story_4_14_9_dialog_content = "Sang Lady sudah memberi kami kekuatan baru…",
  ui_story_4_14_10_dialog_content = "Sang Lady? Jangan-jangan Schummer?",
  ui_story_4_14_11_dialog_content = "Kami… kami akan tetap hidup! Lalu kami akan meninggalkan Lumopolis bobrok ini dengan kepala tegak!",
  ui_story_4_14_13_dialog_content = "Kau tak akan bisa menang, Putri!",
  ui_story_4_14_14_dialog_content = "Kakak…? Tubuhku…",
  ui_story_4_14_15_dialog_content = "<anim type=Shake>Arghhhhhhhhhhhh!</anim>",
  ui_story_4_14_17_dialog_content = "Apa…?! Apa mereka <color=#FFB400>menyatu</color>?!",
  ui_story_4_14_18_dialog_content = "Kurasa yang kauberikan kepada mereka barusan itu bukan kekuatan biasa.",
  ui_story_4_14_19_dialog_content = "Memang. Tapi itu yang mereka mau, kekuatan untuk mengalahkan musuh.",
  ui_story_4_14_21_dialog_content = "Kita berikan nama untuk makhluk ini! Kau mau menyebut mereka apa?",
  ui_story_4_14_22_dialog_content = "Boredom.",
  ui_story_4_14_23_dialog_content = "<anim type=Shake>Argh! Aduh, aduh! Harusnya tak begini!! Kita—</anim>",
  ui_story_4_14_24_dialog_content = "<anim type=Shake>Aku bisa merasakan kita jadi makin kuat, Kak, tapi… tapi sakit… sakit sekali!</anim>",
  ui_story_4_14_25_dialog_content = "<anim type=Shake>Lady! Apa-apaan ini!?</anim>",
  ui_story_4_14_26_dialog_content = "Mundurlah, PlayerName. Makhluk itu sangat berbeda dari yang kita hadapi sebelumnya.",
  ui_story_4_14_27_option_content = "Jangan takut. Aku di sini.",
  ui_story_4_14_28_option_content = "Fokus. Kita pasti bisa menang.",
  ui_story_4_14_29_dialog_content = "Aku sudah tak bisa lagi menahan amarahku.",
  ui_story_4_14_30_dialog_content = "Orang laknat macam apa yang tega memberikan kekuatan jahanam seperti ini?!",
  ui_story_4_14_31_dialog_content = "Baiklah! Kalau begitu, lakukan tugasmu, PlayerName!",
  ui_story_4_14_32_dialog_content = "<anim type=Shake>Aduh, aduh! Kak… Sakit sekali…</anim>",
  ui_story_4_14_33_dialog_content = "<anim type=Shake>Saudariku… Kumohon, bunuh kami…</anim>",
  ui_story_4_14_35_dialog_content = "…",
  ui_story_4_14_36_dialog_content = "Apa maksudnya?",
  ui_story_4_14_A1_dialog_content = "Aku tak tahu apa yang terjadi, tapi kalau memilih kegelapan, hal seperti itu memang tak mengherankan.",
  ui_story_4_14_37_dialog_content = "Dalam nama White Night, kuberi kau…",
  ui_story_4_14_38_dialog_content = "<anim type=Shake>Dandelion…</anim>",
  ui_story_4_14_39_dialog_content = "?",
  ui_story_4_14_40_dialog_content = "<anim type=Shake>Aku akan berubah menjadi dandelion dan terbang jauh…</anim>",
  ui_story_4_14_41_dialog_content = "Kau mulai meracau. Dalam kondisimu sekarang ini, aku tak yakin kau bisa berguna atau…",
  ui_story_4_14_42_dialog_content = "<anim type=Shake>Tapi aku… aku berhasil menjalankan rencana sang Lady…</anim>",
  ui_story_4_14_43_dialog_content = "<anim type=Shake>Janjinya bukan seperti ini… Gertzurde menungguku—</anim>",
  ui_story_4_14_44_dialog_content = "<anim type=Shake>Lady, Lady…</anim>",
  ui_story_4_14_45_dialog_content = "<color=#e8d9bb>Duaar—!!</color>",
  ui_story_4_14_46_dialog_content = "Ledakan lagi?!",
  ui_story_4_14_47_dialog_content = "Asalnya dari gedung <color=#FFB400>Archive</color>, Kapten! Ada ledakan… Maaf…",
  ui_story_4_14_48_dialog_content = "Oke! Tapi, kenapa kau minta maaf, Raphael?",
  ui_story_4_14_49_dialog_content = "<anim type=Shake>Hihi… Hihi… Akhirnya aku menang, Putri…</anim>",
  ui_story_4_14_50_dialog_content = "<anim type=Shake>Gertzurde, Ger… Gertzurde…ku… Kau harus terus hidup…</anim>",
  ui_story_4_14_53_dialog_content = "Aku tahu dia musuh kita, tapi tetap saja aku tak tega melihatnya.",
  ui_story_4_14_54_dialog_content = "<color=#e8d9bb>Di luar gedung Archive</color>",
  ui_story_4_14_55_dialog_content = "Jadi, kau membiarkan si pengkhianat itu begitu saja?",
  ui_story_4_14_56_dialog_content = "Maafkan aku, Carleen… Kalau saja tadi aku…",
  ui_story_4_14_57_dialog_content = "<color=#FFB400>Cari Gertzurde di seluruh kota</color>. Segera. Sekarang juga!",
  ui_story_4_14_58_dialog_content = "Siap, Kapten!",
  ui_story_4_14_59_dialog_content = "Membahayakan keselamatan warga, mengacau di kota… Ini tak bisa dimaklumi…",
  ui_story_4_14_60_dialog_content = "Apa orang itu mencuri…",
  ui_story_4_14_61_dialog_content = "Think Tank Module dari gedung Archive?",
  ui_story_4_14_62_dialog_content = "Dia berhasil mencurinya, tapi aku sendiri bahkan tak tahu wujud benda itu… Aku gagal total…",
  ui_story_4_14_63_dialog_content = "Bisa dibilang ini juga salahku. Tidak, ini memang sebagian besar akibat salahku.",
  ui_story_4_14_64_dialog_content = "Aku benar-benar minta maaf, Carleen.",
  ui_story_4_14_65_dialog_content = "Eclipsite selalu melawan balik, Vice.",
  ui_story_4_14_66_dialog_content = "Sebenarnya, aku bersyukur kau dan PlayerName memperingatkan kami lebih dulu.",
  ui_story_4_14_67_dialog_content = "Seandainya saja itu orang lain, kita pasti sudah kalah lebih parah.",
  ui_story_4_14_68_dialog_content = "Barusan itu dia memuji kita, ya?",
  ui_story_4_14_69_dialog_content = "Sepertinya begitu.",
  ui_story_4_14_70_dialog_content = "Aku gagal menjalankan kewajibanku sebagai Kapten di Guardian. Aku… aku harus menghadapi hukuman dari Yang Mulia sang Lord.",
  ui_story_4_14_71_dialog_content = "Dia ayahmu. Kurasa dia akan memaafkanmu.",
  ui_story_4_14_72_dialog_content = "Kurasa kau sama sekali tak paham tentang ayahku atau Lumopolis.",
  ui_story_4_14_73_dialog_content = "Kalau begitu, kita harus kembali ke Illumina untuk membahas rencana tindak lanjut.",
  ui_story_4_14_74_dialog_content = "Seperti kata pepatah kuno, \"Kalau terlalu khawatir akan melewatkan hari Senin, kau justru akan melewatkan hari Selasa juga.\"",
  ui_story_4_14_75_dialog_content = "Memangnya ada pepatah seperti itu?",
  ui_story_4_14_76_dialog_content = "Kau sangat optimistis, Vice.",
  ui_story_4_14_77_dialog_content = "Setelah semua kejadian ini, tak ada gunanya bersikap pesimistis!",
  ui_story_4_14_78_dialog_content = "Kalau begitu, aku harus kembali ke Uptown untuk melapor kepada sang Lord. Jaga diri kalian.",
  ui_story_4_14_79_dialog_content = "Mungkin kita akan bertemu lagi, PlayerName…",
  ui_story_4_14_80_dialog_content = "<color=#e8d9bb>Sementara itu, di suatu tempat</color>",
  ui_story_4_14_81_dialog_content = "Kakak beradik itu sudah mati.",
  ui_story_4_14_82_dialog_content = "Memang tak mengherankan, 'kan?",
  ui_story_4_14_83_dialog_content = "Ada yang harus kusampaikan padamu. Pertama, Think Tank Module sudah di tangan kita.",
  ui_story_4_14_84_dialog_content = "Dan si Caelestite itu lagi-lagi menampakkan batang hidungnya.",
  ui_story_4_14_85_dialog_content = "PlayerName, ya?",
  ui_story_4_14_86_dialog_content = "Kau memang tak pernah lupa akan kaummu, ya?",
  ui_story_4_14_90_dialog_content = "Kuulangi sekali lagi. Aku bukan lagi bagian dari ras rendahan itu!!!",
  ui_story_4_14_91_dialog_content = "Anak buahmu yang tolol itu nyaris merusak seluruh rencana kita!",
  ui_story_4_14_92_dialog_content = "Akan kucari modul berikutnya sendirian! Kalau ada yang berani menghalangiku… akan kucabik-cabik sampai remuk.",
  ui_story_4_14_93_dialog_content = "Mana modulnya? Berikan padaku, Gertzurde!",
  ui_story_4_14_95_dialog_content = "Shelt… Shelt… Tidak, tidak!",
  ui_story_4_14_96_dialog_content = "Dia sudah janji padaku… Dia janji akan pergi bersamaku, dan kami akan bebas bersama-sama…",
  ui_story_4_14_97_dialog_content = "Apa yang terjadi…?!",
  ui_story_4_14_98_dialog_content = "Berhentilah bicara dengan dirimu sendiri dengan tampang mengenaskan begitu!",
  ui_story_4_14_99_dialog_content = "Mereka dibunuh Lumopolis Guardians. Harusnya kau senang karena kau masih punya waktu untuk menjalankan tugasmu!",
  ui_story_4_14_100_dialog_content = "Carleen…!",
  ui_story_4_14_101_dialog_content = "Nah, itu baru raut wajah bagus, Gertzurde. Kau tampak sangat berbeda dari foto dalam surat penangkapanmu.",
  ui_story_4_14_102_dialog_content = "Aku akan membalaskan dendam mereka!",
  ui_story_5_1_1_dialog_content = "Itukah keputusanmu, Kapten Carleen?",
  ui_story_5_1_2_dialog_content = "Ya, Lord. Kurasa tidak bijak jika kita mengabaikan Caelestite itu. Dia benar-benar… istimewa.",
  ui_story_5_1_3_dialog_content = "Aku tak akan ikut campur, tapi kuharap kau tetap ingat kau ini ada di pihak mana, Kapten.",
  ui_story_5_1_4_dialog_content = "Siap, Lord. Demi White Night.",
  ui_story_5_1_5_dialog_content = "Aku tahu seperti apa situasinya sekarang. Setengah jam lagi akan ada rapat rutin untuk para Legion Commander. Kau bisa sampaikan briefing mendetail saat rapat itu.",
  ui_story_5_1_6_dialog_content = "Pemecahan masalahnya nanti tergantung pada hasil negosiasinya.",
  ui_story_5_1_7_dialog_content = "Baiklah, kalau begitu, cukup itu saja untuk masalah pertama.",
  ui_story_5_1_A1_dialog_content = "Penyelidikan tentang Eclipsite di dekat koordinat yang sudah disebutkan tadi jadi tugas kalian bertiga, Commander.",
  ui_story_5_1_8_dialog_content = "<size=30>Ehem, PlayerName, itu <color=#FFB400>Sharona</color>, Commander dari 1st Legion.</size>",
  ui_story_5_1_A2_dialog_content = "<size=30>Nah, itu Commander <color=#FFB400>Barton</color> dari 2nd Legion. Dia juga anggota pasukan yang menonjol.</size>",
  ui_story_5_1_9_dialog_content = "Paham. Akhir-akhir ini, ada yang melihat Eclipsite, sepertinya High-Level Eclipsite, di dekat Gannon. Ini jelas patut dicurigai.",
  ui_story_5_1_10_dialog_content = "Karena itulah kami memanggil ketiga Commander ini kemari. Kami ingin semua orang waspada dan tidak mengabaikan ancaman ini.",
  ui_story_5_1_11_dialog_content = "Siapa kedua bocah itu?",
  ui_story_5_1_12_dialog_content = "Mereka masalah kedua untuk hari ini. Giliranmu, Hiiro.",
  ui_story_5_1_13_dialog_content = "Operator Colossus sekaligus Caelestite yang masih hidup, ya?",
  ui_story_5_1_14_dialog_content = "…",
  ui_story_5_1_15_option_content = "Kenapa semua orang memandangiku?",
  ui_story_5_1_16_dialog_content = "Kau tersipu-sipu, ya?",
  ui_story_5_1_X16_dialog_content = "Yap, dasar bocah.",
  ui_story_5_1_17_option_content = "Perlukah, anu, kutunjukkan?",
  ui_story_5_1_18_dialog_content = "Dan menjebol atap dengan Colossus itu?",
  ui_story_5_1_19_dialog_content = "Penuh gejolak, ya! Ada hubungan apa antara kamu dan Schummer, Nak?",
  ui_story_5_1_20_dialog_content = "PlayerName tidak seperti Schummer, Commander!",
  ui_story_5_1_21_dialog_content = "Tenanglah. Memang kita tak bisa membandingkan Caelestite polos yang tak bisa bertarung ini dengan Caelestite yang berkomplot dengan Eclipsite.",
  ui_story_5_1_22_dialog_content = "Hanya saja, aku tak menyangka ternyata masih ada Caelestite yang hidup. Kukira mereka semua sudah binasa dalam malapetaka itu.",
  ui_story_5_1_23_dialog_content = "Kembali soal Schummer yang tadi kausebutkan itu. Tahu apa saja dia tentang ketiga modul itu?",
  ui_story_5_1_24_dialog_content = "Kami tak yakin, karena cara untuk menemukan kedua modul lainnya justru ada dalam Think Tank Module itu.",
  ui_story_5_1_25_dialog_content = "Dan kami yakin Schummer punya Think Tank Module itu, jadi sekarang ini situasinya kurang baik untuk kita.",
  ui_story_5_1_26_dialog_content = "Prioritas utama kita adalah menemukan kedua modul lainnya lebih dulu daripada dia!",
  ui_story_5_1_27_dialog_content = "Kuharap para Commander bisa membantu kami, atau mungkin menangani operasinya.",
  ui_story_5_1_28_dialog_content = "Prioritas Illumina adalah menjaga baris depan dan markas di Gannon City.",
  ui_story_5_1_29_dialog_content = "Akhir-akhir ini, Eclipsite makin gencar menyerang dan membuat pasukan kita kewalahan. Sulit bagiku untuk meminjamkan pasukan.",
  ui_story_5_1_30_dialog_content = "Kuulangi, hanya Grand Marshal yang bisa memerintahku dan legiunku.",
  ui_story_5_1_31_dialog_content = "Bagaimana menurutmu, Hiiro? Apa pendapatmu sebagai atasan Vice?",
  ui_story_5_1_32_dialog_content = "Prajurit Illumina sangat patuh pada perintah.",
  ui_story_5_1_33_dialog_content = "Aku paham.",
  ui_story_5_1_34_dialog_content = "Maaf, PlayerName, tapi kami tak bisa membantumu sebelum kami menerima perintah langsung.",
  ui_story_5_1_35_dialog_content = "Ada yang kaurasakan, PlayerName?",
  ui_story_5_1_36_dialog_content = "Hanya kehampaan. Tak ada yang aneh.",
  ui_story_5_1_37_dialog_content = "Jadi, kita sudah tak punya pilihan lagi sekarang?",
  ui_story_5_1_38_dialog_content = "Sebelum Mendelson mati, dia bilang Schummer pasti akan mencari modul-modul lainnya.",
  ui_story_5_1_39_dialog_content = "Kalau bisa melacak Schummer, mungkin kita bisa mendapatkan informasi lebih banyak dan mengambil tindakan.",
  ui_story_5_1_40_dialog_content = [[
Tapi dia 'kan hilang begitu saja tanpa jejak. 
Masa, kita hanya akan diam saja dan menunggu?]],
  ui_story_5_1_41_dialog_content = "*Huahh* Ya ampun, kenapa serius sekali, sih? Rapatnya bikin pusing?",
  ui_story_5_1_42_dialog_content = "<color=#FFB400>Philyshy</color>!",
  ui_story_5_1_43_dialog_content = "Ayolah, santai saja! Ini ada sesuatu untukmu.",
  ui_story_5_1_44_dialog_content = "<color=#FFB400>Laporan tentang Puing Colossus Tanpa Nama Nomor 13</color>?",
  ui_story_5_1_45_dialog_content = "Aku butuh waktu lama untuk menyusunnya, lho!",
  ui_story_5_1_46_dialog_content = "Vivian benar-benar membuatku tertekan dengan laporan ini. Sungguh berat. Oh, aku mengantuk sekali…",
  ui_story_5_1_47_dialog_content = "\"Modul yang berkembang secara otonom telah ditemukan di lokasi jatuhnya Colossus Tanpa Nama. Bisa jadi, modul ini adalah bagian khusus dari Colossus tipe tersebut…\"",
  ui_story_5_1_48_dialog_content = "\"Unit kuncinya ada di bagian paling dalam dari puing Colossus itu, dan cara membukanya belum diketahui. Penelitian masih berlanjut…\"",
  ui_story_5_1_49_dialog_content = "Dari deskripsinya, sepertinya ini <color=#FFB400>Autonomous Growth Unit</color>!",
  ui_story_5_1_50_dialog_content = "Kebetulan sekali! Tapi, hanya ada satu cara untuk mengetahuinya.",
  ui_story_5_1_51_dialog_content = "Oh, Vivian menyuruhku untuk memberitahumu…",
  ui_story_5_1_52_dialog_content = "Para Commander itu memang tak bisa membantumu sekarang, tapi ada cukup banyak orang di sekitar puing Colossus itu.",
  ui_story_5_1_53_dialog_content = [[
*Hoamss* Aku tak tahan lagi. Aku harus tidur. 
Akan kuhibur kau nanti dalam mimpiku.]],
  ui_story_5_1_54_dialog_content = "Philyshy masih saja seperti biasanya.",
  ui_story_5_1_55_option_content = [[
Seandainya saja ada orang seperti dia
di Colossus.]],
  ui_story_5_1_56_dialog_content = "Dia Intel Chief di Illumina. Kita beruntung karena dia mau membantu.",
  ui_story_5_1_57_dialog_content = "Kalau kita bisa mengajak Philyshy bergabung, setidaknya kita bisa punya sedikit informasi sebagai petunjuk.",
  ui_story_5_1_58_dialog_content = "Tapi, sekarang ini sepertinya dia sangat mengantuk.",
  ui_story_5_1_59_dialog_content = "Mungkin dia stres akibat pekerjaan…",
  ui_story_5_1_60_option_content = "Sebenarnya aku juga agak mengantuk.\nBagaimana kalau kita…",
  ui_story_5_1_61_dialog_content = "Istirahat sebentar?",
  ui_story_5_1_A4_dialog_content = "Tidak, jangan turuti rasa kantukmu, PlayerName! Makin cepat kita bereskan masalah ini…",
  ui_story_5_1_62_dialog_content = "Makin cepat pula aku bisa membawamu ke perpustakaan terbesar di Gannon. Setelah itu, kau boleh bersantai semaumu!",
  ui_story_5_1_63_dialog_content = "Bukannya harusnya kau membawaku ke taman hiburan atau kafe? Masa, aku harus langsung belajar setelah bekerja sih? Tidak manusiawi!",
  ui_story_5_1_64_dialog_content = "Sudahlah, waktu kita tak banyak! Kita harus mendapatkan modul berikutnya lebih dulu daripada Schummer!",
  ui_story_5_1_65_dialog_content = "Ayo nyalakan Colossus-nya!",
  ui_story_5_1_66_dialog_content = "Kau tampak percaya diri. Pasti tadi briefing-nya menyenangkan.",
  ui_story_5_1_67_dialog_content = "Carleen!",
  ui_story_5_1_68_dialog_content = [[
Memang sudah semestinya kau kaget. City Lord mengabulkan permintaanku 
untuk mengurus segala hal terkait Schummer.]],
  ui_story_5_1_69_dialog_content = [[
Siapa pun yang berani menentang Lumopolis akan dihukum, 
dan berpihak pada Eclipsite adalah tindakan yang sama sekali tak bisa diampuni.]],
  ui_story_5_1_70_dialog_content = "<size=30>Awas, lagi-lagi Carleen bergejolak.</size>",
  ui_story_5_1_71_dialog_content = "Apa katamu?",
  ui_story_5_1_72_dialog_content = "Hah? Apa tadi bicaraku terlalu keras?",
  ui_story_5_1_73_dialog_content = "Kalau tak berbuat salah, kau tak perlu takut padaku.",
  ui_story_5_1_A5_dialog_content = [[
Kecuali kau ini Shelt, Gertzurde, dan yang sejenis dengan mereka, 
atau orang-orang yang ada di belakang mereka.]],
  ui_story_5_1_74_dialog_content = "Bukannya Gertzurde mencoba mengalihkan perhatian kita dan berusaha membantu Shelt dan yang lainnya untuk kabur?",
  ui_story_5_1_75_dialog_content = [[
Ya, dia juga pengkhianat yang mencari perlindungan 
di bawah Eclipse dalam kegelapan.]],
  ui_story_5_1_76_dialog_content = "Tapi, tak satu pun pengkhianat bisa bersembunyi dari pedang Schwartz Family, ke mana pun mereka lari.",
  ui_story_5_1_77_dialog_content = "Cukup mengobrolnya. Kita mau ke mana?",
  ui_story_5_1_78_dialog_content = "Puing Colossus Tanpa Nama Nomor 13. Kau sudah pernah lihat puing Colossus, Kapten?",
  ui_story_5_1_79_dialog_content = "Itu tak penting, terutama saat ada urusan yang lebih perlu kuperhatikan.",
  ui_story_5_1_80_dialog_content = [[
Apa pun itu, terima kasih, PlayerName, atas semua yang sudah kaulakukan 
untuk Lumopolis.]],
  ui_story_5_1_81_dialog_content = "Aku akan membantumu dalam misi ini. Aku bersumpah, tak akan kubiarkan pengkhianat itu berhasil!",
  ui_story_5_2_1_dialog_content = "(Aku mendengar suara. Terdengar sedih dan seakan-akan menyimpan kerinduan.)",
  ui_story_5_2_2_dialog_content = "Bunga untuk kampung halaman yang telah musnah, di mana bunga sekali lagi tumbuh dalam embusan angin…",
  ui_story_5_2_3_dialog_content = "Aurora untuk saudara-saudara Aurorian yang telah gugur. Kiranya cahaya menuntun arwah mereka…",
  ui_story_5_2_4_dialog_content = "Kesengsaraan kita pada akhirnya akan berakhir. Dari abu kembali menjadi abu, dari debu kembali menjadi debu…",
  ui_story_5_2_5_dialog_content = [[
Dan saat mentari menyingsing, kita akan menyambut kedamaian sejati 
dalam istirahat kekal.]],
  ui_story_5_2_6_dialog_content = "Apa itu cukup, Guru? Tapi, aku masih takut…",
  ui_story_5_2_7_dialog_content = "Bunga yang kutanam belum mengeluarkan kuncup, padahal aku sangat ingin melihatnya mekar.",
  ui_story_5_2_8_dialog_content = "Jangan takut, Nak. Tutup matamu. Rasa sakit ini hanya sementara. Aku akan selalu bersamamu.",
  ui_story_5_2_9_dialog_content = "(Itu… <color=#FFB400>kaumku</color>? Ini nyata atau hanya khayalanku?)",
  ui_story_5_2_10_dialog_content = "Doa dangkal tak berguna untuk orang yang sudah mati. Ayo, jangan bilang aku tak pernah memberimu pilihan…",
  ui_story_5_2_11_dialog_content = "Kita sudah sampai. Kau baik-baik saja, PlayerName?",
  ui_story_5_2_12_option_content = "Vice…",
  ui_story_5_2_13_dialog_content = "Jangan khawatir, aku di sini. Kau merasakan sesuatu?",
  ui_story_5_2_14_dialog_content = "Hanya bayangan dalam pikiranku… Tapi, siapa mereka?",
  ui_story_5_2_15_dialog_content = "Mungkin para Caelestite yang gugur di sini masih meninggalkan emosi yang kuat.",
  ui_story_5_2_16_dialog_content = "Mereka sudah tiada, 'kan? Jadi, mestinya mereka tak bisa berbicara kepadaku seperti Mendelson.",
  ui_story_5_2_17_dialog_content = "Sayangnya, tidak. Barangkali jasad mereka pun tak tersisa sama sekali.",
  ui_story_5_2_18_option_content = "Aku melihat banyak gambaran dalam pikiranku.",
  ui_story_5_2_19_dialog_content = "Apa kau merasakan pikiran seseorang, PlayerName? Mungkinkah ada kaummu yang masih hidup di sini?",
  ui_story_5_2_A1_dialog_content = "Tak ada Caelestite yang masih hidup di sini. Yang kaulihat itu mungkin hanya semacam ilusi.",
  ui_story_5_2_20_dialog_content = "Gambaran sedih dan putus asa, atau mungkin sisa-sisa pikiran para Caelestite yang sudah meninggal?",
  ui_story_5_2_21_dialog_content = "Kurasa begitu. Rasanya seperti emosi kaumku.",
  ui_story_5_2_A2_dialog_content = "Ayo mendarat, Soroz.",
  ui_story_5_2_24_dialog_content = "Kita berada di <color=#FFB400>puing Colossur Tanpa Nama Nomor 13</color>.",
  ui_story_5_2_25_dialog_content = "Dalam dokumen ini tertulis, \"Orang yang pertama menemukan tempat ini terkesima melihat Colossus yang tertidur…\"",
  ui_story_5_2_26_dialog_content = "\"Bagi mereka, Colossus itu bagaikan bintang tidur yang jatuh dari langit.\"",
  ui_story_5_2_27_dialog_content = [[
"Tak ada tanda-tanda kehidupan di dalam Colossus itu, 
hanya kehampaan yang ditinggalkan oleh waktu."]],
  ui_story_5_2_28_dialog_content = "Rasa tertekan yang sangat kuat… Belum pernah kurasakan hal seperti ini.",
  ui_story_5_2_29_dialog_content = "Tentang malapetaka di Eraveil, aku pernah baca di arsip bahwa…",
  ui_story_5_2_30_dialog_content = "\"Para Eclipsite memberantas kaum Caelestite di Eraveil dalam serangan brutal. Tak seorang pun selamat, selain mereka yang mengikuti Eclipsite.\"",
  ui_story_5_2_31_dialog_content = [[
Tapi saat akhirnya aku sedekat ini, 
ternyata rasanya lebih menyedihkan dari yang kuduga.]],
  ui_story_5_2_A3_dialog_content = "…",
  ui_story_5_2_A4_dialog_content = "Kau pasti juga merasakan macam-macam emosi, Vice.",
  ui_story_5_2_A5_dialog_content = "Iya. Tidak sekuat yang dirasakan PlayerName, tapi aku bisa merasakan dukanya.",
  ui_story_5_2_34_dialog_content = "Bagaimana kau bisa selamat, PlayerName?",
  ui_story_5_2_35_dialog_content = "Yang kuingat hanyalah saat peristiwa itu terjadi, Soroz menjalankan perintah terakhirnya dan membawaku pergi dari sana. Waktu itu aku masih bayi.",
  ui_story_5_2_A6_dialog_content = "Setelah itu, aku hidup di bawah tanah selama 17 tahun, sampai beberapa waktu lalu.",
  ui_story_5_2_36_dialog_content = "Vice membawaku ke dunia luar. Sayangnya, ternyata dunia luar ini pun tak lebih baik.",
  ui_story_5_2_37_dialog_content = "Kuharap aku bisa berbicara dengan kaumku lagi, dan dengan Mendelson.",
  ui_story_5_2_38_dialog_content = "PlayerName…",
  ui_story_5_2_39_dialog_content = "Kita tak boleh biarkan tragedi itu terulang.",
  ui_story_5_2_40_dialog_content = "Tentu saja, jangan sampai ada ras yang binasa seperti itu lagi.",
  ui_story_5_2_41_dialog_content = "Eh, lihat, Colossus paling besar di tengah itu. Itukah yang kita cari?",
  ui_story_5_2_A7_dialog_content = "Berkas ini menyebutkan bahwa itu disebut <color=#FFB400>Liebowitz</color>, satu-satunya Colossus yang punya kemampuan perkembangan otonom.",
  ui_story_5_2_42_dialog_content = "Pasti ada <color=#FFB400>Autonomous Growth Unit</color> di dalamnya.",
  ui_story_5_2_43_dialog_content = "Tapi, Colossus itu sudah sangat bobrok. Apa unitnya masih utuh?",
  ui_story_5_2_44_dialog_content = "Hanya itu yang kutahu dari berkas ini.",
  ui_story_5_2_45_dialog_content = "Ayo masuk. Pasti ada petunjuk di dalamnya.",
  ui_story_5_2_46_dialog_content = [[
Kau pasti sadar betapa berbahayanya ini, PlayerName, 
mengingat apa yang terjadi pada Mendelson.]],
  ui_story_5_2_F1_dialog_content = "Aku tahu. Aku mungkin saja akan menghadapi masalah dan hilang begitu saja seperti dia di dalam sana.",
  ui_story_5_2_47_dialog_content = "Aku masih belum bisa lupa bagaimana Mendelson meninggal dan menghilang. Seakan-akan aku bisa meraih dan menyentuhnya, tapi aku benar-benar tak berdaya.",
  ui_story_5_2_48_dialog_content = "Kita masih bisa putar balik.",
  ui_story_5_2_F2_dialog_content = "Aku juga takut, Vice, tapi aku tak punya pilihan.",
  ui_story_5_2_F3_dialog_content = "Aku sudah memutuskan. Apa pun yang terjadi, akan kuhadapi.",
  ui_story_5_2_49_dialog_content = "Aku paham, dan kau tak akan menghadapinya sendirian. Apa pun yang terjadi, aku akan selalu bersamamu.",
  ui_story_5_2_A8_dialog_content = "<color=#e8d9bb>Di dalam Puing</color>",
  ui_story_5_2_50_dialog_content = "Parah sekali. Sebagian besar komponennya rusak sampai tak bisa dikenali.",
  ui_story_5_2_51_dialog_content = "Mungkin kita harus me-reboot Colossus ini agar bisa mengeluarkannya.",
  ui_story_5_2_52_dialog_content = "Suara siapa itu?",
  ui_story_5_2_53_option_content = "Jangan-jangan… Schummer?",
  ui_story_5_2_54_dialog_content = "Bukan… Itu <color=#FFB400>Gronru</color>!",
  ui_story_5_2_55_option_content = "Orang Illumina?",
  ui_story_5_2_56_dialog_content = "Ya! itu <color=#FFB400>Madam Gronru</color>.",
  ui_story_5_2_57_dialog_content = "Gronru adalah Tech Officer di Illumina, dan dia punya banyak pengetahuan tentang Colossus maupun Lumina.",
  ui_story_5_2_58_dialog_content = "Officer!",
  ui_story_5_2_59_dialog_content = "Vice? Aku tak mengira bala bantuan akan sampai kemari secepat ini…",
  ui_story_5_2_60_dialog_content = "Rupanya kaulah orang yang kata Philyshy harus kuwaspadai!",
  ui_story_5_2_61_dialog_content = "Bisa kaubayangkan? Philyshy bertingkah seakan-akan dia kena mantra, tiba-tiba saja dia tertidur saat tengah-tengah bicara.",
  ui_story_5_2_62_dialog_content = "Aku jadi sendirian dan kewalahan! Aku MARAH SEKALI! Tapi, sekarang aku sadar ternyata aku beruntung!",
  ui_story_5_2_63_dialog_content = "Dan kau juga membawa Colossus yang masih bisa dioperasikan? Luar biasa! Berarti Colossus itu masih utuh!",
  ui_story_5_2_64_dialog_content = "<size=45>Boleh aku mengutak-atiknya?</size>",
  ui_story_5_2_65_dialog_content = "Hah?",
  ui_story_5_2_66_dialog_content = "Ehem, sepertinya aku terlalu bersemangat. Kembali ke tugas utama yang harus kita tangani!",
  ui_story_5_2_67_dialog_content = "Gronru sebenarnya baik, tapi kadang cara bicaranya bisa membuatmu garuk-garuk kepala karena bingung.",
  ui_story_5_2_68_dialog_content = "Mungkin dia terobsesi dengan hal-hal tertentu…",
  ui_story_5_2_69_dialog_content = "Apa kau sendirian saja di sini, Madam Gronru?",
  ui_story_5_2_70_dialog_content = "Iya! Penyelidikannya lambat sekali karena Colossus ini rusak parah. Tugas ini akhirnya hanya jadi semacam quest sampingan.",
  ui_story_5_2_71_dialog_content = "Tapi, tetap saja aku merasa ada sesuatu di dalamnya yang harus kita selidiki lebih cermat.",
  ui_story_5_2_72_dialog_content = "Gamer pro tak boleh meninggalkan quest sampingan tanpa menyelesaikannya, makanya aku meminta untuk kembali kemari untuk melakukan penyelidikan ulang sampai beberapa hari lagi.",
  ui_story_5_2_73_dialog_content = "Oh, apa kau kemari mencari <color=#FFB400>Autonomous Growth Unit</color>?",
  ui_story_5_2_74_dialog_content = "Ya. Apa kau menemukannya saat melakukan penyelidikan?",
  ui_story_5_2_75_dialog_content = "Colossus ini memang punya modul semacam itu, tapi modul itu tak bisa dikeluarkan secara paksa.",
  ui_story_5_2_77_dialog_content = [[
Colossus adalah puncak kejayaan masa lampau, dan tak bisa ditangani 
dengan tingkat teknologi Illumina saat ini.]],
  ui_story_5_2_78_dialog_content = "Tak adakah cara lain?",
  ui_story_5_2_79_dialog_content = "Cara lain? Mungkin ada.",
  ui_story_5_2_80_dialog_content = "Kau pasti <color=#FFB400>satu-satunya Caelestite yang masih hidup</color> yang disebutkan Philyshy, ya? Untuk seorang protagonis, julukanmu itu sungguh tanpa basa-basi!",
  ui_story_5_2_81_dialog_content = "Karena di sini ada Caelestite yang masih hidup dan bernapas, kita bisa mencoba me-reboot barang rongsokan besar ini.",
  ui_story_5_2_82_dialog_content = "Kalau begitu, jangan buang-buang waktu. Ayo cepat…",
  ui_story_5_2_83_dialog_content = "<anim type=Shake>Wooga!</anim>",
  ui_story_5_2_84_dialog_content = "Kita kedatangan tamu. Sepertinya kita harus menyingkirkan sampah itu agar tugas kita bisa dilanjutkan.",
  ui_story_5_2_A9_dialog_content = "Kalau begitu, kita harus melakukannya dengan cepat dan segera!",
  ui_story_5_2_85_dialog_content = "Kau akan menyukai lokasi Autonomous Growth Unit itu…",
  ui_story_5_2_86_dialog_content = "Tempat pembuangan sampah yang dipenuhi belatung? Padahal kukira benda itu istimewa.",
  ui_story_5_2_87_dialog_content = "Modul yang kucari ini ada di tengah-tengah bangkai mengenaskan ini? Jangan bilang aku tak sengaja sudah menghancurkannya.",
  ui_story_5_2_88_dialog_content = "Menjengkelkan sekali. Apa <color=#FFB400>wanita itu</color> mengejekku? Aku 'kan sudah bilang aku tidak seperti orang-orang berengsek lemah itu!",
  ui_story_5_2_89_dialog_content = "Makhluk lemah memang sepatutnya diinjak-injak, dicabik-cabik, dan dibiarkan terhambur terbawa angin!",
  ui_story_5_2_90_dialog_content = "Sial, walau dia memang membantuku, tetap saja ini menjengkelkan.",
  ui_story_5_2_91_dialog_content = "Eclipsite tak berguna itu… Kalau saja waktu itu mereka berhasil menjalankan tugas, harusnya aku tak perlu repot sedikit pun.",
  ui_story_5_2_92_dialog_content = "Dan Caelestite itu, kuharap aku bisa segera bertemu dengannya!",
  ui_story_5_3_1_dialog_content = "Bagian dalamnya rusak parah sampai-sampai kita tak bisa melihat dengan jelas. Kau yakin kita menuju arah yang benar?",
  ui_story_5_3_2_dialog_content = "Tenanglah, aku ini pro. Aku sudah membuat tempat singgah di Bridge. Cuma 200 meter di depan sana.",
  ui_story_5_3_3_dialog_content = "Untuk orang yang kemampuan navigasinya sebagus aku, ini sih semudah membalikkan telapak tangan.",
  ui_story_5_3_4_dialog_content = "Aku dengar sesuatu.",
  ui_story_5_3_5_dialog_content = "Sepertinya bukan dari dekat sini.",
  ui_story_5_3_6_dialog_content = "Bulu kudukku jadi merinding…",
  ui_story_5_3_8_dialog_content = "Ada apa, PlayerName? Kau baik-baik saja?",
  ui_story_5_3_9_dialog_content = "Aku merasakan sesuatu yang lebih kuat daripada High-Level Eclipsite… Mungkin saja itu Schummer!",
  ui_story_5_3_10_dialog_content = "Tetap tenang dan terus maju sesuai rencana.",
  ui_story_5_3_11_dialog_content = "Kalau dia ada di sini, kita habisi dia di sini juga.",
  ui_story_5_3_12_dialog_content = "Tapi…",
  ui_story_5_3_13_dialog_content = "Tak ada tapi. Sudah cukup banyak duka yang ditimbulkannya. Akan kutunjukkan kesalahannya kepadanya.",
  ui_story_5_3_A1_dialog_content = "Maju. Ada lebih banyak Eclipsite menanti kita di depan sana.",
  ui_story_5_3_14_dialog_content = "Aku merasakan sesuatu yang familier. Jangan bilang mereka sudah di sini?",
  ui_story_5_3_16_dialog_content = "Makhluk lemah, sama sekali bukan tandinganku, tapi keras kepala.",
  ui_story_5_3_17_dialog_content = "Mendelson sudah mati, tapi sekarang PlayerName malah menggantikannya untuk melindungi modul itu walau akan sia-sia saja jadinya.",
  ui_story_5_3_18_dialog_content = "Sudah kubilang, satu-satunya pilihan yang benar adalah pilihanku.",
  ui_story_5_3_A2_dialog_content = "Menghunus pedang adalah satu-satunya cara untuk mengendalikan nasib kita. Kalau tidak, kita akan selalu jadi mangsa payah.",
  ui_story_5_3_A3_dialog_content = "Ikuti Lumina itu dan sambut para tamu kita, makhluk rendahan! Saatnya pertempuran besar.",
  ui_story_5_3_A4_dialog_content = "Aku agak tak sabar menunggu saatnya bertarung.",
  ui_story_5_3_A5_dialog_content = "(Eclipsian) Ya... Serang!",
  ui_story_5_7_A14_dialog_content = "Nah, kita sudah sampai di Bridge!",
  ui_story_5_7_A15_dialog_content = "Tetap waspada, siapa tahu para Eclipsite menjengkelkan itu juga ada di sini.",
  ui_story_5_7_A16_dialog_content = [[
Walau sudah lama meneliti dan berusaha, aku masih belum bisa melepas 
Autonomous Growth Unit itu dari Bridge.]],
  ui_story_5_7_A17_dialog_content = "Tapi, kali ini ada seorang Caelestite di sini! Kau pasti bisa me-reboot Colossus ini, 'kan?",
  ui_story_5_7_A18_dialog_content = "Akan kucoba semampuku.",
  ui_story_5_7_1_dialog_content = "Langkah pertama untuk menyalakan Colossus adalah mengukur tingkat energinya.",
  ui_story_5_7_2_dialog_content = "Colossus ini rusak parah, tapi ternyata masih menyimpan cukup banyak energi untuk reboot.",
  ui_story_5_7_3_dialog_content = "Langkah kedua adalah melakukan telepati dengan Colossus ini. Ini satu-satunya cara untuk mengakses panel kontrol, dan yang bisa melakukannya hanyalah Caelestite.",
  ui_story_5_7_4_dialog_content = "Langkah ketiga adalah mengoperasikan kontrolnya…",
  ui_story_5_7_5_dialog_content = "Yap, begitu. Bagus sekali kerjamu.",
  ui_story_5_7_6_dialog_content = "Suara apa itu?",
  ui_story_5_7_7_dialog_content = "Aku senang sekali. Sudah lama sekali aku tak melihat sesama Caelestite, keturunan ras kami.",
  ui_story_5_7_8_dialog_content = "Tumbuh sendirian tanpa pernah berhubungan dengan siapa pun. Pasti berat untukmu.",
  ui_story_5_7_9_dialog_content = "Bagaimana kau bisa tahu itu…",
  ui_story_5_7_11_dialog_content = "Sama sepertimu, aku juga berasal dari Eraveil yang indah.",
  ui_story_5_7_14_dialog_content = "Aku hidup dan belajar bersama kaumku sejak masih anak-anak, mendengarkan lagu dan berbincang dengan Colossus.",
  ui_story_5_7_A1_dialog_content = "Di sana, kami hidup sebagai keluarga yang rukun, PlayerName, dan di sanalah tempat Caelestite.",
  ui_story_5_7_15_option_content = "Tapi, kenapa kau tembus pandang?",
  ui_story_5_7_16_dialog_content = "Kenapa aku tak bisa mengenali wajahmu?",
  ui_story_5_7_17_dialog_content = "Karena aku hanyalah bagian kecil dari kerinduanmu. Kami hanya akan mewujud saat kau ingin melihat kami.",
  ui_story_5_7_18_dialog_content = "Kami berlari, tapi sia-sia saja. Tubuh kami terurai hingga hanya menyisakan tulang, jiwa kami tersebar ke langit tanpa batas.",
  ui_story_5_7_19_dialog_content = "Dia memimpin Eclipsite untuk menghabisi kami dalam pembantaian mengerikan. Itulah kegelapan yang tak bisa ditembus oleh Aurora sekalipun.",
  ui_story_5_7_20_dialog_content = "Sampai sekarang pun, dia masih memegang teguh keyakinannya.",
  ui_story_5_7_21_dialog_content = "Bocah malang. Hidup sendirian, pasti pedih sekali.",
  ui_story_5_7_22_dialog_content = "Aku tak bisa memelukmu, tapi aku bisa memainkan lagu ini bersamamu. Melodi kenangan.",
  ui_story_5_7_23_dialog_content = "Lakukan telepati. Berkomunikasilah dengan Colossus itu seperti saat kau bertelepati dengan Soroz.",
  ui_story_5_7_24_dialog_content = "Terimalah pemberian ini, Anak Terakhir yang belum pernah kutemui.",
  ui_story_5_7_A2_dialog_content = "(Ini hanya penampakan, tapi aku bisa merasakan jemari mereka menyentuh kulitku.)",
  ui_story_5_7_25_dialog_content = "(Aku tahu mereka sudah lama meninggal, tapi bagaimana jiwa mereka bisa menyeberang ke dunia ini untuk menuntunku?)",
  ui_story_5_7_26_dialog_content = "(Nyalakan Colossus agar aku bisa melihatmu.)",
  ui_story_5_7_27_dialog_content = [[
(Kau bernyanyi apa? Bagian refreinnya harmonis sekali. 
Kau berkabung untuk siapa? Aku tahu kau sudah terkubur.)]],
  ui_story_5_7_28_dialog_content = "(Aku belum pernah dengar nyanyian seperti ini, tapi entah kenapa aku bisa bersenandung bersamamu.)",
  ui_story_5_7_29_dialog_content = "(Terima kasih sudah melantunkan lagu ini untukku. Akan kuingat simfoni ini selamanya.)",
  ui_story_5_7_30_dialog_content = "Kaumku, betapa aku berharap kalian masih hidup dan nyata.",
  ui_story_5_7_31_dialog_content = "Colossus-nya bisa di-reboot!",
  ui_story_5_7_32_dialog_content = "Colossus itu menggeram. Kedengarannya seperti sedang menangis, tapi tidak juga, sih…",
  ui_story_5_7_33_dialog_content = "Rasanya seperti ada orang yang bersenandung bersama PlayerName.",
  ui_story_5_7_34_dialog_content = "Biar kubantu, PlayerName.",
  ui_story_5_7_35_dialog_content = "Hampir selesai… 5, 4… Berhasil diaktifkan!",
  ui_story_5_7_36_dialog_content = "Lihat, itu <color=#FFB400>Autonomous Growth Unit</color>!",
  ui_story_5_7_37_dialog_content = "Cepat ambil…",
  ui_story_5_7_38_dialog_content = "Ada apa?!",
  ui_story_5_7_39_dialog_content = "<anim type=Shake>*Meraung*</anim>",
  ui_story_5_7_40_dialog_content = "Sepertinya aku tiba tepat waktu.",
  ui_story_5_7_41_dialog_content = "Schummer?!",
  ui_story_5_7_A3_dialog_content = "Kau pasti PlayerName.",
  ui_story_5_7_A4_dialog_content = [[
Kau lebih muda dari yang kukira. 
Aku suka raut terkejut dan ketakutan di wajahmu itu.]],
  ui_story_5_7_42_dialog_content = "Sudah cukup menyanyinya. Oh, ya, kerjamu bagus untuk mengeluarkan Autonomous Growth Unit itu.",
  ui_story_5_7_A5_dialog_content = "Ternyata yang di hadapanku ini memang kau, Schummer…",
  ui_story_5_7_45_dialog_content = "Sakit… Oh, sakit sekali…",
  ui_story_5_7_46_dialog_content = "Tolong, selamatkan kami…",
  ui_story_5_7_47_dialog_content = "Kau membuatku ingat para Caelestite yang dulu kuremukkan seperti semut, PlayerName.",
  ui_story_5_7_48_dialog_content = "Setiap kali aku ingat bahwa dulu aku pun salah satu dari kaum lemah itu, aku jadi merasa… jijik.",
  ui_story_5_7_49_dialog_content = "Kau terlalu banyak omong.",
  ui_story_5_7_50_dialog_content = "Hanya begitu saja balasanmu? Mengecewakan sekali.",
  ui_story_5_7_51_dialog_content = "Kaukah yang mengirimkan monster-monster busuk itu untuk menyerang Lumopolis?",
  ui_story_5_7_52_dialog_content = "Kau menyebut mereka monster, tapi aku menyebut mereka makhluk ganjil.",
  ui_story_5_7_53_dialog_content = "Perbuatanmu itu tak bisa diampuni, dan kau harus menerima ganjarannya!",
  ui_story_5_7_54_dialog_content = "Memangnya bagaimana kau akan melakukannya?",
  ui_story_5_7_55_dialog_content = "PlayerName! Kau baik-baik saja?!",
  ui_story_5_7_A6_dialog_content = "(Tetap tenang… Jangan biarkan dia mempermainkanku. Aku bisa melakukannya…)",
  ui_story_5_7_A7_dialog_content = "(Lakukan saja seperti biasa, dan kita akan bisa mengalahkan Schummer, sumber dan biang keladi semua kekejaman ini.)",
  ui_story_5_7_A8_dialog_content = "PlayerName, sepertinya kau…",
  ui_story_5_7_A9_dialog_content = "Fyuh…",
  ui_story_5_7_A10_dialog_content = "Aku baik-baik saja, Vice. Ambil posisimu dengan Carleen seperti biasa, aku akan memandu kalian.",
  ui_story_5_7_A11_dialog_content = "Baiklah, aku siap!",
  ui_story_5_7_56_dialog_content = "Berikan komando, PlayerName. Tombakku akan menembus semua makhluk keji!",
  ui_story_5_7_57_dialog_content = "Semuanya, bersiap untuk bertarung! Musuh kita adalah Schummer!",
  ui_story_5_7_A12_dialog_content = "Makhluk lemah harus menyerah pada kehancuran.",
  ui_story_5_7_58_dialog_content = "Buat apa kau berusaha? Perlu kusuruh kau lagi untuk berbaring saja seperti domba lemah?",
  ui_story_5_7_59_dialog_content = "Cih, keras kepala sekali kau ini. Walau memberikan komando dan koordinasi, tetap saja kau ini pengecut yang bersembunyi dari pertarungan sesungguhnya.",
  ui_story_5_7_60_dialog_content = "Tapi, harus kuakui, kau memang agak berbeda dari Caelestite lain.",
  ui_story_5_7_61_option_content = "Tidak, aku sama saja dengan Caelestite lainnya.",
  ui_story_5_7_62_option_content = [[
Mengalahkanmu
sama mudahnya dengan membalikkan telapak tangan.]],
  ui_story_5_7_63_dialog_content = "Jangan konyol. Itu bukan pujian. Itu tadi salam pengantar menuju kuburmu.",
  ui_story_5_7_64_dialog_content = "Toh, kau ini bukan apa-apa dibandingkan aku.",
  ui_story_5_7_65_dialog_content = "Kuat sekali…",
  ui_story_5_7_66_dialog_content = "Pilih mana, diinjak atau dihantam?",
  ui_story_5_7_67_dialog_content = "Sekarang!",
  ui_story_5_7_68_dialog_content = "Getaran apa itu…?",
  ui_story_5_7_69_dialog_content = "Ada tambahan beberapa detik di timer! Kita cukup lihai mengulur waktu!",
  ui_story_5_7_70_dialog_content = "Carleen, PlayerName, aku berhasil mendapatkan modulnya!",
  ui_story_5_7_71_dialog_content = "Akan kusela dia untuk melindungimu. Bawa modul itu dan pergilah.",
  ui_story_5_7_72_option_content = "Tapi, Gronru…",
  ui_story_5_7_73_dialog_content = "Memangnya kenapa? Aku sudah tak sabar ingin memamerkan aksi andalanku!",
  ui_story_5_7_74_option_content = "Siap, Officer!",
  ui_story_5_7_75_dialog_content = "Bagus sekali aksimu memanfaatkan aturan game! Nah, sekarang bawah modul itu ke Illumina!",
  ui_story_5_7_76_dialog_content = "Tapi, Schummer mungkin terlalu tangguh untukmu…",
  ui_story_5_7_77_dialog_content = "Eh, aku bukan peneliti kelas kacangan, tahu! Dibandingkan siapa pun, aku lebih paham tentang kekuatan! Aku sendiri juga sangat kuat!",
  ui_story_5_7_78_dialog_content = "Ayo, Vice, PlayerName. Jangan sia-siakan kesempatan yang sudah diberikan Gronru.",
  ui_story_5_7_79_dialog_content = "Sudah cukup mengocehnya. Serahkan modul itu.",
  ui_story_5_7_80_dialog_content = "Sekarang mau apa? Aku benar-benar ingin bertarung melawanmu!",
  ui_story_5_7_A13_dialog_content = "Pertarungan bos mati-matian melawan seorang Caelestite yang menguasai kekuatan Eclipsite… Kedengarannya seru!",
  ui_story_5_7_81_dialog_content = "Sini, ayo main!",
  ui_story_5_7_82_dialog_content = "Kau membuatku bosan.",
  ui_story_5_7_83_dialog_content = "Sudah cukup lama, Vice. Belum ada kabar dari Gronru.",
  ui_story_5_7_84_dialog_content = "Gronru akan baik-baik saja… kurasa.",
  ui_story_5_7_85_dialog_content = "Kita tak boleh buang-buang waktu. Kita harus lepas landas sekarang.",
  ui_story_5_7_86_dialog_content = "Aku tahu.",
  ui_story_5_7_87_dialog_content = "Kaudengar suara di sistem komunikasi itu?",
  ui_story_5_7_88_dialog_content = "Itu…",
  ui_story_5_7_89_dialog_content = "<color=#FFB400>Madam Gronru</color>?!",
  ui_story_5_8_1_dialog_content = "Vice, cepat pergi dengan Soroz dan bawa modul itu. Pergilah…",
  ui_story_5_8_2_dialog_content = "Madam Gronru!",
  ui_story_5_8_3_dialog_content = "Diam! Bukannya tadi sudah kubilang agar diam saja?!",
  ui_story_5_8_4_dialog_content = "Dengar, makhluk rendahan, karena aku tak akan mengulanginya lagi.",
  ui_story_5_8_5_dialog_content = "Kembalilah kemari dalam 30 menit dan serahkan Autonomous Growth Unit itu kepadaku. Kalau tidak, tamatlah riwayat Officer kacangan ini.",
  ui_story_5_8_6_dialog_content = "Jangan dengarkan dia! Pergi sekarang juga, Vice! Ini perintah!",
  ui_story_5_8_7_dialog_content = "Hush!",
  ui_story_5_8_8_dialog_content = "Illumina tak mungkin bisa mengerahkan bala bantuan dalam waktu 30 menit saja.",
  ui_story_5_8_9_dialog_content = "Akan ada lebih banyak nyawa yang bisa diselamatkan kalau kita membawa Autonomous Growth Unit itu ke Illumina.",
  ui_story_5_8_10_dialog_content = "Saya tahu saya harus mematuhi perintah atasan. Itu selalu menjadi prioritas seorang Illuminan.",
  ui_story_5_8_11_dialog_content = "Tapi, aku tak bisa begitu saja meninggalkan Gronru dan membiarkannya mati.",
  ui_story_5_8_12_dialog_content = "Dalam bahasa halus, kau ini penuh kasih seperti biasanya… Dalam bahasa agak keras, kau ini tak bisa mengambil keputusan.",
  ui_story_5_8_13_dialog_content = "Memangnya sesulit itu kalau harus memilih antara satu nyawa atau banyak nyawa?",
  ui_story_5_8_14_dialog_content = "Aku ingin melindungi semua orang.",
  ui_story_5_8_15_dialog_content = "*Meraung*",
  ui_story_5_8_16_dialog_content = [[
Sekarang, kita bereskan dulu tamu-tamu tak diundang di Colossus ini. 
Yang lainnya kita pikirkan belakangan.]],
  ui_story_5_10_1_dialog_content = "Coba kutebak kenapa kalian masih belum memutuskan… Masih berusaha mengulur waktu lagi?",
  ui_story_5_10_2_dialog_content = "Kesabaranku hampir habis. Waktu kalian tinggal 20… eh, 19 menit.",
  ui_story_5_10_3_dialog_content = "Dalam 19 menit, aku akan mulai mencabik-cabik cewek ini sedikit demi sedikit.",
  ui_story_5_10_4_dialog_content = "Ya ampun, membayangkan dia menjerit kesakitan saja sudah membuatku senang.",
  ui_story_5_10_5_dialog_content = "Tak adakah cara lain untuk menyelamatkan Gronru selain menyerahkan modul ini?",
  ui_story_5_10_6_dialog_content = "Dia sinting!",
  ui_story_5_10_7_option_content = "Mungkin ada cara lain.",
  ui_story_5_10_8_dialog_content = "Hah?",
  ui_story_5_10_9_dialog_content = "Aku punya ide yang mungkin bisa berhasil, asalkan ada waktu 15 menit.",
  ui_story_5_10_10_dialog_content = "Maksudmu?",
  ui_story_5_10_11_dialog_content = "Mungkin kita bisa melakukannya dengan jalan memutar…",
  ui_story_5_10_12_option_content = "Aku ingin melindungi semua orang.",
  ui_story_5_10_13_dialog_content = "Kau setuju denganku, PlayerName?",
  ui_story_5_10_14_dialog_content = "Ya. Entah Gronru atau orang lain, kita harus melindungi mereka semua.",
  ui_story_5_10_15_dialog_content = "Pertama Vice, sekarang kamu. Aku menyerah.",
  ui_story_5_10_16_dialog_content = "Tapi, karena sudah bilang begitu, berarti kau pasti punya rencana.",
  ui_story_5_10_17_dialog_content = "Ya. Sangat berisiko, makanya aku butuh bantuanmu.",
  ui_story_5_10_A1_dialog_content = "Kita harus agresif dan bergerak cepat!",
  ui_story_5_10_A2_dialog_content = "Dengarkan aku, begini rencananya…",
  ui_story_5_10_18_dialog_content = "Hanya tersisa beberapa menit lagi. Belum juga mendarat atau berangkat. Masih berdebat?",
  ui_story_5_10_19_dialog_content = "Aktifkan Throne!",
  ui_story_5_10_20_dialog_content = "Ceroboh sekali.",
  ui_story_5_10_21_dialog_content = "Gagal lagi!",
  ui_story_5_10_22_dialog_content = "Sudah tiga kali kau melancarkan serangan bunuh diri. Mau cari mati ya? Untung buatmu, ini belum saatnya kau mati.",
  ui_story_5_10_23_dialog_content = "Shocking Combo…",
  ui_story_5_10_24_dialog_content = "Pusing sekali! Apa game-nya sudah tamat…?",
  ui_story_5_10_25_dialog_content = "Tidurlah. Beberapa menit lagi akan kubuat kau tidur untuk selamanya.",
  ui_story_5_10_A3_dialog_content = "Ini, satu lagi!",
  ui_story_5_10_A4_dialog_content = "Mulus sekali! Schummer tidak melihat kita, 'kan?",
  ui_story_5_10_A5_dialog_content = "Aku tak begitu cocok untuk operasi rahasia, PlayerName.",
  ui_story_5_10_A6_dialog_content = "Aksimu bagus. Ayo lanjutkan, toh kita tak punya pilihan lain.",
  ui_story_5_13_1_dialog_content = "Bangun, waktumu masih 5 menit lagi.",
  ui_story_5_13_2_dialog_content = "Aku melihat bintang… Kalau kukumpulkan, apa aku bisa naik level?",
  ui_story_5_13_3_dialog_content = "Bangun sekarang juga, bodoh.",
  ui_story_5_13_4_dialog_content = "Hoi, kejam sekali kau ini, menghantamku sampai pingsan lalu langsung memaksaku bangun!",
  ui_story_5_13_5_dialog_content = "Tinggal 5 menit lagi dan masih belum ada respons. Mungkin mereka sudah menelantarkanmu.",
  ui_story_5_13_6_dialog_content = "Memang seharusnya begitu! Akan kuwakili kau menghajar mereka kalau mereka sampai berani kembali kemari!",
  ui_story_5_13_7_dialog_content = "Begitu juga tak apa, aku sudah lelah menunggu.",
  ui_story_5_13_A1_dialog_content = "Ini tidak optimal, sih. Tapi, menghabisimu sekarang dan membereskan mereka belakangan juga bukan pilihan buruk.",
  ui_story_5_13_8_dialog_content = "Eh, kau mau membunuh sandera padahal waktunya belum habis? Bukan begitu cara main game-nya!",
  ui_story_5_13_9_dialog_content = "Kuberi tahu, ya. Aturan main game ditentukan oleh pihak yang kuat!",
  ui_story_5_13_A2_dialog_content = "Nah, sekarang, akan kubungkam mulut cerewetmu itu untuk terakhir kalinya!",
  ui_story_5_13_10_dialog_content = "Apa-apaan…?!",
  ui_story_5_13_11_dialog_content = "Ice Blossom!",
  ui_story_5_13_12_dialog_content = "Lagi-lagi serangan diam-diam…",
  ui_story_5_13_13_dialog_content = "Dia tak sabar. Kurasa mungkin dia tak akan mengikuti aturan.",
  ui_story_5_13_14_dialog_content = "Gronru dalam bahaya besar. Kita harus bertindak secepat mungkin.",
  ui_story_5_13_A3_dialog_content = "Aku siap mengikuti rencanamu, PlayerName!",
  ui_story_5_13_A13_dialog_content = "Biarkan Soroz tetap di lokasi kita tadi untuk mengalihkan perhatian Schummer, lalu…",
  ui_story_5_13_17_dialog_content = "Lancarkan serangan tiba-tiba!! Dia tak akan mengira kita akan menerjangnya seperti itu!!",
  ui_story_5_13_18_dialog_content = "Pura-pura ragu, lalu menyerbu?",
  ui_story_5_13_19_dialog_content = "Iya. Yah, berhasil, 'kan? Menyerahlah, Schummer! Kami juga sudah memberantas para Eclipsite itu!",
  ui_story_5_13_20_dialog_content = "Kalau ini yang kalian sebut \"berhasil\"…",
  ui_story_5_13_21_dialog_content = "Jangan lupakan aku! Ciatt!",
  ui_story_5_13_22_dialog_content = "Combo-nya berhasil! Bos Besar Jahat terluka dan tim kita berhasil berkumpul lagi! Keadaan berbalik!",
  ui_story_5_13_A4_dialog_content = "Kalian pasti sudah menyembunyikan modul penting itu di tempat aman, 'kan? Sekarang kita bisa mengeroyoknya dengan adil dan tanpa basa-basi!",
  ui_story_5_13_24_dialog_content = "Ayo kita ikut beraksi, Carleen!",
  ui_story_5_13_26_dialog_content = "Benar, terus tekan dia!",
  ui_story_5_13_27_dialog_content = "Cuma itu kemampuanmu?",
  ui_story_5_13_28_dialog_content = "Aku tak percaya makhluk rendahan seperti kalian bisa meremehkanku.",
  ui_story_5_13_29_dialog_content = "Ada yang berubah!",
  ui_story_5_13_30_dialog_content = "Kekuatannya terasa berbeda dari sebelumnya!",
  ui_story_5_13_31_dialog_content = "Cukup! Karena kalian semua begitu tak sabar ingin mati, aku tak akan setengah-setengah lagi!",
  ui_story_5_13_A14_dialog_content = "Bagus, perlawanan kalian sekarang lebih sengit! Sekarang jadi cukup menyenangkan…",
  ui_story_5_13_A15_dialog_content = "Kepongahan kalian membuatku risih, tahu! Berlututlah!",
  ui_story_5_13_A16_dialog_content = "Kok dia malah jadi makin kuat?",
  ui_story_5_13_A17_dialog_content = "Rupanya dari tadi kau menahan diri… hanya untuk mempermainkan kami?",
  ui_story_5_13_32_dialog_content = "(Kalau terus begini, kami semua akan mati!)",
  ui_story_5_13_A5_dialog_content = "(Apakah dulu kaumku juga berjuang sia-sia seperti ini? Kekuatannya luar biasa…)",
  ui_story_5_13_33_dialog_content = "(Sengeri inikah Caelestite yang punya kekuatan Eclipsite?)",
  ui_story_5_13_34_dialog_content = "Kaget sekaligus kagum? Kekuatan Eclipse bisa mengubah Caelestite paling lemah sekalipun menjadi tak terkalahkan.",
  ui_story_5_13_35_dialog_content = "<size=45>Bahkan lebih kuat dari Aurorian!</size>",
  ui_story_5_13_36_dialog_content = "Sakit sekali… Aku tak bisa… bernapas…",
  ui_story_5_13_37_dialog_content = "Sekarang, kalian pilih, nyawanya atau Autonomous Growth Unit itu?",
  ui_story_5_13_38_dialog_content = "*Batuk-batuk* Tidak, jangan berikan modul itu…",
  ui_story_5_13_39_dialog_content = "Gronru! Vice, Carleen…",
  ui_story_5_13_40_dialog_content = "Aku masih bisa bertarung, sialan… Aku tahu aku mampu…",
  ui_story_5_13_41_dialog_content = "Aku…",
  ui_story_5_13_42_dialog_content = "Kau masih ingin melawanku? Tanpa secuil pun kekuatan Lumina?",
  ui_story_5_13_43_dialog_content = "Ya ampun, ini sangat menarik sekaligus konyol!",
  ui_story_5_13_44_dialog_content = "Aku mungkin memang tak punya Lumina, tapi aku masih punya tinjuku!",
  ui_story_5_13_45_dialog_content = "Schummer!",
  ui_story_5_13_46_dialog_content = "Jangan, PlayerName!",
  ui_story_5_13_47_dialog_content = "Walau tak bisa mengontrol Lumina, aku tak takut bertarung!",
  ui_story_5_13_48_dialog_content = "Aku harus melindungi teman-temanku, kaumku, dan keluargaku!",
  ui_story_5_13_A6_dialog_content = "Kalau tanganku patah, aku masih bisa menggigit. Kalau gigiku rontok, aku masih bisa menyundul dengan kepalaku!",
  ui_story_5_13_A7_dialog_content = "Kau tak bisa memaksaku menyerah, Schummer. Kali ini, kau…",
  ui_story_5_13_49_dialog_content = "<size=45>harus mengalahkanku dulu kalau mau menyentuh mereka!</size>",
  ui_story_5_13_A8_dialog_content = "…",
  ui_story_5_13_A9_dialog_content = "Apa gunanya ini?",
  ui_story_5_13_50_dialog_content = "Memangnya kau harus teriak begitu? Pidato heroikmu itu klise sekali.",
  ui_story_5_13_51_dialog_content = "Argh…",
  ui_story_5_13_52_dialog_content = "Kenapa, PlayerName?",
  ui_story_5_13_53_dialog_content = "Ambil keputusan, pengecut. Modul itu, atau nyawa mereka. Kuhitung, ya. Sepuluh, sembilan…",
  ui_story_5_13_54_option_content = "Aku punya usul…",
  ui_story_5_13_55_option_content = "Baiklah, ini modulnya.",
  ui_story_5_13_56_dialog_content = "Kau? Punya usul untukku? Sungguh?",
  ui_story_5_13_57_dialog_content = "Modulnya boleh kaubawa, tapi kau harus melepaskan mereka dulu!",
  ui_story_5_13_58_dialog_content = "Kau serius? Kau harus berlutut dan memohon belas kasihanku.",
  ui_story_5_13_59_dialog_content = "Lepaskan mereka, lalu kau boleh bawa aku dan modulnya. Kalau tidak, akan kuhancurkan modulnya.",
  ui_story_5_13_60_dialog_content = "Menghancurkannya? Apa kau meniru langkah \"berusaha sampai mati\" ini dari Mendelson? Menjijikkan sekali.",
  ui_story_5_13_F1_dialog_content = "Baiklah. Mereka boleh pergi.",
  ui_story_5_13_F2_dialog_content = "Ini modulnya.",
  ui_story_5_13_F3_dialog_content = "Caelestite malang. Tanpa kekuatan, kau mudah sekali dihabisi. Keselamatan nyawamu hanya bergantung pada belas kasihan dari pihak yang kuat.",
  ui_story_5_13_F4_dialog_content = "Oh, kau tersinggung?",
  ui_story_5_13_F5_dialog_content = "Kau jadi teringat masa lalu?",
  ui_story_5_13_F6_dialog_content = "Ingat-ingatlah perasaan itu. Yang <size=45>lemah</size> harus menanggung penghinaan hanya agar bisa bertahan hidup.",
  ui_story_5_13_61_dialog_content = "Caelestite malang. Tanpa kekuatan, kau mudah sekali dihabisi. Keselamatan nyawamu hanya bergantung pada belas kasihan dari pihak yang kuat.",
  ui_story_5_13_F7_dialog_content = "Kalau bukan demi mendapatkan modul itu, melihat wajah kalian pun aku tak sudi.",
  ui_story_5_13_68_dialog_content = "Selamat, aku memberimu kesempatan untuk hidup. Syukurilah!",
  ui_story_5_13_69_dialog_content = "Kau baik-baik saja, Gronru? Sudah dua jam kau tak sadarkan diri…",
  ui_story_5_13_70_dialog_content = "Jangan khawatir, aku ini keras kepala, aku tak akan mati begitu saja…",
  ui_story_5_13_F8_dialog_content = "Maaf, kau jadi terpaksa menyerahkan modul itu demi menyelamatkan nyawaku.",
  ui_story_5_13_71_dialog_content = "Tidak, salahku sendiri karena tak cukup kuat untuk mengalahkannya.",
  ui_story_5_13_72_dialog_content = "Setidaknya kita semua masih hidup. Kita cukup beruntung.",
  ui_story_5_13_73_dialog_content = "Kau memang sangat mengesankan!",
  ui_story_5_13_74_dialog_content = "Waktu Philyshy memberitahuku, aku tak begitu peduli, tapi sekarang setelah aku menyaksikannya sendiri…",
  ui_story_5_13_A10_dialog_content = "Schummer ternyata memang lebih mengerikan dari yang kuduga!",
  ui_story_5_13_75_dialog_content = "Akan kubereskan semuanya, melapor kepada atasanku, dan memperingatkan mereka tentang betapa seriusnya masalah ini.",
  ui_story_5_13_76_dialog_content = "Masih ada modul ketiga, 'kan?",
  ui_story_5_13_77_dialog_content = "<color=#FFB400>Flame Control Module…</color>",
  ui_story_5_13_78_dialog_content = "Komponen senjata ultra untuk menambahkan teknologi baru \nke Colossus dan melengkapinya dengan kemampuan menyerang… \nNamun, kita tak tahu tentang keberadaannya.",
  ui_story_5_13_79_option_content = "Aku tahu apa yang harus kita lakukan.",
  ui_story_5_13_F9_dialog_content = "Aku sudah berulang kali melihatnya, jadi aku tak akan pernah lupa auranya.",
  ui_story_5_13_F10_dialog_content = "Dia tidak jauh dari lokasi kita. Aku hanya perlu memejamkan mata.",
  ui_story_5_13_F11_dialog_content = "Dia tak akan menyadari keberadaanku, asalkan aku menyelinap seperti makhluk lemah.",
  ui_story_5_13_80_dialog_content = "(Apa itu labirin bizantium dengan banyak sekali jebakan?)",
  ui_story_5_13_81_dialog_content = "(Misterius, gelap, dan penuh dengan benda-benda aneh…)",
  ui_story_5_13_82_dialog_content = "Schummer pasti tahu arah yang ditujunya.",
  ui_story_5_13_83_dialog_content = "Ini <color=#FFB400>Whispering Corridor</color>…",
  ui_story_5_13_85_option_content = "Whispering Corridor!",
  ui_story_6_1_1_dialog_content = "Tak diragukan lagi, Schummer memang lawan yang berbahaya…",
  ui_story_6_1_2_dialog_content = "Kalau sampai dia berhasil mengumpulkan semua modul yang dibutuhkan, dia akan makin sulit dihadapi…",
  ui_story_6_1_3_dialog_content = "(Carleen dan Vice sangat tertekan. Mungkin aku harus bilang sesuatu?)",
  ui_story_6_1_F1_dialog_content = "Kalau kita kejar Schummer sekarang, mungkin kita bisa menghalanginya agar tak mendapatkan modul berikutnya!",
  ui_story_6_1_F2_dialog_content = "Jelas, ini berbahaya…",
  ui_story_6_1_4_option_content = "Jadi, bagaimana menurutmu, Carleen?",
  ui_story_6_1_5_dialog_content = "Aku setuju. Jangan buang-buang waktu. Kita harus kejar Schummer sekarang juga!",
  ui_story_6_1_6_option_content = "Bagaimana menurutmu, Vice?",
  ui_story_6_1_7_dialog_content = "Aku sudah mengirimkan pesan ke Markas untuk memberi tahu bahwa kita sedang menuju <color=#FFB400>Whispering Corridor</color>.",
  ui_story_6_1_8_dialog_content = "Ada yang punya informasi tentang Whispering Corridor?",
  ui_story_6_1_9_dialog_content = "Setahuku, tempat itu ada dalam kekuasaan <color=#FFB400>Umbraton</color>, Carleen. Aku pernah dengar tentang tempat itu sewaktu aku masih bersekolah di Lumopolis.",
  ui_story_6_1_10_dialog_content = "Tak mengherankan kalau kau tahu, kau memang siswa teladan. Pasti masih ada informasi lain yang kauketahui, 'kan?",
  ui_story_6_1_11_dialog_content = "Eh, anu, Whispering Corridor adalah reruntuhan kuno di luar Umbraton.",
  ui_story_6_1_12_dialog_content = "Setelah Lumopolis menemukan dan menggalinya, di sana ditemukan banyak sekali peninggalan arkeologi berharga.",
  ui_story_6_1_13_dialog_content = "Tapi, setelah digali lebih lanjut dan ternyata tak ada lagi penemuan berharga, orang-orang pun mulai kehilangan ketertarikan, dan reruntuhan itu akhirnya ditelantarkan.",
  ui_story_6_1_14_dialog_content = "Sejak itu, tempat tersebut menjadi tempat berkumpulnya gelandangan dan penjahat, dan sangat rawan kejahatan.",
  ui_story_6_1_A1_dialog_content = "Kira-kira sepuluh tahun lalu, sebuah organisasi bernama <color=#FFB400>Istvan Gang</color> muncul di Umbraton.",
  ui_story_6_1_A2_dialog_content = "Istvan, pemimpin organisasi itu, yang namanya juga dijadikan nama organisasinya, sangat dihormati oleh masyarakat Umbraton, dan mereka menyebutnya \"Shadowlord\".",
  ui_story_6_1_A3_dialog_content = "Setelah dia menguasai Whispering Corridor, tak seorang pun berani memasuki tempat itu.",
  ui_story_6_1_A4_dialog_content = "Menurut kabar, sekarang tempat itu menjadi gudang berisi segala macam barang antik berharga yang tak dikenal.",
  ui_story_6_1_A5_dialog_content = "Memang enak kalau punya ensiklopedia berjalan.",
  ui_story_6_1_F3_dialog_content = "Kembali kasih, deh!",
  ui_story_6_1_A6_dialog_content = "Aku juga sudah mengirimkan pesan kepada Shadowlord untuk membantu kita.",
  ui_story_6_1_A7_dialog_content = "Siapa tahu dia ternyata sudah menugaskan orang untuk menunggu dan memandu kita begitu kita sampai di Whispering Corridor, 'kan?",
  ui_story_6_1_A8_dialog_content = "Kalau gaya bahasa suratmu masih seperti biasanya, aku yakin Shadowlord pasti akan langsung mengabaikannya.",
  ui_story_6_1_F4_dialog_content = "Hoi, tak masalah gaya bahasaku bagus atau tidak! Tetap saja aku harus mengirimkan pesan itu!",
  ui_story_6_1_15_dialog_content = "Oh, aku masih punya informasi lain. Militer Illumina baru saja menggelar rapat lagi…",
  ui_story_6_1_16_dialog_content = "Kuingatkan kalian, ya. Walaupun Whispering Corridor memang bagian dari teritori Shadowlord, mengingat siapa yang mengancam kita…",
  ui_story_6_1_17_dialog_content = "Serta keterlibatan Tech Officer Gronru, ini dianggap provokasi terang-terangan.",
  ui_story_6_1_F5_dialog_content = "Kalau saja PlayerName dan rekan-rekannya tidak mengabari kita, kita tak akan tahu rencana Schummer.",
  ui_story_6_1_18_dialog_content = "Sial, kalau bukan gara-gara para cecunguk itu, ini semua tak akan terjadi!",
  ui_story_6_1_19_dialog_content = "Tidak. Keberadaan PlayerName tak ada hubungannya dengan upaya Schummer untuk mendapatkan modul itu.",
  ui_story_6_1_20_dialog_content = "Tak usah ceramah, Hiiro! Pasukanmu jadi ikut denganku atau tidak?",
  ui_story_6_1_21_dialog_content = "Yah…",
  ui_story_6_1_22_dialog_content = "Bukannya aku tidak mau. Aku juga berpandangan sama sepertimu tentang orang-orang yang mengancam Illumina.",
  ui_story_6_1_23_dialog_content = "Tapi, Grand Marshal memerintahkan kita untuk siaga dan menunggu kesempatan yang tepat.",
  ui_story_6_1_X23_dialog_content = "Kenapa Grand Marshal memberikan perintah itu?",
  ui_story_6_1_X24_dialog_content = "Semuanya, tetap tenang. Aku paham perasaan kalian.",
  ui_story_6_1_X25_dialog_content = "Tapi, kita hanya bisa siaga dan mengamati sampai kita mendapatkan perintah baru dari Grand Marshal.",
  ui_story_6_1_X26_dialog_content = "Mungkin dia lebih paham situasinya daripada kita. Kita harus yakin pada Illumina!",
  ui_story_6_1_X27_dialog_content = "…",
  ui_story_6_1_X28_dialog_content = "Di mana Barton dan pasukannya? Kenapa mereka tidak datang?",
  ui_story_6_1_X29_dialog_content = "Kalau dia dan wanita berotot itu setuju untuk mengerahkan pasukan, setidaknya kita bisa bernegosiasi dengan Grand Marshal untuk…",
  ui_story_6_1_X30_dialog_content = "Para Legion Commander yang lain juga punya tugas sendiri-sendiri, tahu!",
  ui_story_6_1_X31_dialog_content = "Kau ikut denganku untuk menjaga area pinggiran Lumopolis, Sharona!",
  ui_story_6_1_25_dialog_content = "Setidaknya, kita harus menunjukkan performa bagus!",
  ui_story_6_1_27_dialog_content = "Jadi, begitu situasinya saat ini. Kita harus bertindak sendiri untuk mencari tahu apa yang direncanakan Schummer.",
  ui_story_6_1_28_dialog_content = "Waktu itu kita cukup beruntung karena ada Philyshy dan Gronru yang membantu kita, tapi kali ini…",
  ui_story_6_1_F6_dialog_content = "Tujuan kita adalah bagian yurisdiksi Umbraton, dan Umbraton berada persis di bawah Lumopolis…",
  ui_story_6_1_F7_dialog_content = "Aku paham. Illumina dan Lumopolis memang bekerja sama, tapi masing-masing punya kepentingannya sendiri.",
  ui_story_6_1_29_dialog_content = "Walau begitu, permainan politik tak akan ada gunanya untuk kedua belah pihak, terutama dalam situasi seperti sekarang ini.",
  ui_story_6_1_30_dialog_content = "Biar kutangani urusan di pihak Lumopolis. Setidaknya…",
  ui_story_6_1_31_dialog_content = "Laporan status, Kapten Carleen?",
  ui_story_6_1_32_dialog_content = "Maaf, kami gagal. <color=#FFB400>Autonomous Growth Unit</color> itu berhasil direbut.",
  ui_story_6_1_33_dialog_content = "Ada korban?",
  ui_story_6_1_34_dialog_content = "Tidak.",
  ui_story_6_1_35_dialog_content = "Sayangnya, mereka selangkah lebih dulu daripada kita, dan sudah pergi menuju Whispering Corridor.",
  ui_story_6_1_36_dialog_content = "Lord Schwartz, dengan rendah hati aku meminta bantuan dari Guardian. Akan lebih baik kalau Four Angels bisa membantu.",
  ui_story_6_1_37_dialog_content = "Ditolak.",
  ui_story_6_1_38_dialog_content = "Ay… maksudku, Lord, kalau dia sampai berhasil mendapatkan <color=#FFB400>Flame Control Module</color>, akibatnya akan sangat mengerikan!",
  ui_story_6_1_39_dialog_content = "Dia bahkan mungkin akan mengancam Lumopolis lagi setelah mengisi ulang daya Colossus miliknya!",
  ui_story_6_1_40_dialog_content = "Ya, aku sudah mempertimbangkannya, Kapten Carleen, dan karena itulah aku memutuskan untuk tidak mengerahkan Guardian.",
  ui_story_6_1_41_dialog_content = "Sebagai Kapten mereka, aku punya wewenang atas Guardian, Lord. Tolong izinkan aku mengerahkan mereka.",
  ui_story_6_1_42_dialog_content = "Aku bisa dengan mudah mencabut wewenangmu itu, Kapten.",
  ui_story_6_1_43_dialog_content = "Kalau begitu, sebagai Kapten, aku akan mengirimkan bala bantuan kepada mereka atas nama Lumopolis, bahkan walaupun bala bantuannya hanya aku sendirian.",
  ui_story_6_1_45_dialog_content = "Kuhargai keberanianmu, Carleen.",
  ui_story_6_1_46_dialog_content = "PlayerName! Sebagai warga Lumopolis, kuharap kau bisa memastikan keselamatan Kapten Carleen.",
  ui_story_6_1_47_dialog_content = "Apa…? Ya, tentu saja.",
  ui_story_6_1_48_dialog_content = "<size=30>Aku dan PlayerName sebenarnya sama sekali bukan warga Lumopolis…</size>",
  ui_story_6_1_49_dialog_content = "Walaupun Carleen bukan seorang Kapten sekalipun, kami akan tetap saling melindungi, apa pun yang terjadi! Itu gunanya teman!",
  ui_story_6_1_50_dialog_content = "Cukup basa-basinya. Sebentar lagi kita sampai!",
  ui_story_6_1_51_dialog_content = "Sejauh mata memandang, yang tampak hanya belantara. Sudah lama sekali tak ada orang datang kemari.",
  ui_story_6_1_52_dialog_content = "Untungnya, kita punya Soroz. Kalau tidak, mustahil kita bisa menyusul Schummer!",
  ui_story_6_1_F8_dialog_content = "Dengar tidak, Soroz? Vice memujimu!",
  ui_story_6_1_53_dialog_content = "Melayanimu memang sudah jadi tugasku, Navigator. Aku merasa terhormat bisa membantu kalian semua.",
  ui_story_6_1_54_dialog_content = "Tapi, tempat ini punya aura ngeri, sama seperti Eraveil… Hati-hati.",
  ui_story_6_1_55_dialog_content = "Tempat ini mungkin sudah dipenuhi Eclipsite, PlayerName… Apa Soroz akan aman di sini?",
  ui_story_6_1_56_dialog_content = "Tempat ini dekat dengan perbukitan, dan di sini ada hutan yang cukup besar untuk tempat berlindung.",
  ui_story_6_1_57_dialog_content = "Tak usah khawatir, Colossus kami sudah menguasai seni kamuflase. Kita hanya perlu fokus untuk bertarung, dan Soroz akan menunggu di sana saat kita kembali nanti.",
  ui_story_6_1_58_dialog_content = "Senang rasanya kalau ada orang yang menunggu kita. Nah, kalau saja dia juga bisa menyiapkan air panas untuk kita mandi…",
  ui_story_6_1_59_dialog_content = "Itu cara yang sungguh kekanak-kanakan untuk menggunakan Colossus…",
  ui_story_6_1_A9_dialog_content = "Oh, ya, aku tak melihat ada tempat yang kira-kira seperti gudang di belantara ini.",
  ui_story_6_1_A10_dialog_content = "Kalau tidak mencari, pintu masuk ke Whispering Corridor tak mungkin bisa ditemukan.",
  ui_story_6_1_A11_dialog_content = "Kalau begitu, apa itu artinya kau sudah…",
  ui_story_6_1_A12_dialog_content = "Benar, persis di bawah kaki kita!",
  ui_story_6_1_A13_dialog_content = "Di bawah kita? Whispering Corridor ada di bawah tanah?",
  ui_story_6_1_A14_dialog_content = "Jaga pijakan kalian, aku akan mengaktifkan pintu masuknya!",
  ui_story_6_1_A15_dialog_content = "Tanahnya runtuh!",
  ui_story_6_1_A16_dialog_content = "Wow, ini…",
  ui_story_6_1_A17_dialog_content = "Repot sekali untuk dilewati dan dibangun. Kenapa ada yang mendesainnya seperti ini, sih?",
  ui_story_6_1_A18_dialog_content = "Yang mau sembunyi di lubang seperti ini hanya penjahat dan tikus.",
  ui_story_6_1_A19_dialog_content = "Whispering Corridor persis di bawah kita. Kau bisa merasakan sesuatu, PlayerName?",
  ui_story_6_1_60_dialog_content = "Schummer… Mestinya dia ada di bawah sana. Aku bisa merasakan aura sangat seram dari bawah sana.",
  ui_story_6_1_A20_dialog_content = "Ternyata kau tak bercanda… Di dalam sini dingin sekali!",
  ui_story_6_1_A21_dialog_content = "Bukan saatnya mengeluh. Kita harus bergegas!",
  ui_story_6_1_61_dialog_content = "Kau bisa melacak lokasi persisnya?",
  ui_story_6_1_62_dialog_content = "Maaf, aku hanya tahu dia ada di suatu tempat di Whispering Corridor. Aku tak bisa memastikan lokasi persisnya.",
  ui_story_6_1_63_dialog_content = "Ini tak akan mudah…",
  ui_story_6_1_64_dialog_content = "Kata orang, Whispering Corridor adalah labirin penuh dengan pintu dan jalan rahasia… dan hanya Shadowlord yang tahu seluk-beluknya.",
  ui_story_6_1_65_dialog_content = "Inilah alasan utama banyak orang menduga bahwa Whispering Corridor adalah gudang berisi artefak berharga.",
  ui_story_6_1_F9_dialog_content = "Jelas, menyimpan barang di sini jauh lebih aman daripada menimbunnya di Umbraton.",
  ui_story_6_1_66_dialog_content = "Sebentar, ada yang datang!",
  ui_story_6_1_67_dialog_content = "Hati-hati! Mungkin saja itu Eclipsite…",
  ui_story_6_1_68_dialog_content = "Karena PlayerName sangat tenang, kurasa yang datang itu Aurorian.",
  ui_story_6_1_70_dialog_content = "Nah, ada apa di sini? Aku bisa dengar kalian mengobrol dari balik setiap pintu dan dinding di tempat ini, tahu!",
  ui_story_6_1_71_dialog_content = "Menarik sekali… Seorang nona manja dari Lumopolis, seorang gadis Illumina yang masih polos, dan seorang Caelestite…",
  ui_story_6_1_72_dialog_content = "Sepertinya kalian inilah \"Colossus Squad\" yang banyak dibicarakan orang akhir-akhir ini.",
  ui_story_6_1_73_dialog_content = "Lumopolis dan Illumina sudah sepakat untuk diam dan menonton saja, tapi Shadowlord memilihku secara khusus untuk membantu kalian.",
  ui_story_6_1_X73_dialog_content = "Sungguh menjengkelkan…",
  ui_story_6_1_74_dialog_content = "Sepertinya kami sangat beruntung!",
  ui_story_6_1_F10_dialog_content = "Namaku Sheol. Nah, apa yang bisa kubantu?",
  ui_story_6_1_75_option_content = [[
Apa kaulihat ada orang lain
yang lewat sini?]],
  ui_story_6_1_76_dialog_content = "Hanya sedikit orang datang kemari. Belum lama ini memang ada cukup banyak Eclipsite yang kemari, tapi tak ada barang di sini yang hilang.",
  ui_story_6_1_77_dialog_content = "Schummer…",
  ui_story_6_1_78_dialog_content = "Yang lebih kukhawatirkan justru musuh kalian… Mereka sudah di sini, 'kan?",
  ui_story_6_1_79_dialog_content = "Yah, aku malah lebih khawatir karena kau menguping kami sebelum akhirnya menampakkan batang hidungmu.",
  ui_story_6_1_80_dialog_content = "Teman-teman perempuanmu ini blak-blakan sekali, PlayerName!",
  ui_story_6_1_81_dialog_content = "Anu, Lady Sheol, tak apa kalau kau tak mau membicarakan ini, tapi bisakah setidaknya kauberi tahu kami tentang tempat ini?",
  ui_story_6_1_82_dialog_content = "Yah, semua orang pasti sudah tahu bahwa tempat ini dulunya adalah reruntuhan besar.",
  ui_story_6_1_83_dialog_content = "Karenanya, tempat ini tidak begitu berharga… Maka, Shadowlord memutuskan untuk membelinya. Dia satu-satunya orang yang tahu segala detail tentang tempat ini.",
  ui_story_6_1_84_dialog_content = "Walau di sini tak banyak penjaga, sebagian besar penyusup kacangan biasanya akan terkena jebakan atau tersesat.",
  ui_story_6_1_85_dialog_content = "Mencari benda yang kalian inginkan itu hampir mustahil… kalau tak ada pemandu yang layak.",
  ui_story_6_1_86_dialog_content = "Jadi, siapa pemandu kami?",
  ui_story_6_1_87_dialog_content = "Memangnya kaulihat ada orang lain lagi di sini?",
  ui_story_6_1_88_dialog_content = "Oh, rupanya kau orangnya! Kalau begitu, tolong tunjukkan jalannya.",
  ui_story_6_1_89_dialog_content = "Hah? Memangnya kapan aku setuju untuk jadi pemandu kalian?",
  ui_story_6_1_90_dialog_content = "Kau beruntung, PlayerName, gadis ini manis sekali…",
  ui_story_6_1_91_dialog_content = "Kurasa kau salah sangka, Lady Sheol.",
  ui_story_6_1_92_dialog_content = "Apa kau tahu apa yang kami cari? Pernah dengar tentang Flame Control Module?",
  ui_story_6_1_93_dialog_content = "Eh, aku tak tahu apa pun tentang benda itu.",
  ui_story_6_1_94_option_content = [[
Bisakah kauberi tahu kami
tentang tempat ini?]],
  ui_story_6_1_95_dialog_content = "Yah, semua orang pasti sudah tahu bahwa tempat ini dulunya adalah reruntuhan besar.",
  ui_story_6_1_96_dialog_content = "Karenanya, tempat ini tidak begitu berharga… Maka, Shadowlord memutuskan untuk membelinya. Dia satu-satunya orang yang tahu segala detail tentang tempat ini.",
  ui_story_6_1_97_dialog_content = "Walau di sini tak banyak penjaga, sebagian besar penyusup kacangan biasanya akan terkena jebakan atau tersesat.",
  ui_story_6_1_98_dialog_content = "Mencari benda yang kalian inginkan itu hampir mustahil… kalau tak ada pemandu yang layak.",
  ui_story_6_1_99_dialog_content = "Jadi, siapa pemandu kami?",
  ui_story_6_1_100_dialog_content = "Memangnya kaulihat ada orang lain lagi di sini?",
  ui_story_6_1_101_dialog_content = "Oh, rupanya kau orangnya! Kalau begitu, tolong tunjukkan jalannya.",
  ui_story_6_1_102_dialog_content = "Memangnya aku pernah bilang akulah pemandunya, Sayang?",
  ui_story_6_1_103_dialog_content = "PlayerName, teman-temanmu sangat sopan dan menarik.",
  ui_story_6_1_104_dialog_content = "Anu, Lady Sheol, tolong jangan mengalihkan pembicaraan. Kami sedang terburu-buru…",
  ui_story_6_1_105_dialog_content = "Masa? Oh, ya, mungkin musuh kalian sudah sampai sini.",
  ui_story_6_1_106_dialog_content = "Jejak Eclipsite tersebar di sini, dan mereka mengarah ke Whispering Corridor…",
  ui_story_6_1_107_dialog_content = "Situasi di sini memang agak suram.. Apa pun yang kalian cari, mungkin benda itu sudah dibawa pergi!",
  ui_story_6_1_108_dialog_content = "Jadi, apa kau tidak keberatan mengantar kami ke lokasi penyimpanan Flame Control Module?",
  ui_story_6_1_109_dialog_content = "Flame apa? Aku belum pernah mendengarnya.",
  ui_story_6_1_110_option_content = [[
Sebenarnya,
kami sedang mencari sesuatu.]],
  ui_story_6_1_111_dialog_content = "Aku tahu. Semua orang yang kemari selalu mencari sesuatu. Tapi kurasa beberapa Eclipsite mungkin sudah mendahului kalian.",
  ui_story_6_1_112_dialog_content = "Sudah kuduga, Eclipsite itu ada di sini… Kita harus bergegas!",
  ui_story_6_1_113_dialog_content = "Kenapa buru-buru, Sayang?",
  ui_story_6_1_114_dialog_content = "Yah, semua orang pasti sudah tahu bahwa tempat ini dulunya adalah reruntuhan besar.",
  ui_story_6_1_115_dialog_content = "Karenanya, tempat ini tidak begitu berharga… Maka, Shadowlord memutuskan untuk membelinya. Dia satu-satunya orang yang tahu segala detail tentang tempat ini.",
  ui_story_6_1_116_dialog_content = "Walau di sini tak banyak penjaga, sebagian besar penyusup kacangan biasanya akan terkena jebakan atau tersesat.",
  ui_story_6_1_117_dialog_content = "Mencari benda yang kalian inginkan itu hampir mustahil… kalau tak ada pemandu yang layak.",
  ui_story_6_1_118_dialog_content = "Jadi, siapa pemandu kami?",
  ui_story_6_1_119_dialog_content = "Memangnya kaulihat ada orang lain lagi di sini?",
  ui_story_6_1_120_dialog_content = "Oh, rupanya kau orangnya! Kalau begitu, tolong tunjukkan jalannya.",
  ui_story_6_1_121_dialog_content = "Memangnya aku pernah bilang aku akan jadi pemandu kalian?",
  ui_story_6_1_122_dialog_content = "Kau beruntung, PlayerName. Gadis ini manis sekali.",
  ui_story_6_1_123_dialog_content = "Tolong jangan melantur, Lady Sheol.",
  ui_story_6_1_124_dialog_content = "Lady Sheol, apa kau tahu benda yang kami cari? Pernah dengar tentang Flame Control Module?",
  ui_story_6_1_125_dialog_content = "Eh, aku tak tahu apa pun tentang benda itu.",
  ui_story_6_1_126_dialog_content = "<size=30>Dia bohong.</size>",
  ui_story_6_1_127_dialog_content = "<size=30>Aku tahu.</size>",
  ui_story_6_1_128_dialog_content = "Lady Sheol, kami tak bermaksud masuk tanpa izinmu. Surat ini adalah bukti niat baik kami.",
  ui_story_6_1_129_dialog_content = "Aku tahu. Jadi, kalian ingin menghentikan Schummer?",
  ui_story_6_1_130_dialog_content = "Ya. Aku yakin kau sudah dengar tentang apa yang terjadi di Lumopolis.",
  ui_story_6_1_131_dialog_content = "Schummer akan melakukan apapun untuk mendapatkan <color=#FFB400>Flame Control Module</color>.",
  ui_story_6_1_132_dialog_content = "Saat kami tahu bahwa dia berniat kemari, kami langsung memberi tahu Shadowlord. Kami khawatir sejumlah besar Eclipsite akan menyerang tempat ini…",
  ui_story_6_1_F11_dialog_content = "Umbraton bisa jadi sedang dalam bahaya. Sulit untuk tak memercayaimu karena kata-katamu sangat tulus.",
  ui_story_6_1_F12_dialog_content = "Tapi, dari mana kau tau bahwa dia menuju kemari?",
  ui_story_6_1_F13_dialog_content = "Aku bicara sejujur-jujurnya… Aku bisa menggunakan kemampuan Caelestite milikku untuk merasakan keberadaannya.",
  ui_story_6_1_134_dialog_content = "Kurasa reputasi hebat kaum Caelestite memang benar adanya. Baiklah, sebagai hadiah atas kejujuranmu, aku akan menjadi pemandu kalian.",
  ui_story_6_1_135_dialog_content = "Terima kasih, kami mengandalkanmu.",
  ui_story_6_1_136_dialog_content = "Manis sekali!",
  ui_story_6_1_137_dialog_content = "Apa kita sudah sampai? Berapa tingkat lagi?",
  ui_story_6_1_138_dialog_content = "Sama sekali belum dekat… Kita baru sampai area pinggiran, perjalanan kita masih jauh.",
  ui_story_6_1_139_dialog_content = "Ya ampun, tempat ini lebih membingungkan daripada Gannon City.",
  ui_story_6_1_140_dialog_content = "Kenapa Flame Control Module disimpan di sini?",
  ui_story_6_1_141_dialog_content = "Kata orang, Shadowlord menemukannya di medan tempur tua dalam perang melawan Eclipsite sepuluh tahun lalu.",
  ui_story_6_1_142_dialog_content = "Aku sendiri baru pernah melihatnya sekali saja. Bentuknya seperti relik kuno berdebu.",
  ui_story_6_1_143_dialog_content = "Kalau bukan karena kalian, barangkali benda itu akan tetap tersembunyi di sini selamanya.",
  ui_story_6_1_144_dialog_content = "Berhenti. Ada yang janggal di sini…",
  ui_story_6_1_145_dialog_content = "Sepertinya ada yang merusak pintu ini.",
  ui_story_6_1_146_dialog_content = "Dari kerusakannya, kurasa pelakunya bukan Aurorian.",
  ui_story_6_1_147_dialog_content = "Tapi aku tak mau bertarung!",
  ui_story_6_1_148_dialog_content = "PlayerName, apa kau merasakan sesuatu?",
  ui_story_6_1_149_dialog_content = "Schummer ada di sini.",
  ui_story_6_1_150_dialog_content = "Ternyata dia memang sudah lebih dulu daripada kita. Berapa jauh jarak kita darinya?",
  ui_story_6_1_151_dialog_content = "Tidak jauh tapi juga tidak dekat… Ada kemungkinan kita akan bertemu dengan Eclipsite. Semuanya, hati-hati.",
  ui_story_6_1_152_dialog_content = "…",
  ui_story_6_1_153_dialog_content = "Kita masih bisa menyusulnya! Mungkin saja dia tersesat karena tak punya pemandu, sedangkan kita punya…",
  ui_story_6_1_154_dialog_content = "Eh, pemandu, kau mau ke mana? Apa kita berbalik arah?",
  ui_story_6_1_155_dialog_content = "Apa kau mau mundur, Lady Sheol?",
  ui_story_6_1_156_dialog_content = "Yah, ini memang berbahaya. Lady Sheol, kami tak akan memaksamu…",
  ui_story_6_1_157_dialog_content = "Rencana ini memang berbahaya, tapi orang yang gentar dalam pertempuran hanya akan menimbulkan celaka bagi teman-temannya.",
  ui_story_6_1_158_dialog_content = "Memangnya aku bilang mau kabur? 'Kan sudah kubilang aku akan memandu kalian!",
  ui_story_6_1_159_dialog_content = "Tapi aku tidak lihai bertarung, jadi aku tak bisa ikut bertarung bersama kalian…",
  ui_story_6_1_160_dialog_content = "Tapi, bagaimana kau bisa memandu kami kalau kau tak ikut dengan kami? Dari jarak jauh?",
  ui_story_6_1_161_dialog_content = "Seperti saran nona Vice yang manis ini, aku akan menunggu dan berkomunikasi dengan kalian dari sini!",
  ui_story_6_1_162_dialog_content = "Asalkan kau bisa memberitahuku apa yang kalian lihat di sekeliling, aku bisa tahu lokasi persis kalian.",
  ui_story_6_1_163_dialog_content = "Sudah kuduga… Memang beginilah kebiasaan di Umbraton, Vice.",
  ui_story_6_1_164_dialog_content = "Tapi, maksudku bukan berarti dia memandu kita dari jauh. Lady Sheol, kurasa akan lebih baik kalau kita pergi bersama-sama.",
  ui_story_6_1_165_dialog_content = "Oh? Yah, masuk akal juga, sih! Kalau begitu, aku akan tunggu di luar saja! Aku akan memandu kalian dari jauh dan terus berkomunikasi dengan kalian!",
  ui_story_6_1_168_dialog_content = "Selain itu, kalau kau berhasil keluar dari sini hidup-hidup, PlayerName…",
  ui_story_6_1_169_dialog_content = "Jangan lupa bertandang ke tokoku, ya! Kau sudah kuanggap temanku, jadi akan kuberikan penawaran spesial untukmu!",
  ui_story_6_1_170_dialog_content = "Semoga berhasil!",
  ui_story_6_1_171_dialog_content = "Rupanya Lady Sheol seorang pebisnis wanita yang sukses…",
  ui_story_6_1_172_dialog_content = "Apa kata-kataku tadi salah? Apa gara-gara \"memandu dari jauh\" itu?",
  ui_story_6_1_173_dialog_content = "Jangan khawatir, Vice. Memang sebaiknya dia pergi saja sekarang daripada nanti justru akan membuat perjalanan kita lambat.",
  ui_story_6_1_174_dialog_content = "Aku iri melihatmu selalu tenang seperti air mengalir, Carleen…",
  ui_story_6_1_175_dialog_content = "Tak ada gunanya kita panik. Apa pun yang ada di depan sana, akan kubuat dia sadar bahwa datang kemari adalah kesalahan besar.",
  ui_story_6_2_X29_dialog_content = "Eh? Hmm…",
  ui_story_6_2_X30_dialog_content = "Officer Charon? Sedang apa kau di sini, ribut tak jelas begini?",
  ui_story_6_2_X31_dialog_content = "Philyshy, kau masih tampak sangat…",
  ui_story_6_2_X32_dialog_content = "Kurang tidur.",
  ui_story_6_2_X33_dialog_content = "Sebenarnya aku sedang menunggu para Officer selesai rapat. Ada poin-poin pengeluaran yang ingin kulaporkan untuk penggantian dana bagi Undercity 28…",
  ui_story_6_2_X34_dialog_content = "Mereka sudah pergi, meong! Lain kali saja.",
  ui_story_6_2_X35_dialog_content = "Kok mereka pergi secepat itu? Sisa subsidinya 'kan masih cukup banyak untuk mengganti pengeluaran itu!",
  ui_story_6_2_X36_dialog_content = "Sekarang mereka tak bisa berbuat apa-apa, meong. Mereka semua menerima perintah mendesak untuk menjaga area pinggiran kota, meong.",
  ui_story_6_2_X37_dialog_content = "Vice pasti sudah memberi tahu mereka bahwa ancamannya ada di <color=#FFB400>Whispering Corridor</color>…",
  ui_story_6_2_X38_dialog_content = "Grand Marshal sudah mengambil keputusan, tapi aku tak paham alasannya, meong…",
  ui_story_6_2_X39_dialog_content = "Pelan-pelan, informasinya terlalu banyak untuk dicerna sekaligus.",
  ui_story_6_2_X40_dialog_content = "Bisa kauberi tahu aku lebih banyak tentang detailnya? Apa Vice dan PlayerName terlibat masalah lagi?",
  ui_story_6_2_X41_dialog_content = "Masalah? Bagaimana bilangnya, ya, meong… Bisa jadi ini <color=#FFB400>krisis terbesar dalam sejarah</color>, meong…",
  ui_story_6_2_X42_dialog_content = "Krisis!?",
  ui_story_6_2_1_dialog_content = "Sepertinya kita sudah berjalan sangat jauh.",
  ui_story_6_2_2_dialog_content = "Bahkan aku pun bisa merasakan hawa Eclipsite di sini.",
  ui_story_6_2_3_dialog_content = "Lady Sheol?",
  ui_story_6_2_4_dialog_content = "Hah? Aku di sini.",
  ui_story_6_2_6_dialog_content = "Apa kalian tersesat, Sayang?",
  ui_story_6_2_7_dialog_content = "Bukannya tersesat, tapi tempat ini seperti labirin, dan sangat suram dan membuat perasaan jadi tertekan.",
  ui_story_6_2_9_dialog_content = "Lihat di sana… Jejaknya janggal sekali. Bukan hanya jejak kaki Eclipsite, tapi juga…",
  ui_story_6_2_10_dialog_content = "Bukankah ini jejak kaki orang yang mengenakan sepatu bot tempur?",
  ui_story_6_2_11_dialog_content = "Sepatu bot tempur?",
  ui_story_6_2_12_dialog_content = "Aku merasakan ada Aurorian. Mungkinkah itu bala bantuan?",
  ui_story_6_2_13_dialog_content = "Ini jelas sepatu bot tempur standar dari Lumopolis. Ini jejak kaki seseorang dari Guardian.",
  ui_story_6_2_14_dialog_content = "Jejaknya masih jelas, tak ada tanda-tanda pertarungan, bahkan tak ada tanda-tanda panik.",
  ui_story_6_2_15_dialog_content = "Kau bisa tahu semua itu hanya dengan melihat jejak sepatu?",
  ui_story_6_2_16_dialog_content = "<color=#FFB400>Gertzurde</color>.",
  ui_story_6_2_X16_dialog_content = "Gertzurde? Kalau aku tak salah ingat…",
  ui_story_6_2_17_option_content = [[
Aku pernah dengar nama itu
saat kita sedang memburu Shelt.]],
  ui_story_6_2_18_option_content = [[
Maling yang mencuri
Think Tank Module itu?]],
  ui_story_6_2_19_dialog_content = "Benar, tapi bukannya Gertzurde hilang begitu saja?",
  ui_story_6_2_20_dialog_content = "Dia berkhianat. Kami punya bukti tak terbantahkan bahwa dia bergabung dengan Eclipse.",
  ui_story_6_2_21_dialog_content = "Dia dan pacarnya sudah lama mengabdi pada Eclipsite. Mereka adalah noda bagi Lumopolis.",
  ui_story_6_2_22_dialog_content = "Dia lewat sini bersama para Eclipsite, dengan mengenakan sepatu bot tempur…",
  ui_story_6_2_23_dialog_content = "Pasti itu Gertzurde!",
  ui_story_6_2_24_dialog_content = "Kenapa dia berbuat begitu?",
  ui_story_6_2_25_dialog_content = "Tak seorang pun tahu.",
  ui_story_6_2_26_dialog_content = "Kata orang, Gertzurde sangat tekun bekerja, dan dia bahkan seorang pahlawan perang, jadi tak seorang pun curiga padanya.",
  ui_story_6_2_27_dialog_content = "Jangan-jangan Gertzurde menyimpan dendam atas apa yang menimpa Shelt, lalu dia kemari untuk…",
  ui_story_6_2_28_dialog_content = "Biarkan anjing liar itu kemari.",
  ui_story_6_2_29_dialog_content = "Kalau sampai kulihat dia, akan kukubur dia di sini, persis di samping Schummer!",
  ui_story_6_2_30_dialog_content = "Ya ampun, menjengkelkan sekali. Jalannya panjang sekali, dan aku terus-menerus merasa seakan-akan sedang diawasi!",
  ui_story_6_2_31_dialog_content = "Menyebalkan! Nyanyikan lagu untukku, Gertzurde.",
  ui_story_6_2_32_dialog_content = "…",
  ui_story_6_2_33_dialog_content = "Kenapa tampangmu begitu, Gertzurde?",
  ui_story_6_2_34_dialog_content = "Orang-orang yang membunuh Shelt ada di sini. Bukannya kau harusnya bernyanyi gembira?",
  ui_story_6_2_35_dialog_content = "Mereka mengejar kita, persis seperti yang kaubilang…",
  ui_story_6_2_36_dialog_content = "Para pembunuh Shelt itu makin mendekat, 'kan?",
  ui_story_6_2_37_dialog_content = "Benar. Sudah kuduga, makhluk-makhluk rendahan itu tak akan mampu menghentikan mereka… Mereka benar-benar gigih.",
  ui_story_6_2_39_dialog_content = "Apakah Shelt…",
  ui_story_6_2_40_dialog_content = "Dia mati mengenaskan, Gertzurde. Bahkan aku sendiri pun bergidik membayangkan betapa mengenaskannya keadaanya.",
  ui_story_6_2_41_dialog_content = "Kenapa! Mereka…",
  ui_story_6_2_42_dialog_content = "Shelt bilang padaku, ini misi menuju kejayaan! Kenapa dia tak minta bantuan darimu dan orang ITU?",
  ui_story_6_2_A1_dialog_content = "Aku mengenalnya. Dia pasti sudah minta bantuan… Apa itu artinya…",
  ui_story_6_2_43_dialog_content = "Kenapa kau teriak-teriak?",
  ui_story_6_2_44_dialog_content = "Maaf.",
  ui_story_6_2_45_dialog_content = "Kudengar, si PlayerName itulah yang berperan besar membuat Shelt yang malang itu tewas.",
  ui_story_6_2_46_dialog_content = "Lower Lumopolis jadi kacau setelah kau melepaskan Shelt, dan Uptown tak berminat melakukan apa pun untuk menanganinya.",
  ui_story_6_2_47_dialog_content = "Tapi, PlayerName dan kedua anjing ganas itu terus saja menghajarnya.",
  ui_story_6_2_48_dialog_content = "Apa? Apa mereka tak punya belas kasihan?",
  ui_story_6_2_49_dialog_content = "Aku tahu. Hukum macam apa yang tetap menghukum maling yang gagal mencuri?",
  ui_story_6_2_50_dialog_content = "Mereka memaksa Shelt dan adiknya untuk… eh… melebur menjadi monster menjijikkan.",
  ui_story_6_2_51_dialog_content = "Shelt, oh, Shelt…",
  ui_story_6_2_52_dialog_content = "Kalau ada hal tertentu yang ingin kaulakukan, sekaranglah kesempatanmu.",
  ui_story_6_2_53_dialog_content = "Flame Control Module yang kucari ada di depan sana. Jadi, apa rencanamu berikutnya?",
  ui_story_6_2_54_dialog_content = "PlayerName!",
  ui_story_6_2_55_dialog_content = "Oh? Sepertinya kau sudah siap balas dendam.",
  ui_story_6_2_56_dialog_content = "Hatsyiii!",
  ui_story_6_2_57_dialog_content = "Kau kedinginan, PlayerName?",
  ui_story_6_2_58_dialog_content = "Tidak, hanya tiba-tiba saja aku merinding.",
  ui_story_6_2_59_dialog_content = "Kau ini 'kan Caelestite, PlayerName. Mungkin Darkflow di sini terlalu kuat untukmu.",
  ui_story_6_2_60_dialog_content = "Tapi, bertahanlah. Masih ada banyak musuh yang harus kita berantas.",
  ui_story_6_2_61_dialog_content = "Ya. Ayo maju terus.",
  ui_story_6_6_1_dialog_content = "Lady Sheol, sepertinya kami sampai di suatu lokasi aneh!",
  ui_story_6_6_2_dialog_content = "Nyam, nyam… Apa itu?",
  ui_story_6_6_3_dialog_content = "Kau sedang makan, Lady Sheol?",
  ui_story_6_6_4_dialog_content = "Aku sedang menikmati waktu minum teh. Ada apa?",
  ui_story_6_6_5_dialog_content = "Kami ingin tahu apakah jalan ini akan mengarah ke lokasi <color=#FFB400>Flame Control Module</color>.",
  ui_story_6_6_6_dialog_content = "Apa? Tentu saja! Aku harus berusaha keras mengingat lokasi penyimpanan benda itu.",
  ui_story_6_6_7_dialog_content = "Kalian harus belajar memercayai orang lain, Sayang. Oh, omong-omong, waspadai jebakan di depan kalian, ya!",
  ui_story_6_6_8_dialog_content = "Tunggu, aku merasakan…",
  ui_story_6_6_9_dialog_content = "Eclipsite?",
  ui_story_6_6_10_dialog_content = "Bukan, seorang Aurorian…",
  ui_story_6_6_11_dialog_content = "Aurorian? Lady Sheol, tadi tak ada orang yang masuk kemari, 'kan?",
  ui_story_6_6_12_dialog_content = "Tak ada, bahkan tak seekor lalat pun masuk.",
  ui_story_6_6_13_dialog_content = "Pasti itu Gertzurde. Aku khawatir kita akan disergap.",
  ui_story_6_6_14_dialog_content = "Disergap?",
  ui_story_6_6_15_dialog_content = "Di depan sana kulihat ada persimpangan dan sebuah jebakan.",
  ui_story_6_6_16_dialog_content = "Lihat, langit-langit di sini sudah sangat reyot dan bisa sewaktu-waktu runtuh begitu saja… Tempat ini sempurna untuk melancarkan sergapan!",
  ui_story_6_6_17_dialog_content = "Walau dulu dia memang seorang kesatria, sekarang dia berkhianat dan memihak Eclipse. Tak ada yang tahu seperti apa kemampuannya sekarang.",
  ui_story_6_6_18_dialog_content = "Biar aku duluan. Akan kuhabisi Gertzurde sebagaimana mestinya.",
  ui_story_6_7_1_dialog_content = "Fyuh, nyaris saja! Kalau bukan karena Carleen, kita pasti sudah jatuh ke lubang!",
  ui_story_6_7_2_dialog_content = "Hoi, bukannya tadi aku sudah banyak memperingatkan kalian?",
  ui_story_6_7_3_dialog_content = "Misalnya, jebakan drum oli yang nyaris meremukkan kepala PlayerName tersayang itu!",
  ui_story_6_7_4_dialog_content = "Aku nyaris mati ketakutan…",
  ui_story_6_7_5_dialog_content = "Rupanya itu strategi Gertzurde sekarang. Dia jadi tak tahu malu dan hina, sama seperti Eclipsite…",
  ui_story_6_7_6_dialog_content = "Panjang umur…",
  ui_story_6_7_7_dialog_content = "Kau membunuh Shelt.",
  ui_story_6_7_8_dialog_content = "Kau… membunuh… Shelt!",
  ui_story_6_7_9_dialog_content = "Persis seperti dugaanku, kau kemari untuk balas dendam.",
  ui_story_6_7_10_dialog_content = "Balas dendam? Ya. Sayang sekali kalian lolos dari jebakanku, karena…",
  ui_story_6_7_11_dialog_content = "Kebencianku tak akan berkurang hanya dengan membunuh kalian saja.",
  ui_story_6_7_F1_dialog_content = "Dasar pengkhianat, kau mau bunuh kami?",
  ui_story_6_7_12_dialog_content = "Gertzurde, sebagai kesatria Lumopolis, kau sudah kehilangan kehormatanmu dan membelot ke pihak Eclipsite. Aku tak akan pernah mengampunimu!",
  ui_story_6_7_13_dialog_content = "Kau tak akan pernah mengampuniku? Memangnya aku butuh ampun darimu? Ya, dulu aku memang kesatria Lumopolis, tapi kini aku bagian dari kelas elite Eclipsite!",
  ui_story_6_7_14_dialog_content = "Semua ini demi dia! Tapi, kau, kau…",
  ui_story_6_7_15_dialog_content = "Kau jauh lebih kejam daripada Eclipsite… Kau menyiksa dan membunuh Shelt!",
  ui_story_6_7_16_dialog_content = "Shelt dan adiknya, mereka sendiri yang memilih mati, Gertzurde!",
  ui_story_6_7_17_dialog_content = "Gertzurde, mereka memilih mati agar mereka terbebas.",
  ui_story_6_7_18_dialog_content = "Tak mungkin!",
  ui_story_6_7_19_dialog_content = "Shelt… Dia sangat mendambakan kebebasan. Mana mungkin dia bunuh diri kalau bukan karena kaupaksa?",
  ui_story_6_7_20_dialog_content = "Schummer mengutusmu untuk menghentikan kami, ya?",
  ui_story_6_7_21_dialog_content = "Tidak, aku kemari untuk balas dendam kepadamu, kepada Lumopolis!",
  ui_story_6_7_22_dialog_content = "Benda yang diincar Schummer tak ada hubungannya denganku.",
  ui_story_6_7_23_dialog_content = "Seorang pengkhianat mau balas dendam untuk setitik tahi lalat?",
  ui_story_6_7_27_dialog_content = "…",
  ui_story_6_7_28_dialog_content = "Hati-hati, Carleen, kebenciannya sepertinya makin membesar…",
  ui_story_6_7_29_dialog_content = "Kebencian? Memang itu sifat alami pengkhianat.",
  ui_story_6_7_30_dialog_content = "Karena mereka putus asa, karena yang mereka tahu hanyalah kebencian.",
  ui_story_6_7_31_dialog_content = "Mereka benci orang-orang yang menghakimi mereka, mereka benci masa lalu yang tak mampu mereka tanggung, dan mereka benci masa depan yang tak akan pernah mereka rasakan.",
  ui_story_6_7_32_dialog_content = "Tak ada gunanya berunding dengan sampah macam dia.",
  ui_story_6_7_33_dialog_content = "Kau Kapten di Guardian dan putri City Lord Lumopolis. Mana mungkin kau bisa paham?",
  ui_story_6_7_34_dialog_content = "Kalaupun aku bukan pengkhianat, tetap saja kau tak akan paham kebencianku!",
  ui_story_6_7_35_dialog_content = "Aku benci kamu karena kau membunuh Shelt!",
  ui_story_6_7_36_dialog_content = "Ya, dia berubah menjadi Eclipsite, dan memang sudah nasibnya untuk bertarung mati-matian melawanmu karena dia musuh kaum Aurorian.",
  ui_story_6_7_37_dialog_content = "Tapi kaulah yang membuatnya jadi begitu! Ini salahmu!",
  ui_story_6_7_38_dialog_content = "Dia berubah wujud!",
  ui_story_6_7_39_dialog_content = "Balas dendam… Dendamku sama sepertimu, PlayerName.",
  ui_story_6_7_40_dialog_content = "Kita ini sama saja, sama-sama menempuh jalan untuk balas dendam, dan kita tak bisa berbalik arah…",
  ui_story_6_7_41_dialog_content = "Sama saja? Apa maksudmu?",
  ui_story_6_7_42_dialog_content = "Kau benar-benar menjadi Eclipsite! Apa kau menerima kekuatan ini dari Master-mu?",
  ui_story_6_7_43_dialog_content = "Balas dendam! Kita saling bunuh dan mati sama-sama, PlayerName!",
  ui_story_6_7_44_dialog_content = "Ayo bersama-sama menuju dunia akhirat dan memohon ampun dari Shelt!",
  ui_story_6_7_45_dialog_content = "Mundur, PlayerName! Tanpamu, kita tak akan punya peluang!",
  ui_story_6_7_X45_dialog_content = "Aku kalah, Shelt…",
  ui_story_6_7_48_dialog_content = "Siap menerima hukumanmu, pengkhianat?",
  ui_story_6_7_49_dialog_content = "…",
  ui_story_6_7_50_dialog_content = "Diam saja? Saat menghadapi kematian, apa akhirnya kau menyesal?",
  ui_story_6_7_51_dialog_content = "Tidak, aku tak menyesal. Aku tahu seperti apa akhir yang harus kuterima.",
  ui_story_6_7_52_dialog_content = "Aku hanya ingin tahu apa yang terjadi pada Shelt pada saat-saat terakhirnya.",
  ui_story_6_7_53_dialog_content = "Kau tak perlu tahu!",
  ui_story_6_7_F2_dialog_content = "Sebentar! Bisa kami jelaskan…",
  ui_story_6_7_54_dialog_content = "Kami berhasil mengejar Shelt, tapi kami hanya berniat mencari tahu apa yang akan mereka lakukan.",
  ui_story_6_7_55_dialog_content = "Benar. Kami sama sekali tak berniat membunuh mereka.",
  ui_story_6_7_56_dialog_content = "Tapi, karena ingin meloloskan diri, mereka minta bantuan dari seorang pemimpin Eclipsite.",
  ui_story_6_7_57_dialog_content = "Schummer?",
  ui_story_6_7_58_dialog_content = "Bukan, auranya berbeda dari Schummer. Auranya berasal dari orang lain, dan dia jauh lebih kuat daripada Schummer.",
  ui_story_6_7_59_dialog_content = "Lalu, mereka mulai berubah menjadi makhluk mengerikan… Tubuh mereka melebur menjadi satu seperti lilin meleleh…",
  ui_story_6_7_60_dialog_content = "Sepertinya mereka tidak memilih untuk melebur menjadi satu. Sepertinya justru…",
  ui_story_6_7_61_dialog_content = "Sepertinya ada kekuatan besar yang memaksa mereka melebur menjadi satu…",
  ui_story_6_7_62_dialog_content = "Lalu, apa yang terjadi!?",
  ui_story_6_7_63_dialog_content = "Kami terpaksa membunuh Shelt.",
  ui_story_6_7_64_dialog_content = "Apa dia mati kesakitan?",
  ui_story_6_7_65_dialog_content = "Yah…",
  ui_story_6_7_66_option_content = "Dia mati penuh kesakitan.",
  ui_story_6_7_67_dialog_content = "<anim type=Shake><size=45>Kesakitan!</size></anim>",
  ui_story_6_7_69_dialog_content = "Sebelum kami memutuskan untuk melawannya, ada seseorang yang memberikan kekuatan tak dikenal kepada mereka…",
  ui_story_6_7_70_dialog_content = "Kekuatan itu memaksa mereka untuk melebur menjadi satu, dan mereka berdua berubah menjadi satu Eclipsite. Itulah yang menyebabkan mereka kesakitan.",
  ui_story_6_7_71_option_content = "Kami hanya mempercepatnya.",
  ui_story_6_7_72_dialog_content = "Jadi, kalian membebaskan dia?",
  ui_story_6_7_73_dialog_content = "Ya. Karena kami tak tega melihat dia menderita.",
  ui_story_6_7_74_dialog_content = "Sebelum kami memutuskan untuk melawannya, ada seseorang yang memberikan kekuatan tak dikenal kepada mereka…",
  ui_story_6_7_75_dialog_content = "Kekuatan itu memaksa mereka untuk melebur menjadi satu, dan mereka berdua berubah menjadi satu Eclipsite. Itulah yang menyebabkan mereka kesakitan.",
  ui_story_6_7_76_dialog_content = "Mungkin rasa sakit itu juga berasal dari penyesalan mereka sendiri.",
  ui_story_6_7_78_dialog_content = "Terutama Shelt. Aku bisa merasakan bahwa sebenarnya dia tak mau bertarung melawan kami.",
  ui_story_6_7_79_dialog_content = "Dia hanya ingin melarikan diri, meninggalkan Lumopolis dan pergi jauh…",
  ui_story_6_7_80_dialog_content = "Sebelum mati, dia sempat menyebutkan sesuatu. Nama bunga.",
  ui_story_6_7_81_dialog_content = "Bunga?",
  ui_story_6_7_82_option_content = "Dandelion.",
  ui_story_6_7_83_dialog_content = "<size=45>…!</size>",
  ui_story_6_7_84_dialog_content = "Kami tak paham apa maksudnya, tapi kau… kau pasti paham.",
  ui_story_6_7_85_dialog_content = "Maafkan aku, Shelt, maafkan aku…",
  ui_story_6_7_86_dialog_content = "Dulu kau sudah pernah memberitahuku, harusnya aku sadar. Dulu kita sebenarnya punya kesempatan…",
  ui_story_6_7_87_dialog_content = "Gertzurde, Gertzurde! Apa ada hal seru yang bisa kita lakukan di dekat sini?",
  ui_story_6_7_88_dialog_content = "Kau mau pergi ke suatu tempat?",
  ui_story_6_7_89_dialog_content = "Ya, tapi bukan hanya untuk senang-senang. Kau tahu Whispering Corridor?",
  ui_story_6_7_90_dialog_content = "Sepertinya tempat itu sangat terpencil, tak akan ada yang bisa menemukan kita di sana. Kita bisa hidup bersama di sana selamanya!",
  ui_story_6_7_91_dialog_content = "Atau, bisa juga kita ke Rediesel Desert sih. Tapi, cuaca di sana terlalu panas.",
  ui_story_6_7_92_dialog_content = "Kau berniat pergi dari Lumopolis? Apa ini karena tindakanmu menyinggung para bangsawan?",
  ui_story_6_7_93_dialog_content = "Bukan, ini karena Eclipse.",
  ui_story_6_7_94_dialog_content = "Aku ingin menjadi dandelion.",
  ui_story_6_7_95_dialog_content = "Hah? Kenapa begitu?",
  ui_story_6_7_96_dialog_content = "Karena tak seorang pun bisa mengekang dandelion. Dandelion menyebar menjadi ribuan bagian kecil dan menghilang bersama angin.",
  ui_story_6_7_97_dialog_content = "Dandelion bisa terbang ke mana pun.",
  ui_story_6_7_98_dialog_content = "\"Bagian kecil\" itu sebenarnya bijinya. Lagi pula, bagaimana jadinya kalau malah jatuh ke air?",
  ui_story_6_7_99_dialog_content = "Cih… Sudahlah, aku tak mau membicarakannya lagi!",
  ui_story_6_7_100_dialog_content = "Kebebasan… Ya, Shelt sering bilang ingin pergi dari Lumopolis karena Eclipse.",
  ui_story_6_7_101_dialog_content = "Dia bilang ingin pergi bersamaku, bebas seperti dandelion.",
  ui_story_6_7_102_dialog_content = "Kau bodoh, Gertzurde. Eclipse adalah akhir bagi segalanya. Bukan, Eclipse adalah Truth…",
  ui_story_6_7_103_dialog_content = "Benarkah PlayerName yang membunuh Shelt?",
  ui_story_6_7_104_dialog_content = "Kan sudah kujelaskan apa yang terjadi, tapi kau tetap saja ngotot bertanya macam-macam. Mungkin aku terlalu berharap banyak darimu.",
  ui_story_6_7_105_dialog_content = "Singkirkan kelemahanmu dan jangan lagi meragukan kami, Gertzurde.",
  ui_story_6_7_106_dialog_content = "Ingat, mereka sebenarnya masih bisa hidup, tapi PlayerName mengubah nasib mereka.",
  ui_story_6_7_107_dialog_content = "Dan mengubah nasibmu juga…",
  ui_story_6_7_108_dialog_content = "Tidak, tidak! Ini tidak benar, tidak benar!",
  ui_story_6_7_109_dialog_content = "Gertzurde!",
  ui_story_6_7_110_dialog_content = "Aku… aku… Shelt… Shelt ingin pergi… Kenapa dia malah memilih melebur? Kenapa!?",
  ui_story_6_7_111_dialog_content = "Kami tak punya kemampuan untuk memanipulasi Darkflow. Hanya Darkflow-lah yang mampu membuat kakak beradik itu melebur menjadi Eclipsite.",
  ui_story_6_7_112_dialog_content = "Kalaupun bukan Schummer yang memberi mereka Darkflow, para Eclipsite yang melakukannya tetap saja diperintah olehnya.",
  ui_story_6_7_113_dialog_content = "Pasti, pasti, pasti bajingan itu…!",
  ui_story_6_7_114_dialog_content = "Katakan kepada kami apa yang kauketahui, Gertzurde.",
  ui_story_6_7_116_dialog_content = "…",
  ui_story_6_7_119_dialog_content = "<color=#FFB400>Schummer</color>, aku tahu dia ada di mana.",
  ui_story_6_8_1_dialog_content = "Apa dia benar akan membawa kita ke lokasi Schummer, Carleen?",
  ui_story_6_8_2_dialog_content = "Aneh, dari tadi kita belum bertemu satu Eclipsite pun. Jangan-jangan ini jebakan?",
  ui_story_6_8_F1_dialog_content = "Kalau memang jebakan, memangnya kenapa?",
  ui_story_6_8_3_dialog_content = "Kalau sampai dia mengkhianatiku lagi, akan kuhajar lagi dia, tapi kali ini aku tak akan beri ampun.",
  ui_story_6_8_F2_dialog_content = "…",
  ui_story_6_8_4_dialog_content = "Maafkan aku, Gertzurde. Kami masih ragu kepadamu, tapi kalau ada yang ingin kaujelaskan, katakan saja.",
  ui_story_6_8_5_dialog_content = "Memangnya apa lagi yang perlu dijelaskan seorang pengkhianat?",
  ui_story_6_8_6_dialog_content = "Pengkhianat, ya… Dulu aku ini jawara di Lumopolis.",
  ui_story_6_8_7_dialog_content = "City Lord sendirilah yang mengangkatku menjadi kesatria saat usiaku delapan belas tahun.",
  ui_story_6_8_8_dialog_content = "Kalian tahu <color=#FFB400>Darkover Crisis</color>?",
  ui_story_6_8_9_dialog_content = "Itu perang yang bermula 17 tahun lalu dan berlangsung lama sekali…",
  ui_story_6_8_10_dialog_content = "Tujuh belas tahun lalu, Eclipsite menyerbu Eraveil, negeri kaum Caelestite. Serangan itu sama sekali tak diduga, bahkan Lumopolis pun tak menyangkanya.",
  ui_story_6_8_11_dialog_content = "Tak lama sesudahnya, kami menerima perintah untuk memperketat latihan dan mengantisipasi kemungkinan serangan Eclipsite skala besar.",
  ui_story_6_8_12_dialog_content = "Saat menerima perintah itu, aku masih lebih muda dari kalian sekarang, dan waktu itu aku baru saja menjadi pengawal.",
  ui_story_6_8_13_dialog_content = "Aku berlatih keras dan selama empat tahun berikutnya aku menjadi pasukan cadangan di Lumopolis Guardians.",
  ui_story_6_8_14_dialog_content = "Lalu, kau mendapatkan kesempatan.",
  ui_story_6_8_15_dialog_content = "Ya. Pagi itu cerah. Lumopolis mengerahkan pasukan untuk melawan Eclipsite yang menyerang Umbraton karena pasukan pertahanan di kota itu kurang.",
  ui_story_6_8_16_dialog_content = "Beberapa Eclipsite berhasil masuk ke Lower Lumopolis. Tanpa disuruh, aku menanggapi tantangan itu dan berinisiatif menyelamatkan seorang gadis bangsawan yang butuh bantuan.",
  ui_story_6_8_19_dialog_content = "Lalu, karena keberanianku itu, aku ditugaskan bertarung sebagai anggota Guardians…",
  ui_story_6_8_20_dialog_content = "Setelah aku kembali, City Lord sendiri mengangkatku menjadi kesatria.",
  ui_story_6_8_22_dialog_content = "Kedengarannya itu permulaan yang hebat.",
  ui_story_6_8_23_dialog_content = "Ya, lengkap dengan akhir cerita seperti dalam dongeng. Si kesatria menikahi sang putri.",
  ui_story_6_8_27_dialog_content = "Sebulan kemudian, aku menikahi gadis bangsawan itu.",
  ui_story_6_8_28_dialog_content = "Gadis itu Shelt, 'kan?",
  ui_story_6_8_29_dialog_content = "Bukan.",
  ui_story_6_8_30_dialog_content = "Maksudmu…",
  ui_story_6_8_31_dialog_content = "Dia anak kedua dari sebuah keluarga bangsawan besar.",
  ui_story_6_8_32_dialog_content = "Sekeras apa pun usahaku, perbedaan status di antara kami tak bisa dihilangkan.",
  ui_story_6_8_33_dialog_content = "Keluarga istriku adalah kekuatan sekaligus kelemahannya.",
  ui_story_6_8_34_dialog_content = "Hubungan kami berubah, dari penuh romantisme menjadi dingin, lalu dia mulai menjauh, membanding-bandingkan, merasa kecewa, mengeluh, bertengkar, dan akhirnya dia bersikap masa bodoh.",
  ui_story_6_8_35_dialog_content = "Dalam beberapa tahun saja, aku jadi dianggap tak lebih dari kerikil di hadapannya.",
  ui_story_6_8_36_dialog_content = "Dia bahkan berharap aku menghilang saja. Lalu, aku bertemu Shelt.",
  ui_story_6_8_45_dialog_content = "Dia menjadi inspirasi bagiku saat hidupku stagnan, dan menyalakan kembali gelora jiwa mudaku.",
  ui_story_6_8_46_dialog_content = "Memandangnya saja, aku jadi teringat masa-masa kejayaanku.",
  ui_story_6_8_47_dialog_content = "Keluarga dan status tak ada artinya. Aku hanya ingin menang dalam pertempuran dan mendapatkan hati kekasihku…",
  ui_story_6_8_49_dialog_content = "Cukup! Tak ada yang bersimpati denganmu, Gertzurde.",
  ui_story_6_8_50_dialog_content = "Lihat apa yang sudah kauperbuat!",
  ui_story_6_8_51_dialog_content = "Berselingkuh dari istrimu, berkomplot dengan Eclipsite, menyerang para penjaga, dan mencuri Think Tank Module!",
  ui_story_6_8_53_dialog_content = "Dulu mungkin kau memang jawara Lumopolis, tapi kini kau tak lebih dari seorang pengkhianat penuh dosa!",
  ui_story_6_8_54_dialog_content = "Yah, aku memang mengkhianati Lumopolis. Tak bisa dibenarkan, dan tak bisa diampuni.",
  ui_story_6_8_F3_dialog_content = "Tapi, kurasa perbuatanku tidak salah. Segala yang kulakukan ini demi cinta sejati…",
  ui_story_6_8_55_dialog_content = "Aku tak paham. Konyol!",
  ui_story_6_8_63_dialog_content = "Jadi, ceritanya sudah selesai?",
  ui_story_6_8_64_dialog_content = "Maaf, Lady Sheol. Aku lupa kau juga ada di sini!",
  ui_story_6_8_65_dialog_content = "Aku hanya ingin menekankan bahwa Gertzurde tidak menyesatkan kalian.",
  ui_story_6_8_66_dialog_content = "Dia mengambil rute yang sama dengan yang kuketahui. Dia bahkan menghindari tempat-tempat yang mungkin dipasangi jebakan.",
  ui_story_6_8_67_dialog_content = "…",
  ui_story_6_8_68_dialog_content = "Aku tak butuh pengertian kalian. 'Kan sudah kubilang, aku akan mengantar kalian menemui Schummer. Lalu, aku masih punya urusan yang harus kubereskan.",
  ui_story_6_9_1_dialog_content = "Huh, orang plinplan memang akan selalu plinplan.",
  ui_story_6_9_2_dialog_content = "Maksudmu Gertzurde?",
  ui_story_6_9_3_dialog_content = "Sepertinya kemampuan persuasimu tak sebagus PlayerName.",
  ui_story_6_9_4_dialog_content = "Memangnya kenapa? Aku sudah tahu Gertzurde akan mengkhianati kita. Hanya saja, keadaan ternyata jadi agak berbeda dari yang kuduga.",
  ui_story_6_9_5_dialog_content = "Gara-gara PlayerName?",
  ui_story_6_9_6_dialog_content = "Ya. Aku tak menduga mereka akan membiarkan Gertzurde hidup. Pasti gara-gara si PlayerName yang sok suci itu.",
  ui_story_6_9_7_dialog_content = "Harus kuakui, itu cerdas sekali. Berhentilah menduga-duga, Schummer. Kau tak cocok berpikir.",
  ui_story_6_9_8_dialog_content = "Suatu hari akan kupatahkan lehermu…",
  ui_story_6_9_9_dialog_content = "Toh aku sudah lebih dekat dengan modul itu dibandingkan mereka. Aku bahkan sudah bisa mencium aroma <color=#FFB400>Flame Control Module</color> itu.",
  ui_story_6_9_10_dialog_content = "Saat aku mendapatkannya, aku hanya perlu menunggu PlayerName di sana, lalu…",
  ui_story_6_9_11_dialog_content = "Bunuh mereka semua.",
  ui_story_6_9_12_dialog_content = "Benar, bunuh mereka semua. Kedengarannya seru.",
  ui_story_6_9_13_dialog_content = "Ya, tapi itu hanya karena kosakatamu terbatas. Tetap lanjutkan dengan hati-hati. Mereka didukung Lumopolis dan Illumina.",
  ui_story_6_9_14_dialog_content = "Pasukan mereka tak akan datang. Para Aurorian itu sedang sibuk saling menerka.",
  ui_story_6_9_15_dialog_content = "Kau mau melihatnya langsung? Melihat reaksi mereka nanti pasti seru, lho.",
  ui_story_6_9_16_dialog_content = "Tidak, tak usah. Kau tahu aku tak suka kalau tanganku kotor.",
  ui_story_6_9_17_dialog_content = "Tapi aku bisa mengirimkan bantuan untukmu… Bukan, anggaplah itu <color=#FFB400>hadiah</color>, hadiah untuk mereka.",
  ui_story_6_9_18_dialog_content = "Bantuan? Hadiah? Apa yang kaumaksud itu sama seperti yang kuduga?",
  ui_story_6_9_19_dialog_content = "Ya, <color=#FFB400>teman lama</color> mereka, yang sudah kumodifikasi menjadi lebih baik.",
  ui_story_6_9_20_dialog_content = "Ternyata kau juga tahu cara bersenang-senang, menyibukkan diri dengan semua \"ciptaan\" itu.",
  ui_story_6_9_21_dialog_content = "Ini semua demi mendukung rencanaku, sedangkan kau hanya bisa menimbulkan masalah.",
  ui_story_6_9_22_dialog_content = "Memangnya kau tidak menimbulkan masalah?",
  ui_story_6_9_23_dialog_content = "Cukup sudah. Coba lihat hadiah ini…",
  ui_story_6_9_24_dialog_content = "Ya ampun, indah sekali. Kira-kira bagaimana perasaan PlayerName saat melihat kawan lamanya ini, ya?",
  ui_story_6_9_25_dialog_content = "Aku tak sabar ingin melihatnya…",
  ui_story_6_9_A1_dialog_content = "Berapa jauh lagi, Gertzurde?",
  ui_story_6_9_A2_dialog_content = "Sedikit lagi. Percayalah padaku. Dibandingkan kalian, aku lebih ingin melihat si munafik itu.",
  ui_story_6_9_A3_dialog_content = "…",
  ui_story_6_9_A4_dialog_content = "Schummer meninggalkan Eclipsite di belakang sana untuk menyergap kalian. Kalian ini petarung hebat, 'kan? Kalau begitu, bertarunglah sebaik mungkin.",
  ui_story_6_13_1_dialog_content = "Apa di depan sana itu ujung Whispering Corridor?",
  ui_story_6_13_2_dialog_content = "Ya, dan Schummer pasti ada di dekat sana.",
  ui_story_6_13_3_dialog_content = "Aku bisa merasakan auranya di sana.",
  ui_story_6_13_5_dialog_content = "Cari botol kaca besar yang bagian bawahnya bertuliskan nomor.",
  ui_story_6_13_6_dialog_content = "Hmm, aku lupa berapa nomornya. Sepertinya, sih…",
  ui_story_6_13_7_dialog_content = "<color=#FFB400>RX6007</color>.",
  ui_story_6_13_8_dialog_content = "Ya, benar! Memang itu nomor penyimpanannya! Kok kamu tahu?",
  ui_story_6_13_10_dialog_content = "Schummer menyebutkannya sambil lalu, dan aku bisa ingat semua yang kudengar.",
  ui_story_6_13_11_dialog_content = "Entah informasi atau ingatan masa lalu, ini kutukan.",
  ui_story_6_13_12_dialog_content = "Kalau sudah menemukan benda bernomor itu, berarti kalian sudah dekat dengan benda yang kalian cari.",
  ui_story_6_13_14_dialog_content = "Hati-hati. Kalau Schummer tahu nomornya, berarti…",
  ui_story_6_13_16_dialog_content = "Dia tahu harus mencarinya di mana, dan bahkan mungkin dia sudah menunggu kita di sana.",
  ui_story_6_14_1_dialog_content = "Ah, kita berjumpa lagi.",
  ui_story_6_14_2_dialog_content = "Schu…",
  ui_story_6_14_3_dialog_content = "Schummer!",
  ui_story_6_14_4_dialog_content = "Kau tampak jengkel. Apa gara-gara PlayerName mengalahkanmu?",
  ui_story_6_14_5_dialog_content = "Apa kau ditawan? Apa perlu kuselamatkan agar kau bisa tanding ulang?",
  ui_story_6_14_6_dialog_content = "Kau dan dia, kalian berdua bohong kepadaku. Kau tak berkata jujur tentang kematian Shelt!",
  ui_story_6_14_7_dialog_content = "Kami bohong kepadamu? Tidak, Gertzurde, kau sendiri yang memilih untuk percaya bahwa Shelt dibunuh oleh Lumopolis.",
  ui_story_6_14_8_dialog_content = "Agar kau bisa balas dendam sebagaimana mestinya!",
  ui_story_6_14_9_dialog_content = "Kau membohongi kami semua. Kau membohongi Shelt, memanfaatkannya… dan kini dia sudah tiada!",
  ui_story_6_14_10_dialog_content = "Kalau kita punya tisu dan sudah kita pakai untuk mengelap ingus, bukannya memang tisunya harus dibuang?",
  ui_story_6_14_11_dialog_content = "Seperti itukah Shelt bagimu…?",
  ui_story_6_14_12_dialog_content = "Kau berkeringat. Perjalanannya pasti berat. Nih, tisu untukmu.",
  ui_story_6_14_13_dialog_content = "Terima kasih…",
  ui_story_6_14_14_dialog_content = "Kaget, ya? Yang di wajahmu itu bukan keringat… Apa itu air mata?",
  ui_story_6_14_15_dialog_content = "Kenapa kau menangis, Gertzurde-ku? Bukannya kau ini pengkhianat? Buat apa seorang pengkhianat menangis?",
  ui_story_6_14_16_dialog_content = "Schummer… Kau… Perbuatanmu terhadap Shelt…",
  ui_story_6_14_17_dialog_content = "Memangnya apa yang kuperbuat? Gertzurde, memangnya sekarang kau bisa apa? Sekarang 'kan kau sudah tak punya kemampuan yang pernah kami berikan kepadamu.",
  ui_story_6_14_20_dialog_content = "Kaukah yang memaksa mereka untuk melebur, Schummer?",
  ui_story_6_14_22_dialog_content = "Bukan. Yah, dari sisi teknis sih memang bisa dibilang akulah yang menyuruh mereka…",
  ui_story_6_14_23_dialog_content = "Apa-apaan kau…!",
  ui_story_6_14_24_dialog_content = "Aku tahu kau mau bertanya kenapa kami melakukannya.",
  ui_story_6_14_25_dialog_content = "Kujawab, ya… karena kami mampu.",
  ui_story_6_14_26_dialog_content = "Apa yang membuatmu marah? Memangnya apa salahnya membersihkan dan membuang sampah yang sudah tak terpakai?",
  ui_story_6_14_27_dialog_content = "Tanya lagi, tanya lagi, tanya lagi. Cukup.",
  ui_story_6_14_28_dialog_content = "PlayerName, dan kedua wanita ini… Sampah inilah yang menjadi akar kesengsaraanmu.",
  ui_story_6_14_29_dialog_content = "Schummer, kau…",
  ui_story_6_14_30_dialog_content = "Aku bisa membantumu menyingkirkan mereka…",
  ui_story_6_14_31_dialog_content = "Awas!",
  ui_story_6_14_32_dialog_content = "Carleen!",
  ui_story_6_14_33_dialog_content = "…!",
  ui_story_6_14_34_dialog_content = "Gert… zurde?",
  ui_story_6_14_35_dialog_content = "Kau…!",
  ui_story_6_14_36_dialog_content = "Aku… aku…",
  ui_story_6_14_37_dialog_content = "Kau gila, ya, Gertzurde? Apa kau memang suka membungkuk dan menurut pada siapa pun yang kebetulan datang?",
  ui_story_6_14_38_dialog_content = "Kenapa…",
  ui_story_6_14_39_dialog_content = "Bukan, ini bukan demi kamu… Ini demi Shelt…",
  ui_story_6_14_40_dialog_content = "…",
  ui_story_6_14_A1_dialog_content = "Bunuh… Schummer…",
  ui_story_6_14_A2_dialog_content = "Aku tak cukup kuat untuk melakukannya, tapi kau… kau kuat…",
  ui_story_6_14_A3_dialog_content = "Bunuh dia… dengan pedangmu!",
  ui_story_6_14_A5_dialog_content = "Schummer…",
  ui_story_6_14_A7_dialog_content = "Aku dan Shelt <anim type=Shake><size=50>akan menunggumu di neraka!</size></anim>",
  ui_story_6_14_44_dialog_content = "Gertzurde… Kau…",
  ui_story_6_14_45_dialog_content = "Carleen, dia… Itu kata-kata terakhirnya.",
  ui_story_6_14_46_dialog_content = "Ini jadi sangat, sangat, sangat, sangat membosankan! Maksudku Gertzurde dan kalian semua…",
  ui_story_6_14_47_dialog_content = "Schummer! <color=#FFB400>Mereka datang</color>. Mundur.",
  ui_story_6_14_48_dialog_content = "Jangan cerewet! Sedang apa kau? Minggir!",
  ui_story_6_14_49_dialog_content = "Kuminta kau pergi. Sekarang.",
  ui_story_6_14_50_dialog_content = "Kenapa?",
  ui_story_6_14_51_dialog_content = "Ada apa?",
  ui_story_6_14_52_dialog_content = "Sepertinya ada <color=#FFB400>pasukan</color> datang dan membawa bendera Illumina, PlayerName! Jumlahnya banyak sekali!",
  ui_story_6_14_53_dialog_content = "Bertahanlah. Begitu sampai di sini, mereka akan mengepung tempat ini!",
  ui_story_6_14_54_dialog_content = "Ada gelombang energi besar mendekat. Ambil modulnya dan segera keluar dari sini.",
  ui_story_6_14_56_dialog_content = "Aku bisa membunuh mereka semua dalam sekejap! Lalu akan kukalahkan PlayerName, dan pelan-pelan…",
  ui_story_6_14_57_dialog_content = "Kau tak akan berhasil.",
  ui_story_6_14_58_dialog_content = "Aku pasti berhasil! Beri aku waktu tiga menit. Tidak, satu menit saja…",
  ui_story_6_14_59_dialog_content = "Sudah kubilang kau tak akan berhasil! Pasukan Illumina sudah menuju kemari! Aku tak mau ambil risiko.",
  ui_story_6_14_60_dialog_content = "Oh, oh, oh! Ayo tambah lagi asapnya!",
  ui_story_6_14_61_dialog_content = "Sebagai garda depan Illumina Legion, aku adalah…",
  ui_story_6_14_62_dialog_content = "Si Pemburu Eclipsite, Pembasmi Malam, Ahli Bahan Peledak dari Undercity, sang Acheron Ferryman, Charon!",
  ui_story_6_14_63_dialog_content = "Aku membawa prajurit tak terhitung banyaknya untuk mengepung Whispering Corridor! Tak satu pun Eclipsite akan bisa lolos!",
  ui_story_6_14_X64_dialog_content = "Jangan sampai aku memaksamu, Schummer.",
  ui_story_6_14_65_dialog_content = "Baiklah, sesukamu sajalah! Toh kami sudah dapat modulnya…",
  ui_story_6_14_66_dialog_content = "Berhenti, Schummer!",
  ui_story_6_14_67_dialog_content = "Mana <color=#FFB400>Flame Control Module</color> itu?",
  ui_story_6_14_68_dialog_content = "<color=#FFB400>Di sini</color>.",
  ui_story_6_14_69_dialog_content = "Kau tak bisa kabur, apalagi pasukan kami sudah tiba.",
  ui_story_6_14_70_dialog_content = "Kalian justru seharusnya mengkhawatirkan Lumopolis.",
  ui_story_6_14_71_dialog_content = "Lumopolis?",
  ui_story_6_14_72_dialog_content = "Yah, kota yang disebut-sebut sebagai Kota Tak Terkalahkan? Sungguh julukan yang tak masuk akal.",
  ui_story_6_14_A8_dialog_content = "Tunggu sampai aku berhasil mengisi ulang daya Black Colossus! Akan kutunjukkan kekuatan mutlak kepada kalian!",
  ui_story_6_14_73_dialog_content = "Tanahnya! Semuanya, hati-hati!",
  ui_story_6_14_74_dialog_content = "Kaget?",
  ui_story_6_14_75_dialog_content = "Itu… Nozard! Tapi dia 'kan sudah mati?",
  ui_story_6_14_76_dialog_content = "<anim type=Shake><size=45>*Mengerang*</size></anim>",
  ui_story_6_14_77_dialog_content = "Daur ulang adalah hal baik. Selalu pakai ulang semua barang.",
  ui_story_6_14_78_dialog_content = "Jangan buang waktu lagi. Black Colossus sedang mendarat.",
  ui_story_6_14_79_dialog_content = "Sayang sekali aku tak bisa tinggal untuk menyaksikan pertunjukannya.",
  ui_story_6_14_80_dialog_content = "Yah, semoga lain kali lebih seru. Dadah, semuanya!",
  ui_story_6_14_81_dialog_content = "Eclipsite itu Nozard? Aku bisa merasakan kebencian sangat kuat darinya!",
  ui_story_6_14_83_dialog_content = "Ini berbeda dari saat terakhir kali kita menghadapi Nozard. Semuanya, hati-hati!",
  ui_story_6_14_84_dialog_content = "Harusnya waktu itu kita habisi saja Nozard, tapi kali ini dia malah kembali dan jauh lebih kuat dibandingkan dulu.",
  ui_story_6_14_85_dialog_content = "Kau pernah bertemu Eclipsite seperti ini sebelum menuju Lumopolis?",
  ui_story_6_14_86_dialog_content = "Ya, tapi kami yakin waktu itu dia sudah mati.",
  ui_story_6_14_87_dialog_content = "Jadi, maksudmu, Eclipse membangkitkannya dan mengubahnya menjadi senjata baru? Seram sekali…",
  ui_story_6_14_90_dialog_content = "Bagi mereka, Eclipsite bukan teman. Mereka hanya menganggap Eclipsite sebagai alat, sama seperti Shelt dan Shire.",
  ui_story_6_14_92_dialog_content = "<color=#FFB400>Flame Control Module</color> sudah direbut. Sekarang kita harus bagaimana?",
  ui_story_6_14_93_dialog_content = "Kita masih harus mengurus Gertzurde…",
  ui_story_6_14_94_dialog_content = "Carleen?",
  ui_story_6_14_97_dialog_content = "Akan kubakar jasad Gertzurde.",
  ui_story_6_14_98_dialog_content = "Tidak dikubur saja? Itu 'kan bertentangan dengan tradisi Lumopolis…",
  ui_story_6_14_99_dialog_content = "Pertama, dia itu pengkhianat, dan karenanya jasadnya harus dilenyapkan. Kedua, Eclipse mungkin saja akan berusaha membangkitkan jasadnya.",
  ui_story_6_14_100_dialog_content = "Benar. Mereka tak akan berpikir dua kali untuk mengubah mayatnya menjadi senjata. Mengerikan.",
  ui_story_6_14_102_dialog_content = "Vice, PlayerName, kumpulkan benda-benda yang mudah terbakar.",
  ui_story_6_14_103_dialog_content = "Aku, Carleen de Schwartz, Kapten dari Lumopolis Guardians, atas nama Lumopolis, dengan ini menyatakan keputusan akhir untuk Gertzurde:",
  ui_story_6_14_104_dialog_content = "Dia adalah seorang kesatria Lumopolis yang kemampuannya telah terbukti di tengah kacaunya pertempuran.",
  ui_story_6_14_105_dialog_content = "Tapi, karena dicemari oleh iblis di dalam hatinya dan diperdaya Eclipsite, dia mengkhianati Lumopolis.",
  ui_story_6_14_106_dialog_content = "Dia dimanipulasi oleh musuh, dia membantu dan bersekongkol dengan Eclipsite untuk membahayakan masyarakat Lumopolis.",
  ui_story_6_14_107_dialog_content = "Tapi, pada akhirnya, dia kehilangan arah dan harus menebusnya dengan nyawanya. Kejahatan yang telah diperbuatnya tak bisa diampuni, tapi dia bisa dibebaskan dari hukuman, yaitu jasadnya tidak akan ditinggalkan begitu saja.",
  ui_story_6_14_108_dialog_content = "Kami akan membakar jasadnya untuk mengabadikan integritasnya… Demi White Night.",
  ui_story_6_14_109_dialog_content = "Beristirahatlah dalam damai, Gertzurde, jawara Lumopolis, kesatria Pengkhianat, antek-antek Eclipse.",
  ui_story_6_14_111_dialog_content = "Biarlah dia beristirahat dalam damai. PlayerName, kau bisa merasakan di mana Schummer berada?",
  ui_story_6_14_112_dialog_content = "Dia sudah pergi dari Whispering Corridor.",
  ui_story_6_14_114_dialog_content = "Aku kurang yakin ke mana arah yang ditujunya. Menurut dugaanku, sepertinya dia sedang di udara.",
  ui_story_6_14_115_dialog_content = "Di udara? Maksudmu, waktu dia tadi menyebut Lumopolis, yang dimaksudnya adalah…",
  ui_story_6_14_116_dialog_content = "Maaf menyela, tapi apa kau masih hidup?",
  ui_story_6_14_117_dialog_content = "Tentu saja!",
  ui_story_6_14_118_dialog_content = "Di hadapanku tiba-tiba muncul seseorang yang memancarkan aura kuat. Kukira…",
  ui_story_6_14_119_dialog_content = "Selain gagal mendapatkan Flame Control Module, kami baik-baik saja.",
  ui_story_6_14_120_dialog_content = "Bagus, bagus.",
  ui_story_6_14_121_dialog_content = "Bagaimana dengan pasukan Illumina? Bukannya tadi kaubilang bala bantuan sudah sampai sini?",
  ui_story_6_14_122_dialog_content = "Nah, kau akan segera melihatnya sendiri.",
  ui_story_6_14_123_dialog_content = "Hai, Vice, PlayerName.",
  ui_story_6_14_124_dialog_content = "Officer Charon?",
  ui_story_6_14_125_dialog_content = "Boleh aku minum dulu? Aku haus sekali setelah lari jauh.",
  ui_story_6_14_126_dialog_content = "Ada apa? Mana pasukannya?",
  ui_story_6_14_127_dialog_content = "Beberapa jam lalu, Philyshy memberitahuku bahwa kalian mungkin sedang menghadapi masalah.",
  ui_story_6_14_128_dialog_content = "Tapi, Gannon menolak untuk mengerahkan pasukan, jadi akhirnya kuputuskan untuk berangkat sendirian saja.",
  ui_story_6_14_129_dialog_content = "Jangan bilang padaku ternyata kaulah \"pasukan\" yang disebutkan Lady Sheol barusan…",
  ui_story_6_14_130_dialog_content = "Persis begitulah, Vice.",
  ui_story_6_14_131_dialog_content = "Saat tiba di area ini, tadi aku melihat Colossus hitam yang tampak aneh, lalu aku bertemu Lady Sheol.",
  ui_story_6_14_132_dialog_content = "Dia khawatir kalian tak mampu mengalahkan Schummer, jadi aku pun menyusun rencana.",
  ui_story_6_14_133_dialog_content = "Jadi, aku… Ehem, anggap sajalah tak mudah untuk membuat seakan-akan ada ribuan prajurit di luar sana.",
  ui_story_6_14_134_dialog_content = "Rupanya itu hanya bualan, ya. Tapi, bagaimana jadinya kalau tadi Schummer tak tertipu?",
  ui_story_6_14_135_dialog_content = "Setidaknya tetap harus dicoba. Lagi pula, memangnya ada yang bisa menebak jumlah prajurit yang ada di dalam kereta Illumina?",
  ui_story_6_14_136_dialog_content = "Omong-omong, si Schummer itu kabur ke mana?",
  ui_story_6_14_137_dialog_content = "Aku melewatkannya. Aku tak bisa melihatnya gara-gara hamburan debu yang kusepak-sepak tadi…",
  ui_story_6_14_138_dialog_content = "Dari auranya, sekarang aku cukup yakin tentang arah yang ditujunya. Menuju angkasa… Menuju Lumopolis.",
  ui_story_6_14_139_dialog_content = "Lumopolis!",
  ui_story_6_14_140_dialog_content = "Lumopolis?!",
  ui_story_6_14_141_dialog_content = "Dia langsung menuju ke sana, persis setelah berhasil merebut semua modulnya? Apa dia mengincar Lumopolis!?",
  ui_story_6_14_142_dialog_content = "Ada perisai kuat yang melindungi Lumopolis. Mustahil dia bisa menerobos masuk!",
  ui_story_6_14_A9_dialog_content = "Tapi, pasti dia punya alasan tersendiri untuk menuju ke sana.",
  ui_story_6_14_143_dialog_content = "Jadi, dikiranya dia bisa bertarung langsung melawan Lumopolis dengan Colossus yang sekarang dimilikinya itu?",
  ui_story_6_14_144_dialog_content = "PlayerName, bersiaplah berangkat ke Lumopolis, segera!",
  ui_story_6_14_145_dialog_content = "Siap, ayo bergegas!",
  ui_story_7_1_1_dialog_content = "Master of the White Night adalah baju zirahku, dagingku, dan tulangku. Dengan perlindungan darinya, tak satu pun makhluk jahat bisa melukaiku…",
  ui_story_7_1_A1_dialog_content = "Master of the White Night adalah baju zirahku, dagingku, dan tulangku. Dengan perlindungan darinya, tak satu pun makhluk jahat… Tetap tenang! Jangan panik!",
  ui_story_7_1_2_dialog_content = "Lihat, dia menabrak perisai!",
  ui_story_7_1_3_dialog_content = "Apa itu… naga… <color=#FFB400>naga hitam</color>!?",
  ui_story_7_1_4_dialog_content = "Itu bukan masalah, 'kan? Perisai kita tak bisa ditembus dan dihancurkan semudah itu!",
  ui_story_7_1_5_dialog_content = "Yakinlah pada Master of the White Night. Yakinlah pada perlindungan dari Aurora.",
  ui_story_7_1_6_dialog_content = "Selama perisai itu masih ada, tak satu pun makhluk jahat bisa masuk ke Uptown yang suci! Tak perlu panik!",
  ui_story_7_1_7_dialog_content = "Kita hampir sampai! Lumopolis sudah di depan sana!",
  ui_story_7_1_8_dialog_content = "Kenapa langitnya berubah warna!?",
  ui_story_7_1_9_dialog_content = "City Lord sudah mengaktifkan <color=#FFB400>perisai</color>.",
  ui_story_7_1_X1_dialog_content = "Sekarang mungkin banyak orang sedang dalam bahaya. Kita harus cepat-cepat masuk ke kota!",
  ui_story_7_1_X2_dialog_content = "Dan Schummer?",
  ui_story_7_1_10_dialog_content = "Selamatkan warga sipil dulu. Kita menuju kota!",
  ui_story_7_1_11_option_content = "Baiklah, kita akan mendarat di dalam kota.",
  ui_story_7_1_12_option_content = [[
Tidak, lebih baik
kita mendarat di luar area kota.]],
  ui_story_7_1_13_dialog_content = "Tidak… Dengan ukuranku dan kondisi Lumopolis saat ini, itu mustahil.",
  ui_story_7_1_14_dialog_content = "Keadaan tidak bagus. <color=#FFB400>Perisai Lumopolis sudah diaktifkan</color>.",
  ui_story_7_1_A2_dialog_content = "Perisai itu akan mencegah para Eclipsite masuk ke kota, tapi Soroz juga tak akan bisa masuk.",
  ui_story_7_1_16_dialog_content = "Kalau sudah ada perisai yang begitu kuat, lantas kenapa kita harus buru-buru?",
  ui_story_7_1_17_dialog_content = "Perisai itu hanya melindungi Uptown… Area lainnya dalam kota sama sekali tak tercakup dalam perlindungannya!",
  ui_story_7_1_F1_dialog_content = "Para Eclipsite itu pasti akan masuk dari Lower Lumopolis dan menyerang titik lemah perisai itu!",
  ui_story_7_1_F2_dialog_content = "Kita tak bisa menyuruh Soroz mendarat di Lower Lumopolis kalau tempat itu sudah dipenuhi Eclipsite.",
  ui_story_7_1_18_dialog_content = "PlayerName, aku bisa terbang melayang di atas Lumopolis dan kau bisa menemuiku sewaktu-waktu kalau kau membutuhkanku.",
  ui_story_7_1_19_dialog_content = "Apa tidak berbahaya?",
  ui_story_7_1_F3_dialog_content = "Aku akan berusaha sebisaku untuk tetap mewaspadai Schummer dan terus berkomunikasi denganmu!",
  ui_story_7_1_F4_dialog_content = "Maaf, Soroz, kau terpaksa harus begitu gara-gara aku.",
  ui_story_7_1_20_dialog_content = "Carleen, apa Lumopolis bisa diterobos?",
  ui_story_7_1_21_dialog_content = "Tidak, itu mustahil. Selama <color=#FFB400>pria itu</color> masih di sana, Lumopolis akan tetap berdiri kokoh.",
  ui_story_7_1_22_dialog_content = "Memang. Dengan ukuranku dan keadaan Lumopolis saat ini, kita tak akan diizinkan masuk.",
  ui_story_7_1_23_dialog_content = "PlayerName, bagaimana menurutmu, apa sebaiknya kita menyuruh Soroz mendarat di luar saja?",
  ui_story_7_1_24_dialog_content = "Yah, kalau Schummer memang mengincar Lumopolis, Soroz harus berada sejauh mungkin dari sana.",
  ui_story_7_1_25_dialog_content = "Aku setuju. Kalaupun kita ingin mengarahkan Soroz untuk masuk ke kota, itu mustahil dilakukan.",
  ui_story_7_1_26_dialog_content = "<color=#FFB400>Perisai Uptown sudah diaktifkan</color>, dan itu artinya tak seorang pun bisa masuk.",
  ui_story_7_1_F5_dialog_content = "Tapi, para Eclipsite itu pasti akan masuk dari Lower Lumopolis dan menyerang titik lemah perisai itu!",
  ui_story_7_1_27_dialog_content = "PlayerName, aku bisa terbang melayang di atas Lumopolis dan kau bisa menemuiku sewaktu-waktu kalau kau membutuhkanku.",
  ui_story_7_1_28_dialog_content = "Apa tidak berbahaya?",
  ui_story_7_1_F6_dialog_content = "Aku akan berusaha sebisaku untuk tetap mewaspadai Schummer dan terus berkomunikasi denganmu!",
  ui_story_7_1_F7_dialog_content = "Maaf, Soroz, kau terpaksa harus begitu gara-gara aku.",
  ui_story_7_1_29_dialog_content = "Ayo berangkat secepat mungkin. Kalau Schummer benar-benar yakin dia bisa merebut Lumopolis…",
  ui_story_7_1_30_dialog_content = "Tidak, itu mustahil. Selama <color=#FFB400>pria itu</color> masih di sana, Lumopolis akan tetap berdiri kokoh.",
  ui_story_7_1_31_dialog_content = "Lord, ancamannya sudah bisa dipastikan. Sebuah Colossus, dan dia menyerang Lumopolis!",
  ui_story_7_1_32_dialog_content = "Perisai kita sudah diaktifkan, dan untuk sementara ini Uptown masih aman.",
  ui_story_7_1_33_dialog_content = "Jangan ceroboh. Saat ini, kita tak bisa menduga kekuatan dan niat musuh. Tetap waspada.",
  ui_story_7_1_34_dialog_content = "Suruh para Guardian untuk terus mengawasi pergerakan musuh. Intelligence Department akan memberitahukan segala perkembangan baru kepada kita.",
  ui_story_7_1_35_dialog_content = "Bagaimana situasi saat ini di Lower Lumopolis?",
  ui_story_7_1_36_dialog_content = "Lord, para Eclipsite itu berhasil menyusup masuk ke Lower Lumopolis. Apa perlu kita kerahkan pasukan untuk membantu di sana?",
  ui_story_7_1_37_dialog_content = "Jangan. Tetap fokus saja untuk melindungi Uptown. Jangan sampai para bangsawan panik dan malah mengambil keputusan bodoh.",
  ui_story_7_1_38_dialog_content = "Lagi pula Lower Lumopolis punya cara sendiri untuk bertahan hidup.",
  ui_story_7_1_39_dialog_content = "Bagaimana dengan Illumina Legion?",
  ui_story_7_1_40_dialog_content = "Sebagian besar legiunnya ditempatkan jauh dari sini dan tak mungkin kembali tepat waktu untuk membantu.",
  ui_story_7_1_41_dialog_content = "Hanya dua skuadron yang sudah sampai di dekat Lumopolis, satu skuadron dipimpin Chief of Staff Vivian dan satu lagi dipimpin oleh Legion Commander Sharona.",
  ui_story_7_1_42_dialog_content = "Dua skuadron itu? Baiklah. Terakhir, bagaimana dengan <color=#FFB400>Carleen</color>? Ada kabar?",
  ui_story_7_1_43_dialog_content = "Aku baru saja menerima kabar bahwa Kapten dari Guardians itu sekarang sedang berjalan kaki menuju Lower Lumopolis.",
  ui_story_7_1_44_dialog_content = "Segera panggil dia kembali ke Uptown. Ini bukan saatnya main-main. Sekarang ini, kita sama sekali tak butuh kabar burung.",
  ui_story_7_1_45_dialog_content = "<color=#e8d9bb>Di dalam Lower Lumopolis</color>",
  ui_story_7_1_46_dialog_content = "Aku belum lihat satu pun Guardian.",
  ui_story_7_1_47_dialog_content = "Aku bisa merasakan ada Eclipsite di sini.",
  ui_story_7_1_48_dialog_content = "Berantakan sekali. Aku tak percaya ini Lumopolis.",
  ui_story_7_1_49_dialog_content = "Berhasil mendarat… Kira-kira di atas… lokasimu.",
  ui_story_7_1_A3_dialog_content = "Perisai Lumopolis… mengganggu sistemku. Semoga… dengar…",
  ui_story_7_1_50_dialog_content = "Tak usah khawatir, aku paham! Kami baik-baik saja. Jaga dirimu!",
  ui_story_7_1_51_dialog_content = "Harusnya aku yang bilang… begitu, PlayerName.",
  ui_story_7_1_52_dialog_content = "Aku akan… menunggumu! Jaga… dirimu…",
  ui_story_7_1_53_dialog_content = "Kuharap ada orang yang bisa memberi tahu kita tentang situasi saat ini…",
  ui_story_7_1_54_dialog_content = "Tidak seburuk yang kaulihat, Vice, PlayerName.",
  ui_story_7_1_55_dialog_content = "Madam <color=#FFB400>Vivian</color>!",
  ui_story_7_1_56_dialog_content = "Sebagian besar legiun sedang menjaga area di sekitar, jadi kamilah satu-satunya yang bisa membantu untuk sementara ini.",
  ui_story_7_1_57_dialog_content = "Lumopolis runtuh? Warga tak terkendali!",
  ui_story_7_1_A4_dialog_content = "Kita bertemu lagi, Caelestite! Setiap kali muncul masalah, kau pasti ada di sana.",
  ui_story_7_1_58_dialog_content = "Aku tak mau berurusan dengan ini semua… Tolong jangan salahkan aku…",
  ui_story_7_1_59_dialog_content = "Kenapa pula kami harus menyalahkanmu? Kau malah sudah berusaha keras untuk menghentikan Schummer, 'kan? Kami hanya tak menduganya, itu saja.",
  ui_story_7_1_60_dialog_content = "Chief, apa kau tahu apa yang terjadi di Lumopolis?",
  ui_story_7_1_61_dialog_content = "Uptown sudah diamankan, tentu saja. Kalian lihat perisainya, 'kan?",
  ui_story_7_1_62_dialog_content = "Perisainya sudah diaktifkan. Tak ada yang bisa menembusnya. Itulah yang membuat orang-orang menyebut Lumopolis sebagai Kota Tak Terkalahkan.",
  ui_story_7_1_63_dialog_content = "Tapi, Lower Lumopolis tak seberuntung itu.",
  ui_story_7_1_64_dialog_content = "Madam <color=#FFB400>Sharona</color>? Maksudku, Legion Commander…",
  ui_story_7_1_65_dialog_content = "Ah, aku lupa bahwa sebagian besar pasukan yang dikerahkan untuk menangani situasi darurat ini adalah pindahan dari 1st Legion.",
  ui_story_7_1_66_dialog_content = "Perisainya tidak menyelubungi Lower Lumopolis. Bocah berusia tiga tahun saja bisa leluasa keluar-masuk, apalagi Eclipsite.",
  ui_story_7_1_68_dialog_content = "Apa kau bisa menanganinya? Ada apa? Beri tahukan detailnya kepadaku.",
  ui_story_7_1_70_dialog_content = "Kami sedang menjalankan operasi sapu bersih cepat, dan akan sulit, tapi sementara ini pasukanku nyaris tak mampu mengatasi situasi ini.",
  ui_story_7_1_71_dialog_content = "Bagaimana dengan Guardians? Aku menerima perintah untuk segera kembali ke Uptown. Mana Guardians yang lainnya?",
  ui_story_7_1_72_dialog_content = "Carleen de Schwartz, sepertinya kau kurang memahami perkataanku.",
  ui_story_7_1_A5_dialog_content = "Ayahmu memerintahkan semua Guardians, termasuk kau, untuk melindungi Uptown.",
  ui_story_7_1_73_dialog_content = "Kau tak terkejut, 'kan? Pasti kau sudah menduga akan begini jadinya.",
  ui_story_7_1_74_dialog_content = "Kau tak perlu bicara seperti itu padaku, Sharona! Aku yakin kontribusiku sudah cukup banyak dan aku layak dihormati!",
  ui_story_7_1_75_dialog_content = "Memangnya ada yang berubah berkat tindakanmu? Lumopolis tetaplah Lumopolis.",
  ui_story_7_1_76_option_content = "Cukup, nona-nona!",
  ui_story_7_1_77_option_content = [[
Kalian berdua, diam!
Kita punya urusan yang lebih genting!]],
  ui_story_7_1_78_dialog_content = "Aku tak tertarik untuk berdebat.",
  ui_story_7_1_79_dialog_content = "PlayerName, ini bukan giliranmu menjadi penengah.",
  ui_story_7_1_80_dialog_content = "Ini urusan antara Illumina dan Lumopolis.",
  ui_story_7_1_81_dialog_content = "Bukan itu masalah yang harus kita hadapi. Lagi pula, bukankah kalian semua ini Aurorian?",
  ui_story_7_1_82_dialog_content = "Chief, PlayerName hanya sebatas khawatir dengan situasi saat ini. Kita semua sedang menghadapi situasi genting…",
  ui_story_7_1_83_dialog_content = "Pengamatanmu cermat, Vice. Yang dibilang PlayerName tadi memang benar. Bukankah kita ini keluarga?",
  ui_story_7_1_84_dialog_content = "Pertama-tama dan yang terutama, yang paling penting adalah kita semua, sesama Aurorian, harus bertarung bersama! Iya, 'kan?",
  ui_story_7_1_85_dialog_content = "Aku setuju. Untuk sekarang ini, pendapat kita tak penting.",
  ui_story_7_1_86_dialog_content = "Omong-omong, Carleen, bukannya kau harus kembali dulu ke Uptown? City Lord sepertinya mencarimu.",
  ui_story_7_1_F8_dialog_content = "Apa cuma aku yang bisa melihat para Eclipsite itu?",
  ui_story_7_1_87_dialog_content = "Jaga bicaramu, PlayerName!",
  ui_story_7_1_88_dialog_content = "Kau sedang berbicara kepada Commander dari 1st Illumina Legion dan Carleen, PlayerName.",
  ui_story_7_1_89_dialog_content = "Aku tahu! Tapi, aku juga tahu, entah Legion Commander atau Kapten dari Guardians, seharusnya kita menyelamatkan warga, bukannya malah buang-buang waktu untuk cekcok tanpa guna!",
  ui_story_7_1_90_dialog_content = "Ya. Sekarang ini, yang paling penting adalah melawan para Eclipsite itu, bukannya malah bertengkar soal secuil kuasa.",
  ui_story_7_1_91_dialog_content = "Sayangnya, aku tak butuh diajari cara berperilaku oleh seorang gadis kecil. Terima kasih banyak.",
  ui_story_7_1_92_dialog_content = "Kalau hanya membunuh Eclipsite, aku sudah melakukannya berulang kali dalam pertempuran setiap hari.",
  ui_story_7_1_93_dialog_content = "Kudengar baru-baru ini kau juga banyak bertarung. Kau pasti bisa memahaminya, 'kan?",
  ui_story_7_1_94_dialog_content = "…",
  ui_story_7_1_95_dialog_content = "Baiklah kalau begitu, kita sudah sepakat. Ayo salurkan energi kita untuk membasi para Eclipsite itu.",
  ui_story_7_1_96_dialog_content = "Apa kau mau kembali dulu, Carleen?",
  ui_story_7_1_97_dialog_content = "Tidak. Kalau aku sedang berada di luar, tak seorang pun bisa memerintahku.",
  ui_story_7_1_98_dialog_content = "Ini 'kan bukan di luar. Maksudku, kau 'kan sebenarnya berada di kampung halamanmu…",
  ui_story_7_1_F9_dialog_content = "Cukup, Vice…",
  ui_story_7_1_99_dialog_content = "Legion Commander! Jumlah Eclipsite di Lower Lumopolis ternyata lebih banyak dari yang kita perkirakan! Pertahanan kita sudah hampir mencapai batas, dan ada Eclipsite yang berhasil menerobos masuk!",
  ui_story_7_1_A6_dialog_content = "Penduduk di sekitar sini tak punya waktu untuk evakuasi! Kami harus bagaimana?",
  ui_story_7_1_100_dialog_content = "Aku sendiri akan ke sana! Kalian semua, lakukan sesuka kalian.",
  ui_story_7_1_101_dialog_content = "Ajak kami juga! Kami bisa membantu!",
  ui_story_7_1_102_dialog_content = "Kau jelas penuh semangat, Vice! <color=#FFB400>Baiklah. Ayo berangkat</color>!",
  ui_story_7_1_103_dialog_content = "Biar aku yang memimpin. Aku sudah sering sekali patroli di Lower Lumopolis. Tak ada yang hafal jalanannya sebaik aku.",
  ui_story_7_1_104_dialog_content = "Carleen, memangnya tak apa kalau kau tidak kembali dulu?",
  ui_story_7_1_105_dialog_content = "Tak ada lagi yang harus diributkan. Aku sudah memutuskan. Ayo kita akhiri semua ini.",
  ui_story_7_1_106_dialog_content = "Perisai Lumopolis ternyata memang sangat kuat!",
  ui_story_7_1_107_dialog_content = "Sial, kenapa kau tidak bilang dari awal tentang pertahanan ini?! Siasat pengecut macam apa sih ini?",
  ui_story_7_1_108_dialog_content = "Sudah kubilang padamu untuk menunggu sampai kekuatannya penuh sebelum menyerang. Tapi, jelas, kau terlalu sombong untuk menunggu!",
  ui_story_7_1_109_dialog_content = "Kalau kau masih punya waktu untuk berceramah begitu, kenapa tidak kaukerahkan anak buahmu lebih banyak untuk mengacau di Lumopolis?",
  ui_story_7_1_110_dialog_content = "Sst, diam. Aku tak suka keributan.",
  ui_story_7_1_111_dialog_content = "Sebentar lagi perisai Lumopolis akan kehabisan energi.",
  ui_story_7_1_A7_dialog_content = "Saat itulah kau akan bisa melenggang masuk.",
  ui_story_7_1_112_dialog_content = "Lalu, sekarang apa yang harus kulakukan? Menunggu, atau terus menyerang?",
  ui_story_7_1_113_dialog_content = "Kau mau duduk diam saja dan melihat teman-temanmu yang tak berguna itu mempermalukan kita?",
  ui_story_7_1_114_dialog_content = "Sabar, Schummer. Musuh lamamu bersembunyi di sekitar sini.",
  ui_story_7_1_116_dialog_content = "Maksudmu Soroz? Dan PlayerName?",
  ui_story_7_1_117_dialog_content = "Benar. Sepertinya kau ingin keluar dan bermain… Lucu sekali.",
  ui_story_7_1_X3_dialog_content = "Akan kulakukan sesukaku. Jangan lupa, aku tak mau diperintah siapa pun… Bukan olehmu, bukan pula Eclipse.",
  ui_story_7_1_X4_dialog_content = "Ya ampun. Kau ini menyebalkan.",
  ui_story_7_2_1_dialog_content = "Carleen, berapa jauh jarak kita dari area yang perlu bantuan?",
  ui_story_7_2_2_dialog_content = "Kita sudah sampai! Ini tempat yang barusan disebut prajurit itu.",
  ui_story_7_2_3_dialog_content = "Aura Eclipsite terasa kuat sekali di sini. Nah, soal <color=#FFB400>urusan paling mendesak</color> yang harus ditangani di sini…",
  ui_story_7_2_4_option_content = "Pertama, kita harus mengevakuasi warga.",
  ui_story_7_2_5_option_content = "Singkirkan para Eclipsite yang berkeliaran.",
  ui_story_7_2_6_dialog_content = "PlayerName, sang andalan masyarakat! Mungkin suatu hari nanti kau akan jadi pemimpin hebat!",
  ui_story_7_2_7_dialog_content = "Pujianmu membuatku malu, Madam…",
  ui_story_7_2_8_dialog_content = "Baiklah, aku akan mencari warga yang perlu bantuan. Gerakku lebih cepat daripada kalian semua.",
  ui_story_7_2_A1_dialog_content = "Basmi setiap Eclipsite yang kalian temui. Kalian pasti bisa menanganinya dengan mudah, 'kan?",
  ui_story_7_2_9_dialog_content = "Kami paham! Satu-satunya cara untuk memastikan kelancaran penyelamatan adalah dengan membasmi ancaman yang ada.",
  ui_story_7_2_10_dialog_content = "Kita berpencar. Mungkin upaya penyelamatan dan pembasmian bisa dijalankan bersamaan.",
  ui_story_7_2_11_dialog_content = "Aku akan mencari warga yang perlu bantuan. Gerakku lebih cepat daripada kalian semua.",
  ui_story_7_2_A2_dialog_content = "Basmi setiap Eclipsite yang kalian temui. Kalian pasti bisa menanganinya dengan mudah, 'kan?",
  ui_story_7_2_12_dialog_content = "Jangan meremehkanku, Sharona.",
  ui_story_7_2_13_dialog_content = "Sepertinya kalian semua sudah siap beraksi! Bagus, ayo!",
  ui_story_7_2_14_dialog_content = "Aku akan ke sana. Vice, tangani bagian sana!",
  ui_story_7_2_15_dialog_content = "Bagaimana dengan Colossus-mu? Kita belum keluar dari hutan. Ingat, awasi belakangmu!",
  ui_story_7_2_16_dialog_content = "Soroz sedang terbang melayang di luar kota dan mestinya aman untuk sementara ini… Semoga.",
  ui_story_7_2_17_dialog_content = "Jumlah kita hanya sedikit, jadi kerahkan semua kekuatan kalian.",
  ui_story_7_2_F1_dialog_content = "Yah, seandainya saja Guardians ada di sini untuk membantu kita…",
  ui_story_7_2_18_dialog_content = "Lho, memangnya aku ini tidak dianggap sebagai Guardian?",
  ui_story_7_2_19_dialog_content = "Maaf, aku tak bermaksud mengesampingkan siapa pun.",
  ui_story_7_2_21_dialog_content = "Ayo bergerak dan hajar para Eclipsite itu! Targetku hari ini adalah membasmi tiga digit Eclipsite!",
  ui_story_7_2_22_dialog_content = "Apa itu…",
  ui_story_7_2_23_dialog_content = "Setiap Officer kelas atas di Illumina punya kemampuan luar biasa. Ayo mulai basmi musuh di sekitar sini!",
  ui_story_7_6_1_dialog_content = "Fyuh. Di sini sudah beres!",
  ui_story_7_6_2_dialog_content = "Di sini juga! Madam, apa masih ada tempat lain di Lower Lumopolis yang butuh bantuan?",
  ui_story_7_6_3_dialog_content = "Sebagian besar makhluk dungu itu memang sudah bermunculan, tapi mereka bisa ditangani. Aksi kalian bagus.",
  ui_story_7_6_4_dialog_content = "Fyuh. Krisisnya sudah teratasi. Sepertinya kita tepat waktu.",
  ui_story_7_6_6_dialog_content = "Bagus sekali, Vice. Untuk sementara ini, Lower Lumopolis mestinya aman. Kita bisa memeriksa di tempat lain!",
  ui_story_7_6_7_dialog_content = "Musuh mungkin saja berencana menyerang titik lemah dalam pertahanan kita!",
  ui_story_7_6_8_dialog_content = "Chief, tahukah kau bahwa kau sangat lihai menggunakan kekuatan yang disebut Jinx itu?",
  ui_story_7_6_9_dialog_content = "Untuk jaga-jaga, apa kau bisa memastikan keadaan Soroz, PlayerName?",
  ui_story_7_6_10_dialog_content = "Sudah agak lama Soroz tidak menghubungiku. Biar kucoba.",
  ui_story_7_6_12_dialog_content = "Normal. Tak ada Eclipsite di sekitarku…. tapi sepertinya suhunya turun banyak, aku…",
  ui_story_7_6_13_dialog_content = "<size=45>Apa?!</size>",
  ui_story_7_6_14_dialog_content = "Ada apa, Carleen? Kau terluka?",
  ui_story_7_6_15_dialog_content = "Tidak, tapi aku baru saja menerima pesan bahwa <color=#FFB400>musuh sudah berhasil menerobos masuk Uptown</color>!",
  ui_story_7_6_16_dialog_content = "Uptown? Eclipsite menembus pertahanan Lower Lumopolis dan sekarang menerobos ke Uptown?",
  ui_story_7_6_17_dialog_content = "Tidak, baris pertahanan Lower Lumopolis masih utuh. Mereka pasti sudah lebih dulu menyusup ke Uptown!",
  ui_story_7_6_18_dialog_content = "Mereka langsung menyerang pusat Lumopolis? Bukannya pertahanan di Uptown sangat ketat?",
  ui_story_7_6_19_dialog_content = "Ya, begitulah. Tapi para Eclipsite itu bertingkah aneh belakangan ini…",
  ui_story_7_6_20_dialog_content = "Kalau Schummer sampai berani menyerang Lumopolis, berarti mungkin Eclipsite itu sudah punya persiapan.",
  ui_story_7_6_21_dialog_content = "Benar. Tiba-tiba perasaanku jadi tak enak. Aku harus segera kembali.",
  ui_story_7_6_22_dialog_content = "Kami ikut! Ayo, PlayerName!",
  ui_story_7_6_23_dialog_content = "Musuh yang mampu menembus masuk ke Uptown pasti punya kekuatan mengerikan. Kuhargai niat kalian untuk ikut denganku.",
  ui_story_7_6_24_dialog_content = "Kami paham! Commander, kami baru saja menerima kabar bahwa Uptown diserang suatu Eclipsite yang berbeda. Kita harus ke sana dan membantu pasukan pertahanan, sekarang juga!",
  ui_story_7_6_25_dialog_content = "Kami menuju ke sana!",
  ui_story_7_6_26_dialog_content = "Aku hampir sampai.",
  ui_story_7_6_27_dialog_content = "Legion Commander itu memang luar biasa!",
  ui_story_7_7_1_dialog_content = "Maaf, aku terlambat!",
  ui_story_7_7_2_dialog_content = "Kapten! Akhirnya kau kembali. Para Eclipsite itu…",
  ui_story_7_7_3_dialog_content = "Tak usah banyak omong! Di mana musuh kita!?",
  ui_story_7_7_4_dialog_content = "Di sini! Ikuti aku!",
  ui_story_7_7_5_dialog_content = "<size=45>Woogagagagaga!!!</size>",
  ui_story_7_7_6_dialog_content = "Terus maju! Jangan biarkan dia maju lebih jauh! Uptown sudah di depan sana!",
  ui_story_7_7_7_dialog_content = "Wooga!!!",
  ui_story_7_7_8_dialog_content = "Sialan! Pertahanannya ditembus! Satukan pasukan! Jangan sampai mereka mendekati kota!",
  ui_story_7_7_9_dialog_content = "Ah! Carleen!",
  ui_story_7_7_10_dialog_content = "Kalian sedang apa, sih? Jangan cuma berdiri di sana menonton kerusuhan ini. Ini pusat Lumopolis!",
  ui_story_7_7_11_dialog_content = "Tapi perintah dari City Lord kepada kami sudah jelas. <color=#FFB400>Kami hanya diperintahkan melindungi Uptown</color>…",
  ui_story_7_7_12_dialog_content = "Bisa dibilang, monster besar itu 'kan belum berhasil menerobos masuk, jadi kami belum bisa keluar sekarang…",
  ui_story_7_7_13_dialog_content = "Logika macam apa itu!?",
  ui_story_7_7_15_dialog_content = "Carleen, kalau Guardians tak bisa menyerang, kita masih bisa mengandalkan bantuan dari Illumina! Kedua Officer ini mestinya mampu mengatasinya!",
  ui_story_7_7_16_dialog_content = "Lagi-lagi kita harus membereskan kekacauan yang ditimbulkan Guardians?",
  ui_story_7_7_17_dialog_content = "Commander! Guardians harus mematuhi perintah yang diberikan kepada mereka… Mereka tak bisa meninggalkan Uptown untuk menghadapi musuh, jadi kita saja yang urus!",
  ui_story_7_7_18_dialog_content = "Setiap kali terpaksa bekerja sama dengan Lumopolis, mau tak mau aku jadi ingat arti sebenarnya dari birokrasi.",
  ui_story_7_7_19_dialog_content = "Baiklah kalau begitu, Sharona. Bukan saatnya mengeluh. Para prajurit itu tak bisa bertahan lebih lama lagi.",
  ui_story_7_7_21_dialog_content = "Bawa kemari jerat dan traktornya! Hancurkan makhluk itu sampai tercerai-berai!",
  ui_story_7_7_22_dialog_content = "Tercerai-berai!?",
  ui_story_7_7_23_dialog_content = "…?",
  ui_story_7_7_24_dialog_content = "Belajar dari pengalaman, mayat makhluk itu akan lebih mudah dibuang kalau dicabik-cabik dulu! Fokus pada pertarungannya saja, anak-anak!",
  ui_story_7_7_25_dialog_content = "Baik! Beri tahu kami apa yang harus kami lakukan, Madam…",
  ui_story_7_7_26_dialog_content = "Pertama, kita kalahkan dulu makhluk busuk ini! Vivian, ingat, potong pada saat yang tepat, persis seperti dulu!",
  ui_story_7_7_27_dialog_content = "Aku paham, persis seperti dulu!",
  ui_story_7_7_28_dialog_content = "Akan kubuat jalan menembusnya! Kalian semua, minggir! Jangan sampai terbunuh! Nah, untuk <color=#FFB400>Commander</color> kita…",
  ui_story_7_7_29_dialog_content = "Aku bisa menanganinya! Tak mungkin aku kalah!",
  ui_story_7_7_30_dialog_content = "<color=#FFB400>Pastikan dia jatuh di luar Uptown</color>!",
  ui_story_7_7_31_dialog_content = "<anim type=Shake><size=45>Aahhhhhhhh!</size></anim>",
  ui_story_7_7_32_dialog_content = "Vivian, sekarang!",
  ui_story_7_7_33_dialog_content = "Nih! Radium Rapier!",
  ui_story_7_7_34_dialog_content = "Blood for Blood!",
  ui_story_7_7_36_dialog_content = "Dia tumbang! Akhirnya!",
  ui_story_7_7_37_dialog_content = "Kita berhasil melumpuhkan ancamannya! Dalam situasi genting, ternyata kalian bisa jadi sangat berguna!",
  ui_story_7_7_38_dialog_content = "…",
  ui_story_7_7_39_dialog_content = "Aku merasa tersanjung, Madam.",
  ui_story_7_7_40_dialog_content = "Madam, Colossus hitam itu masih saja menyerang dan tak menunjukkan tanda-tanda akan berhenti!",
  ui_story_7_7_41_dialog_content = "Schummer…",
  ui_story_7_7_42_dialog_content = "Masih saja keras kepala. Memangnya apa yang didapatkannya dengan terus bertarung?",
  ui_story_7_7_43_dialog_content = "Ini sudah melampaui kemampuannya. Para Eclipsite ini bahkan tak sanggup menjamah Uptown sedikit pun.",
  ui_story_7_7_44_dialog_content = "Bisa jadi mereka memang bodoh.",
  ui_story_7_7_45_dialog_content = "Apa ancaman yang membahayakan Uptown sudah berhasil disingkirkan? Kalau sudah tak ada lagi yang harus dilakukan di sini, aku akan pergi duluan.",
  ui_story_7_7_46_dialog_content = "1st Legion masih harus mempertahankan sisi timur… Ehem, semuanya berkat upaya Guardians.",
  ui_story_7_7_47_dialog_content = "Oh, ya, terima kasih atas bantuan kalian, Illumina.",
  ui_story_7_7_48_dialog_content = "Jangan berterima kasih padaku. Berterima kasihlah pada PlayerName dan Vice.",
  ui_story_7_7_A2_dialog_content = "Tak semua orang bisa sabar saat bekerja sama dengan Lumopolis, apalagi menjaga baris belakang tanpa bantuan.",
  ui_story_7_7_49_dialog_content = "…",
  ui_story_7_7_50_dialog_content = "Ambigu, ya. Sharona memang kadang-kadang begitu. Tak usah terlalu dipikirkan, Carleen.",
  ui_story_7_7_51_dialog_content = "Krisis sudah teratasi. Ini hasil terbaik dan paling penting untuk sekarang.",
  ui_story_7_7_52_dialog_content = "Schummer berniat menyerang Lumopolis secara frontal tanpa menyadari bahwa kita punya pertahanan yang nyaris tak bisa ditembus.",
  ui_story_7_7_53_dialog_content = "Apa yang akan dilakukannya setelah ini? Black Colossus hitam yang barusan itu, apa dayanya sudah terisi penuh?",
  ui_story_7_7_X1_dialog_content = "Dia sudah berhasil mencuri ketiga modulnya, tapi Black Colossus itu kelihatannya tak terlalu kuat.",
  ui_story_7_7_54_dialog_content = "Menurut dugaanku, kekuatan Schummer belum maksimal. Serangan ini jelas membuktikan bahwa dia meremehkan kita.",
  ui_story_7_7_55_dialog_content = "Dari apa yang kauketahui tentang dia, apa kira-kira dia akan membalas membabi buta atas apa yang terjadi di sini hari ini?",
  ui_story_7_7_56_dialog_content = "Aku punya firasat akan terjadi sesuatu yang mengerikan.",
  ui_story_7_7_57_dialog_content = "Tolong jangan bilang begitu, Madam. Biasanya kau benar tentang hal-hal seperti itu.",
  ui_story_7_7_58_option_content = "Kita harus mulai duluan.",
  ui_story_7_7_59_option_content = [[
Sebaiknya kita tunggu saja 
dan lihat apa yang terjadi setelah ini.]],
  ui_story_7_7_60_dialog_content = "Aku setuju. Saat ini, kita harus memanfaatkan keunggulan kita dan memanfaatkan peluang sebaik mungkin!",
  ui_story_7_7_61_dialog_content = "Benar. Selama ini kita hanya menerima apa pun yang dilontarkannya kepada kita. Sekarang giliran kita menyerang!",
  ui_story_7_7_62_dialog_content = "Kau benar, PlayerName. Kita harus tetap tenang sampai kita punya informasi lebih banyak.",
  ui_story_7_7_63_dialog_content = "Kemungkinan besar, Schummer-lah yang akan lebih tak sabar.",
  ui_story_7_7_A3_dialog_content = "Dia memang sudah menguasai ketiga modul itu, tapi sekarang dia terjebak jalan buntu. Kita tunggu saja sampai dia melakukan kesalahan!",
  ui_story_7_7_64_dialog_content = "Aduh…!",
  ui_story_7_7_65_dialog_content = "PlayerName? Ada apa?",
  ui_story_7_7_66_dialog_content = "(Pikiranku… Rasa sakit yang menusuk ini apa!?)",
  ui_story_7_7_67_dialog_content = "…",
  ui_story_7_7_68_dialog_content = "Soroz!",
  ui_story_7_7_69_dialog_content = "Diserang! Musuh… Dia menerobos ke… Lebih dari satu musuh… Ada lagi…",
  ui_story_7_7_X2_dialog_content = "Aku tak bisa mendengarmu! Soroz, apa kau masih di koordinatmu? Kami akan ke sana untuk membantumu sekarang juga!",
  ui_story_7_7_X3_dialog_content = "Dekat! Tolong… Musuh berhasil menerobos… dan dia tak sendirian!",
  ui_story_7_7_A4_dialog_content = "<color=#FFB400>Kembali</color>… <color=#FFB400>Kembali</color>!",
  ui_story_7_7_X4_dialog_content = "Soroz diterobos! Schummer mengubah targetnya!",
  ui_story_7_7_X5_dialog_content = "?!",
  ui_story_7_7_X6_dialog_content = "Karena tak berhasil masuk ke Lumopolis, lalu dia memutuskan menyerang kita?",
  ui_story_7_7_70_dialog_content = "Kembali untuk minta bantuan darurat. Kali ini aku tak membawa pesawat. Apa kita bisa minta satu pesawat dari Lumopolis, Carleen?",
  ui_story_7_7_71_dialog_content = "Anu…",
  ui_story_7_7_72_dialog_content = "Kapten, City Lord memberikan perintah baru. Kau harus kembali ke Uptown.",
  ui_story_7_7_73_dialog_content = "Sebentar. Ini darurat. Aku harus membantu mereka dulu…",
  ui_story_7_7_74_dialog_content = "Maaf, tapi ini bukan permintaan. Kalau kau tak kembali, aku khawatir Four Angels akan dikerahkan.",
  ui_story_7_7_75_dialog_content = "Apa? Aku di sini cuma menonton. Kenapa tiba-tiba aku ikut terseret dalam masalah ini?",
  ui_story_7_7_76_dialog_content = "…",
  ui_story_7_7_77_dialog_content = "Carleen, sepertinya ayahmu punya rencana. Kau harus kembali.",
  ui_story_7_7_78_dialog_content = "Jangan khawatir, sekarang Soroz adalah bagian dari Illumina. Kami akan menanganinya sendiri.",
  ui_story_7_7_79_dialog_content = "Tunggu, memangnya sejak kapan aku jadi bagian dari Illumina?",
  ui_story_7_7_80_dialog_content = "…",
  ui_story_7_7_81_dialog_content = "…",
  ui_story_7_7_82_dialog_content = "Kok aku merasa sepertinya aku dipaksa menerimanya saja padahal belum sempurna? Berapa lama lagi Colossus milikku akan selesai?",
  ui_story_7_7_83_dialog_content = "Sebentar lagi. Tapi, waktu kita sudah hampir habis, dan kesabaranku pun menipis, Schummer.",
  ui_story_7_7_85_dialog_content = "Tentu saja. Aku hanya ingin menuntaskan tugas yang gagal kuselesaikan di Whispering Corridor.",
  ui_story_7_7_86_dialog_content = "PlayerName sangat istimewa. Ini pertama kalinya aku memutuskan untuk tak menghabisi Caelestite.",
  ui_story_7_7_87_dialog_content = "Si Caelestite itu akan datang, aku bisa merasakannya. Anggap saja ini rasa tanggung jawab atas tugas atau kebodohan dari moralitas yang kuat.",
  ui_story_7_7_A5_dialog_content = "Gambaran-gambaran ideal yang sudah kuno itu akan menggiring PlayerName kembali kemari.",
  ui_story_7_7_89_dialog_content = "Kalau begitu, tunggu apa lagi? Sudah berapa banyak anak buahku yang mati akibat omong kosongmu itu? Perlu kuulangi lagi!?",
  ui_story_7_7_90_dialog_content = "<color=#FFB400>Bunuh saja dia</color>, Schummer.",
  ui_story_7_7_91_dialog_content = "Soroz, kawan lamaku…",
  ui_story_7_7_92_dialog_content = "<size=45>Ini mungkin akan terasa agak sakit!</size>",
  ui_story_7_8_1_dialog_content = "Kau bisa mendengarku, Soroz?",
  ui_story_7_8_2_option_content = "Coba bangun telepati.",
  ui_story_7_8_3_dialog_content = "Soroz… Soroz…",
  ui_story_7_8_4_option_content = "Coba bangun telepati.",
  ui_story_7_8_5_dialog_content = "Tidak berhasil. Aku masih tak merasakan apa pun! Lagi pula, pengaruh dari perisai itu…",
  ui_story_7_8_6_dialog_content = "Kita harus ke sana sesegera mungkin!",
  ui_story_7_8_7_dialog_content = "Aku tak punya wewenang untuk menggunakan pesawat Lumopolis tanpa izin dari Guardians.",
  ui_story_7_8_8_dialog_content = "Aku khawatir akan butuh waktu lama untuk minta pesawat dari benteng Illumina terdekat.",
  ui_story_7_8_9_dialog_content = "Tapi, Carleen juga tak bisa berbuat apa-apa soal itu…",
  ui_story_7_8_11_dialog_content = "Sebagai putri City Lord dan Kapten di Lumopolis Guardians, dia sudah berbuat banyak untuk kita.",
  ui_story_7_8_12_dialog_content = "Benar. Kalau dia membangkang lagi dan membawa pesawat untuk kita tanpa izin… Itu akan dianggap kelewatan.",
  ui_story_7_8_13_dialog_content = "Aduh, lagi-lagi Vivian menggunakan kemampuan meramalnya…",
  ui_story_7_8_14_dialog_content = "Lihat!",
  ui_story_7_8_15_dialog_content = "Maaf menyela. Sebuah pesawat baru saja lepas landas di sana!",
  ui_story_7_8_16_dialog_content = "Siapa pilotnya? Pesawat itu berbelok-belok ke sana kemari. Tunggu, apa pesawatnya langsung menuju arah kita?",
  ui_story_7_8_17_dialog_content = "…?",
  ui_story_7_8_18_dialog_content = "Hah?",
  ui_story_7_8_19_dialog_content = "Tak mungkin, Carleen!",
  ui_story_7_8_20_dialog_content = "Cepat naik! Aku sudah <color=#FFB400>menyita</color> pesawat ini!",
  ui_story_7_8_21_dialog_content = "Menyita? Bukannya kau ini Kapten di Guardians!?",
  ui_story_7_8_22_dialog_content = "Kujelaskan nanti saja! Bukannya kau ingin kembali ke lokasi Soroz? Mau ikut atau tidak?",
  ui_story_7_8_23_dialog_content = "Baiklah, sekarang kita bisa kembali ke sana!",
  ui_story_7_8_24_dialog_content = "Maaf, PlayerName, aku terlambat.",
  ui_story_7_8_25_option_content = "Tidak, kau sudah berbuat sangat banyak untuk kami.",
  ui_story_7_8_26_option_content = [[
Tak apa. Aku tak menyangka
kau bisa mengemudikan pesawat.]],
  ui_story_7_8_27_dialog_content = "Yah, aku hanya ingin melindungi Lumopolis…",
  ui_story_7_8_28_dialog_content = "Tapi, sekarang ada hal lain yang ingin kulindungi juga.",
  ui_story_7_8_29_dialog_content = "Yah, sepertinya ada orang yang pikirannya tepat.",
  ui_story_7_8_30_dialog_content = "Ayo cepat, Soroz menunggu kita!",
  ui_story_7_8_31_dialog_content = "Aku tak pernah takut dengan kematian, sama seperti <color=#FFB400>waktu itu</color>, waktu kau juga tak bisa membuatku takut.",
  ui_story_7_8_32_dialog_content = "Kau bisa mengabaikan prinsip cahaya dan berlindung dalam bayangan kegelapan…",
  ui_story_7_8_A1_dialog_content = "Tapi, pada akhirnya, takdir kita sudah digariskan untuk Aurora.",
  ui_story_7_8_33_dialog_content = "Schummer, kau bisa menghancurkan kesadaranku, tapi kau tak akan pernah bisa mengalahkan PlayerName!",
  ui_story_7_9_1_dialog_content = "Persis seperti dugaan kita, Schummer akhirnya menyerang Soroz!",
  ui_story_7_9_2_dialog_content = "Para Eclipsite itu merajalela di sini. Aku bisa mencium aroma Darkflow di udara.",
  ui_story_7_9_3_dialog_content = "Apa yang sudah mereka lakukan pada Soroz?!",
  ui_story_7_9_4_dialog_content = "Ada monster di arah jam sembilan. Makhluk busuk itu berhasil menemukan kita…",
  ui_story_7_9_5_dialog_content = "Ayo kita hadapi mereka!",
  ui_story_7_9_6_dialog_content = "Baguslah, kita tak terlalu banyak menimbulkan keributan, jadi musuh belum sadar akan keberadaan kita.",
  ui_story_7_9_7_dialog_content = "Tapi, kita bisa bunuh saja mereka secepat mungkin sebelum Schummer sempat bereaksi.",
  ui_story_7_9_8_dialog_content = "Kurasa itu tak mungkin…",
  ui_story_7_9_9_dialog_content = "Kau tak harus mengambil risiko demi kami, Carleen.",
  ui_story_7_9_10_dialog_content = "Kita ini teman. Begitu, 'kan, katamu?",
  ui_story_7_9_11_dialog_content = "Lagi pula, kalau aku tak membelah musuh tangguh dengan tombakku, mana bisa aku tidur tenang nanti malam?",
  ui_story_7_9_12_option_content = "Saya tidak akan mengharapkan sesuatu yang kurang dari Anda, Carleen.",
  ui_story_7_9_13_option_content = "Ya, kita ini teman.",
  ui_story_7_9_14_dialog_content = "Maksudmu?",
  ui_story_7_9_15_dialog_content = "Kurasa maksud PlayerName adalah memang sudah semestinya Kapten dari Lumopolis Guardians bertindak begini.",
  ui_story_7_9_A1_dialog_content = "Ini tentang tanggung jawab dan keberanian.",
  ui_story_7_9_16_dialog_content = "Sesukamu sajalah, tapi berdiri di sini dan memujiku tak akan mengubah situasi kita saat ini.",
  ui_story_7_9_17_dialog_content = "Lagi pula, kalaupun kau tak bilang begitu, aku akan tetap bertarung bersama kalian. Karena kita ini <color=#FFB400>teman</color>.",
  ui_story_7_9_18_dialog_content = "Semua orang bilang Lumopolis selalu bersikap masa bodoh, tapi kurasa kau berbeda.",
  ui_story_7_9_19_dialog_content = "Dan itu memang selalu membuatku bingung. Harusnya aku bertindak demi Lumopolis, atau demi diriku sendiri?",
  ui_story_7_9_20_dialog_content = "Nah, melihat tindakanmu ini, sepertinya kau sudah menemukan jawabannya.",
  ui_story_7_9_21_dialog_content = "Mungkin saja.",
  ui_story_7_9_22_dialog_content = "Aku tahu kita ini teman. Apa perlu kauulang-ulang lagi?",
  ui_story_7_9_23_dialog_content = "Kan kau sendiri yang minta. Sudahlah, sekarang ada musuh kuat yang harus kita hajar.",
  ui_story_7_9_24_dialog_content = "Apa kau tahu apa yang akan kita hadapi, Carleen? Kita memang mati-matian berhasil selamat dari beberapa pertarungan terakhir, tapi…",
  ui_story_7_9_25_dialog_content = "Kurasa pertarungan terburuknya masih jauh.",
  ui_story_7_9_26_dialog_content = "Jangan bilang begitu, Madam.",
  ui_story_7_9_27_dialog_content = "Seberapa pun kuatnya Schummer, kita semua punya alasan untuk mengalahkannya, 'kan?",
  ui_story_7_9_28_dialog_content = "Walau terdengar klise kalau kubilang aku ingin <color=#FFB400>melindungi hal-hal yang paling kusayangi</color>…",
  ui_story_7_9_A2_dialog_content = "Pada akhirnya, bukankah kita bertarung bersama memang untuk melindungi orang-orang dan hal-hal yang berharga bagi kita?",
  ui_story_7_9_29_dialog_content = "Benar, misalnya Soroz.",
  ui_story_7_9_30_dialog_content = "Benar, Soroz.",
  ui_story_7_9_31_dialog_content = "PlayerName, apa kau bisa merasakan keberadaan Soroz? Sebaiknya kita cari tahu apakah…",
  ui_story_7_9_32_dialog_content = "Aku tak bisa merasakannya, tapi aku yakin dia masih hidup.",
  ui_story_7_9_33_dialog_content = "Aku belum pernah punya kesempatan untuk berkomunikasi dengan Colossus. Aku agak penasaran seperti apa rasanya.",
  ui_story_7_9_A3_dialog_content = "Oh, maaf, aku tak bermaksud menyinggungmu.",
  ui_story_7_9_34_dialog_content = "Tapi, Madam, apa yang kaulakukan di sini?",
  ui_story_7_9_35_dialog_content = "Sama seperti Carleen, aku sudah muak menghadapi si Schummer itu, dan aku juga ingin menghajarnya.",
  ui_story_7_9_36_dialog_content = "Baiklah, ayo terus bergerak. Di mana Schummer, PlayerName?",
  ui_story_7_9_37_dialog_content = "Aku merasakan aura dinginnya di <color=#FFB400>Bridge</color>!",
  ui_story_7_9_A4_dialog_content = "Aku khawatir kita akan dihadang banyak Eclipsite. Apa kalian semua sudah siap?",
  ui_story_7_9_A5_dialog_content = "Tentu saja! Tombakku selalu siap beraksi!",
  ui_story_7_12_1_dialog_content = "PlayerName, aku tak tahu apakah kau bisa menerima pesan ini…",
  ui_story_7_12_2_dialog_content = "Aku merasa terhormat bisa melayanimu selama ini. Aku senang bisa melindungimu tujuh belas tahun lalu dan menanamkan benih harapan di dunia ini.",
  ui_story_7_12_3_dialog_content = "Kalau kau tak keberatan, kuminta <color=#FFB400>jangan kembali untukku</color>. Kuulangi, <color=#FFB400>jangan kembali untukku</color>.",
  ui_story_7_12_A1_dialog_content = "Musuh ini jauh lebih kuat dari yang kaukira.",
  ui_story_7_12_4_dialog_content = "Kuatlah, PlayerName. Jangan buang waktu dengan bersedih untukku.",
  ui_story_7_12_5_dialog_content = "Aku, si Colossus ini, <color=#FFB400>memang dibuat untuk melayanimu</color>.",
  ui_story_7_13_1_dialog_content = "<size=45>Aduh!</size>",
  ui_story_7_13_2_dialog_content = "(Jantungku berdebar <color=#FFB400>tak terkendali</color>!)",
  ui_story_7_13_3_dialog_content = "Itu Bridge-nya! Waspadai monster!",
  ui_story_7_13_4_dialog_content = "Apa kau masih belum bisa menghubungi Soroz?",
  ui_story_7_13_5_dialog_content = "Sedang kuusahakan. Sepertinya aku bisa dengar sesuatu. Sepertinya kata-kata yang sama, diulang-ulang.",
  ui_story_7_13_6_dialog_content = "Tapi, sekarang aku tak bisa mendengarnya lagi. Mungkin itu…",
  ui_story_7_13_7_dialog_content = "(Lagi-lagi jantungku berdebar tak terkendali!?)",
  ui_story_7_13_8_dialog_content = "Kenapa, PlayerName?",
  ui_story_7_13_9_dialog_content = "Apa Darkflow di sini terlalu kuat untuk PlayerName?",
  ui_story_7_13_10_dialog_content = "Atau mungkin kau merasakan sesuatu?",
  ui_story_7_13_11_dialog_content = "Sungguh? Apa itu Soroz?",
  ui_story_7_13_12_dialog_content = "Bukan, bukan Soroz. Aku pun merasakannya. Memangnya kau tak merasa <color=#FFB400>udaranya tiba-tiba jadi dingin</color>?",
  ui_story_7_13_13_dialog_content = "Perasaan aneh tapi familier ini pasti berasal dari si bedebah arogan dan menjijikkan itu.",
  ui_story_7_13_14_dialog_content = "…?!",
  ui_story_7_13_15_dialog_content = "*Huahh*",
  ui_story_7_13_16_dialog_content = "<size=45><color=#FFB400>Schummer</color>—!</size>",
  ui_story_7_13_17_dialog_content = "PlayerName! Kau bisa merasakan keberadaan Schummer? Di mana dia?",
  ui_story_7_13_18_dialog_content = "Apa yang sudah kaulakukan pada Soroz, Schummer? Aduh…!",
  ui_story_7_13_19_dialog_content = "Masih saja menjengkelkan. Rupanya kau belum belajar, PlayerName.",
  ui_story_7_13_20_dialog_content = "Memangnya apa lagi yang bisa kulakukan pada Soroz? Aku hanya menghancurkan Echo Template-nya.",
  ui_story_7_13_21_dialog_content = "Echo Template? Kau menghancurkan kesadaran Soroz?",
  ui_story_7_13_22_dialog_content = "Yap. Memangnya kau tak merasakannya? Hatimu terasa seperti tercebur ke dalam kegelapan dan kehabisan napas hidup, rasa sakit tak terperi menusuk-nusuk jiwamu?",
  ui_story_7_13_23_dialog_content = "Schummer!",
  ui_story_7_13_24_dialog_content = "Kalau kau masih belum paham, biar kujelaskan: Soroz sudah <color=#FFB400>mati</color>.",
  ui_story_7_14_1_dialog_content = "Kita kehilangan jejak mereka?",
  ui_story_7_14_2_dialog_content = "Maaf! Carleen berlari begitu cepat sampai-sampai aku tak bisa mengejarnya, dan dalam sekejap saja dia sudah hilang…",
  ui_story_7_14_3_dialog_content = "Tadi aku sedang patroli di atas. Yang kulihat hanyalah Black Colossus seram dan sebuah Colossus putih kecil!",
  ui_story_7_14_4_dialog_content = "Colossus putih… Pasti itu PlayerName. Anak-anak itu sudah keluar untuk bermain.",
  ui_story_7_14_5_dialog_content = "Apa sudah ada pergerakan dari Black Colossus itu?",
  ui_story_7_14_6_dialog_content = "Tidak, dia masih terus menyerang perisai. Para Eclipsite juga masih menyerang dengan kekuatan penuh.",
  ui_story_7_14_7_dialog_content = "Pertahankan perisainya, dan prioritaskan cadangan Lumina kita untuk memulihkan daya di distrik bangsawan dan infrastruktur.",
  ui_story_7_14_A1_dialog_content = "Lalu, kerahkan pasukan untuk membantu Lower Lumopolis.",
  ui_story_7_14_9_dialog_content = "Bagaimana dengan Carleen?",
  ui_story_7_14_10_dialog_content = "Dia sudah memilih, jadi dia sudah siap menerima konsekuensinya.",
  ui_story_7_14_11_dialog_content = "Menurutku, tak ada alasan untuk mengerahkan Guardians untuk membantu upayanya yang tak masuk akal itu.",
  ui_story_7_14_12_dialog_content = "Ya.",
  ui_story_7_14_13_dialog_content = "Tapi, bagaimana dia bisa mendapatkan pesawat itu? Itu melanggar protokol.",
  ui_story_7_14_14_dialog_content = "Kalau sampai ada Guardians lain yang meninggalkan Lumopolis <color=#FFB400>untuk membantunya</color>…",
  ui_story_7_14_15_dialog_content = "Kenapa kau menatapku begitu?",
  ui_story_7_14_16_dialog_content = "Ada pertanyaan lagi?",
  ui_story_7_14_17_dialog_content = "Oh, anu, yah, aku paham!",
  ui_story_7_14_18_dialog_content = "Aku akan pergi sekarang. Oh, maksudku, aku minta izin untuk pergi!",
  ui_story_7_14_19_dialog_content = "Lebih cepat, dasar tikus. Sepertinya kalian bisa saja tersesat di rumah kalian sendiri!",
  ui_story_7_14_20_dialog_content = "Diam kau, Eclipsite. Kalau kau punya pesan terakhir, katakan sekarang!",
  ui_story_7_14_21_dialog_content = "Sepertinya kau salah paham, Putri. Sekarang aku sudah memiliki kekuatan dari <color=#FFB400>semua modul</color>.",
  ui_story_7_14_X1_dialog_content = "Kecuali kau mau ikut PlayerName ke neraka, lebih baik kau lari pulang saja ke Lumopolis sambil menanggung malu!",
  ui_story_7_14_22_dialog_content = "Kau tak bisa menembus perisai Lumopolis, 'kan? Kaukira kami akan percaya bahwa kekuatanmu sudah maksimal?",
  ui_story_7_14_23_dialog_content = "Hush, Caelestite. Kekuatan Black Colossus belum terisi penuh.",
  ui_story_7_14_A2_dialog_content = "Tapi, saat saatnya tiba, akan kusiapkan kursi paling depan untuk kalian semua.",
  ui_story_7_14_X2_dialog_content = "(Persis seperti dugaan kami, augmentasinya belum selesai!)",
  ui_story_7_14_X3_dialog_content = "Jangan menatapku seperti itu, PlayerName.",
  ui_story_7_14_24_dialog_content = "Aku terpaksa turun tangan sendiri dan menghadapimu sambil menyerang Lumopolis. Kau benar-benar menguji kesabaranku.",
  ui_story_7_14_25_dialog_content = "Vice dan PlayerName, beri tahu aku, apa Eclipsite ini benar-benar sekuat itu?",
  ui_story_7_14_26_dialog_content = "Dia memang tampak sulit ditangani, tapi kalau kita bahu-membahu, pasti kita bisa menang, 'kan?",
  ui_story_7_14_27_dialog_content = "Akan lebih mudah kalau Commander Sharona juga bersama kita…",
  ui_story_7_14_28_dialog_content = "Mimpi saja sana. Kalaupun kalian mengerahkan semua teman kalian, tetap saja kalian tak akan bisa menandinginya.",
  ui_story_7_14_A3_dialog_content = "Colossus milikku makin kuat seiring waktu…",
  ui_story_7_14_29_dialog_content = "Walau begitu, harus kuakui, optimisme kalian memang patut dikagumi. Apa semua orang di Illumina memang begitu percaya diri tanpa dasar?",
  ui_story_7_14_30_dialog_content = "Cepatlah, Schummer, tak usah banyak omong.",
  ui_story_7_14_31_dialog_content = "Aku tahu, diamlah.",
  ui_story_7_14_32_dialog_content = "…",
  ui_story_7_14_33_dialog_content = "Ada apa, Madam?",
  ui_story_7_14_34_dialog_content = "Orang yang mengendalikan Schummer itu sepertinya <color=#FFB400>sangat familier</color>.",
  ui_story_7_14_38_dialog_content = "Hoi, kalian bisik-bisik apa? Walaupun kalian menyerukan kata-kata terakhir kalian keras-keras, tak seorang pun akan mendengarnya.",
  ui_story_7_14_39_dialog_content = "Tapi, kau memang istimewa.",
  ui_story_7_14_A4_dialog_content = "Aku tahu kau tak mau terus-menerus jadi orang lemah, selamanya meringkuk di balik bayangan orang yang kuat. Kau sama saja denganku.",
  ui_story_7_14_40_dialog_content = "Sini, bergabunglah dengan kami. Pilihlah jalan yang tepat.",
  ui_story_7_14_41_dialog_content = "Ini satu-satunya cara kau bisa mendapatkan kekuatan untuk mengubah nasibmu.",
  ui_story_7_14_42_dialog_content = "Kekuatan untuk mengubah nasibku? Apa maksudmu?",
  ui_story_7_14_43_dialog_content = "Penglihatan, umur panjang, pengetahuan, Darkflow luar biasa kuat, kebenaran tentang dunia ini.",
  ui_story_7_14_44_dialog_content = "Yang paling penting, kau tak perlu lagi khawatir akan kalah. Kau hanya perlu memikirkan siapa yang ingin kaukalahkan. Kau akan jadi sangat hebat.",
  ui_story_7_14_46_dialog_content = "Langsung saja ke intinya, aku sedang buru-buru.",
  ui_story_7_14_47_dialog_content = "Apa-apaan kau!",
  ui_story_7_14_48_dialog_content = "Maaf, aku tak tertarik dengan omonganmu.",
  ui_story_7_14_49_dialog_content = "Kau suka mengoceh dan bahkan tak tahu apa yang kaubicarakan. Memangnya kau tahu arti semua ini?",
  ui_story_7_14_50_dialog_content = "Kebenaran dunia ini. Kekuatan untuk mengubah nasib. Tak perlu khawatir akan kalah.",
  ui_story_7_14_51_dialog_content = "Itu sebabnya di dunia ini tak ada tempat untuk orang-orang yang membahayakan nyawa orang lain.",
  ui_story_7_14_52_dialog_content = "Kaupikir kau harus membasmi semua orang yang lebih lemah darimu, dan kau harus berlutut dan memohon ampun dan menyerah pada kekuatan yang lebih besar saat kau bertemu dengan orang yang lebih kuat darimu?",
  ui_story_7_14_A5_dialog_content = "Aku tak paham bagaimana kau bisa begitu yakin akan hal itu. Kaukira aku ingin jadi sepertimu?",
  ui_story_7_14_53_dialog_content = "Apa kau membual bahwa kau ini benar dan tak pernah salah?",
  ui_story_7_14_54_dialog_content = "Kau harus memeriksakan otakmu pada dokter. Orang waras tak mungkin sebegitu buta sampai tak mampu melihat kebenaran.",
  ui_story_7_14_55_dialog_content = "…",
  ui_story_7_14_56_dialog_content = "Dari mana kaudapat kata-kata itu, PlayerName?",
  ui_story_7_14_57_dialog_content = "Bagus sekali…?",
  ui_story_7_14_F1_dialog_content = "Oh, ya. Aku juga ingin tanya, berapa lama kau harus berlutut agar bisa mendapatkan kekuatanmu itu?",
  ui_story_7_14_58_dialog_content = "Lucu.",
  ui_story_7_14_59_dialog_content = "<size=50>Lucu sekali!</size>",
  ui_story_7_14_60_dialog_content = "Dasar bedebah tak berguna! Idiot! Buta total!",
  ui_story_7_14_61_dialog_content = "Kau berusaha membuatku jengkel, ya? Kau cari mati?",
  ui_story_7_14_63_dialog_content = "Oh, sekarang kau jadi serius, nih?",
  ui_story_7_14_A6_dialog_content = "Amarah bisa membuatmu lebih cepat memperoleh kekuatan yang lebih besar.",
  ui_story_7_14_64_dialog_content = "Akan kubiarkan kau hidup, dan akan kusiksa kau pelan-pelan! Akan kubuat kau merasa hina dan putus asa!",
  ui_story_7_14_F2_dialog_content = "Kalau begitu, kau akan tahu bahwa aku benar!",
  ui_story_7_14_65_dialog_content = "Tidak, harusnya aku yang bilang begitu kepadamu, <color=#FFB400>Schummer, pengkhianat kaum Caelestite</color>!",
  ui_story_7_14_66_dialog_content = "Ayo! Kalian tunggu apa lagi!?",
  ui_story_7_14_67_dialog_content = "Dia terlalu… terlalu kuat… Kekuatannya…",
  ui_story_7_14_68_dialog_content = "Aku masih bisa bergerak. Bersiaplah untuk menyerang lagi! Jangan sampai dia pergi…",
  ui_story_7_14_69_dialog_content = "Jangan gegabah! Kita harus cari cara.",
  ui_story_7_14_70_dialog_content = "Aku tak suka mengakuinya, tapi PlayerName memang benar…",
  ui_story_7_14_A7_dialog_content = "Untunglah kita tak mengajak orang lain bersama kita. Kalau tidak, kita semua justru akan terperangkap di sini.",
  ui_story_7_14_71_dialog_content = "Dalam situasi seperti ini, kita bahkan tak bisa mundur.",
  ui_story_7_14_72_dialog_content = "Mundur? Kalian mau pergi? Baiklah, kalian boleh pergi setelah aku mencabik-cabik kalian dan membuat kalian berhamburan dibawa angin!",
  ui_story_7_14_73_dialog_content = "Darah kalian akan menghujani langit Lumopolis!",
  ui_story_7_14_74_dialog_content = "Dayanya sudah terisi, Schummer. Kekuatan Black Colossus sekarang sudah <color=#FFB400>penuh</color>.",
  ui_story_7_14_75_dialog_content = "Waktunya pas sekali, 'kan? Makhluk-makhluk rendahan di hadapan kita ini bisa jadi korban untuk merayakan kelahiran baru ini!",
  ui_story_7_14_76_dialog_content = "Maaf menyela, tapi aku ingin bertanya… Sebenarnya kau ini siapa?",
  ui_story_7_14_77_dialog_content = "Kau masih belum tahu?",
  ui_story_7_14_78_dialog_content = "Bukan kau. Maksudku orang di belakangmu itu. Eclipsite Level Tinggi yang kuat itu.",
  ui_story_7_14_79_dialog_content = "…",
  ui_story_7_14_80_dialog_content = "Tidak, kau tampak lebih menyerupai <color=#FFB400>Aurorian</color> daripada Eclipsite.",
  ui_story_7_14_81_dialog_content = "Aurorian?",
  ui_story_7_14_82_dialog_content = "Bentuk tubuhnya, auranya, cara bicaranya… Firasatku mengatakan kau bukan Eclipsite sejak lahir.",
  ui_story_7_14_83_dialog_content = "Firasat… Sungguh argumen tak berdasar.",
  ui_story_7_14_84_dialog_content = "<color=#FFB400>Siapa kau?</color>? Katakan padaku, aku harus tahu.",
  ui_story_7_14_85_dialog_content = "Aku tak mau bilang.",
  ui_story_7_14_86_dialog_content = "<size=45>Katakan padaku! Sekarang!</size>",
  ui_story_7_14_87_dialog_content = "Kenapa tiba-tiba dia jadi marah begitu?",
  ui_story_7_14_88_dialog_content = "Sekali lagi, aku tak mau. Karena…",
  ui_story_7_14_89_dialog_content = "Namaku sudah lama <color=#FFB400>dihapus</color>.",
  ui_story_7_14_90_dialog_content = "…",
  ui_story_7_14_91_dialog_content = "Di dunia yang indah ini, mana mungkin orang tak bernama bisa hidup di <color=#FFB400>Illumina</color>?",
  ui_story_7_14_92_dialog_content = "Dulu kau anggota Illumina?",
  ui_story_7_14_94_dialog_content = "Ya.",
  ui_story_7_14_95_dialog_content = "Lihat bekas luka di wajahku ini. Ini akibat kulitku dibakar dengan api. Kau bisa lihat, 'kan?",
  ui_story_7_14_97_dialog_content = "…",
  ui_story_7_14_F3_dialog_content = "Apa itu?",
  ui_story_7_14_98_dialog_content = "Ingat sesuatu?",
  ui_story_7_14_99_dialog_content = "Aku bukannya tak tahu, aku hanya memastikan.",
  ui_story_7_14_100_dialog_content = "Kau baik sekali. Setelah sekian lama, pengetahuanmu masih tetap mengesankan.",
  ui_story_7_14_101_dialog_content = "Kalian saling kenal, Vivian?",
  ui_story_7_14_102_dialog_content = "Bukan hanya kenal, PlayerName…",
  ui_story_7_14_103_dialog_content = "High-Level Eclipsite ini dulu adalah <color=#FFB400>partnerku di Illumina</color>.",
  ui_story_7_14_104_dialog_content = "Kenapa kaget begitu?",
  ui_story_7_14_A8_dialog_content = "Dan kau, <color=#FFB400>Forsakin</color>, kau selalu bilang aku terlalu banyak omong, lalu kenapa sekarang malah kau mengobrol dengan kecoa-kecoa ini?",
  ui_story_7_14_105_dialog_content = "<color=#FFB400>Forsakin</color>?",
  ui_story_7_14_109_dialog_content = "Hanya saling bertukar kabar. Aku sudah selesai. Silakan lakukan sesukamu.",
  ui_story_7_14_110_dialog_content = "Omong-omong, sementara Colossus itu masih diisi daya, sebagian besar energinya belum bisa digunakan.",
  ui_story_7_14_A9_dialog_content = "Cari target yang pantas.",
  ui_story_7_14_111_dialog_content = "Kota di sana itu sepertinya cocok, ya?",
  ui_story_7_14_112_dialog_content = "Arogan, busuk, yakin begitu saja bahwa perisai mereka tak mungkin ditembus… Akan kuhancurkan keyakinan kaum Aurorian!",
  ui_story_7_14_113_dialog_content = "Tak akan kubiarkan kau berhasil! Lumopolis tak akan pernah runtuh. Mana mungkin Eclipsite biasa bisa…",
  ui_story_7_14_114_dialog_content = "<size=45>Tutup mulutmu, Aurorian!</size>",
  ui_story_7_14_115_dialog_content = "Kemarilah, Colossus milikku sayang!",
  ui_story_7_14_116_dialog_content = "Dengan tubuh besarmu dan matamu yang semerah darah, buat mereka gemetar ketakutan!",
  ui_story_7_14_117_dialog_content = "Kalian lihat sekarang? Black Colossus… Black Dragon… Dua-duanya bukan namanya.",
  ui_story_7_14_118_dialog_content = "Ya, begitu! Berlututlah dan sembah dia! Saksikan kekuatan… <size=45><color=#FFB400>Aviduz</color></size>!",
  ui_story_7_14_119_dialog_content = "Apa itu Colossus? Apa yang sudah dilakukannya? Ada apa, PlayerName?",
  ui_story_7_14_120_dialog_content = "Mana aku tahu?",
  ui_story_7_14_121_dialog_content = "Lumina-nya terkuras! Tidak, kita tak boleh menyerah begitu saja!",
  ui_story_7_14_122_dialog_content = "Aku tak bisa bergerak. Apa kalian bisa bergerak?",
  ui_story_7_14_123_dialog_content = "Semuanya, bersiaplah. Akan kuulur waktu untuk kalian.",
  ui_story_7_14_128_dialog_content = "Titik lemahnya ada di arah jam sembilan darimu. Larilah ke sana. Langsung lompat ke bawah, mungkin kalian akan selamat.",
  ui_story_7_14_129_dialog_content = "Vice, PlayerName, Carleen, sampai jumpa lagi.",
  ui_story_7_14_130_dialog_content = "Chief? Apa kau…?",
  ui_story_7_14_131_dialog_content = "<size=50>Mustahil!</size>",
  ui_story_7_14_133_dialog_content = "(Apa…)",
  ui_story_7_14_134_dialog_content = "(Yang terjadi…)",
  ui_story_8_1_1_1_dialog_content = "Kau sedang lihat apa, PlayerName?",
  ui_story_8_1_1_2_dialog_content = "Kalau tak segera menyusul, kau bisa tersesat!",
  ui_story_8_1_1_3_dialog_content = "Sini, pegang tanganku.",
  ui_story_8_1_1_4_dialog_content = "Kenapa menatapku seperti itu? Bukannya kita sudah sepakat mau pergi ke festival Lumopolis?",
  ui_story_8_1_1_5_dialog_content = "Lihat, ada camilan! Ayo lihat mereka jual apa saja!",
  ui_story_8_1_1_6_option_content = "Kita… di mana?",
  ui_story_8_1_1_7_dialog_content = "Kau tak tahu? Kau ada di Lumopolis!",
  ui_story_8_1_1_8_option_content = "Apa yang terjadi?",
  ui_story_8_1_1_9_dialog_content = "Apa lagi? Festival ini hanya digelar sekali setahun, jadi kita harus senang-senang di sini!",
  ui_story_8_1_1_10_dialog_content = "Kau ini kenapa, sih? Kau bukan sedang menjahiliku, 'kan?",
  ui_story_8_1_1_11_dialog_content = "Kalau iya, aku akan marah padamu, seperti ini! *Cemberut*",
  ui_story_8_1_1_12_option_content = "Tingkahmu aneh, Vice.",
  ui_story_8_1_1_13_dialog_content = "Masa? Tak mungkin, aku masih Vice-mu yang mungil dan imut!",
  ui_story_8_1_1_14_dialog_content = "Jangan berpikir macam-macam. Ayo cepat, atau aku akan benar-benar marah!",
  ui_story_8_1_1_15_option_content = "Siapa kau?",
  ui_story_8_1_1_16_dialog_content = "Apa? Aku Vice! Memangnya siapa lagi?",
  ui_story_8_1_1_17_dialog_content = "Kenapa tanya-tanya begitu, sih? Ayo sini, atau aku akan benar-benar marah!",
  ui_story_8_1_1_18_dialog_content = "…",
  ui_story_8_1_1_19_dialog_content = "Suara berisik apa itu?",
  ui_story_8_1_1_20_dialog_content = "Kaudengar sesuatu?",
  ui_story_8_1_1_21_dialog_content = "Ada yang aneh di sini, Vice. Aku merasa kurang nyaman, seperti…",
  ui_story_8_1_1_22_dialog_content = "Itu semua hanya pikiranmu, PlayerName. Kau aman bersamaku, jadi percaya sajalah padaku.",
  ui_story_8_1_1_23_dialog_content = "Kalau kau masih punya banyak pertanyaan, aku bisa menjawab semuanya. Tapi, tolong, pegang saja tanganku, ya?",
  ui_story_8_1_1_24_dialog_content = "Akan kuceritakan padamu. Akan kuceritakan semuanya padamu…",
  ui_story_8_1_1_25_dialog_content = "PlayerName?",
  ui_story_8_1_1_26_dialog_content = "Masa lalu, masa depan, apa pun yang ingin kauketahui.",
  ui_story_8_1_1_27_dialog_content = "Ayo menuju masa depan, bersama!",
  ui_story_8_1_1_28_dialog_content = "Jadi, jangan tinggalkan aku sendirian. Kita sudah saling berjanji, 'kan?",
  ui_story_8_1_1_29_dialog_content = "Memangnya kau tak dengar itu? Apa kau ini tuli, PlayerName?",
  ui_story_8_1_1_30_option_content = "Aku janji aku tak akan pernah meninggalkanmu.",
  ui_story_8_1_1_31_dialog_content = "Aku senang akhirnya kau paham. Sekarang, jangan pernah tinggalkan aku.",
  ui_story_8_1_1_32_dialog_content = "Buang topengmu, Caelestite, dan terimalah kekuatan sejatimu!",
  ui_story_8_1_1_33_option_content = "Aku mau pergi. Kau bukan Vice.",
  ui_story_8_1_1_34_dialog_content = "Tunggu, kembalilah! Dasar Caelestite bodoh!",
  ui_story_8_1_1_35_dialog_content = "Kebanyakan orang hanya bisa memimpikan kesempatan seperti ini. Dasar bodoh. Bodoh, payah, menyedihkan!",
  ui_story_8_1_1_36_dialog_content = "Dengarkan aku, kau harus keluar dari fantasi indah tapi berbahaya ini…",
  ui_story_8_1_1_37_dialog_content = "Sini, ikuti Wispy, dia akan menuntunmu menuju kebenaran.",
  ui_story_8_1_1_38_dialog_content = "Kyuu!!",
  ui_story_8_1_1_39_dialog_content = "(Aduh! Kenapa sakit sekali?)",
  ui_story_8_1_1_42_dialog_content = "(Yang melayang keluar dari tubuhku ini apa?)",
  ui_story_8_1_1_43_dialog_content = "(Apa itu? Dan kenapa…)",
  ui_story_8_1_1_44_dialog_content = "*Meraung*",
  ui_story_8_1_1_45_dialog_content = "Kyuu!!",
  ui_story_8_1_1_47_dialog_content = "Kau Curie, salah satu anak buah Vivian!",
  ui_story_8_1_1_48_dialog_content = "Kyuu!!!",
  ui_story_8_1_1_49_dialog_content = "Mana Master-mu? Dan mana Vice?",
  ui_story_8_1_1_50_dialog_content = "Yang tadi itu, apa itu berasal dari dalam tubuhku? Apa itu?",
  ui_story_8_1_1_51_dialog_content = "Aduh, kepalaku sakit… Aduh, sakit sekali… Apa tadi kepalaku terbentur?",
  ui_story_8_1_1_52_dialog_content = "Kyuu!",
  ui_story_8_1_1_53_dialog_content = "Curie mungil yang malang. Kenapa kau bisa terluka begini? Apa kau juga terpisah dari yang lainnya?",
  ui_story_8_1_1_54_dialog_content = "Aku penasaran, bagaimana keadaan mereka sekarang.",
  ui_story_8_1_1_55_dialog_content = "Tak mungkin!",
  ui_story_8_1_1_58_dialog_content = "Aduh, aduh, aduh… Aku tak bisa ingat apa pun setelah itu.",
  ui_story_8_1_1_59_dialog_content = "Aku penasaran bagaimana keadaan Vice dan yang lainnya…",
  ui_story_8_1_1_60_dialog_content = "PlayerName!",
  ui_story_8_1_1_61_dialog_content = "Vice?",
  ui_story_8_1_1_62_dialog_content = "Sst, pelankan suaramu. Ini aku…",
  ui_story_8_1_1_63_dialog_content = "Kau baik-baik saja? Tempat ini dipenuhi Darkflow! Aku hanya…",
  ui_story_8_1_1_64_dialog_content = "Aku tahu! Aku baik-baik saja. Bagaimana denganmu? Kau terluka? Coba kuperiksa!",
  ui_story_8_1_1_65_option_content = "Perasaanku tak nyaman.",
  ui_story_8_1_1_66_dialog_content = "Rasanya tak nyaman. Sepertinya aku tak terluka, tapi tubuhku terasa berat…",
  ui_story_8_1_1_67_dialog_content = "Kepalaku pun pusing… Tempat apa ini?",
  ui_story_8_1_1_68_dialog_content = "Kau tak ingat? Kita ada di dalam Aviduz, PlayerName.",
  ui_story_8_1_1_69_option_content = "Aku tak ingat.",
  ui_story_8_1_1_70_dialog_content = "Aku tak ingat… Aku baru saja bangun… Oh, iya, tadi aku mimpi buruk!",
  ui_story_8_1_1_71_dialog_content = "Aku melihatmu dalam mimpiku itu, tapi kau sama sekali tak seperti dirimu… Tidak, tidak, itu tak mungkin kau.",
  ui_story_8_1_1_F1_dialog_content = "Lalu, ada orang lain juga.",
  ui_story_8_1_1_72_dialog_content = "Mimpi? Kau mimpi melihatku, tapi tak seperti aku? Siapa si orang lain itu?",
  ui_story_8_1_1_F2_dialog_content = "Maaf, aku tak yakin apa yang sebenarnya terjadi.",
  ui_story_8_1_1_73_dialog_content = "Terus bagaimana? Kau terbangun di sini? Itu saja?",
  ui_story_8_1_1_F3_dialog_content = "Benar. Aku terbangun di sini.",
  ui_story_8_1_1_74_dialog_content = "Baiklah. Mungkin ini akibat Darkflow yang memengaruhi pikiranmu. Kita memang sedang di dalam Aviduz.",
  ui_story_8_1_1_75_option_content = "Kita ada di mana?",
  ui_story_8_1_1_76_dialog_content = "Kita ada di dalam Aviduz, Colossus itu.",
  ui_story_8_1_1_77_dialog_content = "Ini pertama kalinya aku melihat Colossus seperti ini. Itu pun kalau ini memang bisa disebut Colossus.",
  ui_story_8_1_1_78_dialog_content = "Lihat! Kau bisa lihat bercak-bercak Darkflow di mana-mana. Ini taman bermain bagi Eclipsite.",
  ui_story_8_1_1_79_dialog_content = "Sepanjang jalan menuju ke sini, aku juga menjumpai banyak Eclipsite. Semoga tadi aku tidak terlalu berisik.",
  ui_story_8_1_1_80_dialog_content = "Sebentar, tadi kaubilang…",
  ui_story_8_1_1_81_dialog_content = "Kita ada DI DALAM Aviduz?!",
  ui_story_8_1_1_82_dialog_content = "Benar. Aku melihat Schummer menyeretmu kemari, lalu…",
  ui_story_8_1_1_83_dialog_content = "Aku mengikutinya masuk.",
  ui_story_8_1_1_84_dialog_content = "Apa? Kenapa kau mengikuti dia ke tempat seperti ini?",
  ui_story_8_1_1_88_dialog_content = "Tentu saja untuk menyelamatkanmu! Kau sudah membantu kami dengan mendorong kami menjauh, tapi kau masih di atas Soroz. Mana mungkin aku…",
  ui_story_8_1_1_89_dialog_content = "Sebentar, apa yang terjadi sebelumnya?",
  ui_story_8_1_1_90_dialog_content = "Tidak, apa pun yang terjadi sebelumnya, itu tak bisa dijadikan alasan untuk melakukan hal berbahaya seperti menyusulku kemari!",
  ui_story_8_1_1_91_dialog_content = "Aku tahu, tapi memangnya aku harus bagaimana? Diam dan menonton saja?",
  ui_story_8_1_1_92_dialog_content = "Kupikir mungkin kau masih hidup, dan mungkin aku masih bisa berbuat sesuatu.",
  ui_story_8_1_1_93_dialog_content = "Aku paham perasaanmu, Vice, tapi tetap saja…",
  ui_story_8_1_1_94_dialog_content = "Tak ada gunanya berdebat soal itu, PlayerName. Toh sekarang aku sudah di sini!",
  ui_story_8_1_1_95_dialog_content = "Sekarang, kita harus cari tahu apa yang harus kita lakukan setelah ini. Berdirilah!",
  ui_story_8_1_1_96_dialog_content = "Kyuu!",
  ui_story_8_1_1_97_dialog_content = "Tolong bantu aku, Curie, dan buat dia paham. Mau, ya?",
  ui_story_8_1_1_98_dialog_content = "Beri tahu aku apa yang terjadi sebelumnya. Setiap kali berusaha mengingat, kepalaku tiba-tiba terasa sakit seperti mau meledak.",
  ui_story_8_1_1_99_dialog_content = "Bangunlah dulu! Kita tak bisa berdiri saja di sini. Nanti kuceritakan sambil jalan.",
  ui_story_8_1_1_100_dialog_content = "Chief Vivian memerintahkan kita untuk mundur, tapi kemudian Schummer…",
  ui_story_8_1_1_101_dialog_content = "Semuanya, bersiaplah. Akan kuulur waktu untuk kalian.",
  ui_story_8_1_1_103_dialog_content = "Titik lemahnya ada di arah jam sembilan darimu. Larilah ke sana. Langsung lompat ke bawah, mungkin kalian akan selamat.",
  ui_story_8_1_1_104_dialog_content = "Vice, PlayerName, Carleen, sampai jumpa lagi.",
  ui_story_8_1_1_105_dialog_content = "Chief, apa kau…?",
  ui_story_8_1_1_106_dialog_content = "Tak mungkin!",
  ui_story_8_1_1_107_dialog_content = "Akulah lawanmu!",
  ui_story_8_1_1_108_dialog_content = "Sungguh tak diduga. Ternyata kau mau bertarung sebagaimana mestinya demi makhluk rendah tak berguna!",
  ui_story_8_1_1_109_dialog_content = "…",
  ui_story_8_1_1_110_dialog_content = "Kalau memang begitu maumu, setidaknya ayo kita buat agar ini menarik!",
  ui_story_8_1_1_111_dialog_content = "Memangnya kau mau ke mana?!",
  ui_story_8_1_1_112_dialog_content = "Cepat, lompat turun!",
  ui_story_8_1_1_113_dialog_content = "Dari tempat setinggi ini? Sepertinya kita tak punya pilihan… Ayo!",
  ui_story_8_1_1_114_dialog_content = "Pegang tanganku! Kita lompat bersama…",
  ui_story_8_1_1_115_dialog_content = "*Meraung*",
  ui_story_8_1_1_116_dialog_content = "Lepaskan aku!",
  ui_story_8_1_1_117_dialog_content = "PlayerName!!",
  ui_story_8_1_1_118_dialog_content = "(Kita diseret balik!!)",
  ui_story_8_1_1_119_dialog_content = "Kekuatanku sudah tak bersisa… Bagaimana mungkin kita bisa…",
  ui_story_8_1_1_120_dialog_content = "…",
  ui_story_8_1_1_121_option_content = "Pergilah!",
  ui_story_8_1_1_122_dialog_content = "?!",
  ui_story_8_1_1_123_dialog_content = "PlayerName!",
  ui_story_8_1_1_124_dialog_content = "Terlalu tinggi! Kita tak akan berhasil!",
  ui_story_8_1_1_125_dialog_content = "Coba stabilkan posisimu saat jatuh, Vice! Setidaknya kau bisa…",
  ui_story_8_1_1_126_dialog_content = "Carleen!!!",
  ui_story_8_1_1_127_dialog_content = "Aku sudah memegangmu!!",
  ui_story_8_1_1_128_dialog_content = "Raphael? Kenapa kau… Aduh! Sakit!",
  ui_story_8_1_1_129_dialog_content = "Pesawat ini… Apa kau meminta bala bantuan, Carleen?",
  ui_story_8_1_1_130_dialog_content = "Hehe, kurasa bisa dibilang begitu! Aku, Raphael yang hebat, datang kemari untuk membebaskan kalian dari tempat terkutuk ini!",
  ui_story_8_1_1_131_dialog_content = "Sepertinya aku nyaris saja terlambat! Kalau saja aku tiba beberapa detik lebih lambat…",
  ui_story_8_1_1_132_dialog_content = "Hik…",
  ui_story_8_1_1_133_dialog_content = "Suara berisik apa itu?",
  ui_story_8_1_1_134_dialog_content = "Hah? Sepertinya aku dengar sesuatu dari bawah pantatku…",
  ui_story_8_1_1_135_dialog_content = "Kyuu!!",
  ui_story_8_1_1_136_dialog_content = "Curie?!",
  ui_story_8_1_1_137_dialog_content = "Maafkan aku, dari tadi ternyata aku mendudukimu tanpa sadar!",
  ui_story_8_1_1_138_dialog_content = "Kyuu!",
  ui_story_8_1_1_139_dialog_content = "Apa itu peliharaanmu, Vice?",
  ui_story_8_1_1_140_dialog_content = "Bukan, dia milik Chief Vivian.",
  ui_story_8_1_1_141_dialog_content = "Oh? Mana dia? Lalu, mana si Caelestite itu?",
  ui_story_8_1_1_142_dialog_content = "Mereka…",
  ui_story_8_1_1_143_dialog_content = "…",
  ui_story_8_1_1_144_dialog_content = "Bukan saatnya membahas hal-hal ini, Raphael! Situasi sudah berubah drastis. Ayo pergi dari sini dan melapor kepada City Lord sesegera mungkin!",
  ui_story_8_1_1_145_dialog_content = "PlayerName memberi kita kesempatan untuk lolos. Jangan sampai kita menyia-nyiakannya.",
  ui_story_8_1_1_146_dialog_content = "Kita harus cari cara untuk melawan.",
  ui_story_8_1_1_147_dialog_content = "Jadi, apa kau punya rencana, Carleen?",
  ui_story_8_1_1_148_dialog_content = "Ya. Kita kembali dan yakinkan pria itu untuk menggunakan Damocles.",
  ui_story_8_1_1_149_dialog_content = "?!",
  ui_story_8_1_1_150_dialog_content = "Itu satu-satunya cara agar kita bisa punya peluang untuk mengalahkan Schummer.",
  ui_story_8_1_1_151_dialog_content = "Tapi sudah sepuluh tahun lebih Damocles tidak diaktifkan, 'kan? Apa kira-kira dia akan setuju?",
  ui_story_8_1_1_152_dialog_content = "Akan kupaksa dia agar setuju! Saat ini, hanya Damocles-lah yang bisa menghentikan Aviduz.",
  ui_story_8_1_1_153_dialog_content = "Tapi, PlayerName…",
  ui_story_8_1_1_154_dialog_content = "Masalah ini menyangkut keselamatan Lumopolis. Aku tak punya pilihan. Kita semua sudah kehabisan pilihan, Vice.",
  ui_story_8_1_1_155_dialog_content = "…",
  ui_story_8_1_1_156_dialog_content = "Nah, bagaimana? Apa yang kaupikirkan?",
  ui_story_8_1_1_157_dialog_content = "Kau ingin kembali ke tempat Soroz?",
  ui_story_8_1_1_158_dialog_content = "Ya.",
  ui_story_8_1_1_159_dialog_content = "Maafkan aku, Carleen, tapi aku tak bisa meninggalkan PlayerName atau Chief Vivian.",
  ui_story_8_1_1_160_dialog_content = "Vice…",
  ui_story_8_1_1_161_dialog_content = "Aku paham perasaanmu, Carleen, tapi aku tak bisa meninggalkan teman-temanku begitu saja! Aku tak akan meninggalkan mereka!",
  ui_story_8_1_1_162_dialog_content = "Tenanglah, Vice. Terlalu berbahaya kalau kau kembali ke sana sekarang!",
  ui_story_8_1_1_164_dialog_content = "Atau, kau ingin pengorbanan PlayerName sia-sia?",
  ui_story_8_1_1_165_dialog_content = "Aku tahu bahayanya, Carleen. Aku akan cari cara.",
  ui_story_8_1_1_166_dialog_content = "Misalnya apa? Kita hanya punya satu pesawat!",
  ui_story_8_1_1_167_dialog_content = "Benar.",
  ui_story_8_1_1_168_dialog_content = "Kau juga tak punya sayap, Vice sayang. Bagaimana kalau kita…",
  ui_story_8_1_1_169_dialog_content = "…",
  ui_story_8_1_1_170_dialog_content = "Curie, aku mengandalkanmu.",
  ui_story_8_1_1_171_dialog_content = "Kyuu?",
  ui_story_8_1_1_172_dialog_content = "Kyuu?!",
  ui_story_8_1_1_173_dialog_content = "Aku bisa kembali bersama Curie.",
  ui_story_8_1_1_174_dialog_content = "Kau yakin Curie cukup kuat untuk membawamu?",
  ui_story_8_1_1_175_dialog_content = "Aku memang tidak seringan bulu, tapi Curie sangat kuat!",
  ui_story_8_1_1_176_dialog_content = "Kyuu!",
  ui_story_8_1_1_177_dialog_content = "Aku paham, Curie. Kau ingin kembali dan menyelamatkan Master-mu, 'kan?",
  ui_story_8_1_1_180_dialog_content = "Kalau kau memang mau pergi, lepas landaslah dari sini. Jarak kita masih cukup dekat, kau bisa berhasil.",
  ui_story_8_1_1_181_dialog_content = "Carleen…",
  ui_story_8_1_1_182_dialog_content = "Aku tahu aku tak bisa mengubah keputusanmu, sama seperti kau tak bisa mengubah keputusanku. Kita selalu bertindak dengan cara kita sendiri.",
  ui_story_8_1_1_183_dialog_content = "Ingat, tetap waspada. Selama ini, kau selalu beruntung.",
  ui_story_8_1_1_184_dialog_content = "Entah itu dengan mengaktifkan Soroz atau membahayakan nyawamu untuk menyelamatkan Gronru.",
  ui_story_8_1_1_185_dialog_content = "Tapi, apa jadinya kalau keberuntungan sudah tak berpihak padamu lagi?",
  ui_story_8_1_1_186_dialog_content = "Aku percaya pada PlayerName. Aku tahu kami akan bisa menemukan cara untuk lolos, seperti sebelum-sebelumnya.",
  ui_story_8_1_1_187_dialog_content = "Aku yakin, selama kami tak menyerah, kami bisa mewujudkan keajaiban.",
  ui_story_8_1_1_188_dialog_content = "Kadang aku tak sanggup menghadapi optimismemu, Vice.",
  ui_story_8_1_1_189_dialog_content = "Pergilah. Karena aku akan sibuk meyakinkan pria tua itu, kali ini aku tak bisa ikut denganmu.",
  ui_story_8_1_1_190_dialog_content = "Jagalah Caelestite itu untukku, Vice!",
  ui_story_8_1_1_191_dialog_content = "Kau juga hati-hati, Carleen! Kalau kau bisa mengaktifkan Damocles, Schummer pasti akan terkaget-kaget!",
  ui_story_8_1_1_192_dialog_content = "Lebih dari sekadar kaget! Semoga kau bisa keluar dari sana tepat waktu.",
  ui_story_8_1_1_193_dialog_content = "Kami akan kembali secepat mungkin, Carleen!",
  ui_story_8_1_1_194_dialog_content = "Sampai jumpa lagi, Vice.",
  ui_story_8_1_1_195_dialog_content = "(Eclipsian) Di sana! Hancurkan itu! Cepat!",
  ui_story_8_1_1_196_dialog_content = "(Eclipsian) Selamatkan apa pun yang berguna! Tuan kami membutuhkan lebih banyak bahan bangunan untuk menyelesaikan Colossus!",
  ui_story_8_1_1_197_dialog_content = "(Eclipsian) Apakah Anda mendengar itu?!",
  ui_story_8_1_1_198_dialog_content = "Graagh!?",
  ui_story_8_1_1_200_dialog_content = "Jangan teriak, kau satu-satunya yang ada di ruang ini. Mana Eclipsite lainnya? Apa Soroz sudah pergi?",
  ui_story_8_1_1_201_dialog_content = "Aku tak akan mengampunimu karena sudah menghancurkan rumah PlayerName seperti ini!",
  ui_story_8_1_1_202_dialog_content = "(Eclipsian) Sampah Aurorian... Harus memperingatkan master...",
  ui_story_8_1_1_203_dialog_content = "Maafkan aku, kau pasti tak mengira akan seperti ini, tapi aku ingin tanya sesuatu.",
  ui_story_8_1_1_204_dialog_content = "Urraagh!!",
  ui_story_8_1_1_205_dialog_content = "Aku tahu kau mungkin tak paham sepatah kata pun yang kuucapkan, tapi…",
  ui_story_8_1_1_206_dialog_content = "Ada dua orang yang sangat penting, PlayerName dan Chief Vivian, dan aku ingin tahu mereka ada di mana.",
  ui_story_8_1_1_207_dialog_content = "(Eclipsian) Maksudmu Caelestite adalah temanmu? Bukankah kamu sudah melarikan diri? Wanita bodoh...",
  ui_story_8_1_1_208_dialog_content = "Aku tak paham kata-katamu. Buang-buang waktu saja.",
  ui_story_8_1_1_209_dialog_content = "Kalau kau tak bisa bahasa Universese, bagaimana kalau kita pakai pena dan kertas saja?",
  ui_story_8_1_1_210_dialog_content = "?",
  ui_story_8_1_1_211_dialog_content = "Biar kugambar saja…",
  ui_story_8_1_1_212_dialog_content = "Di mana orang ini?",
  ui_story_8_1_1_213_dialog_content = "(Eclipsian) Aku tahu, kau di sini untuk Caelestite!",
  ui_story_8_1_1_214_dialog_content = "(Eclipsian) Aku ingat Caelestite ada di... No.",
  ui_story_8_1_1_215_dialog_content = "Eh, lihat apa kau?",
  ui_story_8_1_1_216_dialog_content = "(Eclipsian) Mengapa saya pernah memberitahu Anda, cacing kotor? Jika kau pikir kau bisa mengacaukan rencana master, maka...",
  ui_story_8_1_1_217_dialog_content = "Ugh!",
  ui_story_8_1_1_218_dialog_content = "Apa tadi dia melirik ke arah Aviduz?",
  ui_story_8_1_1_219_dialog_content = "Kyuu, kyuu…",
  ui_story_8_1_1_220_dialog_content = "Kau baik-baik saja? Tenagamu habis? Kau pasti lelah membawaku terbang sejauh ini.",
  ui_story_8_1_1_221_dialog_content = "Kyuu!",
  ui_story_8_1_1_222_dialog_content = "Asalkan kau masih baik-baik saja… Maafkan aku, Curie, tapi aku terpaksa merepotkanmu sekali lagi.",
  ui_story_8_1_1_223_dialog_content = "Perhentian berikutnya, Aviduz! Mungkin di sanalah kita akan menemukan PlayerName dan Chief Vivian!",
  ui_story_8_1_1_224_dialog_content = "Kyuu?!",
  ui_story_8_1_1_225_dialog_content = "Rupanya begitu caramu menyusup masuk? Ternyata memang bisa, ya?",
  ui_story_8_1_1_226_dialog_content = "Mungkin terdengar sulit dipercaya, tapi ini semua berkat Curie.",
  ui_story_8_1_1_227_dialog_content = "Kyuu…",
  ui_story_8_1_1_228_dialog_content = "Sepertinya Curie siap mendarat.",
  ui_story_8_1_1_229_dialog_content = "Curie sudah bekerja keras. Akan kuberi dia hadiah besar setelah kita kembali nanti!",
  ui_story_8_1_1_230_option_content = "Kalau begitu, ayo pergi dari sini.",
  ui_story_8_1_1_231_dialog_content = "Kyuu!",
  ui_story_8_1_1_232_dialog_content = "Tapi, kita belum menemukan Chief Vivian, PlayerName.",
  ui_story_8_1_1_233_dialog_content = "Kalau kau masih punya tenaga, kuharap kau bisa bertahan sebentar lagi.",
  ui_story_8_1_1_234_dialog_content = "Setelah itu, kita bisa meloloskan diri bersama-sama!",
  ui_story_8_1_1_235_option_content = [[
Tapi aku belum melihat Vivian
di mana pun.]],
  ui_story_8_1_1_236_dialog_content = "Kyuu…",
  ui_story_8_1_1_237_dialog_content = "Kurasa sepertinya dia juga terperangkap di sini. Ayo kita cari dia.",
  ui_story_8_1_1_238_dialog_content = "Apa pun rencana Schummer, kita tak boleh meninggalkan Chief Vivian!",
  ui_story_8_1_1_239_dialog_content = "Aku sudah merasa jauh lebih baik. Ayo kita lakukan!",
  ui_story_8_1_1_240_dialog_content = "Baiklah, ayo!",
  ui_story_8_1_1_241_dialog_content = "Kyuu!",
  ui_story_8_2_1_1_dialog_content = "Maaf, Profesor, bisa tolong beri contoh sekali lagi?",
  ui_story_8_2_1_2_dialog_content = "Aku gagal lagi. Sepertinya aku masih belum berhasil melakukannya.",
  ui_story_8_2_1_3_dialog_content = "Profesor… Profesor?!",
  ui_story_8_2_1_4_dialog_content = "Hei!",
  ui_story_8_2_1_5_dialog_content = "Lagi-lagi kau melamun?",
  ui_story_8_2_1_6_dialog_content = "…",
  ui_story_8_2_1_7_dialog_content = "Kendalikan dirimu. Kau akan segera membuktikan kemampuanmu pada si Caelestite itu, 'kan?",
  ui_story_8_2_1_8_dialog_content = "Cukup.",
  ui_story_8_2_1_9_dialog_content = "Aku tak butuh ceramah motivasi, apalagi darimu.",
  ui_story_8_2_1_10_dialog_content = "Ya sudah.",
  ui_story_8_2_1_11_dialog_content = "…",
  ui_story_8_2_1_12_dialog_content = "Aku membiarkan PlayerName hidup bukan untuk hal sepele seperti membuktikan kemampuanku, Forsakin.",
  ui_story_8_2_1_13_dialog_content = "Anu…",
  ui_story_8_2_1_14_dialog_content = "Tapi, kalaupun kujelaskan, kau tetap tak akan paham.",
  ui_story_8_2_1_15_dialog_content = "Apa pun itu, ini sama saja dengan saat kau membiarkan si gadis Illumina itu hidup.",
  ui_story_8_2_1_16_dialog_content = "Beda, dong. Kau dan aku sama sekali tak sama.",
  ui_story_8_2_1_17_dialog_content = "Lagi pula, aku tak punya urusan dengan Illumina, sedangkan kau ini seorang Caelestite.",
  ui_story_8_2_1_18_dialog_content = "Kau menyebutku Caelestite?!",
  ui_story_8_2_1_19_dialog_content = "Santai sajalah. Obrolan kita sudah selesai.",
  ui_story_8_2_1_20_dialog_content = "Kau memang penuh omong kosong!",
  ui_story_8_2_1_21_dialog_content = "Sampai jumpa lagi.",
  ui_story_8_2_1_22_dialog_content = "Memangnya kau mau ke mana?",
  ui_story_8_2_1_23_dialog_content = "Aku sudah memberikan kekuatan seperti yang kaumiliki kepada si Caelestite itu. Aku yakin sebentar lagi kalian bisa saling menyebut satu sama lain \"saudara\".",
  ui_story_8_2_1_24_dialog_content = "Apa maksudmu? Aku tak memintamu untuk berbuat seperti itu!",
  ui_story_8_2_1_25_dialog_content = "Dia hanya membual!",
  ui_story_8_2_1_26_dialog_content = "Memangnya dia sedang apa sih di sini? Sejak pertama bertemu, dia selalu bersikap seperti itu!",
  ui_story_8_2_1_27_dialog_content = "Kalau kau tak mau membantu, ya sudah. Dulu, sewaktu aku masih fokus pada Lumopolis, dia masih saja mencari masalah…",
  ui_story_8_2_1_28_dialog_content = "Schummer, aku menawarkan diri untuk membantumu, atas perintah dari Lady Forsakin…",
  ui_story_8_2_1_29_dialog_content = "Tapi, jaga bicaramu saat berhadapan dengannya.",
  ui_story_8_2_1_30_dialog_content = "Cih. Sepertinya dia tak bisa menahan diri untuk tak ikut campur, ya?",
  ui_story_8_2_1_31_dialog_content = "Tempat ini kacau sekali…",
  ui_story_8_2_1_32_dialog_content = "Nah, bagaimana, PlayerName? Apa kau berhasil melakukannya?",
  ui_story_8_2_1_33_dialog_content = "Ya. Aku berhasil membangun telepati dengan Colossus ini, tapi aku tak bisa memahaminya.",
  ui_story_8_2_1_F1_dialog_content = "Tidak, bukannya aku tak bisa memahaminya.",
  ui_story_8_2_1_34_dialog_content = "Colossus ini tak punya Echo Template. Dia benar-benar kosong.",
  ui_story_8_2_1_35_dialog_content = "Hati-hati, mungkin saja alarmnya akan aktif.",
  ui_story_8_2_1_36_dialog_content = "Jangan khawatir, Vice. Aku selalu berhati-hati.",
  ui_story_8_2_1_37_dialog_content = "Lagi pula, kekuatanku bisa mencegah agar alarmnya tidak berbunyi, dan kita tak akan ketahuan.",
  ui_story_8_2_1_F2_dialog_content = "Kau benar-benar bisa melakukannya dengan kemampuan psikismu?",
  ui_story_8_2_1_F3_dialog_content = "Ya. Setelah aku belajar mendalami kemampuan psikis, aku bisa melakukan cukup banyak hal dengan sedikit saja energi psikis.",
  ui_story_8_2_1_38_dialog_content = "Apa kau bisa merasakan keberadaan Chief Vivian?",
  ui_story_8_2_1_F4_dialog_content = "Maaf, tapi aku tak berani menggunakan kekuatanku lebih banyak lagi.",
  ui_story_8_2_1_F5_dialog_content = "Kita berada di dalam Aviduz, jadi aku bisa langsung menggunakan kekuatanku melalui sentuhan.",
  ui_story_8_2_1_39_dialog_content = "Tapi, kalau aku melacak terlalu jauh, Schummer akan tahu lokasi kita.",
  ui_story_8_2_1_40_dialog_content = "Aku paham. Kita memang harus mengandalkan mata saja untuk mencarinya.",
  ui_story_8_2_1_41_dialog_content = "Bagaimana keadaanmu? Apa kira-kira kau sanggup bertahan dari Dark Matter yang ada di sini?",
  ui_story_8_2_1_42_dialog_content = "Aku baik-baik saja sekarang. Kepalaku sudah tak sakit lagi.",
  ui_story_8_2_1_43_dialog_content = "Aku bahkan merasa lebih baik sekarang, seakan-akan baru saja bangun setelah tidur lelap lama sekali.",
  ui_story_8_2_1_44_dialog_content = "Sungguh? Kok aneh, ya. Sewaktu di Whispering Corridor dulu, kau jelas tak sanggup menahan Darkflow.",
  ui_story_8_2_1_45_dialog_content = "Kyuu!",
  ui_story_8_2_1_46_dialog_content = "Kau mencium bau apa, Curie?",
  ui_story_8_2_1_47_dialog_content = "Hatsyiii!",
  ui_story_8_2_1_48_dialog_content = "Kyuu…",
  ui_story_8_2_1_49_dialog_content = "Darkflow di sini sangat pekat, bahkan Curie pun tak mampu menahannya…",
  ui_story_8_2_1_50_dialog_content = "Kau terlalu lambat.",
  ui_story_8_2_1_51_dialog_content = "Siapa di sana?",
  ui_story_8_2_1_52_dialog_content = "Kau terlambat lebih lama daripada perkiraanku, padahal roda nasib tak akan menunggu siapa pun.",
  ui_story_8_2_1_53_dialog_content = "Kemarilah, Caelestite, yang kaucari ada di ujung koridor ini.",
  ui_story_8_2_1_54_dialog_content = "Siapa kau? Kau ini Aurorian atau Eclipsite?",
  ui_story_8_2_1_55_dialog_content = "Sst… Itu tak penting. Hal yang penting akan segera terjadi. Hal yang kita cari dengan gigih…",
  ui_story_8_2_1_56_dialog_content = "Truth.",
  ui_story_8_2_1_57_dialog_content = "Ada apa, PlayerName? Kau tampak kepayahan…",
  ui_story_8_2_1_58_dialog_content = "Aku baru saja melihat sesuatu yang aneh.",
  ui_story_8_2_1_59_dialog_content = "Seorang pria berpakaian putih dan membawa koper. Dia menyuruhku pergi ke arah sana.",
  ui_story_8_2_1_60_dialog_content = "Apa? Mana orangnya?",
  ui_story_8_2_1_F6_dialog_content = "Mungkin aku sebatas merasakannya. Dia menyuruhku pergi ke arah sana. Sepertinya dia bisa dipercaya.",
  ui_story_8_2_1_F7_dialog_content = "Tapi, tak jelas arah mana yang dimaksud \"ke sana\" itu…",
  ui_story_8_2_1_61_dialog_content = "Aku tidak terlalu hafal interior Aviduz, tapi mengingat jalur yang sudah kita tempuh…",
  ui_story_8_2_1_62_dialog_content = "Yah, aku bisa menggambar peta sederhana, sih!",
  ui_story_8_2_1_63_dialog_content = "Untungnya, aku masih punya kertas ini.",
  ui_story_8_2_1_64_dialog_content = "Garis-garis yang kaugambar itu apa, Vice?",
  ui_story_8_2_1_65_dialog_content = "Abaikan saja! Itu bukan apa-apa!",
  ui_story_8_2_1_66_dialog_content = "Dan gambar orang-orangan kecil yang kaubuat ini…",
  ui_story_8_2_1_68_dialog_content = "Aku menggambarnya agar bisa menanyakan lokasimu kepada para Eclipsite!",
  ui_story_8_2_1_F8_dialog_content = "Ini aku?",
  ui_story_8_2_1_69_dialog_content = "Kuakui, gambarku memang tak bagus, tapi toh aku berhasil mengetahui lokasimu!",
  ui_story_8_2_1_70_dialog_content = "Sudahlah, cukup sudah mengobrolnya! Aku harus memetakan rute yang baru saja kita tempuh selagi aku masih ingat.",
  ui_story_8_2_1_72_dialog_content = "(Memangnya Eclipsite benar-benar bisa memahami gambar ini?)",
  ui_story_8_2_1_73_dialog_content = "Ini, kita ukur dengan penggaris, lalu…",
  ui_story_8_2_1_74_dialog_content = "Selesai!",
  ui_story_8_2_1_75_dialog_content = "(Aku tak boleh menertawakan kemampuannya menggambar. Dia 'kan sudah berusaha keras.)",
  ui_story_8_2_1_76_dialog_content = "Petanya… luar biasa, seperti karya kartografer kawakan!",
  ui_story_8_2_1_77_dialog_content = "Ini sudah cukup. Dengan waktu sesempit ini, aku hanya bisa membuat gambar sederhana seperti ini.",
  ui_story_8_2_1_78_dialog_content = "Sederhana! Aku bisa paham bagaimana kau bisa menggambar orang yang tampak begitu \"nyata\", tapi ternyata kau juga bisa menggambar peta sebagus ini!?",
  ui_story_8_2_1_79_dialog_content = "Kan sudah kubilang aku mempelajarinya di Illumina.",
  ui_story_8_2_1_80_dialog_content = "Selain itu, pengetahuan seperti ini juga dibutuhkan untuk melakukan perbaikan dan pemeliharaan pada Soroz.",
  ui_story_8_2_1_81_dialog_content = "Kyuu!",
  ui_story_8_2_1_82_dialog_content = "Ada apa, Curie?",
  ui_story_8_2_1_83_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_2_1_84_dialog_content = "Lewat sini? Tapi…",
  ui_story_8_2_1_85_dialog_content = "Bukannya ini arah yang ditunjuk pria itu tadi?",
  ui_story_8_2_1_86_dialog_content = "Curie mencium bau Vivian, PlayerName! Ayo!",
  ui_story_8_2_1_87_dialog_content = "(Kurasa pria itu bukan musuh…)",
  ui_story_8_2_1_88_dialog_content = "Aku yakin di sana pasti ada banyak Eclipsite. Ayo kalahkan mereka secepat mungkin!",
  ui_story_8_2_1_89_dialog_content = "Bersiaplah untuk bertarung!",
  ui_story_8_2_2_1_dialog_content = "<color=#e8d9bb>Uptown, Lumopolis Gardens</color>",
  ui_story_8_2_2_2_dialog_content = "Kau ingin mengaktifkan…",
  ui_story_8_2_2_3_dialog_content = "Damocles?",
  ui_story_8_2_2_5_dialog_content = "Benar. Ini satu-satunya solusi untuk masalah kita saat ini!",
  ui_story_8_2_2_6_dialog_content = "Apa kau sadar apa yang kaukatakan itu, Carleen?",
  ui_story_8_2_2_7_dialog_content = "Untuk menyalakannya, kita butuh Three-Party Resolution. Itu protokol utamanya.",
  ui_story_8_2_2_F1_dialog_content = "Apa kau tahu berapa banyak energi yang dibutuhkannya!?",
  ui_story_8_2_2_8_dialog_content = "Democles akan menguras semua energi dari perisai! Seluruh Lumopolis akan pelan-pelan mati total!",
  ui_story_8_2_2_9_dialog_content = "Aku tahu.",
  ui_story_8_2_2_10_dialog_content = "Kalau sampai berpikir begitu, kau pasti sudah gila!",
  ui_story_8_2_2_11_dialog_content = "Otto.",
  ui_story_8_2_2_12_dialog_content = "Hmph.",
  ui_story_8_2_2_13_dialog_content = "Lord, kau belum lihat kemampuan Schummer dan Black Colossus, tapi aku sudah melihatnya! Aku berhasil lolos hanya karena aku melompat dari atasnya!",
  ui_story_8_2_2_14_dialog_content = "Tak ada yang bisa menghentikan Black Colossus kalau dia dayanya sudah terisi penuh, apalagi sambil melawan semua sekutunya!",
  ui_story_8_2_2_15_dialog_content = "Kita harus mendirikan pertahanan terakhir! Perisai kita tak akan selamanya melindungi kita. Pada akhirnya perisai kita akan runtuh.",
  ui_story_8_2_2_16_dialog_content = "Kau terluka?",
  ui_story_8_2_2_17_dialog_content = "Apa?",
  ui_story_8_2_2_18_dialog_content = "Kau terluka, Carleen?",
  ui_story_8_2_2_19_dialog_content = "Saat Raphael menyelamatkanmu, dia bilang dia baru sekali itu melihat keadaanmu seperti itu. Kau tampak seperti kalah telak.",
  ui_story_8_2_2_20_dialog_content = "…",
  ui_story_8_2_2_21_dialog_content = "Terima kasih atas perhatianmu, Lord, tapi aku benar-benar baik-baik saja.",
  ui_story_8_2_2_22_dialog_content = "Tentu.",
  ui_story_8_2_2_23_dialog_content = "Jadi, bagaimana pendapat kalian?",
  ui_story_8_2_2_24_dialog_content = "Aku sudah menyampaikan pendapatku. Terlalu berisiko kalau kita mengorbankan Lumopolis.",
  ui_story_8_2_2_25_dialog_content = "Apa pendapat Hall of Justice?",
  ui_story_8_2_2_26_dialog_content = "Aku akan mengikuti prinsip Resolution. Kalau sarannya diterima oleh ketiga pihak, aku akan mendukungnya.",
  ui_story_8_2_2_27_dialog_content = "Kalau tidak, Hall of Justice akan dengan tegas menolak usulnya, siapa pun orang yang mengajukannya.",
  ui_story_8_2_2_28_dialog_content = "Baiklah. Mari kita gelar rapat singkat untuk membahas masalah ini.",
  ui_story_8_2_2_29_dialog_content = "Otto, sebagai wakil dari Elder Council, aku yakin kau akan menolak usulan ini.",
  ui_story_8_2_2_30_dialog_content = "Tentu saja.",
  ui_story_8_2_2_31_dialog_content = "Irridon, sebagai Chief Judge dari Hall of Justice, apa keputusanmu?",
  ui_story_8_2_2_32_dialog_content = "Aku abstain.",
  ui_story_8_2_2_33_dialog_content = "Baiklah.",
  ui_story_8_2_2_34_dialog_content = "Terakhir, aku, Schwartz, City Lord di Lumopolis dan wakil dari keluarga bangsawan…",
  ui_story_8_2_2_35_dialog_content = "Dengan ini menolak usulan itu.",
  ui_story_8_2_2_36_dialog_content = "…!!",
  ui_story_8_2_2_37_dialog_content = "Dua pihak menolak, satu abstain. Hall of Justice tidak akan menindaklanjuti usulan ini.",
  ui_story_8_2_2_38_dialog_content = "Ayahmu jelas paham betapa pentingnya melindungi Lumopolis, Carleen.",
  ui_story_8_2_2_39_dialog_content = "Lelucon apa pula ini! Siapa sangka \"Three-Party Resolution\" ternyata dimulai dan diakhiri sebegitu mudahnya!",
  ui_story_8_2_2_40_dialog_content = "Saat terjadi krisis, keputusan tak harus diambil lewat proses yang kaku. Asalkan Hall of Justice hadir dan menerima hasil suara, keputusannya tetap valid.",
  ui_story_8_2_2_41_dialog_content = "Sekarang, tolong hargai keputusan kami, Carleen.",
  ui_story_8_2_2_42_dialog_content = "Tapi…",
  ui_story_8_2_2_43_dialog_content = "Kau sudah dengar, 'kan? Kita harus memberikan semua energi kita untuk menggunakannya, bahkan kita harus menonaktifkan perisai.",
  ui_story_8_2_2_44_dialog_content = "Itu artinya sama saja dengan bunuh diri! Setidaknya sekarang kita masih punya perisai.",
  ui_story_8_2_2_45_dialog_content = "Jujur saja, aku tak menyangka pemikiran putri City Lord ternyata sedangkal itu.",
  ui_story_8_2_2_46_dialog_content = "…",
  ui_story_8_2_2_47_dialog_content = "Carleen.",
  ui_story_8_2_2_48_dialog_content = "…",
  ui_story_8_2_2_49_dialog_content = "Angkat kepalamu dan lihat baik-baik, Carleen de Schwartz!",
  ui_story_8_2_2_50_dialog_content = "Ini Lumopolis! Bukan sekelompok petualang yang terbang ke sana kemari naik Colossus!",
  ui_story_8_2_2_51_dialog_content = "Kota ini tak butuh usul konyol seperti itu, paham?",
  ui_story_8_2_2_52_dialog_content = "…",
  ui_story_8_2_2_53_dialog_content = "Jawab pertanyaanku! Apa kau paham?!",
  ui_story_8_2_2_54_dialog_content = "Ya, Lord.",
  ui_story_8_2_2_55_dialog_content = "Sampai kita punya informasi lengkap tentang situasinya, strategi terbaik kita adalah mempertahankan perisai kita. Usulmu untuk mengaktifkan Damocles…",
  ui_story_8_2_2_56_dialog_content = "Sama sekali tak perlu dibahas.",
  ui_story_8_2_2_57_dialog_content = "Semua akan runtuh, dan kita tak akan bisa menghentikannya! Carleen, kau masih saja bertingkah seperti anak kecil. Rupanya kau belum belajar apa pun!",
  ui_story_8_2_2_58_dialog_content = "…?",
  ui_story_8_2_2_59_dialog_content = "Saat dulu kau jatuh dari rumah pohonmu karena berusaha menyelamatkan seekor kucing, kukira itulah puncak kebodohanmu.",
  ui_story_8_2_2_60_dialog_content = "Tapi, sekarang sudah jelas bahwa kau ternyata sama sekali belum bisa bersikap dewasa!",
  ui_story_8_2_2_61_dialog_content = "(Rumah pohon…?)",
  ui_story_8_2_2_62_dialog_content = "Walau kau memang berhasil menyelamatkan kucing itu dan mengambil keputusan yang tepat, apa untungnya?",
  ui_story_8_2_2_63_dialog_content = "Apakah sepadan kalau kau bertindak berlawanan dengan penilaian orang lain dan akhirnya kakimu patah demi menyelamatkan kucing itu?",
  ui_story_8_2_2_64_dialog_content = "(…?)",
  ui_story_8_2_2_65_dialog_content = "Aku bertanya padamu! Apakah sepadan?!",
  ui_story_8_2_2_66_dialog_content = "Apa-apaan ini, Schwartz? Kenapa kau malah mengungkit cerita keluarga di sini?",
  ui_story_8_2_2_67_dialog_content = "Memangnya aku bicara kepadamu, Otto Troy?",
  ui_story_8_2_2_68_dialog_content = "…",
  ui_story_8_2_2_69_dialog_content = "Ya.",
  ui_story_8_2_2_70_dialog_content = "Kurasa sepadan, Ayah.",
  ui_story_8_2_2_71_dialog_content = "Baiklah. Berarti kau memang sama sekali tak bisa diharapkan, Carleen.",
  ui_story_8_2_2_72_dialog_content = "Sana, kurung dirimu di menara gading itu, persis seperti kucingmu.",
  ui_story_8_2_2_73_dialog_content = "…",
  ui_story_8_2_2_74_dialog_content = "Wah, kata-kata Lord setajam pisau…",
  ui_story_8_2_2_75_dialog_content = "Tapi, buat apa dia mengungkit cerita masa lalu? Agak aneh 'kan, malah terdengar agak seram.",
  ui_story_8_2_2_77_dialog_content = "Kenapa kau malah tersenyum, Carleen? Makin seram jadinya!",
  ui_story_8_2_2_78_dialog_content = "Karena kurasa aku paham apa yang ingin disampaikannya kepadaku.",
  ui_story_8_2_2_79_dialog_content = "Hah?",
  ui_story_8_2_2_80_dialog_content = "Rumah pohon, kucing. Itu memang dulu terjadi.",
  ui_story_8_2_2_81_dialog_content = "Tapi…",
  ui_story_8_2_2_82_dialog_content = "Aku gagal menyelamatkan kucing itu.",
  ui_story_8_2_2_83_dialog_content = "Apa City Lord salah ingat? Atau jangan-jangan…",
  ui_story_8_2_2_84_dialog_content = "Mungkinkah…",
  ui_story_8_2_2_85_dialog_content = "City Lord mulai pikun!?",
  ui_story_8_2_2_86_dialog_content = "Rupanya kau tak paham, tapi tak apa. Ikut saja denganku, ada suatu tempat yang harus kita datangi.",
  ui_story_8_2_2_87_dialog_content = "Oke, siap! Ke mana?",
  ui_story_8_2_2_88_dialog_content = "…",
  ui_story_8_2_2_89_dialog_content = "Ke Ruang Kontrol Damocles.",
  ui_story_8_3_1_1_dialog_content = "<color=#e8d9bb>Di dalam Aviduz</color>",
  ui_story_8_3_1_2_dialog_content = "Heehee! Heehee♪",
  ui_story_8_3_1_3_dialog_content = "Maaf, aku agak terbawa suasana.",
  ui_story_8_3_1_4_dialog_content = "Sini, terus lewat sini! Aku juga baru pertama kali berkeliling di sini.",
  ui_story_8_3_1_5_dialog_content = "Kyuu!",
  ui_story_8_3_1_6_dialog_content = "(Curie bisa melacak bau Vivian. Kalau menurutnya kami harus ke arah ini…)",
  ui_story_8_3_1_7_dialog_content = "Terus saja. Mestinya ini jalan yang benar.",
  ui_story_8_3_1_8_dialog_content = "…",
  ui_story_8_3_1_9_dialog_content = "Ada apa? Kenapa kau menatapku begitu?",
  ui_story_8_3_1_10_dialog_content = "Kau yakin kau baik-baik saja? Aku nyaris tak sanggup menahan Darkflow di sini, tapi kau malah baik-baik saja?",
  ui_story_8_3_1_11_dialog_content = "Oh, aku baik-baik saja, sungguh!",
  ui_story_8_3_1_12_dialog_content = "Aneh, tapi Darkflow di sini nyaris tak memengaruhiku sama sekali. Sebaliknya, aku justru merasa…",
  ui_story_8_3_1_13_dialog_content = "Baunya cukup harum.",
  ui_story_8_3_1_14_dialog_content = "Hah?",
  ui_story_8_3_1_15_dialog_content = "Tapi, kulitku memang jadi agak gatal, sih. Menurutmu, apa ini gara-gara alergi?",
  ui_story_8_3_1_16_dialog_content = "Gatal? Coba kulihat.",
  ui_story_8_3_1_17_dialog_content = "Tak apa, yang paling gatal hanya punggungku. Kalau kau tak keberatan menggaruknya…",
  ui_story_8_3_1_18_dialog_content = "Tapi, yang lebih penting…",
  ui_story_8_3_1_19_option_content = [[
Kau merasa kurang nyaman,
ya? Vice?]],
  ui_story_8_3_1_20_dialog_content = "Selalu mengutamakan orang lain daripada dirimu sendiri, ya?",
  ui_story_8_3_1_21_dialog_content = "Aku baik-baik saja. Ini sulit, tapi tak ada yang lebih buruk selain saat Schummer menekanku.",
  ui_story_8_3_1_22_dialog_content = "Sejak itu, aku jadi makin dewasa, PlayerName.",
  ui_story_8_3_1_23_dialog_content = "Kuharap kita bisa terus mengatasi apa pun yang menghalangi jalan kita!",
  ui_story_8_3_1_24_dialog_content = "Tentu saja, kita pasti bisa. Kita tak akan berhenti sampai kita berhasil mengalahkan Schummer!",
  ui_story_8_3_1_25_dialog_content = "Nah, begitu, dong, PlayerName!",
  ui_story_8_3_1_26_option_content = "Aku ingin tahu bagaimana keadaan Carleen…",
  ui_story_8_3_1_27_dialog_content = "Sekarang, mestinya dia sudah sampai di Lumopolis.",
  ui_story_8_3_1_28_dialog_content = "Aku yakin, dia pasti juga sedang melawan Schummer dengan caranya sendiri.",
  ui_story_8_3_1_29_dialog_content = "Jadi, sebenarnya Damocles itu APA? Semacam senjata superkuat?",
  ui_story_8_3_1_30_dialog_content = "Aku sendiri juga belum pernah melihatnya, tapi aku pernah dengar tentang kekuatannya sewaktu aku masih belajar di sana.",
  ui_story_8_3_1_31_dialog_content = "Semua orang bilang, Damocles adalah strategi terakhir yang hanya akan digunakan saat situasi benar-benar sudah sangat genting.",
  ui_story_8_3_1_32_dialog_content = "Sepertinya kau juga tak tahu banyak tentang Damocles.",
  ui_story_8_3_1_33_option_content = "Di mana Chief Vivian?",
  ui_story_8_3_1_34_dialog_content = "Aku tak yakin, tapi melihat reaksi Curie, dia pasti ada di depan sana!",
  ui_story_8_3_1_35_dialog_content = "Curie pasti akan menuntun kita ke lokasi Vivian!",
  ui_story_8_3_1_36_dialog_content = "Kalau bukan berkat Vivian, kita mungkin sama sekali tak punya peluang untuk lolos.",
  ui_story_8_3_1_37_dialog_content = "Kau juga sudah berbuat sangat banyak untuk kami, dan pada akhirnya kau bahkan mengambil keputusan seperti itu.",
  ui_story_8_3_1_38_dialog_content = "Maksudmu saat aku mendorong kalian berdua keluar?",
  ui_story_8_3_1_39_dialog_content = "Mungkin itu hanya reaksi naluriah yang tak kusadari. Aku bahkan hampir lupa apa yang terjadi waktu itu.",
  ui_story_8_3_1_40_dialog_content = "Apa pun itu, kuharap kau tidak berbuat seperti itu lagi.",
  ui_story_8_3_1_41_dialog_content = "Kau selalu maju tanpa pikir panjang, seperti saat kau berusaha menyelamatkanku dan Gronru…",
  ui_story_8_3_1_42_dialog_content = "Kyuu!!!",
  ui_story_8_3_1_43_dialog_content = "Maaf, Curie terburu-buru. Ayo, percepat langkah kita!",
  ui_story_8_3_1_44_dialog_content = "PlayerName, kau benar-benar harus lebih memperhatikan kondisi fisikmu.",
  ui_story_8_3_1_46_dialog_content = "Aku paham! Tak usah mengkhawatirkanku!",
  ui_story_8_6_1_1_dialog_content = "Terang sekali…",
  ui_story_8_6_1_3_option_content = "Tidak! Aku harus sembunyi!",
  ui_story_8_6_1_4_dialog_content = "PlayerName? Sedang apa kau di pojok sana?",
  ui_story_8_6_1_5_dialog_content = "Sedang apa kau? Kemarilah!",
  ui_story_8_6_1_6_dialog_content = "Kyuu!",
  ui_story_8_6_1_7_dialog_content = "Maaf! Terang sekali, aku jadi agak linglung.",
  ui_story_8_6_1_8_dialog_content = "Terang? Ini cuma ruang biasa.",
  ui_story_8_6_1_9_dialog_content = "Kau tak sanggup menahannya?",
  ui_story_8_6_1_10_dialog_content = "Aku tak yakin. Baiklah, sepertinya mataku masih menyesuaikan dengan suasana di sini.",
  ui_story_8_6_1_11_option_content = "Aduh, gatalnya…",
  ui_story_8_6_1_12_dialog_content = "Jadi, sekarang matamu sudah kembali normal, tapi punggungmu malah gatal-gatal lagi?",
  ui_story_8_6_1_13_dialog_content = "Iya. Apa menurutmu aku harus memeriksakan diri kepada dokter?",
  ui_story_8_6_1_14_dialog_content = "Kita istirahat sebentar. Tak ada seorang pun di sini, jadi kita bisa berkumpul sebentar…",
  ui_story_8_6_1_15_dialog_content = "Kyuu!",
  ui_story_8_6_1_16_dialog_content = "Kau mau ke mana, Curie?",
  ui_story_8_6_1_17_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_6_1_18_dialog_content = "Apa itu Vivian? Apa dia ada di dalam sini?",
  ui_story_8_6_1_19_dialog_content = "Kyuu! Kyuu! Kyuu!",
  ui_story_8_6_1_20_dialog_content = "Kita akan cari cara untuk membuka pintu itu, Curie! Jangan panik! Kalau mereka sampai menemukan kita…",
  ui_story_8_6_1_21_dialog_content = "(Bau ini… Jangan-jangan…?)",
  ui_story_8_6_1_22_dialog_content = "Awas, Vice!!",
  ui_story_8_6_1_23_dialog_content = "Graaaah!",
  ui_story_8_6_1_24_dialog_content = "Mereka menuju persis ke arahmu!",
  ui_story_8_6_1_25_dialog_content = "Kena! Masih ada beberapa lagi, tapi kita tak bisa membiarkan mereka memperingatkan Eclipsite yang lain!",
  ui_story_8_6_1_26_dialog_content = "Basmi sisanya!",
  ui_story_8_6_1_27_dialog_content = "Serahkan padaku. Akan kuhabisi dengan cepat!",
  ui_story_8_6_2_1_dialog_content = "Bagus, kita tak menarik perhatian Eclipsite lagi.",
  ui_story_8_6_2_2_dialog_content = "Aku penasaran, apa ada di antara mereka yang berhasil melarikan diri.",
  ui_story_8_6_2_3_dialog_content = "Awas, di belakangmu!",
  ui_story_8_6_2_4_dialog_content = "Urraagh!",
  ui_story_8_6_2_5_dialog_content = "(Dia melewatiku begitu saja?!)",
  ui_story_8_6_2_6_dialog_content = "Fyuh. Sepertinya Darkflow memang memengaruhiku. Nyaris saja aku membiarkan satu Eclipsite lolos.",
  ui_story_8_6_2_7_dialog_content = "Anu, Vice…",
  ui_story_8_6_2_8_dialog_content = "Eclipsite itu lari melewatiku. Bukan, dia seakan-akan tak melihatku sama sekali!",
  ui_story_8_6_2_9_dialog_content = "Aku juga menyadarinya, dan bukan kali ini saja. Sepertinya mereka makin tak tertarik padamu.",
  ui_story_8_6_2_10_dialog_content = "Seakan-akan…",
  ui_story_8_6_2_11_dialog_content = "Mereka tak menganggapmu sebagai musuh.",
  ui_story_8_6_2_12_dialog_content = "…",
  ui_story_8_6_2_13_dialog_content = "Tapi, kenapa?",
  ui_story_8_6_2_14_dialog_content = "Aku tak yakin. Kau baik-baik saja, PlayerName? Apa kau merasa ada yang tidak nyaman?",
  ui_story_8_6_2_15_dialog_content = "Entahlah, Vice.",
  ui_story_8_6_2_16_dialog_content = "Kyuu!",
  ui_story_8_6_2_17_dialog_content = "Aku tahu, Curie, tapi PlayerName…",
  ui_story_8_6_2_18_dialog_content = "Aku baik-baik saja. Kalau Chief Vivian ada di sini, tugas utama kita adalah menyelamatkannya!",
  ui_story_8_7_1_A1_dialog_content = "Ibu? Ayah?",
  ui_story_8_7_1_A2_dialog_content = "Bukannya kota sudah runtuh? Syukurlah, kalian baik-baik saja.",
  ui_story_8_7_1_1_dialog_content = "Ya, terimalah. Biarkan dia mengubah mimpi terindahmu menjadi nyata.",
  ui_story_8_7_1_2_dialog_content = "Putih dan murni, ditandai dengan tanda asalnya. (Eclipsian) Hadiah ibu.",
  ui_story_8_7_1_3_dialog_content = "Kekuatan ini membuka kemampuan tersembunyi yang terpendam di balik tubuhmu, mengumpulkannya untuk menciptakan kekuatan tak tertandingi.",
  ui_story_8_7_1_4_dialog_content = "Yang lebih penting, kekuatan ini membawamu kepada kami, membuatmu menjadi bagian dari kami.",
  ui_story_8_7_1_5_dialog_content = "Cepat, datanglah ke kuil asal kita…",
  ui_story_8_7_1_6_dialog_content = "Aku tak peduli dengan apa yang kaumiliki. Menjauhlah darinya, Eclipsite!",
  ui_story_8_7_1_7_dialog_content = "Aurorian? Kapan kau sampai di sini?",
  ui_story_8_7_1_8_dialog_content = "Kau bisa mendengarku, Madam?",
  ui_story_8_7_1_9_dialog_content = "Mmm…",
  ui_story_8_7_1_10_dialog_content = "Syukurlah, kalian masih hidup!",
  ui_story_8_7_1_11_dialog_content = "Teman-temanmu itu berusaha keras menyelamatkanmu.",
  ui_story_8_7_1_12_dialog_content = "Atau, jangan-jangan mereka hanya menuruti panggilan Eclipse?",
  ui_story_8_7_1_A3_dialog_content = "Aku Solfall. Senang bisa menjadi Guide kalian.",
  ui_story_8_7_1_13_dialog_content = "\"Panggilan Eclipse\"? Kalau itu undangan untuk berubah menjadi Eclipsite keji seperti kalian, tidak usah saja, terima kasih!",
  ui_story_8_7_1_14_dialog_content = "(Eclipsian) Seharusnya kau berbalik sekarang, Caelestite!",
  ui_story_8_7_1_15_dialog_content = "Aku tak bisa memahami omonganmu. Kau bisa bahasa Universese?",
  ui_story_8_7_1_16_dialog_content = "Kenapa Master tidak memperingatkan kami? Tak ada peringatan satu pun. Apa yang sudah kauperbuat?",
  ui_story_8_7_1_17_dialog_content = "Itu kekuatanku, Eclipsite. Aku bisa membangun telepati dengan Aviduz sampai titik tertentu. Paham?",
  ui_story_8_7_1_18_dialog_content = "Asalkan tidak berisik, kami bisa tetap tak terdeteksi dan alarmnya tak akan berbunyi.",
  ui_story_8_7_1_19_dialog_content = "Ini perubahan tak terduga, tapi tak penting. Dari baumu…",
  ui_story_8_7_1_20_dialog_content = "Sebentar lagi kau akan menjadi seperti kami, Caelestite.",
  ui_story_8_7_1_21_dialog_content = "Maksudmu?",
  ui_story_8_7_1_F1_dialog_content = "PlayerName, jangan biarkan dia memengaruhi pikiranmu!",
  ui_story_8_7_1_22_dialog_content = "Apa yang kaulakukan pada Vivian? Benda yang bersinar itu apa?",
  ui_story_8_7_1_23_dialog_content = "(Eclipsian) Sebuah pertanyaan sia-sia.",
  ui_story_8_7_1_24_dialog_content = "Jangan menguji kesabaranku, Eclipsite! Aku tak punya waktu untuk bermain-main denganmu!",
  ui_story_8_7_1_25_dialog_content = "Ini karunia! Karunia dari sang Bunda!",
  ui_story_8_7_1_26_dialog_content = "Master kami merasakan sakit luar biasa demi melakukan ini. Dia bisa saja meremukkanmu dalam sekejap, tapi dia malah membiarkanmu hidup karena alasan tertentu.",
  ui_story_8_7_1_27_dialog_content = "Dia bahkan bermurah hati mengundangmu kemari dan memberimu kekuatan baru.",
  ui_story_8_7_1_28_dialog_content = "Ini kehormatan! Kehormatan tertinggi!!",
  ui_story_8_7_1_29_dialog_content = "\"Karunia dari sang Bunda\"? Apa maksudmu?!",
  ui_story_8_7_1_30_dialog_content = "Cukup sudah pertanyaannya! Sebentar lagi kau akan tahu.",
  ui_story_8_7_1_31_dialog_content = "Jangan bilang…",
  ui_story_8_7_1_32_dialog_content = "Jangan dengarkan sepatah kata pun darinya! Masih ada waktu. Ayo kalahkan mereka!",
  ui_story_8_7_1_33_dialog_content = "Lagi-lagi kau! Di mana kau?",
  ui_story_8_7_1_34_dialog_content = "Memangnya penting? Aku mungkin saja persis di belakangmu.",
  ui_story_8_7_1_35_dialog_content = "Kau! Kalau kau ingin tetap menjadi Caelestite, lakukan seperti kataku! Cepat habisi mereka!",
  ui_story_8_7_1_36_dialog_content = "(Eclipsian) Gemetar melihat pemandangan baru di hadapan Anda. Buang kebodohanmu yang memalukan!",
  ui_story_8_7_1_37_dialog_content = "Ugh!",
  ui_story_8_7_1_38_dialog_content = "Ada sesuatu yang bergerak di dalam tubuhku, Vice! Bukan, ini suatu kekuatan…",
  ui_story_8_7_1_39_dialog_content = "Suatu energi…",
  ui_story_8_7_1_40_dialog_content = "Tetap tenang dan fokus, PlayerName!",
  ui_story_8_7_1_41_dialog_content = "Argh! Kepalaku! Rasanya seperti terbelah jadi dua!",
  ui_story_8_7_1_43_dialog_content = "Kuat sekali! Kau harus melawannya, PlayerName!",
  ui_story_8_7_1_44_option_content = "Aku tahu, aku harus tetap sadar…",
  ui_story_8_7_1_45_dialog_content = "Kau terlambat. Rencana kami sudah membuahkan hasil.",
  ui_story_8_7_1_46_dialog_content = "Seed sudah berakar dan mulai bertunas. Sekarang pun aku bisa mendengar lolongannya.",
  ui_story_8_7_1_47_dialog_content = "Jiwa berharga baru untuk sang Bunda!",
  ui_story_8_7_1_48_option_content = "Jaga kesadaran…",
  ui_story_8_7_1_49_dialog_content = "Kyuu!!!",
  ui_story_8_7_1_51_dialog_content = "Ayo lakukan, Curie!",
  ui_story_8_7_1_52_dialog_content = "Sungguh kasihan. Tanpa si Caelestite itu, kalian bukan apa-apa!",
  ui_story_8_7_1_53_dialog_content = "Ugh!",
  ui_story_8_7_1_54_dialog_content = "PlayerName…",
  ui_story_8_7_1_55_dialog_content = "Sedang apa kau di sini?",
  ui_story_8_7_1_56_dialog_content = "Jangan sampai kalah begitu saja!",
  ui_story_8_7_1_57_dialog_content = "Kau ini Caelestite. Tak seorang pun bisa mengendalikanmu.",
  ui_story_8_7_1_58_option_content = "(Jaga kesadaran!)",
  ui_story_8_7_1_59_dialog_content = "…?",
  ui_story_8_7_1_60_dialog_content = "Nyaris saja aku hilang kendali.",
  ui_story_8_7_1_61_dialog_content = "Kau berhasil menghentikan transformasinya!?",
  ui_story_8_7_1_62_dialog_content = "Sst, diam!",
  ui_story_8_7_1_63_dialog_content = "Dari tadi kau bicara terus, kepalaku jadi pusing mendengarnya.",
  ui_story_8_7_1_64_dialog_content = "Tidak, mustahil! Bagaimana bisa kau melawan pengaruh Seed?",
  ui_story_8_7_1_65_dialog_content = "Yap, yap, yap… Cukup sudah.",
  ui_story_8_7_1_66_dialog_content = "Suaramu keras sekali, Schummer mungkin saja bisa mendengar kita.",
  ui_story_8_7_1_67_dialog_content = "Tapi, kurasa sekarang kau bisa berteriak sesukamu. Aku sudah membangun ulang telepati dengan Aviduz.",
  ui_story_8_7_1_F2_dialog_content = "Aku sudah mengontrol Colossus itu, dan ruang ini sudah kubuat sepenuhnya kedap suara.",
  ui_story_8_7_1_68_dialog_content = "Jeritanmu tak akan terdengar oleh telinga si Bundamu itu.",
  ui_story_8_7_1_69_dialog_content = "Syukurlah, kau sudah kembali normal, PlayerName.",
  ui_story_8_7_1_70_dialog_content = "Aku baik-baik saja sekarang. Maaf, tadi aku meninggalkanmu sendirian dengan makhluk itu.",
  ui_story_8_7_1_71_dialog_content = "Kepalaku mulai terasa sakit lagi, tapi kurasa aku masih bisa menahannya untuk sementara.",
  ui_story_8_7_1_73_dialog_content = "Dasar bodoh, tak tahu terima kasih! Pencemar karunia sang Bunda! Hanya ada satu tempat untuk sampah sepertimu!",
  ui_story_8_7_1_74_dialog_content = "Cepat atau lambat, kau AKAN jadi seperti kami!!",
  ui_story_8_7_1_75_dialog_content = "Bungkam makhluk itu, Vice.",
  ui_story_8_7_1_76_dialog_content = "Chief Vivian masih menunggu kita.",
  ui_story_8_7_1_77_dialog_content = "Baiklah!",
  ui_story_8_7_2_1_dialog_content = "Officer!",
  ui_story_8_7_2_2_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_7_2_4_dialog_content = "Hmm…",
  ui_story_8_7_2_5_dialog_content = "Chief, kondisimu tampak buruk. Aku benar-benar minta maaf, kami kemari secepat mungkin.",
  ui_story_8_7_2_6_dialog_content = "Mungkin sebaiknya kalian memikirkan diri sendiri sebelum memikirkan orang lain.",
  ui_story_8_7_2_7_dialog_content = "Siapa di sana?",
  ui_story_8_7_2_8_dialog_content = "Rupanya kau! Vice, aku sudah pernah melihatnya. Dialah yang menunjukkan jalan kepadaku.",
  ui_story_8_7_2_9_dialog_content = "Dia pria yang membawa koper putih yang tadi kausebutkan itu?",
  ui_story_8_7_2_10_dialog_content = "Aku bukan musuh kalian. Seperti yang kaulihat, aku ini Aurorian.",
  ui_story_8_7_2_11_dialog_content = "Kau bisa memanggilku Faust. Aku adalah abdi Truth.",
  ui_story_8_7_2_12_dialog_content = "Truth? Kok terdengar agak mencurigakan, ya?",
  ui_story_8_7_2_13_dialog_content = "Truth adalah prinsip abadi dan pasti dari ketertiban dan hukum untuk segala hal. Tak usah khawatir. Aku datang untuk membantu.",
  ui_story_8_7_2_14_dialog_content = "Perkenalanmu itu sama sekali tak membuat kami paham siapa kau sebenarnya.",
  ui_story_8_7_2_15_dialog_content = "Sekarang, itu tak penting. Fokuslah pada pikiranmu…",
  ui_story_8_7_2_16_dialog_content = "Seed di dalam dirimu mulai bertunas.",
  ui_story_8_7_2_17_dialog_content = "Sebenarnya apa sih Seed yang kalian bicarakan ini?!",
  ui_story_8_7_2_18_dialog_content = "Kujelaskan nanti saja. Sekarang kita harus mengatasinya dulu.",
  ui_story_8_7_2_19_dialog_content = "Tolong lepaskan pakaianmu, PlayerName.",
  ui_story_8_7_2_20_dialog_content = "Apa?",
  ui_story_8_7_2_21_dialog_content = "Sekarang bukan saatnya malu-malu. Tolong, lakukan saja sesuai kataku.",
  ui_story_8_7_2_22_dialog_content = "Apa kau merasakan sensasi aneh pada tubuhmu?",
  ui_story_8_7_2_23_dialog_content = "Yah, begitu kau tanya begitu, punggungku terasa gatal lagi.",
  ui_story_8_7_2_24_dialog_content = "Oh, rupanya dia ada di punggungmu.",
  ui_story_8_7_2_25_dialog_content = "Percayalah padaku, aku bisa menolongmu.",
  ui_story_8_7_2_26_option_content = "Baiklah, akan kulepaskan pakaianku.",
  ui_story_8_7_2_27_dialog_content = "…",
  ui_story_8_7_2_28_dialog_content = "Pakaian dalamnya juga, ya.",
  ui_story_8_7_2_29_dialog_content = "Apa aku perlu mengalihkan pandanganku, PlayerName?",
  ui_story_8_7_2_30_dialog_content = "Bukan apa-apa, hanya punggungnya saja. Jangan lama-lama.",
  ui_story_8_7_2_31_option_content = "Baiklah, akan kulepaskan pakaianku…",
  ui_story_8_7_2_32_dialog_content = "Yah…",
  ui_story_8_7_2_33_dialog_content = "Sudah kuduga.",
  ui_story_8_7_2_34_dialog_content = "Apa? Ada apa di punggungku?",
  ui_story_8_7_2_35_dialog_content = "Bisa tetap sadar dalam kondisi seperti ini, berarti entah kau ini sangat kuat atau sangat lambat.",
  ui_story_8_7_2_36_dialog_content = "Katakan padaku, apa yang terjadi!",
  ui_story_8_7_2_37_dialog_content = "Bisakah kau menariknya keluar, Vice?",
  ui_story_8_7_2_38_dialog_content = "Benda itu hampir mencapai bawah kulit, tapi karena kita masih bisa melihatnya, ayo kita keluarkan saja, tak perlu prosedur lembut.",
  ui_story_8_7_2_39_dialog_content = "Tunggu, aku 'kan tak pernah memberitahukan namaku padamu.",
  ui_story_8_7_2_40_dialog_content = "Memang, tapi itu tak penting, terutama untuk saat ini.",
  ui_story_8_7_2_41_dialog_content = "Apa kau merasakan aura bermusuhan dariku?",
  ui_story_8_7_2_42_dialog_content = "…",
  ui_story_8_7_2_43_dialog_content = "Baiklah. Mestinya aku bisa memaksa benda ini keluar, bukan masalah.",
  ui_story_8_7_2_44_dialog_content = "Hoi! Ada yang bisa memberitahuku apa yang terjadi?",
  ui_story_8_7_2_45_dialog_content = "Berhentilah menggeliat!",
  ui_story_8_7_2_46_dialog_content = "Giliranmu, Vice.",
  ui_story_8_7_2_47_dialog_content = "Ini mungkin akan terasa agak sakit, PlayerName.",
  ui_story_8_7_2_48_dialog_content = "Aduh!",
  ui_story_8_7_2_50_dialog_content = "(Sakit sekali sampai-sampai aku tak bisa bicara! Kaubilang ini \"agak sakit\"?)",
  ui_story_8_7_2_51_dialog_content = "Mundur, Vice! Jangan terlalu dekat…",
  ui_story_8_7_2_52_dialog_content = "Benda ini memang berbahaya, tapi juga menakjubkan.",
  ui_story_8_7_2_53_option_content = "Benda apa ini?",
  ui_story_8_7_2_54_dialog_content = "Eclipsite menyebutnya Seed.",
  ui_story_8_7_2_55_dialog_content = "Benda ini juga punya banyak sebutan lain, \"The Origin of Power,\" \"Mother's Kiss,\" \"The Mark of Ascension\", dan banyak lagi.",
  ui_story_8_7_2_56_dialog_content = "Apa pun namanya, yang jelas adalah Eclipsite menggunakannya untuk mendapatkan kekuatan luar biasa dan unik.",
  ui_story_8_7_2_57_dialog_content = "Yang lebih penting, benda ini bisa mencemari dan mengubah inangnya menjadi Eclipsite.",
  ui_story_8_7_2_58_dialog_content = "Mencemari… Itukah yang terjadi pada Gertzurde?",
  ui_story_8_7_2_59_dialog_content = "Bahkan Schummer?",
  ui_story_8_7_2_60_dialog_content = "Aku tak yakin apa maksudmu, tapi kalau mereka adalah makhluk Light yang mampu menerima kekuatan Darkness…",
  ui_story_8_7_2_61_dialog_content = "Seed itu pasti sudah berakar dalam diri mereka.",
  ui_story_8_7_2_62_option_content = "Jadi, kau menyembuhkanku, ya?",
  ui_story_8_7_2_63_dialog_content = "Bisa dibilang begitu. Walau sebenarnya, kalau bukan karena tekadmu yang kuat, kau pasti sudah berubah jadi Eclipsite sebelum aku sampai di sini.",
  ui_story_8_7_2_64_dialog_content = "Lagi pula, Seed sebenarnya bukan penyakit, tapi lebih merupakan kesadaran…",
  ui_story_8_7_2_65_dialog_content = "Bagaimana rasanya sekarang?",
  ui_story_8_7_2_66_dialog_content = "Harusnya kau merasa lebih baik, 'kan sudah…",
  ui_story_8_7_2_67_dialog_content = "Tidak, aku masih merasa tak nyaman.",
  ui_story_8_7_2_68_dialog_content = "Apa?",
  ui_story_8_7_2_69_dialog_content = "Aku merasa seakan-akan kehabisan udara, dan aku tak bisa bernapas. Dadaku terasa sesak, begitu juga tenggorokanku. Pandanganku juga masih kabur.",
  ui_story_8_7_2_70_dialog_content = "Itu wajar.",
  ui_story_8_7_2_71_dialog_content = "Darkflow di tempat ini memang sangat pekat. Wajar saja kalau Caelestite sepertimu bereaksi seperti ini terhadap Darkflow.",
  ui_story_8_7_2_72_dialog_content = "Sebelumnya, kau tak terpengaruh karena Seed ini pelan-pelan mengubahmu menjadi Eclipsite. Kau sudah paham sekarang?",
  ui_story_8_7_2_73_dialog_content = "Begitu, ya… *batuk*",
  ui_story_8_7_2_74_dialog_content = "Benda ini sangat berbahaya. Kita harus menghancurkannya!",
  ui_story_8_7_2_75_dialog_content = "Berhenti, Vice.",
  ui_story_8_7_2_76_dialog_content = "Bagi banyak orang, Seed memang racun, tapi bagi sebagian orang lain, ini harta karun… Misalnya bagiku.",
  ui_story_8_7_2_77_dialog_content = "…?!",
  ui_story_8_7_2_78_dialog_content = "Tenanglah, aku tak akan pernah menggunakannya pada makhluk hidup lain. Aku hanya penasaran tentang sifatnya.",
  ui_story_8_7_2_79_dialog_content = "Sebagai pencari Truth yang gigih, kami punya cara sendiri. Itu saja.",
  ui_story_8_7_2_80_dialog_content = "Dan Seed ini tak akan berbahaya, asalkan disimpan di dalam koperku.",
  ui_story_8_7_2_81_dialog_content = "Kopernya… bergerak?",
  ui_story_8_7_2_82_dialog_content = "Jangan khawatir, koper ini memang istimewa. Suatu hari nanti, rahasia kaum Aurorian dan Eclipsite akan terungkap.",
  ui_story_8_7_2_83_dialog_content = "Kita harus terus saling membantu sepanjang jalan kita menuju Truth.",
  ui_story_8_7_2_84_dialog_content = "Lagi-lagi kau berteka-teki. Bisa tidak sih kau langsung bilang saja apa yang akan kaulakukan dengan benda itu?",
  ui_story_8_7_2_85_dialog_content = "Aku yakin tak lama lagi kau akan tahu. Sampai jumpa lagi, PlayerName, Vice.",
  ui_story_8_7_2_86_dialog_content = "Semoga kalian berhasil meloloskan diri dengan lancar. Apa pun yang terjadi…",
  ui_story_8_7_2_87_dialog_content = "Aku sudah melihat gambaran bahwa sebentar lagi kalian bisa meloloskan diri dengan heroik.",
  ui_story_8_7_2_88_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_8_7_2_89_dialog_content = "Vice?",
  ui_story_8_7_2_90_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_7_2_91_dialog_content = "Chief! Maaf, tadi aku sedang mengobati luka PlayerName…",
  ui_story_8_7_2_92_dialog_content = "Yah, sepertinya aku tak sengaja mendengar pembicaraan kalian. Apa PlayerName baik-baik saja?",
  ui_story_8_7_2_F1_dialog_content = "PlayerName sekarang baik-baik saja. Bagaimana denganmu, Chief?",
  ui_story_8_7_2_F2_dialog_content = "Aku juga baik-baik saja. Tadi aku sempat terjebak ilusi, tapi sekarang aku sudah kembali normal.",
  ui_story_8_7_2_93_dialog_content = "Kyuu!",
  ui_story_8_7_2_94_dialog_content = "Kau pasti khawatir setengah mati, Curie.",
  ui_story_8_7_2_95_dialog_content = "Maafkan aku, kalian terpaksa menghadapi masalah besar gara-gara aku.",
  ui_story_8_7_2_96_option_content = "Bukan masalah.",
  ui_story_8_7_2_97_dialog_content = "Kalau bukan berkat upayamu, Chief, kami mungkin sama sekali tak punya peluang untuk lolos.",
  ui_story_8_7_2_98_dialog_content = "Jadi, kalian memutuskan kembali dan menyelamatkanku?",
  ui_story_8_7_2_99_dialog_content = "Banyak yang terjadi setelah itu. Akan kuceritakan semuanya setelah kita keluar dari sini!",
  ui_story_8_7_2_100_dialog_content = "Bagaimana dengan Forsakin dan cewek psikopat itu?",
  ui_story_8_7_2_101_dialog_content = "Schummer? Mereka tidak ada di dekat sini, tapi cepat atau lambat mereka pasti akan menemukan kita.",
  ui_story_8_7_2_102_dialog_content = "Mungkin sekarang Schummer sudah menyadari keributan ini. Kita harus pergi sekarang juga!",
  ui_story_8_7_2_103_option_content = "Semuanya baik-baik saja sekarang, Chief.",
  ui_story_8_7_2_104_dialog_content = "Semuanya baik-baik saja. Kami berhasil menghentikan Eclipsite itu agar tak memasukkan Seed ke dalam tubuhmu.",
  ui_story_8_7_2_105_dialog_content = "Seed? Maksudmu benda yang tadi kalian bicarakan itu?",
  ui_story_8_7_2_106_dialog_content = "Pertama-tama, ayo keluar dulu dari sini. Nanti kuceritakan detailnya setelah kita aman.",
  ui_story_8_7_2_107_dialog_content = "Baiklah. Kalau begitu, kupercayakan padamu.",
  ui_story_8_7_2_108_dialog_content = "Oh, bagaimana dengan Forsakin? Dan si cewek sinting kuat itu?",
  ui_story_8_7_2_109_dialog_content = "Mereka masih jauh, tapi kita tak boleh lengah.",
  ui_story_8_7_2_110_dialog_content = "Mungkin sekarang Schummer sudah menyadari keributan ini. Kita harus pergi sekarang juga!",
  ui_story_8_7_2_111_dialog_content = "Jadi, pilihan kita adalah meloloskan diri, bukannya menghadapi musuh?",
  ui_story_8_7_2_112_dialog_content = "Setelah kita kembali ke Gannon City, aku harus melaporkan semuanya kepada Grand Marshal dan menanggung hukuman atas semua ini.",
  ui_story_8_7_2_113_dialog_content = "…",
  ui_story_8_7_2_114_dialog_content = "Tusuk, cabik-cabik, dan hancurkan mereka sampai jadi debu.",
  ui_story_8_7_2_115_dialog_content = "Semua aturan kosong, moralitas, dan kota keji penuh kebencian di hadapan kita itu akan remuk sampai jadi debu.",
  ui_story_8_7_2_116_dialog_content = "Tunggu saja, PlayerName.",
  ui_story_8_7_2_117_dialog_content = "Biarlah sepasang mata Caelestite terakhir itu menjadi saksi pemandangan sengeri neraka itu.",
  ui_story_8_7_2_118_dialog_content = "Biarlah ingatan itu tertanam di genmu yang payah dan rendahan itu.",
  ui_story_8_8_1_1_dialog_content = "Ini Lumopolis! Bukan sekelompok petualang yang terbang ke sana kemari naik Colossus!",
  ui_story_8_8_1_2_dialog_content = "Saat dulu kau jatuh dari rumah pohonmu karena berusaha menyelamatkan seekor kucing, kukira itulah puncak kebodohanmu.",
  ui_story_8_8_1_3_dialog_content = "Walau kau memang berhasil menyelamatkan kucing itu dan mengambil keputusan yang tepat, apa untungnya?",
  ui_story_8_8_1_4_dialog_content = "Aku bertanya padamu! Apakah sepadan?!",
  ui_story_8_8_1_5_dialog_content = "…",
  ui_story_8_8_1_6_dialog_content = "Semoga saja aku tak salah memahami maksud perkataannya.",
  ui_story_8_8_1_7_dialog_content = "Tak bisa dipercaya, baru sekali ini dia bicara seperti itu.",
  ui_story_8_8_1_8_dialog_content = "Kalaupun ternyata salah memahami kata-katanya, Carleen, kurasa sekarang kau sudah tak bisa berbalik.",
  ui_story_8_8_1_9_dialog_content = "Toh kita sudah sampai sini.",
  ui_story_8_8_1_10_dialog_content = "Di dalam Ruang Kontrol Damocles.",
  ui_story_8_8_1_11_dialog_content = "Benar. Kalau ada yang memergokimu, bilang saja aku yang memaksamu melakukannya.",
  ui_story_8_8_1_12_dialog_content = "Si hebat Raphael tak peduli dengan hal sepele seperti itu!",
  ui_story_8_8_1_13_dialog_content = "Kadang matamu bersinar penuh keyakinan, Carleen, persis seperti sekarang ini.",
  ui_story_8_8_1_14_dialog_content = "Setiap kali merasa ragu, aku hanya perlu menatap matamu, dan aku langsung tahu bahwa aku bisa mengikutimu tanpa ragu!",
  ui_story_8_8_1_15_dialog_content = "Tak penting apakah keputusannya benar atau salah, yang penting adalah kita harus mengumpulkan keberanian untuk mengambil keputusan. Iya, 'kan?",
  ui_story_8_8_1_16_dialog_content = "…",
  ui_story_8_8_1_17_dialog_content = "Pernyataanmu cukup filosofis, walau sebenarnya sangat tidak masuk akal.",
  ui_story_8_8_1_18_dialog_content = "…",
  ui_story_8_8_1_19_dialog_content = "Hoi, Michael! Kau datang tepat waktu!",
  ui_story_8_8_1_20_dialog_content = "…",
  ui_story_8_8_1_21_dialog_content = "Terima kasih, Michael. Aku tak bisa berharap semua anggota Guardians akan membantuku, tapi kau saja sudah lebih dari cukup.",
  ui_story_8_8_1_22_dialog_content = "Michael bisa diandalkan! Terutama karena dia tak banyak tanya. Iya, 'kan?",
  ui_story_8_8_1_23_dialog_content = "…",
  ui_story_8_8_1_24_dialog_content = "Bagaimana situasi di luar sana? Apa perisainya masih kokoh?",
  ui_story_8_8_1_25_dialog_content = "…",
  ui_story_8_8_1_26_dialog_content = "Menurut laporan terbaru, perisainya tampak sudah melemah.",
  ui_story_8_8_1_27_dialog_content = "Aku tak percaya mereka berhasil menembus pembatas Lumina yang kuat itu. Mengesankan sekali.",
  ui_story_8_8_1_28_dialog_content = "Dia bukan lagi Schummer yang dulu, dan dulu pun aku gagal menghentikannya.",
  ui_story_8_8_1_29_dialog_content = "Tapi kali ini, aku yakin aku bisa menghentikannya!",
  ui_story_8_8_1_30_dialog_content = "Benar! Aku juga akan berusaha sebaik mungkin!",
  ui_story_8_8_1_31_dialog_content = "Michael juga siap berangkat!",
  ui_story_8_8_1_32_dialog_content = "…",
  ui_story_8_8_1_33_dialog_content = "Nah. Tugasnya sangat mudah, kalian berdua…",
  ui_story_8_8_1_34_dialog_content = "Bantu aku memblokir pintu masuk ke ruang kontrol. Jangan biarkan seorang pun masuk ke sana!",
  ui_story_8_8_1_35_dialog_content = "Setelah Damocles berhasil kuaktifkan, dia akan mengalirkan semua energi Lumopolis ke sini.",
  ui_story_8_8_1_36_dialog_content = "Perisainya hanya akan nonaktif sebentar saja, tapi itu saja sudah akan membuat warga panik.",
  ui_story_8_8_1_37_dialog_content = "Raphael, bisakah kaupanggil lagi anggota Guardians yang lain?",
  ui_story_8_8_1_38_dialog_content = "Suruh mereka melindungi area-area lain di Lumopolis sementara Damocles mengisi daya!",
  ui_story_8_8_1_39_dialog_content = "Tentu, akan kucoba sekali lagi!",
  ui_story_8_8_1_40_dialog_content = "Fokus saja untuk melakukan apa yang menurutmu benar, Carleen!",
  ui_story_8_8_1_41_dialog_content = "Aku mengandalkanmu. Sekarang tempat ini jadi tanggung jawabmu.",
  ui_story_8_8_1_42_dialog_content = "…",
  ui_story_8_8_1_43_dialog_content = "Ayah, mungkin ini hal tergila yang pernah kulakukan.",
  ui_story_8_8_1_44_dialog_content = "Tapi, aku sangat yakin…",
  ui_story_8_8_1_45_dialog_content = "Melindungi orang-orang yang kusayangi dengan caraku sendiri…",
  ui_story_8_8_1_46_dialog_content = "Adalah pilihan yang tepat, selalu!",
  ui_story_8_8_1_47_dialog_content = "<color=#e8d9bb>Di luar Ruang Kontrol</color>",
  ui_story_8_8_1_48_dialog_content = "Seperti dugaan kita, dia masuk ke sana, Chief Judge.",
  ui_story_8_8_1_49_dialog_content = "…",
  ui_story_8_8_1_50_dialog_content = "Apa yang harus kita lakukan? Dalam situasi seperti ini…",
  ui_story_8_8_1_51_dialog_content = "Kalau Carleen hanya masuk ke ruang kontrol Damocles dan tidak berbuat hal lain, berarti dia tak melanggar aturan, 'kan?",
  ui_story_8_8_1_52_dialog_content = "Sebagai Kapten di Guardians, dia berhak pergi ke mana pun.",
  ui_story_8_8_1_53_dialog_content = "Kalau dia sampai mengaktifkan Damocles, nah, itu lain soal.",
  ui_story_8_8_1_54_dialog_content = "Tapi, kalau begitu, berarti sudah terlambat!",
  ui_story_8_8_1_55_dialog_content = "Terlambat?",
  ui_story_8_8_1_56_dialog_content = "Lumopolis dibangun berdasarkan hukum dan aturan. Bagi orang-orang yang melanggar hukum Lumopolis dan bertindak seenak jidat mereka…",
  ui_story_8_8_1_57_dialog_content = "Sudah terlambat bagi mereka.",
  ui_story_8_8_1_58_dialog_content = "Kami paham. Kami akan menunggu perintah.",
  ui_story_8_8_1_59_dialog_content = "Bersiaplah untuk mengerahkan satu detasemen pasukan untuk membantu area-area lain.",
  ui_story_8_8_1_60_dialog_content = "Bala bantuan?",
  ui_story_8_8_1_61_dialog_content = "Kalau sampai dia mengaktifkan Damocles, pertahanan Lumopolis akan nonaktif selama beberapa saat.",
  ui_story_8_8_1_62_dialog_content = "Apa ini akan jadi peluang bagi kita untuk selamat, atau justru akan menjerumuskan kita ke neraka?",
  ui_story_8_8_1_63_dialog_content = "Carleen de Schwartz…",
  ui_story_8_9_1_1_dialog_content = "Lewat sini! Kalau aku tak salah mengingat rutenya, kita…",
  ui_story_8_9_1_2_dialog_content = "Tunggu, Vice.",
  ui_story_8_9_1_3_dialog_content = "Ada apa?",
  ui_story_8_9_1_4_dialog_content = "Kita harus berhenti sebentar.",
  ui_story_8_9_1_5_dialog_content = "Kita tak bisa berhenti, Chief! Kita tak boleh membuang waktu sedetik pun! Sini, biar kugendong saja kau!",
  ui_story_8_9_1_6_dialog_content = "Bukan, bukan itu maksudku. Kita sebenarnya ada di bagian mana di dalam Aviduz?",
  ui_story_8_9_1_7_dialog_content = "Ah… Mestinya sih sekarang kita sudah dekat pintu masuk.",
  ui_story_8_9_1_8_dialog_content = "Apa dia sedang bertarung?",
  ui_story_8_9_1_9_dialog_content = "Sepertinya Aviduz mungkin sedang menyerang perisai Lumopolis.",
  ui_story_8_9_1_10_dialog_content = "Cepat atau lambat, perisai itu akan runtuh…",
  ui_story_8_9_1_11_dialog_content = "Kira-kira apa rencana Lumopolis untuk membendungnya?",
  ui_story_8_9_1_12_dialog_content = "Carleen sudah kembali ke sana dan berusaha mengaktifkan Damocles.",
  ui_story_8_9_1_13_dialog_content = "Ternyata akhirnya jadi seperti ini.",
  ui_story_8_9_1_14_dialog_content = "Ya. Daya Aviduz sudah terisi penuh.",
  ui_story_8_9_1_15_dialog_content = "…",
  ui_story_8_9_1_16_dialog_content = "Bagaimana dengan Schummer? Apa dia sudah menyadari keberadaan kita?",
  ui_story_8_9_1_17_dialog_content = "PlayerName masih memanfaatkan kemampuan psikisnya untuk membatasi Colossus ini.",
  ui_story_8_9_1_18_dialog_content = "Benar, tapi yang bisa dibatasinya hanya kemampuan Aviduz untuk memantau bagian dalamnya. Karena Schummer terhubung dengan Aviduz, mereka berdua tak sadar bahwa kita berusaha meloloskan diri.",
  ui_story_8_9_1_19_dialog_content = "Sulit mengira-ngira berapa banyak kekuatan yang harus kupakai. Kalau aku menggunakannya sembarangan, Schummer mungkin saja akan sadar bahwa ada yang tak beres.",
  ui_story_8_9_1_20_dialog_content = "Itu berarti sekarang keadaan sudah berbalik.",
  ui_story_8_9_1_21_dialog_content = "Musuh terlihat jelas, sedangkan kita bersembunyi di balik bayangan.",
  ui_story_8_9_1_22_dialog_content = "Vivian, maksudmu…",
  ui_story_8_9_1_23_dialog_content = "Kita tak akan pergi, Vice.",
  ui_story_8_9_1_24_dialog_content = "Apa?",
  ui_story_8_9_1_25_dialog_content = "Apa kau sudah lupa prinsip dasar perang? Kitalah satu-satunya yang bisa…",
  ui_story_8_9_1_26_dialog_content = "Mengalahkan musuh dari dalam!",
  ui_story_8_9_1_27_dialog_content = "Tapi, Chief, kondisimu tak memungkinkan…",
  ui_story_8_9_1_28_dialog_content = "Ini bukan saatnya mengkhawatirkanku.",
  ui_story_8_9_1_29_dialog_content = "Kita tak boleh menyia-nyiakan kesempatan ini. Kalau kita berhasil, mungkin kita bisa menyelamatkan seluruh kota.",
  ui_story_8_9_1_30_dialog_content = "…",
  ui_story_8_9_1_31_dialog_content = "Kalian sendiri pasti bisa mempertimbangkan untung ruginya pilihan ini, 'kan?",
  ui_story_8_9_1_32_dialog_content = "Biasanya kau ini tenang dan tegas, Vice. Tapi, belakangan kau jadi ragu-ragu.",
  ui_story_8_9_1_33_dialog_content = "Chief, aku hanya tak ingin meninggalkan siapa pun. Lagi pula, kau…",
  ui_story_8_9_1_34_dialog_content = "Kalau begitu, coba kutanya, seandainya ada di posisiku, apa kau akan membiarkan kita menyia-nyiakan kesempatan emas seperti ini?",
  ui_story_8_9_1_35_dialog_content = "Anu…",
  ui_story_8_9_1_36_dialog_content = "Lagi pula, berkat PlayerName, lukaku sekarang mulai pulih.",
  ui_story_8_9_1_37_dialog_content = "Musuh ada di depan mata, Vice. Kenapa kita malah berbalik dan lari sekarang?",
  ui_story_8_9_2_1_dialog_content = "<color=#e8d9bb>Beberapa Tahun Lalu di Lumopolis</color>",
  ui_story_8_9_2_2_dialog_content = "(\"Lindungi orang-orang yang kusayangi dengan caraku sendiri…\")",
  ui_story_8_9_2_3_dialog_content = "…",
  ui_story_8_9_2_4_dialog_content = "Tapi…",
  ui_story_8_9_2_5_dialog_content = "Dia mati.",
  ui_story_8_9_2_6_dialog_content = "Semua makhluk hidup akhirnya akan mati, Carleen.",
  ui_story_8_9_2_7_dialog_content = "Aku gagal menyelamatkannya. Kalau saja aku sedikit lebih hati-hati…",
  ui_story_8_9_2_8_dialog_content = "Dia melompat dari rumah pohon itu karena takut, Carleen. Ini bukan salahmu.",
  ui_story_8_9_2_9_dialog_content = "Tapi, mestinya aku bisa menyelamatkannya… Aku tahu aku pasti bisa!",
  ui_story_8_9_2_10_dialog_content = "Sepertinya tak ada gunanya menjelaskan pada anak kecil yang sedang menangis.",
  ui_story_8_9_2_11_dialog_content = "Kalau ada yang bisa kaupelajari dari kejadian ini, ingatlah bahwa kau tak boleh menyesali apa yang \"mestinya bisa kaulakukan\", tapi ingatlah bahwa kau harus lebih dulu melindungi dirimu sendiri sebelum menyelamatkan orang lain.",
  ui_story_8_9_2_F1_dialog_content = "Apa kau tahu berapa banyak orang yang mengkhawatirkan keselamatanmu?",
  ui_story_8_9_2_12_dialog_content = "Kalian berdua jatuh dari rumah pohon dan kucing itu mati, tapi kau sama sekali tak terluka walau jatuh dari sana.",
  ui_story_8_9_2_13_dialog_content = "Sebenarnya keluarga Schwartz ini monster atau apa, sih?",
  ui_story_8_9_2_14_dialog_content = "Apa pun itu, bersikap baiklah, tunggu saja di sini. Aku sudah memberi tahu ayahmu, dan akan kuminta dokter untuk memeriksamu nanti.",
  ui_story_8_9_2_15_dialog_content = "Pak Otto.",
  ui_story_8_9_2_16_dialog_content = "Ya?",
  ui_story_8_9_2_17_dialog_content = "Boleh aku bertanya?",
  ui_story_8_9_2_18_dialog_content = "Katakan.",
  ui_story_8_9_2_19_dialog_content = "Apa Anda ada di sana saat ibuku meninggal?",
  ui_story_8_9_2_20_dialog_content = "…",
  ui_story_8_9_2_21_dialog_content = "Tidak, Carleen, aku tidak di sana. Ayahmulah satu-satunya yang ada di sana waktu itu.",
  ui_story_8_9_2_22_dialog_content = "…",
  ui_story_8_9_2_23_dialog_content = "Harusnya waktu itu aku pergi ke Northland. Harusnya aku tetap bersamanya dan melindunginya.",
  ui_story_8_9_2_24_dialog_content = "Kalau saja aku melindunginya, mungkin dia tak akan…",
  ui_story_8_9_2_25_dialog_content = "Kalaupun ada bersamanya, kau mungkin tetap tak bisa mengubah apa pun.",
  ui_story_8_9_2_26_dialog_content = "Apa?",
  ui_story_8_9_2_27_dialog_content = "Memang itulah kenyataannya. Bahkan Schwartz sendiri pun tak mampu mengubah keadaan, jadi kenapa kaukira kau bisa mengubahnya?",
  ui_story_8_9_2_28_dialog_content = "Apa maksud Anda, aku ini hanya anak-anak yang tak bisa melindungi siapa pun?",
  ui_story_8_9_2_29_dialog_content = "Kalau memang iya, kenapa?",
  ui_story_8_9_2_30_dialog_content = "…",
  ui_story_8_9_2_31_dialog_content = "Yang mati itu 'kan cuma kucing, Carleen.",
  ui_story_8_9_2_32_dialog_content = "Lain kali, jangan pergi sendirian. Kau ini putri dari keluarga bangsawan.",
  ui_story_8_9_2_33_dialog_content = "…",
  ui_story_8_9_2_34_dialog_content = "Carleen!",
  ui_story_8_9_2_35_dialog_content = "Lanjutkan.",
  ui_story_8_9_2_36_dialog_content = "Hall of Justice mengepung kita!",
  ui_story_8_9_2_37_dialog_content = "Oh, ya? Apa mereka sudah mengambil tindakan?",
  ui_story_8_9_2_38_dialog_content = "Belum, tapi mereka mengawasi setiap gerakan kita. Firasatku tak enak soal ini!",
  ui_story_8_9_2_39_dialog_content = "Chief Judge Irridon juga ada di sana.",
  ui_story_8_9_2_40_dialog_content = "…",
  ui_story_8_9_2_41_dialog_content = "Siagalah, Raphael dan Michael.",
  ui_story_8_9_2_42_dialog_content = "Ya!",
  ui_story_8_9_2_43_dialog_content = "Awasi pintu itu dan jangan biarkan siapa pun masuk ke ruang kontrol Damocles, paham?",
  ui_story_8_9_2_44_dialog_content = "Paham!",
  ui_story_8_9_2_45_dialog_content = "Damocles…",
  ui_story_8_9_2_46_dialog_content = "Kumohon, berubahlah menjadi pedang berkilau dan koyakkan kegelapan yang mengepung kami.",
  ui_story_8_9_2_47_dialog_content = "Damocles, <color=#FFB400>aktifkan</color>!",
  ui_story_8_10_1_1_dialog_content = "Apa yang terjadi?",
  ui_story_8_10_1_2_dialog_content = "Mati listrik?",
  ui_story_8_10_1_3_dialog_content = "Ruang kontrol… Ruang kontrol Damocles!",
  ui_story_8_10_1_4_dialog_content = "Jangan berdiri saja, dasar bodoh! Sana, cari tahu apa yang terjadi!",
  ui_story_8_10_1_5_dialog_content = "…",
  ui_story_8_10_1_6_dialog_content = "Schwartz, kalau ini memang perbuatan Carleen, kau pasti tahu konsekuensinya, 'kan?!",
  ui_story_8_10_1_7_dialog_content = "Dia bertindak bukan atas perintahku. Dia sepenuhnya sadar dan bertindak atas kemauannya sendiri.",
  ui_story_8_10_1_8_dialog_content = "Tapi, mestinya kau tak melalaikan tanggung jawabmu!",
  ui_story_8_10_1_9_dialog_content = "Mana Irridon? Biarkan Hall of Justice…",
  ui_story_8_10_1_10_dialog_content = "Chief Judge ada di pintu masuk ruang kontrol!",
  ui_story_8_10_1_11_dialog_content = "Lumopolis Gardens kacau balau! Para bangsawan panik…",
  ui_story_8_10_1_12_dialog_content = "Berlakukan perintah publik, dan minta semua orang tetap tenang! Kalaupun Damocles sudah diaktifkan, energi Lumopolis tak akan langsung…",
  ui_story_8_10_1_14_dialog_content = "Kotanya turun?!",
  ui_story_8_10_1_15_dialog_content = "Daya kota ini mengalir ke dalam Damocles, termasuk daya di sistem penggerak kita.",
  ui_story_8_10_1_16_dialog_content = "Aku tahu! Sekarang, lakukan sesuatu untuk mengatasinya!",
  ui_story_8_10_1_17_dialog_content = "Aku sudah memerintahkan Guardians untuk bersiaga di setiap distrik Lumopolis dan bersiap mempertahankan kota. Atau, kau lebih suka memberiku wewenang untuk mengerahkan Elder Council juga?",
  ui_story_8_10_1_18_dialog_content = "Kau…!",
  ui_story_8_10_1_19_dialog_content = "Lord Schwartz! Lord Otto! Perisainya…",
  ui_story_8_10_1_20_dialog_content = "<color=#e8d9bb>Sementara itu, di dalam Aviduz</color>",
  ui_story_8_10_1_22_dialog_content = "Apa itu?",
  ui_story_8_10_1_23_dialog_content = "Apa Aviduz barusan bergerak? Apa yang terjadi?",
  ui_story_8_10_1_24_dialog_content = "Kyuu!",
  ui_story_8_10_1_25_dialog_content = "…",
  ui_story_8_10_1_26_dialog_content = "Perisai Lumopolis mulai runtuh.",
  ui_story_8_10_1_27_dialog_content = "Kau yakin? Jadi, Carleen berhasil mengaktifkan Damocles?",
  ui_story_8_10_1_28_dialog_content = "Atau, mungkin saja Schummer berhasil menembus perisai. Kita tak tahu pasti apa yang sebenarnya terjadi.",
  ui_story_8_10_1_29_dialog_content = "Aku yakin itu pasti karena Carleen berhasil!",
  ui_story_8_10_1_30_dialog_content = "Tunggu, kenapa perisainya hilang?",
  ui_story_8_10_1_31_dialog_content = "Damocles harus mengisi daya dengan cara menyerap hampir seluruh daya di Lumopolis, termasuk daya yang digunakan untuk mengaktifkan perisai itu.",
  ui_story_8_10_1_32_dialog_content = "Tapi, itu hanya beberapa saat saja. Bertahanlah sebentar lagi.",
  ui_story_8_10_1_34_dialog_content = "Ada masalah, Schummer sudah menyadari keberadaan kita!",
  ui_story_8_10_1_35_dialog_content = "Maaf, aku tak menyangka Aviduz akan bergerak begitu tiba-tiba, jadi aku tak bisa…",
  ui_story_8_10_1_36_dialog_content = "PlayerName!!",
  ui_story_8_10_1_37_dialog_content = "Schummer!",
  ui_story_8_10_1_38_dialog_content = "Kapan kalian keluar?",
  ui_story_8_10_1_39_dialog_content = "Jawab aku dulu. Apa yang telah kaulakukan?!",
  ui_story_8_10_1_40_dialog_content = "Kenapa kau tak mau menerima takdirmu? Kenapa kau terus bersikeras melawannya!?",
  ui_story_8_10_1_41_dialog_content = "Kau dan perisai kota sialan ini memang sama. Pada akhirnya, kalian akan hancur dan menyerah kepadaku!",
  ui_story_8_10_1_42_dialog_content = "Kaukira kau berhasil meruntuhkan perisai Lumopolis? Kau…",
  ui_story_8_10_1_43_dialog_content = "(Tunggu, mungkin dia belum tahu tentang Damocles!)",
  ui_story_8_10_1_F1_dialog_content = "Ha! Sudah kausaksikan sendiri kekuatan Aviduz, 'kan?",
  ui_story_8_10_1_44_dialog_content = "Apa kau tak penasaran, PlayerName? Apa kau tak ingin tahu kenapa aku membiarkanmu hidup setelah menghajarmu berkali-kali?",
  ui_story_8_10_1_45_dialog_content = "…",
  ui_story_8_10_1_46_dialog_content = "Awalnya, itu karena aku kasihan padamu, karena kau sangat lemah. Setelahnya, itu karena aku marah, bahkan benci.",
  ui_story_8_10_1_47_dialog_content = "Tapi, aku sudah muak dengan semua itu. Pada akhirnya, yang kuinginkan hanyalah membuktikan kemampuanku padamu dan kaummu.",
  ui_story_8_10_1_48_dialog_content = "Kekuatan sejati bukanlah kekuatan yang selama ini kalian sebut-sebut itu!",
  ui_story_8_10_1_49_dialog_content = "Aku sama sekali tak paham maksudmu!",
  ui_story_8_10_1_50_dialog_content = "Oh, kau akan paham.",
  ui_story_8_10_1_51_dialog_content = "Sebentar lagi kau akan tahu.",
  ui_story_8_10_1_52_dialog_content = "Ada apa, PlayerName? Kau baik-baik saja? Bangunlah!",
  ui_story_8_10_1_53_dialog_content = "Jangan khawatir, aku masih sadar. Aku hanya sedang berbicara dengan Schummer.",
  ui_story_8_10_1_54_dialog_content = "Dia berhasil menemukan kita. Ayo, kita harus menghentikannya sekarang juga!",
  ui_story_8_10_1_55_dialog_content = "Setuju. Cepat, kita harus bergerak!",
  ui_story_8_10_1_56_dialog_content = "Kyuu!",
  ui_story_8_10_1_57_dialog_content = "Kita hanya perlu mengalihkan perhatian dan menyibukkan Schummer selama mungkin, 'kan?",
  ui_story_8_10_1_58_dialog_content = "Semoga kita bisa mengulur waktu untuk Carleen.",
  ui_story_8_10_2_1_dialog_content = "Awas, Chief!",
  ui_story_8_10_2_2_dialog_content = "Maaf, tubuhku masih terasa kaku, jadi sekarang ini aku tak begitu berguna untuk kalian.",
  ui_story_8_10_2_3_dialog_content = "Kau tunggu kami di sini saja, Chief. Makin dekat jarak kita ke Bridge, makin banyak Eclipsite yang akan menghalangi.",
  ui_story_8_10_2_4_dialog_content = "Jangan meremehkanku, Vice. Mana mungkin aku membiarkanmu bertarung sendirian?",
  ui_story_8_10_2_5_dialog_content = "Pegangan yang kencang!",
  ui_story_8_10_2_6_dialog_content = "Sekarang dia sedang fokus menyerang Lumopolis! Kita tak tahu seperti apa situasi di luar.",
  ui_story_8_10_2_7_dialog_content = "Kerahkan… Tim 3… ke…",
  ui_story_8_10_2_8_dialog_content = "Satukan barisan! Jangan… arahkan ke retakannya… cangkang luar…",
  ui_story_8_10_2_9_dialog_content = "Itu dari sistem komunikasi Guardians!",
  ui_story_8_10_2_10_dialog_content = "Tapi, Aviduz bisa memblokir komunikasi kita. Bagaimana…",
  ui_story_8_10_2_11_dialog_content = "Mungkin sinyal jarak dekat cukup kuat untuk menembusnya? Dari pesannya, sepertinya sekarang mereka ada di luar.",
  ui_story_8_10_2_12_dialog_content = "Mereka di luar? Mereka melawan Aviduz?",
  ui_story_8_10_2_13_dialog_content = "Benar. Sepertinya mereka sudah menyusun pasukan besar dan mengambil langkah duluan.",
  ui_story_8_10_2_14_dialog_content = "Maju! Kitalah harapan terakhir Lumopo…",
  ui_story_8_10_2_15_dialog_content = "Ikuti aku… Jangan kendurkan serangan! Jangan biarkan…",
  ui_story_8_10_2_16_dialog_content = "Pesawatnya tak terkendali! Kita jatuh dari langit… Tidak! Kalau harus mati, akan kuajak sampah ini bersamaku!",
  ui_story_8_10_2_17_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_8_10_2_18_dialog_content = "…",
  ui_story_8_10_2_19_dialog_content = "Apa tadi itu serangan bunuh diri?",
  ui_story_8_10_2_20_dialog_content = "Anu…",
  ui_story_8_10_2_21_dialog_content = "Chief, lukamu…",
  ui_story_8_10_2_22_dialog_content = "Ayo, jangan buang-buang waktu.",
  ui_story_8_10_2_23_dialog_content = "Jangan sampai tragedi tujuh belas tahun lalu terulang lagi. Kita harus menghentikan para Eclipsite itu.",
  ui_story_8_10_2_24_dialog_content = "Baiklah.",
  ui_story_8_10_2_25_dialog_content = "Kita makin mendekati Bridge. Kau yakin Schummer ada di sana, PlayerName?",
  ui_story_8_10_2_26_dialog_content = "Yakin. Ayo kita tuntaskan ini, selamanya!",
  ui_story_8_10_2_27_dialog_content = "Tak satu pun Eclipsite bisa menghentikan kita sekarang.",
  ui_story_8_13_2_1_dialog_content = "Profesor, aku gagal lagi.",
  ui_story_8_13_2_2_dialog_content = "Tak apa, coba saja lagi.",
  ui_story_8_13_2_3_dialog_content = "Tapi, aku…",
  ui_story_8_13_2_4_dialog_content = "Tak ada satu orang pun yang sudah kuat sejak lahir, Nak. Kita hanya bisa jadi kuat. Berlatihlah dan bangkitlah kembali setiap kali kalah…",
  ui_story_8_13_2_5_dialog_content = "Hanya dengan itulah kau bisa jadi benar-benar kuat.",
  ui_story_8_13_2_6_dialog_content = "Tapi…",
  ui_story_8_13_2_7_dialog_content = "Schummer!",
  ui_story_8_13_2_8_dialog_content = "Kau sudah datang. Sudah cukup untuk hari ini, Schummer. Sana, mainlah dengan teman-temanmu.",
  ui_story_8_13_2_9_dialog_content = "Benar! Jangan buat teman-temanmu menunggu lama!",
  ui_story_8_13_2_10_dialog_content = "Ha ha ha!",
  ui_story_8_13_2_11_dialog_content = "…",
  ui_story_8_13_2_12_dialog_content = "Ada apa?",
  ui_story_8_13_2_13_dialog_content = "Aku…",
  ui_story_8_13_2_14_dialog_content = "…",
  ui_story_8_13_2_15_dialog_content = "Aku membunuh mereka semua.",
  ui_story_8_13_2_16_dialog_content = "Aku mencekik mereka dengan kedua tanganku sendiri. Suara tulang mereka yang patah terdengar seperti nyanyian bagiku.",
  ui_story_8_13_2_17_dialog_content = "Nyanyian kekuatan mutlak dan sejati.",
  ui_story_8_13_2_18_dialog_content = "Bagaimana situasinya, Schummer?",
  ui_story_8_13_2_19_dialog_content = "Jangan ganggu aku. Pertahanan Lumopolis berhasil ditembus, dan para Aurorian itu melancarkan upaya terakhir mereka.",
  ui_story_8_13_2_20_dialog_content = "Sudah kubilang aku bisa mengatasi ini, 'kan?",
  ui_story_8_13_2_22_dialog_content = "Aku berhasil, sementara kalian semua gagal! Ha…",
  ui_story_8_13_2_23_dialog_content = "Ha ha ha!",
  ui_story_8_13_2_24_dialog_content = "…",
  ui_story_8_13_2_25_dialog_content = "Nah, sekarang, bisa tolong minggir?",
  ui_story_8_13_2_26_dialog_content = "Caelestite itu hampir sampai di sini.",
  ui_story_8_13_2_27_dialog_content = "Waktunya pas sekali. Pembantaian hari ini akan segera dimulai. Kemarilah, Sayang!",
  ui_story_8_13_2_28_dialog_content = "Bukannya kau mau membunuh si Caelestite itu?",
  ui_story_8_13_2_29_dialog_content = "Kenapa aku harus membunuh \"saudaraku\"?",
  ui_story_8_13_2_30_dialog_content = "Tapi, dulu 'kan kaubilang…",
  ui_story_8_13_2_31_dialog_content = "Sudah, diamlah! Kau ini memang selalu cerewet. Tak bisakah kau berhenti mengusikku?!",
  ui_story_8_13_2_32_dialog_content = "Bergabunglah denganku, PlayerName. Tempatmu adalah di sisiku!",
  ui_story_8_13_2_33_dialog_content = "Tunggu saja sampai kaulihat aku sekarang jadi apa. Buka saja matamu…",
  ui_story_8_14_1_1_dialog_content = "…",
  ui_story_8_14_1_3_dialog_content = "Kavalerinya sudah sampai, Michael!",
  ui_story_8_14_1_4_dialog_content = "…?",
  ui_story_8_14_1_5_dialog_content = "Carleen? Dia baik-baik saja. Dia menyuruh yang lainnya menjaga pintu!",
  ui_story_8_14_1_6_dialog_content = "<color=#e8d9bb>Di luar Ruang Kontrol Damocles</color>",
  ui_story_8_14_1_7_dialog_content = "Minggir! Kalian semua, minggir!",
  ui_story_8_14_1_8_dialog_content = "Apa-apaan kau ini, Irridon? Kenapa pintunya belum kaudobrak?",
  ui_story_8_14_1_9_dialog_content = "Seperti yang kaulihat.",
  ui_story_8_14_1_10_dialog_content = "Bersabarlah, Lord Otto.",
  ui_story_8_14_1_11_dialog_content = "Mundur! Atas nama Elder Council, kuperintahkan kalian semua untuk mundur!",
  ui_story_8_14_1_F1_dialog_content = "Siapa yang menyuruhmu menjaga ruang kontrol ini!? Minggir!",
  ui_story_8_14_1_12_dialog_content = "Minggat ke mana si Schwartz itu dalam situasi seperti ini? Apa dia sama sekali tak peduli dengan putrinya?!",
  ui_story_8_14_1_13_dialog_content = "Lord Otto, tenanglah, dengarkan aku…",
  ui_story_8_14_1_14_dialog_content = "Lihat di atas sana, langit dipenuhi Eclipsite. Menurutmu, bukankah seharusnya Hall of Justice dan Elder Council berusaha mengatasi mereka dulu?",
  ui_story_8_14_1_15_dialog_content = "Gabriel…",
  ui_story_8_14_1_16_dialog_content = "Boleh kubakar para Eclipsite itu sampai jadi abu?",
  ui_story_8_14_1_17_dialog_content = "Tentu! Tapi, jangan sampai keliru membakar rumah para bangsawan, ya!",
  ui_story_8_14_1_18_dialog_content = "Siap, tapi sepertinya itu sangat sulit bagiku…",
  ui_story_8_14_1_19_dialog_content = "…",
  ui_story_8_14_1_20_dialog_content = "Kau yakin mau berdiri di sana dan menghalangiku, Gabriel?",
  ui_story_8_14_1_21_dialog_content = "Yap, jelas!",
  ui_story_8_14_1_22_dialog_content = "Walau kurasa sebenarnya kata \"berdiri\" kurang tepat. Aku sih lebih pilih bilang aku \"duduk\" menghalangimu!",
  ui_story_8_14_1_23_dialog_content = "Prajurit Hall of Justice, maju!",
  ui_story_8_14_1_24_dialog_content = "<size=45>Bagaimana kalau kaucoba saja?</size>",
  ui_story_8_14_1_25_dialog_content = "Bangunannya runtuh! Mundur ke…",
  ui_story_8_14_1_26_dialog_content = "!!",
  ui_story_8_14_1_27_dialog_content = "Jumlah mereka terlalu banyak! Kalau tetap bertahan, kita akan kehilangan segalanya!!",
  ui_story_8_14_1_28_dialog_content = "…!!",
  ui_story_8_14_1_29_dialog_content = "Aku paham! Mundur ke tempat sempit dan ambil posisi bertahan!",
  ui_story_8_14_1_30_dialog_content = "Jangan sampai para Eclipsite itu lolos!",
  ui_story_8_14_1_31_dialog_content = "*Meraung*",
  ui_story_8_14_1_33_dialog_content = "<color=#e8d9bb>Ruang Kontrol Damocles</color>",
  ui_story_8_14_1_34_dialog_content = "…",
  ui_story_8_14_1_35_dialog_content = "(Raphael, Michael, Gabriel, dan yang lainnya, apa mereka sekarang sedang bertarung?)",
  ui_story_8_14_1_36_dialog_content = "Cepatlah, Damocles…",
  ui_story_8_14_1_37_dialog_content = "Warga Lumopolis dan kota ini membutuhkanmu. Bangunlah!",
  ui_story_8_14_1_38_dialog_content = "Masih terlalu lambat. Aku harus mempercepat proses pengisian dayanya, walau itu artinya mungkin seluruh kekuatanku akan terkuras!",
  ui_story_8_14_1_39_dialog_content = "<color=#e8d9bb>Bridge di Aviduz</color>",
  ui_story_8_14_1_40_dialog_content = "Menara tembak.",
  ui_story_8_14_1_41_dialog_content = "Tembok kota.",
  ui_story_8_14_1_42_dialog_content = "Dan lalat-lalat payah yang kalian sebut \"pesawat\" itu.",
  ui_story_8_14_1_43_dialog_content = "Roda perang sudah berputar. Orang-orang bodoh seperti kalian sama sekali tak akan sanggup menghentikanku.",
  ui_story_8_14_1_44_dialog_content = "Tak ada yang bisa menghentikanku sekarang!!",
  ui_story_8_14_1_45_dialog_content = "Schummer.",
  ui_story_8_14_1_46_dialog_content = "PlayerName.",
  ui_story_8_14_1_47_dialog_content = "Apa kau gugup? Pertunjukan baru saja dimulai dan kau sudah kehabisan napas.",
  ui_story_8_14_1_48_dialog_content = "Sini, duduklah.",
  ui_story_8_14_1_49_dialog_content = "Kau harus menghentikan ini! Jangan diteruskan lagi.",
  ui_story_8_14_1_50_dialog_content = "Dia sedang sibuk mengontrol Aviduz, PlayerName! Ini kesempatan kita.",
  ui_story_8_14_1_51_dialog_content = "Di sebelah kirimu, Vice!",
  ui_story_8_14_1_52_dialog_content = "*Meraung*",
  ui_story_8_14_1_53_dialog_content = "High-Level Eclipsite!",
  ui_story_8_14_1_54_dialog_content = "Kali ini rasanya berbeda. Sepertinya Eclipsite itu akan melawan.",
  ui_story_8_14_1_55_dialog_content = "Dasar bodoh, biarkan saja mereka berdatangan. Jangan rusak kesenanganku.",
  ui_story_8_14_1_56_dialog_content = "Tak mudah menggelar pertunjukan ini. Akan sia-sia jadinya kalau tak ada yang menontonnya.",
  ui_story_8_14_1_57_dialog_content = "Sudah berulang kali kau bertindak bertentangan dengan perintah Lady Forsakin, Schummer. Bahkan dalam situasi seperti ini pun, kau masih saja bertindak semaumu sendiri.",
  ui_story_8_14_1_58_dialog_content = "Aku tak berhak menghentikan perilakumu yang menjengkelkan itu. Tapi, kau juga tak berhak memerintahku.",
  ui_story_8_14_1_59_dialog_content = "Sama seperti Master, kita mengabdikan diri dan pekerjaan demi sang Bunda, bukan demi keinginan pribadi!",
  ui_story_8_14_1_60_dialog_content = "Bunda begini lah, Bunda begitu lah… Sungguh membosankan.",
  ui_story_8_14_1_61_dialog_content = "Seperti yang kaulihat, PlayerName, sekarang aku sedang sangat sibuk.",
  ui_story_8_14_1_62_dialog_content = "Tapi, aku tetap ingin kau menyaksikan Lumopolis hancur lebur. Itulah sebabnya…",
  ui_story_8_14_1_63_dialog_content = "Aku harus minta bantuanmu untuk pertama kalinya. Bunuh Eclipsite ini dan berdirilah di sisiku.",
  ui_story_8_14_1_64_dialog_content = "Kau…?",
  ui_story_8_14_1_65_dialog_content = "Kali ini, apa lagi yang direncanakannya? Waspadalah, PlayerName!",
  ui_story_8_14_1_66_dialog_content = "Benar. Apa pun itu, dia benar.Pertama-tama, kita harus membereskan Eclipsite itu!",
  ui_story_8_14_1_67_dialog_content = "Aku merasa terhormat akhirnya bisa bertemu denganmu, Caelestite. Dan denganmu juga, Aurorian.",
  ui_story_8_14_1_68_dialog_content = "Kalian sudah terlalu lama menjadi duri dalam daging bagi kami. Sudah saatnya melaksanakan kehendak sang Bunda, dan kehendak Eclipse. Nah…",
  ui_story_8_14_1_69_dialog_content = "Kemarilah.",
  ui_story_8_14_1_70_dialog_content = "Jangan mengecewakanku, PlayerName.",
  ui_story_8_14_2_1_dialog_content = "Mustahil… Tak mungkin!",
  ui_story_8_14_2_2_dialog_content = "Bunda, Lady Forsakin, kumohon, beri aku satu kesempatan terakhir! Beri aku kekuatan untuk…",
  ui_story_8_14_2_3_dialog_content = "Cukup sudah.",
  ui_story_8_14_2_4_dialog_content = "Ugh!",
  ui_story_8_14_2_5_dialog_content = "Schummer, dasar kau pengkhianat!",
  ui_story_8_14_2_6_dialog_content = "Pengkhianat? Yang benar saja. Aku kan memang tak pernah berpihak di sisi mana pun.",
  ui_story_8_14_2_7_dialog_content = "Sudah selesai, Schummer.",
  ui_story_8_14_2_8_dialog_content = "Selesai? Kita justru baru saja mulai!",
  ui_story_8_14_2_9_dialog_content = "Bangun telepati, Aviduz!",
  ui_story_8_14_2_10_dialog_content = "PlayerName!",
  ui_story_8_14_2_11_dialog_content = "Sedang apa kau?",
  ui_story_8_14_2_12_dialog_content = "Menghentikanmu, dan Colossus ini!",
  ui_story_8_14_2_13_dialog_content = "Aviduz adalah aku dan aku adalah Aviduz. Kau tak bisa mengendalikannya!",
  ui_story_8_14_2_14_dialog_content = "Masa? Aku hanya ingin mencegahmu mendekati Lumopolis.",
  ui_story_8_14_2_15_dialog_content = "Itu rumah bagi kaum Aurorian…",
  ui_story_8_14_2_16_dialog_content = "Dan teman-temanku… Itu juga rumah mereka!!",
  ui_story_8_14_2_18_dialog_content = "Jadi, walaupun harus begini caranya… Ugh… Aduh!",
  ui_story_8_14_2_19_dialog_content = "Hidungmu berdarah, PlayerName!",
  ui_story_8_14_2_20_dialog_content = "Mundur! Sana… kalahkan Schummer!!",
  ui_story_8_14_2_21_dialog_content = "Sudah kubilang kau tak akan bisa mengendalikannya.",
  ui_story_8_14_2_22_dialog_content = "Awas, Vice!!",
  ui_story_8_14_2_23_dialog_content = "(Bangun telepati lagi dengan Aviduz!)",
  ui_story_8_14_2_24_dialog_content = "Masih tak tahu juga kapan kau harus menyerah, ya? PlayerName?",
  ui_story_8_14_2_25_dialog_content = "Tidak akan pernah! Aku tak akan menyerah, bahkan walaupun harus mati karenanya!",
  ui_story_8_14_2_26_dialog_content = "Sekarang kau tak punya peluang untuk menang, Schummer!",
  ui_story_8_14_2_27_dialog_content = "Kau ini sebenarnya sadar tidak sih dengan kata-katamu? Buka matamu dan lihat baik-baik!!",
  ui_story_8_14_2_28_dialog_content = "Lumopolis sudah hancur! Pertahanannya, prajuritnya… semuanya hancur!",
  ui_story_8_14_2_29_dialog_content = "Aku berhasil, PlayerName! Aku berhasil melakukan hal yang tak bisa dilakukan siapa pun!",
  ui_story_8_14_2_30_dialog_content = "Kenapa tak kauterima saja!? Harusnya kau merangkak memuja kekuatan mutlakku, tapi kenapa, kenapa kau masih terus melawan!?",
  ui_story_8_14_2_31_dialog_content = "Aviduz, matikan… generator…",
  ui_story_8_14_2_32_dialog_content = "Colossus itu milikku!",
  ui_story_8_14_2_33_dialog_content = "Aaaarrrgh!!!",
  ui_story_8_14_2_35_dialog_content = "Oh, kepalaku, terasa berputar… Aku…",
  ui_story_8_14_2_36_dialog_content = "PlayerName…",
  ui_story_8_14_2_37_dialog_content = "Maaf, kami tak mampu menembus pertahanan Schummer.",
  ui_story_8_14_2_38_dialog_content = "Nah, sudah lihat selisih kekuatan kita? Kau dan teman-temanmu yang menjengkelkan itu… Mana mungkin kau bisa mengungguliku?!",
  ui_story_8_14_2_39_dialog_content = "Terus buka matamu, PlayerName. Aku tak mau terus menyiksamu, terutama sekarang…",
  ui_story_8_14_2_40_dialog_content = "Aku ingin kau melihat ini. Menyaksikan ini, sebagai seorang Caelestite…",
  ui_story_8_14_2_41_dialog_content = "Apa?",
  ui_story_8_14_2_42_dialog_content = "…?",
  ui_story_8_14_2_43_dialog_content = "(Kenapa hening sekali?)",
  ui_story_8_14_2_44_dialog_content = "…",
  ui_story_8_14_2_45_dialog_content = "Dasar bedebah, apa lagi yang kalian lakukan kali ini?",
  ui_story_8_14_2_46_dialog_content = "(Schummer tak tahu apa yang terjadi, berarti ini bukan perbuatannya?)",
  ui_story_8_14_2_47_dialog_content = "Apa?",
  ui_story_8_14_2_48_dialog_content = "Kenapa rasanya seluruh tubuhku merinding?",
  ui_story_8_14_2_49_dialog_content = "Udara di sekitar terasa berbeda, Vice.",
  ui_story_8_14_2_50_dialog_content = "Dan kenapa tiba-tiba semuanya hening sekali?",
  ui_story_8_14_2_51_dialog_content = "Kau benar, ini terlalu hening. Aku tak mendengar suara lain apa pun.",
  ui_story_8_14_2_52_dialog_content = "Lihat ke tanah, Vice!",
  ui_story_8_14_2_53_dialog_content = "Debunya bergerak, dan sepertinya ke arah tertentu…",
  ui_story_8_14_2_54_dialog_content = "Mungkin gara-gara pasir. Kau bisa merasakannya? Udara di sekitar kita berkumpul, seperti…",
  ui_story_8_14_2_55_dialog_content = "Seperti ada sesuatu yang terbentuk?",
  ui_story_8_14_2_56_dialog_content = "Ini pertanda buruk!",
  ui_story_8_14_2_58_dialog_content = "Chief, PlayerName, tiaraplah dan cari pegangan.",
  ui_story_8_14_2_59_dialog_content = "Kalau aku tak salah, ini sudah saatnya.",
  ui_story_8_14_2_62_dialog_content = "Ada sesuatu di atas Lumopolis. Apa itu?",
  ui_story_8_14_2_63_dialog_content = "Dari mana asal cahaya itu?",
  ui_story_8_14_2_64_dialog_content = "…",
  ui_story_8_14_2_65_dialog_content = "Demi White Night… Sumpahku kini terpenuhi.",
  ui_story_8_14_2_66_dialog_content = "Schummer, pengkhianat kaum Caelestite, aku, Carleen de Schwartz, akan menjatuhkan…",
  ui_story_8_14_2_67_dialog_content = "Keputusan terakhir untukmu!!!",
  ui_story_8_14_2_68_dialog_content = "Apa itu…?",
  ui_story_8_14_2_69_dialog_content = "Semuanya, tiarap!!",
  ui_story_8_14_2_70_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_8_14_2_73_dialog_content = "(Apa, Lumina Cannon…? Mataku!)",
  ui_story_8_14_2_74_dialog_content = "(Kok aku tak bisa bergerak? Kenapa tubuhku tak bisa digerakkan!?)",
  ui_story_8_14_2_75_dialog_content = "(Schummer…)",
  ui_story_8_14_2_76_dialog_content = "(Kau!)",
  ui_story_8_14_2_77_dialog_content = "(Sudah kubilang aku akan menghentikanmu, bahkan walaupun harus mati…)",
  ui_story_8_14_2_78_dialog_content = "(Kaukira kau bisa menghentikanku dengan cara ini?!)",
  ui_story_8_14_2_82_dialog_content = "Schummer!",
  ui_story_8_14_2_83_dialog_content = "Jangan berani-beraninya berusaha melawan untuk terakhir kalinya!!",
  ui_story_8_14_2_F1_dialog_content = "Sinar Damocles akan menembusmu dan Aviduz!",
  ui_story_8_14_2_84_dialog_content = "(Carleen!)",
  ui_story_8_14_2_87_dialog_content = "Menghindar, Aviduz! Sana!",
  ui_story_8_14_2_88_dialog_content = "Tak akan kubiarkan kau… lolos… Ugh…!",
  ui_story_8_14_2_89_dialog_content = "Hindari ledakannya! Kenapa kau diam saja?",
  ui_story_8_14_2_90_dialog_content = "(Aku harus… berusaha semampuku! Jangan sampai Colossus itu lolos!!)",
  ui_story_8_14_2_91_dialog_content = "Bebaskan Colossus milikku, PlayerName! Putuskan telepatimu dengan Aviduz!",
  ui_story_8_14_2_92_dialog_content = "(Tidak… Sinarnya… meleset?)",
  ui_story_8_14_2_93_dialog_content = "Lumina-mu terlalu lemah, Carleen! Kau tak bisa membidikkan sinarnya lagi! Minggir!",
  ui_story_8_14_2_94_dialog_content = "?!",
  ui_story_8_14_2_95_dialog_content = "Lord? Tapi, kenapa?",
  ui_story_8_14_2_96_dialog_content = "Hanya membantumu mengarahkan serangan Damocles, itu saja!",
  ui_story_8_14_2_97_dialog_content = "Jangan lihat ke belakang. Targetmu ada di depan sana, 'kan?",
  ui_story_8_14_2_98_dialog_content = "Apa kau ingat satu-satunya hal yang tak boleh kaulakukan sebelum mengalahkan musuh?",
  ui_story_8_14_2_99_dialog_content = "Tentu saja aku ingat, Ayah!",
  ui_story_8_14_2_100_dialog_content = "\"Jangan kendurkan genggamanmu sampai tombakmu berhasil menembus dada musuh!\"",
  ui_story_8_14_2_101_dialog_content = "(Aku akan mati! Kalau terus begini, aku…)",
  ui_story_8_14_2_102_dialog_content = "(Hentikan! Keluar, PlayerName!)",
  ui_story_8_14_2_103_dialog_content = "Schummer!",
  ui_story_8_14_2_104_dialog_content = "Sebelum mati, lihat mataku!!!",
  ui_story_8_14_2_105_dialog_content = "Tidak, tidak…",
  ui_story_8_14_2_106_dialog_content = "Tidaaaaak!",
  ui_story_8_14_2_112_dialog_content = "Schummer.",
  ui_story_8_14_2_113_dialog_content = "Aku di sini, Profesor.",
  ui_story_8_14_2_114_dialog_content = "Kenapa kau melakukannya?",
  ui_story_8_14_2_115_dialog_content = "…",
  ui_story_8_14_2_116_dialog_content = "Kenapa…",
  ui_story_8_14_2_117_dialog_content = "Kenapa kau membunuh kami semua?",
  ui_story_8_14_2_118_dialog_content = "Dengan napas terakhirku, kukutuk kau, Schummer, pengkhianat kaum Caelestite, dan kegagalan terbesarku.",
  ui_story_8_14_2_119_dialog_content = "Kukutuk kau mati dengan rasa sakit seratus kali lipat lebih sakit daripada yang kami rasakan, Schummer.",
  ui_story_8_14_2_120_dialog_content = "Kukutuk kau, selamanya.",
  ui_story_8_14_2_121_dialog_content = "Kau tak akan pernah mendapatkan kedamaian.",
  ui_story_8_15_1_1_dialog_content = "Kau terlambat, Forsakin.",
  ui_story_8_15_1_2_dialog_content = "Tempat ini terlalu jauh. Apa memang kau harus bersembunyi di sini?",
  ui_story_8_15_1_3_dialog_content = "Apa kau membawanya?",
  ui_story_8_15_1_4_dialog_content = "Benda itu dibawa Schummer. Ini akan segera berakhir, jadi jangan mendesakku.",
  ui_story_8_15_1_5_dialog_content = "Kenapa kaubiarkan Schummer menyerang Lumopolis? Tugasmu sebenarnya mudah, biarkan saja benda di dalam tubuhnya itu…",
  ui_story_8_15_1_6_dialog_content = "Dia terlalu kekanak-kanakan untuk bisa memahaminya.",
  ui_story_8_15_1_7_dialog_content = "Memangnya penting?",
  ui_story_8_15_1_8_dialog_content = "…",
  ui_story_8_15_1_9_dialog_content = "Jangan lupakan tugasmu, Aurorian.",
  ui_story_8_15_1_10_dialog_content = "*Huahh*",
  ui_story_8_15_1_11_dialog_content = "Itu saja laporan kerugian untuk Lower Lumopolis. Dan ini adalah usulan hukuman untuk Kapten dari Guardians…",
  ui_story_8_15_1_12_dialog_content = "Baiklah, sementara ini sudah cukup.",
  ui_story_8_15_1_13_dialog_content = "Pergilah keluar. Kau boleh kembali dan melanjutkan laporanmu lima menit lagi.",
  ui_story_8_15_1_14_dialog_content = "Ya!",
  ui_story_8_15_1_15_dialog_content = "Lanjutkan.",
  ui_story_8_15_1_16_dialog_content = "Lama tak jumpa, Schwartz.",
  ui_story_8_15_1_17_dialog_content = "Apa kau kemari untuk menghiburku?",
  ui_story_8_15_1_18_dialog_content = "Kalau iya, memangnya kau akan percaya?",
  ui_story_8_15_1_19_dialog_content = "Sebagai orang yang sudah mengungkapkan semua rencana, kau tampak sangat bersemangat.",
  ui_story_8_15_1_20_dialog_content = "Jangan lancang. Sejauh ini aku baru mengeluarkan satu kartu.",
  ui_story_8_15_1_21_dialog_content = "Lagi pula, kita tak lagi sendirian dalam permainan ini. Ada pihak-pihak lain yang sekarang mempertahankan kota.",
  ui_story_8_15_1_22_dialog_content = "Aku tak tertarik untuk mengajari anakmu cara bermain, Schwartz.",
  ui_story_8_15_1_23_dialog_content = "Jujur saja, aku tak ikut campur sama sekali dalam permainan hari ini. Kau tak keberatan, 'kan?",
  ui_story_8_15_1_24_dialog_content = "Tidak. Itu karena aku percaya pada kekuatan Lumopolis, wahai Lord hebat dari Kota Tak Terkalahkan.",
  ui_story_8_15_1_25_dialog_content = "Di pihakku juga ada perkembangan menarik, dan aku tak sabar untuk menceritakannya kepadamu.",
  ui_story_8_15_1_26_dialog_content = "Baiklah. Kita lihat saja apa yang bisa dilakukan Illumina Federation.",
  ui_story_8_15_1_27_dialog_content = "Nyala yang berkelip-kelip itu, apa akhirnya akan bisa membuka jalan menembus kegelapan?",
  ui_story_8_15_1_28_dialog_content = "Jayalah Illumina!",
  ui_story_9_1_1_1_dialog_content = "Kalian berdua boleh masuk sekarang.",
  ui_story_9_1_1_2_dialog_content = "Terima kasih. Ayo, PlayerName.",
  ui_story_9_1_1_3_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_9_1_1_4_dialog_content = "Vice, aku masih belum tahu…",
  ui_story_9_1_1_5_option_content = "Di mana kita?",
  ui_story_9_1_1_6_dialog_content = "Kita ada di Hall of Justice di Lumopolis Gardens.",
  ui_story_9_1_1_7_dialog_content = "Wanita bertongkat di mimbar itu pasti Chief Judge <color=#FFB400>Irridon</color>.",
  ui_story_9_1_1_8_option_content = "Siapa orang-orang ini?",
  ui_story_9_1_1_9_dialog_content = "Kalau aku tak salah…",
  ui_story_9_1_1_10_dialog_content = "Wanita bertongkat di mimbar itu adalah Chief Judge <color=#FFB400>Irridon</color>, yang menjalankan Hall of Justice ini.",
  ui_story_9_1_1_11_dialog_content = "Dan pria gagah di sebelahnya…",
  ui_story_9_1_1_12_dialog_content = "Oh, aku ingat, itu ayah Carleen, 'kan?",
  ui_story_9_1_1_13_dialog_content = "Benar, itu adalah Lord of Lumopolis, <color=#FFB400>Daniel de Schwartz</color>.",
  ui_story_9_1_1_14_dialog_content = "Entah kenapa aku jadi bergidik…",
  ui_story_9_1_1_15_dialog_content = "Shhh…",
  ui_story_9_1_1_16_dialog_content = "…",
  ui_story_9_1_1_17_dialog_content = "Kau teman Kapten Carleen, 'kan?",
  ui_story_9_1_1_18_dialog_content = "Eh, ya. Senang bertemu dengan Anda, Lord.",
  ui_story_9_1_1_19_dialog_content = "Aku Vice, dari Illumina Federation. Ini PlayerName.",
  ui_story_9_1_1_20_dialog_content = "Senang bertemu dengan Anda, aku PlayerName.",
  ui_story_9_1_1_21_dialog_content = "Senang bertemu denganmu.",
  ui_story_9_1_1_22_dialog_content = "Aku tahu kau menunda serangan musuh dan bertarung dengan gagah berani untuk melindungi kota.",
  ui_story_9_1_1_23_dialog_content = "Aku ingin mengucapkan terima kasih kepada kalian berdua.",
  ui_story_9_1_1_24_dialog_content = "Suatu kehormatan bagi kami, Pak. Kami hanya menjalankan tugas.",
  ui_story_9_1_1_25_dialog_content = "Bagaimana dengan luka kalian?",
  ui_story_9_1_1_26_dialog_content = "Berkat dokter yang Anda utus, kami merasa jauh lebih baik sekarang.",
  ui_story_9_1_1_27_dialog_content = "Bagus. Lumopolis tidak akan pernah lupa bahwa Federasi Illumina mengirimkan bantuan untuk mengatasi krisis.",
  ui_story_9_1_1_28_dialog_content = "Tolong sampaikan penghargaan saya kepada orang-orang Illumina atas nama Lumopolis juga.",
  ui_story_9_1_1_29_dialog_content = "Tentu saja, Pak.",
  ui_story_9_1_1_X29_dialog_content = "Baiklah.",
  ui_story_9_1_1_X30_dialog_content = "Kalau begitu, Chief Judge, kamu bisa maju dan mengumumkan sidang pengadilan akan dimulai.",
  ui_story_9_1_1_X31_dialog_content = "Ya, Lord.",
  ui_story_9_1_1_30_dialog_content = "Sidang dimulai. Pihak yang terlibat mohon berdiri.",
  ui_story_9_1_1_31_dialog_content = "Ya!",
  ui_story_9_1_1_32_dialog_content = "(Carleen…)",
  ui_story_9_1_1_33_dialog_content = "Demi White Night.",
  ui_story_9_1_1_34_dialog_content = "Atas nama Hall of Justice, aku akan mengadili Carleen de Schwartz.",
  ui_story_9_1_1_35_dialog_content = "Carleen de Schwartz, Kapten dari Lumopolis Guardians…",
  ui_story_9_1_1_36_dialog_content = "Selama masa jabatannya, dia pernah…",
  ui_story_9_1_1_37_dialog_content = "Abaikan resolusi tiga pihak, paksa masuk ke Ruang Kontrol dengan seorang komandan ksatria sebagai sandera, dan mulai Damocles tanpa izin.",
  ui_story_9_1_1_38_dialog_content = "Yang secara langsung bertanggung jawab atas kegagalan perisai, yang kemudian membuat Taman dan Halaman Lumopolis terkena serangan.",
  ui_story_9_1_1_39_dialog_content = "Menyebabkan seratus delapan bangsawan yang terluka dan banyak pelayan yang terluka atau mati, ditambah kerugian harta benda yang tak terukur.",
  ui_story_9_1_1_40_dialog_content = "Tindakan ini telah melanggar hukum Lumopolis dan harus dihukum sesuai.",
  ui_story_9_1_1_41_dialog_content = "Namun, setelah mempertimbangkan usahanya dalam mengusir para penyerang,",
  ui_story_9_1_1_42_dialog_content = "Dewan Kehakiman telah memutuskan untuk menangguhkan Carleen de Schwartz dari dinas selama 1 tahun...",
  ui_story_9_1_1_43_dialog_content = "Apa? Yang benar saja! Bagaimana kau bisa mengambil keputusan tidak masuk akal seperti itu!?",
  ui_story_9_1_1_44_dialog_content = "…",
  ui_story_9_1_1_45_dialog_content = "Jelas-jelas dia tidak peduli dengan keselamatan semua bangsawan di Lumopolis!",
  ui_story_9_1_1_46_dialog_content = "Kali ini dia beruntung! Kalau kita hanya memberikan hukuman seringan itu, siapa yang tahu dia akan berbuat apa lagi nantinya?",
  ui_story_9_1_1_47_dialog_content = "Kau tidak bersekongkol dengan Hall untuk melindungi putrimu, bukan, Schwartz?",
  ui_story_9_1_1_48_dialog_content = "Kau mempertanyakan putusan Chief Judge, Otto Troy? Itu tidak pantas untuk seorang bangsawan.",
  ui_story_9_1_1_49_dialog_content = "Hmph!",
  ui_story_9_1_1_50_dialog_content = "Silakan lanjutkan, Yang Mulia.",
  ui_story_9_1_1_51_dialog_content = "Hall of Justice telah memutuskan untuk menangguhkan Carleen de Schwartz dari tugas selama 1 tahun.",
  ui_story_9_1_1_52_dialog_content = "Untuk sementara, dia harus mengungkap kebenaran di balik serangan itu.",
  ui_story_9_1_1_53_dialog_content = "Dan memberikan temuan yang memuaskan kepada para bangsawan.",
  ui_story_9_1_1_54_dialog_content = "Jika Carleen de Schwartz tidak mampu memenuhinya, kami akan mencabut jabatan, gelar…",
  ui_story_9_1_1_55_dialog_content = "dan hak tinggalnya di Lumopolis.",
  ui_story_9_1_1_56_dialog_content = "Demi White Night. Kiranya Cahaya memberkati semua orang di Lumopolis.",
  ui_story_9_1_1_57_dialog_content = "Demi White Night.",
  ui_story_9_1_1_58_dialog_content = "Lewat sini, Vice dan PlayerName.",
  ui_story_9_1_1_59_dialog_content = "Bagaimana keadaanmu, Carleen?",
  ui_story_9_1_1_60_dialog_content = "Aku baik-baik saja, terima kasih sudah bertanya.",
  ui_story_9_1_1_61_dialog_content = "Bagaimana denganmu, PlayerName? Kamu sudah sembuh?",
  ui_story_9_1_1_62_dialog_content = "Tadi menegangkan sekali!",
  ui_story_9_1_1_63_dialog_content = "Maaf kau harus menyaksikannya.",
  ui_story_9_1_1_64_dialog_content = "Sepertinya PlayerName sudah sembuh total.",
  ui_story_9_1_1_65_dialog_content = "Kurasa begitu.",
  ui_story_9_1_1_66_dialog_content = "Si Otto itu…",
  ui_story_9_1_1_67_dialog_content = "Dia menentang mati-matian, bahkan sebelum Chief Judge selesai menjatuhkan vonis.",
  ui_story_9_1_1_68_dialog_content = "Dia tidak menunjukkan rasa hormat sama sekali kepada City Lord dan Carleen!",
  ui_story_9_1_1_69_dialog_content = "Jelas-jelas Carleen menyalakan Damocles untuk melindungi Lumopolis.",
  ui_story_9_1_1_70_dialog_content = "Dan si musuh pun kalah.",
  ui_story_9_1_1_71_dialog_content = "Kenapa dia bersikap seakan Carleen melakukan dosa yang tak bisa diampuni?",
  ui_story_9_1_1_72_dialog_content = "Memang seperti itulah bangsawan Lumopolis, tua dan menggelikan!",
  ui_story_9_1_1_73_dialog_content = "…",
  ui_story_9_1_1_74_dialog_content = "!",
  ui_story_9_1_1_75_dialog_content = "Maaf, aku tak bermaksud menjelekkan Lumopolis…",
  ui_story_9_1_1_76_dialog_content = "Tak apa-apa. Aku tahu kau tidak berniat buruk. Aku pun percaya pada hukum dan putusan Lumopolis.",
  ui_story_9_1_1_77_dialog_content = "Kalaupun Hall tidak memerintahkanku, aku akan tetap menyelidiki masalah itu.",
  ui_story_9_1_1_78_dialog_content = "Aku paham perasaanmu. Aku pun ingin tahu yang sebenarnya.",
  ui_story_9_1_1_79_dialog_content = "Tapi, kenapa Hall tidak memberikan bantuan tambahan untuk penyelidikanmu, Carleen?",
  ui_story_9_1_1_80_dialog_content = "Mungkin City Lord tak pernah menganggap Schummer sebagai ancaman…",
  ui_story_9_1_1_81_dialog_content = "Apa? Bagaimana mungkin?",
  ui_story_9_1_1_82_dialog_content = "Aku berbicara empat mata dengannya setelah putusan itu.",
  ui_story_9_1_1_83_dialog_content = "Ayah, aku ingin bertanya tentang serangan Schummer di Lumopolis.",
  ui_story_9_1_1_84_dialog_content = "Katakan.",
  ui_story_9_1_1_85_dialog_content = "Kenapa kota ini tidak menyerang balik sejak awal,",
  ui_story_9_1_1_86_dialog_content = "tapi malah membiarkan mereka menyerang perisainya?",
  ui_story_9_1_1_87_dialog_content = "Apakah Anda menyadari tanggung jawab Anda sendiri sebagai Kapten Penjaga Taman Lumopolis?",
  ui_story_9_1_1_88_dialog_content = "Itu tugasku?",
  ui_story_9_1_1_89_dialog_content = "Tentu saja, tugasmu adalah melindungi rakyat.",
  ui_story_9_1_1_90_dialog_content = "Maaf, aku tak mengerti kenapa kau mengabaikan pertanyaannya dan malah membahas hal yang tak masuk akal.",
  ui_story_9_1_1_91_dialog_content = "Sepertinya kau masih belum paham.",
  ui_story_9_1_1_92_dialog_content = "Sudah menjadi tugas Kapten untuk melindungi Gardens, yang juga merupakan tempat tinggal para bangsawan.",
  ui_story_9_1_1_93_dialog_content = "Beberapa tahun terakhir ini, semata karena kita kekurangan orang, Guardian punya lebih banyak kuasa dan tanggung jawab,",
  ui_story_9_1_1_94_dialog_content = "termasuk pemeliharaan perdamaian di bagian-bagian tertentu dari Lumopolis Bawah.",
  ui_story_9_1_1_95_dialog_content = "Jadi, sebenarnya, bagi rakyat, kewajibanmu adalah memastikan keselamatan orang-orang kelas atas.",
  ui_story_9_1_1_96_dialog_content = "…",
  ui_story_9_1_1_97_dialog_content = "Kurasa sekarang kau mungkin sudah menyadari kesalahanmu.",
  ui_story_9_1_1_98_dialog_content = "Soal pertanyaanmu barusan…",
  ui_story_9_1_1_99_dialog_content = "Kau benar-benar berpikir bahwa sampah itu bisa menembus perisai?",
  ui_story_9_1_1_100_dialog_content = "Maksudmu…",
  ui_story_9_1_1_101_dialog_content = "Coba kaupikirkan saja sendiri. Ada rapat lain yang harus kuhadiri.",
  ui_story_9_1_1_102_dialog_content = "…",
  ui_story_9_1_1_103_dialog_content = "Jadi, apa yang dimaksudnya…?",
  ui_story_9_1_1_104_dialog_content = "Yah, aku juga tak paham. Apa sebenarnya yang ingin disampaikannya?",
  ui_story_9_1_1_105_dialog_content = "Mungkin sebaiknya aku tak perlu terlalu memikirkan urusan Lumopolis atau Illumina…",
  ui_story_9_1_1_106_dialog_content = "Aku hanya ingin tahu apa yang terjadi di masa lalu!",
  ui_story_9_1_1_107_dialog_content = "PlayerName…",
  ui_story_9_1_1_108_dialog_content = "Aku masih merinding kalau memikirkannya.",
  ui_story_9_1_1_109_dialog_content = "Ledakannya cukup dekat, dan PlayerName tetap tidak bergeming!",
  ui_story_9_1_1_110_dialog_content = "Ketua Vivian dan saya tidak bisa menyeret PlayerName jauh sama sekali.",
  ui_story_9_1_1_111_dialog_content = "Untungnya, Curie datang memberikan bantuan. Dengan begitu kita bisa melarikan diri sebelum Aviduz terhantam.",
  ui_story_9_1_1_112_dialog_content = "Saat itu, aku sepenuhnya bertekad tak akan membiarkan Aviduz lolos.",
  ui_story_9_1_1_113_dialog_content = "Akan lebih parah jadinya kalau Carleen tidak mengarahkan Damocles untuk mengenai Aviduz.",
  ui_story_9_1_1_114_dialog_content = "…",
  ui_story_9_1_1_115_dialog_content = "Kau… Kenapa!?",
  ui_story_9_1_1_116_dialog_content = "Aku hanya membantumu mengarahkan serangan Damocles, itu saja!",
  ui_story_9_1_1_117_dialog_content = "Lagi pula, tugasku memang melindungi Lumopolis.",
  ui_story_9_1_1_118_dialog_content = "Jadi, Vivian dan Curie sudah kembali ke Illumina?",
  ui_story_9_1_1_119_dialog_content = "Oh, mereka masih di rumah sakit di Lumopolis.",
  ui_story_9_1_1_120_dialog_content = "Tapi jangan khawatir, mereka tidak dalam bahaya meski terluka, dan hanya perlu pulih dengan damai untuk sementara waktu.",
  ui_story_9_1_1_X120_dialog_content = "Sayap Curie cedera parah akibat serangan itu, tapi dia sudah pulih sekarang. Dia selalu ada di sisi Vivian selama ini.",
  ui_story_9_1_1_121_dialog_content = "Baguslah kalau begitu, tapi…",
  ui_story_9_1_1_122_dialog_content = "Apakah Schummer benar-benar sudah mati?",
  ui_story_9_1_1_123_dialog_content = "Sampai kami keluar, Schummer berada di Bridge Aviduz dan sepertinya tidak bisa bergerak.",
  ui_story_9_1_1_124_dialog_content = "Kurasa tak ada makhluk yang bisa bertahan dari serangan itu.",
  ui_story_9_1_1_125_dialog_content = "Rasanya aku tahu apa yang membuatmu risau, PlayerName.",
  ui_story_9_1_1_126_dialog_content = "Aku juga tidak akan berhenti sampai aku melihat mayat Schummer.",
  ui_story_9_1_1_X126_dialog_content = "Tapi, sebelum itu, ada misi penting yang harus kutangani.",
  ui_story_9_1_1_X127_dialog_content = "Hah? Misi apa?",
  ui_story_9_1_1_X128_dialog_content = "Aku harus membawamu menemui Soroz.",
  ui_story_9_1_1_127_dialog_content = "Kami menugaskan spesialis yang bisa memperbaiki Soroz. Sepertinya, tugas mereka sudah selesai.",
  ui_story_9_1_1_128_dialog_content = "<color=#FFB400>Soroz</color>!",
  ui_story_9_1_1_129_dialog_content = "Tidak ada respons sama sekali…",
  ui_story_9_1_1_130_dialog_content = "Eh, tepat waktu.",
  ui_story_9_1_1_131_dialog_content = "Madam Gronru? Bukankah kau sedang liburan di Gannon?",
  ui_story_9_1_1_132_dialog_content = "Dan melewatkan quest sampingan yang jarang ada? Tidak mungkin, apalagi kalau berhubungan dengan Colossus!",
  ui_story_9_1_1_133_dialog_content = "Sebenarnya akulah yang memanggil Gronru ke sini!",
  ui_story_9_1_1_134_dialog_content = "Saat Raphael mengunjungi Illumina untuk pertama kalinya, kami bertemu dan menjadi akrab, seperti amplop dan prangko, seperti anak kembar, seperti selai kacang dan jeli…",
  ui_story_9_1_1_135_dialog_content = "Oke, jangan lanjutkan lagi.",
  ui_story_9_1_1_136_dialog_content = "Omong-omong, aku sudah menemukan semua bagian dan memperbaiki Colossus untuk PlayerName!",
  ui_story_9_1_1_137_dialog_content = "Dan karena PlayerName sudah membantuku memulihkan HP, aku akan melepaskan reward untuk menyelesaikan stage kali ini.",
  ui_story_9_1_1_138_dialog_content = "Kau sudah memperbaikinya?",
  ui_story_9_1_1_139_dialog_content = "Soroz dikoyak oleh para Eclipsite.",
  ui_story_9_1_1_140_dialog_content = "Tapi, sekarang tak ada satu pun bagian yang penyok!",
  ui_story_9_1_1_141_dialog_content = "Ini luar biasa. Tak heran kamu dipercaya menjadi Tech Officer!",
  ui_story_9_1_1_142_dialog_content = "Yah, Raphael juga ikut membantu sih!",
  ui_story_9_1_1_143_dialog_content = "Terima kasih, kalian semua. Dan sekarang…",
  ui_story_9_1_1_144_dialog_content = "Apakah Soroz sudah sepenuhnya pulih dan berfungsi?",
  ui_story_9_1_1_145_dialog_content = "Seharusnya sudah baik-baik saja, mulai dari kontrol utama hingga bantuan hidup dan modul bio.",
  ui_story_9_1_1_146_dialog_content = "Bahkan aku sempat meningkatkan efisiensi mesinnya!",
  ui_story_9_1_1_147_dialog_content = "Komponen yang kaugunakan untuk memperbaikinya…",
  ui_story_9_1_1_148_dialog_content = "Anda benar-benar seorang Caelestite untuk dapat merasakan itu!",
  ui_story_9_1_1_149_dialog_content = "Aku merasakan kehadiran <color=#FFB400>Mantiz</color>.",
  ui_story_9_1_1_150_dialog_content = "Pemeriksaan menunjukkan ada kesamaan 99,9% antara Soroz dan Mantiz dalam hal suku cadang.",
  ui_story_9_1_1_151_dialog_content = "Bisa dibilang, Mantiz sudah menjadi besi tua sekarang…",
  ui_story_9_1_1_152_dialog_content = "Jadi, kumanfaatkan bagian mana pun yang masih bagus untuk memperbaiki Soroz.",
  ui_story_9_1_1_153_dialog_content = "Akan kubagi Soroz denganmu, <color=#FFB400>Mendelson</color>!",
  ui_story_9_1_1_154_dialog_content = "Sekarang dan selamanya, Soroz akan menjadi mata dan telinga yang akan menunjukkan segala yang ada di atas awan kepadamu.",
  ui_story_9_1_1_155_dialog_content = "Seperti inikah rasanya kematian? Agak berbeda… dari yang kubayangkan… Rasanya sangat kesepian…",
  ui_story_9_1_1_156_dialog_content = "(Mendelson, pada akhirnya, kau dan Mantiz membantu kami..)",
  ui_story_9_1_1_157_dialog_content = "Tapi, kenapa aku tak bisa merasakan kehadiran Soroz?",
  ui_story_9_1_1_158_dialog_content = "Yah… Aku menemukan sesuatu di Bridge. Sepertinya itu suatu komponen.",
  ui_story_9_1_1_159_dialog_content = "Tapi, komponen itu tak bisa diperbaiki. Hanya bagian kecil ini yang tampaknya masih cukup lengkap.",
  ui_story_9_1_1_160_dialog_content = "Ini… Aku ingat Soroz bilang ada komponen utama dalam Echo Template.",
  ui_story_9_1_1_161_dialog_content = "Kesadaran Colossus sebenarnya tersimpan di dalam inti ini.",
  ui_story_9_1_1_162_dialog_content = "Kalau benda ini memang intinya, mungkin kita bisa memulihkan kesadaran Soroz!",
  ui_story_9_1_1_163_dialog_content = "Bagus! Apakah ini intinya?",
  ui_story_9_1_1_164_dialog_content = "Seharusnya iya… Soroz memang pernah bilang soal Echo Template, tapi tidak menunjukkannya kepadaku…",
  ui_story_9_1_1_165_dialog_content = "Yah, tidak mungkin Colossus melepasnya agar kamu bisa lihat, 'kan?",
  ui_story_9_1_1_166_dialog_content = "Jadi… Menurutmu ini intinya?",
  ui_story_9_1_1_167_dialog_content = "Sepertinya begitu…",
  ui_story_9_1_1_168_dialog_content = "Kau tahu cara memperbaikinya?",
  ui_story_9_1_1_169_dialog_content = "…",
  ui_story_9_1_1_170_dialog_content = "Aku…",
  ui_story_9_1_1_171_dialog_content = "PlayerName dan Nyonya Gronru, tidak satu pun dari Anda yang tahu cara memperbaikinya?",
  ui_story_9_1_1_172_dialog_content = "Maaf.",
  ui_story_9_1_1_173_dialog_content = "Aku masih belum mahir untuk memperbaiki teknologi dari era itu.",
  ui_story_9_1_1_174_dialog_content = "Aku… hanya belajar sedikit tentang Colossus dari Soroz.",
  ui_story_9_1_1_175_dialog_content = "Tapi aku tak mempedulikannya, dan aku tak pernah menyangka kalau suatu hari… aku mungkin saja kehilangan Soroz.",
  ui_story_9_1_1_X175_dialog_content = "Kalau saja aku lebih peduli dengan Soroz, mungkin…",
  ui_story_9_1_1_176_dialog_content = "Ini ujian, PlayerName. Kamu bisa jadi kuat hanya kalau kamu bisa mengasah keteguhanmu dalam kesendirian.",
  ui_story_9_1_1_177_dialog_content = "Kenyataannya adalah kau masih hidup, dan kewajibanku adalah menjaga agar kau tetap hidup.",
  ui_story_9_1_1_178_dialog_content = "PlayerName, aku bisa terbang melayang di atas Lumopolis dan kau bisa menemuiku sewaktu-waktu kalau kau membutuhkanku.",
  ui_story_9_1_1_179_dialog_content = "Maaf, Soroz, kau jadi begini gara-gara aku.",
  ui_story_9_1_1_180_dialog_content = "Bisakah kau mendengarku, Soroz?",
  ui_story_9_1_1_181_dialog_content = "Maafkan aku.",
  ui_story_9_1_1_182_dialog_content = "Maaf karena aku ceroboh dan tidak merawatmu.",
  ui_story_9_1_1_183_dialog_content = "PlayerName…",
  ui_story_9_1_1_184_dialog_content = "Aku tak paham. Bukankah Colossus ini jadi lebih kokoh dari sebelumnya?",
  ui_story_9_1_1_185_dialog_content = "Kenapa PlayerName sedih?",
  ui_story_9_1_1_186_dialog_content = "Hush, Raphael.",
  ui_story_9_1_1_187_dialog_content = "Oh, maaf.",
  ui_story_9_1_1_188_dialog_content = "Kau meninggalkan Soroz untuk melindungi rakyat Lumopolis, PlayerName.",
  ui_story_9_1_1_189_dialog_content = "Aku juga bertanggung jawab atas kejadian ini.",
  ui_story_9_1_1_190_dialog_content = "Aku menghargai bantuanmu, tapi aku tak bisa menyalahkan kalian atas apa yang terjadi pada Soroz.",
  ui_story_9_1_1_191_dialog_content = "Ini semua ulah Schummer dan Eclipsite!",
  ui_story_9_1_1_192_dialog_content = "Benar, Schummer, hampir saja lupa!",
  ui_story_9_1_1_193_dialog_content = "Ada hal penting yang harus kusampaikan padamu, Carleen.",
  ui_story_9_1_1_194_dialog_content = "Ada apa?",
  ui_story_9_1_1_195_dialog_content = "Lumo Knights menemukan Aviduz jatuh di <color=#FFB400>Eraveil</color>!",
  ui_story_9_1_1_196_dialog_content = "Baiklah. Sepertinya sekarang kita harus pergi ke kampung halaman PlayerName.",
  ui_story_9_1_1_197_dialog_content = "Eraveil…?",
  ui_story_9_1_1_198_dialog_content = "Ironis sekali, Aviduz jatuh di Eraveil.",
  ui_story_9_1_1_199_dialog_content = "Ada hal lain yang harus kukatakan padamu, PlayerName.",
  ui_story_9_1_1_200_dialog_content = "Serangan khusus Aviduz ke kota dan ketiga modul…",
  ui_story_9_1_1_201_dialog_content = "Aku sudah melaporkannya ke Lumopolis.",
  ui_story_9_1_1_202_dialog_content = "Kuharap kamu bisa mengerti, PlayerName.",
  ui_story_9_1_1_203_dialog_content = "Tak apa, aku mengerti.",
  ui_story_9_1_1_204_dialog_content = "Ketiga modul itu…",
  ui_story_9_1_1_205_dialog_content = "Apa kau masih ingat salah satu dari ketiga modul itu, <color=#FFB400>Think Tank Module</color>, PlayerName?",
  ui_story_9_1_1_206_dialog_content = "Tentu saja. Aku bahkan ingat saat Mendelson bilang…",
  ui_story_9_1_1_207_dialog_content = "Ada banyak informasi tersimpan di dalamnya. Bisa dibilang, semua informasi yang kita inginkan ada di sana.",
  ui_story_9_1_1_208_dialog_content = "Ya, aku juga ingat itu.",
  ui_story_9_1_1_209_dialog_content = "Cari Think Tank Module dan kita akan tahu cara memperbaiki Echo Template!",
  ui_story_9_1_1_210_dialog_content = "Ya! PlayerName, Carleen…",
  ui_story_9_1_1_211_dialog_content = "Menuju Eraveil!",
  ui_story_9_1_1_212_dialog_content = "<color=#e8d9bb>Eraveil</color>",
  ui_story_9_1_1_213_dialog_content = "Persis seperti dugaanku, kau tetap seorang Caelestite…",
  ui_story_9_1_1_214_dialog_content = "Kembali ke Eraveil, kuburan massal, hanya untuk mati.",
  ui_story_9_1_1_215_dialog_content = "…",
  ui_story_9_1_1_216_dialog_content = "Kau hanya bisa menimbulkan masalah bagi orang lain.",
  ui_story_9_1_1_217_dialog_content = "Sampai aku mendapatkan apa yang kumau,",
  ui_story_9_1_1_218_dialog_content = "kau tidak boleh mati.",
  ui_story_9_1_1_219_dialog_content = "*Batuk-batuk*",
  ui_story_9_1_1_220_dialog_content = "Akhirnya, kau bangun.",
  ui_story_9_1_1_221_dialog_content = "… Aku jadi marah… ketika… orang yang pertama kulihat… ternyata adalah kau…",
  ui_story_9_1_1_222_dialog_content = "Itu cara berterima kasih yang sangat baik setelah kau babak belur seperti ini.",
  ui_story_9_1_1_223_dialog_content = "Omong kosong… *Batuk-batuk**",
  ui_story_9_1_1_224_dialog_content = "Akuilah, Schummer. Kau kalah. Telak.",
  ui_story_9_1_1_225_dialog_content = "Aku.. tidak kalah… dari orang-orang itu.",
  ui_story_9_1_1_226_dialog_content = "Cih, tentu saja tidak. Kau tahu kenapa kau kalah?",
  ui_story_9_1_1_227_dialog_content = "Hentikan… *Batuk-batuk*",
  ui_story_9_1_1_228_dialog_content = "Karena kau tak cukup kuat.",
  ui_story_9_1_1_229_dialog_content = "Aku… aku tak mau mendengarnya…",
  ui_story_9_1_1_230_dialog_content = "Sepertinya aku bisa memberimu satu kesempatan lagi.",
  ui_story_9_1_1_231_dialog_content = "Bantu aku menyelesaikan eksperimennya, dan kujamin kau akan tahu…",
  ui_story_9_1_1_232_dialog_content = "Bagaimana rasanya menjadi benar-benar tak terkalahkan.",
  ui_story_9_1_1_233_dialog_content = "Kesempatan lain…? Memperkuat Seed?",
  ui_story_9_1_1_234_dialog_content = "Sepertinya otakmu masih bekerja.",
  ui_story_9_1_1_235_dialog_content = "*Batuk*... Aku punya... hanya satu pertanyaan...",
  ui_story_9_1_1_236_dialog_content = "Kau sangat menjengkelkan.",
  ui_story_9_1_1_237_dialog_content = "Kenapa kau membantuku?",
  ui_story_9_1_1_238_dialog_content = "Jangan salah paham, aku hanya ingin menyelesaikan eksperimennya.",
  ui_story_9_1_1_239_dialog_content = "…",
  ui_story_9_1_1_240_dialog_content = "Dan kau adalah subjek favoritku.",
  ui_story_9_1_1_241_dialog_content = "…",
  ui_story_9_1_1_242_dialog_content = "Kenapa kau mau membantuku?",
  ui_story_9_1_1_243_dialog_content = "Aku… aku tahu mereka salah…",
  ui_story_9_2_1_1_dialog_content = "Ini tempat jatuhnya Aviduz… <color=#FFB400>Eraveil</color>.",
  ui_story_9_2_1_2_dialog_content = "Ini dia…",
  ui_story_9_2_1_3_dialog_content = "(Kampung halaman yang kuimpikan selama 17 tahun…)",
  ui_story_9_2_1_4_dialog_content = "(Hampir sampai…)",
  ui_story_9_2_1_5_dialog_content = "Kami semua di sini bersamamu, PlayerName.",
  ui_story_9_2_1_6_dialog_content = "Jangan lupa bahwa Anda masih memiliki kami, PlayerName.",
  ui_story_9_2_1_7_dialog_content = "Terima kasih, Vice dan Carleen.",
  ui_story_9_2_1_8_dialog_content = "Berapa kali harus kubilang kalau itu tidak perlu, PlayerName?",
  ui_story_9_2_1_9_dialog_content = "Tetap saja, aku harus berterima kasih.",
  ui_story_9_2_1_10_dialog_content = "Berkat dirimu, aku berani menghadapi dunia.",
  ui_story_9_2_1_11_dialog_content = "Kalau begitu, aku harus berterima kasih pada kalian berdua juga.",
  ui_story_9_2_1_12_dialog_content = "Karena kalian memberiku kesempatan untuk mengenal dunia.",
  ui_story_9_2_1_13_dialog_content = "PlayerName, Carleen…",
  ui_story_9_2_1_14_dialog_content = "Perjalanan kita baru saja dimulai!",
  ui_story_9_2_1_15_dialog_content = "Ada yang tahu Eraveil ini tempat seperti apa?",
  ui_story_9_2_1_16_dialog_content = "Aku pernah membacanya, tapi PlayerName mungkin tahu lebih banyak.",
  ui_story_9_2_1_17_dialog_content = "Eraveil adalah rumahku. Iklimnya cukup hangat sepanjang tahun.",
  ui_story_9_2_1_18_dialog_content = "Mainkan beberapa klip tentang Eraveil, Soroz.",
  ui_story_9_2_1_19_dialog_content = "…",
  ui_story_9_2_1_20_dialog_content = "…",
  ui_story_9_2_1_21_dialog_content = "Soroz? Sor…",
  ui_story_9_2_1_22_dialog_content = "Anu, PlayerName, Echo Template milik Soroz, anu…",
  ui_story_9_2_1_23_dialog_content = "…",
  ui_story_9_2_1_24_dialog_content = "Mainkan lagi, Soroz.",
  ui_story_9_2_1_25_dialog_content = "Memainkan Eraveil untuk yang keenam belas kali.",
  ui_story_9_2_1_26_dialog_content = "\"Di selatan World's Spine, tersembunyi lembah hijau Eraveil yang dikelilingi pegunungan.\"",
  ui_story_9_2_1_27_dialog_content = "\"Iklimnya cukup hangat sepanjang tahun, dan dihuni oleh Caelestite pekerja keras dari berbagai generasi.\"",
  ui_story_9_2_1_28_dialog_content = "Apa benda lucu itu, Soroz?",
  ui_story_9_2_1_29_dialog_content = "Dandelion. Bagian yang kuning itu bunga dan yang putih itu bijinya.",
  ui_story_9_2_1_30_dialog_content = "Kenapa aku tak bisa memegangnya?",
  ui_story_9_2_1_31_dialog_content = "Itu hanya video, PlayerName.",
  ui_story_9_2_1_32_dialog_content = "Aku bisa memainkannya lagi kalau kau mau.",
  ui_story_9_2_1_33_dialog_content = "Memainkan Eraveil untuk yang ketujuh belas kali.",
  ui_story_9_2_1_34_dialog_content = "… ke-90 kali.",
  ui_story_9_2_1_35_dialog_content = "… ke-437 kali.",
  ui_story_9_2_1_36_dialog_content = "… ke-2.628 kali.",
  ui_story_9_2_1_37_dialog_content = "Aku bersumpah akan mengembalikan kesadaranmu, Soroz!",
  ui_story_9_2_1_38_dialog_content = "<color=#e8d9bb>Eraveil</color>",
  ui_story_9_2_1_39_dialog_content = "Kita sudah sampai.",
  ui_story_9_2_1_40_dialog_content = "Ini Eraveil?",
  ui_story_9_2_1_41_dialog_content = "Sama sekali tidak seperti yang kubayangkan…",
  ui_story_9_2_1_42_dialog_content = "Ini benar-benar berbeda dengan video yang kutonton tadi!",
  ui_story_9_2_1_43_dialog_content = "Kau yakin ini tempatnya?",
  ui_story_9_2_1_44_dialog_content = "Menurut koordinat, lokasinya memang di sini.",
  ui_story_9_2_1_45_dialog_content = "…",
  ui_story_9_2_1_46_dialog_content = "Di mana-mana hanya ada rumput layu…",
  ui_story_9_2_1_47_dialog_content = "Hei, aku melihat batuan putih di bawah rumput.",
  ui_story_9_2_1_48_dialog_content = "Batu-batunya ditata dengan rapi, mungkin ini fondasi sebuah rumah.",
  ui_story_9_2_1_49_dialog_content = "Aku juga lihat di sini… dan di sana…",
  ui_story_9_2_1_50_dialog_content = "Mungkin, dulu ini permukiman yang cukup besar.",
  ui_story_9_2_1_51_option_content = "Psychic Scan",
  ui_story_9_2_1_52_dialog_content = "(Ketiadaan…)",
  ui_story_9_2_1_53_dialog_content = "Kenapa aku tak bisa merasakan apa pun…?",
  ui_story_9_2_1_54_dialog_content = "Sudah terlalu lama, PlayerName. Bahkan batunya pun terkikis.",
  ui_story_9_2_1_55_option_content = "Psychic Scan",
  ui_story_9_2_1_56_dialog_content = "…",
  ui_story_9_2_1_57_dialog_content = "Ayo kita lanjutkan, PlayerName, mungkin…",
  ui_story_9_2_1_58_option_content = "Psychic Scan",
  ui_story_9_2_1_59_dialog_content = "Hatsyiii!",
  ui_story_9_2_1_60_dialog_content = "Awas, aku merasakan <color=#FFB400>Darkflow</color>!",
  ui_story_9_2_1_61_dialog_content = "Apakah itu karena Aviduz ada di dekat sini?",
  ui_story_9_2_1_62_dialog_content = "Kurasa bukan… Darkflow-nya sangat kuat di sini. Sepertinya ada sesuatu yang ikut masuk juga.",
  ui_story_9_2_1_63_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_9_2_1_64_dialog_content = "Aku baik-baik saja.",
  ui_story_9_2_1_65_dialog_content = "Carleen, di belakangmu!",
  ui_story_9_2_1_66_dialog_content = "Aahhhhhh!",
  ui_story_9_2_1_67_dialog_content = "Menyebar! Ice Flower!",
  ui_story_9_2_1_68_dialog_content = "Eclipsite! Berani-beraninya kalian menghancurkan rumah PlayerName!",
  ui_story_9_2_1_69_dialog_content = "Berikan perintah, PlayerName!",
  ui_story_9_2_2_1_dialog_content = "<color=#e8d9bb>Di dalam Aviduz</color>",
  ui_story_9_2_2_2_dialog_content = "Tetaplah berbaring.",
  ui_story_9_2_2_3_dialog_content = "Apakah ini <color=#FFB400>healing pod</color>?",
  ui_story_9_2_2_4_dialog_content = "Apa kamu merasa lebih baik?",
  ui_story_9_2_2_5_dialog_content = "Rupanya kau sudah menduga hal ini… *Batuk-batuk*",
  ui_story_9_2_2_6_dialog_content = "Karena itu… kau memasukkan sampah ini ke Colossus milikku…",
  ui_story_9_2_2_7_dialog_content = "Jaga omonganmu.",
  ui_story_9_2_2_8_dialog_content = "Ini terlihat… menjijikkan.",
  ui_story_9_2_2_9_dialog_content = "Kau memang menyedihkan.",
  ui_story_9_2_2_10_dialog_content = "Apa? Tidak… *Batuk-batuk*… Bukankah kau mau menyelamatkan subjek favoritmu?",
  ui_story_9_2_2_11_dialog_content = "Sudah kubilang, kamu bisa memiliki kekuatan tak tertandingi kalau kau mau meninggalkan semua tentang Caelestite.",
  ui_story_9_2_2_12_dialog_content = "Dan sudah kukatakan berulang kali, aku bukan lagi seorang Caelestite.",
  ui_story_9_3_2_1_dialog_content = "Hei, kau yakin ini jalannya?",
  ui_story_9_3_2_2_dialog_content = "Apa kau meragukanku, pria yang paling bisa diandalkan di Rediesel Wrench?",
  ui_story_9_3_2_3_dialog_content = "Apa? Kau yang menunjukkan jalan dari tadi?",
  ui_story_9_3_2_4_dialog_content = "Beruntung sekali bisa menemukan bom di tempat seperti ini!",
  ui_story_9_3_2_5_dialog_content = "Tunggu, bukankah ini benda yang tadi kubuang?",
  ui_story_9_3_2_6_dialog_content = "Jadi, kita hanya berputar-putar saja?",
  ui_story_9_3_2_7_dialog_content = "Bicara apa kau? Aku mengikuti petanya!",
  ui_story_9_3_2_8_dialog_content = "Brock, dasar bodoh, kau membaca petanya terbalik!",
  ui_story_9_3_2_9_dialog_content = "Untung saja kita tidak makin tersesat.",
  ui_story_9_3_2_10_dialog_content = "<size=45>Brock!</size>",
  ui_story_9_3_2_11_dialog_content = "Aku akan membuka kepalamu dan mencari tahu apa yang salah di dalamnya!",
  ui_story_9_3_2_12_dialog_content = "♪Jangan takut, Barbara di sini!",
  ui_story_9_3_2_13_dialog_content = "<anim type=Shake>♪Saat ada cinta, pasti ada harapan!</anim>",
  ui_story_9_3_2_14_dialog_content = "Argh! Aku sudah tak tahan lagi, Bos! Boleh aku menghajarnya!?",
  ui_story_9_3_2_X14_dialog_content = "Bos bilang, hari ini kita harus rukun. Aku tak akan merendahkan diriku hanya untuk mendapatkan perhatianmu!",
  ui_story_9_3_2_X15_dialog_content = "Kalau tak kaututup mulutmu itu, mungkin si Bos sekalipun tak akan bisa menahanku untuk mengakhiri hidupmu…",
  ui_story_9_3_2_15_dialog_content = "Hei… omong-omong, mana si Bos?",
  ui_story_9_3_2_16_dialog_content = "Hoi, kalian tahu Bos ada di mana?",
  ui_story_9_3_2_17_dialog_content = "Auraku yang keren membuatnya takut! Aku tahu aku memang nomor 1!",
  ui_story_9_3_2_18_dialog_content = "Barusan sih dia memang di sini.",
  ui_story_9_3_2_19_dialog_content = "Apakah Honcho Sinsa sudah pergi?",
  ui_story_9_3_2_20_dialog_content = "Hei, Bopper juga tak ada.",
  ui_story_9_3_2_21_dialog_content = "Maju, para pengikutku!",
  ui_story_9_3_2_22_dialog_content = "Kembali ke sini, Brock!",
  ui_story_9_3_2_23_dialog_content = "<size=45><anim type=Shake>&*#%#%…!</anim></size>",
  ui_story_9_3_2_24_dialog_content = "<color=#e8d9bb>Boing!</color>",
  ui_story_9_3_2_25_dialog_content = "Aduh, sakit banget!",
  ui_story_9_3_2_26_dialog_content = "Hei, siapa yang memasang jebakan sialan itu untukku?!",
  ui_story_9_3_2_27_dialog_content = "Dasar pengecut, beraninya hanya menyergap!",
  ui_story_9_3_2_28_dialog_content = "Keluar dan hadapi aku layaknya pria sejati! Akan kubuat kau jadi daging giling!",
  ui_story_9_3_2_29_dialog_content = "Tempat yang kita pijak terlihat sama saja…",
  ui_story_9_3_2_30_dialog_content = "Sepertinya ini jebakan buatan manusia.",
  ui_story_9_3_2_31_dialog_content = "Tapi, melihat dedaunan yang menutupi lubang ini…",
  ui_story_9_3_2_32_dialog_content = "Ayo, keluar sekarang juga!",
  ui_story_9_3_2_33_dialog_content = "Kau dengar aku, Bos?",
  ui_story_9_3_2_34_dialog_content = "Apa kaubilang?",
  ui_story_9_3_2_35_dialog_content = "Itu lubang alami, bukan jebakan! Tidak ada yang menyerang kita!",
  ui_story_9_3_2_36_dialog_content = "…",
  ui_story_9_3_2_37_dialog_content = "Anggaplah kau tak dengar apa pun, Bopper, dan jangan beri tahu adikku bahwa aku habis marah-marah.",
  ui_story_9_3_2_38_dialog_content = "Tentu saja, asal kau memang mendengarkanku…",
  ui_story_9_3_2_39_dialog_content = "<anim type=Shake>Majulah, para pengikutku!</anim>",
  ui_story_9_3_2_40_dialog_content = "<anim type=Shake>Kembali ke sini, Brock!</anim>",
  ui_story_9_3_2_41_dialog_content = "Baiklah, baiklah, baiklah…",
  ui_story_9_3_2_42_dialog_content = "Karena itu bukan jebakan, kita tak perlu takut disergap. Ayo kita segera keluar dari sini.",
  ui_story_9_3_2_X42_dialog_content = "Regina! Brock! Bisakah kalian mendengarku?",
  ui_story_9_3_2_43_dialog_content = "Berdasarkan durasi kita jatuh dan kecepatan gravitasinya…",
  ui_story_9_3_2_44_dialog_content = "Mereka tak akan mendengar kita, sekeras apa pun kita berteriak.",
  ui_story_9_3_2_45_dialog_content = "Regina!",
  ui_story_9_3_2_46_dialog_content = "Aku akan beri tahu Eve bahwa kau marah-marah, Bos!",
  ui_story_9_3_2_47_dialog_content = "Tidak, tidak, tidak… Tadi kau bilang apa soal berapa lama dan kecepatannya?",
  ui_story_9_3_2_48_dialog_content = "Intinya, lubang ini terlalu dalam sehingga mereka tak bisa mendengar kita.",
  ui_story_9_3_2_49_dialog_content = "*Batuk-batuk* Begitu, ya…",
  ui_story_9_3_2_50_dialog_content = "Analisis dari pilot <color=#FFB400>Lepidoz</color> memang masuk akal.",
  ui_story_9_3_2_51_dialog_content = "Baiklah, ayo bergerak dan lihat kemana perginya lubang ini.",
  ui_story_9_3_2_52_dialog_content = "<color=#e8d9bb>Ding! Klang!</color>",
  ui_story_9_3_2_53_dialog_content = "Lihat, Bos, banyak sekali suku cadang Colossus di sini!",
  ui_story_9_3_2_54_dialog_content = "Wah, kepala kecil yang sangat bulat dan sayap mungil yang lucu… Benar-benar keterampilan yang luar biasa!",
  ui_story_9_3_2_55_dialog_content = "Ini pertama kalinya aku melihat Firefly yang sangat cantik… Lepidoz pasti menyukainya!",
  ui_story_9_3_2_56_dialog_content = "Benda ini hanya memiliki satu sayap tersisa. Apa gunanya selain sebagai bola sepak?",
  ui_story_9_3_2_57_dialog_content = "Masih ada lagi di sana! Aku akan bawa ini dan itu…",
  ui_story_9_3_2_58_dialog_content = "Kau seharusnya fokus pada tujuan utama kita ke sini!",
  ui_story_9_3_2_59_dialog_content = "Aku tahu, tapi aku berjanji kepada Lepidoz untuk membawakannya oleh-oleh.",
  ui_story_9_3_2_60_dialog_content = "Aku yakin banyak barang yang lebih berharga di Colossus hitam yang terdampar itu.",
  ui_story_9_3_2_61_dialog_content = "Uh…",
  ui_story_9_3_2_62_dialog_content = "Tapi, kenapa banyak sekali suku cadang tersebar di gua ini?",
  ui_story_9_3_2_63_dialog_content = "Jangan-jangan, sebenarnya kita menemukan…",
  ui_story_9_3_2_64_dialog_content = "?",
  ui_story_9_3_2_65_dialog_content = "Kita harus menemukan jalan keluar dan keluar!",
  ui_story_9_3_2_66_dialog_content = "Sepertinya ada orang lain di sini.",
  ui_story_9_4_1_1_dialog_content = "Ada yang aneh!",
  ui_story_9_4_1_2_dialog_content = "Tusuk musuh-musuh itu!",
  ui_story_9_4_1_3_dialog_content = "Hei, Nona, sebaiknya kamu pikir lagi serangan mengendap-endap itu.",
  ui_story_9_4_1_4_dialog_content = "Kau Aurorian?",
  ui_story_9_4_1_5_dialog_content = "Lumayan untuk seorang petarung, tapi penilaianmu meninggalkan sesuatu yang diinginkan.",
  ui_story_9_4_1_6_dialog_content = "Apa-apaan kau…!",
  ui_story_9_4_1_7_dialog_content = "Ada apa, Carleen?",
  ui_story_9_4_1_8_dialog_content = "Kau baik-baik saja, Bos?",
  ui_story_9_4_1_9_dialog_content = "Aku baik-baik saja!",
  ui_story_9_4_1_10_dialog_content = "Kamu rupanya!",
  ui_story_9_4_1_11_dialog_content = "Kau kenal penjahat Rediesel Wrench ini, PlayerName?",
  ui_story_9_4_1_12_option_content = "Saat berada di Illumina…",
  ui_story_9_4_1_13_dialog_content = "Setelah Soroz dan aku meledak dari bawah permukaan, kami jatuh di dekat Undercity.",
  ui_story_9_4_1_14_dialog_content = "Dia adalah pemimpin para bandit.",
  ui_story_9_4_1_15_dialog_content = "Kenapa kau bilang begitu? Kami justru menyelamatkanmu dari para Eclipsite itu, lho!",
  ui_story_9_4_1_16_dialog_content = "Di Rediesel Desert, Soroz hampir dirampok dan dibongkar oleh orang itu!",
  ui_story_9_4_1_17_option_content = "Saat berada di Rediesel Desert…",
  ui_story_9_4_1_18_dialog_content = "Dia bersama gengnya mencegat saat kami hendak pergi.",
  ui_story_9_4_1_19_dialog_content = "Dan dia hampir mencincang Soroz.",
  ui_story_9_4_1_20_dialog_content = "Yah, aku tidak bisa membantahnya. Itu salahku.",
  ui_story_9_4_1_21_dialog_content = "Tapi, berkat bantuanmu, adikku akhirnya bisa diselamatkan.",
  ui_story_9_4_1_22_dialog_content = "Aku berutang budi kepadamu, PlayerName.",
  ui_story_9_4_1_23_dialog_content = "Kau pernah ke Rediesel Desert?",
  ui_story_9_4_1_24_dialog_content = "Setelah kami pergi terakhir kalinya dari Lumopolis.",
  ui_story_9_4_1_25_dialog_content = "Rupanya si tuan putri dari Lumopolis ini masih saja agresif seperti dulu.",
  ui_story_9_4_1_26_dialog_content = "Menyerang tanpa tahu apa yang sebenarnya terjadi… Bagaimana jadinya orang yang tak bersalah jadi terluka?",
  ui_story_9_4_1_27_dialog_content = "Dia tak sengaja, Sinsa.",
  ui_story_9_4_1_28_dialog_content = "Itu memang kesalahanku.",
  ui_story_9_4_1_29_dialog_content = "Aku, Carleen de Schwartz, meminta maaf atas tindakanku.",
  ui_story_9_4_1_30_dialog_content = "Tapi kau bersikeras menghancurkan Lumopolis…",
  ui_story_9_4_1_31_dialog_content = "Kita bisa menyelesaikannya di sini sekarang juga.",
  ui_story_9_4_1_X31_dialog_content = "Kalau mau bertarung, setidaknya pilih waktu dan tempat yang tepat!",
  ui_story_9_4_1_32_dialog_content = "Dia penuh semangat, ya, PlayerName? Bagaimana kalian bisa bekerja sama?",
  ui_story_9_4_1_33_dialog_content = "Yah, aku tidak tahu apa daging sapi kalian berdua...",
  ui_story_9_4_1_34_dialog_content = "Tapi karena kalian berdua telah bertarung bersamaku dan Vice, Saya harap Anda dapat mengesampingkan perbedaan Anda untuk saat ini.",
  ui_story_9_4_1_35_dialog_content = "Tentu, saya akan pergi dengan apa PlayerName kata.",
  ui_story_9_4_1_36_dialog_content = "Harusnya aku yang bilang begitu.",
  ui_story_9_4_1_X36_dialog_content = "Harap diingat bahwa saya berhenti hanya karena saya memiliki tugas lain yang harus saya tangani. Aku tidak punya waktu untuk menyia-nyiakanmu.",
  ui_story_9_4_1_X37_dialog_content = "Hah, aku tak percaya kau bilang begitu…",
  ui_story_9_4_1_37_dialog_content = "Ehem! Hei! Ayo ganti topik, Sinsa…",
  ui_story_9_4_1_38_option_content = "Siapa gadis di belakangmu itu?",
  ui_story_9_4_1_39_dialog_content = "Oh, ini Bopper.",
  ui_story_9_4_1_40_dialog_content = "Halo, semuanya, aku Bopper.",
  ui_story_9_4_1_41_dialog_content = "Jadi, kau PlayerName? Eve sering membicarakanmu!",
  ui_story_9_4_1_42_dialog_content = "Kami melihat Colossus hitam jatuh di sekitar sini dan datang mencari.",
  ui_story_9_4_1_43_dialog_content = "Lalu kami jatuh ke dalam lubang dan bertemu denganmu setelah keluar dari sana.",
  ui_story_9_4_1_44_option_content = "Sedang apa kalian di sini?",
  ui_story_9_4_1_45_dialog_content = "Tentu saja untuk mengambil jarahan! Hahahahaha!",
  ui_story_9_4_1_46_dialog_content = "Jarahan? Apa maksudmu?",
  ui_story_9_4_1_47_dialog_content = "Kami melihat Colossus hitam jatuh di sekitar sini dan datang mencari.",
  ui_story_9_4_1_48_dialog_content = "Lalu kami jatuh ke dalam lubang dan bertemu denganmu setelah keluar dari sana.",
  ui_story_9_4_1_49_dialog_content = "Hai, aku Bopper. Kau pasti PlayerName? Eve sering membicarakanmu!",
  ui_story_9_4_1_50_dialog_content = "Kau juga mencari harta karun, PlayerName?",
  ui_story_9_4_1_51_dialog_content = "Yah, ceritanya panjang.",
  ui_story_9_4_1_52_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian…</color>",
  ui_story_9_4_1_53_dialog_content = "<size=45>Eraveil?!</size>",
  ui_story_9_4_1_54_dialog_content = "Jadi inilah Eraveil…",
  ui_story_9_4_1_55_dialog_content = "Banyak hal yang telah kaulalui dalam waktu singkat, PlayerName.",
  ui_story_9_4_1_56_dialog_content = "Itu mungkin yang harus kulalui sebagai konsekuensi kembali ke dunia permukaan.",
  ui_story_9_4_1_57_dialog_content = "Tapi aku tak akan pernah berhenti berharap.",
  ui_story_9_4_1_58_dialog_content = "Aku tersentuh. Aku akan ikut dalam perjalananmu.",
  ui_story_9_4_1_59_dialog_content = "Hah?",
  ui_story_9_4_1_60_dialog_content = "Anda keberatan?",
  ui_story_9_4_1_61_dialog_content = "Sama sekali tidak. Selamat bergabung dengan tim kami!",
  ui_story_9_4_1_62_dialog_content = "Bagaimanapun, kita bisa menggunakan semua bantuan yang bisa kita dapatkan.",
  ui_story_9_4_1_63_dialog_content = "Sepertinya kita sepakat!",
  ui_story_9_4_1_64_dialog_content = "Tapi bagaimana dengan Regina dan yang lainnya?",
  ui_story_9_4_1_65_dialog_content = "Oh, ya… Dalam perjalananmu, apa kau sempat lihat Rediesel Wrench lain?",
  ui_story_9_4_1_66_dialog_content = "Anggota kalian masih ada lagi?",
  ui_story_9_4_1_X66_dialog_content = "Ya, kami di Rediesel Wrench suka berwisata berkelompok.",
  ui_story_9_4_1_67_dialog_content = "Aku tak melihat siapa pun selain Eclipsite di sepanjang jalan ke sini.",
  ui_story_9_4_1_X67_dialog_content = "Aduh…",
  ui_story_9_4_1_68_dialog_content = "Yah, saat kau selesai bicara, Eclipsite muncul… Biasalah.",
  ui_story_9_4_1_69_dialog_content = "Mari kita lihat apakah kepemimpinanmu sudah berkembang, PlayerName!",
  ui_story_9_4_2_1_dialog_content = "(Eclipsian) Sekelompok Aurorian mendekat, nona.",
  ui_story_9_4_2_2_dialog_content = "(Eclipsian) Mereka juga membawa Caelestite.",
  ui_story_9_4_2_3_dialog_content = "(Eclipsian) Tapi kita terlalu kekurangan tenaga untuk menghalangi mereka.",
  ui_story_9_4_2_4_dialog_content = "Caelestite?",
  ui_story_9_4_2_5_dialog_content = "Apakah namanya PlayerName?",
  ui_story_9_4_2_6_dialog_content = "Tidak, si sampah itu sepertinya…",
  ui_story_9_4_2_7_dialog_content = "…",
  ui_story_9_4_2_8_dialog_content = "Kau memang tak ada gunanya, Schummer.",
  ui_story_9_4_2_9_dialog_content = "(Eclipsian) Pergi dan bawakan aku prajurit Lumopolis.",
  ui_story_9_4_2_10_dialog_content = "(Eclipsian) Ya, nona.",
  ui_story_9_4_2_11_dialog_content = "Aku benci hal yang rumit…",
  ui_story_9_4_2_12_dialog_content = "dan tidak suka membuang-buang sumber daya.",
  ui_story_9_4_2_13_dialog_content = "Tak ada yang boleh mengganggu eksperimennya.",
  ui_story_9_5_2_1_dialog_content = "<color=#e8d9bb>Tempat Persembunyian True Order</color>",
  ui_story_9_5_2_2_dialog_content = "Apa perintah darimu, Lady Victoria?",
  ui_story_9_5_2_3_dialog_content = "Kau harus mengumpulkan lebih banyak <color=#FFB400>Seed</color> untuk Lord of the Truth yang agung, Faust.",
  ui_story_9_5_2_4_dialog_content = "Suatu kehormatan bagiku, Lady Victoria.",
  ui_story_9_5_2_5_dialog_content = "Ajak Pact dan Nails juga bersamamu.",
  ui_story_9_5_2_6_dialog_content = "Baik, Lady Victoria. Semoga Truth memberkatimu.",
  ui_story_9_5_2_7_dialog_content = "Apakah ini yang kaumaksud tadi?",
  ui_story_9_5_2_8_dialog_content = "Kekuatan dari kegelapan yang ditakuti sekaligus didambakan.",
  ui_story_9_5_2_9_dialog_content = "Memang ada orang-orang yang hidup di bawah sinar matahari tapi tetap saja mau mengkhianati Truth dan secara sukarela mencari kekuatan Seed.",
  ui_story_9_5_2_10_dialog_content = "Kasihan orang-orang yang berpaling dari sifat Aurorian mereka.",
  ui_story_9_5_2_11_dialog_content = "Kau yakin mau menelannya?",
  ui_story_9_5_2_12_dialog_content = "Oh, saya lupa, Anda hanya sebuah buku dan mungkin tidak tahu banyak tentang sifat manusia.",
  ui_story_9_5_2_13_dialog_content = "Victoria Varaki.",
  ui_story_9_5_2_X13_dialog_content = "Cukup. Kau hanya perlu menaruhnya di tubuhku.",
  ui_story_9_5_2_14_dialog_content = "Oke. Coba kita lihat apa kau bisa melahapnya.",
  ui_story_9_5_2_15_dialog_content = "<color=#e8d9bb>Krauk! Glek!</color>",
  ui_story_9_5_2_16_dialog_content = "Bagaimana rasanya?",
  ui_story_9_5_2_17_dialog_content = "Rasanya agak mirip daging.",
  ui_story_9_5_2_18_dialog_content = "Ini adalah Seed yang diekstrak dari Caelestite.",
  ui_story_9_5_2_19_dialog_content = "Caelestite?",
  ui_story_9_5_2_20_dialog_content = "Jadi, sekarang kau tertarik dengan daging Caelestite?",
  ui_story_9_5_2_21_dialog_content = "Jaga kata-katamu, Victoria Varaki!",
  ui_story_9_5_2_22_dialog_content = "Sepertinya tubuhmu bisa menerimanya dengan baik.",
  ui_story_9_5_2_23_dialog_content = "Ini hanyalah permulaan.",
  ui_story_9_5_2_24_dialog_content = "Ya. Ini jadi makin menarik.",
  ui_story_9_5_2_25_dialog_content = "Jangan lupakan janji yang sudah kita buat.",
  ui_story_9_5_2_26_dialog_content = "Mana mungkin aku lupa? Aku sudah mengirimkan orang untuk mencari Seed.",
  ui_story_9_5_2_27_dialog_content = "Jangan lupakan juga orang-orang yang harus kausingkirkan.",
  ui_story_9_5_2_28_dialog_content = "Jangan serakah.",
  ui_story_9_5_2_29_dialog_content = "Kita harus menunggu kesempatan yang tepat.",
  ui_story_9_5_2_30_dialog_content = "<color=#e8d9bb>Jauh di Kedalaman Eraveil</color>",
  ui_story_9_5_2_31_dialog_content = "Lumayan juga, Nak!",
  ui_story_9_5_2_32_dialog_content = "Kau makin pandai menjadi pemimpin!",
  ui_story_9_5_2_33_dialog_content = "Terima kasih…",
  ui_story_9_5_2_X33_dialog_content = "*Uhuk-uhuk*",
  ui_story_9_5_2_34_dialog_content = "Kenapa, PlayerName?",
  ui_story_9_5_2_35_option_content = "Dingin sekali…",
  ui_story_9_5_2_36_dialog_content = "Nih, minum air hangat ini.",
  ui_story_9_5_2_37_dialog_content = "Aku tak menyangka kau sangat perhatian…",
  ui_story_9_5_2_38_dialog_content = "Dia selalu membawa termos untuk adiknya.",
  ui_story_9_5_2_39_dialog_content = "Santai saja. Sudah biasa bagiku.",
  ui_story_9_5_2_40_option_content = "Bukan apa-apa…",
  ui_story_9_5_2_41_dialog_content = "Ulurkan tanganmu, PlayerName.",
  ui_story_9_5_2_42_dialog_content = "Tanganmu sangat dingin!",
  ui_story_9_5_2_43_dialog_content = "Aku baik-baik saja, Vice.",
  ui_story_9_5_2_44_dialog_content = "Aneh, kenapa semakin jauh kita masuk semakin dingin?",
  ui_story_9_5_2_45_dialog_content = "Bukankah Eraveil harusnya hangat?",
  ui_story_9_5_2_46_dialog_content = "…",
  ui_story_9_5_2_47_dialog_content = "Hati-hati, semuanya, Darkflow semakin intens!",
  ui_story_9_5_2_48_dialog_content = "Aku khawatir Eraveil sudah berubah menjadi sarang Eclipsite.",
  ui_story_9_5_2_49_dialog_content = "!",
  ui_story_9_5_2_50_dialog_content = "Mungkin itulah yang memancing gerombolan Eclipsite yang tadi kita temui itu.",
  ui_story_9_5_2_51_dialog_content = "Mungkin saja Aviduz terdampar di sini bukan karena kebetulan.",
  ui_story_9_5_2_52_dialog_content = "Jangan-jangan…",
  ui_story_9_7_1_1_dialog_content = "Graaah!",
  ui_story_9_7_1_2_dialog_content = "Ya ampun, serangga lagi?",
  ui_story_9_7_1_3_dialog_content = "Baiklah! Siap!",
  ui_story_9_7_1_4_dialog_content = "Kau sedang apa, Bopper?",
  ui_story_9_7_1_5_dialog_content = "Berburu barang berharga.",
  ui_story_9_7_1_6_dialog_content = "Kenapa kau mengobrak-abrik rongsokan?",
  ui_story_9_7_1_7_dialog_content = "Ini bukan rongsokan, Bos!",
  ui_story_9_7_1_8_dialog_content = "Bagian ini sempurna untuk Lepidoz!",
  ui_story_9_7_1_9_dialog_content = "Aku belum pernah melihat baut ini… Akan kutunjukkan kepada Tiny One!",
  ui_story_9_7_1_10_dialog_content = "Dan coba lihat ini! Aku mengumpulkan Firefly warna merah, kuning, biru, dan hijau!",
  ui_story_9_7_1_11_dialog_content = "Bagus sekali, Bopper.",
  ui_story_9_7_1_12_dialog_content = "Tadi aku sama sekali tak sadar ada banyak barang bagus di sini!",
  ui_story_9_7_1_13_dialog_content = "Oh, masih ada lagi…",
  ui_story_9_7_1_14_dialog_content = "Apa ini, PlayerName?",
  ui_story_9_7_1_15_dialog_content = "Bagian Colossus, tapi bukan dari Aviduz…",
  ui_story_9_7_1_16_dialog_content = "Jadi, ini lepas dari Colossus lain?",
  ui_story_9_7_1_17_dialog_content = "Pada malam itu, 17 tahun lalu?",
  ui_story_9_7_1_18_dialog_content = "Dilihat dari kerusakannya, sepertinya kejadian itu kejam sekali.",
  ui_story_9_7_1_19_dialog_content = "…",
  ui_story_9_7_1_20_dialog_content = "Maafkan aku. Menurutku sayang sekali kalau meninggalkannya di sini.",
  ui_story_9_7_1_21_dialog_content = "Tetapi jika itu menyinggung PlayerName, aku tak akan mengambilnya…",
  ui_story_9_7_1_22_dialog_content = "Tentu saja tidak, Bopper.",
  ui_story_9_7_1_23_dialog_content = "Aku yakin barang-barang ini ingin punya rumah dan seseorang yang menghargainya.",
  ui_story_9_7_1_24_dialog_content = "Benarkah? Terima kasih, PlayerName!",
  ui_story_9_7_1_25_dialog_content = "Bopper!",
  ui_story_9_7_1_26_dialog_content = "Tapi PlayerName kan bilang tidak apa-apa…",
  ui_story_9_7_1_27_dialog_content = "Kita tak tahu harus pergi berapa lama lagi dan berapa pertarungan yang akan kita hadapi.",
  ui_story_9_7_1_28_dialog_content = "Kau harus tahu diri.",
  ui_story_9_7_1_29_dialog_content = "Baiklah…",
  ui_story_9_7_1_30_dialog_content = "Boleh kusimpan yang ini?",
  ui_story_9_7_1_31_dialog_content = "Tak apa, toh itu hanya barang kecil.",
  ui_story_9_7_1_32_dialog_content = "!",
  ui_story_9_7_1_33_dialog_content = "Kau tahu ini, Carleen?",
  ui_story_9_7_1_34_dialog_content = "Itu lencana <color=#FFB400>Lumo Guard</color>… Bagaimana bisa sampai di sini?",
  ui_story_9_7_1_35_dialog_content = "Di mana kau menemukannya, Bopper?",
  ui_story_9_7_1_36_dialog_content = "Di perempatan saat Eclipsite menyerang kita.",
  ui_story_9_7_1_37_dialog_content = "Boleh kulihat?",
  ui_story_9_7_1_38_dialog_content = "Tentu.",
  ui_story_9_7_1_39_option_content = "Psychic Scan",
  ui_story_9_7_1_40_dialog_content = "Akhirnya, aku memakai lencana ini!",
  ui_story_9_7_1_41_dialog_content = "Kau lihat ini, Bu?",
  ui_story_9_7_1_42_dialog_content = "Putramu kini menjadi seorang Lumo Guard sejati!",
  ui_story_9_7_1_43_dialog_content = "Aku tak perlu lagi melayani orang-orang bodoh di Uptown!",
  ui_story_9_7_1_44_dialog_content = "Tapi kau sudah tiada…",
  ui_story_9_7_1_45_dialog_content = "Kenapa kau bengong seperti orang bodoh? Lawan Eclipsite itu!",
  ui_story_9_7_1_46_dialog_content = "Ya!",
  ui_story_9_7_1_47_dialog_content = "Aahhhhhh!",
  ui_story_9_7_1_48_dialog_content = "Restui dan lindungi aku, Bu!",
  ui_story_9_7_1_49_dialog_content = "Di mana… aku…?",
  ui_story_9_7_1_50_dialog_content = "(Eclipsian) Ini adalah tawanan Lumopolis, nona.",
  ui_story_9_7_1_51_dialog_content = "(Eclipsian) Bagus sekali.",
  ui_story_9_7_1_52_dialog_content = "Eclipsite? Apa yang kalian lakukan kepadaku?",
  ui_story_9_7_1_53_dialog_content = "Lepaskan!",
  ui_story_9_7_1_54_dialog_content = "Jangan takut, tak akan terasa sakit!",
  ui_story_9_7_1_55_dialog_content = "Jangan mendekat! Tetap di sana!",
  ui_story_9_7_1_56_dialog_content = "Aghhh!",
  ui_story_9_7_1_57_dialog_content = "!",
  ui_story_9_7_1_58_dialog_content = "Apa yang kaulihat, PlayerName?",
  ui_story_9_7_1_59_dialog_content = "Aku melihat…",
  ui_story_9_7_1_60_option_content = "Seorang penjaga.",
  ui_story_9_7_1_61_dialog_content = "Lencana ini dulu milik seorang Lumo Guard.",
  ui_story_9_7_1_62_dialog_content = "!",
  ui_story_9_7_1_63_dialog_content = "Dia ditugaskan ke dalam pertempuran setelah bergabung dengan Guard.",
  ui_story_9_7_1_64_dialog_content = "Tapi pada akhirnya dia berubah menjadi Eclipsite.",
  ui_story_9_7_1_65_option_content = "Eclipsite.",
  ui_story_9_7_1_66_dialog_content = "Lencana ini dulu milik seorang Eclipsite.",
  ui_story_9_7_1_67_dialog_content = "Tak mungkin!",
  ui_story_9_7_1_68_dialog_content = "Tapi Eclipsite itu dulunya adalah seorang Lumo Guard.",
  ui_story_9_7_1_69_dialog_content = "Coba ulang lagi. Jadi dia penjaga atau Eclipsite?",
  ui_story_9_7_1_70_dialog_content = "Ada yang memaksa penjaga ini berubah menjadi Eclipsite…",
  ui_story_9_7_1_71_dialog_content = "Dan aku tahu jelas siapa orangnya—<color=#FFB400>Forsakin</color>!",
  ui_story_9_7_1_72_dialog_content = "Orang misterius di sebelah Schummer itu?",
  ui_story_9_7_1_73_dialog_content = "Benar! Masih ingat Seed yang kaukeluarkan dari tubuhku, Vice?",
  ui_story_9_7_1_74_dialog_content = "Ya, Seed itu nyaris mengubahmu jadi Eclipsite!",
  ui_story_9_7_1_75_dialog_content = "Wow, benarkah?",
  ui_story_9_7_1_76_dialog_content = "Aku melihat Forsakin memasukkan Seed ke dalam tubuh penjaga itu.",
  ui_story_9_7_1_77_dialog_content = "!",
  ui_story_9_7_1_78_dialog_content = "Seorang pria dengan koper putih berkata…",
  ui_story_9_7_1_79_dialog_content = "Seed merupakan satu-satunya cara untuk mengubah makhluk lain menjadi Eclipsite.",
  ui_story_9_7_1_80_dialog_content = "Jadi maksudmu si Forsakin itu mengubah seorang Lumo Guard menjadi Eclipsite?",
  ui_story_9_7_1_81_dialog_content = "Ya.",
  ui_story_9_7_1_82_dialog_content = "Jadi, Eclipsite yang baru saja kita bunuh itu dulunya penjaga Lumopolis?",
  ui_story_9_7_1_83_dialog_content = "Ya…",
  ui_story_9_7_1_84_dialog_content = "…",
  ui_story_9_7_1_85_dialog_content = "Berhenti menyalahkan diri sendiri dan tenggelam dalam kesedihan!",
  ui_story_9_7_1_86_dialog_content = "Kita tidak membunuh penjaga itu. Forsakin yang membunuhnya!",
  ui_story_9_7_1_87_dialog_content = "Sinsa benar.",
  ui_story_9_7_1_88_dialog_content = "Meskipun kita memang membunuh penjaga ini…",
  ui_story_9_7_1_89_dialog_content = "Jika bukan karena Forsakin, dia pasti tak akan menjadi Eclipsite.",
  ui_story_9_7_1_90_dialog_content = "…",
  ui_story_9_7_1_91_dialog_content = "Carleen…",
  ui_story_9_7_1_92_dialog_content = "Kurasa, sebaiknya kauambil lencana itu.",
  ui_story_9_7_1_93_dialog_content = "… Baiklah.",
  ui_story_9_7_1_94_dialog_content = "Aku, Carleen de Schwartz, dengan ini berkabung bagi mereka yang telah gugur.",
  ui_story_9_7_1_95_dialog_content = "Penjaga Lumopolis, pemegang lencana ini.",
  ui_story_9_7_1_96_dialog_content = "Dia menjalankan tugasnya dengan baik dan berjuang dengan gagah berani.",
  ui_story_9_7_1_97_dialog_content = "Meskipun dia ditangkap, menjadi Eclipsite, dan menyerang Aurorian, itu bukan karena kehendaknya sendiri.",
  ui_story_9_7_1_98_dialog_content = "Maafkan kami karena telah mengakhiri penderitaannya.",
  ui_story_9_7_1_99_dialog_content = "Semoga dia beristirahat dalam damai. Demi White Night…",
  ui_story_9_7_1_100_dialog_content = "Istirahatlah dalam damai…",
  ui_story_9_7_1_101_dialog_content = "…",
  ui_story_9_7_1_102_dialog_content = "Aviduz, Eraveil, Forsakin… Ini semua terlalu aneh.",
  ui_story_9_7_1_103_dialog_content = "Perasaanku tidak enak…",
  ui_story_9_7_1_104_dialog_content = "Schummer…",
  ui_story_9_7_1_105_dialog_content = "Mungkin Schummer masih hidup?",
  ui_story_9_7_1_106_dialog_content = "!",
  ui_story_9_7_1_107_dialog_content = "Apa pun itu, kita harus bergegas!",
  ui_story_9_7_1_108_dialog_content = "Aahhhhhh!",
  ui_story_9_7_1_109_dialog_content = "Waspada, masih ada lagi!",
  ui_story_9_7_1_110_dialog_content = "Apakah itu High-Level Eclipsite?",
  ui_story_9_7_1_111_dialog_content = "Aku belum pernah melihat Eclipsite yang dimutilasi sebelumnya.",
  ui_story_9_7_1_112_dialog_content = "<anim type=Shake>Aku… mau… pulang…</anim>",
  ui_story_9_7_1_113_dialog_content = "<anim type=Shake>Rumah… mau… pulang…</anim>",
  ui_story_9_7_1_114_dialog_content = "Apa dia berbicara bahasa Universese?",
  ui_story_9_7_1_115_dialog_content = "Aku tak paham apa yang ingin diucapkannya..",
  ui_story_9_7_1_116_dialog_content = "Aku merasakan aura Aurorian darinya.",
  ui_story_9_7_1_117_dialog_content = "Apakah dulu dia juga seorang Aurorian?",
  ui_story_9_7_1_118_dialog_content = "!",
  ui_story_9_7_1_119_dialog_content = "Aku bisa merasakan emosi yang kuat darinya…",
  ui_story_9_7_1_120_dialog_content = "Rasa sakit, keputusasaan, kemarahan, ketidakberdayaan… Semua terpendam dan tak bisa diluapkan.",
  ui_story_9_7_1_121_dialog_content = "Aurorian itu hanya ingin pulang ke rumah…",
  ui_story_9_7_1_122_dialog_content = "…",
  ui_story_9_7_1_123_dialog_content = "<anim type=Shake>Groar!</anim>",
  ui_story_9_7_1_124_dialog_content = "Sepertinya ia tidak tahu bahwa dirinya sudah berubah menjadi Eclipsite. Tidak ada jalan pulang untukmu, penjaga…",
  ui_story_9_7_1_125_dialog_content = "Mari akhiri penderitaannya!",
  ui_story_9_7_2_1_dialog_content = "<anim type=Shake>Rumah… Pulang… rumah…</anim>",
  ui_story_9_7_2_2_dialog_content = "Demi White Night, semoga kau beristirahat dalam damai.",
  ui_story_9_7_2_3_dialog_content = "Kau tak lagi tersiksa oleh bentuk fisikmu.",
  ui_story_9_7_2_4_dialog_content = "Maaf, kami tak mampu membebaskanmu…",
  ui_story_9_7_2_5_dialog_content = "Kami berusaha sebaik mungkin untuk meminimalkan penderitaannya dalam pertempuran.",
  ui_story_9_7_2_6_dialog_content = "Jangan terlalu menyalahkan dirimu sendiri, PlayerName.",
  ui_story_9_7_2_X6_dialog_content = "Sekarang, yang bisa kita lakukan untuk para Aurorian ini adalah menemukan Forsakin dan menghentikannya.",
  ui_story_9_7_2_7_dialog_content = "Benar.",
  ui_story_9_7_2_8_dialog_content = "Kau benar, kita harus menemukan Forsakin dan menghentikannya agar tak menciptakan lebih banyak Eclipsite!",
  ui_story_9_7_2_9_dialog_content = "Si Forsakin itu siapa sih? Namanya terdengar seperti seorang Aurorian bagiku.",
  ui_story_9_7_2_10_option_content = "Memang.",
  ui_story_9_7_2_11_dialog_content = "Dari perawakan fisik hingga aura dan tingkah laku, Forsakin mirip dengan Aurorian.",
  ui_story_9_7_2_12_dialog_content = "Tapi dia memilih bergabung dengan Eclipsite.",
  ui_story_9_7_2_13_dialog_content = "Dan Vivian bilang, Forsakin pernah melayani Illumina…",
  ui_story_9_7_2_14_option_content = "Bukan.",
  ui_story_9_7_2_15_dialog_content = "Dulu, Forsakin memang seorang Aurorian, tapi sekarang dia ada di pihak Eclipsite.",
  ui_story_9_7_2_16_dialog_content = "Meskipun Vivian bilang dia pernah melayani Illumina…",
  ui_story_9_7_2_17_dialog_content = "Vivian?",
  ui_story_9_7_2_18_dialog_content = "Chief of Staff di Illumina, dia atasanku.",
  ui_story_9_7_2_19_dialog_content = "Sebelum kita pergi, dia mengingatkanku untuk berhati-hati, khususnya dengan Forsakin.",
  ui_story_9_7_2_20_dialog_content = "Dia benar sekali.",
  ui_story_9_7_2_21_dialog_content = "Aku tak paham. Kalau Forsakin benar-benar bekerja untuk Illumina…",
  ui_story_9_7_2_22_dialog_content = "Kenapa dia sama sekali tak punya perasaan?",
  ui_story_9_7_2_23_dialog_content = "Sepertinya dia berobsesi untuk mengubah Aurorian menjadi Eclipsite.",
  ui_story_9_7_2_24_dialog_content = "Aku tak pernah mendengar orang seperti itu saat berada di Illumina…",
  ui_story_9_7_2_25_dialog_content = "Kurasa para petinggi di Illumina pasti tak akan membiarkanmu tahu rahasia sebesar itu.",
  ui_story_9_7_2_26_dialog_content = "Sinsa, aku tahu kau tak memercayai Illumina karena apa yang telah terjadi pada Eve…",
  ui_story_9_7_2_27_dialog_content = "Tetapi para perwira Illumina selalu berada di garis depan pertempuran, memberikan contoh yang baik bagi mereka yang bertempur di bawah mereka…",
  ui_story_9_7_2_X27_dialog_content = "Mungkin selama ini mereka melakukan penyelidikan…",
  ui_story_9_7_2_28_dialog_content = "Heh. Kau orang yang naif karena percaya omong kosong itu.",
  ui_story_9_7_2_29_dialog_content = "Adikku, Eve, menderita komplikasi serius setelah diserang oleh Eclipsite.",
  ui_story_9_7_2_30_dialog_content = "Aku tertipu oleh propaganda mulia Illumina dan dengan bodohnya mengirimkan adikku ke sana untuk dirawat.",
  ui_story_9_7_2_31_dialog_content = "…",
  ui_story_9_7_2_32_dialog_content = "Lalu apa yang terjadi? Mereka bukan hanya gagal mengobatinya, tapi dia bahkan nyaris mati dalam sebuah kebakaran!",
  ui_story_9_7_2_33_dialog_content = "Kebakaran itu…",
  ui_story_9_7_2_34_dialog_content = "!",
  ui_story_9_7_2_35_dialog_content = "Harusnya aku menyadari hubungannya sejak awal… Forsakin punya bekas luka di wajahnya akibat kebakaran.",
  ui_story_9_7_2_36_dialog_content = "Apa kaubilang?!",
  ui_story_9_7_2_37_dialog_content = "Kebakaran di Illumina…",
  ui_story_9_7_2_38_dialog_content = "Aghhh!",
  ui_story_9_7_2_39_dialog_content = "Bekas luka Forsakin…",
  ui_story_9_7_2_40_dialog_content = "Lihat bekas luka di wajahku ini… Ini akibat kulitku dibakar dengan api. Kau bisa lihat, 'kan?",
  ui_story_9_7_2_41_dialog_content = "Jangan-jangan…",
  ui_story_9_7_2_42_dialog_content = "Aku ingin bertanya padamu, Sinsa… Apa yang terjadi kepada orang yang bertanggung jawab merawat Eve?",
  ui_story_9_7_2_43_dialog_content = "Saat aku tiba di Illumina, aku diberi tahu bahwa…",
  ui_story_9_7_2_44_dialog_content = "Orang yang bertanggung jawab atas perawatan eksperimentalnya meninggal dalam kebakaran itu.",
  ui_story_9_7_2_45_dialog_content = "Benarkah?",
  ui_story_9_7_2_46_dialog_content = "Tentu saja aku tidak begitu saja memercayai penjelasan itu.",
  ui_story_9_7_2_47_dialog_content = "Tapi, mereka menolak menyebutkan nama orang itu.",
  ui_story_9_7_2_48_dialog_content = "Jadi aku mengirim orangku sendiri untuk mencari tahu.",
  ui_story_9_7_2_49_dialog_content = "Tapi, tetap saja aku tak bisa mendapatkan informasi baru.",
  ui_story_9_7_2_50_dialog_content = "Tapi, aku tak akan melupakan namanya selama aku masih hidup—<color=#FFB400>Denier</color>.",
  ui_story_9_7_2_X50_dialog_content = "Informasi yang kami peroleh sebelumnya ternyata membuat kami salah jalan. Kami semua mengira si peneliti tewas dalam kebakaran itu.",
  ui_story_9_7_2_51_dialog_content = "Jadi kami tidak mengenali Forsakin saat pertama kali melihatnya!",
  ui_story_9_7_2_52_dialog_content = "Benar… Tapi, kalau kupikir-pikir lagi, aku curiga jangan-jangan Forsakin adalah Denier.",
  ui_story_9_7_2_53_dialog_content = "!",
  ui_story_9_7_2_54_dialog_content = "Aghhh!",
  ui_story_9_7_2_55_dialog_content = "Eve…",
  ui_story_9_7_2_56_dialog_content = "Sial, akan kupaksa si Forsakin itu mengungkapkan kebenarannya!",
  ui_story_9_7_2_57_dialog_content = "Kalau benar dulu dia menyakiti Eve, akan kupastikan dia menerima ganjarannya!",
  ui_story_9_8_1_1_dialog_content = "<color=#e8d9bb>Di dalam Healing Pod Aviduz</color>",
  ui_story_9_8_1_2_dialog_content = "Profesor…",
  ui_story_9_8_1_3_dialog_content = "Permisi… Profesor… Lagi…",
  ui_story_9_8_1_4_dialog_content = "Kenapa…",
  ui_story_9_8_1_5_dialog_content = "<color=#e8d9bb>Hangar Instruksional Colossus di Eraveil</color>",
  ui_story_9_8_1_6_dialog_content = "Maaf, Profesor Handro, boleh aku mencobanya lagi?",
  ui_story_9_8_1_7_dialog_content = "Kau sudah menggunakan tiga kesempatanmu, Schummer.",
  ui_story_9_8_1_8_dialog_content = "Maafkan aku, tapi kamu tidak lolos ujian untuk mengemudikan Colossus.",
  ui_story_9_8_1_9_dialog_content = "Tapi, kalau tidak lolos, aku tidak akan bisa mendaftar seleksi untuk Navigator Aviduz!",
  ui_story_9_8_1_10_dialog_content = "Aku harus lolos ujian ini!",
  ui_story_9_8_1_11_dialog_content = "Aku paham perasaanmu, Schummer.",
  ui_story_9_8_1_12_dialog_content = "Kau salah satu muridku yang paling berbakat dan aku sangat ingin kau masuk seleksi itu.",
  ui_story_9_8_1_13_dialog_content = "Entah alam tes atau seleksi, semuanya harus adil.",
  ui_story_9_8_1_14_dialog_content = "Aku siap mengikuti ujiannya, Profesor Handro! Bisa mulai sekarang?",
  ui_story_9_8_1_15_dialog_content = "Baiklah, aku akan segera ke sana.",
  ui_story_9_8_1_16_dialog_content = "Aku sangat senang melihat kerja kerasmu, Schummer.",
  ui_story_9_8_1_17_dialog_content = "Aku yakin jika kau terus berlatih, kemampuan psikismu akan meningkat dengan pesat!",
  ui_story_9_8_1_18_dialog_content = "Dan aku yakin kau akan terpilih untuk mengemudikan Aviduz di kesempatan berikutnya!",
  ui_story_9_8_1_19_dialog_content = "Tapi, kapankah itu…?",
  ui_story_9_8_1_20_dialog_content = "…",
  ui_story_9_8_1_21_dialog_content = "Kamu tak akan mengalami hari itu. Seleksi terakhir saja sudah beberapa dekade yang lalu!",
  ui_story_9_8_1_X1_dialog_content = "(Tutup mulutmu, Nona… Sekarang kau baru ingat bahwa kau punya anak perempuan? Hanya karena aku akan ikut seleksi?)",
  ui_story_9_8_1_X2_dialog_content = "Schummer, meskipun kamu mendapatkan nilai tertinggi dalam ujian terakhir…",
  ui_story_9_8_1_X3_dialog_content = "Jangan sampai fokusmu teralihkan sekarang. Bertelepati dengan Colossus berbeda dengan ujian lainnya. Kau harus berusaha sebaik mungkin.",
  ui_story_9_8_1_X4_dialog_content = "(Aku tahu… Tak perlu mengingatkanku.)",
  ui_story_9_8_1_22_dialog_content = "Bukankah kau selalu bisa menjadi yang terbaik dalam setiap ujian yang kauikuti, Schummer?",
  ui_story_9_8_1_23_dialog_content = "Bagaimana mungkin kau tak bisa mengerjakan hal sesederhana menjalankan Colossus?",
  ui_story_9_8_1_X5_dialog_content = "(Aku bisa melakukannya. Lihat saja.)",
  ui_story_9_8_1_X6_dialog_content = "Dia bahkan tidak bisa bertelepati dengan Colossus! Kau ini benar-benar Caelestite bukan sih, Schummer?",
  ui_story_9_8_1_X7_dialog_content = "(Diam! Kaupikir kau ini hebat hanya karena bisa bertelepati sedikit.)",
  ui_story_9_8_1_24_dialog_content = "Schummer gagal dalam ujian pilot? Tidak mungkin…",
  ui_story_9_8_1_X8_dialog_content = "(Itu cuma ujian. Lain kali…)",
  ui_story_9_8_1_X9_dialog_content = "Handro bilang kau cocok menjadi Navigator untuk Aviduz?",
  ui_story_9_8_1_X10_dialog_content = "Sebaiknya kau menyerah saja.",
  ui_story_9_8_1_X11_dialog_content = "Kau tak punya bakat atau kualifikasi untuk itu…",
  ui_story_9_8_1_X12_dialog_content = "(Tutup mulutmu! Kalian semua idiot! Kalian tak tahu apa-apa!)",
  ui_story_9_8_1_X13_dialog_content = "(Suatu hari nanti, akan kutunjukkan kepada kalian semua!)",
  ui_story_9_8_1_X14_dialog_content = "…",
  ui_story_9_8_1_25_dialog_content = "Dia bahkan tidak bisa bertelepati dengan Colossus! Kau ini benar-benar Caelestite bukan sih, Schummer?",
  ui_story_9_8_1_26_dialog_content = "Apa-apaan kau…!",
  ui_story_9_8_1_27_dialog_content = "Lihat, itu Mendelson si Pengecut!",
  ui_story_9_8_1_28_dialog_content = "Apa yang kaupikirkan? Coba beri tahu kami.",
  ui_story_9_8_1_29_dialog_content = "Hentikan, sudah cukup…",
  ui_story_9_8_1_30_dialog_content = "Berani-beraninya menyuruh kami, memangnya kaukira kau ini siapa?",
  ui_story_9_8_1_31_dialog_content = "Profesor Handro…",
  ui_story_9_8_1_32_dialog_content = "Oh? Profesor kenapa?",
  ui_story_9_8_1_33_dialog_content = "Aku… akan…",
  ui_story_9_8_1_34_dialog_content = "Kau mau melapor kepada profesor Handro? Kau hanya bisa menjilat.",
  ui_story_9_8_1_35_dialog_content = "Baiklah, diamlah.",
  ui_story_9_8_1_36_dialog_content = "Baiklah. Ayo kita pergi!",
  ui_story_9_8_1_X15_dialog_content = "K-kau menindasnya lagi…? A-akan kuberi tahu Profesor Handro!",
  ui_story_9_8_1_37_dialog_content = "Kau baik-baik saja?",
  ui_story_9_8_1_38_dialog_content = "Siapa kau? Apa aku terlihat butuh bantuanmu!? Urus saja urusanmu sendiri!",
  ui_story_9_8_1_39_dialog_content = "A-aku Mendelson… A-aku lihat mereka menindasmu…",
  ui_story_9_8_1_X16_dialog_content = "Aku hanya berpikir… kau butuh bantuan…",
  ui_story_9_8_1_X17_dialog_content = "Jadi kaukira karena kau melihat mereka menindasku, kau mau menggunakan kesempatan itu untuk menggangguku?",
  ui_story_9_8_1_40_dialog_content = "Kau hanya mencoba untuk memanipulasiku. Kaupikir ini dengan begini kau merasa dirimu lebih baik?",
  ui_story_9_8_1_X18_dialog_content = "Bukankah kau sama saja dengan mereka?",
  ui_story_9_8_1_X19_dialog_content = "Saat suasana hatimu bagus, kau datang dan pura-pura peduli. Lalu, saat suasana hatimu buruk, kau datang dan tertawa?",
  ui_story_9_8_1_41_dialog_content = "Tidak sama sekali…",
  ui_story_9_8_1_X20_dialog_content = "Kalau begitu, kenapa?",
  ui_story_9_8_1_42_dialog_content = "Kenapa kau mau membantuku?",
  ui_story_9_8_1_43_dialog_content = "Aku… aku tahu mereka salah…",
  ui_story_9_8_1_44_dialog_content = "(Tentu saja mereka salah…)",
  ui_story_9_8_1_45_dialog_content = "(Mereka pikir mereka hebat…)",
  ui_story_9_8_1_46_dialog_content = "Sedang apa kau sendirian di sini, Schummer?",
  ui_story_9_8_1_47_dialog_content = "!",
  ui_story_9_8_1_48_dialog_content = "Itu Schummer yang tidak bisa mengemudikan Colossus!",
  ui_story_9_8_1_49_dialog_content = "Kau mencoba bertelepati dengan Colossus? Rajin sekali!",
  ui_story_9_8_1_50_dialog_content = "Ayolah, jangan ganggu dia…",
  ui_story_9_8_1_51_dialog_content = "Tunggu sebentar, aku punya ide.",
  ui_story_9_8_1_52_dialog_content = "Bagaimana kalau kita bertaruh?",
  ui_story_9_8_1_53_dialog_content = "Bertaruh apa?",
  ui_story_9_8_1_54_dialog_content = "Schummer, apakah kau berani keluar dari Eraveil bersama kami?",
  ui_story_9_8_1_X21_dialog_content = "Hah? Bukannya itu memang rencana kita kemarin…",
  ui_story_9_8_1_X22_dialog_content = "Haha! Lihat Schummer, dia bahkan tak berani mengangkat kepalanya. Mungkin dia takut padamu…",
  ui_story_9_8_1_55_dialog_content = "Katakan dulu kepadaku bahwa kau berani.",
  ui_story_9_8_1_56_dialog_content = "Ayo!",
  ui_story_9_8_1_57_dialog_content = "Mungkin kau bisa bertelepati dengan Colossus, tapi apakah kau berani membawanya keluar Eraveil?",
  ui_story_9_8_1_58_dialog_content = "Seperti yang kubilang waktu itu… Profesor Handro bilang di luar sana berbahaya karena ada Eclipsite.",
  ui_story_9_8_1_59_dialog_content = "Jadi, kau takut?",
  ui_story_9_8_1_60_dialog_content = "Apa yang kautakutkan? Ayo kita keluar dengan Colossus!",
  ui_story_9_8_1_61_dialog_content = "Kalau bisa pergi-pulang dengan Colossus, kau dianggap menang.",
  ui_story_9_8_1_62_dialog_content = "Kalau kami menang, kau tahu sendiri akibatnya!",
  ui_story_9_8_1_63_dialog_content = "Ayo ambil Learner I!",
  ui_story_9_8_1_64_dialog_content = "Kau yakin aku tak akan tertangkap?",
  ui_story_9_8_1_65_dialog_content = "Jangan khawatir, Profesor Handro menganggapmu calon Navigator berikutnya untuk Aviduz!",
  ui_story_9_8_1_66_dialog_content = "!",
  ui_story_9_8_1_67_dialog_content = "Benar, kami yakin akan kemampuanmu!",
  ui_story_9_8_1_68_dialog_content = "Meskipun tertangkap, tak akan ada yang menyalahkanmu!",
  ui_story_9_8_1_69_dialog_content = "Baiklah… Tapi sekali ini saja, ya.",
  ui_story_9_8_1_70_dialog_content = "Baiklah, kita lepas landas!",
  ui_story_9_8_1_X23_dialog_content = "Schummer, kau ikut tidak?",
  ui_story_9_8_1_X24_dialog_content = "Aku yakin dia tak akan ikut! Aku bertaruh tiga buku!",
  ui_story_9_8_1_71_dialog_content = "(Aviduz… adalah milikku…)",
  ui_story_9_8_1_72_dialog_content = "(Kalian tak tahu apa-apa… Jadi…)",
  ui_story_9_8_1_73_dialog_content = "<color=#e8d9bb>Di Luar Eraveil</color>",
  ui_story_9_8_1_74_dialog_content = "Colossus-nya tidak mau bergerak!",
  ui_story_9_8_1_75_dialog_content = "…",
  ui_story_9_8_1_76_dialog_content = "Para Eclipsite itu mendobrak pintunya!",
  ui_story_9_8_1_77_dialog_content = "Kita harus bagaimana?",
  ui_story_9_8_1_78_dialog_content = "Ckck!",
  ui_story_9_8_1_79_dialog_content = "Aku tak percaya mangsa-mangsa ini datang sendiri kepadaku!",
  ui_story_9_8_1_X25_dialog_content = "(Lebih baik kalian mati saja.)",
  ui_story_9_8_1_80_dialog_content = "Kita harus melawan!",
  ui_story_9_8_1_81_dialog_content = "Agh!",
  ui_story_9_8_1_82_dialog_content = "Bocah sialan. Aku bisa saja mengatasimu dengan mudah.",
  ui_story_9_8_1_83_dialog_content = "Err…",
  ui_story_9_8_1_84_dialog_content = "Oh…",
  ui_story_9_8_1_85_dialog_content = "Itu saja?",
  ui_story_9_8_1_86_dialog_content = "Itu hanya ujian kecil. Aku sebal saat mereka mati tanpa izin.",
  ui_story_9_8_1_87_dialog_content = "…",
  ui_story_9_8_1_88_dialog_content = "Itu saja kemampuanmu? Kalau kukencangkan cengkeramanku, tulangmu bisa hancur.",
  ui_story_9_8_1_89_dialog_content = "Akan kujadikan tulangmu sebagai trofi dan mengenakannya sebagai kalung!",
  ui_story_9_8_1_90_dialog_content = "…",
  ui_story_9_8_1_91_dialog_content = "(Kabur… Bagaimana… aku bisa kabur…?)",
  ui_story_9_8_1_X91_dialog_content = "Aduh…",
  ui_story_9_8_1_92_dialog_content = "Hah? Maksudmu ada makhluk kecil yang bersembunyi di dalam reruntuhan?",
  ui_story_9_8_1_X92_dialog_content = "Ck, ck, ck… Menarik sekali.",
  ui_story_9_8_1_X26_dialog_content = "(…!)",
  ui_story_9_8_1_S1_dialog_content = "Jangan bergerak!",
  ui_story_9_8_1_X27_dialog_content = "Tenanglah… Aku punya kabar baik untukmu.",
  ui_story_9_8_1_X28_dialog_content = "Kau mau dengar?",
  ui_story_9_8_1_X29_dialog_content = "… Kau bisa bicara bahasa Universese?",
  ui_story_9_8_1_S2_dialog_content = "Ck! Kau masih saja memikirkan hal seperti itu sekarang!? Kau tak takut aku akan membunuhmu?",
  ui_story_9_8_1_S3_dialog_content = "… Takut.",
  ui_story_9_8_1_X30_dialog_content = "Ck, ck, ck! Dengarkan baik-baik kalau begitu.",
  ui_story_9_8_1_93_dialog_content = "Sang Bunda Agung telah menetapkan bahwa Caelestite akan dimusnahkan seluruhnya pada hari Penghakiman.",
  ui_story_9_8_1_94_dialog_content = "Itu adalah penghakiman terakhir untuk Caelestite, dan akhir bahagia yang diberikan oleh sang Bunda!",
  ui_story_9_8_1_95_dialog_content = "Oleh karena itu, kau patut bersyukur bisa menyaksikan momen bersejarah itu!",
  ui_story_9_8_1_96_dialog_content = "… A-apa!?",
  ui_story_9_8_1_97_dialog_content = "Kau tak berhak bertanya!",
  ui_story_9_8_1_98_dialog_content = "Orang yang lemah hanya pantas mati!",
  ui_story_9_8_1_99_dialog_content = "Sama seperti teman-teman kecilmu, berkerut menjadi bola-bola kecil dan tewas dalam kesakitan.",
  ui_story_9_8_1_100_dialog_content = "…!",
  ui_story_9_8_1_101_dialog_content = "Ck, ck… Jangan khawatir. Aku memutuskan untuk memilihmu. Aku memutuskan untuk memberimu kesempatan.",
  ui_story_9_8_1_102_dialog_content = "Aku akan memberimu kekuatan untuk melawan Caelestites! Aku akan memberimu kesempatan untuk melupakan keberadaanmu yang menyedihkan itu!",
  ui_story_9_8_1_103_dialog_content = "Melupakan…",
  ui_story_9_8_1_104_dialog_content = "Bukankah kau selalu bisa menjadi yang terbaik dalam setiap ujian yang kauikuti, Schummer?",
  ui_story_9_8_1_105_dialog_content = "Bagaimana mungkin kau tak bisa mengerjakan hal sesederhana menjalankan Colossus?",
  ui_story_9_8_1_106_dialog_content = "Schummer gagal dalam ujian pilot? Tidak mungkin…",
  ui_story_9_8_1_107_dialog_content = "Dia bahkan tidak bisa bertelepati dengan Colossus! Kau ini benar-benar Caelestite bukan sih, Schummer?",
  ui_story_9_8_1_108_dialog_content = "Kau yakin aku tak akan tertangkap?",
  ui_story_9_8_1_109_dialog_content = "Jangan khawatir, Profesor Handro menganggapmu calon Navigator berikutnya untuk Aviduz!",
  ui_story_9_8_1_110_dialog_content = "Lihat Seed ini? Ini adalah harapanmu.",
  ui_story_9_8_1_111_dialog_content = "Harapanku…",
  ui_story_9_8_1_112_dialog_content = "Bagus. Aku bisa merasakan hasratmu akan kekuatan.",
  ui_story_9_8_1_113_dialog_content = "Kekuatan…",
  ui_story_9_8_1_114_dialog_content = "Apa yang kaulakukan, Schummer…?",
  ui_story_9_8_1_115_dialog_content = "Ya, kau hanya bisa hidup dengan menjadi anak dari sang Bunda!",
  ui_story_9_8_1_116_dialog_content = "Aku harus hidup…",
  ui_story_9_8_1_117_dialog_content = "Kau tak akan jadi lemah atau takut lagi!",
  ui_story_9_8_1_118_dialog_content = "Terimalah karunia ini, jadilah lebih kuat… dan bergabunglah bersama kami!",
  ui_story_9_8_1_119_dialog_content = "Kau akan menguasai dunia… menguasai segalanya!",
  ui_story_9_8_1_120_dialog_content = "Menguasai… segalanya…",
  ui_story_9_8_1_121_dialog_content = "Jangan, Schummer…",
  ui_story_9_8_1_122_dialog_content = "Benar. Kemarilah.",
  ui_story_9_8_1_123_dialog_content = "Tidak… Kumohon…",
  ui_story_9_8_1_124_dialog_content = "…",
  ui_story_9_8_1_125_dialog_content = "Ada apa?",
  ui_story_9_8_1_126_dialog_content = "Aku…",
  ui_story_9_8_1_127_dialog_content = "Ambil pisaunya!",
  ui_story_9_8_1_128_dialog_content = "Aku…",
  ui_story_9_8_1_129_dialog_content = "Jangan ragu! Jangan menguji kesabaranku! Tunggu apa lagi!?",
  ui_story_9_8_1_130_dialog_content = "Aku akan berubah menjadi Eclipsite… Iya 'kan?",
  ui_story_9_8_1_131_dialog_content = "Lupakan saja.",
  ui_story_9_8_1_132_dialog_content = "Agh!",
  ui_story_9_8_1_133_dialog_content = "Kau…!",
  ui_story_9_8_1_134_dialog_content = "Kau membencinya, 'kan?",
  ui_story_9_8_1_135_dialog_content = "…",
  ui_story_9_8_1_136_dialog_content = "Bukankah kau harusnya berterima kasih padaku karena sudah membunuhnya?",
  ui_story_9_8_1_137_dialog_content = "Apa kau akan membunuhku juga?",
  ui_story_9_8_1_138_dialog_content = "Kenapa aku harus membunuhmu?",
  ui_story_9_8_1_139_dialog_content = "Aku tahu kau berbeda dengan mereka. Kau punya potensi untuk menjadi orang yang hebat.",
  ui_story_9_8_1_140_dialog_content = "Tentu saja. Jika menjadi Eclipsite, kau akan memperoleh kekuatan untuk mengalahkan Caelestite, dan bahkan Aurorian!",
  ui_story_9_8_1_141_dialog_content = "Tapi… Kekuatan macam apa itu?",
  ui_story_9_8_1_142_dialog_content = "Sebuah berkah dari sang Bunda yang memelihara dunia, karunia paling berharga yang bisa diterima siapa pun.",
  ui_story_9_8_1_143_dialog_content = "Kau akan terus hidup tanpa rasa takut.",
  ui_story_9_8_1_144_dialog_content = "Maksudmu… Aku hanya bisa hidup jika menerimanya…?",
  ui_story_9_8_1_145_dialog_content = "Tentu saja. Kau bahkan bisa hidup lebih lama dari lembah ini.",
  ui_story_9_8_1_146_dialog_content = "Dan aku tak akan jadi lemah lagi?",
  ui_story_9_8_1_147_dialog_content = "Tentu saja. Setelah itu, hanya kata \"tak terkalahkan\" sajalah yang pantas untuk menggambarkan dirimu.",
  ui_story_9_8_1_S147_dialog_content = "Dengan menerimanya… aku akan memenuhi syarat untuk memiliki Aviduz?",
  ui_story_9_8_1_S148_dialog_content = "Aviduz? Apakah itu Colossus?",
  ui_story_9_8_1_S149_dialog_content = "Ck, ck, ck… Katakan padaku, Colossus seperti apa yang kau inginkan?",
  ui_story_9_8_1_S150_dialog_content = "Aviduz… adalah Colossus paling kuat. Hanya Caelestite terkuat… yang berhak mengendalikannya.",
  ui_story_9_8_1_S151_dialog_content = "Ck, ck, ck! Berarti, kau akan lebih berhak untuk mengendalikannya daripada Caelestite lainnya! Dan kau akan mengungguli mereka semua!",
  ui_story_9_8_1_148_dialog_content = "…",
  ui_story_9_8_1_149_dialog_content = "Aku…",
  ui_story_9_8_1_150_dialog_content = "Menerimanya.",
  ui_story_9_8_1_151_dialog_content = "Ckck!",
  ui_story_9_8_1_152_dialog_content = "Oh…!",
  ui_story_9_8_1_153_dialog_content = "Kau mendapatkan hamba lagi, wahai Bunda Agung!",
  ui_story_9_8_1_154_dialog_content = "Kau sudah memberiku kekuatan?",
  ui_story_9_8_1_155_dialog_content = "Aku tak merasakan perbedaan apa pun…",
  ui_story_9_8_1_156_dialog_content = "Schummer… Itu namamu, 'kan?",
  ui_story_9_8_1_157_dialog_content = "Ingat ini, Schummer. Jangan pernah meragukan sang Bunda. Kau harus belajar untuk bersabar.",
  ui_story_9_8_1_158_dialog_content = "…",
  ui_story_9_8_1_159_dialog_content = "Kau mau membawaku ke mana?",
  ui_story_9_8_1_160_dialog_content = "Kita tak ke mana-mana, Schummer. Aku ingin kau kembali ke Eraveil. Tentu saja, bersamaku.",
  ui_story_9_8_1_161_dialog_content = "Kembali ke Eraveil?",
  ui_story_9_8_1_162_dialog_content = "Apa kau lupa, Aviduz masih menunggumu di sana?",
  ui_story_9_8_1_163_dialog_content = "Kau baru akan jadi utuh dan tak terkalahkan saat sudah bertemu Aviduz!",
  ui_story_9_8_1_164_dialog_content = "Bukannya lupa. Aku hanya tak seperti yang lainnya.",
  ui_story_9_8_1_165_dialog_content = "Aku… tak bisa bertelepati dengan Colossus mana pun. Kukira aku bisa menunggu sampai semua ini selesai.",
  ui_story_9_8_1_166_dialog_content = "Apa, Caelestite yang tidak bisa bertelepati dengan Colossus?",
  ui_story_9_8_1_167_dialog_content = "Diam! Aku tak mau mendengarnya!",
  ui_story_9_8_1_168_dialog_content = "Lupakan, Seed sudah menguasaimu.",
  ui_story_9_8_1_169_dialog_content = "Mulai sekarang kau bukan Caelestite lagi.",
  ui_story_9_8_1_170_dialog_content = "Kau bisa coba menyalakan Colossus-nya sekarang.",
  ui_story_9_8_1_171_dialog_content = "… Baiklah.",
  ui_story_9_8_1_172_dialog_content = "Tidak mungkin..!",
  ui_story_9_8_1_173_dialog_content = "Aku tidak kalah… Aku tidak kalah…!",
  ui_story_9_8_1_174_dialog_content = "Schummer!",
  ui_story_9_8_1_175_dialog_content = "Sebelum mati, lihat mataku!!!",
  ui_story_9_8_1_176_dialog_content = "Tidak, tidak…",
  ui_story_9_8_1_177_dialog_content = "Tidak!",
  ui_story_9_9_1_1_dialog_content = "Semuanya, perhatikan kaki kalian!",
  ui_story_9_9_1_2_dialog_content = "Ada apa?",
  ui_story_9_9_1_3_dialog_content = "<color=#e8d9bb>Meratap—meratap—meratap—</color>",
  ui_story_9_9_1_4_dialog_content = "Aku mendengar banyak suara…",
  ui_story_9_9_1_5_dialog_content = "Maksudmu, seperti tanah yang berguncang?",
  ui_story_9_9_1_6_dialog_content = "Bukan… itu Aviduz, menangis dan meratap…",
  ui_story_9_9_1_7_dialog_content = "<color=#e8d9bb>Meratap—meratap—meratap—</color>",
  ui_story_9_9_1_8_dialog_content = "(Itu… suara ratapan Colossus… Sepertinya Colossus yang dulu dikubur di sini ikut meratap…)",
  ui_story_9_9_1_9_dialog_content = "<color=#e8d9bb><anim type=Shake>Meratap—meratap—meratap—</anim></color>",
  ui_story_9_9_1_10_dialog_content = "(Rasanya seperti pisau yang menyayat hatiku…)",
  ui_story_9_9_1_11_dialog_content = "(Aku merasakan cairan panas mengalir…)",
  ui_story_9_9_1_12_dialog_content = "Air mata?",
  ui_story_9_9_1_13_dialog_content = "PlayerName…",
  ui_story_9_9_1_14_dialog_content = "PlayerName… Kau menangis?",
  ui_story_9_9_1_15_dialog_content = "PlayerName…",
  ui_story_9_9_1_16_dialog_content = "Tidak apa-apa… Aku hanya… teringat pada Soroz.",
  ui_story_9_9_1_X16_dialog_content = "PlayerName…",
  ui_story_9_9_1_17_dialog_content = "Vice.",
  ui_story_9_9_1_18_dialog_content = "Kau merasakan sesuatu? Kalau kau butuh bantuan, kami siap!",
  ui_story_9_9_1_19_dialog_content = "Kalau tak keberatan, ambillah ini.",
  ui_story_9_9_1_20_dialog_content = "Hmm…?",
  ui_story_9_9_1_21_dialog_content = "Sapu tangan untuk menyeka air matamu, PlayerName.",
  ui_story_9_9_1_22_dialog_content = "Maaf, aku benar-benar tak tahu kenapa…",
  ui_story_9_9_1_23_dialog_content = "Kau tak perlu minta maaf, PlayerName.",
  ui_story_9_9_1_24_dialog_content = "Air mata bukan hanya untuk orang lemah. Kita semua kadang memang perlu meluapkan perasaan.",
  ui_story_9_9_1_25_dialog_content = "Baiklah.",
  ui_story_9_9_1_26_dialog_content = "Apa yang kaurasakan, Nak?",
  ui_story_9_9_1_27_dialog_content = "Aku mendengar ratapan para Colossus, bersahut-sahutan.",
  ui_story_9_9_1_28_dialog_content = "Kedengarannya seperti duka, atau seseorang yang berkabung atas meninggalnya orang yang dicintai…",
  ui_story_9_9_1_29_dialog_content = "Aku merasakan penderitaan mereka… seolah-olah itu penderitaanku sendiri.",
  ui_story_9_9_1_30_dialog_content = "Apa ada Colossus lain di dekat sini?",
  ui_story_9_9_1_31_dialog_content = "Sepertinya tidak. Suara yang aku dengar itu tidak nyata…",
  ui_story_9_9_1_32_dialog_content = "Yang kudengar adalah sisa pikiran mereka.",
  ui_story_9_9_1_33_dialog_content = "Tapi, kenapa sekarang?",
  ui_story_9_9_1_34_dialog_content = "…",
  ui_story_9_9_1_35_dialog_content = "Kau masih bisa merasakan Aviduz, PlayerName?",
  ui_story_9_9_1_36_dialog_content = "Darkflow-nya makin tebal di Eraveil.",
  ui_story_9_9_1_37_dialog_content = "Aku hampir tidak bisa merasakan keberadaan Aviduz yang melemah.",
  ui_story_9_9_1_38_dialog_content = "Tapi sekarang aku tak bisa merasakan apa pun.",
  ui_story_9_9_1_39_dialog_content = "Aku iri dengan kekuatanmu yang bisa merasakan keberadaan Colossus, PlayerName.",
  ui_story_9_9_1_40_dialog_content = "Itu bakat bawaan Caelestite, sama sepertimu yang bisa menggunakan Lumina untuk bertempur.",
  ui_story_9_9_1_41_dialog_content = "Sebenarnya, aku penasaran…",
  ui_story_9_9_1_42_dialog_content = "Seperti apa rasanya bertelepati dengan Colossus?",
  ui_story_9_9_1_43_dialog_content = "Seperti apa rasanya?",
  ui_story_9_9_1_44_dialog_content = "Aku tak tahu bagaimana harus menjawabnya.",
  ui_story_9_9_1_45_dialog_content = "(Aku sudah terbiasa ditemani Soroz selama 17 tahun.)",
  ui_story_9_9_1_46_dialog_content = "(Tapi, bagaimana seandainya aku tak bisa bertelepati dengan Soroz lagi…)",
  ui_story_9_9_1_47_dialog_content = "Tidak apa-apa kalau kau tak ingin membicarakannya, PlayerName.",
  ui_story_9_9_1_48_dialog_content = "Aku baik-baik saja, bukan masalah nyaman atau tidak.",
  ui_story_9_9_1_49_dialog_content = "Tapi, aku baru sadar, aku tak pernah memikirkan ini.",
  ui_story_9_9_1_50_dialog_content = "Sepertinya aku merasa aman dan hangat saat bertelepati dengan Colossus.",
  ui_story_9_9_1_51_dialog_content = "Ia seperti orang kepercayaan yang tahu isi pikiranmu.",
  ui_story_9_9_1_52_dialog_content = "Dan hanya dirimulah yang bisa memahaminya.",
  ui_story_9_9_1_53_dialog_content = "Memang, omelannya kadang-kadang menjengkelkan.",
  ui_story_9_9_1_54_dialog_content = "Tapi saat semua itu hilang, kau akan merindukannya.",
  ui_story_9_9_1_55_dialog_content = "Menurutku, bertelepati dengan Colossus membuatku merasa bahagia.",
  ui_story_9_9_1_56_dialog_content = "Perasaan bahagia…",
  ui_story_9_9_1_57_dialog_content = "Aku ingin tahu juga pendapat Lepidoz.",
  ui_story_9_9_1_58_dialog_content = "Apakah Lepidoz yang kaumaksud itu juga Colossus?",
  ui_story_9_9_1_59_dialog_content = "Lepidoz adalah kebanggaan Rediesel Wrench!",
  ui_story_9_9_1_60_dialog_content = "Kami menemukan lambung kapal yang setengah terkubur di Rediesel Desert.",
  ui_story_9_9_1_61_dialog_content = "Lalu kami menggalinya dan menyadari bahwa itu adalah Colossus yang sudah bobrok.",
  ui_story_9_9_1_62_dialog_content = "Teknisi kami butuh waktu lama untuk menyatukannya kembali.",
  ui_story_9_9_1_63_dialog_content = "Lepidoz hanya mau dikemudikan oleh Bopper, sih.",
  ui_story_9_9_1_64_dialog_content = "Dia sama sekali tak mau disentuh orang lain.",
  ui_story_9_9_1_65_dialog_content = "Butuh waktu lama bagiku untuk belajar mengemudikan Lepidoz.",
  ui_story_9_9_1_66_dialog_content = "Kau bisa mengemudikannya tanpa bertelepati?",
  ui_story_9_9_1_67_dialog_content = "Ya, aku pun bingung kenapa bisa seperti itu.",
  ui_story_9_9_1_68_dialog_content = "Terkadang aku merasakan apa yang dirasakan Lepidoz.",
  ui_story_9_9_1_69_dialog_content = "Saat pertama kali menemukannya, mungkin dia merasa kesepian dan tersesat.",
  ui_story_9_9_1_70_dialog_content = "Meskipun aku tak tahu apa yang dipikirkannya, aku tetap bicara dengannya setiap hari.",
  ui_story_9_9_1_71_dialog_content = "Sekarang, dia mencintai kehidupannya sebagai anggota Rediesel Wrench!",
  ui_story_9_9_1_72_dialog_content = "Bertelepati atau tidak, itu tidak penting bagi Bopper.",
  ui_story_9_9_1_73_dialog_content = "Kemampuan mengemudinya sekarang sudah cukup bagus!",
  ui_story_9_9_1_74_dialog_content = "Aku tak pernah menyangka begundal gurun ternyata punya Colossus sendiri.",
  ui_story_9_9_1_75_dialog_content = "Di dunia nyata, ada banyak hal yang tak terduga, tuan putri.",
  ui_story_9_9_1_76_dialog_content = "Sesekali, kau memang perlu melihat-lihat ke luar istana.",
  ui_story_9_9_1_77_dialog_content = "…",
  ui_story_9_9_1_78_dialog_content = "Awas, di belakangmu!",
  ui_story_9_9_1_79_dialog_content = "Mungkinkah itu… Eclipsite lain yang dulunya Aurorian?",
  ui_story_9_9_1_80_dialog_content = "Sebanyak ini…? Mereka terlalu banyak…",
  ui_story_9_9_1_81_dialog_content = "Jelas, semua penjaga Lumopolis yang datang ke sini untuk menyelidiki pasti ditangkap dan digunakan sebagai subjek tes.",
  ui_story_9_9_1_82_dialog_content = "!",
  ui_story_9_9_1_83_dialog_content = "PlayerName, berikan perintahmu! Ayo habisi mereka secepatnya, sebelum mereka merasakan sakit.",
  ui_story_9_13_1_1_dialog_content = "Demi White Night, semoga kalian beristirahat dalam damai.",
  ui_story_9_13_1_2_dialog_content = "Istirahatlah dalam damai…",
  ui_story_9_13_1_3_dialog_content = "Berapa jauh lagi, PlayerName?",
  ui_story_9_13_1_4_dialog_content = "Tandanya lemah, tapi Aviduz mestinya ada di sekitar sini.",
  ui_story_9_13_1_X4_dialog_content = "Ke arah mana? Kiri? Kanan? Depan?",
  ui_story_9_13_1_5_dialog_content = "Aahhhhhh!",
  ui_story_9_13_1_6_dialog_content = "Ada segerombolan besar Eclipsite menyerang dari depan kita!",
  ui_story_9_13_1_7_dialog_content = "PlayerName, beri tahukan arah tujuan kita, akan kubukakan jalan!",
  ui_story_9_13_2_1_dialog_content = "Aku melihatnya di leher Eclipsite yang mati di sebelah sana itu.",
  ui_story_9_13_2_2_dialog_content = "Kotor sekali Eclipsite ini! Aku tak tahu harus mulai dari mana.",
  ui_story_9_13_2_3_dialog_content = "Bisa tolong bantu Pact, Nails?",
  ui_story_9_13_2_4_dialog_content = "…",
  ui_story_9_13_2_5_dialog_content = "Maafkan aku, Lord of The Truth yang agung.",
  ui_story_9_13_2_6_dialog_content = "Doktrinnya melarang kami menyentuh apa pun yang kotor.",
  ui_story_9_13_2_7_dialog_content = "Tapi untuk mencari jejakmu, aku harus melihat yang seharusnya tak kulihat, menyentuh yang seharusnya tak kusentuh.",
  ui_story_9_13_2_8_dialog_content = "Aku akan mandi selama 3 hari untuk menyucikan diri setelah kembali nanti.",
  ui_story_9_13_2_9_dialog_content = "…",
  ui_story_9_13_2_10_dialog_content = "Tolong berikan itu kepada White Suitcase.",
  ui_story_9_13_2_11_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_9_13_2_12_dialog_content = "Untuk apa aku memberikan Seed sebagai makanan White Suitcase?",
  ui_story_9_13_2_X12_dialog_content = "White Suitcase sepertinya menyukai benda-benda seperti itu… Apa yang harus kita lakukan kalau dia tak mau memuntahkannya?",
  ui_story_9_13_2_X13_dialog_content = "Karena Nails tertarik, biar dia saja yang menyimpannya.",
  ui_story_9_13_2_X14_dialog_content = "…",
  ui_story_9_13_2_13_dialog_content = "Maafkan aku, Lady Victoria. Seharusnya aku menenangkan diri…",
  ui_story_9_13_2_14_dialog_content = "Pact, jangan meremehkan Seed.",
  ui_story_9_13_2_X15_dialog_content = "Meskipun kecil, Darkflow yang ada dalam Seed bisa berpengaruh besar terhadap kondisi psikis Aurorian biasa.",
  ui_story_9_13_2_X16_dialog_content = "Tubuh kita mengandung Lumina yang kuat, tapi kita hanya bisa menahan efeknya sementara waktu.",
  ui_story_9_13_2_X17_dialog_content = "Kita tak bisa menyentuhnya terlalu lama.",
  ui_story_9_13_2_15_dialog_content = "Dan kita punya aturan lain yang tidak bisa diabaikan. Aku benar-benar tidak boleh meremehkannya…",
  ui_story_9_14_1_1_dialog_content = "Di depan sana.",
  ui_story_9_14_1_2_dialog_content = "Hati-hati!",
  ui_story_9_14_1_3_dialog_content = "Apakah itu Aviduz?",
  ui_story_9_14_1_4_dialog_content = "Kelihatannya seram… Lepidoz lebih menggemaskan.",
  ui_story_9_14_1_5_dialog_content = "Ledakan Lumina cannon, ditambah dengan benturan akibat tabrakan itu…",
  ui_story_9_14_1_6_dialog_content = "Kondisi Aviduz sekarang sangat buruk.",
  ui_story_9_14_1_7_dialog_content = "Hmm… Baru saja… ketika Aviduz meratap, kedengarannya seperti tangisan terakhirnya sebelum meninggalkan dunia ini…",
  ui_story_9_14_1_8_dialog_content = "Ayo kita masuk dan cari tubuh Schummer.",
  ui_story_9_14_1_9_dialog_content = "Tunggu, ada yang datang!",
  ui_story_9_14_1_10_dialog_content = "Apa itu Schummer?",
  ui_story_9_14_1_11_dialog_content = "Bukan, itu jelas bukan Schummer.",
  ui_story_9_14_1_12_dialog_content = "Itu <color=#FFB400>Forsakin</color>!",
  ui_story_9_14_1_13_dialog_content = "!!!",
  ui_story_9_14_1_14_dialog_content = "!",
  ui_story_9_14_1_15_dialog_content = "Aku penasaran, siapa yang berani-beraninya menggangguku sekarang?",
  ui_story_9_14_1_16_dialog_content = "Ternyata kaulah orangnya.",
  ui_story_9_14_1_17_dialog_content = "Tak adakah yang pernah mengajarimu untuk menelepon dulu sebelum berkunjung?",
  ui_story_9_14_1_18_dialog_content = "Harusnya kamilah yang bilang begitu.",
  ui_story_9_14_1_19_dialog_content = "Ini Eraveil. Kau tak seharusnya ada di sini!",
  ui_story_9_14_1_20_dialog_content = "Karena aku sudah di sini, jelas aku tak akan tunduk pada aturanmu.",
  ui_story_9_14_1_21_dialog_content = "Kamu rupanya!",
  ui_story_9_14_1_22_dialog_content = "Kukira kau mati dalam kebakaran itu!",
  ui_story_9_14_1_23_dialog_content = "Tapi, aku bahkan akan tetap mengenali abumu, jangan kira kau bisa kabur dengan mengganti namamu!",
  ui_story_9_14_1_24_dialog_content = "…",
  ui_story_9_14_1_25_dialog_content = "Apa yang kaulakukan kepada adikku, <color=#FFB400>Denier</color>?",
  ui_story_9_14_1_26_dialog_content = "…",
  ui_story_9_14_1_27_dialog_content = "Hoi, kau tuli, ya?!",
  ui_story_9_14_1_28_dialog_content = "PlayerName, aku tak bisa merasakan Darkflow apa pun pada dirimu…",
  ui_story_9_14_1_29_option_content = "Siapa kau sebenarnya?",
  ui_story_9_14_1_30_dialog_content = "Jangan bilang dulu kau adalah peneliti di Illumina.",
  ui_story_9_14_1_31_dialog_content = "Memang apa hubungannya denganmu?",
  ui_story_9_14_1_32_dialog_content = "Apa itu penting?",
  ui_story_9_14_1_33_dialog_content = "Sama sekali tidak.",
  ui_story_9_14_1_34_dialog_content = "Sekarang, di mana Seed yang ada dalam tubuhmu, PlayerName?",
  ui_story_9_14_1_35_dialog_content = "Rupanya kaulah yang menanamnya di punggungku!",
  ui_story_9_14_1_36_dialog_content = "Aku sempat jadi gatal-gatal karenanya.",
  ui_story_9_14_1_37_dialog_content = "Gatal?",
  ui_story_9_14_1_38_dialog_content = "Lalu, apa yang terjadi? Berapa lama gatal-gatalnya?",
  ui_story_9_14_1_39_dialog_content = "Sekitar… Hei, memangnya untuk apa aku harus memberitahumu?",
  ui_story_9_14_1_40_dialog_content = "Hati-hati, PlayerName. Jangan biarkan dia mengendalikanmu.",
  ui_story_9_14_1_41_dialog_content = "Bagaimana kau menyingkirkan Seed itu dari punggungmu?",
  ui_story_9_14_1_42_dialog_content = "Kalau mau tahu, kau harus menjawab pertanyaanku dulu…",
  ui_story_9_14_1_43_option_content = "Kenapa kau ada di Eraveil?",
  ui_story_9_14_1_44_dialog_content = "Kenapa kau mengubah Aurorian menjadi Eclipsite? Kenapa melakukan eksperimen yang tak berperasaan itu?",
  ui_story_9_14_1_45_option_content = "Kenapa kau menanam Seed ke dalam tubuhku?",
  ui_story_9_14_1_46_dialog_content = "Kalau aku tak mengeluarkannya, apakah aku akan berubah jadi Eclipsite?",
  ui_story_9_14_1_47_dialog_content = "Kau terlalu banyak bertanya.",
  ui_story_9_14_1_48_dialog_content = "Aku hanya bisa bilang bahwa aku sangat kecewa, PlayerName.",
  ui_story_9_14_1_49_dialog_content = "Aku memberimu kesempatan untuk memperoleh kekuatan yang sangat besar dan mengetahui kebenaran dunia.",
  ui_story_9_14_1_50_dialog_content = "Tapi kau menyia-nyiakan kesempatan itu dan berpaling darinya.",
  ui_story_9_14_1_51_dialog_content = "Sayang sekali.",
  ui_story_9_14_1_52_dialog_content = "Dan sekarang kau tak perlu mencari tahu, PlayerName.",
  ui_story_9_14_1_53_dialog_content = "Jangan dengarkan dia!",
  ui_story_9_14_1_54_dialog_content = "Aku yakin dia mantan peneliti Illumina itu, Denier!",
  ui_story_9_14_1_55_dialog_content = "Denier? Aku tak pernah mendengar nama itu.",
  ui_story_9_14_1_56_dialog_content = "Jangan pura-pura!",
  ui_story_9_14_1_57_dialog_content = "Gara-gara kau, Eve menderita bertahun-tahun!",
  ui_story_9_14_1_58_dialog_content = "Eve?",
  ui_story_9_14_1_59_dialog_content = "Ingat?",
  ui_story_9_14_1_60_dialog_content = "Sedikit, tapi masih tidak ingat.",
  ui_story_9_14_1_61_dialog_content = "Lagi pula, eksperimen dan subjekku jumlahnya tak terhingga.",
  ui_story_9_14_1_62_dialog_content = "Kau…!",
  ui_story_9_14_1_63_dialog_content = "Tenang, Sinsa. Forsakin hanya berusaha memancingmu.",
  ui_story_9_14_1_64_dialog_content = "Aku tenang!",
  ui_story_9_14_1_65_dialog_content = "Sangat tenang, sampai-sampai aku sudah memikirkan ratusan cara untuk mencabik-cabik tubuhnya!",
  ui_story_9_14_1_66_dialog_content = "Sepertinya kau memikirkan ratusan cara untuk menghabisiku.",
  ui_story_9_14_1_67_dialog_content = "Sepertinya aku harus memberimu pelajaran!",
  ui_story_9_14_1_68_dialog_content = "…",
  ui_story_9_14_1_69_dialog_content = "Tong kosong nyaring bunyinya.",
  ui_story_9_14_1_70_dialog_content = "Kau baik-baik saja, Bos?",
  ui_story_9_14_1_71_dialog_content = "*Batuk-batuk*… Aku baik-baik saja!",
  ui_story_9_14_1_72_dialog_content = "Apa yang terjadi?",
  ui_story_9_14_1_73_dialog_content = "Dia melambaikan tangannya dan Sinsa terpental.",
  ui_story_9_14_1_74_dialog_content = "Dia memakai Eclipsium.",
  ui_story_9_14_1_75_dialog_content = "Si Forsakin di depan kita itu telah meninggalkan jati dirinya sebagai Aurorian dan lebih memilih menjadi monster!",
  ui_story_9_14_1_76_dialog_content = "Akan kubunuh kau, dasar penyihir!",
  ui_story_9_14_1_77_dialog_content = "Diam… Jangan lupa diri.",
  ui_story_9_14_1_78_dialog_content = "Aku tak suka bertempur.",
  ui_story_9_14_1_79_dialog_content = "Tapi, jika kau memaksa, aku bisa mencarikan lawan yang sesuai.",
  ui_story_9_14_1_80_dialog_content = "Mainlah dengan teman-teman barumu, Mad Horn.",
  ui_story_9_14_1_81_dialog_content = "<anim type=Shake>Taba… tak akan… mati!</anim>",
  ui_story_9_14_1_82_dialog_content = "Mad Horn? Ini jelas-jelas Tabaad yang kita lawan waktu itu!",
  ui_story_9_14_1_X82_dialog_content = "Nama itu hanyalah kode yang dibuat agar mudah diingat…",
  ui_story_9_14_1_83_dialog_content = "Kau pernah bertemu Eclipsite ini?",
  ui_story_9_14_1_84_dialog_content = "Commander Hiiro menghantamnya dengan telak saat berada di dalam Mantiz…",
  ui_story_9_14_1_85_dialog_content = "Ini makhluk lain yang dibuat dengan menghidupkan makhluk yang sudah mati.",
  ui_story_9_14_1_86_dialog_content = "Forsakinlah yang telah menghidupkan monster-monster yang sudah mati itu!",
  ui_story_9_14_1_87_dialog_content = "Sebut saja daur ulang yang efisien.",
  ui_story_9_14_1_88_dialog_content = "Ini sudah lebih dari cukup untuk membuatmu kewalahan.",
  ui_story_9_14_1_89_dialog_content = "<anim type=Shake>Aahhhhhh!</anim>",
  ui_story_9_14_1_90_dialog_content = "<anim type=Shake>Taba… tak akan… mati!</anim>",
  ui_story_9_14_2_1_dialog_content = "<anim type=Shake>Aduh!</anim>",
  ui_story_9_14_2_2_dialog_content = "Tetap waspadai Forsakin!",
  ui_story_9_14_2_3_dialog_content = "Awas, PlayerName!",
  ui_story_9_14_2_4_dialog_content = "!",
  ui_story_9_14_2_5_dialog_content = "Jangan berani-berani menyentuh siapa pun!",
  ui_story_9_14_2_6_dialog_content = "…",
  ui_story_9_14_2_7_dialog_content = "Bos!",
  ui_story_9_14_2_8_dialog_content = "Kau tidak apa-apa, Sinsa?",
  ui_story_9_14_2_9_dialog_content = "Aku baik-baik saja! *Batuk-batuk*",
  ui_story_9_14_2_10_dialog_content = "Satu langkah lagi, Aurorian pengkhianat, aku akan menegakkan keadilan!",
  ui_story_9_14_2_11_dialog_content = "Jangan senang dulu.",
  ui_story_9_14_2_12_dialog_content = "Aku hanya ingin melihat PlayerName lebih dekat.",
  ui_story_9_14_2_13_dialog_content = "Mau apa kau dengan PlayerName, Forsakin?",
  ui_story_9_14_2_14_dialog_content = "Kau menolak untuk menjawab pertanyaanku, jadi aku harus melakukan risetku sendiri.",
  ui_story_9_14_2_15_dialog_content = "Memang benar tak ada tanda-tanda Seed di tubuhmu, PlayerName.",
  ui_story_9_14_2_16_dialog_content = "Sekali lagi, bagaimana caramu mengeluarkannya?",
  ui_story_9_14_2_17_dialog_content = "Katakan padaku alasanmu melakukan eksperimen seperti itu.",
  ui_story_9_14_2_18_dialog_content = "Kau masih tak menyadari kondisimu sekarang, PlayerName.",
  ui_story_9_14_2_19_dialog_content = "Kau tak berhak dan tak punya kuasa untuk tawar-menawar denganku.",
  ui_story_9_14_2_20_dialog_content = "Jangan buang waktumu untuknya, PlayerName.",
  ui_story_9_14_2_21_dialog_content = "Hah?",
  ui_story_9_14_2_22_dialog_content = "Akulah yang mengeluarkannya dari PlayerName. Keberatan?",
  ui_story_9_14_2_23_dialog_content = "Bagaimana mungkin ada pengkhianat sepertimu di Illumina?",
  ui_story_9_14_2_24_dialog_content = "Jangan berbuat bodoh, Vice!",
  ui_story_9_14_2_25_dialog_content = "Cepat katakan yang sebenarnya.",
  ui_story_9_14_2_26_dialog_content = "Aghhh! Oh…",
  ui_story_9_14_2_27_dialog_content = "Vice!",
  ui_story_9_14_2_28_dialog_content = "Forsakin! Lepaskan Vice sekarang juga!",
  ui_story_9_14_2_29_dialog_content = "Aku akan berhenti, tapi aku punya syarat yang harus kaupenuhi.",
  ui_story_9_14_2_30_dialog_content = "Katakan, ke mana perginya Seed itu?",
  ui_story_9_14_2_31_dialog_content = "…",
  ui_story_9_14_2_32_dialog_content = "(Aku tak boleh membahayakan Vice…)",
  ui_story_9_14_2_33_dialog_content = "(Sepertinya aku terpaksa memberitahunya.)",
  ui_story_9_14_2_34_dialog_content = "Aku akan memberitahumu, tapi lepaskan dia dulu! Aku janji aku akan memberitahumu!",
  ui_story_9_14_2_X34_dialog_content = "Baiklah.",
  ui_story_9_14_2_X35_dialog_content = "*Batuk-batuk*",
  ui_story_9_14_2_X36_dialog_content = "Vice, kemari!",
  ui_story_9_14_2_X37_dialog_content = "Nah. Bicaralah.",
  ui_story_9_14_2_35_dialog_content = "Seed itu diambil oleh seorang pria yang membawa koper putih.",
  ui_story_9_14_2_36_dialog_content = "Pria yang membawa koper putih…",
  ui_story_9_14_2_37_dialog_content = "Siapa dia?",
  ui_story_9_14_2_38_dialog_content = "Aku tak tahu siapa dia atau alasan dia mengambil Seed itu.",
  ui_story_9_14_2_39_dialog_content = "Dia bilang Seed itu bisa mengubah Aurorian menjadi Eclipsite!",
  ui_story_9_14_2_40_dialog_content = "Tidak hanya aku saja yang ingin kauubah menjadi Eclipsite, bahkan para prajurit Lumopolis itu juga!",
  ui_story_9_14_2_41_dialog_content = "Orang-orang yang kausebut subjek itu sebenarnya adalah korban Seed!",
  ui_story_9_14_2_42_dialog_content = "Benar, 'kan?",
  ui_story_9_14_2_43_dialog_content = "Karena kau sangat percaya, masih ada banyak hal yang ingin kukatakan.",
  ui_story_9_14_2_44_dialog_content = "Tidak, aku ingin tahu kenapa kau melakukan eksperimen tidak manusiawi itu?",
  ui_story_9_14_2_45_dialog_content = "Kau ini Aurorian… Tapi, kenapa justru bersekongkol dengan kegelapan?",
  ui_story_9_14_2_46_dialog_content = "Sudah kubilang, PlayerName. Kesempatanmu untuk mencari tahu telah habis.",
  ui_story_9_14_2_47_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_9_14_2_48_dialog_content = "Hmm, sudah saatnya.",
  ui_story_9_14_2_49_dialog_content = "Suara berisik apa itu?",
  ui_story_9_14_2_50_dialog_content = "Suaranya dari dalam Aviduz.",
  ui_story_9_14_2_51_dialog_content = "Itu suara saat Colossus berhenti berfungsi.",
  ui_story_9_14_2_52_dialog_content = "(Aku tak bisa merasakan apa pun lagi dari Aviduz.)",
  ui_story_9_14_2_53_dialog_content = "(Apakah dia… sudah mati?)",
  ui_story_9_14_2_54_dialog_content = "Kau bahkan menghabisi Aviduz, Forsakin?!",
  ui_story_9_14_2_55_dialog_content = "Apa yang kaulakukan kepadanya?",
  ui_story_9_14_2_56_dialog_content = "Pertanyaanmu benar-benar tak ada habisnya, PlayerName.",
  ui_story_9_14_2_57_dialog_content = "Kalau memang ingin tahu, kenapa kau tak masuk saja ke dalam Colossus itu dan tanyakan kepada <color=#FFB400>teman lamamu</color>?",
  ui_story_9_14_2_58_dialog_content = "Forsakin masuk ke dalam Colossus!",
  ui_story_9_14_2_59_dialog_content = "Hei, kembali ke sini!",
  ui_story_9_14_2_60_dialog_content = "\"<color=#FFB400>Teman lama</color>\"?",
  ui_story_9_14_2_61_dialog_content = "…",
  ui_story_9_14_2_62_dialog_content = "Schummer…",
  ui_story_9_14_2_63_dialog_content = "<size=45>Schummer masih hidup!</size>",
  ui_story_10_1_1_1_dialog_content = "<color=#e8d9bb>Lumopolis, di depan pusat perawatan medis</color>",
  ui_story_10_1_1_2_dialog_content = "Rupanya seperti inilah Lumopolis Courtyard, meong?",
  ui_story_10_1_1_S1_dialog_content = "Bangunan-bangunan ini… terlihat lebih mewah daripada yang sebelumnya.",
  ui_story_10_1_1_3_dialog_content = "Saya yakin berharap Ketua Vivian tinggal sedikit lebih lama untuk mendapatkan kembali kekuatannya. Dengan begitu, Philyshy bisa istirahat lebih lama...",
  ui_story_10_1_1_4_dialog_content = "Meong?",
  ui_story_10_1_1_5_dialog_content = "Mana pasien barunya? Aku menuju ke sana!",
  ui_story_10_1_1_6_dialog_content = "Madam, tolong jangan mondar-mandir di sini!",
  ui_story_10_1_1_7_dialog_content = "Dia sudah pergi, meong?",
  ui_story_10_1_1_8_dialog_content = "Nyehehe, sepertinya sekaranglah kesempatan untuk Philyshy…",
  ui_story_10_1_1_9_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_10_1_1_10_dialog_content = "Ya ampun, berapa lama lagi sih aku harus di sini? Mereka tak mengizinkanku melakukan apa pun sampai aku pulih…",
  ui_story_10_1_1_11_dialog_content = "Kyuu!",
  ui_story_10_1_1_12_dialog_content = "Terima kasih telah menghiburku, Curie. Aku hanya sedikit cemas, itu saja…",
  ui_story_10_1_1_13_dialog_content = "Bagaimana kalau kau berjaga di luar sebentar?",
  ui_story_10_1_1_14_dialog_content = "Kyuu!",
  ui_story_10_1_1_15_dialog_content = "Lalu…",
  ui_story_10_1_1_16_dialog_content = "<color=#e8d9bb>*Gemerisik*</color>",
  ui_story_10_1_1_17_dialog_content = "Kau yang di sana. Telingamu menyapu bersih lantai ini, dasar kucing kecil penguping.",
  ui_story_10_1_1_18_dialog_content = "Meong? Tapi Philyshy tidak menyapu lantai!",
  ui_story_10_1_1_19_dialog_content = "Philyshy hanya ingin mendengarkan pergerakan musuh di tanah, itu saja!",
  ui_story_10_1_1_20_dialog_content = "Aku tahu apa yang kaucemaskan.",
  ui_story_10_1_1_21_dialog_content = "Meskipun mereka menata ruangan ini untukku, tak diragukan lagi…",
  ui_story_10_1_1_22_dialog_content = "Tempat ini tak dilengkapi sistem pengawasan.",
  ui_story_10_1_1_S2_dialog_content = "Mereka hanya ingin aku tinggal lebih lama di Lumopolis.",
  ui_story_10_1_1_23_dialog_content = "Jadi, ada kabar apa untukku?",
  ui_story_10_1_1_24_dialog_content = "Ehehe, itu baru Vivian yang kukenal! Kau benar-benar mengenal Philyshy!",
  ui_story_10_1_1_25_dialog_content = "Ehem, setelah Philyshy memperoleh informasi tentang <color=#FFB400>Forsakin</color>, Philyshy langsung memberitahumu.",
  ui_story_10_1_1_26_dialog_content = "Apa yang sudah bisa kaupastikan tentang dia?",
  ui_story_10_1_1_27_dialog_content = "Sulit untuk dikatakan, meong.",
  ui_story_10_1_1_28_dialog_content = "Lagi pula… menurut laporan internal, sudah 9 tahun berlalu sejak dia <color=#FFB400>mati</color>.",
  ui_story_10_1_1_29_dialog_content = "Setelah kebakaran hebat yang menghancurkan seluruh Undercity…",
  ui_story_10_1_1_30_dialog_content = "Semua orang mengira dia mati dalam kebakaran itu.",
  ui_story_10_1_1_31_dialog_content = "Tapi, tim penyelidik menemukan jasad Eclipsite dan Aurorian di reruntuhan itu.",
  ui_story_10_1_1_32_dialog_content = "Saat aku mendengar bahwa Forsakin menanamkan <color=#FFB400>Seed</color> di dalam tubuh PlayerName…",
  ui_story_10_1_1_33_dialog_content = "Saat itu juga, aku langsung tahu hubungannya, meong!",
  ui_story_10_1_1_34_dialog_content = "Menurutmu ini ada hubungannya dengan apa yang dicari Forsakin waktu itu?",
  ui_story_10_1_1_35_dialog_content = "Sepertinya dia telah… <color=#FFB400>berubah menjadi Eclipsite</color>.",
  ui_story_10_1_1_36_dialog_content = "Bagaimana reaksi Grand Marshal setelah tahu bahwa Forsakin masih hidup?",
  ui_story_10_1_1_37_dialog_content = "Meong… Soal itu…",
  ui_story_10_1_1_38_dialog_content = "Ada apa? Kenapa kau begitu gugup?",
  ui_story_10_1_1_39_dialog_content = "K-kau tahu hubungan mereka berdua, 'kan? Jadi…",
  ui_story_10_1_1_40_dialog_content = "Aku tahu apa yang membuatmu cemas. Itu karena <color=#FFB400>Forsakin adalah adik perempuan Grand Marshal</color>, bukan?",
  ui_story_10_1_1_41_dialog_content = "Tepat sekali! Kau memang atasanku, meong. Hanya dengan petunjuk kecil, kau bisa melihat semua isi hati Philyshy.",
  ui_story_10_1_1_42_dialog_content = "Beri tahu aku apa yang terjadi.",
  ui_story_10_1_1_43_dialog_content = "Grand Marshal mengumpulkan semua Legion Commander dan pergi. Dia bilang mereka akan mengadakan rapat komandan, tapi…",
  ui_story_10_1_1_44_dialog_content = "Menurut Philyshy, kali ini ada yang berbeda.",
  ui_story_10_1_1_45_dialog_content = "Keempat Legion Commander itu adalah orang kepercayaan Grand Marshal, sekaligus prajurit terkuat di Illumina.",
  ui_story_10_1_1_46_dialog_content = "Madam… apakah menurutmu Grand Marshal membawa mereka untuk memburu Forsakin?",
  ui_story_10_1_1_47_dialog_content = "Penilaianmu tentang Eclipsite memang layak dipuji, Philyshy.",
  ui_story_10_1_1_48_dialog_content = "Tapi, kalau berkaitan dengan rekan-rekanmu, sepertinya analisismu masih perlu diperbaiki.",
  ui_story_10_1_1_49_dialog_content = "Meong…",
  ui_story_10_1_1_50_dialog_content = "B-bisakah kau memberitahuku jawabannya, Madam? Otak Philyshy tak sanggup…",
  ui_story_10_1_1_51_dialog_content = "Kau benar-benar mengira bahwa Grand Marshal kita akan menyalahgunakan kekuasaannya dan bertindak begitu gegabah gara-gara dendam pribadi?",
  ui_story_10_1_1_52_dialog_content = "Nyeh? P-Philyshy tidak menuduh Grand Marshal apa pun! Sungguh!",
  ui_story_10_1_1_53_dialog_content = "Aku tahu… jangan takut, biar kujelaskan.",
  ui_story_10_1_1_54_dialog_content = "Kemunculan Forsakin adalah pertanda bagi kita.",
  ui_story_10_1_1_55_dialog_content = "Saat predator menyudutkan mangsanya dan bersiap untuk membunuh… Saat itulah mereka justru paling rentan.",
  ui_story_10_1_1_56_dialog_content = "Meong! Aku paham! Philyshy seharusnya tidak mencampuri urusan Grand Marshal, 'kan?",
  ui_story_10_1_1_57_dialog_content = "Lagi pula, Grand Marshal pasti punya rencana sendiri!",
  ui_story_10_1_1_58_dialog_content = "Ya. Kuharap kau benar-benar mengerti. Apa pun yang terjadi, cobalah untuk tidak terlalu banyak menduga-duga tentang masalah Grand Marshal, Philyshy.",
  ui_story_10_1_1_59_dialog_content = "Meong-ya!",
  ui_story_10_1_1_60_dialog_content = "Kalau begitu Philyshy sebaiknya terus menyelidiki Seed, 'kan?",
  ui_story_10_1_1_61_dialog_content = "Tentu saja!",
  ui_story_10_1_1_62_dialog_content = "Lalu, bolehkah Philyshy pergi mencari Vice dan yang lainnya, meong?",
  ui_story_10_1_1_63_dialog_content = "Hmm? Kenapa kamu bisa menyimpulkan begitu?",
  ui_story_10_1_1_64_dialog_content = "Sederhana saja. Aku mendapatkan informasi tentang Seed dari Vice dan PlayerName sendiri!",
  ui_story_10_1_1_65_dialog_content = [[
Dalam perjalanan ke sini, aku mendengar mereka mengatakan sesuatu 
tentang Aviduz yang jatuh dari langit, meong!]],
  ui_story_10_1_1_66_dialog_content = "Dan mereka bilang ada Colossus yang meninggalkan Lumopolis beberapa hari yang lalu!",
  ui_story_10_1_1_67_dialog_content = "Aku cukup yakin itu berarti Vice dan teman-temannya berangkat untuk <color=#FFB400>mengejar Aviduz</color>, meong!",
  ui_story_10_1_1_68_dialog_content = "Karena ada hubungan antara Seed dan Aviduz, walau entah apa hubungannya… Bagaimana kalau kukejar saja Aviduz itu?",
  ui_story_10_1_1_69_dialog_content = "Philyshy… kau benar-benar cerdas…",
  ui_story_10_1_1_70_dialog_content = "Kau benar sekali. PlayerName dan Vice sedang dalam perjalanan menuju lokasi Aviduz sekarang.",
  ui_story_10_1_1_71_dialog_content = "Philyshy boleh ikut juga?",
  ui_story_10_1_1_72_dialog_content = "Tunggu, kau tak pergi hanya untuk bersenang-senang, 'kan?",
  ui_story_10_1_1_73_dialog_content = "Sama sekali tidak! Philyshy punya firasat buruk tentang semua ini…",
  ui_story_10_1_1_74_dialog_content = "Bagaimanapun, ini berkaitan dengan Schummer dan Forsakin. Bukan hanya untuk penyelidikan, tapi juga untuk berjaga-jaga.",
  ui_story_10_1_1_75_dialog_content = "Ikut dengan mereka adalah keputusan terbaik!",
  ui_story_10_1_1_76_dialog_content = "Selain itu, memikirkan semua informasi tentang Forsakin membuatku sangat bersemangat, bahkan aku sampai tak bisa duduk, meong!",
  ui_story_10_1_1_77_dialog_content = "Bagaimana jika Forsakin berhasil menangkap PlayerName dan Vice lalu melakukan percobaan terhadap mereka?",
  ui_story_10_1_1_78_dialog_content = "Baiklah… Aku paham pemikiranmu sekarang.",
  ui_story_10_1_1_79_dialog_content = "Tapi kau tak perlu terlalu mengkhawatirkan Vice dan teman-temannya.",
  ui_story_10_1_1_80_dialog_content = [[
Sebelum mereka berangkat, kami membicarakan beberapa kemungkinan 
yang mungkin terjadi saat mereka bertemu Forsakin.]],
  ui_story_10_1_1_81_dialog_content = "Yang terpenting adalah Kapten Carleen juga ada bersama mereka.",
  ui_story_10_1_1_82_dialog_content = "Itu berarti… Lumopolis telah mengambil alih masalah Schummer, dan semua yang berhubungan dengannya.",
  ui_story_10_1_1_83_dialog_content = "Meong? Jadi begitu…",
  ui_story_10_1_1_84_dialog_content = "Kalau begitu, mungkin sebaiknya aku tetap di sini…",
  ui_story_10_1_1_85_dialog_content = "Ya. Sampai situasinya bisa dipastikan, kita harus menunggu komunikasi dari Vice dulu.",
  ui_story_10_2_1_1_dialog_content = "Um…",
  ui_story_10_2_1_2_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_10_2_1_3_dialog_content = "Habisi semua yang menghalangi kita, tentunya! Apa lagi? Memangnya kau mau kalau dia sampai kabur?",
  ui_story_10_2_1_4_dialog_content = "Tenangkan dirimu.",
  ui_story_10_2_1_5_dialog_content = "Mau dilihat dari mana pun juga, sudah jelas kita dipancing masuk.",
  ui_story_10_2_1_6_dialog_content = "Ya ampun!",
  ui_story_10_2_1_7_dialog_content = "Kalau kita masuk, kita mungkin akan kena jebakan dari Forsakin.",
  ui_story_10_2_1_8_dialog_content = "Tapi kalau tidak, itu sama saja kita melepaskan dia begitu saja!",
  ui_story_10_2_1_9_dialog_content = "Belum lagi, kalian juga sedang mencari <color=#FFB400>Schummer</color>, 'kan?",
  ui_story_10_2_1_10_dialog_content = "Yang aku tahu dengan pasti adalah Schummer masih hidup, dan dia ada di dalam Aviduz!",
  ui_story_10_2_1_11_dialog_content = "Aku bisa merasakan keberadaannya, tapi rasanya sangat lemah… Kurasa dia cedera.",
  ui_story_10_2_1_12_dialog_content = "Kita tidak boleh gegabah. Mungkin kalau kita buat pertahanan di posisi ini…",
  ui_story_10_2_1_13_dialog_content = "Coba kutebak, kamu mau memanggil bala bantuan dari Lumopolis atau Illumina, ya?",
  ui_story_10_2_1_14_dialog_content = "Lupakan saja. Kita bakal keburu ubanan begitu anak buah mereka muncul.",
  ui_story_10_2_1_15_dialog_content = "Tolong jangan nilai semuanya berdasarkan perasaan.",
  ui_story_10_2_1_16_dialog_content = "Hah! Mereka cuma mengirimmu sendirian… Itu sudah jelas, 'kan?",
  ui_story_10_2_1_17_dialog_content = "Ada banyak prajurit Lumopolis yang mati di sini… Mereka tahu seperti apa kondisi di sini!",
  ui_story_10_2_1_18_dialog_content = "Kalau mereka memang berniat membantu, mereka tak akan perlu menunggu panggilanmu.",
  ui_story_10_2_1_19_dialog_content = "Anu, ku-kurasa sebaiknya kita jangan bertengkar…",
  ui_story_10_2_1_20_dialog_content = "Kalau kita berteriak cukup keras, mungkin rekan kita akan mendengarnya \ndan menolong kita…",
  ui_story_10_2_1_21_dialog_content = "Kamu mau tunggu sampai mereka menemukan kita? Kita jatuh ke sini! Mereka tak akan menemukan kita, kecuali mereka juga jatuh ke sini!",
  ui_story_10_2_1_22_dialog_content = "Benar… kurasa mereka juga tak akan menemukan jalan kemari…",
  ui_story_10_2_1_23_dialog_content = "Apa Forsakin benar-benar membuat perangkap hanya untuk membunuh kita semua?",
  ui_story_10_2_1_24_dialog_content = "Entah kenapa, sepertinya bukan begitu…",
  ui_story_10_2_1_25_dialog_content = "Waktu tadi kita melawannya, kita bahkan tidak bisa menyentuhnya sama sekali.",
  ui_story_10_2_1_26_dialog_content = "Meskipun dia sekuat itu, rasanya seakan-akan…",
  ui_story_10_2_1_27_dialog_content = "<color=#FFB400>Dia tidak berencana menyerang kita.</color>",
  ui_story_10_2_1_28_dialog_content = "Apa mungkin dia ingin kita menemui Schummer?",
  ui_story_10_2_1_29_dialog_content = "Seandainya saja kita punya informasi lebih lengkap…",
  ui_story_10_2_1_30_dialog_content = "PlayerName, apa kamu bisa menggunakan kekuatan psikismu untuk merasakan apa yang dipikirkan Forsakin?",
  ui_story_10_2_1_31_dialog_content = "Sebenarnya… Tadi aku sudah mencobanya…",
  ui_story_10_2_1_32_dialog_content = "Maaf, tapi aku <color=#FFB400>tidak bisa menggunakan kekuatanku seperti itu kepada Forsakin</color>.",
  ui_story_10_2_1_33_dialog_content = "Kenapa?",
  ui_story_10_2_1_34_dialog_content = "Aku juga kurang yakin cara menjelaskannya. Hanya saja…",
  ui_story_10_2_1_35_dialog_content = "Merasakan pikiran seseorang saja sudah sulit.",
  ui_story_10_2_1_36_dialog_content = "Jarak, kekuatan pengguna, dan apakah target melawan atau tidak… Ada banyak faktor yang bisa memengaruhi hasil kemampuan itu.",
  ui_story_10_2_1_37_dialog_content = "Jujur saja, kemampuan itu baru bekerja dengan baik saat aku merasakan keberadaan Schummer barusan…",
  ui_story_10_2_1_38_dialog_content = "Lalu… rasanya jadi makin mudah.",
  ui_story_10_2_1_39_dialog_content = "Satu-satunya yang aku yakin saat ini adalah Schummer cedera parah.",
  ui_story_10_2_1_40_dialog_content = "Vice, Carleen… Aku…",
  ui_story_10_2_1_41_dialog_content = [[
Ayo kita masuk! Kita selalu menerjang maju saat situasi tampak bahaya, 
dan kali ini tak ada bedanya!]],
  ui_story_10_2_1_42_dialog_content = "Baiklah, ayo kita masuk dan survei areanya. Aku akan memimpin.",
  ui_story_10_2_1_43_dialog_content = "Sekarang kau mau masuk? Bahkan kau berjalan lebih cepat dariku!",
  ui_story_10_2_1_44_dialog_content = "Kalian ini repot-repot bicara panjang lebar, padahal kesimpulannya sama saja dengan yang sebelumnya…",
  ui_story_10_2_1_45_dialog_content = "Aku tahu kau dan Vice memang dekat, tapi sejak kapan si Carleen itu mulai menurutimu juga?",
  ui_story_10_2_1_46_dialog_content = "Mereka tidak menurutiku… Vice dan Carleen selama ini sudah membantuku, bukan sebaliknya, jadi aku berterima kasih kepada mereka.",
  ui_story_10_2_1_47_dialog_content = "Kuharap aku bisa membalas budi atas bantuan mereka setelah ini semua selesai.",
  ui_story_10_2_1_48_dialog_content = "Ayo…",
  ui_story_10_2_1_49_dialog_content = "Jadi, inilah Aviduz, ya?",
  ui_story_10_2_1_50_dialog_content = "Hah, apanya yang mengerikan dari ini?! Semua bagiannya rusak parah, kurasa membunuh seekor Sandworm pun tak mungkin bisa!",
  ui_story_10_2_1_51_dialog_content = "Itu karena Lumopolis menembaknya jatuh.",
  ui_story_10_2_1_52_dialog_content = "Iya, iya, tak usah terus-menerus mengingatkanku.",
  ui_story_10_2_1_53_dialog_content = "Aku hanya menjawab keraguanmu… Atau jangan-jangan, kaukira Lumopolis tak cukup kuat untuk melakukan ini?",
  ui_story_10_2_1_54_dialog_content = "*Uhuk* Uh, kondisi Aviduz yang kehabisan energinya mungkin juga jadi salah satu faktor…",
  ui_story_10_2_1_55_dialog_content = "*Uhuk-uhuk*",
  ui_story_10_2_1_56_dialog_content = "Kenapa batuk-batuk begitu? Apa kau takut kita bakal mulai bertengkar lagi?",
  ui_story_10_2_1_57_dialog_content = "Bukan… Ini gara-gara Darkflow…",
  ui_story_10_2_1_58_dialog_content = "Aviduz rusak parah, tapi Darkflow di sini masih sangat kuat…",
  ui_story_10_2_1_59_dialog_content = "Grrr…",
  ui_story_10_2_1_60_dialog_content = "Eclipsite? Semuanya, tetap waspada!",
  ui_story_10_2_1_61_dialog_content = "Ahhhh!",
  ui_story_10_2_2_1_dialog_content = "Graaah—!",
  ui_story_10_2_2_2_dialog_content = "Gawat! Awas, PlayerName!",
  ui_story_10_2_2_3_dialog_content = "Enyahlah kau!",
  ui_story_10_2_2_4_dialog_content = "Kau baik-baik saja?",
  ui_story_10_2_2_5_dialog_content = "*Terengah-engah* Ah… terima kasih…",
  ui_story_10_2_2_6_dialog_content = "Aku tidak apa-apa, tapi celanaku tadi hampir terbakar…",
  ui_story_10_2_2_7_dialog_content = "Maaf! Ada satu yang lolos…",
  ui_story_10_2_2_8_dialog_content = "Di sebelah sana!",
  ui_story_10_2_2_9_dialog_content = "Aahhhhhh!",
  ui_story_10_2_2_10_dialog_content = "Hah? Kenapa dia lari? Jangan kabur…",
  ui_story_10_2_2_11_dialog_content = "Kamu mau ke mana, hah?!",
  ui_story_10_2_2_12_dialog_content = "Grrr…",
  ui_story_10_2_2_13_dialog_content = "Aneh… sepertinya Eclipsite-Eclipsite ini buta. Apa mereka tidak bisa melihat kita?",
  ui_story_10_2_2_14_dialog_content = "Ya, aneh… Biasanya, Eclipsite akan langsung menerjang begitu melihat kita.",
  ui_story_10_2_2_15_dialog_content = "Tapi Eclipsite ini kelihatannya tidak ingin menyergap kita…",
  ui_story_10_2_2_16_dialog_content = "Bahkan mereka lari dari kita.",
  ui_story_10_2_2_17_dialog_content = "Eh, bisa jadi memang begitu. Lupakan saja cecurut-cecurut ini, kita langsung cari Forsakin dan selesaikan urusannya.",
  ui_story_10_2_2_18_dialog_content = "Tingkah laku aneh ini mungkin ada hubungannya dengan Forsakin. Bagaimanapun juga, kita harus tetap waspada.",
  ui_story_10_2_2_19_dialog_content = "Ya, bisa jadi.",
  ui_story_10_2_2_20_dialog_content = "Kita harus habisi Eclipsite yang kita temukan sambil terus maju. Kalau tidak…",
  ui_story_10_2_2_21_dialog_content = "Ada kemungkinan kita akan dikepung oleh Eclipsite dan diserang dari kedua sisi.",
  ui_story_10_2_2_22_dialog_content = "Aku tahu Darkflow di sini membuatmu kesulitan, PlayerName…",
  ui_story_10_2_2_23_dialog_content = "Tetapi apa kau masih bisa menggunakan kemampuan psikismu untuk mengintai ke sana?",
  ui_story_10_2_2_24_dialog_content = "Akan kucoba.",
  ui_story_10_2_2_25_dialog_content = "…",
  ui_story_10_2_2_26_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_10_2_2_27_dialog_content = "Brrr! Dari mana asal angin ini…?",
  ui_story_10_2_2_28_dialog_content = "Sst! Diam dong. Masa kau tak lihat PlayerName sedang berkonsentrasi?",
  ui_story_10_2_2_29_dialog_content = "Tapi, Bos… kau sendiri malah lebih berisik daripada aku…",
  ui_story_10_2_2_30_dialog_content = "Sst…",
  ui_story_10_2_2_31_dialog_content = "(Darkflow-nya…)",
  ui_story_10_2_2_32_dialog_content = "(Sepertinya Darkflow-nya terkonsentrasi di satu arah.)",
  ui_story_10_2_2_33_dialog_content = "(Rasanya mual sekali… Kepadatannya terus berubah antara menipis dan menebal… \nAku tidak tahan lagi.)",
  ui_story_10_2_2_34_dialog_content = "(Eclipsite… Eclipsite…)",
  ui_story_10_2_2_35_dialog_content = "(Semuanya Eclipsite.)",
  ui_story_10_2_2_36_dialog_content = "(Rasanya mau muntah… Bau apa ini…?)",
  ui_story_10_2_2_37_dialog_content = "(Lalu…)",
  ui_story_10_2_2_38_dialog_content = "<color=#e8d9bb>Krauk…</color>",
  ui_story_10_2_2_39_dialog_content = "(Bunyi apa itu?)",
  ui_story_10_2_2_40_dialog_content = "<color=#e8d9bb>Krauk</color>",
  ui_story_10_2_2_41_dialog_content = "(Suara kertakan gigi?)",
  ui_story_10_2_2_42_dialog_content = "<color=#e8d9bb>Krauk</color>",
  ui_story_10_2_2_43_dialog_content = "(Tidak, dia mengunyah sesuatu…)",
  ui_story_10_2_2_44_dialog_content = "<color=#e8d9bb>Krauk</color>",
  ui_story_10_2_2_45_dialog_content = "(Sesuatu yang… lengket… baunya tidak enak…)",
  ui_story_10_2_2_46_dialog_content = "(Baunya… membuatku mual…)",
  ui_story_10_2_2_47_dialog_content = "(Aku juga bisa merasakan rasa sakit…)",
  ui_story_10_2_2_48_dialog_content = "(Apa itu? Di antara giginya, dan di bawah lidahnya…)",
  ui_story_10_2_2_49_dialog_content = "(Di dalam tenggorokannya juga… Sesuatu yang bergumpal dan basah?!)",
  ui_story_10_2_2_50_dialog_content = "Aduh…",
  ui_story_10_2_2_51_dialog_content = "Eclipsite ini… tidak enak.",
  ui_story_10_3_1_1_dialog_content = "Argh!",
  ui_story_10_3_1_2_dialog_content = "PlayerName! Sadarkan dirimu!",
  ui_story_10_3_1_3_dialog_content = "Argh… *Batuk-batuk*",
  ui_story_10_3_1_4_dialog_content = "Aku… Aku kembali… Hoek!",
  ui_story_10_3_1_5_dialog_content = "Apa yang terjadi? Aku belum pernah melihatmu seperti ini setelah menggunakan kekuatanmu!",
  ui_story_10_3_1_6_dialog_content = "*Batuk* Maaf… Aku merasakan sesuatu yang sangat menjijikkan. Hoek!",
  ui_story_10_3_1_7_dialog_content = "Baiklah, baiklah, keluarkan saja dulu.",
  ui_story_10_3_1_8_dialog_content = "Uh… M-mungkin sebaiknya kaumuntahkan saja dulu, kalau tidak, bisa-bisa kamu tersedak saat berbicara.",
  ui_story_10_3_1_9_dialog_content = "Apa Caelestite memang mengalami reaksi seperti ini setelah memakai kemampuan psikis mereka, Vice?",
  ui_story_10_3_1_10_dialog_content = "Tidak, ini belum pernah terjadi… kecuali terjadi sesuatu.",
  ui_story_10_3_1_11_dialog_content = "Sesuatu yang sangat buruk.",
  ui_story_10_3_1_12_dialog_content = "Grrr…",
  ui_story_10_3_1_13_dialog_content = "Kemarilah, ini perintah!",
  ui_story_10_3_1_14_dialog_content = "Grrr…",
  ui_story_10_3_1_15_dialog_content = "Merangkaklah masuk!",
  ui_story_10_3_1_16_dialog_content = "Grrr…",
  ui_story_10_3_1_17_dialog_content = "Bagus.",
  ui_story_10_3_1_18_dialog_content = "Graagh!",
  ui_story_10_3_1_19_dialog_content = "Diam. Kamu menimpaku.",
  ui_story_10_3_1_20_dialog_content = "Gah… gah!",
  ui_story_10_3_1_21_dialog_content = "…",
  ui_story_10_3_1_22_dialog_content = "Nah, begitu dong.",
  ui_story_10_3_1_23_dialog_content = "Forsakin, apa kamu tidak bisa membuat mereka lebih hati-hati saat mereka masuk?",
  ui_story_10_3_1_24_dialog_content = "Seluruh tubuhku sakit… Apa kamu juga mau meremukkanku dengan makhluk-makhluk kotor ini?",
  ui_story_10_3_1_25_dialog_content = "Apa? Aku tidak dengar kata-katamu.",
  ui_story_10_3_1_26_dialog_content = "Jangan pura-pura bego.",
  ui_story_10_3_1_27_dialog_content = "Aku bisa dengar suaramu dengan jelas… Mana mungkin kamu tidak mendengar teriakanku?",
  ui_story_10_3_1_28_dialog_content = "Apa kaukira volume suaramu ada hubungannya dengan apakah aku mau mendengarkanmu atau tidak?",
  ui_story_10_3_1_29_dialog_content = "Tapi kalau itu bisa membuatmu makan sedikit lebih banyak, kurasa aku tak keberatan mengobrol denganmu sebentar.",
  ui_story_10_3_1_30_dialog_content = "Memangnya siapa yang mau makan makhluk seperti ini?",
  ui_story_10_3_1_31_dialog_content = "Amarah akan merangsang pertumbuhanmu. Kamu harus belajar memanfaatkannya.",
  ui_story_10_3_1_32_dialog_content = "Jangan benar-benar makan Eclipsite itu, gigit satu dua kali saja dan hisap Darkflow mereka.",
  ui_story_10_3_1_33_dialog_content = "Ini cara termudah. Jangan bilang kamu sudah sampai sejauh ini tanpa tahu cara makan dengan benar.",
  ui_story_10_3_1_34_dialog_content = "Jangan coba-coba merendahkanku…",
  ui_story_10_3_1_35_dialog_content = "Seed di pungggung mereka terlalu keras… Aku tak bisa memakannya.",
  ui_story_10_3_1_36_dialog_content = "Lapisan luarnya saja yang keras. Gigit saja dengan keras, gigi Eclipsite-mu jauh lebih kuat dari dugaanmu.",
  ui_story_10_3_1_37_dialog_content = "Aku tahu… Aku hanya ingin meluapkan kekesalanku.",
  ui_story_10_3_1_38_dialog_content = "…",
  ui_story_10_3_1_39_dialog_content = "Sepertinya setelah pulih dari lukamu, sekarang kau tidak terlalu murung lagi.",
  ui_story_10_3_1_40_dialog_content = "Rasanya aku harus memujimu sedikit.",
  ui_story_10_3_1_41_dialog_content = "Maksudmu apa, hah?",
  ui_story_10_3_1_42_dialog_content = "Harus kuakui, kau cukup pandai menilai orang. Sepertinya si PlayerName itu memang cukup berguna.",
  ui_story_10_3_1_43_dialog_content = "Meski undanganku gagal, tapi Caelestite itu cukup berguna untuk merangsang perkembanganmu.",
  ui_story_10_3_1_44_dialog_content = "Aku rasa kau pasti sangat senang karena terluka begini parah akibat teman lamamu dan Lumopolis.",
  ui_story_10_3_1_45_dialog_content = "Berani mengejekku sekali lagi, akan kucabut sendiri gigimu…",
  ui_story_10_3_1_46_dialog_content = "Sensitif sekali. Sebaiknya kau cepat-cepat melatih ketahanan mentalmu.",
  ui_story_10_3_1_47_dialog_content = "Maksudmu apa sih?",
  ui_story_10_3_1_48_dialog_content = "Maksudku… teman lamamu PlayerName sudah memasuki Aviduz.",
  ui_story_10_3_1_49_dialog_content = "Caelestite itu jelas ingin membunuhmu dan membalas dendam.",
  ui_story_10_3_1_50_dialog_content = "…",
  ui_story_10_3_1_51_dialog_content = "Kuberi tahu saja, aku akan mengulur waktu untukmu.",
  ui_story_10_3_1_52_dialog_content = "Aku akan cari cara untuk menahan mereka sampai energi yang kauserap sudah cukup banyak untuk menuntaskan transformasimu.",
  ui_story_10_3_1_53_dialog_content = "Tapi yang pasti, waktu kita tak banyak.",
  ui_story_10_3_1_54_dialog_content = "<color=#e8d9bb>Krauk</color>",
  ui_story_10_3_1_55_dialog_content = "Kharap kamu akhirnya bisa <color=#FFB400>melengkapi</color> dirimu.",
  ui_story_10_3_1_56_dialog_content = "Kalau bisa, jangan jadi seperti Aviduz…",
  ui_story_10_3_1_57_dialog_content = "Mencapai Lumopolis itu tidak mudah, tapi dia malah kalah padahal hanya terhantam satu kali.",
  ui_story_10_3_1_58_dialog_content = "Tutup mulutmu…",
  ui_story_10_3_1_59_dialog_content = "Aku tak perlu diingatkan.",
  ui_story_10_3_1_60_dialog_content = "Meremehkan musuhmu selalu jadi kelemahanmu…",
  ui_story_10_3_1_61_dialog_content = "…",
  ui_story_10_3_1_62_dialog_content = "Satu-satunya kelalaianku… adalah terlalu tinggi menilai pemikiran PlayerName.",
  ui_story_10_3_1_63_dialog_content = "Mengambil kesempatan, meraih kekuatan, menjadi lebih kuat…",
  ui_story_10_3_1_64_dialog_content = "Bagi pemikirannya yang kolot, itu semua tidak penting. Bahkan para Aurorian itu lebih berharga baginya!",
  ui_story_10_3_1_65_dialog_content = "Yang benar saja. Berteman dengan Aurorian dan merasa makin kuat karenanya? Menyedihkan sekali!",
  ui_story_10_3_1_66_dialog_content = "Aku sudah menunjukkan ketulusan dan kebaikanku kepadanya, tapi apa hasilnya?",
  ui_story_10_3_1_67_dialog_content = "Oh, PlayerName tak berbeda dengan Caelestite menjijikkan lainnya, tak bisa membedakan baik dan buruk.",
  ui_story_10_3_1_68_dialog_content = "Mereka semua begitu tolol.",
  ui_story_10_3_1_69_dialog_content = "Akan kubebaskan mereka dari kedunguan mereka…",
  ui_story_10_3_1_70_dialog_content = "Akan kubuat mereka menerima ganjarannya, akan kubawa mereka menuju kematian, dengan ketakutan dan penyesalan.",
  ui_story_10_3_1_71_dialog_content = "Sudah baikan? Ayo, ceritakan apa yang kaurasakan.",
  ui_story_10_3_1_72_dialog_content = "Schummer sedang memakan Eclipsite…",
  ui_story_10_3_1_73_dialog_content = "Hah? Kukira kau merasakan hal yang sangat buruk, tapi ternyata dia cuma sedang makan Eclipsite.",
  ui_story_10_3_1_74_dialog_content = "Tak usah dipikirkan, mungkin saja cederanya membuat dia ingat bahwa dia sudah beberapa hari belum makan, jadi dia makan apa saja yang ada.",
  ui_story_10_3_1_75_dialog_content = "Memangnya Eclipsite bisa dimakan? Bukankah mereka hancur berkeping-keping setelah mati?",
  ui_story_10_3_1_76_dialog_content = "Masih ada sedikit bagian yang bisa digigit sebelum mereka akhirnya hancur, tapi dari yang kudengar, rasanya lebih jijik daripada muntahan binatang sekalipun.",
  ui_story_10_3_1_77_dialog_content = "Siapa pun yang tahan memakan Eclipsite, pasti otaknya tidak beres.",
  ui_story_10_3_1_78_dialog_content = "Tapi dari yang kita tahu, Eclipsite tidak butuh makan dan tidak menunjukkan perilaku kanibal.",
  ui_story_10_3_1_79_dialog_content = "Kurasa dia menghisap energi mereka… Darkflow-nya sangat tebal di sana.",
  ui_story_10_3_1_80_dialog_content = "Dia mencoba memulihkan dirinya. Kita harus bergegas. Hoek…",
  ui_story_10_3_1_81_dialog_content = "Aduh… Mendengarkan kalian saja sudah membuatku ingin muntah.",
  ui_story_10_3_1_82_dialog_content = "Aku baik-baik saja, kurasa sudah tidak ada lagi yang bisa kumuntahkan. Hoek…",
  ui_story_10_3_1_83_dialog_content = "Iyuh, melihat gerakan mau muntahmu ikut membuatku jijik… Lihat, badanmu gemetaran!",
  ui_story_10_3_1_84_dialog_content = "Ayo…",
  ui_story_10_3_1_85_dialog_content = "Tunggu dulu, kau bahkan kesulitan berdiri! Sini, duduklah dulu sebentar!",
  ui_story_10_3_1_86_dialog_content = "Sebentar saja!",
  ui_story_10_3_1_87_dialog_content = "Aku akan baik-baik saja. Aku masih bisa membantu…",
  ui_story_10_3_1_88_dialog_content = "Sudahlah, Nak. Kalau kami menyuruhmu istirahat, menurut sajalah.",
  ui_story_10_3_1_89_dialog_content = "Kalau si Schummer ini memilih memulihkan diri dulu, berarti dia tidak bisa kabur.",
  ui_story_10_3_1_90_dialog_content = "Nih, minum air hangat ini.",
  ui_story_10_3_1_91_dialog_content = "Bagaimana kalau kau juga makan untuk memulihkan tenaga? Kami bawa beberapa makanan khas Rediesel.",
  ui_story_10_3_1_92_dialog_content = "Bopper! Kemarilah dan berikan dendeng kadalmu kepada semuanya!",
  ui_story_10_3_1_93_dialog_content = "B-baik! Karena Schummer sedang memulihkan energi, bagaimana kalau kita juga memulihkan energi kita? Nih, silakan dimakan!",
  ui_story_10_3_1_94_dialog_content = "Jangan sampai lengah.",
  ui_story_10_3_1_95_dialog_content = "Berikan aku satu bungkus, lalu aku akan pergi mengintai.",
  ui_story_10_3_1_96_dialog_content = "Baiklah. Dendeng ini juga sangat praktis, bisa dimakan langsung setelah dibuka bungkusnya! Rasanya pedas manis, dan juga bagus untuk memulihkan stamina!",
  ui_story_10_3_1_97_dialog_content = "Lihat, PlayerName. Bahkan Carleen pun mau memakannya, jadi sebaiknya kau juga memakannya.",
  ui_story_10_3_1_98_dialog_content = "Perutmu pasti kosong setelah muntah-muntah. Kau tak akan bisa bertarung dengan baik dengan perut kosong!",
  ui_story_10_3_1_99_dialog_content = "Maaf, setelah yang tadi itu, aku benar-benar tidak ingin makan. Bisa-bisa aku malah muntah lagi.",
  ui_story_10_3_1_100_dialog_content = "Eh? Baiklah… Kalau begitu, setidaknya minumlah sedikit air lagi, ya?",
  ui_story_10_3_1_101_dialog_content = "Masih ada satu botol lagi. Ambillah.",
  ui_story_10_3_1_102_dialog_content = "Ada sekerumunan Eclipsite di depan. Mereka akan segera sampai sini.",
  ui_story_10_3_1_103_dialog_content = "Tak usah pikirkan soal memberikan perintah, PlayerName.",
  ui_story_10_3_1_104_dialog_content = "Selagi kami bertarung, gunakan waktunya untuk menenangkan diri.",
  ui_story_10_3_1_105_dialog_content = "Yap! Kami tak akan membiarkan seekor Eclipsite pun mendekatimu, jadi duduk dan beristirahatlah!",
  ui_story_10_3_1_106_dialog_content = "Eclipsite muncul! Bersiaplah untuk bertarung!",
  ui_story_10_3_2_1_dialog_content = "PlayerName! Barusan kamu memberikan perintah, ya?",
  ui_story_10_3_2_2_dialog_content = "Bukankah kami sudah bilang untuk istirahat saja dan memulihkan tenagamu?",
  ui_story_10_3_2_3_dialog_content = "Aku tak apa-apa. Aku sudah merasa baikan.",
  ui_story_10_3_2_4_dialog_content = "Lagi pula, bertelepati dengan kalian jauh lebih baik daripada dengan Eclipsite.",
  ui_story_10_3_2_5_dialog_content = "Eclipsite ini… Sepertinya mereka sudah bersemangat untuk bertarung lagi, ya?",
  ui_story_10_3_2_6_dialog_content = "Ya, sepertinya kita harus menghabisi mereka sambil menerobos masuk.",
  ui_story_10_3_2_7_dialog_content = "Ayo. Aku sudah merasa baikan, sungguh.",
  ui_story_10_3_2_8_dialog_content = "Maaf ya. Seandainya aku tidak memintamu untuk mengintai dengan kekuatanmu, kamu pasti tak akan jadi cedera begini.",
  ui_story_10_3_2_9_dialog_content = "Tidak, ini bukan salahmu.",
  ui_story_10_3_2_10_dialog_content = [[
Ini karena aku tiba-tiba merasakan musuh sedang memakan Eclipsite 
sehingga aku sangat mual.]],
  ui_story_10_3_2_11_dialog_content = "Aku tak akan terpengaruh lagi.",
  ui_story_10_3_2_12_dialog_content = "Baiklah, Nak, kedengarannya kau memang sudah lebih sehat.",
  ui_story_10_3_2_13_dialog_content = "Jadi, apa tadi kau bisa merasakan keberadaan Forsakin?",
  ui_story_10_3_2_14_dialog_content = "Rasanya samar-samar, tapi tadi aku memang merasakan sesuatu…",
  ui_story_10_3_2_15_dialog_content = "Sepertinya Forsakin dan Schummer sedang berada di tempat yang sama.",
  ui_story_10_3_2_16_dialog_content = "Kalau begitu, ayo maju. Sekarang, tujuan kita semua sama.",
  ui_story_10_3_2_17_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_10_3_2_18_dialog_content = "Sepertinya makin dalam kita masuk, kondisi Colossus ini makin rusak…",
  ui_story_10_3_2_19_dialog_content = "Sepertinya Colossus ini bisa runtuh sewaktu-waktu. Seharusnya tidak ada Colossus yang rusak sampai seperti ini.",
  ui_story_10_3_2_20_dialog_content = "Yah, namanya juga kena tembak Damocles.",
  ui_story_10_3_2_21_dialog_content = "Ditambah lagi, Schummer mengisap semua energi yang tersisa darinya.",
  ui_story_10_3_2_22_dialog_content = "Colossus ini sudah <color=#FFB400>mati</color>…",
  ui_story_10_3_2_23_dialog_content = "Maksdumu, Schummer, sang Navigator dari Colossus ini…",
  ui_story_10_3_2_24_dialog_content = "Membunuh Colossus-nya sendiri dengan sengaja?",
  ui_story_10_3_2_25_dialog_content = "Eclipsite sekalipun tidak menyakiti sesamanya, tapi dia malah membunuh Colossus ini. Cuma dia yang bisa sejahat ini.",
  ui_story_10_3_2_26_dialog_content = "Aku tak akan heran kalau kau bilang dia mau menghancurkan Colossus, apalagi sekadar mengisap energinya.",
  ui_story_10_3_2_27_dialog_content = "Dia sangat busuk. PlayerName lebih tahu tentang hal itu daripada kita.",
  ui_story_10_3_2_28_dialog_content = "Ayo. Kita tak boleh membiarkan dia selesai memulihkan diri…",
  ui_story_10_7_1_1_dialog_content = "Mengisap energi dari Eclipsite lain adalah cara bagus untuk meningkatkan Darkflow.",
  ui_story_10_7_1_2_dialog_content = "Tapi hanya Eclipsite tertentu yang bisa menguasai ilmu mengisap Darkflow…",
  ui_story_10_7_1_3_dialog_content = "…",
  ui_story_10_7_1_4_dialog_content = "Oh? Sudah tertidur, sepertinya eksperimen yang ini masih bisa diharapkan.",
  ui_story_10_7_1_5_dialog_content = "Siapa yang waktu itu mendatangiku untuk berbicara soal kekuatan? Oh, aku ingat.",
  ui_story_10_7_1_6_dialog_content = "Seseorang dari Lumopolis… dengan ekor serangga… Siapa namanya ya…?",
  ui_story_10_7_1_7_dialog_content = "<color=#FFB400>Boredom</color>?",
  ui_story_10_7_1_8_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_10_7_1_9_dialog_content = "Aduh… Ada angin lagi?",
  ui_story_10_7_1_10_dialog_content = "Bukan… ini…",
  ui_story_10_7_1_11_dialog_content = "*Hiks*",
  ui_story_10_7_1_12_dialog_content = "Tangisan?",
  ui_story_10_7_1_13_dialog_content = "Apa Eclipsite juga bisa menangis?",
  ui_story_10_7_1_14_dialog_content = "Mundurlah, mereka kemari.",
  ui_story_10_7_1_15_dialog_content = "E-Eclipsite ini menyeramkan.",
  ui_story_10_7_1_16_dialog_content = "Tunggu dulu… Kok rasanya aku pernah lihat Eclipsite ini, ya?",
  ui_story_10_7_1_17_dialog_content = "Ja… jangan bilang ini juga Aurorian yang diubah menjadi Eclipsite?!",
  ui_story_10_7_1_18_dialog_content = "Penampilannya dengan tangan-tangan yang seperti akar pohon, dan suara itu… Tak salah lagi…",
  ui_story_10_7_1_19_dialog_content = "Si kakak beradik itu, <color=#FFB400>Shelt</color> dan <color=#FFB400>Shire</color>, akhirnya berubah menjadi monster itu.",
  ui_story_10_7_1_20_dialog_content = "Kakak beradik? Bukannya itu cuma satu Eclipsite?",
  ui_story_10_7_1_21_dialog_content = "Kami melihat mereka dipaksa melebur jadi satu.",
  ui_story_10_7_1_22_dialog_content = "Ya, mereka terus berkata, \"Master memberi kami kekuatan,\" lalu beginilah nasib mereka.",
  ui_story_10_7_1_23_dialog_content = "*Hiks*",
  ui_story_10_7_1_24_dialog_content = "Um, sepertinya mereka menerjang kemari, meski dengan sangat pelan… Apa kita perlu bersiap untuk melawan?",
  ui_story_10_7_1_25_dialog_content = "*Hiks* Bunuh…",
  ui_story_10_7_1_26_dialog_content = "Bunuh? Mereka bilang \"bunuh\"? Apa mereka mau membunuh kita?",
  ui_story_10_7_1_27_dialog_content = "Tidak… Mereka ingin dibebaskan.",
  ui_story_10_7_1_28_dialog_content = "<color=#FFB400>\"Bunuh kami\"</color>… Mereka pernah bilang begitu.",
  ui_story_10_7_1_29_dialog_content = "Tapi sepertinya sekarang pun mereka masih terperangkap dalam rasa sakit.",
  ui_story_10_7_1_30_dialog_content = "Mayat mereka diseret ke sini dan dihidupkan kembali agar mereka bisa dimanfaatkan lagi.",
  ui_story_10_7_1_31_dialog_content = "Memakai cara yang begitu keji berkali-kali. Yang bisa berbuat begitu hanya orang yang benar-benar gila!",
  ui_story_10_7_1_32_dialog_content = "Argh!",
  ui_story_10_7_1_33_dialog_content = "Dalam kondisi seperti itu, sudah tidak ada lagi rasa kemanusiaan atau kesadaran dalam wujud itu.",
  ui_story_10_7_1_34_dialog_content = "Habisi mereka.",
  ui_story_10_7_1_35_dialog_content = "Setelah itu, kita akan cari monster yang bertanggung jawab atas kekejaman ini dan mengirimnya ke neraka!",
  ui_story_10_7_2_1_dialog_content = "M-mereka jadi lebih tenang?",
  ui_story_10_7_2_2_dialog_content = "Ya. Mereka sudah mati, untuk kedua kalinya.",
  ui_story_10_7_2_3_dialog_content = "Vice, PlayerName, cari benda yang mudah terbakar.",
  ui_story_10_7_2_4_dialog_content = "Kita akan membakar jasad mereka.",
  ui_story_10_7_2_5_dialog_content = "Semoga dengan ini kita bisa membantu mereka beristirahat dengan tenang seperti <color=#FFB400>Gertzurde</color>.",
  ui_story_10_7_2_6_dialog_content = "Tentu. Kami akan mencarinya.",
  ui_story_10_7_2_7_dialog_content = "Gertzurde itu siapa sih?",
  ui_story_10_7_2_8_dialog_content = "Seorang kesatria dari Lumopolis, dan kekasih Shelt.",
  ui_story_10_7_2_9_dialog_content = "Dia dan Shelt bergabung dengan Eclipsite, tapi pada akhirnya…",
  ui_story_10_7_2_10_dialog_content = "Dia mengorbankan dirinya untuk menyelamatkan kami.",
  ui_story_10_7_2_11_dialog_content = "Lumopolis lagi… Mungkin ini bukan waktu atau tempat yang tepat, tapi aku harus tanya sesuatu.",
  ui_story_10_7_2_12_dialog_content = "Kenapa orang-orang Lumopolis mau bergabung dengan para Eclipsite?",
  ui_story_10_7_2_13_dialog_content = "Kalian tidak perlu khawatir diserang Eclipsite, hidup kalian juga tak begitu sulit.",
  ui_story_10_7_2_14_dialog_content = "Aneh, 'kan?",
  ui_story_10_7_2_15_dialog_content = "Sekarang kita sedang berjuang dengan tujuan yang sama, Sinsa.",
  ui_story_10_7_2_16_dialog_content = "Jadi tolong jangan ungkit-ungkit hal seperti itu.",
  ui_story_10_7_2_17_dialog_content = "Tak apa.",
  ui_story_10_7_2_18_dialog_content = "Aku hanya menyampaikan pikiranku. Lagi pula, jarang-jarang bisa bicara dengan orang dari Lumopolis.",
  ui_story_10_7_2_19_dialog_content = "Oh ya, kalau kamu tidak keberatan memakai apiku, aku juga bisa membantu kremasinya.",
  ui_story_10_7_2_20_dialog_content = "Aku akan mengurus semuanya sendiri, Sinsa. Kau tak perlu repot-repot.",
  ui_story_10_7_2_21_dialog_content = "Aku juga tak butuh bantuanmu.",
  ui_story_10_7_2_22_dialog_content = "Sebenarnya aku memang tak berencana membantu, sih. Asalkan kau tahu apa yang harus kaulakukan, itu sudah cukup untukku.",
  ui_story_10_7_2_23_dialog_content = "Aku akan berjaga.",
  ui_story_10_7_2_24_dialog_content = "…",
  ui_story_10_7_2_25_dialog_content = "Anu, aku juga akan cari benda yang bisa dibakar.",
  ui_story_10_7_2_26_dialog_content = "Sinsa terkadang memang berlebihan, dan dia selalu bicara blak-blakan…",
  ui_story_10_7_2_27_dialog_content = "Tapi dia sungguh tak berniat buruk kepadamu dan orang-orang Lumopolis.",
  ui_story_10_7_2_28_dialog_content = "Ya, aku paham.",
  ui_story_10_7_2_29_dialog_content = "Nyalakan apinya.",
  ui_story_10_7_2_30_dialog_content = "Demi White Night…",
  ui_story_10_7_2_31_dialog_content = "Dalam upaya mencari kebebasan, sang kakak beradik, Shelt dan Shire tersesat. Semoga mereka bisa beristirahat dengan tenang, dan menemukan kebebasan yang mereka dambakan.",
  ui_story_10_7_2_32_dialog_content = "Biarlah keadilan menghukum mereka yang menipu dan memanipulasi mereka berdua.",
  ui_story_10_7_2_33_dialog_content = "Biarlah pula <color=#FFB400>Schummer</color>, pelaku semua dosa keji ini, dikirimkan ke neraka.",
  ui_story_10_7_2_34_dialog_content = "Aku bisa mencoba mencari jalan yang harus kita ikuti…",
  ui_story_10_7_2_35_dialog_content = "PlayerName? Kau mau mencoba memakai kemampuan psikismu lagi?",
  ui_story_10_7_2_36_dialog_content = "Iya.",
  ui_story_10_7_2_37_dialog_content = "Jangan! Bagaimana kalau kau sampai sakit lagi?",
  ui_story_10_7_2_38_dialog_content = "Aduh.",
  ui_story_10_7_2_39_dialog_content = "PlayerName?!",
  ui_story_10_7_2_40_dialog_content = "Profesor…",
  ui_story_10_7_2_41_dialog_content = "Sebentar, yang kulihat ini apa…?",
  ui_story_10_7_2_42_dialog_content = "Aku tak apa-apa, akan kucari cara untuk mengintai. Jangan khawatir.",
  ui_story_10_7_2_43_dialog_content = "Profesor Handro…",
  ui_story_10_7_2_44_dialog_content = "Apa yang telah kauperbuat? Kenapa kau melakukannya?!",
  ui_story_10_7_2_45_dialog_content = "Kenapa kau membunuh murid yang lain?! Jawab aku!!",
  ui_story_10_7_2_46_dialog_content = "Aku tidak melakukan apa pun, profesor.",
  ui_story_10_7_2_47_dialog_content = "Aku hanya membuktikan keberanianku.",
  ui_story_10_7_2_48_dialog_content = "Kau ini kenapa?!",
  ui_story_10_7_2_49_dialog_content = "Membuktikan keberanian? Dengan membunuh teman sekelasmu?!",
  ui_story_10_7_2_50_dialog_content = "Profesor, lagi-lagi Anda hanya mendengarkan setengah kata-kata orang sebelum menilai mereka.",
  ui_story_10_7_2_51_dialog_content = "Apa?!",
  ui_story_10_7_2_52_dialog_content = "B-baiklah! Kalau begitu, jelaskan!",
  ui_story_10_7_2_53_dialog_content = "Mereka bertaruh denganku. Aku hanya mengikuti peraturannya!",
  ui_story_10_7_2_54_dialog_content = "Murid-murid bodoh ini mengira mereka sudah cukup kuat untuk melawan Eclipsite.",
  ui_story_10_7_2_55_dialog_content = "Jadi kami bertaruh untuk melihat siapa yang cukup berani pergi keluar.",
  ui_story_10_7_2_56_dialog_content = "Ini semua terjadi karena itu?",
  ui_story_10_7_2_57_dialog_content = "Kami hanya berniat melihat-lihat, Profesor. Tak ada yang mengira kami benar-benar akan bertemu Eclipsite…",
  ui_story_10_7_2_58_dialog_content = "Mereka selalu mengucilkanku! Mengejekku! Hanya karena aku tidak bisa memakai kemampuan psikisku sebaik mereka!",
  ui_story_10_7_2_59_dialog_content = "Anda selalu bilang kami tak boleh meremehkan potensi orang lain, Profesor! Tapi apa mereka mendengarkan?",
  ui_story_10_7_2_60_dialog_content = "Tidak! Mereka tidak mendengarkan!",
  ui_story_10_7_2_61_dialog_content = "Tapi pada akhirnya aku bisa membuktikan kemampuanku! Akulah satu-satunya orang yang selamat!",
  ui_story_10_7_2_62_dialog_content = "Itu berarti akulah yang paling kuat!",
  ui_story_10_7_2_63_dialog_content = "*Menghela napas*",
  ui_story_10_7_2_64_dialog_content = "Kau selamat hanya karena kau beruntung, Schummer!",
  ui_story_10_7_2_65_dialog_content = "Aku sudah bilang padamu berkali-kali…",
  ui_story_10_7_2_66_dialog_content = "Kita, kaum Caelestite, adalah bangsa yang lembut dan cinta damai, dan akan selalu begitu.",
  ui_story_10_7_2_67_dialog_content = "Karena itu, kita tidak perlu membuktikan kemampuan kita kepada siapa pun.",
  ui_story_10_7_2_68_dialog_content = "Yang penting dari kekuatan adalah bukan siapa yang lebih kuat, tapi bagaimana kita bisa saling membantu menghadapi bahaya dan kejamnya dunia.",
  ui_story_10_7_2_69_dialog_content = "Menghadapi bahaya? Profesor, Anda benar-benar berpikir bahwa bersembunyi di Eraveil dan tidak berani pergi itu bisa dianggap \"menghadapi bahaya\"?",
  ui_story_10_7_2_70_dialog_content = "Lagi-lagi kau salah mengartikan kata-kataku. Sudah berkali-kali aku memperingatkanmu…",
  ui_story_10_7_2_71_dialog_content = "Ada begitu banyak Eclipsite berkeliaran di dunia di luar Eraveil.",
  ui_story_10_7_2_72_dialog_content = "Kita berbeda dengan Aurorian. Kita tidak bisa menggunakan kekuatan Lumina untuk bertarung atau melindungi diri.",
  ui_story_10_7_2_73_dialog_content = "Tanpa kemampuan untuk melindungi diri, bertemu dengan Eclipsite yang kekuatannya biasa-biasa saja sama artinya kita pasti mati.",
  ui_story_10_7_2_74_dialog_content = "Untungnya, kita punya Eraveil dan Colossus.",
  ui_story_10_7_2_75_dialog_content = "Eraveil melindungi kita, dan Colossus bisa membawa kita terbang tinggi di atas tanah, dan jauh dari serangan Eclipsite.",
  ui_story_10_7_2_76_dialog_content = [[
Tapi yang paling penting, kita memiliki <color=#FFB400>kemampuan psikis</color>, 
kekuatan yang hanya dimiliki bangsa kita.]],
  ui_story_10_7_2_77_dialog_content = "Dengannya, kita bisa merasakan Light Trail, memahami perasaan orang lain, dan mendeteksi musuh dan bahaya lain.",
  ui_story_10_7_2_78_dialog_content = "Tapi tanpa keahlian dan pengalaman yang cukup, kau tak akan bisa menggunakan kemampuan psikismu untuk mendeteksi dan menyelamatkan diri dari bahaya.",
  ui_story_10_7_2_79_dialog_content = "Keluar dari Eraveil begitu saja seperti kalian sama artinya dengan bunuh diri!",
  ui_story_10_7_2_80_dialog_content = "Mendeteksi, lalu kabur, semua orang di sini sama saja!",
  ui_story_10_7_2_81_dialog_content = "Apa kalian tidak pernah berpikir apa yang harus dilakukan kalau Eclipsite tiba-tiba muncul di sini?!",
  ui_story_10_7_2_82_dialog_content = "Anda benar-benar percaya Eraveil bisa melindungi kita selamanya?!",
  ui_story_10_7_2_83_dialog_content = "Beri tahu aku, apa yang harus kita lakukan? Naik ke Colossus dan terbang? Memangnya kita bisa ke mana?",
  ui_story_10_7_2_84_dialog_content = "Pergi ke dunia luar yang luas dan berbahaya, di mana kita bisa mati kapan saja?",
  ui_story_10_7_2_85_dialog_content = "Siapa yang bilang kita bisa mati kapan saja di luar sana?!",
  ui_story_10_7_2_86_dialog_content = "Bukankah aku sudah bilang berkali-kali? Selama kita punya Colossus…",
  ui_story_10_7_2_87_dialog_content = "Cukup, aku sudah tahu Anda akan bilang apa.",
  ui_story_10_7_2_88_dialog_content = "Profesor, alasan sebenarnya yang membuat kita jadi bangsa yang lembut dan cinta damai adalah karena kita tidak punya kekuatan untuk bertarung sendiri.",
  ui_story_10_7_2_89_dialog_content = "*Menghela napas* Masih keras kepala juga, ya. Aku tak bisa menyalahkanmu, Schummer.",
  ui_story_10_7_2_90_dialog_content = "Suatu saat, kau akan paham…",
  ui_story_10_7_2_91_dialog_content = "Aku tak paham. Dan kurasa aku tak akan pernah paham…",
  ui_story_10_7_2_92_dialog_content = "Pergilah sekarang, Profesor.",
  ui_story_10_7_2_93_dialog_content = "Anda tak akan bisa membuatku menyesali apa yang telah terjadi.",
  ui_story_10_7_2_94_dialog_content = "Sepertinya kamu masih butuh waktu untuk menenangkan diri.",
  ui_story_10_7_2_95_dialog_content = "Para tetua sudah mengatur penyelidikan tentang kejadian ini.",
  ui_story_10_7_2_96_dialog_content = "Aku percaya bahwa kau tidak berniat membuat teman-teman sekelasmu mati…",
  ui_story_10_7_2_97_dialog_content = [[
Namun, sampai para tetua menentukan hukumanmu, aku tidak punya pilihan 
selain mengurungmu di sini.]],
  ui_story_10_7_2_98_dialog_content = "Lalu, salah satu temanmu membawakan buku ini. Dia memintaku memberikannya kepadamu.",
  ui_story_10_7_2_99_dialog_content = "Teman? Siapa? Aku tak punya teman…",
  ui_story_10_7_2_100_dialog_content = "Ini dari <color=#FFB400>Mendelson</color>. Dia mengkhawatirkanmu. Nilai-nilainya dulu juga jelek sepertimu.",
  ui_story_10_7_2_101_dialog_content = "Kurasa dia bisa memahami situasimu dan ingin berteman denganmu.",
  ui_story_10_7_2_102_dialog_content = "Dia mengkhawatirkanku?",
  ui_story_10_7_2_103_dialog_content = "Schummer… Aku berdoa dengan segenap hati agar suatu hari nanti kau sadar bahwa semua orang menyayangimu.",
  ui_story_10_7_2_104_dialog_content = "Selama kau dikurung dan berpuasa, tolong renungkan baik-baik apa yang telah terjadi. Semua orang mengharapkan yang terbaik darimu, jangan kecewakan mereka.",
  ui_story_10_7_2_105_dialog_content = "…",
  ui_story_10_7_2_106_dialog_content = "Menyadari bahwa <color=#FFB400>semua orang menyayangiku</color>?",
  ui_story_10_7_2_107_dialog_content = "Mereka selalu memakai alasan itu untuk menyiksaku. Menyebalkan sekali…",
  ui_story_10_7_2_108_dialog_content = "…",
  ui_story_10_7_2_109_dialog_content = "Buku, ya?",
  ui_story_10_7_2_110_dialog_content = "<color=#FFB400>Ada dan sang Colossus</color>?!",
  ui_story_10_7_2_111_dialog_content = "Lelucon macam apa ini?! Apa mereka mengejekku karena mereka tahu aku tidak bisa bertelepati dengan Colossus?",
  ui_story_10_7_2_112_dialog_content = "…",
  ui_story_10_7_2_113_dialog_content = "Mendelson…",
  ui_story_10_7_2_114_dialog_content = "Oh, si cowok yang rambutnya lebih merah dariku, dan juga tampak lebih lemah dariku.",
  ui_story_10_7_2_115_dialog_content = "Dia pasti juga tidak bisa bertelepati dengan Colossus.",
  ui_story_10_7_2_116_dialog_content = "<color=#e8d9bb>Cring</color>",
  ui_story_10_7_2_117_dialog_content = "Apa ini?",
  ui_story_10_7_2_118_dialog_content = "<color=#FFB400>Kunci</color>?!",
  ui_story_10_7_2_119_dialog_content = "Ck, pintu ini. Kalau aku mau, bisa saja aku mendobraknya sekarang juga…",
  ui_story_10_8_1_1_dialog_content = "Setelah meningkatkan Darkflow dari Seed.",
  ui_story_10_8_1_2_dialog_content = "Darkflow akan membuat mereka merasa lebih nyaman.",
  ui_story_10_8_1_3_dialog_content = "Sekaligus secara perlahan mengikis kemampuan berpikir mereka.",
  ui_story_10_8_1_4_dialog_content = "Umumnya, subjek percobaan yang menerima Darkflow akan lebih mudah menunjukkan hasrat terbesar mereka.",
  ui_story_10_8_1_5_dialog_content = "Pada titik ini, hal yang paling memengaruhi kehendak bebas mereka adalah keterikatan mereka dengan hal-hal tertentu…",
  ui_story_10_8_1_6_dialog_content = "Jangan terburu-buru! Dengan berlatih, kemampuan psikismu bisa ditingkatkan, perlahan tapi pasti.",
  ui_story_10_8_1_7_dialog_content = "Aviduz adalah Colossus istimewa. Biasanya butuh waktu lebih lama sebelum muncul Navigator yang sesuai.",
  ui_story_10_8_1_8_dialog_content = "Asalkan kau terus belajar dan jadi makin kuat, mungkin suatu hari nanti kau akan…",
  ui_story_10_8_1_9_dialog_content = "Aviduz… Di mana kamu…",
  ui_story_10_8_1_10_dialog_content = "Colossus…",
  ui_story_10_8_1_11_dialog_content = "Colossus…",
  ui_story_10_8_1_12_dialog_content = "Colossus biasa…",
  ui_story_10_8_1_13_dialog_content = "Bukan, bukan yang ini…",
  ui_story_10_8_1_14_dialog_content = "Bukan yang ini juga…",
  ui_story_10_8_1_15_dialog_content = "Aku harus bagaimana lagi?",
  ui_story_10_8_1_16_dialog_content = "Hancurkan semua inti daya mereka, tapi biarkan satu utuh.",
  ui_story_10_8_1_17_dialog_content = "Itu perintah.",
  ui_story_10_8_1_18_dialog_content = "Hancurkan inti daya mereka…",
  ui_story_10_8_1_19_dialog_content = "Hancurkan semua inti daya para Colossus, kecuali Aviduz…",
  ui_story_10_8_1_20_dialog_content = "Ketemu…",
  ui_story_10_8_1_21_dialog_content = "Kalau kuhancurkan Echo Template-mu, kau akan mematuhiku, 'kan?",
  ui_story_10_8_1_22_dialog_content = "<color=#e8d9bb>Kondisi mesin normal. Diaktifkan…</color>",
  ui_story_10_8_1_23_dialog_content = "Hitam mengkilap, kuat, istimewa…",
  ui_story_10_8_1_24_dialog_content = "<color=#e8d9bb>16%… 33%…</color>",
  ui_story_10_8_1_25_dialog_content = "<color=#FFB400>Aviduz-ku.</color>",
  ui_story_10_8_1_26_dialog_content = "<color=#e8d9bb>100%. Berhasil diaktifkan.</color>",
  ui_story_10_8_1_27_dialog_content = "Sudah kuduga akan berhasil!",
  ui_story_10_8_1_28_dialog_content = "Selama aku memilikimu, Aviduz…",
  ui_story_10_8_1_29_dialog_content = "SCHUMMER!",
  ui_story_10_8_1_30_dialog_content = "?!",
  ui_story_10_8_1_31_dialog_content = "Itukah suaramu?!",
  ui_story_10_8_1_32_dialog_content = "Apa itu cara yang pantas… untuk menjawab atasanmu?!",
  ui_story_10_8_1_33_dialog_content = "Seharusnya kamu menjawab, \"Ya, Master Figerald! Hamba menunggu perintah Anda!\"",
  ui_story_10_8_1_34_dialog_content = "Ya… <color=#FFB400>M-Master Figerald</color>…",
  ui_story_10_8_1_35_dialog_content = "Mengulang kata-kataku saja tidak becus, dasar bodoh.",
  ui_story_10_8_1_36_dialog_content = "Ck, ck, ck, tapi aku tak boleh membandingkanmu dengan yang lain, jadi tidak apa-apa.",
  ui_story_10_8_1_37_dialog_content = "Saat ini kamu punya nilai berharga bagi kami..",
  ui_story_10_8_1_38_dialog_content = "Kamu baru saja berubah menjadi Eclipsite, belum paham apa yang terjadi.",
  ui_story_10_8_1_39_dialog_content = "Inilah cara Eclipsite biasanya berkomunikasi, berkat kekuatan yang diberikan oleh sang Bunda.",
  ui_story_10_8_1_40_dialog_content = "Meskipun kita ada di tempat yang berjauhan, aku masih bisa mengirimkan suaraku kepadamu…",
  ui_story_10_8_1_41_dialog_content = "Kekuatan dari sang Bunda?",
  ui_story_10_8_1_42_dialog_content = "Jangan lupa, aku memilihmu dan memberimu kekuatan dan kesempatan baru atas kehendak sang Bunda.",
  ui_story_10_8_1_43_dialog_content = "Kau bisa begitu cepat beradaptasi dengan Seed dan menjadi sekuat itu. Itu adalah bukti bahwa penilaian sang Bunda selalu benar.",
  ui_story_10_8_1_44_dialog_content = "Tapi, dalam kondisimu sekarang, kamu belum berhak tahu lebih banyak.",
  ui_story_10_8_1_45_dialog_content = "Hanya dengan menjadi lebih kuat dan menunjukkan kesetiaanmu, barulah kamu berhak mendengarkan ajaran dari Mother.",
  ui_story_10_8_1_46_dialog_content = "Nah, katakan, apakah kau sudah menyelesaikan tugas yang kuberikan?",
  ui_story_10_8_1_47_dialog_content = "Sudah selesai.",
  ui_story_10_8_1_48_dialog_content = "Bagus. Sekarang arahkan Colossus-mu ke sisiku.",
  ui_story_10_8_1_49_dialog_content = "Pasukan Eclipsite telah memasuki Eraveil sesuai rencana. Inilah akhir nasib mereka.",
  ui_story_10_8_1_50_dialog_content = "Tapi waktumu tidak banyak lagi. Jangan lupa, kau punya tugas sebagai utusan.",
  ui_story_10_8_1_51_dialog_content = "Em… Utusan?",
  ui_story_10_8_1_S1_dialog_content = "Ya. Kamu harus membawaku menemui Caelestite yang menurutmu layak menerima kekuatan kita.",
  ui_story_10_8_1_52_dialog_content = "Aku akan memberi mereka kesempatan untuk <color=#FFB400>diselamatkan</color>.",
  ui_story_10_8_1_S2_dialog_content = "Hmm…",
  ui_story_10_8_1_S3_dialog_content = "Schummer… Kenapa kau ragu?",
  ui_story_10_8_1_S4_dialog_content = "Aku tiba-tiba… merasa… sangat gatal…",
  ui_story_10_8_1_S5_dialog_content = "Gatal?",
  ui_story_10_8_1_S6_dialog_content = [[
Ck, ck, ck! Kau mulai merasa aneh, ya? 
Apa ada keanehan lain yang perlu kuketahui?]],
  ui_story_10_8_1_S7_dialog_content = "Keanehan lain…",
  ui_story_10_8_1_S8_dialog_content = "Aku tak bisa membuka mataku. Cahaya di luar terlalu silau…",
  ui_story_10_8_1_S9_dialog_content = "Ya… Luar biasa, kamu bisa membuat Seed di dalammu berubah begitu cepat!",
  ui_story_10_8_1_S10_dialog_content = "Aku merasakan Darkflow di dalam dirimu sudah matang.",
  ui_story_10_8_1_S11_dialog_content = "Mestinya cara pandangmu sekarang sudah jadi sepenuhnya baru. Ikutlah bersama kami ke Eraveil.",
  ui_story_10_8_1_S12_dialog_content = "Cara pandang yang sepenuhnya baru…",
  ui_story_10_8_1_S13_dialog_content = "Ya. Kau sudah melebihi para Caelestite. Lagi pula, darah Caelestite rendahan tidak cocok denganmu.",
  ui_story_10_8_1_S14_dialog_content = "Tapi… Aku terlahir seperti ini…",
  ui_story_10_8_1_S15_dialog_content = "Tapi kau bisa membuangnya, sama seperti kau bisa membuang takdirmu sebagai Caelestite yang selamanya lemah, yang ditakdirkan untuk hancur…",
  ui_story_10_8_1_S16_dialog_content = "Membuangnya… Apa yang harus kulakukan?",
  ui_story_10_8_1_S17_dialog_content = "Apa yang harus kaulakukan? Ck, ck, ck…",
  ui_story_10_8_1_S18_dialog_content = "Kau harus menginginkan kekuatan! Setelah itu, barulah kekuatan di dalam dirimu akan memberitahumu apa yang harus kaulakukan!",
  ui_story_10_8_1_S19_dialog_content = "…",
  ui_story_10_8_1_S20_dialog_content = "Menginginkan… kekuatan…",
  ui_story_10_8_1_S21_dialog_content = "Keinginan untuk bebas dari kelemahan…",
  ui_story_10_8_1_S22_dialog_content = "Menginginkan perubahan…",
  ui_story_10_8_1_S23_dialog_content = "Tidak… Aku tak sama seperti mereka.",
  ui_story_10_8_1_S24_dialog_content = "Sekarang aku memiliki semuanya!",
  ui_story_10_8_1_53_dialog_content = "Lihat ke sana! Cepatlah!",
  ui_story_10_8_1_54_dialog_content = "Bawa senjata! Bawa senjata!!",
  ui_story_10_8_1_55_dialog_content = "Ribut-ribut apa ini?",
  ui_story_10_8_1_56_dialog_content = "Apa yang terjadi?",
  ui_story_10_8_1_57_dialog_content = "Rupanya kau bersembunyi di sini…",
  ui_story_10_8_1_58_dialog_content = "S-siapa kamu?!",
  ui_story_10_8_1_59_dialog_content = "Hah! Ini aku—Schummer! Kau tak percaya apa yang kaulihat, 'kan?",
  ui_story_10_8_1_60_dialog_content = "Schummer? Tidak… Tandukmu, dan rambutmu… Kau sangat berbeda!",
  ui_story_10_8_1_61_dialog_content = "Jangan ragukan aku, dan jangan takut. Ini semua bukti bahwa aku adalah utusan yang terpilih.",
  ui_story_10_8_1_62_dialog_content = "Aku terpilih, dan telah menerima kekuatan jauh di atas para Caelestite.",
  ui_story_10_8_1_63_dialog_content = "U-utusan? Kekuatan? Apa maksudmu?!",
  ui_story_10_8_1_64_dialog_content = "…",
  ui_story_10_8_1_65_dialog_content = "Sudah kuduga kau tak akan paham! Ingat saja ini—Aku jauh lebih kuat daripada semua Caelestite!",
  ui_story_10_8_1_66_dialog_content = "Sekarang jawab aku, kenapa kau membantuku? Kenapa kau menaruh kunci itu di buku yang kauberikan kepadaku?",
  ui_story_10_8_1_67_dialog_content = "M-mereka bilang mereka a-akan me-mengurungmu sampai kau m-mati…",
  ui_story_10_8_1_68_dialog_content = "Mereka juga bilang kalau aku melaporkannya kepada profesor, a-aku juga akan dikurung…",
  ui_story_10_8_1_69_dialog_content = "Tapi kita ini saudara! Saudara seharusnya tidak…",
  ui_story_10_8_1_70_dialog_content = "Oh, simpati yang membosankan.",
  ui_story_10_8_1_71_dialog_content = "Jadi intinya, kau sekadar bersimpati dengan keadaanku?",
  ui_story_10_8_1_72_dialog_content = "Saat mereka melihatku dikurung, mereka seenaknya bicara omong kosong, menyebalkan.",
  ui_story_10_8_1_73_dialog_content = "A-aku tidak paham. Apa yang sebenarnya terjadi? Bukankah mereka merundungimu?",
  ui_story_10_8_1_74_dialog_content = "Murid-murid keluar dari Eraveil tanpa izin dan terbunuh oleh Eclipsite… Para tetua tak akan berani mengatakan apa pun.",
  ui_story_10_8_1_75_dialog_content = "Mereka takut… kalau semua orang akan tahu bahwa hari akhir akan tiba, tak seorang pun akan menuruti peraturan konyol mereka.",
  ui_story_10_8_1_76_dialog_content = "Dengarkan baik-baik, jangan salah paham. Aku tidak pernah berniat menerima buku ataupun kunci di dalamnya itu.",
  ui_story_10_8_1_77_dialog_content = "Tapi aku tidak sepenuhnya tak punya hati. Karena kau pernah membantuku, aku bersedia memberimu kesempatan untuk tetap hidup.",
  ui_story_10_8_1_78_dialog_content = "Begitu pula kesempatan untuk mendapat kekuatan luar biasa. Mulai sekarang…",
  ui_story_10_8_1_79_dialog_content = "A-apa maksudmu… Kesempatan seperti apa?",
  ui_story_10_8_1_80_dialog_content = "Masih belum paham juga, ya?",
  ui_story_10_8_1_81_dialog_content = "Akhir Eraveil telah tiba, dan para Eclipsite akan membawa hukuman bagi dunia.",
  ui_story_10_8_1_82_dialog_content = "Semuanya akan mati…",
  ui_story_10_8_1_83_dialog_content = "Maka jadilah Eclipsite sepertiku!",
  ui_story_10_8_1_84_dialog_content = "Tidak, tidak… A-aku…",
  ui_story_10_8_1_85_dialog_content = "Dia orangnya?",
  ui_story_10_8_1_86_dialog_content = "Aku sibuk, cepat selesaikan…",
  ui_story_10_8_1_87_dialog_content = "!!!",
  ui_story_10_8_1_88_dialog_content = "Kalau kau menolak, kau akan mati.",
  ui_story_10_8_1_89_dialog_content = "Katakan dengan jelas, kau mau hidup, atau mati?",
  ui_story_10_8_1_90_dialog_content = "Aku…",
  ui_story_10_8_1_91_dialog_content = "Uh…",
  ui_story_10_8_1_92_dialog_content = "Satu Eclipsite saja sudah bisa membuat kita kewalahan…",
  ui_story_10_8_1_93_dialog_content = "Handro! Eclipsite juga terlihat di sisi timur!",
  ui_story_10_8_1_94_dialog_content = "Kalian semua pergi duluan! Aku akan segera menyusul!",
  ui_story_10_8_1_95_dialog_content = "Profesor! Aku kembali!",
  ui_story_10_8_1_96_dialog_content = "Ikutlah denganku!",
  ui_story_10_8_1_97_dialog_content = "Kau?!",
  ui_story_10_8_1_98_dialog_content = "Schummer?!",
  ui_story_10_8_1_99_dialog_content = "Jangan takut, Profesor.",
  ui_story_10_8_1_100_dialog_content = [[
Para tetua tidak pernah memberi tahu bahwa Eraveil ditakdirkan 
untuk dihancurkan oleh para Eclipsite. Karena itulah semuanya panik seperti ini.]],
  ui_story_10_8_1_101_dialog_content = "Kau ini bicara apa?",
  ui_story_10_8_1_102_dialog_content = "Hari akhir Eraveil sudah ditentukan sejak dahulu.",
  ui_story_10_8_1_103_dialog_content = "Dunia sudah membuat keputusan, dan keputusannya adalah untuk berevolusi.",
  ui_story_10_8_1_104_dialog_content = "Eclipsite tak akan menyakiti siapa pun yang tak seharusnya mereka sakiti. Asalkan kau memang pantas…",
  ui_story_10_8_1_105_dialog_content = "Kau bisa selamat dari penghakiman mereka!",
  ui_story_10_8_1_106_dialog_content = "Aku telah menjadi utusan dari para Eclipsite. Aku merekomendasikanmu kepada mereka juga!",
  ui_story_10_8_1_107_dialog_content = "Tangkap dia! Cepat ikat dia!",
  ui_story_10_8_1_108_dialog_content = "Cepat! Ayo, semuanya!",
  ui_story_10_8_1_109_dialog_content = "…?",
  ui_story_10_8_1_110_dialog_content = "Buka pintu ke ruang tersembunyi! Cepat!",
  ui_story_10_8_1_111_dialog_content = "Kurung dia. Bawa Schummer dan kunci dia di sana.",
  ui_story_10_8_1_112_dialog_content = "…",
  ui_story_10_8_1_113_dialog_content = "Jadi itu jawabanmu?",
  ui_story_10_8_1_114_dialog_content = "Sungguh pengecut…",
  ui_story_10_8_1_115_dialog_content = "Tapi tak masalah…",
  ui_story_10_8_1_116_dialog_content = "Kalian akan segera menyesalinya.",
  ui_story_10_8_1_117_dialog_content = "Saat mereka tiba, kalian semua akan menyesalinya! Kemudian, kalian akan memohon kepadaku…",
  ui_story_10_8_1_118_dialog_content = "Memohon untuk diberi kesempatan kedua.",
  ui_story_10_8_1_119_dialog_content = "Ah!",
  ui_story_10_8_1_120_dialog_content = "Lari! Lewat sana, cepat!",
  ui_story_10_8_1_121_dialog_content = "Apa masih ada Colossus yang bisa bergerak?",
  ui_story_10_8_1_122_dialog_content = "Bagi yang bisa merasakan keberadaan musuh, cari cara untuk kabur! Bawa anak-anak bersamamu!",
  ui_story_10_8_1_123_dialog_content = "Tidak mungkin, jumlah Eclipsite itu terlalu banyak…",
  ui_story_10_8_1_124_dialog_content = "Ahh… suaranya indah sekali.",
  ui_story_10_8_1_125_dialog_content = "Terakhir kali adalah waktu kita memusnahkan para Demi-Human, yang tak ada bedanya dengan binatang biasa…",
  ui_story_10_8_1_126_dialog_content = "Sudah lama sekali aku tidak mendengar suara penderitaan yang begitu mengoyak hati.",
  ui_story_10_8_1_127_dialog_content = "Suara para Caelestite ini tidak sekencang Demi-Human, tapi jeritan melengking mereka juga cukup menghibur.",
  ui_story_10_8_1_128_dialog_content = "Memang sudah sepantasnya bangsa yang menyukai musik akan bertingkah seperti ini. Ck, ck, ck.",
  ui_story_10_8_1_129_dialog_content = "Grrr…",
  ui_story_10_8_1_130_dialog_content = "Maju! Buat mereka menjerit lagi untukku! Habisi mereka semua!",
  ui_story_10_8_1_131_dialog_content = "Aahhhh!",
  ui_story_10_8_1_132_dialog_content = "Keluarkan semua Colossus yang masih bisa bergerak!",
  ui_story_10_8_1_133_dialog_content = "Cepat! Bantu orang-orang yang masih hidup!",
  ui_story_10_8_1_134_dialog_content = "*Batuk-batuk*",
  ui_story_10_8_1_135_dialog_content = "*Batuk-batuk*",
  ui_story_10_8_1_136_dialog_content = "Masih ada yang hidup. Untunglah…",
  ui_story_10_8_1_137_dialog_content = "Profesor! Profesor!",
  ui_story_10_8_1_138_dialog_content = "Mendelson, kau masih hidup. Ayo, kita harus pergi.",
  ui_story_10_8_1_139_dialog_content = "Profesor, semuanya mati…",
  ui_story_10_8_1_140_dialog_content = "Apa kita bisa pergi, profesor? Apa kita benar-benar bisa menyelamatkan diri?",
  ui_story_10_8_1_141_dialog_content = "Tentu saja kita bisa menyelamatkan diri. *Uhuk* Ikuti aku…",
  ui_story_10_8_1_142_dialog_content = "Lewat sini, cepat… <color=#FFB400>Mantiz</color> menunggu di dekat sini…",
  ui_story_10_8_1_143_dialog_content = "…",
  ui_story_10_8_1_144_dialog_content = "Profesor?",
  ui_story_10_8_1_145_dialog_content = "Dengarkan aku, Mendelson. Aku bisa merasakan bahwa semua orang sudah dihabisi…",
  ui_story_10_8_1_146_dialog_content = "Aku akan mengalihkan perhatian Eclipsite di sekitar kita dan membuat mereka menjauh. Itu kesempatanmu untuk naik ke Mantiz dan mengaktifkannya.",
  ui_story_10_8_1_147_dialog_content = "Di dalam Mantiz, ada ruang khusus. Setelah kau kabur dari Eraveil, kau harus menemukan ruang khusus itu.",
  ui_story_10_8_1_148_dialog_content = "Di dalamnya, ada sebuah <color=#FFB400>modul khusus</color>. Modul itu…",
  ui_story_10_8_1_149_dialog_content = "Bisa mengubah total fungsi kognitif Colossus.",
  ui_story_10_8_1_150_dialog_content = "Kalau sampai benda itu jatuh ke tangan yang salah, bisa celaka jadinya.",
  ui_story_10_8_1_151_dialog_content = "Satu-satunya orang yang bisa memiloti Mantiz sudah mati. Hanya kamu yang tersisa.",
  ui_story_10_8_1_152_dialog_content = "T-tapi aku tidak bisa. Aku belum pernah berhasil bertelepati dengan Colossus.",
  ui_story_10_8_1_153_dialog_content = "Aku percaya kepadamu, Mendelson. Kau memiliki banyak potensi, kamu hanya perlu merasa percaya diri.",
  ui_story_10_8_1_154_dialog_content = [[
Sebelumnya, kami menyadari bahwa kamu cocok untuk memiloti Mantiz 
dan berencana untuk menjadikanmu Navigator berikutnya.]],
  ui_story_10_8_1_155_dialog_content = "Tapi, Profesor, Anda bisa bertelepati dengan Colossus. Bukankah lebih baik kalau kita pergi bersama?",
  ui_story_10_8_1_156_dialog_content = "Aku tidak bisa pergi denganmu, Mendelson. <color=#FFB400>Liebowitz</color> masih menungguku.",
  ui_story_10_8_1_157_dialog_content = "Aku percaya kepadamu. Aku tahu kau pasti bisa mengaktifkannya.",
  ui_story_10_8_1_158_dialog_content = "Ada dua penjaga di dalam Mantiz, <color=#FFB400>Philex</color> dan <color=#FFB400>Vani</color>. \nMereka akan membantu dan menemanimu…",
  ui_story_10_8_1_159_dialog_content = "Aku… Tapi, Profesor… Aku tidak bisa melakukannya sendirian! Aku tidak pernah bisa bertelepati dengan…",
  ui_story_10_8_1_160_dialog_content = "Aku tahu kau bisa melakukannya dengan baik. Ini bukan saatnya meragukan dirimu!",
  ui_story_10_8_1_161_dialog_content = "Tapi Eclipsite itu, mereka ada di mana-mana! Lalu juga ada satu yang kelihatan sangat berbahaya…",
  ui_story_10_8_1_162_dialog_content = "Kalaupun aku bisa mengaktifkan Colossus-nya, aku tak akan bisa kabur…",
  ui_story_10_8_1_163_dialog_content = "Kalau begini, kita akan mati, kita semua akan mati.",
  ui_story_10_8_1_164_dialog_content = "Profesor, Schummer bilang dia punya cara agar kita bisa selamat…",
  ui_story_10_8_1_165_dialog_content = "Apa?! Dia juga mendatangimu?",
  ui_story_10_8_1_166_dialog_content = "Mungkin ada cara lain agar kita bisa bertahan hidup?",
  ui_story_10_8_1_167_dialog_content = "Cara untuk selamat dari hari penghakiman.",
  ui_story_10_8_1_168_dialog_content = "Belum juga puas, Schummer?",
  ui_story_10_8_1_169_dialog_content = "Master Figerald, tidak ada lagi yang bisa kupilih.",
  ui_story_10_8_1_170_dialog_content = "Sayang sekali, tapi aku sudah lama menunggu.",
  ui_story_10_8_1_171_dialog_content = "Mereka tak akan mendapat kesempatan lagi untuk tetap hidup.",
  ui_story_10_8_1_172_dialog_content = "Ck! Ck! Ck! Kalau begitu, mari lihat kemegahan hari penghakiman mereka!",
  ui_story_10_8_1_173_dialog_content = "Eclipse akan segera terjadi!",
  ui_story_10_9_1_1_dialog_content = "PlayerName?!",
  ui_story_10_9_1_2_dialog_content = "Hari penghakiman, dan <color=#FFB400>Eclipse</color>…",
  ui_story_10_9_1_3_dialog_content = "Hari akhir? Apa maksudnya? Sadarlah, dan ceritakan apa yang kaulihat.",
  ui_story_10_9_1_4_dialog_content = "Aku pernah melihatnya, kehancuran Eraveil…",
  ui_story_10_9_1_5_dialog_content = "Semuanya nyata.",
  ui_story_10_9_1_6_dialog_content = "Aku baru saja melihat ingatan Schummer tentang Eraveil. Hari saat tempat ini diserang Eclipsite.",
  ui_story_10_9_1_7_dialog_content = "Schummer membawa para Eclipsite ke Eraveil…",
  ui_story_10_9_1_8_dialog_content = "Langit menjadi gelap, lalu terjadi Eclipse…",
  ui_story_10_9_1_9_dialog_content = "Tapi yang paling penting, ada Eclipsite berwujud manusia bernama <color=#FFB400>Figerald</color>.",
  ui_story_10_9_1_10_dialog_content = "Eclipsite itulah yang memimpin penyerangan yang menghancurkan seluruh Eraveil itu!",
  ui_story_10_9_1_11_dialog_content = "Apa kau baik-baik saja?",
  ui_story_10_9_1_12_dialog_content = "Aku baik-baik saja. Ada kerumunan besar Eclipsite mendekat dari depan. Kita harus bersiap bertempur.",
  ui_story_10_9_1_13_dialog_content = "Kau bisa merasakan serangan Eclipsite di tempat sesenyap ini?",
  ui_story_10_9_1_14_dialog_content = "Aku mendengar sesuatu! Para Eclipsite kemari!",
  ui_story_10_9_1_15_dialog_content = "Ha, kukira barusan kamu kehilangan akal.",
  ui_story_10_9_1_16_dialog_content = "Menurutku, kondisimu tak memungkinkan untuk memperkirakan kondisi di medan tempur.",
  ui_story_10_9_1_17_dialog_content = "Tapi asal tahu saja, jangan sepenuhnya berfokus untuk balas dendam.",
  ui_story_10_9_1_18_dialog_content = [[
Jangan gegabah begitu kau melihat orang yang kau incar. 
Tenanglah dan berikan perintah seperti biasanya, dan kita akan baik-baik saja.]],
  ui_story_10_9_1_19_dialog_content = "Baik. Terima kasih, Sinsa.",
  ui_story_10_9_1_20_dialog_content = "Akan kuhadapi dia dengan tenang… dan mengakhiri semua ini.",
  ui_story_10_13_1_1_dialog_content = "Menjadi Eclipsite bukan berarti pasti akan punya kekuatan untuk mengendalikannya.",
  ui_story_10_13_1_2_dialog_content = "Selalu ada kemungkinan Darkflow akan menggerogotimu, dan menyebabkanmu kehilangan kendali.",
  ui_story_10_13_1_3_dialog_content = "Bahkan orang seperti Schummer sekalipun, yang sangat haus akan kekuatan, hanya bisa mendapatkan kekuatan sampai batas tertentu.",
  ui_story_10_13_1_4_dialog_content = "Kalau terus seperti ini… aku tak perlu mencatat satu pun hasil eksperimen ini.",
  ui_story_10_13_1_5_dialog_content = "(Eclipsian) Nyonya! Apa yang harus kita lakukan sekarang?",
  ui_story_10_13_1_6_dialog_content = "(Eclipsian) Orang-orang Aurorian akan segera menghubungi kita di sini.",
  ui_story_10_13_1_7_dialog_content = "Sepertinya aku tidak bisa mengandalkan Schummer untuk maju sendiri.",
  ui_story_10_13_1_8_dialog_content = "Aku harus memberikan dorongan untuknya.",
  ui_story_10_13_1_9_dialog_content = "Terus awasi pergerakan para Aurorian.",
  ui_story_10_13_1_10_dialog_content = "(Bahasa Eclipsian) Baik.",
  ui_story_10_13_1_11_dialog_content = "Schummer.",
  ui_story_10_13_1_12_dialog_content = "Tenanglah…",
  ui_story_10_13_1_13_dialog_content = "Kau masih tertidur?",
  ui_story_10_13_1_14_dialog_content = "Hah?",
  ui_story_10_13_1_15_dialog_content = "Hapus ekspresi bodohmu itu. Aku datang untuk memberitahukan hasil eksperimennya.",
  ui_story_10_13_1_16_dialog_content = "Apa?",
  ui_story_10_13_1_17_dialog_content = "Kesimpulan terakhir yang kuambil adalah bahwa kau sebuah <color=#FFB400>kegagalan total</color>.",
  ui_story_10_13_1_18_dialog_content = "For… sakin…",
  ui_story_10_13_1_19_dialog_content = "Jangan sakit hati, Schummer. Aku cuma menyampaikan fakta secara objektif.",
  ui_story_10_13_1_20_dialog_content = "Kau sudah menyerap seluruh kekuatan Aviduz, dan segunduk penuh Eclipsite, tapi transformasimu belum juga selesai.",
  ui_story_10_13_1_21_dialog_content = "Menyerap kekuatan… Aviduz?",
  ui_story_10_13_1_22_dialog_content = "Benar. Lihat healing pod itu? Itu terhubung dengan Aviduz kesayanganmu.",
  ui_story_10_13_1_23_dialog_content = "Kau memakainya untuk mengisap habis semua kekuatannya. Sekarang Aviduz tak lebih dari rongsokan besi raksasa belaka.",
  ui_story_10_13_1_24_dialog_content = "Kenapa, kenapa kau tidak bilang…",
  ui_story_10_13_1_25_dialog_content = "Karena aku tahu kau sangat menyayangi Colossus ini.",
  ui_story_10_13_1_26_dialog_content = "Bagaikan anak kecil yang akhirnya mendapatkan mainan yang selalu mereka inginkan, kau tidak mau melepaskannya sedetik pun. Ini sangat wajar.",
  ui_story_10_13_1_27_dialog_content = "Lalu juga sangat jelas, bahwa di dalam hatimu, kau masih tak lebih dari seorang Caelestite yang lemah.",
  ui_story_10_13_1_28_dialog_content = [[
Karena itu, tiap kali kau bertemu PlayerName, kamu tidak berani membunuh 
atau melepaskan rekan sebangsamu itu.]],
  ui_story_10_13_1_29_dialog_content = "Selama ini kau masih saja terbelenggu oleh masa lalumu. Sayang sekali.",
  ui_story_10_13_1_30_dialog_content = "Kuharap kamu tidak berkhayal dan mengira bahwa kau memegang kendali atas nasibmu, ya?",
  ui_story_10_13_1_31_dialog_content = "Itu bukan hak bagi mereka yang lemah.",
  ui_story_10_13_1_32_dialog_content = "Kurang ajar.",
  ui_story_10_13_1_33_dialog_content = "Memang sepantasnya kau marah.",
  ui_story_10_13_1_34_dialog_content = "Karena ini semua salahmu.",
  ui_story_10_13_1_35_dialog_content = "Karena kau begitu lemah, kekanakan, payah, dan begitu bodoh.",
  ui_story_10_13_1_36_dialog_content = "Akan kubunuh kau…",
  ui_story_10_13_1_37_dialog_content = "Salah. Bukan aku yang pantas kaubenci.",
  ui_story_10_13_1_38_dialog_content = "Kau sudah lupa.",
  ui_story_10_13_1_39_dialog_content = "Siapa yang memaksamu hingga jadi seperti ini?",
  ui_story_10_13_1_40_dialog_content = "Ingat apa yang pernah dikatakan Caelestite itu?",
  ui_story_10_13_1_41_dialog_content = "Kau selalu berlutut di lantai, merengek meminta kekuatan.",
  ui_story_10_13_1_42_dialog_content = "Rekan sebangsamu bisa langsung tahu isi hatimu…",
  ui_story_10_13_1_43_dialog_content = "Tapi sekarang mereka di sini.",
  ui_story_10_13_1_44_dialog_content = "Dan saat mereka menemukanmu, mereka akan membunuhmu.",
  ui_story_10_13_1_45_dialog_content = "Atau kau bisa mencoba meminta ampun kepada mereka.",
  ui_story_10_13_1_46_dialog_content = "Mana mungkin…",
  ui_story_10_13_1_47_dialog_content = "Kau bisa memohon agar mereka membiarkanmu pergi. Mohonlah kepada PlayerName agar dia tidak membunuhmu.",
  ui_story_10_13_1_48_dialog_content = "Sampai kiamat pun, aku tak sudi melakukannya…",
  ui_story_10_13_1_49_dialog_content = "Kalau begitu, kalau kau tidak mau mati…",
  ui_story_10_13_1_50_dialog_content = "Kalau kau ingin tetap hidup dan membunuh orang-orang bodoh itu…",
  ui_story_10_13_1_51_dialog_content = "Maka hanya ada satu pilihan yang tersisa.",
  ui_story_10_13_1_52_dialog_content = "Kau harus menginginkan lebih banyak kekuatan.",
  ui_story_10_13_1_53_dialog_content = "Kekuatan…",
  ui_story_10_13_1_54_dialog_content = "…",
  ui_story_10_13_1_55_dialog_content = "Schummer?",
  ui_story_10_13_1_56_dialog_content = "<size=45>Beri aku kekuatan!</size>",
  ui_story_10_13_1_57_dialog_content = "…",
  ui_story_10_13_1_58_dialog_content = "Aku memang sudah menduga kau akan kesulitan mengendalikan emosimu pada titik ini.",
  ui_story_10_13_1_59_dialog_content = "Tapi aku tidak menyangka kau akan sepenuhnya kehilangan kendali…",
  ui_story_10_13_1_60_dialog_content = "<size=45>Kekuatan!!!</size>",
  ui_story_10_13_1_61_dialog_content = "Sungguh tak berguna.",
  ui_story_10_13_1_62_dialog_content = "<color=#e8d9bb>Aahhhhhh!</color>",
  ui_story_10_13_1_63_dialog_content = "A-apa itu?",
  ui_story_10_13_1_64_dialog_content = "Apa kau bisa merasakan apa yang baru saja terjadi, PlayerName?",
  ui_story_10_13_1_65_dialog_content = "Entahlah. Sekalipun aku berusaha sekuat tenaga, aku hanya bisa melihat secuil saja pikiran Schummer.",
  ui_story_10_13_1_66_dialog_content = "Benaknya berisi pikiran-pikiran abstrak seperti kekuatan, kuasa, dan keistimewaan.",
  ui_story_10_13_1_67_dialog_content = "Ada yang lain juga. Perasaan yang sangat kuat…",
  ui_story_10_13_1_68_dialog_content = "<color=#FFB400>Kebencian.</color>",
  ui_story_10_13_1_69_dialog_content = "Sepertinya dia sudah benar-benar gila!",
  ui_story_10_13_1_70_dialog_content = "Gila? Saat kaubilang dia memakan Eclipsite, kukira dia sudah cukup gila.",
  ui_story_10_13_1_71_dialog_content = "Tapi kedengarannya aneh sekali.",
  ui_story_10_13_1_72_dialog_content = "Ini pasti ada hubungannya dengan Forsakin.",
  ui_story_10_13_1_73_dialog_content = "Mungkin saja dia sudah memberi tahu Schummer bahwa kita ada di sini.",
  ui_story_10_13_1_74_dialog_content = "Sepertinya pada akhirnya dia memang berencana melawan kita.",
  ui_story_10_13_1_75_dialog_content = "Kalau dia mengincarmu, berarti mungkin dia punya cara tertentu untuk melewati kami semua.",
  ui_story_10_13_1_76_dialog_content = "Mengingat Forsakin juga ada di sini… Mungkin kami tak akan bisa melindungimu saat kita bertarung.",
  ui_story_10_13_1_77_dialog_content = "Aku akan memeriksa kondisinya dulu. Kalian pastikan PlayerName tetap aman.",
  ui_story_10_13_1_78_dialog_content = "Baik.",
  ui_story_10_13_1_79_dialog_content = "Eclipsite, tepat di depan!",
  ui_story_10_13_1_80_dialog_content = "Cepat habisi mereka!",
  ui_story_10_13_1_81_dialog_content = "Graagh!",
  ui_story_10_13_1_82_dialog_content = "Apa yang terjadi? Eclipsite-Eclipsite tadi tiba-tiba jadi bersemangat sekali!",
  ui_story_10_13_1_83_dialog_content = "Apa karena gempa yang barusan?",
  ui_story_10_13_1_84_dialog_content = "Perasaanku tidak enak…",
  ui_story_10_13_1_85_dialog_content = "Bahkan Pact sekalipun bisa merasakannya.",
  ui_story_10_13_1_86_dialog_content = "Pasti muncul sesuatu yang sangat berbahaya.",
  ui_story_10_13_1_87_dialog_content = "Perintah dari Lady Victoria…",
  ui_story_10_13_1_88_dialog_content = "Adalah untuk tidak terlibat dalam perselisihan ini, untuk sementara waktu.",
  ui_story_10_13_1_89_dialog_content = "Aku setuju. Karena kita sudah mendapatkan banyak Seed, sebaiknya kita juga pergi dari sini.",
  ui_story_10_13_1_90_dialog_content = "Pertarungan yang sesungguhnya akan segera dimulai.",
  ui_story_10_13_2_1_dialog_content = "Graagh!!",
  ui_story_10_13_2_2_dialog_content = "…",
  ui_story_10_13_2_3_dialog_content = "Schummer?!",
  ui_story_10_13_2_4_dialog_content = "B-barusan dia menerkam Eclipsite itu?",
  ui_story_10_13_2_5_dialog_content = "Lalu memakannya?!",
  ui_story_10_13_2_6_dialog_content = "Apa itu benar-benar Schummer? Dia kelihatan sangat berbeda!",
  ui_story_10_13_2_7_dialog_content = "Schummer!",
  ui_story_10_13_2_8_dialog_content = "Sekarang aku tahu seluruh kebenaran tentang dosa-dosamu!",
  ui_story_10_13_2_9_dialog_content = "Kau tidak mau mati, karena itu kamu bergabung dengan para Eclipsite. Apa itu belum cukup?",
  ui_story_10_13_2_10_dialog_content = "Untuk apa kau juga membawa mereka ke Eraveil?!",
  ui_story_10_13_2_11_dialog_content = "Untuk apa kau membunuh semua orang?!",
  ui_story_10_13_2_12_dialog_content = "…",
  ui_story_10_13_2_13_dialog_content = "Pengkhianat… Kau harus membayar semua dosamu!",
  ui_story_10_13_2_14_dialog_content = "Aahhhh!",
  ui_story_10_13_2_15_dialog_content = "Awas, PlayerName!",
  ui_story_10_13_2_16_dialog_content = "Graagh!?",
  ui_story_10_13_2_17_dialog_content = "Dia… menyerang Eclipsite yang di sana?",
  ui_story_10_13_2_18_dialog_content = "…",
  ui_story_10_13_2_19_dialog_content = "Kekuatan…",
  ui_story_10_13_2_20_dialog_content = "Apa yang sebenarnya terjadi?",
  ui_story_10_13_2_21_dialog_content = "Dia seakan-akan… sama sekali tak melihat kita!",
  ui_story_10_13_2_22_dialog_content = "Hei, PlayerName! Tindakanmu barusan sangat gegabah, tahu!",
  ui_story_10_13_2_23_dialog_content = "Kau ini komandannya, bodoh! Kenapa kau malah menerjang maju mendahului pasukanmu?!",
  ui_story_10_13_2_24_dialog_content = "Maaf, tadi aku terlalu bersemangat, tapi aku sudah tenang sekarang.",
  ui_story_10_13_2_25_dialog_content = "…",
  ui_story_10_13_2_26_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_10_13_2_27_dialog_content = "Schummer, kurasa dia sudah melakukan segala hal kotor yang bisa dipikirkannya untuk mendapatkan kekuatan, tapi pada akhirnya, dia jadi kehilangan akal…",
  ui_story_10_13_2_28_dialog_content = "Semuanya, waspadalah. Sebaiknya kita tes dulu kekuatannya sebelum mencoba mengalahkannya.",
  ui_story_10_13_2_29_dialog_content = "Grrr…",
  ui_story_10_13_2_30_dialog_content = "Dia melihat kemari! Apa karena dia sudah selesai memakan Eclipsite itu?!",
  ui_story_10_13_2_31_dialog_content = "…",
  ui_story_10_13_2_32_dialog_content = "PlayerName…",
  ui_story_10_13_2_33_dialog_content = "Dia bereaksi!",
  ui_story_10_13_2_34_dialog_content = "PlayerName… Akan kubunuh kau…",
  ui_story_10_13_2_35_dialog_content = "Hadapi dulu aku!",
  ui_story_10_13_2_36_dialog_content = "<anim type=Shake><size=50>PlayerName! Mati kau!! MATIII!!!</size></anim>",
  ui_story_10_14_2_1_dialog_content = "Apa kita menang?!",
  ui_story_10_14_2_2_dialog_content = "Sekarang! Habisi dia!",
  ui_story_10_14_2_3_dialog_content = "Schummer! Selesai sudah!",
  ui_story_10_14_2_4_dialog_content = "Ahhhh!",
  ui_story_10_14_2_5_dialog_content = "Aduh, mimpi yang panjang dan menjijikkan…",
  ui_story_10_14_2_6_dialog_content = "Ayolah, ini cuma ingatan dari 17 tahun yang lalu.",
  ui_story_10_14_2_7_dialog_content = "Sudah, cukup…",
  ui_story_10_14_2_8_dialog_content = "Cukup!",
  ui_story_10_14_2_9_dialog_content = "Awas, PlayerName!",
  ui_story_10_14_2_10_dialog_content = "Duarr!!!",
  ui_story_10_14_2_11_dialog_content = "*Batuk-batuk*",
  ui_story_10_14_2_12_dialog_content = "Sial, dia masih bisa bertarung setelah semua itu?",
  ui_story_10_14_2_13_dialog_content = "Yang benar saja. Kenapa dia kuat sekali?!",
  ui_story_10_14_2_14_dialog_content = "…",
  ui_story_10_14_2_15_dialog_content = "Vice, PlayerName… apa kalian baik-baik saja?",
  ui_story_10_14_2_16_dialog_content = "Tidak terlalu, tapi lumayan.",
  ui_story_10_14_2_17_dialog_content = "Aku baik-baik saja… Terima kasih sudah melindungiku, Bopper.",
  ui_story_10_14_2_18_dialog_content = "Tak apa-apa, yang penting kau aman…",
  ui_story_10_14_2_19_dialog_content = "…",
  ui_story_10_14_2_20_dialog_content = "Apa dia mati?",
  ui_story_10_14_2_21_dialog_content = "Tidak. Ada yang salah…",
  ui_story_10_14_2_22_dialog_content = "Ha, haha… hahaha…",
  ui_story_10_14_2_23_dialog_content = "Schummer berhasil mengendalikan diri lagi! Semuanya, bersiaplah untuk bertarung lagi! Kekuatannya belum habis!",
  ui_story_10_14_2_24_dialog_content = "Mengendalikan diri?",
  ui_story_10_14_2_25_dialog_content = "Benar, barusan, aku begitu marah…",
  ui_story_10_14_2_26_dialog_content = "Tapi begitu aku ingat kau ada di sini, PlayerName… aku jadi sangat senang!",
  ui_story_10_14_2_27_dialog_content = "!",
  ui_story_10_14_2_28_dialog_content = "Sebenarnya kau ini makhluk macam apa?!",
  ui_story_10_14_2_29_dialog_content = "PlayerName, mundur!",
  ui_story_10_14_2_30_dialog_content = "Bopper! Kuserahkan PlayerName padamu! Pastikan komandan kita aman!",
  ui_story_10_14_2_31_dialog_content = "Baik!",
  ui_story_10_14_2_32_dialog_content = "Hei, maniak! Beri tahu aku, di mana Forsakin berada!",
  ui_story_10_14_2_33_dialog_content = "Maniak? Kau mau menghinaku?",
  ui_story_10_14_2_34_dialog_content = "Sudahlah, aku tak bisa marah kepadamu… aku tak punya waktu untukmu.",
  ui_story_10_14_2_35_dialog_content = "Soal Forsakin, tak usah khawatir.",
  ui_story_10_14_2_36_dialog_content = "Aku bersumpah, akan kucari pengecut itu dan kubuat dia menerima ganjarannya.",
  ui_story_10_14_2_37_dialog_content = "Tapi sebelum itu, aku harus selesaikan urusanku denganmu dulu, PlayerName.",
  ui_story_10_14_2_38_dialog_content = "Dan kali ini, aku janji akan menggunakan seluruh kekuatanku…",
  ui_story_10_14_2_39_dialog_content = "Untuk memberimu kematian yang paling menyakitkan!!!",
  ui_story_10_14_2_40_dialog_content = "!!!",
  ui_story_10_14_2_41_dialog_content = "Kau ingin melawan mereka sampai mati? Tak akan berhasil…",
  ui_story_10_14_2_42_dialog_content = "Forsakin?!",
  ui_story_10_14_2_43_dialog_content = "Selamat, Schummer. Seed-nya telah bereaksi dengan keinginanmu dan akhirnya matang.",
  ui_story_10_14_2_44_dialog_content = "Sayangnya, kamu sudah menghabiskan sebagian besar kekuatanmu dalam pertarungan tadi.",
  ui_story_10_14_2_45_dialog_content = "Kalau kau terus seperti ini, semua kerja keras yang sudah kulakukan untuk Seed-mu akan jadi sia-sia.",
  ui_story_10_14_2_46_dialog_content = "Kau?!",
  ui_story_10_14_2_47_dialog_content = "Jaga perilakumu sampai aku bisa memanen Seed milikku.",
  ui_story_10_14_2_48_dialog_content = "Sinsa! Target Forsakin ternyata adalah Schummer, bukan kita! Dia mengincar <color=#FFB400>Seed</color>-nya!",
  ui_story_10_14_2_49_dialog_content = "Aku tak akan membiarkanmu begitu saja!",
  ui_story_10_14_2_50_dialog_content = "Jangan terlalu marah. Mengingat tujuanku, anggap saja aku menyelamatkan kalian semua.",
  ui_story_10_14_2_51_dialog_content = "Kalian bisa urus Schummer sesuka kalian, setelah aku mengambil Seed milikku, tentunya.",
  ui_story_10_14_2_52_dialog_content = "Semua orang akan mendapatkan yang mereka inginkan, dan kita semua senang.",
  ui_story_10_14_2_53_dialog_content = "Lagi pula, kalian tak akan bisa menghentikanku.",
  ui_story_10_14_2_54_dialog_content = "Sinsa, awas!!!",
  ui_story_10_14_2_55_dialog_content = "Serangan jarak luas?!",
  ui_story_10_14_2_56_dialog_content = "Jangan bergerak, kalian semua.",
  ui_story_10_14_2_57_dialog_content = "Baiklah…",
  ui_story_10_14_2_58_dialog_content = "Ada kata-kata terakhir sebelum kau mati, Schummer?",
  ui_story_10_14_2_59_dialog_content = "Beri tahu aku bagaimana rasanya kehilangan kekuatanmu. Atau lebih tepatnya, bagaimana rasanya menjadi Caelestite lagi.",
  ui_story_10_14_2_60_dialog_content = "Kalau ada hal penting yang ingin kausampaikan, aku berjanji akan menuliskannya dalam catatan risetku.",
  ui_story_10_14_2_61_dialog_content = "…",
  ui_story_10_14_2_62_dialog_content = "Cih…",
  ui_story_10_14_2_63_dialog_content = "Baiklah.",
  ui_story_10_14_2_64_dialog_content = "Sebagai hadiah karena telah membantu menyelesaikan eksperimenku, kuserahkan Schummer kepada kalian.",
  ui_story_10_14_2_65_dialog_content = "Selamat tinggal, Schummer.",
  ui_story_10_14_2_66_dialog_content = "*Batuk-batuk*",
  ui_story_10_14_2_67_dialog_content = "Sinsa, apa pun yang terjadi… Jangan kejar dia.",
  ui_story_10_14_2_68_dialog_content = "Aku tahu.",
  ui_story_10_14_2_69_dialog_content = "Apa yang akan kita lakukan dengan Schummer, PlayerName? Keputusan ada di tanganmu.",
  ui_story_10_14_2_70_dialog_content = "Dia tak akan bisa bertahan lama dengan luka itu, dia bahkan hampir tidak bisa bergerak dengan kondisi itu.",
  ui_story_10_14_2_71_dialog_content = "Jangan pikirkan apa yang baru saja terjadi. Ikuti saja kata hatimu.",
  ui_story_10_14_2_72_dialog_content = "Kalau kau mau, aku bisa membuatkan bongkahan es tajam agar kau bisa menuntaskan dendammu, PlayerName.",
  ui_story_10_14_2_73_dialog_content = "Sebelum itu, ada pertanyaan yang perlu kaujawab.",
  ui_story_10_14_2_74_dialog_content = "Ha! Menuntaskan dendam? Menanyaiku?",
  ui_story_10_14_2_75_dialog_content = "Kenapa kau… tidak tanyakan saja sekarang? Aku akan menjawabnya…",
  ui_story_10_14_2_76_dialog_content = "Beri tahu aku, di mana ketiga modul Colossus itu?",
  ui_story_10_14_2_77_dialog_content = "Mati saja kau!",
  ui_story_10_14_2_78_dialog_content = "Caelestite keparat! Kau mau mengambil modulku?! Enak saja!",
  ui_story_10_14_2_79_dialog_content = [[
Kau tak tahu betapa berharganya modul itu! Komponen itu milik Aviduz, 
dan hanya Aviduz saja yang layak memilikinya!]],
  ui_story_10_14_2_80_option_content = "Kau benar, aku tidak tahu, tapi apakah Aviduz sepenting itu bagimu?",
  ui_story_10_14_2_81_dialog_content = "Apakah alasanmu mengkhianati Caelestite adalah agar kau bisa merebut Aviduz?",
  ui_story_10_14_2_82_dialog_content = "Aku tak akan menyalahkanmu kalau kau tak mau mati saat diserang Eclipsite.",
  ui_story_10_14_2_83_dialog_content = "Hidup saja terus sebagai Eclipsite! Pergi dan jangan pernah kembali lagi! Kenapa kau malah membawa mereka ke Eraveil?!",
  ui_story_10_14_2_84_dialog_content = "Kenapa?!",
  ui_story_10_14_2_85_dialog_content = "Hehe…",
  ui_story_10_14_2_86_dialog_content = "Kamu tak akan paham.",
  ui_story_10_14_2_87_dialog_content = "Kau belum melihatnya dengan matamu sendiri. Kau belum menyaksikan sendiri hari penghakiman itu, kau tak akan paham…",
  ui_story_10_14_2_88_dialog_content = "Eraveil, mereka turun ke Eraveil!",
  ui_story_10_14_2_89_dialog_content = "Tak ada jalan keluar! Tak seorang pun akan bisa kabur!",
  ui_story_10_14_2_90_dialog_content = "Begitu pula dengan kalian… Kalian semua akan dihancurkan…",
  ui_story_10_14_2_91_dialog_content = "Omong kosong! Eclipsite mencuci otakmu agar kau memercayai hal itu!",
  ui_story_10_14_2_92_dialog_content = "Jangan biarkan kebohongannya menipumu, PlayerName!",
  ui_story_10_14_2_93_option_content = "Aku tak tahu, dan tak mau tahu! Serahkan modulnya!",
  ui_story_10_14_2_94_dialog_content = "Sejak awal, modul itu bukan milikmu!",
  ui_story_10_14_2_95_dialog_content = "Modul itu milik para Caelestite!",
  ui_story_10_14_2_96_dialog_content = "Kaum Caelestite menyimpannya demi mereka sendiri!!",
  ui_story_10_14_2_97_dialog_content = "Sejak awal modul itu milik kaum Caelestite!!!",
  ui_story_10_14_2_98_dialog_content = "Pengkhianat sepertimu tak berhak mengambilnya!!!",
  ui_story_10_14_2_99_dialog_content = "…",
  ui_story_10_14_2_100_dialog_content = "Kau tak tahu apa-apa!",
  ui_story_10_14_2_101_dialog_content = [[
Memangnya Caelestite itu apa? Sekumpulan orang lemah 
yang tak tahu apa yang terbaik bagi mereka!]],
  ui_story_10_14_2_102_dialog_content = "Orang-orang bodoh itu tak tahu nilai sesungguhnya dari Colossus, nilai sesungguhnya dari kekuatan!",
  ui_story_10_14_2_103_dialog_content = "Mereka semua tolol dan tidak kompeten, sama sepertimu!",
  ui_story_10_14_2_104_dialog_content = "Diam!",
  ui_story_10_14_2_105_dialog_content = "PlayerName, jangan sampai terpancing!",
  ui_story_10_14_2_106_dialog_content = "Aku tahu.",
  ui_story_10_14_2_107_dialog_content = "Aku tahu…",
  ui_story_10_14_2_108_dialog_content = "Aku sudah bisa menebak di tengah jalan kemari, bahwa tujuan para Eclipsite sejak awal adalah menghancurkan Eraveil.",
  ui_story_10_14_2_109_dialog_content = "Suatu hari, entah bagaimana caranya, mereka tetap akan menyerang.",
  ui_story_10_14_2_110_dialog_content = "Schummer, dalam segala yang terjadi ini, kau sebenarnya hanyalah korban yang malang.",
  ui_story_10_14_2_111_dialog_content = "Hah?",
  ui_story_10_14_2_112_dialog_content = "Apa maksudmu?",
  ui_story_10_14_2_113_dialog_content = "Aku terpilih, terpilih untuk hidup karena aku pantas!",
  ui_story_10_14_2_114_dialog_content = "Bagaimana cederamu, Vice?",
  ui_story_10_14_2_115_dialog_content = "H-Hah? Tidak apa-apa… Aku baik-baik saja.",
  ui_story_10_14_2_116_dialog_content = "Hei!!!",
  ui_story_10_14_2_117_dialog_content = "Kau mendengarkanku, tidak?!",
  ui_story_10_14_2_118_dialog_content = "Sebagian besar Colossus punya struktur sama. Kurasa aku bisa menemukan di mana modulnya, Vice.",
  ui_story_10_14_2_119_dialog_content = "Bisa tolong bantu aku?",
  ui_story_10_14_2_120_dialog_content = "Baiklah.",
  ui_story_10_14_2_121_dialog_content = "…",
  ui_story_10_14_2_122_dialog_content = "…",
  ui_story_10_14_2_123_dialog_content = "Bagaimana dengan dendammu?",
  ui_story_10_14_2_124_dialog_content = "Kenapa kau tak berteriak-teriak dan melontarkan sumpah serapah lagi? Kau sudah tak ingin membalaskan dendammu? Hanya karena kau kini menentang Eclipsite?",
  ui_story_10_14_2_125_dialog_content = "Oh, jadi sekarang kaukira bisa tinggal mengambil modulnya, membunuhku, pulang, lalu minum-minum teh dengan teman-teman kesayanganmu itu?",
  ui_story_10_14_2_126_dialog_content = "PlayerName, sampaikan saja perintahnya, akan langsung kubungkam mulutnya…",
  ui_story_10_14_2_127_dialog_content = "Abaikan saja dia! Kau juga harus merawat lukamu, Sinsa.",
  ui_story_10_14_2_128_dialog_content = "Bopper, bisa tolong bantu aku mengambil modulnya?",
  ui_story_10_14_2_129_dialog_content = "Baiklah…",
  ui_story_10_14_2_130_dialog_content = "Ha! Hahaha…",
  ui_story_10_14_2_131_dialog_content = "Ya, inilah kaum yang lembut dan cinta damai.",
  ui_story_10_14_2_132_dialog_content = "Kaum Caelestite benar-benar tolol.",
  ui_story_10_14_2_133_dialog_content = "Carleen, tolong buatkan bongkahan es tajam untukku.",
  ui_story_10_14_2_134_dialog_content = "Baik.",
  ui_story_10_14_2_135_dialog_content = "…",
  ui_story_10_14_2_136_dialog_content = "Beri tahu aku, Schummer, siapa <color=#FFB400>Figerald</color>?",
  ui_story_10_14_2_137_dialog_content = "Lalu, <color=#FFB400>Eclipse</color> itu apa?",
  ui_story_10_14_2_138_dialog_content = "!",
  ui_story_10_14_2_139_dialog_content = "Kau melihat ingatanku?!",
  ui_story_10_14_2_140_dialog_content = "Ya, tapi sayangnya aku hanya melihatnya sepotong-sepotong.",
  ui_story_10_14_2_141_dialog_content = "Karena itu aku akan mendengarkan sisa ceritanya langsung dari mulutmu.",
  ui_story_10_14_2_142_dialog_content = "…",
  ui_story_10_14_2_143_dialog_content = "Hahaha…",
  ui_story_10_14_2_144_dialog_content = "Baiklah. Kemarilah, akan kuceritakan…",
  ui_story_10_14_2_145_dialog_content = "Sedikit lebih dekat saja sudah cukup.",
  ui_story_10_14_2_146_dialog_content = "Lagi pula, kau akan mengakhiri penderitaanku dengan bongkahan es itu, 'kan?",
  ui_story_10_14_2_147_dialog_content = "Ada yang tidak beres, PlayerName! Jangan tertipu!",
  ui_story_10_14_2_148_dialog_content = "Jangan khawatir, aku sama sekali tak berniat mendekatinya.",
  ui_story_10_14_2_149_dialog_content = "Sudah terlambat…",
  ui_story_10_14_2_150_dialog_content = "Grrr…",
  ui_story_10_14_2_151_dialog_content = "Grrr…",
  ui_story_10_14_2_152_dialog_content = "Di belakangmu!",
  ui_story_10_14_2_153_dialog_content = "Graagh!",
  ui_story_10_14_2_154_dialog_content = "Hahaha… haha…",
  ui_story_10_14_2_155_dialog_content = "Sudah kubilang aku ini terpilih! Aku adalah utusan dari Eclipse!",
  ui_story_10_14_2_156_dialog_content = "Ayo, ayo kepung mereka…",
  ui_story_10_14_2_157_dialog_content = "Grrr…",
  ui_story_10_14_2_158_dialog_content = "Grrr…",
  ui_story_10_14_2_159_dialog_content = "Pada akhirnya, akulah yang menang.",
  ui_story_10_14_2_160_dialog_content = "PlayerName.",
  ui_story_10_14_2_161_dialog_content = [[
Persaingan, evolusi, satu-satunya cara mewujudkan itu 
adalah dengan menginjak kepala orang lain!]],
  ui_story_10_14_2_162_dialog_content = "Korban sesungguhnya dalam hal ini adalah kau dan Eraveil!",
  ui_story_10_14_2_163_dialog_content = [[
Aku sudah mengungguli kalian semua melewati cobaan-cobaan ini, 
dan sekarang aku tak akan bisa dihentikan!]],
  ui_story_10_14_2_164_dialog_content = "…",
  ui_story_10_14_2_165_dialog_content = "Semuanya, bersiaplah untuk mundur…",
  ui_story_10_14_2_166_dialog_content = "Apa?! Kita tak akan mendapatkan kesempatan lagi seperti ini! Kita lawan saja mereka!",
  ui_story_10_14_2_167_dialog_content = "Sudah jelas kondisi kita tak memungkinkan untuk melawan Eclipsite sebanyak ini. Kita sedang cedera, tahu.",
  ui_story_10_14_2_168_dialog_content = "Kalian semua harusnya lebih paham daripada aku.",
  ui_story_10_14_2_169_dialog_content = "Aku ingin balas dendam, tapi aku tak mau kalau harus mengorbankan satu pun dari kalian.",
  ui_story_10_14_2_170_dialog_content = "Mundur? Coba saja! Aku ingin melihatnya sendiri…",
  ui_story_10_14_2_171_dialog_content = "Siapa yang lebih cepat, Eclipsite milikku atau kalian yang sedang terluka!",
  ui_story_10_14_2_172_dialog_content = "Cincang mereka!",
  ui_story_10_14_2_173_dialog_content = "Grrr…",
  ui_story_10_14_2_174_dialog_content = "Kalian tunggu apa?! Serang!!",
  ui_story_10_14_2_175_dialog_content = "Graagh!",
  ui_story_10_14_2_176_dialog_content = "Apa?!",
  ui_story_10_14_2_177_dialog_content = "Argh! Lepaskan aku!!",
  ui_story_10_14_2_178_dialog_content = "Jangan aku! Tidak!!",
  ui_story_10_14_2_179_dialog_content = "Tidaaaak!!!",
  ui_story_10_14_2_180_dialog_content = "Graagh!",
  ui_story_10_14_2_181_dialog_content = "…",
  ui_story_10_14_2_182_dialog_content = "Kita tak punya waktu… Kita harus lari selagi masih bisa!",
  ui_story_10_14_2_183_dialog_content = "Kalau tidak, kita akan jadi santapan berikutnya!",
  ui_story_10_14_2_184_dialog_content = "PlayerName!",
  ui_story_10_14_2_185_dialog_content = "Bawa PlayerName keluar dari sini! Sana!",
  ui_story_10_14_2_186_dialog_content = "Pergilah!!",
  ui_story_10_14_2_187_dialog_content = "Akhir seperti ini…",
  ui_story_10_14_2_188_dialog_content = "(Aku tak mau menerimanya!)",
  ui_story_10_14_2_189_dialog_content = "(Aku berusaha begitu keras untuk tetap hidup, untuk mendapatkan semua ini…)",
  ui_story_10_14_2_190_dialog_content = "(Mereka semua pembohong!)",
  ui_story_10_14_2_191_dialog_content = "(Ini semua palsu!)",
  ui_story_10_14_2_192_dialog_content = "(Kekuatan palsu! Penghakiman palsu!)",
  ui_story_10_14_2_193_dialog_content = "(Forsakin, Figerald, Eclipse…)",
  ui_story_10_14_2_194_dialog_content = "(Sejak awal, mereka tidak berniat membiarkanku pergi…)",
  ui_story_10_14_2_195_dialog_content = "(Terkutuklah kalian semua…)",
  ui_story_10_14_2_196_dialog_content = "(Bangsa lemah yang ditakdirkan untuk binasa…)",
  ui_story_10_14_2_197_dialog_content = "(Caelestite sudah terkutuk semenjak mereka lahir…)",
  ui_story_10_14_2_198_dialog_content = "(Kau juga tak ada bedanya, kau akan mati dengan mengerikan dan tragis, sepertiku…)",
  ui_story_10_14_2_199_dialog_content = "(Terkutuklah kau…)",
  ui_story_10_14_2_200_dialog_content = "(PlayerName…)",
  ui_story_10_14_2_201_dialog_content = "(Terimalah kengerian dari takdir kehancuranmu…)",
  ui_story_10_14_2_202_dialog_content = "(<color=#FFB400>Eclipse telah tiba sejak dahulu!</color>)",
  ui_story_10_15_1_1_dialog_content = "Apa lagi yang bisa kulakukan?)",
  ui_story_10_15_1_2_dialog_content = "(Dia sudah mati.)",
  ui_story_10_15_1_3_dialog_content = "(Dimakan Eclipsite… Cara mati yang menyedihkan…)",
  ui_story_10_15_1_4_dialog_content = "(Apa yang harus kita lakukan sekarang? Apa yang harus kulakukan…)",
  ui_story_10_15_1_5_dialog_content = "Grrr…",
  ui_story_10_15_1_6_dialog_content = "(Kita semua terluka, dan para Eclipsite ini… tak akan membiarkan kita pergi begitu saja…)",
  ui_story_10_15_1_7_dialog_content = "(Sama seperti Eclipse…)",
  ui_story_10_15_1_8_dialog_content = "(Hari itu, semua orang dibantai…)",
  ui_story_10_15_1_9_dialog_content = "Apa yang harus kita lakukan?",
  ui_story_10_15_1_10_dialog_content = "Lari!",
  ui_story_10_15_1_11_dialog_content = "Bawa PlayerName!",
  ui_story_10_15_1_12_dialog_content = "Ayo! Cepat kita keluar dari sini!",
  ui_story_10_15_1_13_dialog_content = "Lari! Ikuti jalan yang tadi kita tempuh!",
  ui_story_10_15_1_14_dialog_content = "P-para Eclipsite makin mendekati kita…",
  ui_story_10_15_1_15_dialog_content = "Aku akan jaga bagian belakang!",
  ui_story_10_15_1_16_dialog_content = "Graagh!",
  ui_story_10_15_1_17_dialog_content = "Carleen?!",
  ui_story_10_15_1_18_dialog_content = "*Uhuk* Aku baik-baik saja, lari!",
  ui_story_10_15_1_19_dialog_content = "Baru saja semuanya hampir selesai, kita malah kena masalah lagi…",
  ui_story_10_15_1_20_dialog_content = "…",
  ui_story_10_15_1_21_dialog_content = "Mereka mengejar kita sampai sini? Keras kepala sekali!",
  ui_story_10_15_1_22_dialog_content = "Graagh!",
  ui_story_10_15_1_23_dialog_content = "!",
  ui_story_10_15_1_24_dialog_content = "PlayerName! Sadarlah!",
  ui_story_10_15_1_25_dialog_content = "Kami butuh bantuanmu!!",
  ui_story_10_15_1_26_dialog_content = "…",
  ui_story_10_15_1_27_dialog_content = "…",
  ui_story_10_15_1_28_dialog_content = "Vice, Eclipsite memblokir jalan di depan! Tembak mereka!",
  ui_story_10_15_1_29_dialog_content = "Carleen, ambil jarak dulu, kepung mereka dari sisi kiri belakang, lalu serang!",
  ui_story_10_15_1_30_dialog_content = "Rapid Torrent!",
  ui_story_10_15_1_31_dialog_content = "Baik!",
  ui_story_10_15_1_32_dialog_content = "Graagh!",
  ui_story_10_15_1_33_dialog_content = "Akhirnya kau sadar juga!",
  ui_story_10_15_1_34_dialog_content = "Maaf, barusan Schummer sempat memengaruhiku sebelum dia akhirnya mati. Aku jadi agak pusing karenanya.",
  ui_story_10_15_1_35_dialog_content = "Tidak usah minta maaf, coba tenangkan dirimu secepat mungkin.",
  ui_story_10_15_1_36_dialog_content = "Tugas kita belum selesai.",
  ui_story_10_15_1_37_dialog_content = "Aku masih harus melaporkan ini ke Lumopolis, dan kau masih harus memperbaiki Soroz.",
  ui_story_10_15_1_38_dialog_content = "Ayo kita habisi Eclipsite ini, dan keluar dari sini hidup-hidup!",
  ui_story_10_15_1_39_dialog_content = "Kau benar.",
  ui_story_10_15_1_40_dialog_content = "Aku mulai merasa normal lagi… Sekarang aku bisa membantu kalian semua bertarung lagi!",
  ui_story_10_15_1_41_dialog_content = "Untunglah kau sudah merasa baikan, PlayerName.",
  ui_story_10_15_1_42_dialog_content = "Tapi Eclipsite ini!",
  ui_story_10_15_1_43_dialog_content = "Aahhhhhh!",
  ui_story_10_15_1_44_dialog_content = "Aku ingin bilang aku tak takut mati…",
  ui_story_10_15_1_45_dialog_content = "Tapi adikku menungguku pulang!",
  ui_story_10_15_1_46_dialog_content = "<size=45>Semuanya, kita akan bertarung sampai titik darah terakhir! Tapi jangan sampai ada yang mati!</size>",
  ui_story_10_15_1_47_dialog_content = "Jangan terlalu berisik, Sinsa! Bukan kau yang berhak memberikan perintah di sini!",
  ui_story_10_15_1_48_dialog_content = "Grrr…",
  ui_story_10_15_1_49_dialog_content = "Graagh!",
  ui_story_10_15_1_50_dialog_content = "Sini!",
  ui_story_10_15_1_51_dialog_content = "Para Eclipsite itu tersedot ke sana?!",
  ui_story_10_15_1_52_dialog_content = "Dan tetap tiarap!",
  ui_story_10_15_1_53_dialog_content = "Graagh!",
  ui_story_10_15_1_54_dialog_content = "Yo, Sinsa! Pahlawanmu, Brock, datang menolong!",
  ui_story_10_15_1_55_dialog_content = "Hahaha! Kau tidak mengira ini akan terjadi, 'kan? Hahahaha!",
  ui_story_10_15_1_56_dialog_content = "Awas, akan ada ledakan!",
  ui_story_10_15_1_57_dialog_content = "Waaaaah?!",
  ui_story_10_15_1_58_dialog_content = "Hoi, hati-hati menembakkannya! Kau hampir membuatku meledak!",
  ui_story_10_15_1_59_dialog_content = "Salahmu sendiri menarik semua Eclipsite kemari tanpa menghabisi mereka!",
  ui_story_10_15_1_60_dialog_content = "Ada apa ini?",
  ui_story_10_15_1_61_dialog_content = "Haha…",
  ui_story_10_15_1_62_dialog_content = "Maaf, tapi sepertinya kawan-kawan Rediesel Wrench-ku datang membantu.",
  ui_story_10_15_1_63_dialog_content = "Jangan salah, mereka kuat, tapi sayangnya juga agak berisik.",
  ui_story_10_15_1_64_dialog_content = "Fiuh, kita selamat! Kalian luar biasa!",
  ui_story_10_15_1_65_dialog_content = "Ya… kita selamat…",
  ui_story_10_15_1_66_dialog_content = "Wow, pertarungan yang melelahkan! Eclipsite-nya banyak sekali.",
  ui_story_10_15_1_67_dialog_content = "Hei, Sinsa! Kamu mau tahu bagaimana kami bisa kemari? Jadi begini, semuanya dimulai saat gunung itu bergetar…",
  ui_story_10_15_1_68_dialog_content = "Bos! Kau baik-baik saja?!",
  ui_story_10_15_1_69_dialog_content = "Aku tak apa-apa, ini cuma luka kecil…",
  ui_story_10_15_1_70_dialog_content = "Wow, Colossus ini bagus sekali!",
  ui_story_10_15_1_71_dialog_content = "Tak akan sia-sia kita kemari kalau kita bisa membawa pulang benda ini!",
  ui_story_10_15_1_72_dialog_content = "Semuanya, kemarilah dan bantu aku membongkarnya agar bisa kita pindahkan!",
  ui_story_10_15_1_73_dialog_content = "Tunggu dulu!",
  ui_story_10_15_1_74_dialog_content = "Kau dari Lumopolis?",
  ui_story_10_15_1_75_dialog_content = "Maaf, Odi, aku belum sempat memperkenalkannya.",
  ui_story_10_15_1_76_dialog_content = "Dia Carleen, dari Lumopolis. Mereka berdua adalah Vice dan PlayerName.",
  ui_story_10_15_1_77_dialog_content = "Tunggu, tunggu, tunggu… Bos, bukankah si Carleen dari Lumopolis ini adalah Kapten dari Guardian?",
  ui_story_10_15_1_78_dialog_content = "Diamlah, Brock!",
  ui_story_10_15_1_79_dialog_content = "Hari ini, kami semua adalah rekan bertempur.",
  ui_story_10_15_1_80_dialog_content = "Benar 'kan, Carleen?",
  ui_story_10_15_1_81_dialog_content = "…",
  ui_story_10_15_1_82_dialog_content = "Baiklah. Lalu, apa mereka juga mengincar Colossus ini?",
  ui_story_10_15_1_83_dialog_content = "Kalau iya, kurasa sebaiknya kita bagi-bagi saja berdasarkan siapa yang bekerja lebih banyak. Setuju?",
  ui_story_10_15_1_84_dialog_content = "Aku yang akan ambil keputusan, kalian semua diam dan dengarkan saja.",
  ui_story_10_15_1_85_dialog_content = "Kalau masih ada yang tidak setuju, kita urus nanti saat sudah kembali ke markas.",
  ui_story_10_15_1_86_dialog_content = "PlayerName!",
  ui_story_10_15_1_87_dialog_content = [[
Kau mau Colossus hitam ini? 
Kami akan membantu membawanya kalau kau mau!]],
  ui_story_10_15_1_88_dialog_content = "Eh?",
  ui_story_10_15_1_89_dialog_content = "Kenapa, masih pusing, ya? Ayolah, Nak!",
  ui_story_10_15_1_90_dialog_content = "Aku baik-baik saja. Aku sudah baik-baik saja dari tadi.",
  ui_story_10_15_1_91_dialog_content = "Baguslah kalau begitu.",
  ui_story_10_15_1_92_dialog_content = "Maksudku, benda ini seharusnya jadi milikmu. Lagi pula, ini Colossus milik para Caelestite.",
  ui_story_10_15_1_93_dialog_content = "Tapi, kalau aku boleh memberikan saran…",
  ui_story_10_15_1_94_dialog_content = "Apa itu?",
  ui_story_10_15_1_95_dialog_content = "Bagaimana kalau kau bergabung ke Rediesel Wrench? Dengan begitu, kurasa akan lebih bisa dibenarkan kalau kami membawa benda ini ke markas kami!",
  ui_story_10_15_1_96_dialog_content = "Aku…",
  ui_story_10_15_1_97_dialog_content = "Kau tidak perlu menjawab sekarang juga! Aku hanya menyarankan, kok.",
  ui_story_10_15_1_98_dialog_content = "Kalau suatu saat nanti kau ingin bergabung ke Rediesel Wrench, kami selalu siap menerimamu.",
  ui_story_10_15_1_99_dialog_content = "Terima kasih.",
  ui_story_10_15_1_100_dialog_content = "Tapi aku hanya butuh tiga modul dari Colossus ini.",
  ui_story_10_15_1_101_dialog_content = "Kalian bebas berbuat apa pun dengan sisa Aviduz.",
  ui_story_10_15_1_102_dialog_content = "Baiklah, bagaimana dengan kalian berdua? Ada yang ingin kalian sampaikan?",
  ui_story_10_15_1_103_dialog_content = "Kalau Lumopolis atau Illumina tertarik dengannya, kurasa kalian berdua tak akan membiarkan kami membawanya begitu saja.",
  ui_story_10_15_1_104_dialog_content = "Kalau PlayerName bilang kalian boleh mengambilnya, aku tak berniat menghentikan kalian.",
  ui_story_10_15_1_105_dialog_content = "Kami tidak membutuhkannya.",
  ui_story_10_15_1_106_dialog_content = "Sejujurnya, sejak pertama kali bertemu, aku tahu kalian kemari untuk Colossus ini.",
  ui_story_10_15_1_107_dialog_content = "Saat itu, aku sudah memutuskan bahwa aku tak akan merebut Aviduz darimu.",
  ui_story_10_15_1_108_dialog_content = "Bagus! Kau sangat setia kawan!",
  ui_story_10_15_1_109_dialog_content = "Ini bukan soal setia atau apalah, aku sekadar tidak tertarik.",
  ui_story_10_15_1_110_dialog_content = "PlayerName.",
  ui_story_10_15_1_111_dialog_content = "Aku yakin perasaanmu sedang campur-aduk setelah apa yang baru saja kita alami.",
  ui_story_10_15_1_112_dialog_content = "Tapi jangan terlalu dipikirkan. Yang kaulakukan sudah lebih dari cukup!",
  ui_story_10_15_1_113_dialog_content = [[
Kalau sekarang kau mau kembali ke kehidupan yang damai, 
tak akan ada yang menyalahkanmu!]],
  ui_story_10_15_1_114_dialog_content = "Sinsa…",
  ui_story_10_15_1_115_dialog_content = "Terima kasih.",
  ui_story_10_15_1_116_dialog_content = "Hei, kenapa kalian saling berbicara seperti itu?",
  ui_story_10_15_1_117_dialog_content = "Aku cuma memuji dia! Jangan pasang tampang seperti itu!",
  ui_story_10_15_1_118_dialog_content = "Baiklah, urusan kita selesai! Ayo kembali bekerja!",
  ui_story_10_15_1_119_dialog_content = "Aduh, istirahatlah kalau memang perlu. Yang lainnya, kemarilah dan mulai bekerja!",
  ui_story_10_15_1_120_dialog_content = "Ayo jalan!",
  ui_story_10_15_1_121_dialog_content = "Kita tarik di hitungan ketiga! Siap?",
  ui_story_10_15_1_122_dialog_content = "Siap!",
  ui_story_10_15_1_123_dialog_content = "Brock! Sedang apa kau di sana sendirian?!",
  ui_story_10_15_1_124_dialog_content = "Sudah pasti pemanasan!",
  ui_story_10_15_1_125_dialog_content = "Kaukira aku akan menunggu sampai kau menyuruhku mulai?!",
  ui_story_10_15_1_126_dialog_content = "Mana mungkin kita bisa menyeret benda ini! Ini Colossus utuh, tahu!",
  ui_story_10_15_1_127_dialog_content = "Atau kita bongkar dan ambil yang bisa digunakan saja?",
  ui_story_10_15_1_128_dialog_content = "Setuju.",
  ui_story_10_15_1_129_dialog_content = "Hei Bopper, apa kalian masih butuh bantuan? Aku ingin kembali kepada Soroz secepat mungkin.",
  ui_story_10_15_1_130_dialog_content = "Tidak, kurasa kami bisa mengurus ini sendiri.",
  ui_story_10_15_1_131_dialog_content = "Kami akan cari cara sendiri, jadi tak usah khawatirkan kami.",
  ui_story_10_15_1_132_dialog_content = "Kembalilah ke Colossus kalian dan beristirahatlah. Yang penting, urus dulu luka kalian!",
  ui_story_10_15_1_133_dialog_content = "Jangan khawatir, kami tidak lupa kok. Sakitnya bahkan masih terasa.",
  ui_story_10_15_1_134_dialog_content = "Tapi kami ingin berpamitan kepada Sinsa. Mana dia?",
  ui_story_10_15_1_135_dialog_content = "Soal itu… dia bilang dia tidak butuh perpisahan sedih, jadi tak usah dipikirkan.",
  ui_story_10_15_1_136_dialog_content = "Baiklah…",
  ui_story_10_15_1_137_dialog_content = "Kami akan pergi sekarang. Selamat tinggal…",
  ui_story_10_15_1_138_dialog_content = "Ya, selamat tinggal…",
  ui_story_10_15_1_139_dialog_content = "Jaga dirimu baik-baik ya? Suatu hari nanti, kita akan bertemu lagi!",
  ui_story_10_15_1_140_dialog_content = "Ya! Sampai jumpa lagi…",
  ui_story_10_15_1_141_dialog_content = "Bagaimana caranya aku bisa sampai ke titik ini?",
  ui_story_10_15_1_142_dialog_content = "Pada awalnya, kurasa itu karena… mimpi itu.",
  ui_story_10_15_1_143_dialog_content = "\"Hiduplah…\"",
  ui_story_10_15_1_144_dialog_content = "Apa kau melihat <color=#FFB400>mimpi itu</color> lagi?",
  ui_story_10_15_1_145_dialog_content = "Ya.",
  ui_story_10_15_1_146_dialog_content = "Mimpi adalah visualisasi dari hal-hal tak diketahui yang dihadirkan oleh pikiran. Itu hanya ilusi.",
  ui_story_10_15_1_147_dialog_content = "Lalu kemudian… Mendelson meninggal.",
  ui_story_10_15_1_148_dialog_content = "Hari itu, 17 tahun lalu, aku menerima <color=#FFB400>Kekuatan Eclipsite</color> agar bisa bertahan hidup.",
  ui_story_10_15_1_149_dialog_content = "Aku ingin bisa melihat langit, meski hanya sekali untuk terakhir kalinya…",
  ui_story_10_15_1_150_dialog_content = "Lalu tak lama setelahnya, aku melihat Schummer mati di depan mataku…",
  ui_story_10_15_1_151_dialog_content = "(Terkutuklah kau…)",
  ui_story_10_15_1_152_dialog_content = "(PlayerName…)",
  ui_story_10_15_1_153_dialog_content = "Itu sama sekali bukan mimpi, itu semua nyata…",
  ui_story_10_15_1_154_dialog_content = "Soroz…",
  ui_story_10_15_1_155_dialog_content = "Aku berhasil mendapatkan Think Tank Module, tapi aku tak tahu… apakah kau punya sistem untuk menghubungkan komponen ini dengan…",
  ui_story_10_15_1_156_dialog_content = "Lagi pula, kau kan Colossus Level 6, dan walaupun orang-orang bilang begitu…",
  ui_story_10_15_1_E1_dialog_content = "…",
  ui_story_10_15_1_E2_dialog_content = "Sebaiknya kusimpan keluhanku sampai kau kembali.",
  ui_story_10_15_1_157_dialog_content = "Ketiga colokan di Think Tank Module ini…",
  ui_story_10_15_1_158_dialog_content = "Semuanya tampak sama.",
  ui_story_10_15_1_159_dialog_content = "…",
  ui_story_10_15_1_160_dialog_content = "<color=#e8d9bb>Kontrol Utama normal.</color>",
  ui_story_10_15_1_161_dialog_content = "<color=#e8d9bb>Modul biologis sedang hibernasi.</color>",
  ui_story_10_15_1_162_dialog_content = "<color=#e8d9bb>Bantuan hidup beroperasi. Kapasitas saat ini: 1 orang.</color>",
  ui_story_10_15_1_163_dialog_content = "<color=#e8d9bb>Kondisi mesin normal.</color>",
  ui_story_10_15_1_164_dialog_content = "<color=#e8d9bb>Think Tank Module terdeteksi. Menghubungkan…</color>",
  ui_story_10_15_1_165_dialog_content = "<color=#e8d9bb>1%… 3%… 8%…</color>",
  ui_story_10_15_1_166_dialog_content = "Jadi…",
  ui_story_10_15_1_167_dialog_content = "Rupanya beginilah akhirnya, ya?",
  ui_story_10_15_1_168_dialog_content = "Hampir tak ada yang tersisa dari mayat Schummer…",
  ui_story_10_15_1_169_dialog_content = "Ya… PlayerName bahkan tak mau memeriksanya.",
  ui_story_10_15_1_170_dialog_content = "Kurasa dengan kemampuan psikisnya, PlayerName bisa merasakan bahwa Schummer memang sudah mati.",
  ui_story_10_15_1_171_dialog_content = "Yah, karena dia sudah mati, sekarang kita tak perlu memikirkan dia lagi.",
  ui_story_10_15_1_172_dialog_content = "Tapi… apa kita benar-benar bisa melakukan itu?",
  ui_story_10_15_1_173_dialog_content = "Schummer memang sudah mati, tapi para Eclipsite yang menghancurkan Eraveil…",
  ui_story_10_15_1_174_dialog_content = "Mereka masih ada di seluruh penjuru dunia.",
  ui_story_10_15_1_175_dialog_content = "Belum lagi, masih ada Eclipsite yang sempat disebutkan PlayerName, si <color=#FFB400>Figerald</color> itu.",
  ui_story_10_15_1_176_dialog_content = "Tapi pada akhirnya, PlayerName tidak menanyakan siapa sebenarnya Figerald itu.",
  ui_story_10_15_1_177_dialog_content = "Ada begitu banyak yang terjadi dalam waktu singkat…",
  ui_story_10_15_1_178_dialog_content = "Mungkin PlayerName sekadar tidak sempat menanyakannya.",
  ui_story_10_15_1_179_dialog_content = "Setelah melihat Schummer mati, PlayerName tampak terbengong-bengong.",
  ui_story_10_15_1_180_dialog_content = "PlayerName sadar tak lama setelah itu, tapi rasanya, masih ada yang tidak beres dengannya.",
  ui_story_10_15_1_181_dialog_content = "Mungkin PlayerName tidak ingin kita mengkhawatirkannya, dan karenanya dia bersikap seperti biasa.",
  ui_story_10_15_1_182_dialog_content = "Atau mungkin, sekarang PlayerName sedang fokus pada hal lain yang lebih penting…",
  ui_story_10_15_1_183_dialog_content = "Apa pun itu, aku yakin PlayerName tak akan ragu meminta bantuan kita kalau memang perlu.",
  ui_story_10_15_1_184_dialog_content = "Hmm… Kau benar.",
  ui_story_10_15_1_185_dialog_content = "Omong-omong, PlayerName sudah cukup lama di dalam Soroz dan belum juga keluar…",
  ui_story_10_15_1_186_dialog_content = "Aku agak khawatir…",
  ui_story_10_15_1_187_dialog_content = "PlayerName ingin membawa komponennya ke dalam sendirian, aku yakin dia punya alasan kuat.",
  ui_story_10_15_1_188_dialog_content = "Coba kita tunggu sebentar lagi…",
  ui_story_10_15_1_189_dialog_content = "Baiklah…",
  ui_story_10_15_1_190_dialog_content = "<color=#e8d9bb>10%… 23%…</color>",
  ui_story_10_15_1_191_dialog_content = "<color=#e8d9bb>33%… 35%…</color>",
  ui_story_10_15_1_192_dialog_content = "<color=#e8d9bb>Koneksi gagal. Jumlah Kegagalan: 1</color>",
  ui_story_10_15_1_193_dialog_content = "Tak apa. Coba saja lagi…",
  ui_story_10_15_1_194_dialog_content = "Hubungkan Think Tank Module…",
  ui_story_10_15_1_195_dialog_content = "<color=#e8d9bb>Think Tank Module terdeteksi. Menghubungkan…</color>",
  ui_story_10_15_1_196_dialog_content = "<color=#e8d9bb>1%… 3%… 8%…</color>",
  ui_story_10_15_1_197_dialog_content = "<color=#e8d9bb>61%… 67%…</color>",
  ui_story_10_15_1_198_dialog_content = "<color=#e8d9bb>76%… 85%…</color>",
  ui_story_10_15_1_199_dialog_content = "<color=#e8d9bb>Koneksi gagal. Jumlah Kegagalan: 2</color>",
  ui_story_10_15_1_200_dialog_content = "Ini cuma kegagalan kedua. Ingat berapa kali aku harus mencoba mengaktifkan mesinmu?",
  ui_story_10_15_1_201_dialog_content = "Aku mencobanya sampai lebih dari tiga ribu kali.",
  ui_story_10_15_1_202_dialog_content = "Tidak apa-apa…",
  ui_story_10_15_1_203_dialog_content = "Lagi. Ayo coba lagi.",
  ui_story_10_15_1_204_dialog_content = "Ulang dari langkah paling pertama, lalu coba lagi.",
  ui_story_10_15_1_205_dialog_content = "<color=#e8d9bb>Kontrol Utama normal.</color>",
  ui_story_10_15_1_206_dialog_content = "<color=#e8d9bb>Modul biologis sedang hibernasi.</color>",
  ui_story_10_15_1_207_dialog_content = "<color=#e8d9bb>Echo Template rusak.</color>",
  ui_story_10_15_1_208_dialog_content = "<color=#e8d9bb>Bantuan hidup beroperasi. Kapasitas saat ini: 1 orang.</color>",
  ui_story_10_15_1_209_dialog_content = "<color=#e8d9bb>Generator normal.</color>",
  ui_story_10_15_1_210_dialog_content = "<color=#e8d9bb>Think Tank Module terdeteksi. Menghubungkan…</color>",
  ui_story_10_15_1_211_dialog_content = "<color=#e8d9bb>1%… 3%… 8%…</color>",
  ui_story_10_15_1_212_dialog_content = "<color=#e8d9bb>10%… 25%…</color>",
  ui_story_10_15_1_213_dialog_content = "…",
  ui_story_10_15_1_214_dialog_content = "…",
  ui_story_10_15_1_215_dialog_content = "Cukup, ayo kita lihat kondisi di dalam!",
  ui_story_10_15_1_216_dialog_content = "Setidaknya, kita harus memeriksa kondisi PlayerName!",
  ui_story_10_15_1_217_dialog_content = "Kalau kaulakukan itu, kau mungkin justru akan membuat PlayerName terganggu, Vice.",
  ui_story_10_15_1_218_dialog_content = "Aku tahu, tapi…",
  ui_story_10_15_1_219_dialog_content = "Kalau Think Tank Module tidak bisa dihubungkan ke Colossus…",
  ui_story_10_15_1_220_dialog_content = "Kalau tidak ada cara untuk memperbaiki Soroz…",
  ui_story_10_15_1_221_dialog_content = "Aku tak ingin PlayerName menghadapi itu sendirian.",
  ui_story_10_15_1_222_dialog_content = "Aku cuma akan memeriksa PlayerName! Aku janji aku akan berusaha sebisa mungkin agar tidak mengganggunya!",
  ui_story_10_15_1_223_dialog_content = "*Menghela napas* Nah.",
  ui_story_10_15_1_224_dialog_content = "Kalau kau sekhawatir itu, kenapa tidak panggil saja dia dari pintu masuk?",
  ui_story_10_15_1_225_dialog_content = "PlayerName itu seorang Caelestite. Berkat indera Caelestite yang tajam dan kemampuan psikis mereka…",
  ui_story_10_15_1_226_dialog_content = "Aku yakin PlayerName akan bisa mendengarmu.",
  ui_story_10_15_1_227_dialog_content = "Dengan begitu, kamu tak akan menghalangi keinginan PlayerName untuk masuk sendirian.",
  ui_story_10_15_1_228_dialog_content = "Benar juga! Akan kulakukan itu!",
  ui_story_10_15_1_229_dialog_content = "Kau memang bisa diandalkan untuk memikirkan ide brilian, Carleen!",
  ui_story_10_15_1_230_dialog_content = "Kau ini omong apa sih… Aku kan mempelajarinya darimu…",
  ui_story_10_15_1_231_dialog_content = "*Menarik napas*",
  ui_story_10_15_1_232_dialog_content = "PlayerName!",
  ui_story_10_15_1_233_dialog_content = "<color=#e8d9bb>89%… 97%…</color>",
  ui_story_10_15_1_234_dialog_content = "<color=#e8d9bb>100%. Koneksi berhasil.</color>",
  ui_story_10_15_1_235_dialog_content = "<color=#e8d9bb>Terima kasih sudah menggunakan Think Tank Module.</color>",
  ui_story_10_15_1_236_dialog_content = "Vice! Carleen!",
  ui_story_10_15_1_237_dialog_content = "Koneksinya berhasil! Aku menemukan cara untuk memperbaiki Echo Template!",
  ui_story_10_15_1_238_dialog_content = "Kurasa aku bisa menyelamatkan Soroz!",
  ui_story_10_15_1_239_dialog_content = "Jadi maksudmu…",
  ui_story_10_15_1_240_dialog_content = "Caelestite bernama PlayerName itu berhasil mengalahkan Schummer, si Caelestite pengkhianat itu?",
  ui_story_10_15_1_241_dialog_content = "Lalu setelah itu, Caelestite itu membiarkan Rediesel Wrench membawa Black Colossus?",
  ui_story_10_15_1_242_dialog_content = "Forsakin bukan hanya gagal menghentikan mereka, tapi bahkan juga membantu mereka mencapai tujuan mereka. Benar begitu?",
  ui_story_10_15_1_243_dialog_content = "Ya.",
  ui_story_10_15_1_244_dialog_content = "Apa menurutmu Caelestite itu akan mengganggu rencana kita?",
  ui_story_10_15_1_245_dialog_content = "Tidak, PlayerName hanya akan membuatnya jadi makin menarik.",
  ui_story_10_15_1_246_dialog_content = "Aku yakin Schwartz juga akan merasa begitu.",
  ui_story_70000101_1_dialog_content = "<color=#e8d9bb>\"Menjalankan diagnosis mandiri.\"</color>",
  ui_story_70000101_2_dialog_content = "<color=#e8d9bb>\"Pemeriksaan sistem kendali utama… Berjalan. Integritas komponen berkurang sebesar 39%. Pemeliharaan dibutuhkan.\"</color>",
  ui_story_70000101_3_dialog_content = "<color=#e8d9bb>\"Pemeriksaan modul biologis… Berjalan. Integritas modul berkurang sebesar 46%. Pemeliharaan dibutuhkan.\"</color>",
  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>\"Pemeriksaan sistem Life Support… Berjalan. Peringatan: Pemuatan penuh. Pemeliharaan dibutuhkan.\"</color>",
  ui_story_70000101_5_dialog_content = "<color=#e8d9bb>\"Pemeriksaan sistem pemeliharaan… Normal. Mengaktifkan…\"</color>",
  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>\"Eror: Echo Template hilang. Fungsi pemeliharaan tidak bisa diaktifkan.\"</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>\"Gagal memulai. Jumlah Kegagalan: 1.012.\"</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>\"Harap menginstal Echo Template untuk mengakses fungsi pemeliharaan.\"</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>\"Peringatan: Fungsi relevan tak akan bisa diakses lagi jika integritas komponen berkurang sebesar 50%.\"</color>",
  ui_story_70000101_10_dialog_content = "<color=#e8d9bb>\"Silakan tanda tangani dan konfirmasikan.\"</color>",
  ui_story_70000101_11_dialog_content = "Soroz…",
  ui_story_70000101_12_dialog_content = "PlayerName, bagaimana keadaan Soroz?",
  ui_story_70000101_13_dialog_content = "…",
  ui_story_70000101_14_dialog_content = "Masih sama. Echo Template masih belum ditemukan. Tak mampu melakukan fungsi pemeliharaan mandiri. Situasinya mengenaskan.",
  ui_story_70000101_15_dialog_content = "Seharusnya aku memperbaiki Soroz secepatnya… tapi aku malah melakukan hal-hal lain dulu.",
  ui_story_70000101_16_dialog_content = "Ini bukan salahmu. Aku kan juga bertanggung jawab karena tak sadar ada yang tidak beres dengannya, padahal aku sudah lama tinggal di sini.",
  ui_story_70000101_17_dialog_content = "Tapi, jangan terlalu khawatir. Kita sudah dapat solusinya, 'kan?",
  ui_story_70000101_18_dialog_content = "Aku menemukan beberapa petunjuk!",
  ui_story_70000101_19_dialog_content = "Kita mendapat himpunan koordinat dari Think Tank Module, tapi… di mana lokasinya?",
  ui_story_70000101_20_dialog_content = "Boleh kulihat?",
  ui_story_70000101_21_dialog_content = "Koordinatnya ada di <color=#FFB400>Dark Zone</color>?",
  ui_story_70000101_22_dialog_content = "Kalau tidak salah… itu kan lokasi <color=#FFB400>Undercity 80</color>.",
  ui_story_70000101_23_option_content = "Dark Zone…?",
  ui_story_70000101_24_option_content = "Undercity 80…?",
  ui_story_70000101_25_dialog_content = "Dark Zone mencakup wilayah-wilayah di dekat Eternal Night.",
  ui_story_70000101_26_dialog_content = "Dan koordinat itu mengarah ke lokasi Undercity 80.",
  ui_story_70000101_27_dialog_content = "Dark Zone adalah tempat yang berbahaya.",
  ui_story_70000101_28_dialog_content = "Di sana, durasi siangnya sangat singkat dan malamnya sangat panjang. Konon, tempat itu juga jadi tempat berkumpulnya Eclipsite.",
  ui_story_70000101_29_dialog_content = "Hei, kau di sana, PlayerName?",
  ui_story_70000101_30_dialog_content = "Hah? Panggilan dari Sheol…?",
  ui_story_70000101_31_dialog_content = "Kudengar kau sedang menyelidiki Dark Zone. Kebetulan aku punya informasi intel.",
  ui_story_70000101_32_dialog_content = "Hah? Kenapa kau tahu?",
  ui_story_70000101_33_dialog_content = "Pedagang Umbraton selalu pasang telinga kalau ada kesempatan bisnis.",
  ui_story_70000101_34_dialog_content = "Baiklah. Pasti kau tahu dari \"jaringan intelijen khusus\" punyamu, 'kan?",
  ui_story_70000101_35_dialog_content = "Wah, kau memang mengenalku, ya.",
  ui_story_70000101_X35_dialog_content = "Karena aku sedang baik hati, akan kuberikan sebagian info intel untukmu secara cuma-cuma.",
  ui_story_70000101_36_dialog_content = "Himpunan koordinat itu ada di suatu tempat bernama <color=#FFB400>Mire</color>. Tempat itu sangat berbahaya.",
  ui_story_70000101_37_dialog_content = "… Meski begitu, aku masih tetap menuju ke sana.",
  ui_story_70000101_38_dialog_content = "Hanya ini petunjuk dari Think Tank Module. Mana mungkin aku duduk-duduk saja di sini dan membiarkan Soroz rusak.",
  ui_story_70000101_39_dialog_content = "PlayerName, berpikirlah dengan otakmu, bukan hatimu.",
  ui_story_70000101_40_dialog_content = "Bukan langkah yang bijaksana kalau kau pergi ke Mire tanpa informasi intel dan persiapan.",
  ui_story_70000101_41_dialog_content = "…",
  ui_story_70000101_42_dialog_content = "Itu benar. Saya setuju.",
  ui_story_70000101_43_dialog_content = "Tapi, kalau kau mau melakukan sesuatu untukku sebagai gantinya… aku mau-mau saja mencarikan informasi intel yang relevan untukmu…",
  ui_story_70000101_44_dialog_content = "Huh… Nightium lagi, ya?",
  ui_story_70000101_45_dialog_content = "Seharusnya Lumopolis punya informasi soal wilayah itu.",
  ui_story_70000101_46_dialog_content = "Bisa kuperiksa.",
  ui_story_70000101_47_dialog_content = "Kalu begitu, kuserahkan padamu. Tolong aku, ya.",
  ui_story_70000101_48_dialog_content = "Aku sudah memeriksa Soroz lagi. Dia masih berfungsi, kok. Saat ini, tak ada yang perlu dicemaskan.",
  ui_story_70000101_49_dialog_content = "Sudah cukup lama. Tak lama lagi, Carleen dan Sheol seharusnya kembali dengan informasi intel itu.",
  ui_story_70000101_50_dialog_content = "Aku juga sudah bertanya kepada orang-orang Illumina untuk mencari lebih banyak petunjuk. Santailah sedikit.",
  ui_story_70000101_51_dialog_content = "Semoga mereka menemukan informasi yang berguna karena…",
  ui_story_70000101_52_dialog_content = "Itu satu-satunya cara untuk menyelamatkan Soroz.",
  ui_story_70000101_53_dialog_content = "Kalau himpunan koordinat ini akurat, sayangnya kita harus mencarinya di seantero Undercity.",
  ui_story_70000101_54_dialog_content = "Bahkan akan butuh waktu berhari-hari untuk memeriksa Undercity terkecil sekalipun.",
  ui_story_70000101_55_dialog_content = "Memangnya kita tak punya lokasi yang lebih detail?",
  ui_story_70000101_56_dialog_content = "Tidak. Sekarang sih hanya ini yang kita punya.",
  ui_story_70000101_57_dialog_content = "Mungkin kalau kita bisa mendekati target…",
  ui_story_70000101_58_dialog_content = "Apa kau bisa dengar aku, PlayerName?",
  ui_story_70000101_59_dialog_content = "Carleen! Ya, aku bisa mendengarmu!",
  ui_story_70000101_60_dialog_content = "Bagus. Aku sedang di perpustakaan Dawn Academy. Di sini sinyalnya buruk, jadi aku akan bicara dengan singkat saja.",
  ui_story_70000101_61_dialog_content = "Di sini ada beberapa catatan mengenai perang lama di Undercity 80.",
  ui_story_70000101_62_dialog_content = "Nah, menurut catatan-catatan itu, dulunya Undercity 80 adalah pos jaga terdepan dan pusat transportasi Illumina.",
  ui_story_70000101_63_dialog_content = "Karena sangat dekat dengan Eternal Night, tempat itu dulunya dijadikan sebagai medan tempur Illumina Federation dan Eclipsite.",
  ui_story_70000101_64_dialog_content = "Namun, selama <color=#FFB400>Dark Zone War</color>, lokasinya yang terpencil membuat bala bantuan untuk melawan serangan sengit Eclipsite sulit diterjunkan.",
  ui_story_70000101_65_dialog_content = "Illumina pun melakukan evakuasi dan meninggalkan Undercity 80 tak lama kemudian.",
  ui_story_70000101_66_option_content = "Dark Zone War?",
  ui_story_70000101_67_dialog_content = "Aku pernah dengar tentang perang itu. Invasi Eclipsite berskala besar itu terjadi lebih dari dua puluh tahun yang lalu.",
  ui_story_70000101_68_dialog_content = "Pasukan Eclipsite dalam jumlah besar menyerang dari Eternal Night… Itu perang yang brutal.",
  ui_story_70000101_69_dialog_content = "Meski pada akhirnya Illumina Federation berhasil memenangkan perang itu, tak terhitung banyaknya Undercity dan tentara yang jadi korbannya.",
  ui_story_70000101_70_dialog_content = "Di sini juga tertulis demikian.",
  ui_story_70000101_71_dialog_content = "Saat Illumina mundur, banyak perlengkapan yang tertinggal. Anda mungkin menemukan apa yang Anda butuhkan di sana.",
  ui_story_70000101_72_dialog_content = "Aku mengerti! Terima kasih banyak!",
  ui_story_70000101_73_dialog_content = "Bukan masalah. Akan kulakukan apa pun untuk membantumu.",
  ui_story_70000101_X74_dialog_content = "<color=#e8d9bb>Wuuuuuu… Wuuuuuu…</color>",
  ui_story_70000101_75_dialog_content = "Ada panggilan lain yang masuk? Halo?",
  ui_story_70000101_76_dialog_content = "Ini aku, PlayerName.",
  ui_story_70000101_77_dialog_content = "Hei, Sheol. Informasi apa yang kaudapat?",
  ui_story_70000101_X77_dialog_content = "Begini, aku mendapat informasi intel lagi… tapi ini bukan kabar baik.",
  ui_story_70000101_78_dialog_content = "Menurut informanku, tempat itu dipenuhi Eclipsite.",
  ui_story_70000101_79_dialog_content = "Kau tak akan bisa mendekati Mire tanpa Soroz.",
  ui_story_70000101_80_dialog_content = "Sementara itu, di Undercity… Tak ada apa-apa lagi yang tersisa selain reruntuhan yang menjadi penanda pertempuran di masa lampau.",
  ui_story_70000101_81_dialog_content = "Untuk sekarang, inti energinya masih berfungsi dengan baik, tapi kondisinya terganggu. Bahkan, inti energi itu pun tak sanggup lagi menjaga sistem pertahanan. Inti itu bisa mati sewaktu-waktu.",
  ui_story_70000101_82_dialog_content = "Satu-satunya orang yang cukup beruntung keluar hidup-hidup mengatakan bahwa satu-satunya jalan keluar masuk Undercity adalah…",
  ui_story_70000101_83_dialog_content = "<color=#FFB400>Jurang</color> yang disebabkan oleh reruntuhan.",
  ui_story_70000101_84_dialog_content = "Begitu rupanya.",
  ui_story_70000101_85_dialog_content = "Oke.",
  ui_story_70000101_86_dialog_content = "Semoga misimu berhasil.",
  ui_story_70000101_87_dialog_content = "Sebaiknya kau pulang hidup-hidup dan membayarku.",
  ui_story_70000101_88_dialog_content = "B-baiklah…",
  ui_story_70000101_89_dialog_content = "Aneh. Belum ada informasi intel dari Philyshy, ya?",
  ui_story_70000101_90_dialog_content = "<color=#e8d9bb>Bip… Bip…</color>",
  ui_story_70000101_91_dialog_content = "Hah? Ada pesan dari Philyshy.",
  ui_story_70000101_92_dialog_content = "Apa isinya? Sini, biar kulihat.",
  ui_story_70000101_93_dialog_content = "<color=#FFB400>Panduan Pertempuran Dark Zone?</color>",
  ui_story_70000101_94_option_content = "Kau punya yang seperti itu?",
  ui_story_70000101_95_dialog_content = "Aku malah tak ingat ada benda seperti itu…",
  ui_story_70000101_96_dialog_content = "Kelihatannya kok jelek dan murahan, sih…",
  ui_story_70000101_97_dialog_content = "Jangankan ada indeksnya, formatnya saja tak resmi begini.",
  ui_story_70000101_98_dialog_content = "Sepertinya tidak terlihat autentik.",
  ui_story_70000101_99_dialog_content = "Mencurigakan sekali…",
  ui_story_70000101_100_dialog_content = "Mana mungkin Philyshy memberi informasi intel semacam ini.",
  ui_story_70000101_101_option_content = "Tapi, Philyshy bahkan bilang mau membantu?",
  ui_story_70000101_102_dialog_content = "Kok tumben, ya.",
  ui_story_70000101_103_dialog_content = "Bukan itu sih intinya… Tapi, sepertinya tak ada salahnya kalau aku memberitahumu…",
  ui_story_70000101_104_dialog_content = "Begini, Philyshy memintaku untuk merahasiakan bahwa dia bolos kerja agar bisa tidur siang…",
  ui_story_70000101_105_dialog_content = "Dia bersedia memberi kita informasi intel tentang Undercity 80 agar aku tetap mau tutup mulut.",
  ui_story_70000101_106_dialog_content = "Nah, itu baru Philshy…",
  ui_story_70000101_107_dialog_content = "Philyshy kan memang selalu punya informasi intel yang paling bisa diandalkan.",
  ui_story_70000101_108_dialog_content = "Tapi… kenapa panduannya kelihatan sangat murahan begini, sih?",
  ui_story_70000101_109_dialog_content = "Memangnya apa isinya?",
  ui_story_70000101_110_dialog_content = "\"Peraturan Pertama Pertempuran Dark Zone\"",
  ui_story_70000101_111_dialog_content = "\"Hindari pertempuran di Dark Zone kecuali jika benar-benar perlu!\"",
  ui_story_70000101_112_dialog_content = "Apa?!",
  ui_story_70000101_113_dialog_content = "Dark Zone adalah tempat yang berbahaya…?",
  ui_story_70000101_114_dialog_content = "\"Menurut informasi intel yang diketahui, Dark Zone adalah wilayah yang sangat berbahaya.\"",
  ui_story_70000101_115_dialog_content = "\"Darkflow yang terkonsentrasi menghambat pergerakan Aurorian, dan efeknya bahkan lebih berat di malam hari.\"",
  ui_story_70000101_116_dialog_content = "\"Dark Zone adalah rumah bagi Eclipsite, dan Eclipsite yang kuat menghuninya. Tempat itu sangat berbahaya!\"",
  ui_story_70000101_117_dialog_content = "Illumina Soldier dilarang masuk… Apa itu akan mempersulit keadaan?",
  ui_story_70000101_119_dialog_content = "Aku tak bisa membuatmu terseret ke dalam masalah.",
  ui_story_70000101_120_dialog_content = "Mungkin aku bisa meminta bantuan Hiiro!",
  ui_story_70000101_121_dialog_content = "PlayerName…",
  ui_story_70000101_122_dialog_content = "Aku tak keberatan, kok.",
  ui_story_70000101_123_dialog_content = "Soroz sangat berarti bagi kami berdua.",
  ui_story_70000101_124_dialog_content = "Mana mungkin aku bakal tinggal diam kalau teman-temanku membutuhkanku.",
  ui_story_70000101_125_dialog_content = "Selain itu, aku kan sudah terlibat. Kalau tidak melaporkannya, aku akan dianggap melakukan kejahatan oleh Illumina Military.",
  ui_story_70000101_126_dialog_content = "Asalkan kita tak memberi tahu Grand Marshal dan Legion Commander… seharusnya tak apa-apa, sih.",
  ui_story_70000101_127_dialog_content = "Semua pasti akan baik-baik saja!",
  ui_story_70000101_128_dialog_content = "Maaf karena kau jadi terlibat…",
  ui_story_70000101_129_dialog_content = "Panduan ini sepertinya menjelaskan pertempuran di Dark Zone dengan mendetail…",
  ui_story_70000101_130_dialog_content = "Tapi, siapa sih yang menulisnya…?",
  ui_story_70000101_131_dialog_content = "Lain kali saja cari tahunya.",
  ui_story_70000101_132_dialog_content = "Sekarang, prioritas kita adalah menyusun rencana berdasarkan informasi intel.",
  ui_story_70000101_133_dialog_content = "Eclipsite dalam jumlah besar, Darkflow yang lebih kuat pada malam hari… dan durasi malamnya yang panjang…",
  ui_story_70000101_134_dialog_content = "Ini akan jadi misi yang sulit.",
  ui_story_70000101_135_dialog_content = "Kita bisa menggunakan Soroz untuk terbang langsung ke lokasi target, melewati sebagian besar Eclipsite dalam perjalanan.",
  ui_story_70000101_136_dialog_content = "Nah, saat memasuki Undercity, kita akan menggunakan Think Tank Module untuk menemukan target.",
  ui_story_70000101_137_dialog_content = "Kalau pertempurannya terus berjalan singkat, kita bisa menyelesaikan misi ini sebelum senja.",
  ui_story_70000101_138_dialog_content = "Tapi, risikonya tetap tinggi, lo. Bagaimana kalau kita disergap High-Level Eclipsite di bawah tanah?",
  ui_story_70000101_139_dialog_content = "Nah, kita kitari saja mereka. Pokoknya, kita harus menghindari pertempuran dengan cara apa pun. Begitu modulnya ketemu, kita akan langsung mundur.",
  ui_story_70000101_140_dialog_content = "Aku mengerti.",
  ui_story_70000101_141_dialog_content = "Baiklah kalau begitu. Ayo berangkat. Tujuan: Undercity 80!",
  ui_story_70000101_142_dialog_content = "<color=#e8d9bb>Illumina Safe Line</color>",
  ui_story_70000101_143_dialog_content = "Soroz akan melewati jalur aman, menuju ke Undercity 80.",
  ui_story_70000101_144_dialog_content = "Kau… benar-benar mau mengizinkan mereka lewat?",
  ui_story_70000101_145_dialog_content = "Hm? Kau mengatakan sesuatu kepadaku?",
  ui_story_70000101_146_dialog_content = "Y-Ya… Kau adalah Grand Marshal. Ini keputusanmu.",
  ui_story_70000101_147_dialog_content = "Karena kau tahu bahwa mereka meminta Philyshy menyelidiki Undercity 80, kau pasti paham tujuan mereka.",
  ui_story_70000101_148_dialog_content = "Iya. PlayerName mendapatkan informasi intel bahwa ada benda teknologi kuno yang bisa memperbaiki Echo Template Colossus di Undercity 80.",
  ui_story_70000101_149_dialog_content = "Menurutmu, kenapa dia mencarinya?",
  ui_story_70000101_150_dialog_content = "Colossus yang dia gunakan, Soroz, kehilangan Echo Template saat bertempur dengan Schummer dan Forsakin…",
  ui_story_70000101_151_dialog_content = "Colossus adalah keluarganya. Bagi Colossus, kehilangan Echo Template itu mungkin seperti kehilangan nyawanya.",
  ui_story_70000101_152_dialog_content = "Nah, kalau menurutmu begitu…",
  ui_story_70000101_153_dialog_content = "Apa aku punya alasan untuk mencegah seseorang menyelamatkan keluarganya?",
  ui_story_70000101_154_dialog_content = "Dia tak punya niat buruk. Jadi, biar kuabaikan saja kali ini.",
  ui_story_70000101_155_dialog_content = "Anggap saja ini sebagai bayaran karena dia sudah membantu kita melawan Eclipsite.",
  ui_story_70000101_156_dialog_content = "Tapi, bagaimana cara menjelaskannya kepada Committee? Mereka kan melarang siapa pun menjelajahi Dark Zone, terutama kau, Grand Marshal.",
  ui_story_70000101_157_dialog_content = "Yah, itu memang jadi masalah…",
  ui_story_70000101_158_dialog_content = "Begini saja. Katakan kepada mereka bahwa Caelestite itu pergi ke Dark Zone tanpa izin. Kita sudah mencoba untuk mencegatnya, tapi gagal.",
  ui_story_70000101_159_dialog_content = "Karena batasan dari Committee, pasukan kita tak bisa melakukan pengejaran hingga ke luar jalur aman.",
  ui_story_70000101_160_dialog_content = "Caelestite itu bukan warga Illumina, dia terhubung dengan semua faksi.",
  ui_story_70000101_161_dialog_content = "Aku yakin Committee tak akan menindaknya hanya karena alasan itu saja.",
  ui_story_70000101_162_dialog_content = "Tapi, Grand Marshal, aku tetap merasa di sana sangat berbahaya.",
  ui_story_70000101_163_dialog_content = "Mereka sudah banyak makan asam garam dalam pertempuran. Mereka pasti bisa menangani bahayanya.",
  ui_story_70000101_164_dialog_content = "Asalkan mereka berhati-hati… dan mematuhi Panduan itu. Seharusnya mereka akan baik-baik saja.",
  ui_story_70000101_165_dialog_content = "Kalau begitu… kenapa kita di sini?",
  ui_story_70000101_166_dialog_content = "Meski punya kemampuan tempur yang mumpuni, mereka akan butuh hal lain agar bisa keluar hidup-hidup…",
  ui_story_70000101_167_dialog_content = "Misalnya, tali pengaman untuk menarik mereka keluar dari Mire jika dibutuhkan.",
  ui_story_70000101_168_dialog_content = "Tetaplah waspada dan terus pantau Dark Zone.",
  ui_story_70000101_169_dialog_content = "Baik, Grand Marshal.",
  ui_story_70000101_170_dialog_content = "Philyshy?",
  ui_story_70000101_171_dialog_content = "Meong!?",
  ui_story_70000101_172_dialog_content = "Untuk sekarang, aku akan mengamankan terminal komunikasimu.",
  ui_story_70000101_173_dialog_content = "Soal bolos kerja yang kaulakukan… Kita bahas kalau semua sudah selesai.",
  ui_story_70000101_174_dialog_content = "Begitu rupanya.",
  ui_story_70000101_175_dialog_content = "Nah, sekarang, pantau Undercity 80 dan beri tahu aku kalau situasinya berubah.",
  ui_story_70000101_176_dialog_content = "Siap, Pak…",
  ui_story_70000101_177_dialog_content = "Vice… sekarang kau dalam masalah besar…",
  ui_story_70000101_178_dialog_content = "Undercity 80…",
  ui_story_70000101_179_dialog_content = "Bukan tempat untuk sembarang orang. Mereka berdua memang nekat.",
  ui_story_70000201_1_dialog_content = "Kita sudah melewati jalur aman di dekat perbatasan Eternal Night yang dibuat oleh Illumina Federation.",
  ui_story_70000201_2_dialog_content = "Sebentar lagi kita akan sampai di Undercity 80.",
  ui_story_70000201_3_dialog_content = "Makin gelap. Ini Dark Zone, ya?",
  ui_story_70000201_4_dialog_content = "Lingkungannya benar-benar membuatku tak nyaman. Rasanya aku bernapas hanya dengan sebelah paru-paru saja…",
  ui_story_70000201_5_dialog_content = "Semoga kemampuan tempur kita tak terpengaruh…",
  ui_story_70000201_6_dialog_content = "Bagaimana kata Panduan?",
  ui_story_70000201_7_dialog_content = "Biar kulihat…",
  ui_story_70000201_8_dialog_content = "\"Peraturan ke-3: Hindari pertempuran dengan cara apa pun di Mire. Ketahuilah kapan harus keluar.\"",
  ui_story_70000201_9_dialog_content = "\"Undercity 80 juga dikenal sebagai Mire karena Darkflow-nya yang sangat pekat membuat kita sulit bernapas.\"",
  ui_story_70000201_10_dialog_content = "\"Tidak hanya sangat mengganggu sinyal komunikasi, Darkflow bahkan bisa sepenuhnya melumpuhkannya hanya dari jarak beberapa meter.\"",
  ui_story_70000201_11_dialog_content = "\"Dampak negatif dari Darkflow makin kuat seiring waktu.\"",
  ui_story_70000201_12_dialog_content = "\"Dampak negatifnya juga akan meningkat setidaknya 2 kali lipat pada malam hari.\"",
  ui_story_70000201_13_dialog_content = "Berarti, Eclipsite biasa saja bahkan akan sulit ditangani.",
  ui_story_70000201_14_dialog_content = "Sepertinya kita memang benar-benar harus menghindari pertempuran, ya.",
  ui_story_70000201_15_dialog_content = "Waktu kita tak banyak. Situasinya akan makin buruk pada malam hari.",
  ui_story_70000201_16_dialog_content = "Kalau begitu, kita harus mengandalkan mobilitas Soroz untuk memasukinya pada siang hari, dan segera menyelesaikannya.",
  ui_story_70000201_17_dialog_content = "PlayerName… kau kelihatan lebih bisa diandalkan, deh.",
  ui_story_70000201_18_dialog_content = "Ah, masa?",
  ui_story_70000201_19_dialog_content = "Aku jadi malu.",
  ui_story_70000201_20_dialog_content = "Tapi, ada sesuatu yang kupikirkan, sih.",
  ui_story_70000201_21_dialog_content = "Siapa pun yang menulis Panduan itu jelas sangat mengenal Undercity 80. Apa jangan-jangan dia veteran perang, ya?",
  ui_story_70000201_22_dialog_content = "Yah, mana kita tahu…",
  ui_story_70000201_23_dialog_content = "Panduan ini tidak resmi. Bahkan nama penulisnya pun tak ada.",
  ui_story_70000201_24_dialog_content = "Malah tampak seperti daftar hal penting yang ditulis oleh komandan di garis depan untuk bala tentaranya.",
  ui_story_70000201_25_dialog_content = "Aneh…",
  ui_story_70000201_26_dialog_content = "Tapi, ini kan dari Philyshy. Aku yakin kita bisa memercayainya.",
  ui_story_70000201_27_dialog_content = "Semoga kita tidak mengalami kesulitan di Dark Zone.",
  ui_story_70000201_28_dialog_content = "PlayerName, lihat!",
  ui_story_70000201_29_dialog_content = "Itu Undercity 80?",
  ui_story_70000201_30_dialog_content = "Kita sudah sampai, nih?",
  ui_story_70000201_31_dialog_content = "Kok tidak seperti yang kubayangkan, ya…",
  ui_story_70000201_32_dialog_content = "Seingatku, semua Undercity di Illumina dilengkapi dengan tembok tebal dan amunisi senapan dalam jumlah besar…",
  ui_story_70000201_33_dialog_content = "Tapi, di sini hanya ada puing-puing dan bangunan runtuh dengan lubang peluru di sana-sini… dan senjata rusak yang dibuang.",
  ui_story_70000201_34_dialog_content = "Rasanya tempat ini jadi binasa karena perang dan bencana…",
  ui_story_70000201_35_dialog_content = "Apa yang kita cari… benar-benar ada di sini?",
  ui_story_70000201_36_dialog_content = "Sudah kuduga. Dulu memang ada perang besar yang terjadi di sini, dan tempat ini sudah lama ditinggalkan…",
  ui_story_70000201_37_dialog_content = "Mungkin sekarang ini jadi sarang Eclipsite…",
  ui_story_70000201_38_dialog_content = "Suatu hari nanti, Illumina pasti akan mengambil kembali tempat ini.",
  ui_story_70000201_39_dialog_content = "Setiap Undercity mempunyai energi, sumber daya, dan teknologi yang berharga.",
  ui_story_70000201_40_dialog_content = "Illumina… tak mungkin menyerahkannya kepada Eclipsite.",
  ui_story_70000201_41_dialog_content = "…",
  ui_story_70000201_42_dialog_content = "Ada banyak Eclipsite di permukaan. Tak usah buang-buang waktu untuk melawan mereka.",
  ui_story_70000201_43_dialog_content = "Cari tempat yang sepi untuk mendarat. Kita akan menyelinap diam-diam.",
  ui_story_70000201_44_dialog_content = "Fajar sudah menyingsing. Seharusnya kita punya cukup waktu untuk menyelesaikan misi ini.",
  ui_story_70000201_45_dialog_content = "<color=#e8d9bb>Tak lama setelahnya…</color>",
  ui_story_70000201_46_dialog_content = "Ini pengaruh Darkflow, ya?",
  ui_story_70000201_47_dialog_content = "Tubuhku terasa sangat berat… rasanya seperti memanggul beban di punggung.",
  ui_story_70000201_48_dialog_content = "Sama… Baru beberapa langkah saja aku sudah mulai terengah-engah…",
  ui_story_70000201_49_dialog_content = "Ini pasti seperti yang tertulis di Panduan itu… dampak Dark Zone…",
  ui_story_70000201_50_dialog_content = "Hampir mustahil bisa bertarung dalam kondisi begini…",
  ui_story_70000201_51_dialog_content = "Ayo cari jalan masuknya dulu.",
  ui_story_70000201_52_dialog_content = "Semuanya runtuh. Kita tak mungkin bisa menemukan jalan masuk asli ke Undercity.",
  ui_story_70000201_53_dialog_content = "Hanya pelat baja bekas dengan tulisan \"80\" yang tercoreng itu yang membuktikan bahwa ini dulunya adalah Undercity milik Illumina.",
  ui_story_70000201_54_dialog_content = "Struktur utamanya rusak, tembok luar benar-benar runtuh, semua bingkai arsitekturnya bengkok…",
  ui_story_70000201_55_dialog_content = "Tempat ini pasti pernah diguncang gempa bumi berskala 9,0, atau diserang Elite Eclipsite selama 24 jam nonstop…",
  ui_story_70000201_56_dialog_content = "Kalau tidak, mana mungkin kerusakan pertahanan Undercity milik Illumina bisa separah ini.",
  ui_story_70000201_57_dialog_content = "Bagaimana gerbang depannya?",
  ui_story_70000201_58_dialog_content = "Sepenuhnya terkubur.",
  ui_story_70000201_59_dialog_content = "Rute ke area bawah tanah juga tak kelihatan.",
  ui_story_70000201_60_dialog_content = "Sepertinya kita memang harus mencari <color=#FFB400>jurang</color> yang Sheol bilang, ya.",
  ui_story_70000201_61_dialog_content = "*Meraung*",
  ui_story_70000201_62_dialog_content = "Awasi bagian samping, PlayerName!",
  ui_story_70000201_63_dialog_content = "Dari mana datangnya mereka!?",
  ui_story_70000201_64_dialog_content = "Sepertinya ada retakan atau semacamnya dari arah munculnya para Eclipsite itu!",
  ui_story_70000201_65_dialog_content = "Sepertinya kita tak bisa kabur dari pertempuran ini…",
  ui_story_70000201_66_dialog_content = "Vice, ikuti Panduan itu dan berhati-hatilah.",
  ui_story_70000201_67_dialog_content = "Siap!",
  ui_story_70000202_1_dialog_content = "*Mendengkur*",
  ui_story_70000202_2_dialog_content = "Sudah… selesai?",
  ui_story_70000202_3_dialog_content = "Kepalaku sakit, rasanya mau pecah…",
  ui_story_70000202_4_dialog_content = "Aku bahkan tak bisa melihat jejak cahaya lagi…",
  ui_story_70000202_5_dialog_content = "PlayerName?!",
  ui_story_70000202_6_dialog_content = "Aku tak apa-apa… Hanya mau pingsan.",
  ui_story_70000202_7_dialog_content = "Nah, mulai sekarang jangan menarik perhatian untuk menghindari masalah…",
  ui_story_70000202_8_dialog_content = "Tak kusangka situasinya bakal sesulit ini…",
  ui_story_70000202_9_dialog_content = "Aku tak boleh menyerah… Aku harus menyelamatkan Soroz…",
  ui_story_70000202_10_dialog_content = "Ayo kita periksa jurang itu.",
  ui_story_70000202_11_dialog_content = "Hmm…",
  ui_story_70000202_12_dialog_content = "Ini bukan jurang.",
  ui_story_70000202_13_dialog_content = "Ini tebing!",
  ui_story_70000202_14_dialog_content = "Aku hampir bisa melihat sesuatu yang berpijar di bawah sana.",
  ui_story_70000202_15_dialog_content = "Kelihatannya seperti lampu sinyal dari semacam mesin!",
  ui_story_70000202_16_dialog_content = "Kota ini masih berfungsi!?",
  ui_story_70000202_17_dialog_content = "Pipa ekstrusi itu harus berfungsi sebagai pijakan ...",
  ui_story_70000202_18_dialog_content = "Pada ketinggian ini, saya bisa membawa Anda dan mendarat di bawah.",
  ui_story_70000202_19_dialog_content = "Tapi, kita bakal butuh jalan keluar lain.",
  ui_story_70000202_20_dialog_content = "Pintu keluar... Apakah ada sesuatu tentang itu di Manual?",
  ui_story_70000202_21_dialog_content = "Sepertinya begitu! Biar kulihat!",
  ui_story_70000202_22_dialog_content = "\"Undercity 80 memiliki jalan keluar yang mengarah dari Core Room ke permukaan.\"",
  ui_story_70000202_23_dialog_content = "\"Tapi, untuk mencegah infiltrasi musuh, pintu jalan keluarnya hanya bisa dibuka dari dalam.\"",
  ui_story_70000202_24_dialog_content = "\"Jalan keluarnya tersembunyi dengan baik. Lokasinya ada di belakang pintu rahasia di dekat Energy Core Undercity.\"",
  ui_story_70000202_25_dialog_content = "\"Untuk membuka pintu rahasia itu, ketuk pelan 3 kali, ketuk keras 3 kali, lalu ketuk pelan 3 kali di sepanjang dinding utara Core Room.\"",
  ui_story_70000202_26_dialog_content = "Jadi, ada hal-hal yang bahkan tak diketahui Sheol!?",
  ui_story_70000202_27_dialog_content = "Pengarangnya pasti pernah bekerja atau bertarung di sini sampai-sampai bisa tahu banyak soal Undercity 80.",
  ui_story_70000202_28_dialog_content = "Nah, karena rute pelariannya sudah didapat, sekarang saatnya bergerak.",
  ui_story_70000202_29_dialog_content = "Berpeganganlah padaku, PlayerName.",
  ui_story_70000202_30_dialog_content = "Apa aku boleh menolak? Rasanya hampir seperti…",
  ui_story_70000202_31_dialog_content = "Hei!",
  ui_story_70000202_32_dialog_content = "<anim type=Shake>Ahhhhhhhhhhh!</anim>",
  ui_story_70000202_33_dialog_content = "Hampir seperti…",
  ui_story_70000202_34_dialog_content = "Hati-hati, PlayerName! Jangan sampai lidahmu tergigit!",
  ui_story_70000202_35_dialog_content = "<size=45><anim type=Shake>Ahhhhhhhh!</anim></size>",
  ui_story_70000202_36_dialog_content = "Heyo!",
  ui_story_70000202_37_dialog_content = "<size=50><anim type=Shake>Ahhhhhhhh!</anim></size>",
  ui_story_70000202_38_dialog_content = "Kita sudah mendarat, PlayerName…",
  ui_story_70000202_39_dialog_content = "Oh… Benarkah?",
  ui_story_70000202_40_dialog_content = "Kau baik-baik saja?",
  ui_story_70000202_41_dialog_content = "Kita sudah di darat?",
  ui_story_70000202_42_dialog_content = "Kepalaku sangat pusing… Sebentar…",
  ui_story_70000202_43_dialog_content = "Hah? Ini karena pendaratannya kasar, ya? Mau istirahat sebentar?",
  ui_story_70000202_44_dialog_content = "Biar aku ambil napas dulu…",
  ui_story_70000202_45_dialog_content = "Bagaimana situasi di sekitar?",
  ui_story_70000202_46_dialog_content = "Belum ada Eclipsite yang terlihat, sih.",
  ui_story_70000202_47_dialog_content = "Sepertinya lantai bawah Undercity ada di dekat sini.",
  ui_story_70000202_48_dialog_content = "Sisa-sisa reruntuhan dan mesin ada di mana-mana. Sepertinya juga ada pecahan peralatan standar Illumina.",
  ui_story_70000202_49_dialog_content = "Tulisan di dinding berbunyi… <color=#FFB400>Ventilation Shaft 02</color>?",
  ui_story_70000202_50_dialog_content = "Kelihatannya kita memang ada di dalam Undercity.",
  ui_story_70000202_51_dialog_content = "Lubang peluru di seluruh dinding… Terjadi pertempuran sengit di sini.",
  ui_story_70000202_52_dialog_content = "Dark Zone War?",
  ui_story_70000202_53_dialog_content = "Selongsong peluru di tanah konsisten dengan senjata standar Illumina kuno. Jadi, itu mungkin ya.",
  ui_story_70000202_54_dialog_content = "Pantas saja siapa pun yang menulis Panduan ini tak mau kembali kemari.",
  ui_story_70000202_55_dialog_content = "Tempat ini hampir seperti lumpur yang… melahap kehidupan.",
  ui_story_70000202_56_dialog_content = "…",
  ui_story_70000202_57_option_content = "(Sentuh lubang peluru)",
  ui_story_70000202_58_option_content = "(Pungut selongsong peluru)",
  ui_story_70000202_59_dialog_content = "J-Jangan mendekat!",
  ui_story_70000202_60_dialog_content = "*Meraung*",
  ui_story_70000202_61_dialog_content = "Tolong… Tolong aku…",
  ui_story_70000202_62_dialog_content = "Hah?",
  ui_story_70000202_63_dialog_content = "Jangan makan aku! Aku tidak enak dimakan!",
  ui_story_70000202_64_dialog_content = "*Meraung*",
  ui_story_70000202_65_dialog_content = "Ibu… Aku ingin Ibu…",
  ui_story_70000202_66_dialog_content = "Aku… tak bisa kembali lagi…",
  ui_story_70000202_67_dialog_content = "…",
  ui_story_70000202_68_dialog_content = "Kau melihatnya, 'kan, PlayerName?",
  ui_story_70000202_69_dialog_content = "Hmm…",
  ui_story_70000202_70_dialog_content = "Tak ada yang bisa kita lakukan untuk itu… Biarkan saja.",
  ui_story_70000202_71_dialog_content = "Ayo kita periksa lokasi target.",
  ui_story_70000202_72_dialog_content = "Baiklah. Biar kucoba merasakannya.",
  ui_story_70000202_73_option_content = "Mulai telepati!",
  ui_story_70000202_74_dialog_content = "…!",
  ui_story_70000202_75_dialog_content = "Apa yang kita cari masih di bawah.",
  ui_story_70000202_76_dialog_content = "Gangguannya berat. Aku hanya bisa mendapat keseluruhan arahnya.",
  ui_story_70000202_77_dialog_content = "Ke sana!",
  ui_story_70000202_78_dialog_content = "Lagi-lagi ada tebing…",
  ui_story_70000202_79_dialog_content = "Sepertinya lebih dalam ketimbang yang tadi. Mustahil kita bisa turun…",
  ui_story_70000202_80_dialog_content = "Kita pasti akan ketahuan Eclipsite kalau melompat turun begitu saja.",
  ui_story_70000202_81_dialog_content = "Kalau begitu, mungkin kita bakal disergap.",
  ui_story_70000202_82_dialog_content = "Tapi, firasatku mengatakan lewat sini, jadi ini pasti rute tercepatnya.",
  ui_story_70000202_83_dialog_content = "Berapa banyak sisa waktu kita?",
  ui_story_70000202_84_dialog_content = "Tidak banyak.",
  ui_story_70000202_85_dialog_content = "Siang hari di sini jauh lebih pendek daripada di tempat lain. Ada enam jam siang hari paling lama.",
  ui_story_70000202_86_dialog_content = "Jika kita ingin melarikan diri di siang hari, kita hanya punya waktu sekitar tiga jam lagi.",
  ui_story_70000202_87_dialog_content = "Mari kita pergi dengan cara ini. Kami akan menyembunyikan diri saat kami mendarat. Kita harus punya cukup waktu.",
  ui_story_70000202_88_dialog_content = "... Baiklah. Saya percaya kamu.",
  ui_story_70000301_1_dialog_content = "Sekarang, di mana dua orang itu?",
  ui_story_70000301_2_dialog_content = "Menilai dari sinyal pelacakan mereka, mereka masih di Undercity 80.",
  ui_story_70000301_3_dialog_content = "Tapi gangguan Darkflow yang berat mengacaukan sinyal. Mereka mungkin telah... memasuki kedalamannya?",
  ui_story_70000301_4_dialog_content = "Semoga semuanya berjalan lancar.",
  ui_story_70000301_5_dialog_content = "Jangan khawatir dan tetap tenang.",
  ui_story_70000301_6_dialog_content = "Tidak ada berita adalah berita terbaik dalam hal operasi rahasia.",
  ui_story_70000301_7_dialog_content = "Kenapa bisa begitu?",
  ui_story_70000301_8_dialog_content = "Semua orang di Illumina adalah prajuritku. Sebagai Grand Marshal, saya sangat menyadari kemampuan orang-orang saya.",
  ui_story_70000301_9_dialog_content = "Selain itu, saya terus mencermati Vice sejak dia mulai bekerja dengan <color=#FFB400>individu itu</color>.",
  ui_story_70000301_10_dialog_content = "Jadi Anda tidak perlu khawatir. Saya meninggalkan beberapa tindakan pengamanan di Manual.",
  ui_story_70000301_11_dialog_content = "Tindakan pengamanan…?",
  ui_story_70000301_12_dialog_content = "Jika mereka masih berada di Undercity dalam satu setengah jam, hubungi mereka melalui komunikator.",
  ui_story_70000301_13_dialog_content = "Ya.",
  ui_story_70000301_14_dialog_content = "…",
  ui_story_70000301_15_dialog_content = "Lewat sini, PlayerName.",
  ui_story_70000301_16_dialog_content = "Ada peningkatan yang nyata di Eclipsites di sini...",
  ui_story_70000301_17_dialog_content = "Berjalan juga jadi terasa makin berat…",
  ui_story_70000301_18_dialog_content = "Bertahanlah, PlayerName.",
  ui_story_70000301_19_dialog_content = "Tidak bisa… Aku lelah…",
  ui_story_70000301_20_dialog_content = "Terlalu berbahaya di sini. Kita perlu mencari tempat yang aman jika kita ingin beristirahat.",
  ui_story_70000301_21_dialog_content = "Lihat, kita hanya beberapa ratus meter dari mencapai area di atas ruang inti.",
  ui_story_70000301_22_dialog_content = "Jika kau benar-benar tidak bisa berjalan... Aku bisa menggendongmu di punggungku.",
  ui_story_70000301_23_dialog_content = "NN-Tidak, tidak apa-apa...",
  ui_story_70000301_24_dialog_content = "Aku hanya perlu ambil napas!",
  ui_story_70000301_25_dialog_content = "Begitu kita mendapatkan apa yang kita cari dan kembali ke Soroz, aku akan menyiapkan pesta untukmu!",
  ui_story_70000301_26_dialog_content = "Tidak perlu untuk itu ... sungguh!",
  ui_story_70000301_27_dialog_content = "A-Aku sama sekali tidak capek, kok! Ayo pergi!",
  ui_story_70000301_28_dialog_content = "Ada Eclipsites di depan. Tapi tidak bisa melihat berapa banyak... Saya hanya bisa melihat siluet.",
  ui_story_70000301_29_dialog_content = "Mereka memblokir pintu masuk terowongan yang mengarah ke ruang inti. ... Betapa merepotkan.",
  ui_story_70000301_30_dialog_content = "Bisa kita kitari, tidak?",
  ui_story_70000301_31_dialog_content = "Biar kuperiksa di peta dulu.",
  ui_story_70000301_32_dialog_content = "Dari mana kau dapat peta itu!?",
  ui_story_70000301_33_dialog_content = "Hah? Kau tidak lihat, ya?",
  ui_story_70000301_34_dialog_content = "Saya menemukan fragmen peta di reruntuhan saat Anda sedang beristirahat. Jadi saya hanya menyalinnya di buku catatan saya.",
  ui_story_70000301_35_dialog_content = "Memangnya ingatanmu setajam itu?",
  ui_story_70000301_36_dialog_content = "Ini hanya draf dasar, jadi tidak terlalu sulit!",
  ui_story_70000301_37_dialog_content = "Semua Undercities dibangun mengikuti tata letak tertentu. Tidak sulit untuk menghafal peta jika Anda mengetahui tata letak dasarnya.",
  ui_story_70000301_38_dialog_content = "Misalnya, selalu ada setidaknya dua jalan keluar, dan poros ventilasi selalu berada—",
  ui_story_70000301_39_dialog_content = "Berhenti sebentar! Aku hanya ingin tahu apakah ada rute yang membawa kita mengelilingi Eclipsites.",
  ui_story_70000301_40_dialog_content = "Ada, tapi saya tidak tahu apakah itu diblokir atau tidak.",
  ui_story_70000301_41_dialog_content = "Selain itu, ini jalan memutar yang cukup. Menilai dari kecepatan kami saat ini, biayanya setidaknya setengah jam lebih.",
  ui_story_70000301_42_dialog_content = "Setengah jam... Kita tidak punya banyak waktu untuk memulai. Semakin lama kita di sini, semakin berbahaya bagi kita...",
  ui_story_70000301_43_dialog_content = "Jadi apa yang kita lakukan, PlayerName? Mengambil jalan memutar atau tidak?",
  ui_story_70000301_44_dialog_content = "Tidak ada cukup waktu.",
  ui_story_70000301_45_dialog_content = "Ada itu, ditambah jalan memutar akan berisiko.",
  ui_story_70000301_46_dialog_content = "Bagaimana dengan ini, mari berpencar dan mengapit Eclipsites di kedua sisi.",
  ui_story_70000301_X46_dialog_content = "Saya akan menarik perhatian mereka, dan Anda menyerang mereka dari belakang. Pastikan Anda mengerjakannya dengan cepat.",
  ui_story_70000301_47_dialog_content = "Baiklah, ayo lakukan itu.",
  ui_story_70000301_48_dialog_content = "Hati-hati.",
  ui_story_70000302_1_dialog_content = "Apakah Anda merasa Eclipsites itu jauh lebih kuat daripada yang pernah kita temui sebelumnya?",
  ui_story_70000302_2_dialog_content = "Mungkin bukan karena mereka menjadi lebih kuat tetapi kita menjadi lebih lemah.",
  ui_story_70000302_3_dialog_content = "Makin dalam kita melangkah, makin aku kesulitan bernapas.",
  ui_story_70000302_4_dialog_content = "Mungkin konsentrasi Darkflow tidak hanya dipengaruhi oleh siklus siang-malam, tetapi juga oleh kedalaman.",
  ui_story_70000302_5_dialog_content = "Semakin dalam kita pergi ke sini, semakin jauh kita tenggelam.... Pantas saja disebut Mire.",
  ui_story_70000302_6_dialog_content = "Kami tepat di atas ruang inti sekarang. Tidak ada Eclipsites di sekitar jadi kita aman untuk saat ini.",
  ui_story_70000302_7_dialog_content = "PlayerName, kamu tidak terlihat terlalu baik. Anda sebaiknya istirahat.",
  ui_story_70000302_8_dialog_content = "Kita masih punya waktu satu setengah jam. Beberapa menit tidak akan membuat perbedaan.",
  ui_story_70000302_9_dialog_content = "Aku masih bisa bertahan sedikit lagi... Aku tidak sabar menunggu sampai...",
  ui_story_70000302_10_dialog_content = "Manual mengatakan Anda perlu memanfaatkan setiap kesempatan untuk beristirahat untuk mempertahankan kekuatan Anda saat bertarung di Zona Gelap.",
  ui_story_70000302_11_dialog_content = "Jika Anda tidak mau mendengarkan saya, setidaknya dengarkan nasihat dari veteran ini.",
  ui_story_70000302_12_dialog_content = "Oke saya minta maaf, Vice. Aku memperlambat kita.",
  ui_story_70000302_13_dialog_content = "Jangan khawatir. Kita kan teman.",
  ui_story_70000302_14_dialog_content = "Kemarilah. Duduk di batu ini.",
  ui_story_70000302_15_dialog_content = "Di mana kita sekarang?",
  ui_story_70000302_16_dialog_content = "Menurut Manual, kita harus berada di tempat yang dulunya merupakan tempat penyimpanan. Kami sudah cukup dalam.",
  ui_story_70000302_17_dialog_content = "Memang ada banyak hal yang tersebar di sini.",
  ui_story_70000302_18_dialog_content = "Kaleng, kotak P3K kosong, selongsong peluru...",
  ui_story_70000302_19_dialog_content = "Dan juga benteng darurat compang-camping yang dibuat dengan kain kasa kotor dan sisa-sisa besi.",
  ui_story_70000302_20_dialog_content = "Para prajurit Illumina di sini pasti bertempur sampai orang terakhir.",
  ui_story_70000302_21_dialog_content = "Namun pada akhirnya Undercity masih kalah.",
  ui_story_70000302_22_dialog_content = "…",
  ui_story_70000302_23_dialog_content = "Saya hanya tahu Illumina kehilangan banyak orang dalam perang itu. Banyak orang.",
  ui_story_70000302_24_dialog_content = "Jika kami punya waktu, kami mungkin bisa menemukan tag anjing mereka di sini...",
  ui_story_70000302_25_dialog_content = "Jika kita bisa membawa mereka kembali bersama kita ke Illumina, saya membayangkan itu akan menutup keluarga mereka...",
  ui_story_70000302_26_dialog_content = "Vice…",
  ui_story_70000302_27_dialog_content = "Jika saya bisa membantu, saya pasti akan...",
  ui_story_70000302_28_dialog_content = "Hah?",
  ui_story_70000302_29_dialog_content = "Ini...",
  ui_story_70000302_30_dialog_content = "Apa yang kautemukan, PlayerName?",
  ui_story_70000302_31_dialog_content = "Pecahan di antara puing-puing itu... terlihat agak familiar.",
  ui_story_70000302_32_dialog_content = "Mereka tertutup debu, tapi potongannya tampak putih, dan pola di atasnya menyerupai...",
  ui_story_70000302_33_dialog_content = "<color=#FFB400>Colossus?</color>",
  ui_story_70000302_34_dialog_content = "Hah?",
  ui_story_70000302_35_dialog_content = "Sekarang setelah Anda mengatakannya, saya pikir Anda benar ...",
  ui_story_70000302_36_dialog_content = "Sepintas sepertinya tidak ada yang istimewa, tetapi setelah melihat lebih dekat ...",
  ui_story_70000302_37_dialog_content = "Apa ini komponen Colossus?",
  ui_story_70000302_38_dialog_content = "Bahkan jika bukan itu, mereka tetaplah sesuatu yang hanya ada di Eraveil.",
  ui_story_70000302_39_dialog_content = "Tidak heran Modul Think Tank mengatakan apa yang kita butuhkan untuk memperbaiki Soroz ada di sini.",
  ui_story_70000302_40_dialog_content = "Sepertinya kita sudah di jalan yang benar.",
  ui_story_70000302_41_dialog_content = "Biarkan saya mencoba merasakan lokasi target kami.",
  ui_story_70000302_42_option_content = "Mindlink!",
  ui_story_70000302_43_dialog_content = "Ini...",
  ui_story_70000302_44_dialog_content = "Groar!",
  ui_story_70000302_45_dialog_content = "?!",
  ui_story_70000302_46_dialog_content = "PlayerName? Kau baik-baik saja?",
  ui_story_70000302_47_dialog_content = "Aku merasakan sesuatu yang sangat kuat...",
  ui_story_70000302_48_dialog_content = "Seorang Eclipsite?",
  ui_story_70000302_49_dialog_content = "Mirip tapi... Saya tidak yakin.",
  ui_story_70000302_50_dialog_content = "Darkflow intens memancar darinya, tapi ada juga jejak Lumina.",
  ui_story_70000302_51_dialog_content = "Seolah-olah...",
  ui_story_70000302_52_dialog_content = "Mungkinkah itu produk dari salah satu eksperimen Forsakin?",
  ui_story_70000302_53_dialog_content = "Saya tidak yakin.",
  ui_story_70000302_54_dialog_content = "Saya hanya tahu bahwa apa pun itu, sangat kuat.",
  ui_story_70000302_55_dialog_content = "Ia tidak di dekat kita. Kurasa kita bisa menyelinap melewatinya dan membawa pergi barang yang kita butuhkan.",
  ui_story_70000302_56_dialog_content = "Diam…",
  ui_story_70000302_57_dialog_content = "Diam…",
  ui_story_70000302_58_dialog_content = "Waktunya habis. Kau bisa menghubungi mereka?",
  ui_story_70000302_59_dialog_content = "Tidak. Sinyalnya benar-benar hilang…",
  ui_story_70000302_60_dialog_content = "Apa aku harus mengutus regu pencarian dan penyelamatan?",
  ui_story_70000302_61_dialog_content = "Katakan pada mereka untuk bersiap-siap. Aku akan memimpinnya sendiri.",
  ui_story_70000302_62_dialog_content = "Kau mau pergi!?",
  ui_story_70000302_63_dialog_content = "Tentu saja. Lagi pula, memang sudah waktunya aku berlatih.",
  ui_story_70000302_64_dialog_content = "Saya kira itu terlalu dini untuk membuat mereka menghadapi tantangan seperti itu ...",
  ui_story_70000302_65_dialog_content = "Sepertinya saya benar-benar harus memainkannya sesuai buku di masa depan.",
  ui_story_70000302_66_dialog_content = "Baiklah. Regu penyelamatan, bersiap!",
  ui_story_70000302_67_dialog_content = "(Bahasa Eclipsian) Pasukan Illumina berkumpul di dekat perbatasan Eternal Night.",
  ui_story_70000302_68_dialog_content = "(Eclipsian) Dia ada di antara mereka.",
  ui_story_70000302_69_dialog_content = "(Eclipsian) Selain itu, Caelestite telah memasuki Undercity 80.",
  ui_story_70000302_70_dialog_content = "Undercity 80…",
  ui_story_70000302_71_dialog_content = "Mungkinkah dia juga sedang mencari <color=#FFB400>\"itu\"</color>?",
  ui_story_70000302_72_dialog_content = "Memang, itu satu-satunya tempat di mana petunjuk mungkin masih ada di dunia ini.",
  ui_story_70000302_73_dialog_content = "Mari kita lihat apa yang akhirnya Anda munculkan...",
  ui_story_70000302_74_dialog_content = "Saudari.",
  ui_story_70000401_1_dialog_content = "Ulurkan tanganmu, PlayerName.",
  ui_story_70000401_2_dialog_content = "Hei!",
  ui_story_70000401_3_dialog_content = "Akhirnya... kita berhasil...",
  ui_story_70000401_4_dialog_content = "Bukan lelucon betapa terkonsentrasinya Darkflow di sini... Hampir mustahil untuk bergerak.",
  ui_story_70000401_5_dialog_content = "PlayerName, apa yang kita cari benar-benar ada di sini?",
  ui_story_70000401_6_dialog_content = "Aku bisa merasakannya. Benda itu di dekat sini.",
  ui_story_70000401_7_dialog_content = "Itu seharusnya... tepat di atas mesin di ruang inti.",
  ui_story_70000401_8_dialog_content = "Saya pikir itu saja!",
  ui_story_70000401_9_dialog_content = "Apa ini… benar-benar Echo Template?",
  ui_story_70000401_10_dialog_content = "Kok tidak seperti yang di Soroz, sih.",
  ui_story_70000401_11_dialog_content = "Tapi, Think Tank Module kan mengarahkan kita kemari.",
  ui_story_70000401_12_dialog_content = "Tidak ada hal lain di sekitar sini yang menyerupai Template Gema.",
  ui_story_70000401_13_dialog_content = "Either way, mari kita bawa kembali ke Soroz dan lihat.",
  ui_story_70000401_14_dialog_content = "Oke, tapi itu diinstal pada intinya.",
  ui_story_70000401_15_dialog_content = "Biar kucoba melepasnya.",
  ui_story_70000401_16_dialog_content = "Hmm…",
  ui_story_70000401_17_dialog_content = "Tidak beruntung. Itu benar-benar tertanam di sana.",
  ui_story_70000401_18_dialog_content = "PlayerName, bantu aku, dong.",
  ui_story_70000401_19_dialog_content = "Saya datang!",
  ui_story_70000401_20_dialog_content = "Kita hitung dari tiga…",
  ui_story_70000401_21_dialog_content = "Tiga…",
  ui_story_70000401_22_dialog_content = "Dua…",
  ui_story_70000401_23_dialog_content = "Satu…",
  ui_story_70000401_24_dialog_content = "Sekarang!",
  ui_story_70000401_25_dialog_content = "Agh!",
  ui_story_70000401_26_dialog_content = "Sepertinya kepalaku membentur sesuatu... Apakah modulnya utuh?",
  ui_story_70000401_27_dialog_content = "Sepertinya sih baik-baik saja. Ayo cepat pergi dari sini!",
  ui_story_70000401_28_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_70000401_29_dialog_content = "Gempa bumi?!",
  ui_story_70000401_30_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_70000401_31_dialog_content = "Catu daya Undercity... terputus begitu saja?!",
  ui_story_70000401_32_dialog_content = "Apa karena kita mengambil modulnya?",
  ui_story_70000401_33_dialog_content = "Entahlah, tapi aku bisa merasakan…",
  ui_story_70000401_34_dialog_content = "<color=#e8d9bb>Duaar—!!</color>",
  ui_story_70000401_36_dialog_content = "Makin dekat!",
  ui_story_70000401_37_dialog_content = "Dia datang!",
  ui_story_70000401_37X1_dialog_content = "PlayerName, menyingkir dari tembok itu!",
  ui_story_70000401_37X2_dialog_content = "*Batuk-batuk*",
  ui_story_70000401_37X3_dialog_content = "Begitu banyak debu!",
  ui_story_70000401_37X4_dialog_content = "…",
  ui_story_70000401_37X5_dialog_content = "Ada ruang terbuka di balik tembok yang runtuh...?",
  ui_story_70000401_37X6_dialog_content = "Apa isinya…?",
  ui_story_70000401_37X7_dialog_content = "…",
  ui_story_70000401_37X8_dialog_content = "Darkflow ini membuatku tercekik!",
  ui_story_70000401_37X9_dialog_content = "Mungkinkah makhluk seperti Eclipsite yang kamu rasakan...?",
  ui_story_70000401_37X10_dialog_content = "…!",
  ui_story_70000401_37X11_dialog_content = "Itu benar-benar sebuah Eclipsite! Jenis yang belum pernah kita lihat sebelumnya!",
  ui_story_70000401_37X12_dialog_content = "Sepertinya dia tak bereaksi terhadap kehadiran kita… Jangan-jangan dia tidur, ya?",
  ui_story_70000401_37X13_dialog_content = "Mari kita tidak mengganggunya. Mari kita menyelinap lewat dan menemukan jalan keluar ...",
  ui_story_70000401_37X14_dialog_content = "Tapi kita perlu mengetuk dinding untuk membuka pintu keluar, dan itu pasti akan membangunkannya.",
  ui_story_70000401_37X15_dialog_content = "Kalau itu sampai terjadi, kau—",
  ui_story_70000401_37X16_dialog_content = "Illu…",
  ui_story_70000401_37X17_dialog_content = "Apakah itu ... berbicara dalam tidurnya?",
  ui_story_70000401_37X18_dialog_content = "Itu terlalu jauh. Aku tidak bisa mengerti apa yang dikatakannya.",
  ui_story_70000401_37X19_dialog_content = "Ada banyak Eclipsites yang bisa bicara...",
  ui_story_70000401_37X20_dialog_content = "Sudahlah. Yang penting kita keluar dari sini dulu!",
  ui_story_70000401_37X21_dialog_content = "Kau benar.",
  ui_story_70000401_37X22_dialog_content = "Illu… mina…!",
  ui_story_70000401_37X23_dialog_content = "Tunggu, kau dengar itu? Itu hanya mengatakan—",
  ui_story_70000401_37X24_dialog_content = "Groar!",
  ui_story_70000401_37X25_dialog_content = "Aduh! Dia bangun!",
  ui_story_70000401_37X26_dialog_content = "Berlari! Kami telah ditemukan!",
  ui_story_70000401_38_dialog_content = "Awas, PlayerName!",
  ui_story_70000401_39_dialog_content = "Vice! Apakah kamu baik-baik saja?",
  ui_story_70000401_39X1_dialog_content = "Aliran Gelap di sini terlalu kuat. Kita tidak bisa melawannya, kita harus menemukan jalan keluar!",
  ui_story_70000401_40_dialog_content = "Alihkan terus perhatiannya selagi aku mencari jalan keluarnya!",
  ui_story_70000401_41_dialog_content = "Aduh...",
  ui_story_70000401_42_dialog_content = "Buru-buru! Saya tidak bisa mengulur waktu lama, jadi sebaiknya cepat dan temukan!",
  ui_story_70000402_1_dialog_content = "Tiga ketukan ringan...",
  ui_story_70000402_2_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_70000402_3_dialog_content = "Tiga ketukan keras…",
  ui_story_70000402_4_dialog_content = "<color=#e8d9bb>Tok! Tok! Tok!</color>",
  ui_story_70000402_5_dialog_content = "Tiga ketukan ringan...",
  ui_story_70000402_6_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_70000402_7_dialog_content = "…",
  ui_story_70000402_8_dialog_content = "Hah? Tidak ada yang terjadi!? Serius, nih?",
  ui_story_70000402_9_dialog_content = "Buka!",
  ui_story_70000402_10_dialog_content = "Anda sudah mendapatkannya, PlayerName?!",
  ui_story_70000402_11_dialog_content = "Tidak berhasil!",
  ui_story_70000402_12_dialog_content = "*Meraung*",
  ui_story_70000402_13_dialog_content = "Argh…!",
  ui_story_70000402_14_dialog_content = "Ini tidak akan berhasil! Ayo mundur lebih jauh untuk saat ini!",
  ui_story_70000402_15_dialog_content = "Tapi itu jalan buntu!",
  ui_story_70000402_16_dialog_content = "Tak ada jalan lain!",
  ui_story_70000402_17_dialog_content = "Tapi benda itu menghalangi satu-satunya jalan kita ke permukaan, kita tidak punya jalan keluar lain!",
  ui_story_70000402_18_dialog_content = "Kita mungkin memiliki kesempatan jika kita masuk lebih dalam.",
  ui_story_70000402_19_dialog_content = "... Kamu benar.",
  ui_story_70000402_20_dialog_content = "Lalu berhenti berlama-lama, lari!",
  ui_story_70000402_21_dialog_content = "*Meraung*",
  ui_story_70000402_22_dialog_content = "<color=#e8d9bb>Gemuruh…!</color>",
  ui_story_70000402_23_dialog_content = "L-Lapor!",
  ui_story_70000402_24_dialog_content = "Gempa kuat terdeteksi datang dari arah reruntuhan Undercity 80!",
  ui_story_70000402_25_dialog_content = "Tenang! Tenang!",
  ui_story_70000402_26_dialog_content = "Pertahankan formasi pertahanan. Lanjutkan memasuki Undercity 80.",
  ui_story_70000402_27_dialog_content = "Ya!",
  ui_story_70000402_28_dialog_content = "<color=#e8d9bb>Aahhhhhh!</color>",
  ui_story_70000402_29_dialog_content = "Suara apa itu?!",
  ui_story_70000402_30_dialog_content = "Itu…?",
  ui_story_70000402_31_dialog_content = "…!",
  ui_story_70000402_32_dialog_content = "Perasaan ini…",
  ui_story_70000402_33_dialog_content = "Tidak, mustahil…",
  ui_story_70000402_34_dialog_content = "Grand Marshal, kau baik-baik saja?",
  ui_story_70000402_35_dialog_content = "…",
  ui_story_70000402_36_dialog_content = "Tidak, mereka tidak bisa pergi.",
  ui_story_70000402_37_dialog_content = "Mereka tidak bisa menangani ini.",
  ui_story_70000402_38_dialog_content = "Tim penyelamat, segera mundur ke garis aman! Itu perintah!",
  ui_story_70000402_39_dialog_content = "Apa pun yang terjadi, jangan masuk ke Dark Zone.",
  ui_story_70000402_40_dialog_content = "Ya Bu! Tapi Marsekal Agung...",
  ui_story_70000402_41_dialog_content = "Jangan khawatir. Ada beberapa hal yang harus saya jaga sendiri.",
  ui_story_70000402_42_dialog_content = "Juga, lulus Vivian pesan dari saya...",
  ui_story_70000402_43_dialog_content = "Minta dia untuk menangani \"orang-orang itu\" sampai aku kembali.",
  ui_story_70000402_44_dialog_content = "Ya!",
  ui_story_70000402_45_dialog_content = "<color=#e8d9bb>Aahhhhhh!</color>",
  ui_story_70000402_46_dialog_content = "…",
  ui_story_70000402_47_dialog_content = "Jadi ada petunjuk yang tertinggal di sini, seperti dugaanku.",
  ui_story_70000402_48_dialog_content = "\"Semuanya meninggalkan jejak.\"",
  ui_story_70000402_49_dialog_content = "Saya akan mengambil potongan puzzle ini kalau begitu.",
  ui_story_70000402_50_dialog_content = "Forsakin…",
  ui_story_70000402_51_dialog_content = "Jangan lupa pada janjimu.",
  ui_story_70000402_52_dialog_content = "Cih…",
  ui_story_70000402_53_dialog_content = "Baiklah.",
  ui_story_70000402_54_dialog_content = "Yang perlu Anda lakukan hanyalah menunggu sinyal saya dan kemudian mengusir cacing-cacing itu.",
  ui_story_70000402_55_dialog_content = "Kau justru akan gagal kalau ragu-ragu.",
  ui_story_70000402_56_dialog_content = "Dasar amatir.",
  ui_story_70000402_57_dialog_content = "Sungguh bodoh…",
  ui_story_70000501_1_dialog_content = "Ada jejak Luminatics yang belum dilahap oleh Darkflow. Jejaknya masih baru.",
  ui_story_70000501_2_dialog_content = "Trek Eclipsite... Sekitar sepuluh di antaranya. Namun, tidak ada tanda-tanda pertempuran besar.",
  ui_story_70000501_3_dialog_content = "Sepertinya taktik penyergapan digunakan untuk menghindari pertempuran.",
  ui_story_70000501_4_dialog_content = "Strategi yang brilian, sungguh. Bahkan medan dipertimbangkan ...",
  ui_story_70000501_5_dialog_content = "Kerja bagus, dia akhirnya menjadi komandan yang hebat.",
  ui_story_70000501_6_dialog_content = "Tapi... berapa lama kalian berdua bisa bertahan hidup di tempat seperti ini?",
  ui_story_70000501_7_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_70000501_8_dialog_content = "Apakah mereka terjebak?",
  ui_story_70000501_9_dialog_content = "Padahal sudah berkali-kali ditekankan dalam Panduan, tapi mereka tetap melakukan kesalahan amatir begini.",
  ui_story_70000501_10_dialog_content = "Aku harus memberi mereka pelajaran kalau mereka kembali.",
  ui_story_70000501_11_dialog_content = "Vice, mundur ke kanan!",
  ui_story_70000501_12_dialog_content = "Oke!",
  ui_story_70000501_13_dialog_content = "Rasakan ini!",
  ui_story_70000501_14_dialog_content = "*Meraung*",
  ui_story_70000501_15_dialog_content = "Serangan kami tidak melakukan apa-apa!",
  ui_story_70000501_16_dialog_content = "Darkflow di sini terlalu kuat!",
  ui_story_70000501_17_dialog_content = "Biarkan saya mencoba menghentikannya!",
  ui_story_70000501_18_option_content = "Kontrol Paksa—!",
  ui_story_70000501_19_dialog_content = "Illu…",
  ui_story_70000501_20_dialog_content = "Illu?",
  ui_story_70000501_21_dialog_content = "Apa yang… dia coba katakan?",
  ui_story_70000501_22_dialog_content = "Illu… mina…",
  ui_story_70000501_23_dialog_content = "Illumina? Seperti di Federasi Illumina?!",
  ui_story_70000501_24_dialog_content = "Illumina!",
  ui_story_70000501_25_dialog_content = "Wah, itu memancarkan kebencian yang begitu kuat.",
  ui_story_70000501_26_dialog_content = "PlayerName?!",
  ui_story_70000501_27_dialog_content = "Aku tak apa-apa!",
  ui_story_70000501_28_dialog_content = "Eclipsite yang itu berbeda… Sepertinya dia sangat membenci Illumina!",
  ui_story_70000501_29_dialog_content = "Illu… mina! Groar!",
  ui_story_70000501_30_dialog_content = "Apa dia menyerang kita karena melihat seragam Illumina ku?",
  ui_story_70000501_31_dialog_content = "PlayerName, akan kubuat dia tetap sibuk selagi kau mencari jalan keluarnya!",
  ui_story_70000501_32_dialog_content = "Bagaimana denganmu!?",
  ui_story_70000501_33_dialog_content = "Tak usah mencemaskanku! Pikirkan saja dirimu!",
  ui_story_70000501_34_dialog_content = "Illumina!",
  ui_story_70000501_35_dialog_content = "Argh…!",
  ui_story_70000501_36_dialog_content = "Vice!",
  ui_story_70000501_37_dialog_content = "Saya perlu menabung Vice!",
  ui_story_70000501_38_dialog_content = "Yo! Bodoh idiot! Hai! Aku disini!",
  ui_story_70000501_39_dialog_content = "*Meraung*",
  ui_story_70000501_40_dialog_content = "PlayerName… Lari… Lari…!",
  ui_story_70000501_41_dialog_content = "Ayo tangkap aku!",
  ui_story_70000501_42_dialog_content = "*Meraung*",
  ui_story_70000501_43_dialog_content = "Ini sangat cepat!",
  ui_story_70000501_44_dialog_content = "Ugh!",
  ui_story_70000501_45_dialog_content = "PlayerName?!",
  ui_story_70000501_46_dialog_content = "Apa aku… akan mati di sini…?",
  ui_story_70000501_47_dialog_content = "Siapa saja… Tolong… Tolong kami…",
  ui_story_70000501_48_dialog_content = "*Meraung*",
  ui_story_70000501_49_dialog_content = "<color=#e8d9bb>Klang—!</color>",
  ui_story_70000501_50_dialog_content = "Seorang komandan tak boleh mengalihkan pandangan dari medan tempur.",
  ui_story_70000501_51_dialog_content = "Suara ini...",
  ui_story_70000501_52_dialog_content = "Reinhardt!?",
  ui_story_70000501_53_dialog_content = "PlayerName Caelestite, Anda memiliki bakat untuk menjadi komandan yang baik, tetapi Anda membutuhkan lebih banyak pelatihan.",
  ui_story_70000501_54_dialog_content = "saya akan mendapatkan Barton Dan Gram untuk mencambuk Anda menjadi bugar!",
  ui_story_70000501_55_dialog_content = "Hah?!",
  ui_story_70000501_56_dialog_content = "Illumina! Illumina!",
  ui_story_70000501_57_dialog_content = "!",
  ui_story_70000501_58_dialog_content = "Grand Marshal… Reinhardt…!",
  ui_story_70000501_59_dialog_content = "Kalau kau masih bisa bergerak, cepat berlindung.",
  ui_story_70000501_60_dialog_content = "Vice! Lewat sini!",
  ui_story_70000501_61_dialog_content = "Groar!",
  ui_story_70000501_62_dialog_content = "Jadi, rupanya memang kau.",
  ui_story_70000501_63_dialog_content = "Bahkan jika Anda telah menjadi setengah Eclipsite di luar, cara Anda bertarung tidak berubah sama sekali.",
  ui_story_70000501_64_dialog_content = "Reinhardt… berbicara dengan Eclipsite itu?",
  ui_story_70000501_65_dialog_content = "Apakah Anda lupa siapa Anda?",
  ui_story_70000501_66_dialog_content = "Teman lama.",
  ui_story_70000501_67_dialog_content = "\"Teman lama\"…?",
  ui_story_70000501_68_dialog_content = "Aahhhh!",
  ui_story_70000501_69_dialog_content = "Darkflow di sini sangat kuat! Ini merugikan Reinhardt!",
  ui_story_70000501_70_dialog_content = "Kita harus coba mengalihkan perhatian Eclipsite itu…",
  ui_story_70000501_71_dialog_content = "Mulai telepati!",
  ui_story_70000501_72_dialog_content = "*Meraung*",
  ui_story_70000501_73_dialog_content = "Ahhh!",
  ui_story_70000501_74_dialog_content = "<color=#e8d9bb>Gemuruh…!</color>",
  ui_story_70000501_75_dialog_content = "Orang ini…benar-benar menyia-nyiakan hidupnya!",
  ui_story_70000501_76_dialog_content = "Apa dia peduli bahwa tindakannya mungkin membuat seluruh Undercity ini runtuh!?",
  ui_story_70000501_77_dialog_content = "PlayerName, serahkan ini padaku.",
  ui_story_70000501_78_dialog_content = "Tunggu sebentar.",
  ui_story_70000501_78X1_dialog_content = "!",
  ui_story_70000501_78X2_dialog_content = "Reinhardt?! Pergi dari sana!",
  ui_story_70000501_78X3_dialog_content = "Grand Marshal!",
  ui_story_70000501_78X4_dialog_content = "Tenanglah. Aku sungguh tidak apa-apa.",
  ui_story_70000501_78X5_dialog_content = "Ada satu hal yang ingin saya coba terlebih dahulu.",
  ui_story_70000501_79_dialog_content = "Namun…",
  ui_story_70000501_80_dialog_content = "PlayerName, percayakan saja pada Grand Marshal untuk saat ini...",
  ui_story_70000501_81_dialog_content = "Reinhardt… Kenapa dia tak balas menyerang?",
  ui_story_70000501_82_dialog_content = "Apa kau… masih ingat?",
  ui_story_70000501_83_dialog_content = "Kita bertarung berdampingan dan bersama-sama mengalahkan musuh yang tak terhitung jumlahnya.",
  ui_story_70000501_84_dialog_content = "…",
  ui_story_70000501_85_dialog_content = "Kita menggali parit, menahan gelombang demi gelombang serangan lawan untuk melindungi rumah kita, Gannon.",
  ui_story_70000501_86_dialog_content = "Gan… non…",
  ui_story_70000501_87_dialog_content = "Benar. Gannon. Kita adalah anak-anaknya, dan kita sudah bersumpah kepadanya.",
  ui_story_70000501_88_dialog_content = "Kau masih ingat namamu?",
  ui_story_70000501_89_dialog_content = "Ahh…",
  ui_story_70000501_90_dialog_content = "Anda... <color=#FFB400>Helios</color>.",
  ui_story_70000501_91_dialog_content = "Illu… mina…",
  ui_story_70000501_92_dialog_content = "Illumina!",
  ui_story_70000501_93_dialog_content = "*Meraung*",
  ui_story_70000501_94_dialog_content = "Cih… Gagal, ya?",
  ui_story_70000501_95_dialog_content = "Grand Marshal! Awas!",
  ui_story_70000501_96_dialog_content = "Konstruksi tempat ini terlalu rapuh. Undercity ini sudah tak bisa menahan serangan lagi!",
  ui_story_70000501_97_dialog_content = "Kalau begini terus, seluruh Undercity ini mungkin akan runtuh!",
  ui_story_70000501_98_dialog_content = "Groar!",
  ui_story_70000501_99_dialog_content = "Terkadang kau harus menatap cermin…",
  ui_story_70000501_100_dialog_content = "Ingatlah… Ingatlah siapa dirimu yang sebenarnya.",
  ui_story_70000501_101_dialog_content = "Pulanglah ke Illumina denganku. Akan kucari cara untuk mengobatimu agar wujudmu kembali seperti semula!",
  ui_story_70000501_102_dialog_content = "*Meraung*",
  ui_story_70000501_103_dialog_content = "*Batuk-batuk*",
  ui_story_70000501_104_dialog_content = "PlayerName, lewat sini!",
  ui_story_70000501_105_dialog_content = "<color=#e8d9bb>Ding…</color>",
  ui_story_70000501_106_dialog_content = "!!!",
  ui_story_70000501_107_dialog_content = "Ini…",
  ui_story_70000501_108_dialog_content = "Suara bel… Dari mana asalnya?",
  ui_story_70000501_109_dialog_content = "Groar!",
  ui_story_70000501_110_dialog_content = "High-Level Eclipsite itu… baru saja memanjat tebing dan pergi.",
  ui_story_70000501_111_dialog_content = "Bel itu yang mengendalikan Eclipsite?",
  ui_story_70000501_112_dialog_content = "Tidak.",
  ui_story_70000501_113_dialog_content = "Suara bel itu menandakan satu hal: <color=#FFB400>\"Bala bantuan datang. Mundur.\"</color>",
  ui_story_70000501_114_dialog_content = "Eclipsite itu… dulunya orang yang kaukenal?",
  ui_story_70000501_115_dialog_content = "Bukan hanya sekadar kenalan. Dulu dia saudara seperjuanganku.",
  ui_story_70000501_116_dialog_content = "Orang yang sangat kupercaya.",
  ui_story_70000501_117_dialog_content = "Dia hilang dalam tugas di Undercity ini selama Dark Zone War.",
  ui_story_70000501_118_dialog_content = "Kupikir dia sudah mati… Tapi, tak kusangka…",
  ui_story_70000501_119_dialog_content = "Tak kusangka dia berubah menjadi Eclipsite.",
  ui_story_70000501_120_dialog_content = "Berubah menjadi Eclipsite? Kedengarannya hampir seperti…",
  ui_story_70000501_121_dialog_content = "Aku benar-benar bingung dengan apa yang terjadi padanya sekarang.",
  ui_story_70000501_122_dialog_content = "<color=#e8d9bb>Gemuruh…!</color>",
  ui_story_70000501_123_dialog_content = "Sepertinya Undercity ini sudah tak terselamatkan lagi.",
  ui_story_70000501_124_dialog_content = "Ayo pergi dari sini. Kita bicarakan dalam perjalanan pulang.",
  ui_story_70000501_125_dialog_content = "Baiklah.",
  ui_story_70000501_126_dialog_content = "Aku tahu jalan keluarnya. Ikuti aku.",
  ui_story_70000601_1_dialog_content = "Dulu aku, <color=#FFB400>Denier</color>, dan <color=#FFB400>Helios</color> bersahabat.",
  ui_story_70000601_1X1_dialog_content = "Kuyakin kau juga mengenal orang yang satunya. Dulu, dia biasa dipanggil <color=#FFB400>Denier</color>.",
  ui_story_70000601_1X2_dialog_content = "Forsakin?",
  ui_story_70000601_1X3_dialog_content = "Ya. Sekarang itulah namanya.",
  ui_story_70000601_2_dialog_content = "Kami tumbuh besar di panti asuhan Illumina, bergabung dengan militer, dan bertarung bersama.",
  ui_story_70000601_3_dialog_content = "Denier, Reinhardt, kalian sudah punya rencana?",
  ui_story_70000601_4_dialog_content = "Instrukturku bilang aku ini berbakat. Aku bisa jadi pengintai di masa depan.",
  ui_story_70000601_5_dialog_content = "Aku berbeda dengan kalian semua. Pekerjaan di lab adalah keahlianku.",
  ui_story_70000601_6_dialog_content = "Sepertinya ada yang lebih cocok jadi orang bodoh ketimbang aku.",
  ui_story_70000601_7_dialog_content = "Dasar tukang sindir…",
  ui_story_70000601_8_dialog_content = "Kau bagaimana, Reinhardt?",
  ui_story_70000601_9_dialog_content = "Aku?",
  ui_story_70000601_10_dialog_content = "Aku masih pikir-pikir, sih. Mungkin aku akan mulai dari hal kecil.",
  ui_story_70000601_11_dialog_content = "Aku akan mulai dari posisi Grand Marshal di Illumina.",
  ui_story_70000601_12_dialog_content = "Tak lama, kemampuan kami diakui oleh para pemimpin Illumina.",
  ui_story_70000601_13_dialog_content = "Dan kami semua jadi kandidat untuk Grand Marshal berikutnya.",
  ui_story_70000601_14_dialog_content = "Kalian adalah para prajurit terbaik Illumina. Masa depan Illumina ada di pundak kalian.",
  ui_story_70000601_15_dialog_content = "Kalian akan menempuh latihan berat yang paling brutal di seluruh Illumina.",
  ui_story_70000601_16_dialog_content = "Setiap hari, setiap jam, akan ada orang yang tersingkir.",
  ui_story_70000601_17_dialog_content = "Pemenangnya akan menjadi Grand Marshal di Illumina.",
  ui_story_70000601_18_dialog_content = "Apa kalian sanggup?",
  ui_story_70000601_19_dialog_content = "Untuk menjadi yang terkuat dalam kelompok!?",
  ui_story_70000601_20_dialog_content = "Ya.",
  ui_story_70000601_21_dialog_content = "Ya!",
  ui_story_70000601_22_dialog_content = "YA!",
  ui_story_70000601_23_dialog_content = "<color=#FFB400>Committee</color>? Apa itu?",
  ui_story_70000601_24_dialog_content = "Hah? Kau belum pernah dengar tentang Committee, PlayerName?",
  ui_story_70000601_25_dialog_content = "Sama sekali belum!",
  ui_story_70000601_26_dialog_content = "Lembaga yang mengatur segala hal di Illumina bersama dengan Grand Marshal Reinhardt!",
  ui_story_70000601_27_dialog_content = "Yah, semua orang membicarakan Grand Marshal…",
  ui_story_70000601_28_dialog_content = "Tapi, tak ada yang jelas-jelas menyebut komite itu.",
  ui_story_70000601_29_dialog_content = "*Batuk-batuk*",
  ui_story_70000601_30_dialog_content = "(Oh, sial! Aku lupa, Grand Marshal ada di sini!)",
  ui_story_70000601_31_dialog_content = "Committee itu kependekan dari <color=#FFB400>Military and Political Affairs Committee of Illumina Federation</color>.",
  ui_story_70000601_32_dialog_content = "Mereka adalah sekelompok orang ketinggalan zaman yang suka mengatur segala hal terkait Illumina, sampai ke hal terkecil sekali pun.",
  ui_story_70000601_33_dialog_content = "Tapi, mereka memang tak suka menonjolkan diri, jadi wajar saja kalau tak banyak orang yang tahu tentang mereka.",
  ui_story_70000601_34_dialog_content = "(Syukurlah, Reinhardt sendiri malah menyelamatkanku…)",
  ui_story_70000601_35_dialog_content = "Hah? Sebentar… Apa itu berarti…",
  ui_story_70000601_36_dialog_content = "Committee-lah yang memutuskan siapa yang akan jadi Grand Marshal?",
  ui_story_70000601_37_dialog_content = "Hah?",
  ui_story_70000601_38_dialog_content = "Bukankah yang menjadi Grand Marshal mestinya adalah orang yang paling berpengalaman?",
  ui_story_70000601_39_dialog_content = "Maksudku, itulah yang kupelajari saat sekolah dulu…",
  ui_story_70000601_40_dialog_content = "Itu hanya sebagian syaratnya.",
  ui_story_70000601_41_dialog_content = "Mempersatukan masyarakat adalah tugas sulit.",
  ui_story_70000601_41X_dialog_content = "Illumina Federation terdiri dari banyak Undercity. Reputasi saja tak akan cukup untuk mendapatkan dukungan dari mereka.",
  ui_story_70000601_42_dialog_content = "Seandainya penunjukan Grand Marshal didasarkan pada reputasi semata… Apa jadinya kalau ternyata dia tak punya jiwa kepemimpinan?",
  ui_story_70000601_43_dialog_content = "Atau ternyata dia orang yang hanya mengandalkan otot tapi tak punya otak?",
  ui_story_70000601_44_dialog_content = "Apa kita harus mematuhinya dan menggunakan semua sumber daya Illumina untuk membangun tembok dan amunisi senapan?",
  ui_story_70000601_44X_dialog_content = "Lalu tinggal menunggu sampai kita tua dan mati?",
  ui_story_70000601_45_dialog_content = "Hmm…",
  ui_story_70000601_46_dialog_content = "Kita sudah sampai.",
  ui_story_70000601_47_dialog_content = "Kita… benar-benar dikelilingi reruntuhan!",
  ui_story_70000601_48_dialog_content = "Jangan panik. Aku ingat jalan masuknya…",
  ui_story_70000601_49_dialog_content = "Ada jalan rahasia, di sini!?",
  ui_story_70000601_50_dialog_content = "Lebih tepatnya, terowongan darurat.",
  ui_story_70000601_51_dialog_content = "Terowongan darurat Undercity sudah diperkuat, mungkin karena di sini sering terjadi gempa.",
  ui_story_70000601_52_dialog_content = "Aku pernah memimpin pasukan untuk membubarkan pengepungan di sini.",
  ui_story_70000601_53_dialog_content = "Masuk.",
  ui_story_70000601_54_dialog_content = "Sunyi sekali…",
  ui_story_70000601_55_dialog_content = "Vice, ulurkan tanganmu.",
  ui_story_70000601_56_dialog_content = "Terima kasih, PlayerName.",
  ui_story_70000601_57_dialog_content = "Aku tak keberatan, kok.",
  ui_story_70000601_58_dialog_content = "Tadi kau terkena serangan sengit. Sebaiknya kausimpan tenagamu.",
  ui_story_70000601_59_dialog_content = "Begini… Walaupun kalian berdua memang sangat kuat, kalian harus tetap tahu batas diri kalian.",
  ui_story_70000601_60_dialog_content = "Seandainya kalian mengikuti Panduan itu dan kembali ke permukaan saat waktunya habis…",
  ui_story_70000601_60X_dialog_content = "Mestinya kalian bisa menghindari ini semua.",
  ui_story_70000601_61_dialog_content = "Kau tahu tentang Panduan itu? Jangan-jangan…",
  ui_story_70000601_62_dialog_content = "Memang akulah yang menulisnya, tentu saja. Aku juga tahu kalian meminta Philyshy untuk mengamati Undercity 80.",
  ui_story_70000601_63_dialog_content = "!!!",
  ui_story_70000601_64_dialog_content = "Kenapa kalian menatapku seperti itu?",
  ui_story_70000601_65_dialog_content = "Di seluruh Illumina Federation, akulah satu-satunya orang yang pernah bertempur dalam Dark Zone War dan berhasil keluar hidup-hidup dari sana.",
  ui_story_70000601_66_dialog_content = "Waktu itu, aku ditugaskan di Undercity 80.",
  ui_story_70000601_67_dialog_content = "Bagaimana fakta bahwa seseorang sedang menyelidiki Undercity ini luput dari perhatianku?",
  ui_story_70000601_68_dialog_content = "Kalau begitu, kenapa kau di sini…?",
  ui_story_70000601_69_dialog_content = "Kukira kau di Gannon.",
  ui_story_70000601_70_dialog_content = "Aku mengizinkan kalian menjelajahi wilayah ini karena aku percaya pada kemampuan kalian.",
  ui_story_70000601_71_dialog_content = "Tapi, bukan berarti aku tak punya rencana untuk berjaga-jaga kalau ada masalah dan kalian terancam bahaya besar.",
  ui_story_70000601_72_dialog_content = "Melindungi semua orang di Illumina memang tanggung jawab Grand Marshal.",
  ui_story_70000601_73_dialog_content = "Dan itu termasuk dirimu, kawan Illumina, PlayerName.",
  ui_story_70000601_74_dialog_content = "Uhh… Baiklah…",
  ui_story_70000601_75_dialog_content = "Begitu aku tahu bahwa kalian mau menyelidiki Undercity 80…",
  ui_story_70000601_75X_dialog_content = "Aku langsung memimpin pasukan untuk menunggu di Safe Line di perbatasan Dark Zone.",
  ui_story_70000601_76_dialog_content = "Aku berniat mengamati performa kalian dari sana…",
  ui_story_70000601_77_dialog_content = "Kalau kalian berhasil menyelesaikan misi tanpa kendala, aku akan pura-pura seakan-akan tak terjadi apa-apa.",
  ui_story_70000601_78_dialog_content = "Tapi, tak kuduga, kalian justru terperosok ke dalam bahaya besar.",
  ui_story_70000601_79_dialog_content = "Semuanya berjalan lancar. Tapi, tanpa terduga, kami bertemu dengan musuh kuat di bawah tanah…",
  ui_story_70000601_79X_dialog_content = "Dampaknya akan sangat mengerikan andai aku tidak merasakan keberadaan Helios dan buru-buru membantu kalian.",
  ui_story_70000601_80_dialog_content = "Percayai info intelnya, tapi siapkan diri untuk hal-hal tak terduga.",
  ui_story_70000601_81_dialog_content = "Kalau kalian ingin jadi komandan yang baik, sebaiknya ingat itu.",
  ui_story_70000601_82_dialog_content = "Oh, begitu…",
  ui_story_70000601_83_dialog_content = "Kalian tak kembali sesuai waktu yang sudah ditentukan. Mau tak mau aku mengira kalian mengalami skenario terburuk.",
  ui_story_70000601_84_dialog_content = "Awalnya, kukira hanya beberapa Eclipsite. Aku tak menyangka, ternyata dia orangnya…",
  ui_story_70000601_85_dialog_content = "Oh, ternyata takdir suka bercanda agak kelewatan.",
  ui_story_70000601_86_dialog_content = "…",
  ui_story_70000601_87_dialog_content = "Tak usah pikirkan itu.",
  ui_story_70000601_88_dialog_content = "Terowongan daruratnya persis di balik pintu ini.",
  ui_story_70000601_89_dialog_content = "Telusuri saja naik sampai ke permukaan.",
  ui_story_70000601_90_dialog_content = "<color=#e8d9bb>Krieeek…</color>",
  ui_story_70000601_91_dialog_content = "Rupanya terowongan ini tak rusak akibat gempa.",
  ui_story_70000601_92_dialog_content = "Aku bahkan bisa merasakan embusan angin segar.",
  ui_story_70000601_93_dialog_content = "Berarti terowongan ini memang mengarah ke luar!",
  ui_story_70000601_94_dialog_content = "Diamlah. Terowongan ini membuat suaramu makin keras.",
  ui_story_70000601_95_dialog_content = "Mungkin saja ada Eclipsite yang bersembunyi di dalam sini.",
  ui_story_70000601_96_dialog_content = "*Meraung*",
  ui_story_70000601_97_dialog_content = "Panjang umur…",
  ui_story_70000601_98_dialog_content = "M-maaf!",
  ui_story_70000601_99_dialog_content = "Bersiaplah untuk bertarung, Caelestite. Tunjukkan seberapa hebat kemampuanmu sebagai komandan!",
  ui_story_70000602_1_dialog_content = "Kenapa…",
  ui_story_70000602_2_dialog_content = "Kita mengarah naik, tapi Darkflow di sini justru terasa makin kuat… Kenapa?",
  ui_story_70000602_3_dialog_content = "Benar…",
  ui_story_70000602_4_dialog_content = "Tadi aku sanggup mengatasi beberapa Eclipsite. Tapi, sekarang, satu atau dua Eclipsite saja sudah terasa terlalu berat untuk kuatasi…",
  ui_story_70000602_5_dialog_content = "Aku sudah menuliskan alasannya di dalam buku Panduan itu. Masih ingat, tidak?",
  ui_story_70000602_6_dialog_content = "Kelelahan fisik?",
  ui_story_70000602_7_dialog_content = "Tidak.",
  ui_story_70000602_8_dialog_content = "Memang itu salah satu faktor, tapi bukan yang utama.",
  ui_story_70000602_9_dialog_content = "Mungkinkah karena faktor… waktu?",
  ui_story_70000602_10_dialog_content = "Yap.",
  ui_story_70000602_11_dialog_content = "Karena ini sudah malam?",
  ui_story_70000602_12_dialog_content = "Bagus.",
  ui_story_70000602_13_dialog_content = "Sepertinya kau memang membaca Panduan itu dengan cermat.",
  ui_story_70000602_14_dialog_content = "Sudah berkali-kali aku berusaha mengingatkan agar selalu ingat waktu agar tak terjebak dalam skenario terburuk, yang sekarang sedang kita alami ini.",
  ui_story_70000602_15_dialog_content = "Tapi, kalaupun aku memberitahumu, kau pasti tak akan memedulikannya, 'kan?",
  ui_story_70000602_16_dialog_content = "Soroz sangat penting bagimu. Dia keluargamu.",
  ui_story_70000602_17_dialog_content = "Kau bisa menebak isi hatiku…",
  ui_story_70000602_18_dialog_content = "Kau sendiri yang mudah ditebak.",
  ui_story_70000602_19_dialog_content = "Ditambah lagi, Vice terus-menerus membicarakanmu tanpa henti.",
  ui_story_70000602_20_dialog_content = "Walaupun aku tak mau mendengarnya, tetap saja aku tak bisa menutup telinga darinya.",
  ui_story_70000602_21_dialog_content = "Grand Marshal Reinhardt!",
  ui_story_70000602_22_dialog_content = "Tapi, aku punya pertanyaan lain.",
  ui_story_70000602_23_dialog_content = "Bagaimana kau bisa merasakan Helios?",
  ui_story_70000602_24_dialog_content = "Mungkin karena ada ikatan di antara kami.",
  ui_story_70000602_25_dialog_content = "Karena tumbuh bersama, hubungan yang terjalin antara kami begitu dekat.",
  ui_story_70000602_26_dialog_content = "Kita selalu tahu saat anggota keluarga kita mengalami masalah.",
  ui_story_70000602_27_dialog_content = "Undercity ini sudah lama ditutup. Darkflow dan faktor jarak membuat ikatan kami terputus.",
  ui_story_70000602_28_dialog_content = "Tapi, kau berhasil membukanya. Kau bahkan membangunkan Helios yang sudah terkurung di sini selama bertahun-tahun.",
  ui_story_70000602_29_dialog_content = "Ikatan antara kami pun tumbuh kembali…",
  ui_story_70000602_30_dialog_content = "Mungkinkah Reinhardt juga punya kemampuan psikis?",
  ui_story_70000602_31_dialog_content = "Kalau memang punya, aku akan senang sekali.",
  ui_story_70000602_32_dialog_content = "Dengan begitu, aku bisa memberikan perintah dengan lebih mudah.",
  ui_story_70000602_33_dialog_content = "Dulu, pasti ada semacam ikatan yang terjalin antarsesama rekan seperjuangan.",
  ui_story_70000602_34_dialog_content = "Itu putus ...",
  ui_story_70000602_34X_dialog_content = "Tapi, operasi yang kaulakukan kembali menyambung ikatan kami dan mempertemukan kami sekali lagi.",
  ui_story_70000602_35_dialog_content = "Menurutku, itu karena ada pengalaman tertentu yang kita alami bersama…",
  ui_story_70000602_36_dialog_content = "Pengalaman menghadapi situasi antara hidup dan mati bersama.",
  ui_story_70000602_36X1_dialog_content = "Itulah kenangan yang kami bertiga alami.",
  ui_story_70000602_36X2_dialog_content = "Apa yang terjadi padamu?",
  ui_story_70000602_36X3_dialog_content = "Pertempuran sengit. Tapi, bagi mereka, peristiwa itu lebih tampak seperti pengkhianatan terbesar.",
  ui_story_70000602_36X4_dialog_content = "Mereka dikhianati oleh Illumina dan olehku… Kami meninggalkan mereka.",
  ui_story_70000602_36X5_dialog_content = "Meninggalkan?",
  ui_story_70000602_36X6_dialog_content = "Tapi, Reinhardt… Aku tak percaya kau meninggalkan rekan seperjuanganmu!",
  ui_story_70000602_37_dialog_content = "Ceritanya panjang. Biar kususun dulu ceritanya.",
  ui_story_70000602_38_dialog_content = "Yang kutakutkan adalah pengkhianatan inilah yang mengubah Helios menjadi monster.",
  ui_story_70000602_39_dialog_content = "Dan Denier... Tidak, dia memakai nama baru sekarang...",
  ui_story_70000602_40_dialog_content = "<color=#FFB400>Forsakin.</color>",
  ui_story_70000602_41_dialog_content = "Forsakin…",
  ui_story_70000602_42_dialog_content = "Jadi, alasannya mengkhianati Illumina adalah karena dia ditelantarkan dan sudah tak punya harapan lagi?",
  ui_story_70000602_43_dialog_content = "Aku tidak tahu.",
  ui_story_70000602_44_dialog_content = "Tapi, itu tak bisa dijadikan pembenaran baginya untuk memanfaatkan manusia sebagai subjek uji dan membahayakan warga Illumina.",
  ui_story_70000602_45_dialog_content = "Aku tahu dia memendam dendam karena tak diselamatkan.",
  ui_story_70000602_46_dialog_content = "Itu salahku karena aku lemah dan ringkih. Mestinya akulah yang jadi sasaran dendamnya.",
  ui_story_70000602_47_dialog_content = "Tapi, dia justru melampiaskannya pada orang lain…",
  ui_story_70000602_48_dialog_content = "Schummer, aku, dan banyak sekali orang-orang tak bersalah…",
  ui_story_70000602_49_dialog_content = "Ya. Itu kejahatannya.",
  ui_story_70000602_50_dialog_content = "Kejahatan yang harus dipertanggungjawabkannya.",
  ui_story_70000602_51_dialog_content = "Aku setuju denganmu. Kedua hal itu berbeda satu sama lain.",
  ui_story_70000602_51X1_dialog_content = "Terkadang, terlintas dalam benakku bahwa…",
  ui_story_70000602_51X2_dialog_content = "Andai mereka tidak mengikuti program latihan Committee dan tidak ikut terjun dalam pertempuran mengerikan itu…",
  ui_story_70000602_51X3_dialog_content = "Akankah mereka menikmati hidup yang lebih baik sekarang sebagai manusia dan bukan Eclipsite?",
  ui_story_70000602_52_dialog_content = "Latihan macam apa itu?",
  ui_story_70000602_52X1_dialog_content = "Tak tampak seperti latihan yang bisa dijalani manusia biasa.",
  ui_story_70000602_53_dialog_content = "Proyek pengembangan dari Committee bukanlah <color=#FFB400>latihan</color> biasa.",
  ui_story_70000602_54_dialog_content = "Kalian bertiga… mengikuti latihan dari Committee?",
  ui_story_70000602_55_dialog_content = "Proyek pengembangan dari Committee bukanlah latihan biasa.",
  ui_story_70000602_56_dialog_content = "Pesertanya mungkin saja akan kehilangan nyawa.",
  ui_story_70000602_57_dialog_content = "Kedengarannya berat.",
  ui_story_70000602_58_dialog_content = "Apa Illumina memang harus… memilih Grand Marshal dengan cara itu?",
  ui_story_70000602_59_dialog_content = "Bagi warga Illumina, Grand Marshal adalah cahaya dalam kegelapan.",
  ui_story_70000602_60_dialog_content = "Hanya api paling terang yang dapat menyinari sudut tergelap, menumbuhkan harapan pada setiap manusia yang putus asa.",
  ui_story_70000602_61_dialog_content = "Harapanlah yang mempersatukan warga Illumina dan memotivasi mereka untuk terus melangkah maju di dunia yang keras ini.",
  ui_story_70000602_62_dialog_content = "Tapi, kalau kau mau menunggu sampai orang yang benar-benar hebat akhirnya lahir di dunia ini, sangat kecil kemungkinan atau bahkan tak mungkin kau akan bisa melihatnya selagi kau masih hidup.",
  ui_story_70000602_63_dialog_content = "Inilah alasanku ingin menjadi Grand Marshal di Illumina walaupun aku harus melalui banyak kesulitan untuk mencapainya.",
  ui_story_70000602_63X_dialog_content = "Orang terkuat di muka bumi.",
  ui_story_70000602_64_dialog_content = "…",
  ui_story_70000602_65_dialog_content = "Nak, jangan menatapku seperti itu.",
  ui_story_70000602_66_dialog_content = "Apa pepatahnya, ya?",
  ui_story_70000602_67_dialog_content = "\"Besar kapal, besar pula gelombangnya.\"",
  ui_story_70000602_68_dialog_content = "Jangan khawatir. Kalaupun langit runtuh, orang yang paling tinggi di antara kita akan menopangnya agar tak menjatuhi kita.",
  ui_story_70000602_69_dialog_content = "Itu juga berlaku di sini. Saat Illumina menghadapi masalah, Grand Marshal siap menanggungnya.",
  ui_story_70000602_70_dialog_content = "Aku akan melindungi semua orang, termasuk kalian.",
  ui_story_70000602_71_dialog_content = "Kita sudah sampai.",
  ui_story_70000701_1_dialog_content = "Sepertinya ini tingkat atas Undercity, sama dengan area tempat kita masuk tadi.",
  ui_story_70000701_2_dialog_content = "Tapi, terowongan ini membuat orientasi arahku kacau. Aku tak terlalu yakin dengan arah langkahku sekarang…",
  ui_story_70000701_3_dialog_content = "PlayerName, ini bukan tempat yang kita masuki pertama tadi.",
  ui_story_70000701_4_dialog_content = "Kita sebenarnya berada di tempat yang sama sekali berbeda.",
  ui_story_70000701_5_dialog_content = "Apa?!",
  ui_story_70000701_6_dialog_content = "Memangnya sulit dibedakan, ya? Kita kan bisa langsung tahu dengan melihat tata letak jalur kabel di langit-langit. Lubang ventilasinya juga…",
  ui_story_70000701_7_dialog_content = "(Ya ampun… Si Vice mulai lagi, deh…)",
  ui_story_70000701_8_dialog_content = "Anu… ada yang ingin kutanyakan!",
  ui_story_70000701_9_dialog_content = "Apa rasa ingin tahu memang salah satu ciri khas kaum Caelestite, ya?",
  ui_story_70000701_10_dialog_content = "Maaf. Aku janji, ini yang terakhir kali!",
  ui_story_70000701_11_dialog_content = "Tak apa. Tak ada salahnya punya rasa ingin tahu, kok.",
  ui_story_70000701_12_dialog_content = "High-Level Eclipsite yang tadi kabur itu… adalah temanmu yang dulu bertempur bersamamu, 'kan, Reinhardt?",
  ui_story_70000701_13_dialog_content = "Kenapa dia jadi seperti itu?",
  ui_story_70000701_14_dialog_content = "Apa ini hasil perbuatan Forsakin juga? Tapi, aku tidak menemukan jejak Seed apa pun padanya.",
  ui_story_70000701_15_dialog_content = "Jawaban untuk pertanyaanmu itu adalah: aku tak tahu.",
  ui_story_70000701_16_dialog_content = "Perangnya brutal. Kami semua mengira dia sudah tewas.",
  ui_story_70000701_17_dialog_content = "Apa yang terjadi… saat itu?",
  ui_story_70000701_18_dialog_content = "…",
  ui_story_70000701_19_dialog_content = "Dulu, semua kandidat Grand Marshal disatukan menjadi sebuah tim khusus.",
  ui_story_70000701_20_dialog_content = "Sebelas tahun lalu, kami menerima perintah dari Committee yang mengharuskan kami untuk merebut material ilmiah yang hilang di Undercity 80, sebuah kota yang sudah lama ditinggalkan penduduknya.",
  ui_story_70000701_21_dialog_content = "Info intel menyatakan bahwa Undercity 80 berada di bawah kendali Eclipsite, tapi jumlah mereka tak banyak.",
  ui_story_70000701_22_dialog_content = "Jadi, kami memutuskan untuk melakukan hal yang sama denganmu, menempuh perjalanan singkat.",
  ui_story_70000701_22X_dialog_content = "Kami berencana memasuki Undercity dan memperoleh target selama siang hari yang singkat.",
  ui_story_70000701_23_dialog_content = "Tapi… info intel kami ternyata meleset…",
  ui_story_70000701_24_dialog_content = "Apa-apaan ini! Jumlah mereka banyak sekali!",
  ui_story_70000701_25_dialog_content = "Meminta bantuan! Meminta⁠—",
  ui_story_70000701_26_dialog_content = "Eclipsite di Undercity itu banyak sekali seperti semut mengerubungi gula. Berapa pun banyaknya yang sudah kami singkirkan, mereka selalu berdatangan lagi.",
  ui_story_70000701_27_dialog_content = "Untuk mencapai gudang target saja, kami harus kehilangan seperlima pasukan.",
  ui_story_70000701_28_dialog_content = "Jadi, benteng dan peralatan rusak yang kita lihat di gudang tadi…",
  ui_story_70000701_29_dialog_content = "Peninggalan para prajurit kami yang pemberani.",
  ui_story_70000701_30_dialog_content = "…",
  ui_story_70000701_31_dialog_content = "Lalu, saat kami berhasil mengambil item target dan bersiap untuk evakuasi…",
  ui_story_70000701_32_dialog_content = "Hari sudah malam.",
  ui_story_70000701_33_dialog_content = "Banyak Eclipsite kuat menyerbu ke dalam Undercity 80 seakan-akan ada sesuatu yang menarik mereka…",
  ui_story_70000701_34_dialog_content = "Sama seperti yang terjadi sekarang.",
  ui_story_70000701_35_dialog_content = "Groar!",
  ui_story_70000701_36_dialog_content = "Vice, PlayerName, bersiaplah untuk bertarung!",
  ui_story_70000702_1_dialog_content = "Ahh…",
  ui_story_70000702_2_dialog_content = "Pertempuran selesai!",
  ui_story_70000702_3_dialog_content = "Sudah tak ada musuh di area sekitar… untuk sementara ini.",
  ui_story_70000702_4_dialog_content = "Vice!",
  ui_story_70000702_5_dialog_content = "Aduh… Tubuhku terasa… sangat berat…",
  ui_story_70000702_6_dialog_content = "Ini sudah tengah malam, konsentrasi Darkflow mencapai titik tertinggi.",
  ui_story_70000702_7_dialog_content = "Kalian berdua hebat. Terakhir kali kami mengalami hal seperti ini, banyak yang pingsan.",
  ui_story_70000702_8_dialog_content = "Padahal kami masih harus melawan ratusan atau bahkan ribuan Eclipsite lagi…",
  ui_story_70000702_9_dialog_content = "<color=#e8d9bb>Saat Dark Zone War</color>",
  ui_story_70000702_10_dialog_content = "Awas, arah jam 3 darimu!",
  ui_story_70000702_11_dialog_content = "*Meraung*",
  ui_story_70000702_12_dialog_content = "<color=#e8d9bb>Dadada…</color>",
  ui_story_70000702_13_dialog_content = "Target tumbang!",
  ui_story_70000702_14_dialog_content = "High-level Eclipsite di arah jam 10 darimu!",
  ui_story_70000702_15_dialog_content = "1, 2, 3… Mereka banyak sekali!",
  ui_story_70000702_16_dialog_content = "Kita butuh bantuan tembakan segera!",
  ui_story_70000702_17_dialog_content = "Tak akan kubiarkan kalian lolos dari sini!",
  ui_story_70000702_18_dialog_content = "Graaoooooohhh!!",
  ui_story_70000702_19_dialog_content = "Info intelnya tak menyebutkan bahwa jumlah Eclipsite-nya sebanyak ini!",
  ui_story_70000702_20_dialog_content = "Rupanya info intel dari Committee sekalipun juga bisa salah, ya?",
  ui_story_70000702_21_dialog_content = "Ini memang bukan hal yang kita inginkan, tapi yang sudah terjadi ya sudahlah. Sekarang kita hanya bisa berusaha keluar dari sini dan membawa datanya!",
  ui_story_70000702_22_dialog_content = "Kalian pasti tahu apa yang terjadi selanjutnya, 'kan?",
  ui_story_70000702_23_dialog_content = "Darkflow di Undercity memutus komunikasi kami, jadi aku ditugaskan menerobos untuk mendapatkan bantuan.",
  ui_story_70000702_24_dialog_content = "Saat aku kembali ke seberang Safe Line… Undercity itu sudah terbenam dan runtuh.",
  ui_story_70000702_25_dialog_content = "Dalam situasi seperti itu… masuk ke Undercity yang dikepung Eclipsite, bertempur sambil berusaha menyelamatkan pasukan…",
  ui_story_70000702_26_dialog_content = "Kemungkinan berhasilnya kecil, sedangkan potensi gagalnya besar…",
  ui_story_70000702_27_dialog_content = "Pada akhirnya, setelah mempertimbangkannya matang-matang, tak mungkin misi penyelamatan seperti itu bisa disetujui…",
  ui_story_70000702_28_option_content = "Bisa-bisanya kau melakukannya?",
  ui_story_70000702_29_dialog_content = "Mereka itu prajurit Illumina… orang-orang bernyawa…",
  ui_story_70000702_30_dialog_content = "Kenapa Illumina meninggalkan mereka seperti itu!?",
  ui_story_70000702_31_dialog_content = "…",
  ui_story_70000702_32_dialog_content = "Pertanyaan itu juga sejak dulu selalu mengusikku. Wajar saja kalau kau tak bisa memahaminya.",
  ui_story_70000702_33_dialog_content = "Tim kami yang diutus ke Undercity adalah tim elite dengan persenjataan terbaik di seluruh Illumina.",
  ui_story_70000702_34_dialog_content = "Kalau kami saja tak mampu menang di Undercity 80, apa mungkin pasukan biasa yang menjaga Safe Line bisa menang?",
  ui_story_70000702_35_dialog_content = "Pasukan yang terkurung di bawah tanah itu saudara-saudariku. Aku tak mau kehilangan mereka.",
  ui_story_70000702_36_dialog_content = "Tapi, bukankah para prajurit biasa Illumina juga saudara-saudariku?",
  ui_story_70000702_37_dialog_content = "Kalau harus mengorbankan nyawa sepuluh orang demi menyelamatkan satu orang… apa kau sendiri mau bertaruh seperti itu?",
  ui_story_70000702_38_dialog_content = "Aku…",
  ui_story_70000702_39_dialog_content = "Aku yakin kau pasti bisa paham… Kita semua punya keluarga, teman-teman, dan orang-orang yang penting bagi kita.",
  ui_story_70000702_40_dialog_content = "Darkflow memang hanya membuatku lemas, tapi bisa jadi mematikan bagi orang biasa.",
  ui_story_70000702_41_dialog_content = "Selain itu, Eclipsite yang harus kami hadapi juga tak ada habisnya…",
  ui_story_70000702_42_dialog_content = "Kalau kami saja tak bisa keluar dari situasi berbahaya itu, apa mungkin mereka bisa?",
  ui_story_70000702_43_option_content = "Oh, begitu…",
  ui_story_70000702_44_dialog_content = "Seandainya saja kau bisa paham.",
  ui_story_70000702_45_option_content = "Aku tetap tak setuju.",
  ui_story_70000702_46_dialog_content = "Apa pun yang terjadi, aku tak akan menyerah demi teman-temanku.",
  ui_story_70000702_47_dialog_content = "Tak akan pernah.",
  ui_story_70000702_48_dialog_content = "Aku tak perlu persetujuan darimu. Aku hanya ingin kau bisa paham…",
  ui_story_70000702_49_dialog_content = "Sebagai Grand Marshal di Illumina, keputusanku haruslah berpihak pada kepentingan terbaik bagi semua orang di Illumina.",
  ui_story_70000702_50_dialog_content = "…",
  ui_story_70000702_51_dialog_content = "(Apa aku… membuat percakapan ini jadi terasa tak mengenakkan…?)",
  ui_story_70000702_52_dialog_content = "Yah… Rute ini sebenarnya cukup lancar…",
  ui_story_70000702_53_dialog_content = "Memang.",
  ui_story_70000702_54_dialog_content = "Rute ini dibangun dengan pengorbanan dan darah yang tiada habisnya.",
  ui_story_70000702_55_dialog_content = "Dan hanya pengorbanan merekalah yang membuatku bisa selamat.",
  ui_story_70000702_56_dialog_content = "<color=#e8d9bb>Ding…</color>",
  ui_story_70000702_57_dialog_content = "PlayerName, kaudengar itu tidak?",
  ui_story_70000702_58_dialog_content = "Suara lonceng itu lagi!",
  ui_story_70000702_59_dialog_content = "Aku dengar! Suaranya dekat dari sini!",
  ui_story_70000702_60_dialog_content = "High-Level Eclipsite yang langsung kabur begitu mendengar suara lonceng itu…",
  ui_story_70000702_61_dialog_content = "Mungkinkah dia masih di sekitar sini?",
  ui_story_70000702_62_dialog_content = "Sial… Seandainya saja Darkflow di sini tak sekuat ini, aku pasti bisa menggunakan kemampuan psikisku…",
  ui_story_70000702_63_dialog_content = "Tak apa. Aku yakin dia ada di sekitar sini.",
  ui_story_70000702_64_dialog_content = "Kenapa kau begitu yakin, Grand Marshal Reinhardt?",
  ui_story_70000702_65_dialog_content = "Sebelum aku berusaha kabur dari sini, aku menjanjikan sesuatu kepada mereka.",
  ui_story_70000702_66_dialog_content = "Begitu aku kembali bersama bala bantuan, aku akan memberi tanda kepada kalian untuk melakukan evakuasi.",
  ui_story_70000702_67_dialog_content = "Seperti biasa, tanda untuk evakuasi adalah suara lonceng.",
  ui_story_70000702_68_dialog_content = "Baiklah, aku paham.",
  ui_story_70000702_69_dialog_content = "Jangan khawatir. Kita pasti bisa bertahan.",
  ui_story_70000702_70_dialog_content = "Kalaupun aku berubah jadi Eclipsite, aku akan tetap menunggu tanda darimu!",
  ui_story_70000702_71_dialog_content = "Baiklah…",
  ui_story_70000702_72_dialog_content = "Begitu suara loncengnya terdengar, kita langsung lari keluar!",
  ui_story_70000702_73_dialog_content = "Sungguh ironis, pada akhirnya leluconnya justru jadi kenyataan…",
  ui_story_70000702_74_dialog_content = "Selalu saja mengacaukan segalanya…",
  ui_story_70000702_75_dialog_content = "Jadi… Dia masih ingat janjimu itu?",
  ui_story_70000702_76_dialog_content = "Atau mungkin \"dia\" sudah sepenuhnya kehilangan akal sehat, dan bertindak hanya berdasarkan insting.",
  ui_story_70000702_77_dialog_content = "…",
  ui_story_70000702_78_dialog_content = "…",
  ui_story_70000702_79_dialog_content = "Bersiaplah untuk bertarung. Mungkin saja \"dia\" sudah menunggu kita.",
  ui_story_70000702_80_dialog_content = "Tolong beri aku satu kesempatan terakhir...",
  ui_story_70000702_81_dialog_content = "Aku tak mau menyia-nyiakan kesempatan lagi untuk menyelamatkannya… Tidak setelah yang terakhir dulu itu.",
  ui_story_70000801_1_dialog_content = "<color=#e8d9bb>Ding…</color>",
  ui_story_70000801_2_dialog_content = "Akhirnya kita berhasil keluar!",
  ui_story_70000801_3_dialog_content = "Tapi… Darkflow di sini belum berkurang…",
  ui_story_70000801_4_dialog_content = "Jangan terlalu memaksakan diri, PlayerName.",
  ui_story_70000801_5_dialog_content = "Biar kupapah kau.",
  ui_story_70000801_6_dialog_content = "<color=#e8d9bb>Ding…</color>",
  ui_story_70000801_7_dialog_content = "Suara loncengnya… dekat sini…",
  ui_story_70000801_8_dialog_content = "Di sana!",
  ui_story_70000801_9_dialog_content = "Ahh…",
  ui_story_70000801_10_dialog_content = "Dia mencari sumber suara lonceng?",
  ui_story_70000801_11_dialog_content = "Apa semua Eclipsite itu ada di sekitarnya?",
  ui_story_70000801_12_dialog_content = "Apa kita sungguh mau mencoba mendekatinya dengan cara ini?",
  ui_story_70000801_13_dialog_content = "Ini permintaan pribadi. Tolong, beri kami waktu sebentar.",
  ui_story_70000801_14_dialog_content = "Ini upaya terakhirku untuk menyelamatkannya.",
  ui_story_70000801_15_dialog_content = "Kalau sudah lima menit, kita akan langsung melakukan evakuasi.",
  ui_story_70000801_16_dialog_content = "Biar kubantu!",
  ui_story_70000801_17_dialog_content = "Bagaimana denganmu, PlayerName?",
  ui_story_70000801_18_dialog_content = "Aku ikut.",
  ui_story_70000801_19_dialog_content = "Kali ini, kita akan menyelamatkannya!",
  ui_story_70000801_20_dialog_content = "Baiklah, buka mata kalian dan perhatikan baik-baik.",
  ui_story_70000801_21_dialog_content = "Saksikanlah kuatnya tekad Illumina.",
  ui_story_70000801_22_dialog_content = "Sama seperti waktu itu. Kita berpencar.",
  ui_story_70000801_23_dialog_content = "Vice, kita ambil jalan memutar ke seberang kawanan Eclipsite itu.",
  ui_story_70000801_24_dialog_content = "Tentu.",
  ui_story_70000801_25_dialog_content = "Sepertinya posisi kita sudah bagus sekarang.",
  ui_story_70000801_26_dialog_content = "Bagus. Reinhardt juga sudah siap.",
  ui_story_70000801_27_dialog_content = "Hmm…",
  ui_story_70000801_28_dialog_content = "Hoi, Eclipsite tolol! Sini, tangkap aku!",
  ui_story_70000801_29_dialog_content = "Groar…!",
  ui_story_70000801_30_dialog_content = "Groar!",
  ui_story_70000801_31_dialog_content = "Hah?",
  ui_story_70000801_32_dialog_content = "Banyak sekali!?",
  ui_story_70000801_33_dialog_content = "Bertahanlah, PlayerName!",
  ui_story_70000802_1_dialog_content = "Lupa, ya?",
  ui_story_70000802_2_dialog_content = "Impian Illumina?",
  ui_story_70000802_3_dialog_content = "Tekad Illumina?",
  ui_story_70000802_4_dialog_content = "Kejayaan Illumina?",
  ui_story_70000802_5_dialog_content = "Ingatan tentang Illumina…",
  ui_story_70000802_6_dialog_content = "Apa kau sudah lupa semuanya!?",
  ui_story_70000802_7_dialog_content = "*Meraung*",
  ui_story_70000802_8_dialog_content = "Jawablah aku…",
  ui_story_70000802_9_dialog_content = "Kenapa kau meninggalkan cahaya dan mengikuti kegelapan?",
  ui_story_70000802_10_dialog_content = "Agar bisa bertahan hidup?",
  ui_story_70000802_11_dialog_content = "Atau, jangan-jangan ada orang lain yang menyuruhmu melakukannya?",
  ui_story_70000802_12_dialog_content = "Beri tahu aku…",
  ui_story_70000802_13_dialog_content = "<size=45>Jawabanmu!</size>",
  ui_story_70000802_14_dialog_content = "*Meraung*",
  ui_story_70000802_15_dialog_content = "<color=#e8d9bb>Ding…</color>",
  ui_story_70000802_16_dialog_content = "…!",
  ui_story_70000802_17_dialog_content = "Suara lonceng itu lagi!",
  ui_story_70000802_18_dialog_content = "Sudah dekat… sangat dekat! Di sana!",
  ui_story_70000802_19_dialog_content = "<color=#e8d9bb>Ding…</color>",
  ui_story_70000802_20_dialog_content = "I-itu karena…",
  ui_story_70000802_21_dialog_content = "Forsakin!?",
  ui_story_70000802_22_dialog_content = "…",
  ui_story_70000802_23_dialog_content = "Lama tak jumpa. Kau jadi cerewet.",
  ui_story_70000802_24_dialog_content = "Reinhardt.",
  ui_story_70000802_25_dialog_content = "Denier… Bukan. Forsakin.",
  ui_story_70000802_26_dialog_content = "Apa kau juga ada hubungannya dengan apa yang terjadi pada Helios?",
  ui_story_70000802_27_dialog_content = "Aku juga tak tahu apa-apa tentang ini, sama sepertimu.",
  ui_story_70000802_28_dialog_content = "Tapi, memang, dia subjek uji yang bagus.",
  ui_story_70000802_29_dialog_content = "Lalu, bagaimana dia bisa berubah jadi seperti ini…",
  ui_story_70000802_30_dialog_content = "Masih belum paham juga, ya?",
  ui_story_70000802_31_dialog_content = "Dia tak melupakan apa pun.",
  ui_story_70000802_32_dialog_content = "Justru sebaliknya… Dia masih sangat kuat mengingatnya.",
  ui_story_70000802_33_dialog_content = "…?!",
  ui_story_70000802_34_dialog_content = "Si putra yang terbuang. Satu-satunya hal yang sudah dilupakannya adalah kebenciannya pada Illumina.",
  ui_story_70000802_35_dialog_content = "Sudah saatnya mengingatnya.",
  ui_story_70000802_36_dialog_content = "<size=45>Graah! Groar!</size>",
  ui_story_70000802_37_dialog_content = "Argh…!",
  ui_story_70000802_38_dialog_content = "Ini… ingatan!?",
  ui_story_70000802_39_dialog_content = "Sudah empat jam sejak Reinhardt menerobos masuk…",
  ui_story_70000802_40_dialog_content = "Belum ada suara lonceng…",
  ui_story_70000802_41_dialog_content = "Aku masih punya sisa kekuatan. Akan kutunjukkan kekuatanku kepada kawanan Eclipsite itu, bahkan walau harus dengan tangan telanjang.",
  ui_story_70000802_42_dialog_content = "Bagaimana denganmu? Berapa banyak sisa amunisi dan persediaan bekalmu?",
  ui_story_70000802_43_dialog_content = "10 peluru dan… dua sawdust bun.",
  ui_story_70000802_44_dialog_content = "Kalau saja aku tahu ini akan terjadi, aku pasti akan memilih tetap di Gannon saja dan berurusan dengan peraturan lab yang ribet itu.",
  ui_story_70000802_45_dialog_content = "Aku lebih mahir membedah Eclipsite dengan pisau bedah daripada harus pakai senapan dan peluru.",
  ui_story_70000802_46_dialog_content = "Hahaha! Kau ini sungguh peneliti yang sedang naik daun.",
  ui_story_70000802_47_dialog_content = "Aku berani bertaruh, kau pasti masih bisa mengikat simpul di badan Eclipsite dengan jahitan.",
  ui_story_70000802_48_dialog_content = "Ha. Terima kasih atas dukunganmu.",
  ui_story_70000802_49_dialog_content = "Tapi, kira-kira berapa lama kita bisa bertahan?",
  ui_story_70000802_50_dialog_content = "Atau… Mungkinkah kita ditelantarkan?",
  ui_story_70000802_51_dialog_content = "…",
  ui_story_70000802_52_dialog_content = "Itu tak penting. Kita tak boleh menyerah.",
  ui_story_70000802_53_dialog_content = "Reinhardt… Dia akan kembali membawa bala bantuan dari Illumina untuk menyelamatkan kita.",
  ui_story_70000802_54_dialog_content = "Sementara itu, kita harus bertahan.",
  ui_story_70000802_55_dialog_content = "Lihat, jalan keluarnya ada di depan sana!",
  ui_story_70000802_56_dialog_content = "Ada banyak Eclipsite berkeliaran di sekitarnya… Selain itu…",
  ui_story_70000802_57_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_70000802_58_dialog_content = "Pertempuran terakhir tadi luar biasa sengit. Jalan keluar itu bisa saja runtuh sewaktu-waktu.",
  ui_story_70000802_59_dialog_content = "Sekarang sudah fajar, saat kekuatan Eclipsite ada di titik terlemah.",
  ui_story_70000802_60_dialog_content = "Kalau tak memanfaatkan peluang ini untuk keluar, kita akan mati di sini.",
  ui_story_70000802_61_dialog_content = "Ikuti aku. Kita coba menerobos saat kawanan Eclipsite itu pergi.",
  ui_story_70000802_62_dialog_content = "Arah jam 11!",
  ui_story_70000802_63_dialog_content = "Aku tahu!",
  ui_story_70000802_64_dialog_content = "Sial! Jumlah mereka tak ada habisnya!",
  ui_story_70000802_65_dialog_content = "Aku masih bisa bertahan! Denier, pergilah ke arah jalan keluar!",
  ui_story_70000802_66_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_70000802_67_dialog_content = "Tanahnya runtuh! Awas!",
  ui_story_70000802_68_dialog_content = "Agh!",
  ui_story_70000802_69_dialog_content = "Helios!",
  ui_story_70000802_70_dialog_content = "Aku harus… bertahan hidup.",
  ui_story_70000802_71_dialog_content = "Aku harus menunggu… bala bantuan.",
  ui_story_70000802_72_dialog_content = "Sudah berapa hari…?",
  ui_story_70000802_73_dialog_content = "Tubuhku… ada hal buruk yang terjadi padaku…",
  ui_story_70000802_74_dialog_content = "Lonceng… Kumohon, biarkan aku mendengar suara lonceng itu…",
  ui_story_70000802_75_dialog_content = "Sehari… dua hari…",
  ui_story_70000802_76_dialog_content = "Setahun… dua tahun…",
  ui_story_70000802_77_dialog_content = "Mana bala bantuannya?",
  ui_story_70000802_78_dialog_content = "Kenapa kau menelantarkanku!?",
  ui_story_70000802_79_dialog_content = "Groar!",
  ui_story_70000802_80_dialog_content = "Sepertinya sekarang kau mulai ingat.",
  ui_story_70000802_81_dialog_content = "Tapi, itu belum cukup.",
  ui_story_70000802_82_dialog_content = "Sama seperti Seed. Amarah adalah gizi terbaik…",
  ui_story_70000802_83_dialog_content = "Biar kubantu kau.",
  ui_story_70000802_84_dialog_content = "Apa yang kaulakukan, Forsakin!?",
  ui_story_70000802_85_dialog_content = "…",
  ui_story_70000802_86_dialog_content = "Reinhardt…",
  ui_story_70000802_87_dialog_content = "Kenapa… kau tak kembali bersama bala bantuan?",
  ui_story_70000802_88_dialog_content = "Karena…",
  ui_story_70000802_89_dialog_content = "Dalam situasi tanpa harapan, pilihan yang masuk akal adalah mengorbankanmu.",
  ui_story_70000802_90_dialog_content = "Rupanya, kau benar-benar…",
  ui_story_70000802_91_dialog_content = "…belum berubah.",
  ui_story_70000802_92_dialog_content = "Kau maupun Illumina.",
  ui_story_70000802_93_dialog_content = "Groar!",
  ui_story_70000802_94_dialog_content = "Awas! Dia menuju ke sini!",
  ui_story_70000802_95_dialog_content = "Murkalah! Dan… tumbuhlah.",
  ui_story_70000802_96_dialog_content = "Hancurkan segalanya… di Dark Zone ini!",
  ui_story_70000802_97_dialog_content = "Groar!",
  ui_story_70000802_98_dialog_content = "Sudah saatnya ini diakhiri.",
  ui_story_70000802_99_dialog_content = "Vice, bersiaplah untuk bertarung!",
  ui_story_70000802_100_dialog_content = "Ya!",
  ui_story_70000902_1_dialog_content = "Graah! Groar!",
  ui_story_70000902_2_dialog_content = "Masih saja terkekang walau dalam kondisi seperti ini?",
  ui_story_70000902_3_dialog_content = "Sepertinya kau tetap saja <color=#FFB400>subjek cacat</color>.",
  ui_story_70000902_4_dialog_content = "Tapi, bisa bergerak saja sudah merupakan terobosan dalam eksperimen ini.",
  ui_story_70000902_5_dialog_content = "Setidaknya, itu cukup bermakna.",
  ui_story_70000902_6_dialog_content = "Sayangnya, waktuku tak banyak.",
  ui_story_70000902_7_dialog_content = "Argh…!",
  ui_story_70000902_8_dialog_content = "Darkflow… terpusat di area ini!",
  ui_story_70000902_9_dialog_content = "Darkflow-nya… terlalu kuat! Aku tak bisa…",
  ui_story_70000902_10_dialog_content = "*Uhuk* Setelah bertahun-tahun, ternyata peneliti ringkih sepertimu bisa juga jadi petarung.",
  ui_story_70000902_11_dialog_content = "Diamlah.",
  ui_story_70000902_12_dialog_content = "Orang lemah harus tetap di atas tanah.",
  ui_story_70000902_13_dialog_content = "Nah, kau… Terimalah Darkflow ini dan tunjukkan kehebatanmu!",
  ui_story_70000902_14_dialog_content = "Groar!",
  ui_story_70000902_15_dialog_content = "Eclipsite itu… hilang!",
  ui_story_70000902_16_dialog_content = "Graah! Groar!",
  ui_story_70000902_17_dialog_content = "Mereka… menjerit kesakitan!",
  ui_story_70000902_18_dialog_content = "Forsakin mengambil energi hidup mereka… mengisap Darkflow mereka!",
  ui_story_70000902_19_dialog_content = "Kalau Darkflow sebesar itu diubah jadi serangan…",
  ui_story_70000902_20_dialog_content = "Satu ledakan saja sudah cukup untuk meratakan Undercity ini!",
  ui_story_70000902_21_dialog_content = "Reinhardt, awas!",
  ui_story_70000902_22_dialog_content = "…!",
  ui_story_70000902_23_dialog_content = "PlayerName, berlindunglah!",
  ui_story_70000902_24_dialog_content = "Terlalu lamban.",
  ui_story_70000902_25_dialog_content = "(Itu kekuatan paling luar biasa yang pernah kulihat.)",
  ui_story_70000902_26_dialog_content = "(Darkflow luar biasa besar dan kegelapan Eternal Night menyelubungi seperti laut, memorakporandakan negeri dan segala yang ada di atasnya.)",
  ui_story_70000902_27_dialog_content = "(Aku dan Vice, tertahan di atas tanah oleh suatu tekanan besar, hanya bisa berbaring tak berdaya di hadapan kekuatan mengerikan itu.)",
  ui_story_70000902_28_dialog_content = "(Aku hanya bisa mendongak dan melihat Darkflow menelanku.)",
  ui_story_70000902_29_dialog_content = "Lalu, dalam kegelapan tanpa ujung itu…",
  ui_story_70000902_30_dialog_content = "Aku melihat <color=#FFB400>cahaya</color>.",
  ui_story_70000902_31_dialog_content = "Tidak, saya tidak akan membiarkan Anda mendapatkan apa yang Anda inginkan!",
  ui_story_70000902_32_dialog_content = "Reinhardt!?",
  ui_story_70000902_33_dialog_content = "(Di tengah kegelapan tiada akhir itu, cahaya itu hanyalah setitik sinar kecil yang bisa saja padam sewaktu-waktu…)",
  ui_story_70000902_34_dialog_content = "(Tapi, ia tetap bertahan dan melawan kegelapan itu, dan cahayanya makin menyebar.)",
  ui_story_70000902_35_dialog_content = "(Seperti mentari terbit di cakrawala, yang mengisyaratkan datangnya hari baru.)",
  ui_story_70000902_36_dialog_content = "Itu hanya… Darkflow kecil.",
  ui_story_70000902_37_dialog_content = "Dan saya membawa Kemegahan Illumina di pundak saya!",
  ui_story_70000902_38_dialog_content = "Aku akan tetap menopang langit walau runtuh menjatuhi Illumina!",
  ui_story_70000902_39_dialog_content = "(Perlahan, kegelapan itu memudar…)",
  ui_story_70000902_40_dialog_content = "(Ada cahaya, bersinar menembus awan.)",
  ui_story_70000902_41_dialog_content = "Ugh!",
  ui_story_70000902_42_dialog_content = "…!",
  ui_story_70000902_43_dialog_content = "Reinhardt!",
  ui_story_70000902_44_dialog_content = "Melupakan pertahanan sepenuhnya untuk menyerang habis-habisan… begitu, ya?",
  ui_story_70000902_45_dialog_content = "Walau begitu, sebagian besar serangan bisa ditahan dengan mudah…",
  ui_story_70000902_46_dialog_content = "Ha… Dasar tolol…",
  ui_story_70000902_47_dialog_content = "Tolol dan sinting.",
  ui_story_70000902_48_dialog_content = "Tingkat kekuatanmu masih dalam batas wajar.",
  ui_story_70000902_49_dialog_content = "Aurorian biasa pasti sudah gila kalau terkena Darkflow sebesar ini.",
  ui_story_70000902_50_dialog_content = "Kau memang hebat.",
  ui_story_70000902_51_dialog_content = "Sama hebatnya dengan \"monster\" terkuat yang berhasil keluar hidup-hidup dari Mire.",
  ui_story_70000902_52_dialog_content = "Rupanya orang-orang itu \"mengajarimu\" dengan baik.",
  ui_story_70000902_53_dialog_content = "Begitu pula dengan dirimu.",
  ui_story_70000902_54_dialog_content = "Kau punya teknologi secanggih ini, tapi kau hanya membayangkan dirimu jadi pahlawan dalam permainan anak-anak…",
  ui_story_70000902_55_dialog_content = "Dan kau tampak benar-benar… bersenang-senang.",
  ui_story_70000902_56_dialog_content = "Karena memang itulah impian kita… iya, 'kan?",
  ui_story_70000902_57_dialog_content = "Menjadi Grand Marshal di Illumina dan memimpin warga Illumina menuju dunia yang lebih baik.",
  ui_story_70000902_58_dialog_content = "Demi Illumina dan warganya…",
  ui_story_70000902_59_dialog_content = "Sungguh naif. Sebenarnya, apa yang mereka lakukan untukmu? Tak ada, selain menyia-nyiakanmu dan terus-menerus memintamu melindungi mereka tanpa henti.",
  ui_story_70000902_60_dialog_content = "Di mata mereka, kau hanyalah lambang dalam wujud manusia. Bisa diganti dan dibuang dengan mudah.",
  ui_story_70000902_61_dialog_content = "Sesungguhnya, kau ini tak ada bedanya dengan hewan-hewan hidup yang jadi subjek uji itu.",
  ui_story_70000902_62_dialog_content = "Peneliti hanya tertarik dengan data yang diperoleh dari subjek uji.",
  ui_story_70000902_63_dialog_content = "Dan orang-orang itu hanya peduli dengan… citra yang tampak kuat. Perkara citra itu dilekatkan pada siapa, itu tak penting bagi mereka.",
  ui_story_70000902_64_dialog_content = "Hehe…",
  ui_story_70000902_65_dialog_content = "Hahahah!",
  ui_story_70000902_66_dialog_content = "Forsakin… Bukan. Denier…",
  ui_story_70000902_67_dialog_content = "Kau sendiri juga jadi cerewet.",
  ui_story_70000902_68_dialog_content = "Aku masih ingat bagaimana kau selalu mengurung diri di lab dan menjalankan eksperimenmu.",
  ui_story_70000902_69_dialog_content = "Apa pun yang kukatakan kepadamu, kau hanya ingin membuktikan kepada dunia bahwa kau adalah yang terhebat.",
  ui_story_70000902_70_dialog_content = "…",
  ui_story_70000902_71_dialog_content = "Dulu, kau tak pernah peduli apa pandangan orang lain tentangmu.",
  ui_story_70000902_72_dialog_content = "Sekarang, aku ada di posisimu. Aku Grand Marshal di Illumina. Aku akan melindungi Illumina dan warganya. Itulah satu-satunya yang penting.",
  ui_story_70000902_73_dialog_content = "Soal pandangan mereka tentangku? Aku sama sekali tak peduli.",
  ui_story_70000902_74_dialog_content = "Aku jadi diriku yang sekarang ini justru karena belajar darimu.",
  ui_story_70000902_75_dialog_content = "…",
  ui_story_70000902_76_dialog_content = "Begini saja. Akan kuberi label pada data tesmu: \"sinting\".",
  ui_story_70000902_77_dialog_content = "Karena aku sudah dapat material yang kubutuhkan, sekarang saatnya melanjutkan eksperimenku.",
  ui_story_70000902_78_dialog_content = "For… sakin…",
  ui_story_70000902_79_dialog_content = "Hama benar-benar sulit untuk dibunuh.",
  ui_story_70000902_80_dialog_content = "Tidak seperti artikel percobaan yang gagal ini...",
  ui_story_70000902_81_dialog_content = "…",
  ui_story_70000902_82_dialog_content = "Itu saja…?",
  ui_story_70000902_83_dialog_content = "Yah… Kurasa yang ini cukup layak dijadikan subjek studi.",
  ui_story_70000902_84_dialog_content = "Bukan Aurorian, bukan pula Eclipsite.",
  ui_story_70000902_85_dialog_content = "Hanya sesuatu yang… bernilai sebagai pion.",
  ui_story_70000902_86_dialog_content = "Apa yang kaulakukan!? Turunkan dia!",
  ui_story_70000902_87_dialog_content = "Kaukira kau bisa menghentikanku? Memangnya kaukira kau ini siapa?",
  ui_story_70000902_88_dialog_content = "\"Sudah saatnya.\"",
  ui_story_70000902_89_dialog_content = "Getaran dan debu… datang dari cakrawala…?",
  ui_story_70000902_90_dialog_content = "PlayerName… Apa itu?",
  ui_story_70000902_91_dialog_content = "Aku tak tahu… Coba kulihat…",
  ui_story_70000902_92_option_content = "Force Boost!",
  ui_story_70000902_93_dialog_content = "…!",
  ui_story_70000902_94_dialog_content = "(Apa itu… Eclipsite!?)",
  ui_story_70000902_95_dialog_content = "(Sepasukan besar… Eclipsite!)",
  ui_story_70000902_96_dialog_content = "(Eclipsian) Tolong... Forsakin!",
  ui_story_70000902_97_dialog_content = "(Mereka kemari!?)",
  ui_story_70000902_98_dialog_content = "(Walaupun ada Reinhardt bersama kita, jumlah mereka tetap saja terlalu banyak…)",
  ui_story_70000902_99_dialog_content = "(Lagi pula… dia cedera berat akibat berusaha mati-matian menyerang tadi…)",
  ui_story_70000902_100_dialog_content = "(Dia bisa bertahan semata karena tekadnya…)",
  ui_story_70000902_101_dialog_content = "(Kita harus mundur sekarang juga!)",
  ui_story_70000902_102_dialog_content = "Reinhardt! Situasi sama sekali tak bagus!",
  ui_story_70000902_103_dialog_content = "Apa?",
  ui_story_70000902_104_dialog_content = "Aku bisa merasakan banyak sekali Eclipsite bergerak menuju arah kita! Tak lama lagi mereka pasti sudah sampai sini!",
  ui_story_70000902_105_dialog_content = "Ada juga sesuatu yang sangat kuat di antara mereka!",
  ui_story_70000902_106_dialog_content = "Kita harus pergi, sekarang juga!",
  ui_story_70000902_107_dialog_content = "Tiga menit saja… Hanya itu yang kubutuhkan!",
  ui_story_70000902_108_dialog_content = "Groar!",
  ui_story_70000902_109_dialog_content = "Tak ada waktu lagi, Reinhardt!",
  ui_story_70000902_110_dialog_content = "Kalau menunggu, kita akan terkepung!",
  ui_story_70000902_111_dialog_content = "…",
  ui_story_70000902_112_dialog_content = "\"Peraturan ke-3: Hindari pertempuran dengan cara apa pun di Mire. Ketahuilah kapan harus keluar.\"",
  ui_story_70000902_113_dialog_content = "…",
  ui_story_70000902_114_dialog_content = "Dasar makhluk lemah.",
  ui_story_70000902_115_dialog_content = "Kau tahu betul bahwa dia adalah rekan seperjuangan kami.",
  ui_story_70000902_116_dialog_content = "Jika kamu berani menyakitinya atau orang-orang Illumina... Aku akan membuatmu membayar.",
  ui_story_70000902_117_dialog_content = "Ha.",
  ui_story_70000902_118_dialog_content = "Bagaimana kalau kau berusaha selamat dulu, baru bilang begitu kepadaku?",
  ui_story_70000902_119_dialog_content = "Saat ini, kau tak punya pilihan.",
  ui_story_70000902_120_dialog_content = "…",
  ui_story_70000902_121_dialog_content = "Vice, PlayerName, bersiaplah untuk evakuasi.",
  ui_story_70000902_122_dialog_content = "…",
  ui_story_70000902_123_dialog_content = "Waktumu hampir habis…",
  ui_story_70000902_124_dialog_content = "\"Saudariku\".",
  ui_story_70001001_1_dialog_content = "Vice, papah Reinhardt. Aku akan mengaktifkan Colossus!",
  ui_story_70001001_2_dialog_content = "Baiklah!",
  ui_story_70001001_3_dialog_content = "Apa kita… sudah mengudara?",
  ui_story_70001001_4_dialog_content = "Ya, sekarang kita sudah terbang!",
  ui_story_70001001_5_dialog_content = "Nyaris saja kita gagal lepas landas tepat waktu…",
  ui_story_70001001_6_dialog_content = "RTB… kecepatan penuh…",
  ui_story_70001001_7_dialog_content = "Grand Marshal Reinhardt!?",
  ui_story_70001001_8_dialog_content = "Cederanya terlalu parah… Luar biasa sekali dia bisa bertahan selama itu.",
  ui_story_70001001_9_dialog_content = "PlayerName, kau kemudikan saja Soroz. Aku akan ambil P3K.",
  ui_story_70001001_10_dialog_content = "Baiklah!",
  ui_story_70001001_11_dialog_content = "Bertahanlah… Reinhardt…",
  ui_story_70001001_12_dialog_content = "Eh…",
  ui_story_70001001_13_dialog_content = "Situasinya buruk. Kondisi Grand Marshal kritis.",
  ui_story_70001001_14_dialog_content = "Dia butuh penanganan medis segera!",
  ui_story_70001001_15_dialog_content = "<color=#e8d9bb>\"Kata kunci terdeteksi: Penanganan medis.\"</color>",
  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>\"Memindai data… Pemindaian selesai.\"</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>\"Upgrade untuk Echo Template Repair Module ditemukan.\"</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>\"Install Echo Template untuk upgrade Life Support System menjadi Emergency Medical System.\"</color>",
  ui_story_70001001_19_option_content = "Soroz?",
  ui_story_70001001_20_dialog_content = "Tiba-tiba saja dia aktif!?",
  ui_story_70001001_21_dialog_content = "Unit perbaikan Echo Template… Maksudnya ini? Bisa-bisanya aku lupa!?",
  ui_story_70001001_22_dialog_content = "Karena ini sistem medis, mungkin ini bisa menolong Reinhardt.",
  ui_story_70001001_23_dialog_content = "Coba kita instal dan lihat hasilnya!",
  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>\"Echo Template Repair Module terdeteksi.\"</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>\"Menyambungkan koneksi… Selesai.\"</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>\"Pengaturan prioritas sistem… Selesai.\"</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>\"Upgrade untuk Life Support System ditemukan. Memulai upgrade.\"</color>",
  ui_story_70001001_28_dialog_content = "Modul perbaikannya… berubah!?",
  ui_story_70001001_29_dialog_content = "<color=#e8d9bb>\"Upgrade selesai. Emergency Medical System berfungsi.\"</color>",
  ui_story_70001001_30_dialog_content = "<color=#e8d9bb>\"Muatan Saat Ini: 1, Sisa Slot: 1\"</color>",
  ui_story_70001001_31_dialog_content = "<color=#e8d9bb>\"Silakan tanda tangani dan konfirmasikan.\"</color>",
  ui_story_70001001_32_dialog_content = "Tapi… Bukannya kita mestinya melakukan pemeriksaan menyeluruh lebih dulu?",
  ui_story_70001001_33_dialog_content = "Eh…",
  ui_story_70001001_34_dialog_content = "Kurasa tak ada waktu untuk itu.",
  ui_story_70001001_35_dialog_content = "Kita harus manfaatkan kesempatan ini…",
  ui_story_70001001_36_dialog_content = "Ya!",
  ui_story_70001001_37_dialog_content = "Semoga ini berhasil…",
  ui_story_70001001_38_dialog_content = "Dia akan baik-baik saja.",
  ui_story_70001001_39_dialog_content = "Aku percaya kepadanya, dan aku percaya Soroz.",
  ui_story_70001001_40_dialog_content = "Perintah suara barusan… Soroz pasti tahu kita butuh bantuan, maka dia pun memberikannya…",
  ui_story_70001001_41_dialog_content = "Hmm…",
  ui_story_70001001_42_dialog_content = "Emergency Medical System ini sepertinya butuh waktu untuk menanganinya…",
  ui_story_70001001_43_dialog_content = "Sementara itu, kita pusatkan saja perhatian kita untuk mencari cara untuk memperbaiki Echo Template.",
  ui_story_70001001_44_dialog_content = "Baiklah. Aku juga akan membantu.",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>\"Melanjutkan prosedur perbaikan Echo Template.\"</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>\"Langkah Pertama: Harap instal Colossus Echo Template Standard Database Plugin.\"</color>",
  ui_story_70001001_47_dialog_content = "Hah?",
  ui_story_70001001_48_dialog_content = "Apa katanya…?",
  ui_story_70001001_49_dialog_content = "PlayerName, memangnya kau masih punya modul lain?",
  ui_story_70001001_50_dialog_content = "Uhh… Hanya yang itu…",
  ui_story_70001001_51_dialog_content = "Soroz, Database Plugin itu apa?",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>\"Mencari informasi tentang Colossus Echo Template Standard Database Plugin… Pencarian selesai.\"</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>\"Jawaban: Colossus Echo Template Standard Database Plugin adalah Echo Template untuk Colossus.\"</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>\"Modul yang Saat Ini Disimpan: 0\"</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>\"Catatan: Colossus Echo Template Standard Database Plugin bisa ditemukan di Colossus Maintenance Base.\"</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>\"Mencari Colossus Maintenance Base terdekat… Pencarian selesai.\"</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>\"Lokasi target: Eraveil.\"</color>",
  ui_story_70001001_58_dialog_content = "Eraveil…!?",
  ui_story_70001001_59_dialog_content = "Masih ada markas di Eraveil!?",
  ui_story_70001001_60_dialog_content = "Kok aku tak pernah dengar tentang pangkalan itu…",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>\"Catatan: Jika plugin tidak diinstal, Echo Template Repair Module akan ditangguhkan ke mode siaga.\"</color>",
  ui_story_70001001_62_dialog_content = "Memasuki mode siaga…",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>\"Soroz Echo Template Repair Module memasuki mode siaga.\"</color>",
  ui_story_70001001_64_dialog_content = "Begitu kita sampai di Eraveil, aku akan langsung mencari <color=#FFB400>Colossus Maintenance Base</color> itu.",
  ui_story_70001001_65_dialog_content = "Kalau kita harus menjungkirbalikkan Eraveil sekalipun, akan kucari cara untuk menyelamatkan Soroz…",
  ui_story_70001001_66_dialog_content = "Tapi, prioritas pertama kita adalah mengantar Grand Marshal kembali ke Safe Line.",
  ui_story_70001001_67_dialog_content = "Benar…",
  ui_story_70001001_68_dialog_content = "Bagaimana kondisi Reinhardt?",
  ui_story_70001001_69_dialog_content = "Sistem medis Soroz sedang menanganinya.",
  ui_story_70001001_70_dialog_content = "Hanya saja, aku tak tahu seberapa efektif sistem itu…",
  ui_story_70001001_71_dialog_content = "Semoga semuanya lancar.",
  ui_story_70001001_72_dialog_content = "<color=#e8d9bb>Bip Bip Bip!</color>",
  ui_story_70001001_73_dialog_content = "Permintaan komunikasi dari Illumina…? Tapi, pemanggilnya tak dikenal.",
  ui_story_70001001_74_dialog_content = "Mungkin saja itu bala bantuan kita. Kita dengarkan saja mereka!",
  ui_story_70001001_75_dialog_content = "Memanggil Soroz… Lieutenant Vice, Caelestite PlayerName…",
  ui_story_70001001_76_dialog_content = "Apa kau bisa mendengarku?",
  ui_story_70001001_77_dialog_content = "Aku harus jawab apa…?",
  ui_story_70001001_78_dialog_content = "Baiklah. Ini Soroz. Kami mendengarmu.",
  ui_story_70001001_79_dialog_content = "Ini Petugas Intelijen Esien dari Illumina.",
  ui_story_70001001_80_dialog_content = "Di mana lokasi kalian saat ini?",
  ui_story_70001001_81_dialog_content = "Barat daya Undercity 80. Perkiraan waktu ke garis pertahanan Illumina… 10 menit.",
  ui_story_70001001_82_dialog_content = "Kami ingin melaporkan situasi mendesak!",
  ui_story_70001001_83_dialog_content = "Grand Marshal Reinhardt terluka parah dalam pertempuran. Kami butuh penanganan medis segera.",
  ui_story_70001001_84_dialog_content = "Sudah kuduga.",
  ui_story_70001001_85_dialog_content = "Bukan apa-apa.",
  ui_story_70001001_86_dialog_content = "Akan kuperintahkan tim medis menunggu kalian di garis pertahanan Illumina. Bawa dia ke sana secepat mungkin.",
  ui_story_70001001_87_dialog_content = "Aku tahu!",
  ui_story_70001001_88_dialog_content = "Selesai.",
  ui_story_70001001_89_dialog_content = "Mereka sungguh buru-buru.",
  ui_story_70001001_90_dialog_content = "Grand Marshal!",
  ui_story_70001001_91_dialog_content = "Reinhardt…!",
  ui_story_70001001_92_dialog_content = "Bagaimana kondisimu?",
  ui_story_70001001_93_dialog_content = "Aku baik-baik saja. Rasanya seluruh tubuhku seperti mau meledak… tapi aku tak akan mati hari ini.",
  ui_story_70001001_94_dialog_content = "Kau harus istirahat beberapa hari untuk memulihkan diri.",
  ui_story_70001001_95_dialog_content = "Teknologi kaum Caelestite sungguh luar biasa.",
  ui_story_70001001_96_dialog_content = "Seandainya saja kami punya unit medis seperti ini di Undercity Illumina, sebagian besar warga pasti bisa diselamatkan…",
  ui_story_70001001_97_dialog_content = "Kalau bukan karena Soroz yang mengingatkanku, aku sendiri pun tak tahu tentang fungsi ini.",
  ui_story_70001001_98_dialog_content = "Oh, lalu bagaimana kondisi Soroz sekarang?",
  ui_story_70001001_99_dialog_content = "Kami punya modul yang dibutuhkan, tapi masih ada modul lain yang harus kami dapatkan agar Soroz bisa diperbaiki.",
  ui_story_70001001_100_dialog_content = "Begitukah…",
  ui_story_70001001_101_dialog_content = "Semoga kau bisa segera memperbaikinya.",
  ui_story_70001001_102_dialog_content = "…",
  ui_story_70001001_103_dialog_content = "Reinhardt, ada sesuatu yang tak kupahami.",
  ui_story_70001001_104_dialog_content = "Hm? Bukannya tadi kau sudah mengajukan \"pertanyaan terakhir\"?",
  ui_story_70001001_105_dialog_content = "Bukan. Ini bukan pertanyaan… Hanya sesuatu yang menurutku bertentangan…",
  ui_story_70001001_106_dialog_content = "Kau bukan tipe orang yang akan menelantarkan temanmu.",
  ui_story_70001001_107_dialog_content = "Tapi, waktu itu, kenapa kau memilih untuk menelantarkan mereka?",
  ui_story_70001001_108_dialog_content = "Itu keputusan yang paling masuk akal… untuk saat itu.",
  ui_story_70001001_109_dialog_content = "Aku tak akan membiarkan para prajurit Illumina dikorbankan untuk alasan yang tak pasti.",
  ui_story_70001001_110_dialog_content = "Tapi, waktu itu, kau kan belum menjadi Grand Marshal. Kau hanyalah prajurit biasa.",
  ui_story_70001001_111_dialog_content = "Aku yakin pasti ada alasan lain.",
  ui_story_70001001_112_dialog_content = "Memang aneh…",
  ui_story_70001001_113_dialog_content = "Grand Marshal, kau sendiri datang untuk menyelamatkan kami, dan kau berusaha semampumu untuk membantu kawan-kawan lamamu.",
  ui_story_70001001_114_dialog_content = "Kurasa, waktu itu mestinya kau juga akan kembali untuk menyelamatkan mereka, apa pun yang terjadi…",
  ui_story_70001001_115_dialog_content = "…",
  ui_story_70001001_116_dialog_content = "Caelestite memang merepotkan.",
  ui_story_70001001_117_option_content = "Kuanggap itu pujian",
  ui_story_70001001_118_option_content = "Anggap saja aku punya perhatian lebih pada hal-hal detail",
  ui_story_70001001_119_dialog_content = "Aku tak mau mengingat masa lalu, tapi kalau dipikir-pikir lagi…",
  ui_story_70001001_120_dialog_content = "Waktu itu, saat aku menerobos barisan musuh dan kembali ke Safe Line…",
  ui_story_70001001_121_dialog_content = "Aku ingin melaporkan kabar mendesak!",
  ui_story_70001001_122_dialog_content = "Info intel yang sebelumnya ternyata salah! Bagian dalam Undercity 80 dipenuhi kawanan Eclipsite!",
  ui_story_70001001_123_dialog_content = "Aku menerobos mereka sendirian untuk meminta bantuan untuk menyelamatkan timku yang masih terjebak di sana. Kami kehilangan banyak anggota pasukan!",
  ui_story_70001001_124_dialog_content = "Kami butuh bantuan!",
  ui_story_70001001_125_dialog_content = "Baiklah. Kami akan memeriksanya. Tim medis, tangani luka-lukanya.",
  ui_story_70001001_126_dialog_content = "Silakan, lewat sini…",
  ui_story_70001001_127_dialog_content = "Tidak! Kau tak paham betapa mendesaknya ini!",
  ui_story_70001001_128_dialog_content = "Mereka butuh bantuan SEKARANG JUGA!",
  ui_story_70001001_129_dialog_content = "Kalau tidak… teman-temanku… mereka akan mati di sana!",
  ui_story_70001001_130_dialog_content = "Operasi pencarian dan penyelamatan harus direncanakan dan dirundingkan lebih dulu. Sekarang, ini bukan urusanmu. Kau boleh pergi.",
  ui_story_70001001_131_dialog_content = "Kau bahkan tak mau berusaha menyelamatkan mereka, 'kan?",
  ui_story_70001001_132_dialog_content = "Jangan berasumsi tanpa dasar.",
  ui_story_70001001_133_dialog_content = "Baiklah. Kalau kau tak mau mengirimkan bala bantuan, aku akan kembali ke sana sendirian.",
  ui_story_70001001_134_dialog_content = "Aku tak akan menelantarkan mereka!",
  ui_story_70001001_135_dialog_content = "Kau prajurit Illumina, dan kau harus menaati perintah. Kalau kau berani membantah perintahku lagi, akan kusuruh anak buahku menangkapmu.",
  ui_story_70001001_136_dialog_content = "Teman-temanku masih menungguku kembali ke sana.",
  ui_story_70001001_137_dialog_content = "Medis!",
  ui_story_70001001_138_dialog_content = "Berani-beraninya… kau…",
  ui_story_70001001_139_dialog_content = "Bius dia, tangani luka-lukanya, dan awasi dia baik-baik.",
  ui_story_70001001_140_dialog_content = "Ya.",
  ui_story_70001001_141_dialog_content = "Saat aku akhirnya sadar, sudah beberapa hari berlalu.",
  ui_story_70001001_142_dialog_content = "Aku dipindahkan ke fasilitas medis di Gannon. Orang-orang yang berhasil kembali dari Safe Line memberitahuku…",
  ui_story_70001001_143_dialog_content = "Pada akhirnya, Committee memang tak pernah mengirimkan bala bantuan ke Undercity 80.",
  ui_story_70001001_144_dialog_content = "Akulah satu-satunya orang yang selamat dalam insiden itu.",
  ui_story_70001001_145_dialog_content = "…",
  ui_story_70001001_146_dialog_content = "Setelah aku bisa menenangkan diri, aku merenung lama dan akhirnya bisa memahami alasan mereka.",
  ui_story_70001001_147_dialog_content = "Setiap kehidupan di Illumina sama pentingnya.",
  ui_story_70001001_148_dialog_content = "Kepentingan orang banyak harus didahulukan daripada kepentingan segelintir orang.",
  ui_story_70001001_149_dialog_content = "Itu adalah hal yang harus diterima dan dilakukan Grand Marshal. Itu harga yang harus dibayar.",
  ui_story_70001001_150_dialog_content = "Hingga akhirnya Denier kembali ke Illumina walau dalam keadaan terluka parah.",
  ui_story_70001001_151_dialog_content = "Yang sekarang jadi Forsakin…?",
  ui_story_70001001_152_dialog_content = "Aku senang melihat temanku masih hidup, tapi setelah itu, ada sesuatu yang berubah dalam hubungan kami.",
  ui_story_70001001_153_dialog_content = "Pada akhirnya, kami berpisah.",
  ui_story_70001001_154_dialog_content = "Kau bohong kepadanya. Bukan kau yang memutuskan untuk menelantarkan mereka.",
  ui_story_70001001_155_dialog_content = "Menurutku, lebih baik dia membenciku saja daripada membenci seluruh Illumina.",
  ui_story_70001001_156_dialog_content = "Dia memang sangat cerdas, tapi juga sangat penuh dendam.",
  ui_story_70001001_157_dialog_content = "Kalau kemarahannya hanya tertuju padaku, berarti nyawa warga Illumina tak akan terancam.",
  ui_story_70001001_158_dialog_content = "Toh, \"monster\" sepertiku ini kan tak bisa dibunuh dengan mudah.",
  ui_story_70001001_159_dialog_content = "Sekarang aku paham.",
  ui_story_70001001_160_dialog_content = "Sepertinya aku salah sangka kepadamu.",
  ui_story_70001001_161_dialog_content = "Oh? Kok bisa?",
  ui_story_70001001_162_dialog_content = "Kukira kau ini bajingan berdarah dingin.",
  ui_story_70001001_163_dialog_content = "PlayerName… Itu bukan kata-kata yang pantas diucapkan di hadapan Grand Marshal…",
  ui_story_70001001_164_dialog_content = "Hahaha⁠—Gah! Auh! *uhuk-uhuk*",
  ui_story_70001001_165_dialog_content = "*uhuk-uhuk* A-Aku tak apa-apa.",
  ui_story_70001001_166_dialog_content = "Aku sudah biasa menghadapi prasangka buruk. Berkurang satu ataupun bertambah satu prasangka bukanlah hal penting bagiku.",
  ui_story_70001001_167_dialog_content = "Asalkan aku bisa melindungi warga Illumina… aku bisa menanggungnya.",
  ui_story_70001001_168_dialog_content = "Hmm…",
  ui_story_70001001_169_dialog_content = "Sudah lama kita bercakap-cakap. Sebentar lagi kita akan sampai di Illumina Safe Line.",
  ui_story_70001001_170_dialog_content = "Benar. Keluar dari mulut buaya, masuk mulut harimau… Sekarang aku harus menghadapi \"mereka\".",
  ui_story_70001001_171_dialog_content = "Grand Marshal, kau sudah kembali!",
  ui_story_70001001_172_dialog_content = "Seandainya saja kau belum kembali, Committee berniat mengajukan kami semua ke pengadilan militer…",
  ui_story_70001001_173_dialog_content = "Kami sudah dengar tentang cederamu. Tim medis sudah siaga menunggumu!",
  ui_story_70001001_174_dialog_content = "Tak apa. Aku baik-baik saja.",
  ui_story_70001001_175_dialog_content = "Berkat Caelestite ini dan Colossus miliknya, aku sudah mendapatkan penanganan medis darurat. Untuk sementara ini, kondisiku sudah stabil.",
  ui_story_70001001_176_dialog_content = "Ini semua berkat pengingat dari Soroz yang tepat waktu.",
  ui_story_70001001_177_dialog_content = "Tolong, biarkan kami memeriksamu secara menyeluruh, sekadar untuk memastikan saja!",
  ui_story_70001001_178_dialog_content = "Kami tak mau sampai kehilangan Grand Marshal.",
  ui_story_70001001_179_dialog_content = "Kehilangan \"Grand Marshal\"… Begitu, ya?",
  ui_story_70001001_180_dialog_content = "Nah, inilah yang kumaksud. Prosedur mungkin memang perlu, tapi tetap saja merepotkan.",
  ui_story_70001001_181_dialog_content = "Pemeriksaan fisik, 'kan? Baiklah. Aku akan menuruti kalian.",
  ui_story_70001001_182_dialog_content = "Silakan, lewat sini.",
  ui_story_70001001_183_dialog_content = "Beri aku waktu sebentar. Aku perlu bicara dengan PlayerName.",
  ui_story_70001001_184_dialog_content = "Hah? Oh, baiklah.",
  ui_story_70001001_185_dialog_content = "Kalau mereka menanyaimu tentang apa yang terjadi di Undercity 80, jawab saja sejujurnya.",
  ui_story_70001001_186_dialog_content = "Walau mereka memang konservatif dan keras kepala, Committee tetap bertindak menurut aturan. Mereka tak akan menyalahkanmu.",
  ui_story_70001001_187_dialog_content = "Tapi, bagaimana denganmu…?",
  ui_story_70001001_188_dialog_content = "Tak usah khawatir. Terakhir kali kulihat, aku masih Grand Marshal di Illumina, kok.",
  ui_story_70001001_189_dialog_content = "Baiklah… Jaga dirimu. Semoga kita bertemu lagi.",
  ui_story_70001001_190_dialog_content = "Aku pun berharap begitu.",
  ui_story_70001001_191_dialog_content = "Menatap punggung Reinhardt yang lenyap seiring sosoknya memasuki Undercity…",
  ui_story_70001001_192_dialog_content = "Kekhawatiran besar menyeruak dari dalam benakku.",
  ui_story_70001001_193_dialog_content = "Tapi, aku harus kembali dan memeriksa status Soroz.",
  ui_story_70001001_194_dialog_content = "Lalu kembali ke Eraveil dan mencari cara untuk memperbaikinya."
}
return config
